def create_code_backup(reason="startup"):

    """Crée une copie horodatée du code avant lancement; conserve les 12 dernières."""

    if getattr(sys,"frozen",False):

        return None

    try:

        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")

        target = os.path.join(CODE_BACKUP_DIR, f"backup_{stamp}_{reason}")

        os.makedirs(target, exist_ok=True)

        for name in ("main.py", "legacy_import.py", "ui_components.py"):

            source = os.path.join(BASE_DIR, name)

            if os.path.isfile(source):

                shutil.copy2(source, os.path.join(target, name))

        with open(os.path.join(target, "README.txt"), "w", encoding="utf-8") as f:

            f.write(f"Sauvegarde automatique du code\nCréée le : {datetime.now().isoformat(timespec='seconds')}\nRaison : {reason}\n")

        folders = sorted((p for p in Path(CODE_BACKUP_DIR).glob("backup_*" ) if p.is_dir()), key=lambda p: p.stat().st_mtime, reverse=True)

        for old in folders[12:]:

            shutil.rmtree(old, ignore_errors=True)

        return target

    except OSError:

        return None





def restore_latest_code_backup():

    """Restaure la dernière copie du code; réservé au lancement avec --restore-code."""

    folders = sorted((p for p in Path(CODE_BACKUP_DIR).glob("backup_*" ) if p.is_dir()), key=lambda p: p.stat().st_mtime, reverse=True)

    if not folders:

        return False

    latest = folders[0]

    try:

        for name in ("main.py", "legacy_import.py", "ui_components.py"):

            source = latest / name

            if source.exists():

                shutil.copy2(source, os.path.join(BASE_DIR, name))

        return True

    except OSError:

        return False



