# Poids des nationalités dans un championnat français : majorité locale,
# forte présence des pays du futsal et de l'immigration.
NATIONALITY_WEIGHTS = {
    "Portugaise":9,"Brésilienne":9,"Espagnole":6,"Argentine":4,"Marocaine":5.5,
    "Algérienne":5,"Tunisienne":3.5,"Sénégalaise":4,"Ivoirienne":3,"Camerounaise":2.5,
    "Nigériane":2.5,"Congolaise":2.5,"Malienne":2.5,"Cap-Verdienne":2,
    "Italienne":3,"Allemande":2,"Belge":2.5,"Turque":2,"Serbe":1.8,"Croate":1.8,
    "Polonaise":1.8,"Néerlandaise":1.6,"Anglaise":1.6,"Suédoise":1.2,"Suisse":1.4,
    "Grecque":1.4,"Roumaine":1.6,"Colombienne":2,"Uruguayenne":1.6,"Égyptienne":1.8,
    "Australienne":1,"Sud-coréenne":1.2,"Américaine":1.2,"Japonaise":1,
    "Française":10,
}


def pick_nationality(domestic="Française", domestic_share=0.38):
    """Nationalité d'un joueur : le pays du club pèse ~38 %, le reste est
    international (futsal : Portugal, Brésil, Maghreb, Afrique de l'Ouest…)."""
    if random.random()<domestic_share:
        return domestic if domestic in NAME_BANK else "Française"
    pool=[(k,v) for k,v in NATIONALITY_WEIGHTS.items() if k in NAME_BANK and k!=domestic]
    total=sum(v for _,v in pool)
    pick=random.uniform(0,total); acc=0.0
    for nat,weight in pool:
        acc+=weight
        if pick<=acc: return nat
    return pool[-1][0]


def random_player_name(nationality=None, domestic="Française"):
    """Prénom + nom issus de la MÊME nationalité."""
    nat=nationality or pick_nationality(domestic)
    firsts,lasts=NAME_BANK.get(nat,NAME_BANK["Française"])
    return random.choice(firsts),random.choice(lasts),nat


_NAME_INDEX=None


def _name_index():
    """Index (prénom/nom -> nationalité) construit depuis NAME_BANK."""
    global _NAME_INDEX
    if _NAME_INDEX is None:
        idx={}
        for nat,(firsts,lasts) in NAME_BANK.items():
            for value in firsts: idx.setdefault(("f",value.lower()),nat)
            for value in lasts:  idx.setdefault(("l",value.lower()),nat)
        _NAME_INDEX=idx
    return _NAME_INDEX


def nationality_for_name(first, last):
    """Nationalité déduite du NOM lui-même (banque par pays)."""
    idx=_name_index()
    nat=idx.get(("l",str(last or "").lower())) or idx.get(("f",str(first or "").lower()))
    return nat or "Française"


