def _spin_arrow_assets():

    """Flèches des steppers QSpinBox : petits triangles PNG generates par

    l'application dans data/icons (une seule fois). Rien si Qt n'est pas pret :

    les regles ::up-arrow garde alors un fallback invisible sans casser le style."""

    global _SPIN_ARROW_CACHE

    try:

        if _SPIN_ARROW_CACHE is not None: return _SPIN_ARROW_CACHE

        from PySide6.QtGui import QGuiApplication, QPixmap, QPainter, QColor, QPolygonF

        from PySide6.QtCore import QPointF, Qt

        if QGuiApplication.instance() is None: return ("","")

        icons=os.path.join(DATA_DIR,"icons"); os.makedirs(icons,exist_ok=True)

        up_path=os.path.join(icons,"spin_up.png"); down_path=os.path.join(icons,"spin_down.png")

        for path,up in ((up_path,True),(down_path,False)):

            if not os.path.exists(path):

                pm=QPixmap(28,16); pm.fill(QColor(0,0,0,0))

                p=QPainter(pm); p.setRenderHint(QPainter.Antialiasing); p.setPen(Qt.NoPen)

                p.setBrush(QColor("#cfd9e8"))

                if up: poly=QPolygonF([QPointF(14,2.5),QPointF(25.5,13.5),QPointF(2.5,13.5)])

                else: poly=QPolygonF([QPointF(2.5,2.5),QPointF(25.5,2.5),QPointF(14,13.5)])

                p.drawPolygon(poly); p.end()

                pm.save(path,"PNG")

        _SPIN_ARROW_CACHE=(up_path.replace("\\","/"),down_path.replace("\\","/"))

        return _SPIN_ARROW_CACHE

    except Exception:

        return ("","")

_SPIN_ARROW_CACHE=None

_COMBO_ARROW_CACHE={}


def _combo_arrow_asset(color="#9fb0c5"):
    """Chevron de QComboBox dessiné une fois puis mis en cache."""
    try:
        if color in _COMBO_ARROW_CACHE: return _COMBO_ARROW_CACHE[color]
        from PySide6.QtGui import QGuiApplication, QPixmap, QPainter, QColor, QPen
        from PySide6.QtCore import Qt, QPointF
        if QGuiApplication.instance() is None: return ""
        icons=os.path.join(DATA_DIR,"icons"); os.makedirs(icons,exist_ok=True)
        os.makedirs(icons,exist_ok=True)
        path=os.path.join(icons,"combo_"+color.replace("#","")+".png")
        if not os.path.exists(path):
            pm=QPixmap(22,14); pm.fill(QColor(0,0,0,0))
            pp=QPainter(pm); pp.setRenderHint(QPainter.Antialiasing)
            pp.setPen(QPen(QColor(color),2.0,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            pp.drawLine(QPointF(5,5),QPointF(11,11)); pp.drawLine(QPointF(11,11),QPointF(17,5))
            pp.end(); pm.save(path,"PNG")
        _COMBO_ARROW_CACHE[color]=path.replace("\\","/")
        return _COMBO_ARROW_CACHE[color]
    except Exception:
        return ""






import colorsys

def _hex_to_rgb(h):
    h=h.lstrip("#")
    return tuple(int(h[i:i+2],16)/255.0 for i in (0,2,4))

def _rgb_to_hex(r,g,b):
    return "#%02x%02x%02x"%(int(round(r*255)),int(round(g*255)),int(round(b*255)))

def _lum(rgb):
    r,g,b=rgb
    return 0.2126*r+0.7152*g+0.0722*b

def _light_surface(hexcol):
    r,g,b=_hex_to_rgb(hexcol)
    h,l,sat=colorsys.rgb_to_hls(r,g,b)
    # surfaces : on éclaircit fortement en gardant une trace de la teinte
    new_l=0.915 if l<0.10 else 0.895 if l<0.22 else 0.870 if l<0.34 else 0.840
    nr,ng,nb=colorsys.hls_to_rgb(h,new_l,min(sat,0.22))
    return _rgb_to_hex(nr,ng,nb)

def _light_border(hexcol):
    r,g,b=_hex_to_rgb(hexcol)
    h,l,sat=colorsys.rgb_to_hls(r,g,b)
    if l>=0.55: return _rgb_to_hex(r,g,b)
    nr,ng,nb=colorsys.hls_to_rgb(h,0.70,min(sat,0.25))
    return _rgb_to_hex(nr,ng,nb)

def _dark_text(hexcol):
    r,g,b=_hex_to_rgb(hexcol)
    h,l,sat=colorsys.rgb_to_hls(r,g,b)
    if sat>0.45:      # accent coloré : on assombrit pour rester lisible
        nr,ng,nb=colorsys.hls_to_rgb(h,max(0.16,min(0.40,l*0.55)),min(0.85,sat))
    else:
        nr,ng,nb=colorsys.hls_to_rgb(0.60,0.14,0.10)
    return _rgb_to_hex(nr,ng,nb)


def _light_rgba(match):
    r,g,b,a=int(match.group(1)),int(match.group(2)),int(match.group(3)),match.group(4)
    lum=(0.2126*r+0.7152*g+0.0722*b)/255.0
    if lum<0.24:
        return f"rgba(246,249,253,{a})"
    return match.group(0)


def light_stylesheet(base, inline=False):
    """Transforme une feuille sombre en feuille claire.

    · MODE GLOBAL (inline=False) : les surfaces deviennent claires et les
      textes clairs sont assombris (la page est claire).
    · MODE INLINE (inline=True) : on raisonne PAR BLOC. Si le bloc définit une
      surface sombre, elle est éclaircie et son texte assombri ; si le fond est
      un ACCENT (bouton vert, bleu, violet), rien n'est touché : le texte blanc
      reste blanc."""
    def conv(col, is_bg, gradient, darken_text):
        try: rgb=_hex_to_rgb(col)
        except Exception: return col
        lum=_lum(rgb)
        if is_bg:
            if gradient: return _light_surface(col) if lum<0.24 else col
            return _light_surface(col) if lum<0.52 else col
        if darken_text and lum>0.58: return _dark_text(col)
        return col

    def transform_block(decls):
        # 1) ce bloc définit-il une surface sombre ?
        has_dark_surface=False
        for prop,value in re.findall(r'([A-Za-z-]+)\s*:\s*([^;{}]+)',decls):
            if "background" in prop.lower():
                for col in re.findall(r'#[0-9a-fA-F]{6}',value):
                    try:
                        if _lum(_hex_to_rgb(col))<0.24: has_dark_surface=True
                    except Exception: pass
                if "rgba(" in value: has_dark_surface=True
        darken_text=(not inline) or has_dark_surface
        def fix(m):
            prop=m.group(1); value=m.group(2); low=prop.lower()
            is_bg="background" in low
            gradient="gradient" in value
            def conv_hex(mm): return conv(mm.group(0),is_bg,gradient,darken_text)
            value=re.sub(r'#[0-9a-fA-F]{6}',conv_hex,value)
            if is_bg or "border" in low:
                value=re.sub(r'rgba\((\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*([0-9.]+)\)',_light_rgba,value)
            return f"{prop}:{value}"
        return re.sub(r'([A-Za-z-]+)\s*:\s*([^;{}]+)',fix,decls)

    # traitement bloc par bloc : "selecteur { declarations }"
    out=[]; i=0
    for m in re.finditer(r'\{([^{}]*)\}',base):
        out.append(base[i:m.start()+1])
        out.append(transform_block(m.group(1)))
        i=m.end()-1
    out.append(base[i:])
    return "".join(out)


def apply_theme_to_tree(root, light):
    """Applique (ou retire) le thème clair aux styles INLINE des widgets.

    La feuille globale ne suffit pas : beaucoup de cartes et de tableaux
    portent leur propre setStyleSheet(). On mémorise leur version sombre dans
    la propriété `_dark_qss` pour pouvoir revenir en arrière proprement."""
    try:
        from PySide6.QtWidgets import QWidget
    except Exception:
        return
    stack=[root]
    while stack:
        wdg=stack.pop()
        try:
            if not isinstance(wdg,QWidget):
                continue
            qss=wdg.styleSheet()
            base=wdg.property("_dark_qss")
            if base is None and qss and "#" in qss:
                wdg.setProperty("_dark_qss",qss); base=qss
            if base:
                wdg.setStyleSheet(light_stylesheet(base, inline=True) if light else base)
            stack.extend(wdg.children())
        except Exception:
            continue


def style_for_theme(theme):

    style=STYLE

    up,down=_spin_arrow_assets()

    if not up: # pas de PNG : fleches natives de Qt (aucune regle image)

        style=style.replace("QSpinBox::up-arrow { image:url({SPIN_UP_URL}); width:11px; height:7px; }","")

        style=style.replace("QSpinBox::down-arrow { image:url({SPIN_DOWN_URL}); width:11px; height:7px; }","")

    else:

        style=style.replace("{SPIN_UP_URL}",up).replace("{SPIN_DOWN_URL}",down)

    for old,new in THEME_REPLACEMENTS.get(theme,{}).items():

        style=style.replace(old,new)

    arrow=_combo_arrow_asset("#26333f" if theme=="Clair" else "#9fb0c5")

    if arrow: style=style.replace("{COMBO_ARROW_URL}",arrow)

    else: style=re.sub(r'QComboBox::down-arrow \{[^}]*\}','',style)

    if theme=="Clair":
        style=light_stylesheet(style)

    return style





