def unique_save_path(name):

    slug=re.sub(r"[^a-z0-9]+","_",name.lower()).strip("_") or "carriere"

    stem=f"{slug}_{datetime.now().strftime('%Y%m%d_%H%M%S')}"

    path=os.path.join(SAVE_DIR,stem+".db"); suffix=2

    while os.path.exists(path):

        path=os.path.join(SAVE_DIR,f"{stem}_{suffix}.db"); suffix+=1

    return path



class _Row(dict):

    """Ligne de base de données compatible dict : supporte row["col"], row.get("col", def) ET row[0] (index)."""

    def __init__(self, *args, **kwargs):

        super().__init__(*args, **kwargs)

        self._keys = list(self.keys())

    def __getitem__(self, key):

        if isinstance(key, int):

            return list(self.values())[key]

        try:

            return super().__getitem__(key)

        except KeyError:

            raise KeyError(key)

    def get(self, key, default=None):

        try:

            return self[key]

        except KeyError:

            return default

    def __getattr__(self, name):

        # Permet d'accéder aux colonnes comme des attributs : row.club_id

        try:

            return self[name]

        except KeyError:

            raise AttributeError(name)





class FinanceChart(QFrame):

    """Mini-graphe financier dessine a la main : courbe de tresorerie (mode line) ou flux nets (mode bar)."""

    MODES=("line","bar")

    def __init__(self,mode="line",title=""):

        super().__init__()

        self._mode=mode if mode in self.MODES else "line"

        self._series=[]; self._title=title

        self.setMinimumHeight(140); self.setMinimumWidth(200)

        self.setStyleSheet("background:#141c2c;border:1px solid #26334a;border-radius:8px;")

    def set_series(self,series):

        try: self._series=[float(v) for v in series]

        except (TypeError,ValueError): self._series=[]

        self.update()

    def paintEvent(self,event):

        p=QPainter(self); p.setRenderHint(QPainter.Antialiasing)

        w=float(self.width()); h=float(self.height())

        p.fillRect(QRectF(0,0,w,h),QColor("#141c2c"))

        if self._title:

            f=QFont(); f.setPointSize(7); f.setBold(True); f.setWeight(QFont.Black); p.setFont(f)

            p.setPen(QPen(QColor("#aeb9d1")))

            p.drawText(QRectF(10,4,w-20,14),int(Qt.AlignLeft|Qt.AlignVCenter),self._title)

        s=self._series

        if not s: return

        bottom=h-10.0; top=22.0

        all_min=min(0.0,min(s)); all_max=max(s)

        if all_max-all_min<1e-9: all_max=all_min+1.0

        span=all_max-all_min

        # Série plate (une seule valeur ou historique constant) : une ligne
        # médiane discrète, jamais une barre géante qui remplit tout le graphe.
        if (max(s)-min(s))<1e-9:

            mid=(top+bottom)/2.0

            p.setPen(QPen(QColor("#4a5b7d"),1)); p.drawLine(QPointF(12,mid),QPointF(w-12,mid))

            p.setPen(QPen(QColor("#6fd0e8"),2)); p.drawLine(QPointF(12,mid),QPointF(w-12,mid))

            f2=QFont(); f2.setPointSize(7); p.setFont(f2); p.setPen(QPen(QColor("#7f8ba4")))

            p.drawText(QRectF(10,bottom-13,w-20,13),int(Qt.AlignRight|Qt.AlignVCenter),f"{s[-1]:,.0f}".replace(","," ")+" €")

            p.end(); return

        def y(v):

            return bottom-(bottom-top)*((v-all_min)/span)

        if self._mode=="bar":

            n=len(s); slot=(w-24.0)/n; zero=y(0.0)

            for i,v in enumerate(s):

                height=abs(v)/span*(bottom-top)

                color=QColor("#6f9384") if v>=0 else QColor("#b07a7a")

                p.setPen(QPen(color,1)); p.setBrush(color)

                if v>=0:

                    rect=QRectF(12+i*slot+2,zero-height,max(3.0,slot-4.0),max(1.0,height))

                else:

                    rect=QRectF(12+i*slot+2,zero,max(3.0,slot-4.0),max(1.0,height))

                p.drawRect(rect)

            p.setBrush(Qt.NoBrush); p.setPen(QPen(QColor("#4a5b7d"),1))

            p.drawLine(QPointF(12,zero),QPointF(w-12,zero))

        else:

            denom=max(1,len(s)-1)

            pts=[QPointF(12+i*(w-24.0)/denom,y(v)) for i,v in enumerate(s)]

            fill=QPolygonF(pts+[QPointF(pts[-1].x(),bottom),QPointF(pts[0].x(),bottom)])

            grad=QLinearGradient(QPointF(0,top),QPointF(0,bottom))

            grad.setColorAt(0,QColor(143,169,196,70)); grad.setColorAt(1,QColor(143,169,196,8))

            p.setBrush(grad); p.setPen(QPen(QColor("#111c2c"),1)); p.drawPolygon(fill)

            p.setBrush(Qt.NoBrush); p.setPen(QPen(QColor("#9fb8d0"),2)); p.drawPolyline(pts)

            f2=QFont(); f2.setPointSize(7); p.setFont(f2); p.setPen(QPen(QColor("#7f8ba4")))

            p.drawText(QRectF(10,bottom-13,w-20,13),int(Qt.AlignRight|Qt.AlignVCenter),f"{s[-1]:,.0f}".replace(","," ")+" €")





def db():

    conn = sqlite3.connect(DB_PATH)

    conn.row_factory = lambda cursor, row: _Row(zip([d[0] for d in cursor.description], row))

    return conn





def db_path(path):

    """Connexion SQLite avec row_factory _Row pour supporter .get() sur n'importe quel chemin."""

    conn = sqlite3.connect(path)

    conn.row_factory = lambda cursor, row: _Row(zip([d[0] for d in cursor.description], row))

    return conn





def _rep_name_fr(rep_value):

    """Nom de palier de réputation associé à une valeur 0..100."""

    v=max(0,min(100,int(rep_value or 0)))

    return "LOCAL" if v<25 else "RÉGIONALE" if v<50 else "NATIONALE" if v<70 else "CONTINENTALE" if v<88 else "MONDIALE"





def column_exists(conn, table, column):

    rows = conn.execute(f"PRAGMA table_info({table})").fetchall()

    return any(r[1] == column for r in rows)





def record_player_history(conn,player_id,club_id,kind,detail,season=None):

    """Grave un évènement de carrière (signature, transfert, résiliation…) pour le suivi global."""

    try:

        if season is None:

            row=conn.execute("SELECT season FROM club WHERE id=?",(club_id,)).fetchone() if club_id else None

            if row is None:

                row=conn.execute("SELECT season FROM club WHERE id=1").fetchone()

            season=int(row["season"] or 1) if row else 1

        conn.execute("INSERT INTO player_history(player_id,season,club_id,kind,detail,created_at) VALUES(?,?,?,?,?,?)",

                     (player_id,season,club_id,kind,detail,career_timestamp(conn)))

    except sqlite3.Error as exc:

        try: add_news(conn,"Erreur d'historique",str(exc))

        except Exception: pass





