def sync_league_state(conn):

    club_rows = conn.execute("SELECT id FROM club ORDER BY id").fetchall()

    club_ids = {r["id"] for r in club_rows}

    for cid in club_ids:

        conn.execute("INSERT OR IGNORE INTO league_standing(club_id) VALUES(?)", (cid,))



    stale = conn.execute("SELECT club_id FROM league_standing").fetchall()

    for r in stale:

        if r["club_id"] not in club_ids:

            conn.execute("DELETE FROM league_standing WHERE club_id=?", (r["club_id"],))



    career = conn.execute("SELECT wins,draws,losses,goals_for,goals_against,points FROM career WHERE id=1").fetchone()

    # NOTE : pas de reinjection des totaux carriere dans le classement — avec les clotures de

    # saison le classement est remis a zero et doit rester dans sa saison. reconcile_user_results

    # reconstruit la ligne du club depuis les matchs de la saison en cours (juste apres, dans init_db).



    tx_count = conn.execute("SELECT COUNT(*) n FROM finance_tx WHERE club_id=1").fetchone()["n"]

    if tx_count == 0:

        starting_budget=conn.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"]

        conn.execute(

            "INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",

            ("Capital de départ", starting_budget, career_timestamp(conn), "Capital"),

        )



    conn.execute("INSERT OR IGNORE INTO facility(id,arena_level,medical_level,youth_level,marketing_level) VALUES(1,1,1,1,1)")

    conn.execute('UPDATE career SET "current_date"=COALESCE(NULLIF("current_date",\'\'),\'2026-08-01\') WHERE id=1')

    # Reparation UNIQUE des anciennes sauvegardes (contrats corrompus a 0) : un drapeau meta

    # evite d'annuler les expirations de contrat legitimes produites par les clotures de saison.

    if not conn.execute("SELECT value FROM meta WHERE key='contract_repair_v1'").fetchone():

        conn.execute("UPDATE player SET is_free_agent=1,contract_years=0,transfer_listed=0 WHERE contract_years<=0 AND COALESCE(is_free_agent,0)=0 AND COALESCE(retired,0)=0")

        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('contract_repair_v1','1')")

    # NETTOYAGE : un joueur à 0 année de contrat est LIBRE, il ne reste pas
    # dans l'effectif (retour « les joueurs à 0 an restent au club »).
    if not conn.execute("SELECT value FROM meta WHERE key='free_agents_clean_v1'").fetchone():
        conn.execute("UPDATE player SET is_free_agent=1,contract_years=0,transfer_listed=0 WHERE COALESCE(is_free_agent,0)=0 AND contract_years<=0 AND COALESCE(retired,0)=0")
        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('free_agents_clean_v1','1')")

    # RÉÉQUILIBRAGE DES SALAIRES (sauvegardes issues de l'ancienne formule) :
    # un contrat payé plus de 1,7× sa valeur sportive est réaligné à 1,6×.
    if not conn.execute("SELECT value FROM meta WHERE key='salary_balance_v1'").fetchone():
        try:
            rows=conn.execute("""SELECT p.*, c.division div FROM player p JOIN club c ON c.id=p.club_id
                                 WHERE COALESCE(p.is_free_agent,0)=0""").fetchall()
            fixed=0
            for p in rows:
                fair=compute_fair_salary(player_level_from_row(p),int(p["div"] or 3),int(p["age"] or 25),player_potential_from_row(p))
                sal=int(p["salary"] or 0)
                if sal>int(fair*1.7):
                    conn.execute("UPDATE player SET salary=? WHERE id=?",(int(round(fair*1.6/50))*50,int(p["id"])))
                    fixed+=1
            if fixed:
                add_news(conn,"Finances",
                         f"Rééquilibrage des salaires : {fixed} contrat(s) alignés sur la valeur sportive — la masse salariale redevient soutenable.")
        except Exception:
            pass
        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('salary_balance_v1','1')")

    conn.execute("UPDATE player SET salary=2500 WHERE salary<=0 AND COALESCE(is_free_agent,0)=0")

    conn.execute("UPDATE player SET market_value=MAX(15000, round((technique+passing+finishing+defense+stamina)*700.0/2500.0)*2500) WHERE market_value<=0")



    team_ids=[row[0] for row in conn.execute("SELECT DISTINCT club_id FROM player").fetchall()]

    for team_id in team_ids:

        team_players=conn.execute("SELECT id,shirt_number FROM player WHERE club_id=? ORDER BY CASE position WHEN 'Gardien' THEN 0 ELSE 1 END,last_name,id",(team_id,)).fetchall()

        used_numbers={int(p["shirt_number"]) for p in team_players if 1<=int(p["shirt_number"])<=99}

        next_number=1

        for player in team_players:

            if int(player["shirt_number"])>0: continue

            while next_number in used_numbers and next_number<=99: next_number+=1

            number=next_number if next_number<=99 else (int(player["id"])%99)+1

            conn.execute("UPDATE player SET shirt_number=? WHERE id=?",(number,player["id"]))

            used_numbers.add(number); next_number+=1



    conn.execute("CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT)")

    conn.execute("INSERT OR IGNORE INTO meta(key,value) VALUES('scout_staff_hired','0')")

    conn.execute("INSERT OR IGNORE INTO meta(key,value) SELECT 'scout_level',CASE WHEN value='1' THEN '1' ELSE '0' END FROM meta WHERE key='scout_staff_hired'")

    conn.execute("INSERT OR IGNORE INTO meta(key,value) VALUES('physio_hired','0')")

    conn.execute("INSERT OR IGNORE INTO meta(key,value) VALUES('preparateur_physique_hired','0')")
    conn.execute("INSERT OR IGNORE INTO meta(key,value) VALUES('difficulty_mode','Normale')")

    for staff_key in ("comptable_hired","directeur_sportif_hired","adjoint_hired","marketing_hired"):

        conn.execute("INSERT OR IGNORE INTO meta(key,value) VALUES(?, '0')",(staff_key,))

    free_agents_seeded=conn.execute("SELECT value FROM meta WHERE key='free_agents_seeded_v1'").fetchone()

    if not free_agents_seeded:

        candidates=conn.execute("SELECT id FROM player WHERE club_id>0 AND club_id<>1 AND is_free_agent=0 AND COALESCE(retired,0)=0 ORDER BY market_value ASC,age DESC,id LIMIT 6").fetchall()

        for candidate in candidates:

            conn.execute("UPDATE player SET is_free_agent=1,contract_years=0 WHERE id=?",(candidate["id"],))

        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('free_agents_seeded_v1','1')")



    news_count = conn.execute("SELECT COUNT(*) n FROM news").fetchone()["n"]

    if news_count == 0:

        add_news(conn, "Bienvenue Manager", "Le board vous confie les clés du club. Objectif : installer une dynastie en futsal.")

    ensure_fixtures(conn)

    normalize_club_names(conn)

    ensure_free_agents(conn)

    # Reparation des sauvegardes creees avec l'ancien generateur : un libre ne
    # reste jamais rattache au club du manager.
    try:
        conn.execute("""UPDATE player SET club_id=(SELECT id FROM club WHERE id<>1 ORDER BY RANDOM() LIMIT 1)
                        WHERE COALESCE(is_free_agent,0)=1 AND club_id=1""")
    except Exception:
        pass

    try:
        _today=str(conn.execute('SELECT "current_date" d FROM career WHERE id=1').fetchone()["d"])
        conn.execute("""UPDATE player SET free_agent_since=? WHERE COALESCE(is_free_agent,0)=1
                        AND COALESCE(free_agent_since,'')=''""",(_today,))
        conn.execute("""UPDATE player SET free_agent_since='' WHERE COALESCE(is_free_agent,0)=0
                        AND COALESCE(free_agent_since,'')<>''""")
        # Anciennes sauvegardes : un retraite ne doit jamais rester au marche.
        conn.execute("""UPDATE player SET is_free_agent=0,free_agent_since='',club_id=0
                        WHERE COALESCE(retired,0)=1""")
    except Exception:
        pass

    # Sauvegardes anciennes : le marche libre avait ete cree en vidant les
    # clubs. On remet immediatement les clubs IA sous 11 a niveau.
    try:
        from squad_engine import ensure_ai_squads as _ensure_ai_squads
        class _Host:
            @staticmethod
            def log_error(context, exc):
                pass
        _ensure_ai_squads(_Host(), conn, 11)
    except Exception:
        pass

    ensure_birth_dates(conn)

    diversify_world_names(conn)
    normalize_player_nationalities(conn)

    repair_overdue_career_at_boot(conn)

    restore_cup_results_from_records(conn)

    repair_phantom_user_fixtures(conn)

    repair_fixture_calendar(conn)

    repair_shirt_numbers(conn)





def reverse_league_standing(conn, club_id, gf, ga):

    """Défait _update_standing : retire un match battu par erreur d'une ligne de classement."""

    if gf>ga: w,d,l,pts=1,0,0,3

    elif gf==ga: w,d,l,pts=0,1,0,1

    else: w,d,l,pts=0,0,1,0

    conn.execute(

        """UPDATE league_standing SET played=MAX(0,played-1),wins=MAX(0,wins-?),draws=MAX(0,draws-?),

           losses=MAX(0,losses-?),gf=MAX(0,gf-?),ga=MAX(0,ga-?),pts=MAX(0,pts-?) WHERE club_id=?""",

        (w,d,l,gf,ga,pts,club_id),

    )





def restore_cup_results_from_records(conn):
    """Répare les coupes dont un résultat a été effacé par l'ancien correctif
    de matchs fantômes. Un match de coupe réellement joué possède un
    match_record daté du même jour ; on le remet en « joué » avec son score."""
    try:
        season=int(conn.execute("SELECT season FROM club WHERE id=1").fetchone()["season"] or 1)
        rows=conn.execute("""SELECT f.id,f.fixture_date,f.home_club_id,f.away_club_id,hc.name hn,ac.name an
                             FROM fixture f JOIN club hc ON hc.id=f.home_club_id
                             JOIN club ac ON ac.id=f.away_club_id
                             WHERE f.season=? AND f.fixture_type='cup' AND f.played=0
                               AND (f.home_club_id=1 OR f.away_club_id=1)""",(season,)).fetchall()
        restored=0
        for row in rows:
            rec=conn.execute("""SELECT home_goals,away_goals FROM match_record
                                WHERE season=? AND COALESCE(matchday,0)=0 AND home=? AND away=?
                                  AND substr(created_at,1,10) BETWEEN ? AND date(?,'+3 day')
                                ORDER BY id DESC LIMIT 1""",
                             (season,row["hn"],row["an"],str(row["fixture_date"]),str(row["fixture_date"]))).fetchone()
            if rec is None: continue
            conn.execute("UPDATE fixture SET played=1,home_goals=?,away_goals=? WHERE id=?",
                         (rec["home_goals"],rec["away_goals"],row["id"]))
            try:
                if not conn.execute("SELECT 1 FROM ai_match_report WHERE fixture_id=?",(row["id"],)).fetchone():
                    conn.execute("INSERT OR REPLACE INTO ai_match_report(fixture_id,scorers,created_at) VALUES(?,?,?)",
                                 (row["id"],"[]",str(row["fixture_date"])))
            except Exception:
                pass
            restored+=1
        if restored:
            add_news(conn,"Coupe Inter-Ligue",
                     f"{restored} résultat(s) de coupe restauré(s) depuis l'historique des matchs.")
    except sqlite3.Error as exc:
        print("restore_cup_results_from_records:",exc)


def repair_phantom_user_fixtures(conn):

    """Annule au démarrage les rencontres du club manager qui ont été marquées « jouées »

    par la simulation globale sans avoir été disputées par le joueur (aucun match_record).



    La simulation des autres clubs ne doit JAMAIS toucher les matchs du club du manager :

    ceux-ci sont remis à jouer, les classements des deux clubs sont rétablis et le dossier

    fantôme du calendrier est supprimé.

    """

    try:

        current_season=int(conn.execute("SELECT season FROM club WHERE id=1").fetchone()["season"] or 1)

        phantoms=conn.execute("""SELECT f.id,f.home_club_id,f.away_club_id,f.home_goals,f.away_goals,
                                         COALESCE(f.fixture_type,'championship') fixture_type

                                 FROM fixture f

                                 WHERE f.played=1 AND (f.home_club_id=1 OR f.away_club_id=1)

                                   AND f.season=?

                                   AND NOT EXISTS(SELECT 1 FROM match_record m

                                                  WHERE m.home=(SELECT name FROM club WHERE id=f.home_club_id)

                                                    AND m.away=(SELECT name FROM club WHERE id=f.away_club_id)

                                                    AND m.home_goals=f.home_goals AND m.away_goals=f.away_goals)""",(current_season,)).fetchall()

        if not phantoms: return

        for row in phantoms:

            hg=int(row["home_goals"] or 0); ag=int(row["away_goals"] or 0)

            # Seul le championnat alimente le classement : une coupe ou un amical
            # ne doit jamais être soustrait des statistiques de ligue.
            if str(row["fixture_type"] or "championship")=="championship":
                reverse_league_standing(conn,row["home_club_id"],hg,ag)
                reverse_league_standing(conn,row["away_club_id"],ag,hg)

            conn.execute("DELETE FROM ai_match_report WHERE fixture_id=?",(row["id"],))

            conn.execute("UPDATE fixture SET played=0,home_goals=NULL,away_goals=NULL WHERE id=?",(row["id"],))

        reconcile_user_results(conn)

        add_news(conn,"Calendrier réparé",f"{len(phantoms)} match(s) du club avait été enregistré(s) sans être disputé(s) : ils sont remis à jouer.")

    except sqlite3.Error as exc:

        print("repair_phantom_user_fixtures:",exc)





def repair_overdue_career_at_boot(conn):

    """Réparation au démarrage : si des matchs officiels du club sont en retard



    (date de carrière > date du match non joué), rembobine la date de carrière

    à la veille du premier match en retard. Protège les carrières créées avant

    que l'avance du calendrier ne s'arrête sur les matchs non joués.

    """

    try:

        career=conn.execute('SELECT "current_date" AS current_date FROM career WHERE id=1').fetchone()

        if not career or not str(career["current_date"]): return

        overdue=conn.execute(

            """SELECT fixture_date FROM fixture

               WHERE played=0 AND COALESCE(fixture_type,'championship')<>'friendly'

                 AND (home_club_id=1 OR away_club_id=1) AND fixture_date<?

               ORDER BY fixture_date LIMIT 1""",

            (str(career["current_date"]),),

        ).fetchone()

        if not overdue: return

        new_date=(date.fromisoformat(str(overdue["fixture_date"]))-timedelta(days=1)).isoformat()

        conn.execute("UPDATE career SET current_date=? WHERE id=1",(new_date,))

        add_news(conn,"Calendrier réparé",f"Des matchs officiels étaient en retard : la carrière revient au {fmt_date_fr(new_date)} pour les disputer.")

    except sqlite3.Error as exc:

        print("repair_overdue_career_at_boot:",exc)





def user_season_aggregate(conn, season):

    """Bilan du club manager sur LA SAISON DONNEE uniquement : filtre par la saison de la table fixture,

    entierement independant du dossier carriere — les reparations au boot ne corrompent plus

    les sauvegardes avancees (l'ancienne logique remontait les totaux de toute la carriere)."""

    club=conn.execute("SELECT name,season FROM club WHERE id=1").fetchone()

    if not club: return None

    if season is None: season=int(club["season"] or 1)

    agg={"played":0,"wins":0,"draws":0,"losses":0,"gf":0,"ga":0,"pts":0}

    for f in conn.execute("""SELECT home_club_id,away_club_id,home_goals,away_goals FROM fixture

                             WHERE season=? AND played=1 AND (home_club_id=1 OR away_club_id=1)

                             AND COALESCE(fixture_type,'championship')='championship' AND COALESCE(matchday,0)<100""",(season,)).fetchall():

        hg=int(f["home_goals"] or 0); ag=int(f["away_goals"] or 0)

        gf,ga=(hg,ag) if int(f["home_club_id"])==1 else (ag,hg)

        agg["played"]+=1; agg["gf"]+=gf; agg["ga"]+=ga

        if gf>ga: agg["wins"]+=1; agg["pts"]+=3

        elif gf==ag: agg["draws"]+=1; agg["pts"]+=1

        else: agg["losses"]+=1

    return agg





def reconcile_user_results(conn):

    """Reconstruit les resultats a PARTIR des scores enregistres (victoires a l'exterieur incluses).

    La table career garde le cumul de toute la carriere ; la ligne de classement du club du

    manager est reconstruite depuis les matchs de la SAISON EN COURS (les sauvegardes multi-saisons

    seraient sinon cumulees avec l'ancienne logique sur l'ensemble de la carriere)."""

    club=conn.execute("SELECT name FROM club WHERE id=1").fetchone()

    if not club: return

    records=conn.execute("SELECT matchday,home,away,home_goals,away_goals FROM match_record ORDER BY id").fetchall()

    wins=draws=losses=goals_for=goals_against=points=played=0

    for record in records:

        if record["home_goals"] is None or record["away_goals"] is None: continue

        # Les amicaux sont enregistres avec matchday=0 : jamais comptes pour le championnat.

        if int(record["matchday"] or 0)<=0: continue

        if record["home"]==club["name"]:

            gf,ga=int(record["home_goals"]),int(record["away_goals"])

        elif record["away"]==club["name"]:

            gf,ga=int(record["away_goals"]),int(record["home_goals"])

        else:

            continue

        played+=1; goals_for+=gf; goals_against+=ga

        if gf>ga: wins+=1; points+=3

        elif gf==ga: draws+=1; points+=1

        else: losses+=1

    if not played: return

    # Classement : la SAISON EN COURS uniquement (les saisons passees ne polluent plus le championnat).

    agg=user_season_aggregate(conn,None)

    if agg is None: return

    conn.execute("UPDATE career SET matchday=?,wins=?,draws=?,losses=?,goals_for=?,goals_against=?,points=? WHERE id=1",(agg["played"]+1,wins,draws,losses,goals_for,goals_against,points))

    conn.execute("UPDATE league_standing SET played=?,wins=?,draws=?,losses=?,gf=?,ga=?,pts=? WHERE club_id=1",

                 (agg["played"],agg["wins"],agg["draws"],agg["losses"],agg["gf"],agg["ga"],agg["pts"]))





def career_timestamp(conn):

    """Timestamp d'affichage basé sur le calendrier fictif de la carrière."""

    try:

        row = conn.execute('SELECT career."current_date" AS career_date FROM career WHERE id=1').fetchone()

        if row and row["career_date"]:

            return f"{row['career_date']}T{datetime.now().strftime('%H:%M')}"

    except sqlite3.Error:

        pass

    return datetime.now().isoformat(timespec="minutes")





def add_news(conn, title, body):

    conn.execute(

        "INSERT INTO news(title,body,created_at) VALUES(?,?,?)",

        (title, body, career_timestamp(conn)),

    )





def queue_manager_message(conn,kind,title,body,created_date,due_date,action_data,is_read=False,ready=False):

    conn.execute(

        "INSERT INTO manager_message(kind,title,body,created_date,due_date,status,action_data,is_read) VALUES(?,?,?,?,?,?,?,?)",

        (kind,title,body,created_date,due_date,"ready" if ready else "waiting",
         json.dumps(action_data,ensure_ascii=False),int(is_read)),

    )





def next_shirt_number(conn,club_id):

    used={int(row[0]) for row in conn.execute("SELECT shirt_number FROM player WHERE club_id=? AND shirt_number BETWEEN 1 AND 99",(club_id,)).fetchall()}

    return next((number for number in range(1,100) if number not in used),1)





def repair_shirt_numbers(conn):

    """Ressource unique du club : aucun doublon de numéro de maillot autorisé.

    Les doublons (ou numéros 0/vide) sont réattribués au premier numéro libre."""

    fixed=0

    for crow in conn.execute("SELECT id FROM club").fetchall():

        club_id=int(crow["id"])

        seen=set()

        for prow in conn.execute("SELECT id,shirt_number FROM player WHERE club_id=? ORDER BY shirt_number,id",(club_id,)).fetchall():

            number=int(prow["shirt_number"] or 0)

            if number<1 or number>99 or number in seen:

                new=next_shirt_number(conn,club_id)

                conn.execute("UPDATE player SET shirt_number=? WHERE id=?",(new,prow["id"]))

                seen.add(new); fixed+=1

            else:

                seen.add(number)

    return fixed





WINTER_BREAK_START_DAY = 21   # trêve du 21/12 au 4/01 inclus





# --- Postes secondaires, pied préféré, polyvalence : dérivés des attributs réels,

# --- déterministes (même joueur → même profil), sans colonne supplémentaire.

POSITION_FIT_WEIGHTS={

    "Gardien":{"goalkeeper":1.0,"positioning":.25,"defense":.1,"stamina":.05},

    "Défenseur":{"defense":1.0,"positioning":.5,"stamina":.3,"goalkeeper":-.15,"passing":.15},

    "Ailier":{"dribble":.75,"speed":.7,"technique":.45,"finishing":.35,"passing":.2,"defense":-.1},

    "Pivot":{"finishing":.8,"technique":.4,"positioning":.3,"defense":.25,"passing":.25,"goalkeeper":-.2},

    "Universel":{"technique":.4,"passing":.4,"defense":.35,"dribble":.3,"speed":.3,"finishing":.3,"stamina":.3,"positioning":.2},

}



def player_position_fit(p,position):

    """Adequation 0-100 du joueur au poste (attributs pondérés specifiques futsal)."""

    weights=POSITION_FIT_WEIGHTS[position]

    total=0.0

    for key,weight in weights.items():

        value=float(row_get(p,key,50) or 50)

        total+=rating20(value)*5.0*weight

    return max(0,min(100,int(round(total))))





def player_positions_from_row(p):

    """((poste naturel, fit), [(poste secondaire, fit, label)], ...)."""

    natural=str(row_get(p,"position","Universel") or "Universel")

    natural_fit=player_position_fit(p,natural)

    secondaries=[]

    for position in POSITION_FIT_WEIGHTS:

        if position==natural: continue

        fit=player_position_fit(p,position)

        if fit>=natural_fit-5:

            secondaries.append((position,fit,"CONFORTABLE"))

        elif fit>=natural_fit-10:

            secondaries.append((position,fit,"POSSIBLE"))

    secondaries.sort(key=lambda item:-item[1])

    return natural,natural_fit,secondaries[:2]





def player_preferred_foot(p):

    roll=f"{int(row_get(p,'id',0))}"

    pick=random.Random(f"foot|{roll}").random()

    return "Droitier" if pick<0.72 else "Gaucher" if pick<0.95 else "Ambidextre"





def player_versatility(p):

    """Polyvalence 0-100 : moyenne des adequations sur les cinq postes."""

    return max(0,min(100,int(round(sum(player_position_fit(p,position) for position in POSITION_FIT_WEIGHTS)/len(POSITION_FIT_WEIGHTS)))))





# --- SCOUTING : découverte progressive. Une mission rapporte un gain variable

# --- (effort, niveau du recruteur) et une fiabilité. Les attributs ne passent en

# --- précis qu'à partir d'une connaissance forte ; le potentiel reste le dernier

# --- secret (strictement à 100).



SCOUT_EFFORTS={

    "express":{"label":"EXPRESS","days":2,"cost":1200,"gain_mod":-8,"acc_bonus":0.00},

    "standard":{"label":"STANDARD","days":4,"cost":0,"gain_mod":0,"acc_bonus":0.05},

    "deep":{"label":"APPROFONDIE","days":6,"cost":2400,"gain_mod":7,"acc_bonus":0.12},

}



def scout_gain_for(player_id,reports,scout_level,effort="standard"):

    """Gain de connaissance d'une mission : varie (effort, niveau recruteur, grain du joueur)."""

    effort_meta=SCOUT_EFFORTS.get(effort or "standard",SCOUT_EFFORTS["standard"])

    rng=random.Random(f"scoutgain|{player_id}|{reports}")

    base=32+2*int(scout_level or 0)+effort_meta["gain_mod"]+rng.randint(-5,8)

    return int(max(18,min(52,base)))



def scout_accuracy_for(player_id,reports,scout_level,effort="standard"):

    """Fiabilité 0.35-0.95 d'après le recruteur, l'effort et un grain par observation."""

    effort_meta=SCOUT_EFFORTS.get(effort or "standard",SCOUT_EFFORTS["standard"])

    rng=random.Random(f"scoutacc|{player_id}|{reports}")

    value=0.52+0.04*int(scout_level or 0)+effort_meta["acc_bonus"]+rng.uniform(-0.06,0.10)

    return round(float(max(0.35,min(0.95,value))),2)



def scout_attr_band(knowledge,accuracy=0.60):

    """Blur maximal sur un attribut : 0 = précis. Rien d'affiché sous 25."""

    if knowledge>=100: return 0

    base=None

    if knowledge>=75: base=1

    elif knowledge>=45: base=2

    elif knowledge>=25: base=3

    elif knowledge>=1: base=4

    if base is None: return None

    if accuracy<0.50 and base>0: base+=1

    return int(base)



def scout_attr_text(p,key,knowledge,accuracy=0.60):

    """Texte d'attribut visible : — (inconnu), ~x-y (fourchette) ou x/20 (précis)."""

    band=scout_attr_band(knowledge,accuracy)

    if band is None: return "—"

    value=int(round(rating20(p[key])))

    if band==0: return f"{value}/20"

    low=max(1,value-band); high=min(20,value+band)

    return ("≈ " if band>=3 else "")+f"{low}-{high}"



def scout_attr_low_band(p,key,knowledge,accuracy=0.60):

    """Borne basse garantie de l'attribut (sert uniquement aux filtres honnêtes)."""

    band=scout_attr_band(knowledge,accuracy)

    if band is None: return 0

    return max(1,int(round(rating20(p[key])))-band)



def scout_potential_text(p,knowledge,accuracy=0.60):

    """Le potentiel est le dernier secret : inconnu < 75, fourchette < 100, exact à 100."""

    if knowledge<75: return "—"

    value=int(round(player_potential_from_row(p)))

    if knowledge>=100: return f"{value}/20"

    if accuracy<0.5: return f"~{max(1,value-3)}-{min(20,value+3)}"

    return f"~{max(1,value-2)}-{min(20,value+2)}"



def scout_level_text(p,knowledge,accuracy=0.60):

    """Niveau actuel : inconnu < 25, fourchette, puis précis à partir de 75."""

    if knowledge<25: return "—"

    value=int(round(player_level_from_row(p)))

    if knowledge>=75: return f"{value}/20"

    return f"≈{max(1,value-2)}-{min(20,value+2)}"



def scout_value_band(p,knowledge,season=None,key_player=False):

    """Estimation de valeur : publique si listé (demande connue), incertaine sinon.



    Les joueurs libres ne sont PLUS publics : sans indemnité, leur valeur ne doit pas

    trahir leur niveau — elle s'estime au fil des missions de scouting."""

    value=int(p["market_value"] or 0)

    if p["transfer_listed"] or knowledge>=60:

        return value,value,True

    rng=random.Random(f"valband|{p['id']}|{season}")



    span=max(1000,int(value*0.28)-2)

    low=max(500,int(value-rng.randint(span//2,span)))

    low=min(low,value)

    high=low+span

    return low,high,False



def scout_contract_known(knowledge):

    """Exigences contractuelles fiables seulement sous une observation suffisante."""

    return knowledge>=60





def free_agent_offer_hint(player_id, row=None):

    """Montant de départ proposé dans le dialogue pour un JOUEUR LIBRE.



    Sans connaissance suffisante, on n'affiche PAS le salaire réel (qui trahirait le

    niveau) : le curseur démarre sur le bas d'une fourchette voilée, même graine

    ('salband') que la tuile PRÉTENTION de la fiche pour rester cohérent."""

    conn=db()

    if row is None:

        row=conn.execute("SELECT salary FROM player WHERE id=?",(player_id,)).fetchone()

    krow=conn.execute("SELECT COALESCE(knowledge,0) k FROM scout_report WHERE player_id=?",(player_id,)).fetchone()

    conn.close()

    if row is None: return 5000

    try: base_sal=int(row["salary"] or 0)

    except (TypeError,ValueError): base_sal=0

    try: knowledge=int(krow["k"] or 0) if krow else 0

    except (TypeError,ValueError): knowledge=0

    if scout_contract_known(knowledge):

        return max(250,int(base_sal*1.1))

    rng=random.Random(f"salband|{player_id}")

    return max(250,int(base_sal*(1.0-rng.uniform(0.15,0.35))))





def free_agent_ask_salary(player,club):

    """Exigence NÉGOCIABLE d'un joueur libre : l'agent démarre sur la fourchette

    HAUTE (aléa tiré une fois pour toutes par joueur+saison, donc stable entre

    deux ouvertures de dialogue) puis peut concéder au fil des tours jusqu'au

    PLANCHER (player_salary_demand). Retourne (ask, floor)."""

    floor,_gap=player_salary_demand(player,club)

    try: season=int(club["season"] or 1)

    except (TypeError,KeyError,IndexError): season=1

    rng=random.Random(f"freeask|{int(player['id'])}|{season}")

    ask=round_money(max(floor,int(floor*rng.uniform(1.18,1.55))))

    return ask,floor





def scout_tier_label(knowledge):

    if knowledge>=100: return ("COMPLET","#66e5a8")

    if knowledge>=75: return ("AVANCÉ","#8ed9ff")

    if knowledge>=45: return ("PARTIEL","#ffd16d")

    if knowledge>=25: return ("APERÇU","#c89aff")

    if knowledge>=1: return ("À PEINE VU","#9aa8c4")

    return ("NON OBSERVÉ","#77839c")









def first_saturday_of_season(d):

    """Le calendrier démarre le premier samedi de septembre de l'année courante."""

    base=date(int(d.year),9,1)

    offset=(5-base.weekday())%7   # 5 = samedi

    return base+timedelta(days=offset)





def matchday_dates(count,kickoff):

    """Calendrier ETALÉ (retour « matchs étalés sur la saison, saison

    septembre → mars/avril », trêves hivernale ET estivale) : trêve de

    NOËL (21/12 → 4/01, conservée) ; l'ÉTÉ est la trêve naturelle (aucune

    journée de juillet-août : la saison reprend le premier samedi de

    septembre). Le rythme s'élargit quand l'hiver avance :

    septe-octobre = toutes les semaines ; novembre-décembre = +12 j ;

    janvier-avril = +14 j → 18 journées finissent début mars."""

    dates=[]

    d=kickoff

    while len(dates)<count:

        if d.month==12 and d.day>=WINTER_BREAK_START_DAY:

            d=date(d.year+1,1,5)

        dates.append(d.isoformat())

        if d.month in (9,10):

            d=d+timedelta(days=7)

        elif d.month in (11,12):

            d=d+timedelta(days=12)

        else:

            d=d+timedelta(days=14)   # janvier→avril : rythme calme d'hiver

    return dates





def division_pairings(teams,seed):

    """Calendrier aller-retour d'une division : Berger + domicile équilibré + lissage.



    Chaque club rencontre chaque adversaire une fois à domicile et une fois à

    l'extérieur, dispute exactement un match par journée, et n'enchaîne jamais

    plus de deux rencontres au même endroit.

    """

    rotation=[int(t) for t in teams]

    random.Random(f"calendar|{seed}").shuffle(rotation)

    if len(rotation)%2:

        rotation.append(None)

    rounds=len(rotation)-1; half=len(rotation)//2

    alive=[t for t in rotation if t is not None]

    cards_by_round=[]

    for _ in range(rounds):

        cards=[]

        for pair_index in range(half):

            left,right=rotation[pair_index],rotation[-1-pair_index]

            if left is None or right is None: continue

            cards.append((left,right))

        cards_by_round.append(cards)

        rotation=[rotation[0],rotation[-1],*rotation[1:-1]]

    home_count={t:0 for t in alive}

    phasing={}

    first_leg=[]

    for index,cards in enumerate(cards_by_round):

        drawn=[]

        for left,right in cards:

            if home_count[left]>home_count[right] or (home_count[left]==home_count[right] and (index+((left<right)-(left>right)))%2):

                left,right=right,left

            home_count[left]+=1

            phasing[(left,index)]=True; phasing[(right,index)]=False

            drawn.append((left,right))

        first_leg.append(drawn)

    # Lissage par descente locale : on n'inverse la journée d'une paire que si cela

    # réduit le nombre de suites de 3 au même endroit. La phase aller et son retour

    # dérivent de la même liste : chaque club garde un match à domicile et un à

    # l'extérieur contre chaque adversaire.

    def _run_penalty():

        penalty=0

        for t in alive:

            sequence=[phasing[(t,r)] for r in range(rounds)]+[not phasing[(t,r)] for r in range(rounds)]

            run=1

            for i in range(1,len(sequence)):

                run=run+1 if sequence[i]==sequence[i-1] else 1

                if run>=3: penalty+=1

        return penalty

    for _iter in range(400):

        current=_run_penalty()

        if current==0: break

        best=None; best_penalty=current

        for index in range(rounds):

            for card in tuple(first_leg[index]):

                h,a=card

                first_leg[index].remove(card); first_leg[index].append((a,h))

                phasing[(h,index)]=False; phasing[(a,index)]=True

                p=_run_penalty()

                if p<best_penalty:

                    best=(index,h,a); best_penalty=p

                # remets l'original en place pour continuer l'exploration

                first_leg[index].remove((a,h)); first_leg[index].append((h,a))

                phasing[(h,index)]=True; phasing[(a,index)]=False

        if best is None: break

        index,h,a=best

        first_leg[index].remove((h,a)); first_leg[index].append((a,h))

        phasing[(h,index)]=False; phasing[(a,index)]=True

    calendar=[]

    for md,drawn in enumerate(first_leg,start=1):

        for home,away in drawn: calendar.append((md,home,away))

    for md,drawn in enumerate(first_leg,start=rounds+1):

        for home,away in drawn: calendar.append((md,away,home))

    return calendar





def season_number_for_calendar(conn):

    try:

        return int(conn.execute("SELECT MAX(season) FROM club").fetchone()[0] or 1)

    except sqlite3.Error:

        return 1





def build_division_fixtures(conn,season,division,today=None):

    """Construit (sans écrire) le calendrier complet d'une division pour une saison."""

    if today is None:

        today=parse_iso(conn.execute('SELECT "current_date" FROM career WHERE id=1').fetchone()["current_date"])

    teams=[int(row["id"]) for row in conn.execute("SELECT id FROM club WHERE division=? ORDER BY id",(division,)).fetchall()]

    if len(teams)<2: return []

    calendar=division_pairings(teams,f"{season}|{division}")

    dates=matchday_dates(len(calendar) and max(md for md,_,_ in calendar) or 0,first_saturday_of_season(today))

    return [(md,dates[md-1],home,away) for md,home,away in calendar if 0<md<=len(dates)]





def write_division_fixtures(conn,season,division,today=None):

    inserted=0

    for md,fixture_date,home,away in build_division_fixtures(conn,season,division,today):

        conn.execute("INSERT INTO fixture(season,matchday,fixture_date,home_club_id,away_club_id,fixture_type) VALUES(?,?,?,?,?,'championship')",

                     (season,md,fixture_date,home,away))

        inserted+=1

    return inserted





def ensure_fixtures(conn):

    cnt = conn.execute("SELECT COUNT(*) n FROM fixture WHERE (home_club_id=1 OR away_club_id=1)").fetchone()["n"]

    season=season_number_for_calendar(conn)

    if cnt == 0:

        start=parse_iso(conn.execute('SELECT career."current_date" AS current_date FROM career WHERE id=1').fetchone()["current_date"])

        for division_row in conn.execute("SELECT DISTINCT division FROM club ORDER BY division").fetchall():

            write_division_fixtures(conn,season,int(division_row["division"] or 3),start)

    # COUPE INTER-LIGUE : tirage au sort entre TOUTES les divisions, chaque saison.

    ensure_cup_fixtures(conn,season)





def repair_fixture_duplicates(conn):

    """Retire les doublons de championnat : un même club ne peut pas jouer deux fois le même matchday."""

    removed=0

    for column in ("home_club_id","away_club_id"):

        groups=conn.execute(f"SELECT season,matchday,{column} AS ref_club,COUNT(*) n FROM fixture WHERE COALESCE(fixture_type,'championship')='championship' GROUP BY season,matchday,{column} HAVING COUNT(*)>1").fetchall()

        for group in groups:

            members=conn.execute(f"SELECT id,played FROM fixture WHERE season=? AND matchday=? AND {column}=? ORDER BY played DESC,id",

                                 (group["season"],group["matchday"],group["ref_club"])).fetchall()

            for extra in members[1:]:

                if int(extra["played"] or 0):

                    continue

                conn.execute("DELETE FROM fixture WHERE id=?",(int(extra["id"]),))

                removed+=1

    return removed





CUP_MATCHDAY_OFFSET = 100   # les tours de coupe portent le matchday 101, 102…

CUP_ROUND_GAP_DAYS = 21     # un tour toutes les ~3 semaines, hors trève





def fixture_tag(matchday,fixture_type):

    """ETIQUETTE d'un match au calendrier : AMICAL / Jxx / COUPE Rn

    (retour « une coupe en élimination directe entre toutes les divisions »)."""

    ft=str(fixture_type or "championship")

    md=int(matchday or 0)

    if ft=="friendly": return "AMICAL"

    if ft=="cup": return "COUPE R%d"%max(1,md-CUP_MATCHDAY_OFFSET)

    return "J%02d"%md





def _cup_winner_of(fixture_row):

    """Vainqueur d'une confrontation de coupe JOUEE ; égalité -> séance de

    10 m (poids = réputation du club, l'avantage reste mesuré)."""

    ft_uri=str(fixture_row["fixture_type"] or "championship")

    hg,ag=int(fixture_row["home_goals"] or 0),int(fixture_row["away_goals"] or 0)

    if hg>ag: return int(fixture_row["home_club_id"])

    if ag>hg: return int(fixture_row["away_club_id"])

    # Séance de 10 m déjà enregistrée : c'est elle qui décide du qualifié.
    try:
        ph=fixture_row["pen_home"]; pa=fixture_row["pen_away"]
    except (KeyError,IndexError):
        ph=pa=None
    if ph is not None and pa is not None and int(ph)!=int(pa):
        return int(fixture_row["home_club_id"]) if int(ph)>int(pa) else int(fixture_row["away_club_id"])

    hr=int(fixture_row.get("home_rep",30) or 30); ar=int(fixture_row.get("away_rep",30) or 30)

    rng=random.Random(f"cup-shootout|{fixture_row['id']}")

    return int(fixture_row["home_club_id"]) if rng.random()<(hr+35.0)/max(1,hr+ar+70) else int(fixture_row["away_club_id"])





def _cup_round_date(after_iso,gap_days=CUP_ROUND_GAP_DAYS,conn=None):
    """Date du prochain tour : un MERCREDI, `gap_days` après la date fournie,
    en sautant la trêve hivernale ET en gardant au moins 4 jours d'écart avec
    les autres matchs déjà programmés (retour « des matchs tous les 3 jours »)."""
    d=parse_iso(after_iso)+timedelta(days=gap_days)
    while d.weekday()!=2:
        d=d+timedelta(days=1)
    if d.month==12 and d.day>=WINTER_BREAK_START_DAY:
        d=date(d.year+1,1,8)
        while d.weekday()!=2: d=d+timedelta(days=1)
    try:
        own=conn is None
        c=conn if conn is not None else db()
        try:
            for _ in range(8):
                clash=c.execute("""SELECT 1 FROM fixture
                                   WHERE played=0 AND (home_club_id=1 OR away_club_id=1)
                                     AND ABS(julianday(fixture_date)-julianday(?))<4
                                   LIMIT 1""",(d.isoformat(),)).fetchone()
                if not clash: break
                d=d+timedelta(days=7)     # mercredi suivant
        finally:
            if own: c.close()
    except Exception:
        pass
    return d.isoformat()





def cup_slots_for(club_count):
    """Tableau à la puissance de 2 supérieure : 61 clubs -> 64 places."""
    slots=1
    while slots<max(2,int(club_count)): slots*=2
    return slots


CUP_ROUND_NAMES={64:"32es DE FINALE",32:"16es DE FINALE",16:"8es DE FINALE",8:"QUARTS DE FINALE",4:"DEMI-FINALES",2:"FINALE"}
CUP_ROUND_SHORT={64:"32es",32:"16es",16:"8es",8:"1/4",4:"1/2",2:"FINALE"}

# PRIMES DE LA COUPE INTER-LIGUE : versées au club du manager à chaque tour
# franchi, plus un million pour le vainqueur.
CUP_PRIZES={64:15000,32:30000,16:55000,8:100000,4:200000,2:300000}
CUP_WINNER_PRIZE=1000000

# PRIME DE TITRE de championnat, versée dès la fin du dernier match.
CHAMPION_PRIZE={1:1500000,2:500000,3:250000,4:150000,5:80000,6:40000}


def cup_prize_for(teams_at_start,winner=False):
    if winner: return CUP_WINNER_PRIZE
    return int(CUP_PRIZES.get(int(teams_at_start),0))


def cup_round_name(teams_at_start):
    return CUP_ROUND_NAMES.get(int(teams_at_start),f"TOUR À {int(teams_at_start)}")


def cup_round_teams(conn,season,matchday):
    """Nombre de clubs engagés au début du tour (matchday = 100 + index)."""
    row=conn.execute("SELECT value FROM meta WHERE key=?",(f"cup_slots_{int(season)}",)).fetchone()
    slots=int(row["value"] or 0) if row and row["value"] else 0
    if slots<=0:
        n=int(conn.execute("SELECT COUNT(*) n FROM club").fetchone()["n"] or 0)
        slots=cup_slots_for(n)
    r=max(1,int(matchday)-CUP_MATCHDAY_OFFSET)
    teams=max(2,slots//(2**(r-1)))
    return teams


def cup_read_byes(conn,season,round_index):
    import json as _json
    row=conn.execute("SELECT value FROM meta WHERE key=?",(f"cup_byes_{int(season)}",)).fetchone()
    try: data=_json.loads(row["value"] or "{}") if row else {}
    except Exception: data={}
    return [int(x) for x in (data.get(str(int(round_index))) or [])]


def cup_write_byes(conn,season,round_index,ids):
    import json as _json
    key=f"cup_byes_{int(season)}"
    row=conn.execute("SELECT value FROM meta WHERE key=?",(key,)).fetchone()
    try: data=_json.loads(row["value"] or "{}") if row else {}
    except Exception: data={}
    data[str(int(round_index))]=sorted({int(i) for i in ids})
    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES(?,?)",(key,_json.dumps(data)))


def _cup_draw_seed(season,round_index,clubs,stamp):
    """Graine de tirage : change à CHAQUE saison (et à chaque tour), pour ne
    jamais rejouer deux fois le même tableau."""
    mix=sum((i+1)*int(c) for i,c in enumerate(sorted(clubs)))%999983
    return f"cup-draw|{season}|{round_index}|{len(clubs)}|{mix}|{stamp}"


def ensure_cup_fixtures(conn,season,today=None):
    """TIRAGE INITIAL de la COUPE INTER-LIGUE : élimination directe, toutes les
    divisions, tableau à la puissance de 2 supérieure (61 clubs -> 64 places).
    Les clubs les plus réputés sont EXEMPTÉS au 1er tour (3 places avec 61
    clubs) et sont enregistrés comme qualifiés : ils ne disparaissent plus.
    Tirage par pots (gros contre petits) pour un premier tour lisible."""
    have=conn.execute("SELECT COUNT(*) n FROM fixture WHERE season=? AND fixture_type='cup'",(season,)).fetchone()["n"]
    if have: return 0
    clubs=[int(r["id"]) for r in conn.execute("SELECT id FROM club ORDER BY id").fetchall()]
    if len(clubs)<4: return 0
    slots=cup_slots_for(len(clubs))
    bye_count=max(0,slots-len(clubs))
    d=today or conn.execute('SELECT "current_date" FROM career WHERE id=1').fetchone()["current_date"]
    d0=parse_iso(d)
    stamp=_cup_round_date(first_saturday_of_season(d0).isoformat(),gap_days=8,conn=conn)
    if parse_iso(stamp)<d0:
        stamp=_cup_round_date(d,gap_days=10,conn=conn)
    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES(?,?)",(f"cup_slots_{int(season)}",str(slots)))
    # EXEMPTÉS : les plus gros clubs (réputation puis budget).
    # EXEMPTÉS AU HASARD (retour « pas les élites, exemption aléatoire ») :
    # tirage intégral, puis les exemptés sortent du chapeau des matchs.
    order=[int(r["id"]) for r in conn.execute("SELECT id FROM club ORDER BY id").fetchall()]
    rng_byes=random.Random(f"cup-byes|{season}|{stamp}")
    shuffled=list(order); rng_byes.shuffle(shuffled)
    byes=shuffled[:bye_count]
    playing=[c for c in order if c not in byes]
    cup_write_byes(conn,season,1,byes)
    rng=random.Random(_cup_draw_seed(season,1,playing,stamp))
    rng.shuffle(playing)
    half=len(playing)//2
    pot_high=playing[:half]
    pot_low=playing[half:]
    pairs=list(zip(pot_high,pot_low))
    if len(playing)%2:
        pairs.append((playing[-1],byes[0] if byes else playing[-1]))
    inserted=0
    for home_id,away_id in pairs:
        if home_id==away_id: continue
        if rng.random()<.5: home_id,away_id=away_id,home_id
        conn.execute("INSERT INTO fixture(season,matchday,fixture_date,home_club_id,away_club_id,fixture_type) VALUES(?,?,?,?,?,'cup')",
                     (season,CUP_MATCHDAY_OFFSET+1,stamp,home_id,away_id))
        inserted+=1
    if inserted:
        names=", ".join(str(conn.execute("SELECT name FROM club WHERE id=?",(i,)).fetchone()["name"]) for i in byes) if byes else "aucun"
        add_news(conn,"Coupe Inter-Ligue",
                 f"🏆 Tirage de la Coupe Inter-Ligue : {inserted} confrontation(s) directes entre toutes les divisions, le {fmt_date_fr(stamp)}. "
                 f"Exemptés d'entrée (têtes de série) : {names}.")
    return inserted


def ensure_cup_progress(conn,current_date,season=None):
    """AVANCEMENT de la coupe : quand un tour est entièrement joué, le tour
    suivant est tiré depuis les VAINQUEURS + les EXEMPTÉS du tour. Les
    exemptés sont désormais conservés, donc le tableau ne perd plus de clubs."""
    try:
        if season is None:
            season=int(conn.execute("SELECT season FROM club WHERE id=1").fetchone()["season"] or 1)
        rows=conn.execute("""SELECT f.*,hc.name home_name,ac.name away_name,
                                    hc.reputation home_rep,ac.reputation away_rep
                             FROM fixture f JOIN club hc ON hc.id=f.home_club_id
                             JOIN club ac ON ac.id=f.away_club_id
                             WHERE f.season=? AND f.fixture_type='cup' ORDER BY f.matchday,f.id""",(season,)).fetchall()
        if not rows:
            return ensure_cup_fixtures(conn,season,current_date)
        if any(int(r["played"] or 0)==0 for r in rows):
            return 0
        last_round=max(int(r["matchday"] or 0)-CUP_MATCHDAY_OFFSET for r in rows)
        playable=[r for r in rows if int(r["matchday"] or 0)-CUP_MATCHDAY_OFFSET==last_round]
        winners={_cup_winner_of(r) for r in playable}
        winners.update(cup_read_byes(conn,season,last_round))
        winners=sorted(int(w) for w in winners)
        if len(winners)<=1:
            guard=conn.execute("SELECT value FROM meta WHERE key='cup_winner_season'").fetchone()
            if not guard or str(guard["value"])!=str(season):
                if winners:
                    name=conn.execute("SELECT name FROM club WHERE id=?",(winners[0],)).fetchone()
                    nm=name["name"] if name else "Club"
                    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('cup_winner_season',?)",(str(season),))
                    try:
                        import json as _json
                        prow=conn.execute("SELECT value FROM meta WHERE key='cup_palmares'").fetchone()
                        _pal=_json.loads(prow["value"] or "[]") if prow else []
                        if int(season) not in [int(e.get("season",0) or 0) for e in _pal]:
                            _pal.append({"season":int(season),"club":nm,"date":str(current_date)})
                            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('cup_palmares',?)",
                                         (_json.dumps(_pal,ensure_ascii=False),))
                    except Exception:
                        pass
                    add_news(conn,"Coupe Inter-Ligue",f"🏆 {nm} remporte la Coupe Inter-Ligue (saison {season}).")
                    if winners[0]==1:
                        try:
                            conn.execute("UPDATE club SET budget=budget+? WHERE id=1",(CUP_WINNER_PRIZE,))
                            conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",
                                         ("Coupe Inter-Ligue • VICTOIRE FINALE",CUP_WINNER_PRIZE,career_timestamp(conn),"Coupe"))
                        except Exception:
                            pass
                        add_news(conn,"TROPHEE",f"🏆 LA COUPE EST A NOUS ! Trophée de la Coupe Inter-Ligue et {CUP_WINNER_PRIZE:,} €.".replace(","," "))
            return 0
        last_date=max(str(r["fixture_date"]) for r in playable)
        stamp=_cup_round_date(last_date,conn=conn)
        rng=random.Random(_cup_draw_seed(season,last_round+1,winners,stamp))
        rng.shuffle(winners)
        n=0
        for i in range(0,len(winners)-1,2):
            home_id,away_id=int(winners[i]),int(winners[i+1])
            if rng.random()<.5: home_id,away_id=away_id,home_id
            conn.execute("INSERT INTO fixture(season,matchday,fixture_date,home_club_id,away_club_id,fixture_type) VALUES(?,?,?,?,?,'cup')",
                         (season,CUP_MATCHDAY_OFFSET+1+last_round,stamp,home_id,away_id))
            n+=1
        if n:
            teams=cup_round_teams(conn,season,CUP_MATCHDAY_OFFSET+1+last_round)
            add_news(conn,"Coupe Inter-Ligue",f"🏆 Tirage des {cup_round_name(teams)} : {n} confrontation(s) le {fmt_date_fr(stamp)}.")
        return n
    except Exception:
        return 0


def _championship_slot_free(conn,season,date_iso,clubs):

    """Repos de 3 jours minimum entre deux championnats des clubs concernés."""

    for club_id in clubs:

        clash=conn.execute("""SELECT 1 FROM fixture

                              WHERE season=? AND COALESCE(fixture_type,'championship')='championship'

                                AND (home_club_id=? OR away_club_id=?)

                                AND fixture_date<>?

                                AND ABS(julianday(fixture_date)-julianday(?))<3""",

                           (season,club_id,club_id,date_iso,date_iso)).fetchone()

        if clash:

            return False

    return True





def repair_fixture_calendar(conn):

    """Audit du calendrier au démarrage : doublons purgés, journées manquantes reconstruites."""

    try:

        removed=repair_fixture_duplicates(conn)

        season=season_number_for_calendar(conn)

        today=parse_iso(conn.execute('SELECT "current_date" FROM career WHERE id=1').fetchone()["current_date"])

        filled=0

        for division_row in conn.execute("SELECT DISTINCT division FROM club ORDER BY division").fetchall():

            division=int(division_row["division"] or 3)

            expected=build_division_fixtures(conn,season,division,today)

            for md,fixture_date,home,away in expected:

                existing=conn.execute("""SELECT id FROM fixture WHERE season=? AND matchday=? AND

                                         COALESCE(fixture_type,'championship')='championship' AND

                                         (home_club_id IN (?,?) OR away_club_id IN (?,?))""",

                                       (season,md,home,away,home,away)).fetchone()

                if existing:

                    continue

                for extra in range(0,9):

                    cand=(date.fromisoformat(fixture_date)+timedelta(days=7*extra)).isoformat()

                    if _championship_slot_free(conn,season,cand,(home,away)):

                        conn.execute("INSERT INTO fixture(season,matchday,fixture_date,home_club_id,away_club_id,fixture_type) VALUES(?,?,?,?,?,'championship')",

                                     (season,md,cand,home,away))

                        filled+=1

                        break

        if filled or removed:

            conn.commit()

            if filled:

                add_news(conn,"Calendrier réparé",f"{filled} journée(s) manquante(s) ont été replanifiée(s) dans le calendrier.")

        try:

            conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_fixture_md_unique ON fixture(season,matchday,home_club_id) WHERE COALESCE(fixture_type,'championship')='championship'")

        except sqlite3.Error as exc:

            print("idx_fixture_md_unique:",exc)

    except sqlite3.Error as exc:

        print("repair_fixture_calendar:",exc)





def player_level_from_row(p):

    attributes=[int(p[key]) for key in ("technique","passing","finishing","defense","stamina")]

    if p["position"]=="Gardien": attributes.append(int(p["goalkeeper"]))

    return rating20(sum(attributes)/len(attributes))





def player_discipline_text(player):

    """Statut d'indisponibilité en texte : source UNIQUE pour tous les libellés.



    Priorité identique au badge du maillot : suspension d'abord, puis blessure

    (jours restants d'abord, fallback legacy sur les matchs).'' si disponible."""

    try:

        keys=player.keys()

        def field(name):

            value=player[name] if name in keys else 0

            try: return int(value or 0)

            except (TypeError,ValueError): return 0

    except (AttributeError,TypeError):

        def field(name):

            try: return int(player.get(name) or 0)

            except (TypeError,ValueError): return 0

    susp=field("suspension_matches")

    if susp>0:

        return f"SUSPENDU ({susp} match{'s' if susp>1 else ''})"

    # Les indisponibilites de blessure vivent EN JOURS ; les restes 'matchs' sont legacy.

    days=field("injury_days")

    if days>0:

        return f"BLESSÉ (encore {days} j)"

    matches=field("injury_matches")

    if matches>0:

        return f"BLESSÉ ({matches} match{'s' if matches>1 else ''})"

    return ""





def player_status_glyph(player):

    """Indicateur d'indisponibilité affichable : '🟥' suspendu, '🚑' blessé, sinon ''.



    Utilise le même ordre de priorité que player_discipline_text : suspendu d'abord."""

    text=player_discipline_text(player)

    if text.startswith("SUSPENDU"):

        return "🟥"

    if text.startswith("BLESSÉ"):

        return "🚑"

    return ""





def age_decline_deltas(age):

    """Le déclin physique lié à l'âge — l'endurance fond d'abord, les techniques plus tard.



    Retourne un dict attribut -> delta appliqué à chaque anniversaire (deltas négatifs).

    Equilibre la progression : au-delà de 27 ans la hausse d'attributs s'arrête déjà

    (player_potential_from_row), ici la physique commence à décrocher."""

    if age<28:

        return {}

    deltas={"stamina": -2 if age>=30 else -1}

    if age>=32 and age%2==0:

        deltas["technique"]=-1

    if age>=33:

        deltas["passing"]=-1

    if age>=34:

        deltas["defense"]=-1

    return deltas





def clean_message_text(value):
    """Nettoie les anciens messages créés avec des glyphes de police cassés.
    On ne modifie pas la DB utilisateur : le nettoyage se fait au rendu, donc
    même une sauvegarde ancienne redevient lisible immédiatement."""
    text=str(value or "")
    text=text.replace("�\x81", "◆").replace("\x81", "")
    text=text.replace("�", "•")
    return "".join(ch if (ord(ch)>=32 or ch in "\n\t") else " " for ch in text)





def player_salary_monthly(player):

    """Retourne la colonne canonique player.salary, exprimée en €/mois.



    Les contrats, la génération et les sauvegardes utilisent tous salary comme

    montant mensuel ; cette fonction protège l'UI contre NULL/texte des anciennes

    sauvegardes sans jamais substituer une autre colonne (market_value, budget...).

    """

    try:

        return int(float(player["salary"] or 0))

    except (KeyError, TypeError, ValueError):

        return 0





def format_salary_monthly(player, suffix=" / mois"):

    return format_euros(player_salary_monthly(player), suffix)





def training_growth_probability(quality,intensity,weight,age,headroom,prep_factor):

    """Probabilite qu'un attribut progresse de +1 pendant une seance.



    Calibre VISIBLE (les joueurs doivent evoluer sous les yeux du manager) :

    un jeune en croissance gagne ~1 a 2 niveaux/20 par saison, un senior

    progresse encore lentement (~+0.3/saison), quasi-nul pres du potentiel."""

    intensity_mult={"Faible":.80,"Normale":1.00,"Élevée":1.25}.get(intensity,1.0)

    age_mult=1.55 if age<=18 else 1.35 if age<=21 else 1.0 if age<=26 else .70 if age<=29 else .40

    return min(.50,max(0.0,0.062*(quality/100.0)*prep_factor)*intensity_mult*weight*headroom*age_mult)





def player_potential_from_row(player):

    """Potentiel FIXE du joueur : fige une fois pour toutes a sa creation.



    La migration (boot) colle la valeur aux joueurs anciens ; les creations

    (generate_player_roster, process_youth_intakes) stockent la valeur dans

    player.potential_fixed. La grille d'age ne se recalcule donc plus jamais

    avec le niveau courant (le joueur ne 'gonfle' pas son plafond en

    progressant). PAS d'ecriture ici : cette fonction peut etre appelee au

    milieu d'une transaction (ecriture ici = deadlock SQLite).

    """

    stored=row_get(player,"potential_fixed",None)

    if stored is not None:

        return min(20,max(1,int(round(float(stored)))))

    age=int(player["age"]); current=player_level_from_row(player)

    growth=4 if age<19 else 3 if age<23 else 2 if age<27 else 1 if age<31 else 0

    return min(20,current+growth)





DIVISION_LEVEL_NORM={1:15.5,2:14.5,3:13.5,4:12.0,5:10.8,6:9.5}

def contract_demand_years(player):
    """Durée attendue par le joueur : sécurité pour les jeunes (3-4 ans),
    souplesse pour les trentenaires (1 an). Une offre plus longue est acceptée."""
    try: age=int(player["age"] or 25)
    except Exception: age=25
    try: level=player_level_from_row(player)
    except Exception: level=12
    if age<=21: return 4 if level>=16 else 3
    if age<=24: return 3
    if age<=30: return 2
    return 1

def player_salary_demand(player,club):

    level=player_level_from_row(player); salary=int(player["salary"])

    fair=compute_fair_salary(level,max(1,min(6,int(club["division"] or 1))),int(player["age"]),player_potential_from_row(player))

    # ANCRAGE SUR LE SALAIRE JUSTE : un salaire déjà surpayé ne fait plus
    # grimper les exigences (retour « prétentions beaucoup trop élevées »).
    # Plancher : -15 % max par rapport au salaire actuel ; plafond : +35 %
    # au-dessus du salaire juste.
    base=max(int(fair*1.02),int(salary*0.85))
    base=min(base,int(fair*1.35))

    division=max(1,min(6,int(club["division"] or 1)))

    # Surqualification par rapport a la NORME du niveau ou l'on joue : chaque

    # niveau de plus que la moyenne attendue vaut +16 %. PLAFONDS (retour

    # « les contre-propositions atteignent des grosses sommes ») : la taxe

    # s'arrete a 3 niveaux d'ecart et le deficit de reputation compte au

    # plus pour 40 points — la demande ne depasse plus ~1,58x la base.

    excess=min(3.0,max(0.0,float(level)-DIVISION_LEVEL_NORM[division]))

    expected_rep=12+level*4.5

    reputation_gap=min(40,max(0,expected_rep-int(club["reputation"])))

    preference_multiplier=1+excess*0.16+reputation_gap*0.0025

    return round_money(max(base,int(base*preference_multiplier))), (1 if excess>=0.75 else 0)





def row_get(row,key,default=None):

    """Lit une colonne d'une ligne sqlite3 tolérante aux anciens schémas."""

    try:

        return row[key]

    except (IndexError, KeyError):

        return default





def compute_fair_salary(level,division,age=25,potential=None):

    """Salaire mensuel de référence : cohérent avec le niveau, la division et l'âge."""

    division=max(1,min(6,int(division)))

    base=(float(level)**3.1)*0.9*(0.55+(6-division)*0.13)

    if potential is not None and age<=23:

        base+=max(0,int(potential)-int(level))*22

    if age<=20: base*=0.78

    elif age<=23: base*=0.88

    elif age<=30: base*=1.0

    elif age<=32: base*=0.85

    elif age<=34: base*=0.70

    elif age<=36: base*=0.58

    else: base*=0.45

    # PLANCHER PROFESSIONNEL : même un joueur de Ligue 6 ne joue pas pour 400 €
    # par mois — cela évite des masses salariales irréalistes en bas de pyramide.
    return round_money(max(1200,int(base)))





