MARKET_POSITION_FACTOR={"Gardien":0.85,"Défenseur":0.95,"Universel":1.0,"Pivot":1.08,"Ailier":1.12}





def compute_market_value(level,age,potential,position,division,reputation,

                         season_goals=0,season_assists=0,season_saves=0,

                         rating_avg=0.0,rating_count=0,contract_years=2,

                         injury_days=0,is_free_agent=0,futsal_avg=55.0,morale=70):

    """Valeur marchande ESTIMÉE du joueur : une seule formule pour tout le jeu.



    Croix complète niveau × âge/potentiel × poste × performances × contrat ×

    blessure × réputation du club × niveau de la division × qualités futsal × moral.

    """

    division=max(1,min(6,int(division)))

    base=(float(level)**3.55)*3.4

    growth=max(0,int(potential)-int(level))

    age=int(age)

    if age<=20: age_mult=1.05+growth*0.045

    elif age<=23: age_mult=1.08+growth*0.035

    elif age<=27: age_mult=1.0+growth*0.015

    elif age<=30: age_mult=0.94

    elif age<=33: age_mult=0.80

    else: age_mult=max(0.45,0.68-(age-33)*0.05)

    # Prime "pepite" : un jeune a tres haut potentiel est un ACTIF marchand

    # (theoriquement pas a revendre mais le marche le paie plus cher).

    pot_prem=1.0

    if age<=22 and int(potential or 0)>=15:

        pot_prem=1.0+(int(potential)-14)*0.05

    pos_mult=MARKET_POSITION_FACTOR.get(str(position),1.0)

    perf_mult=1.0

    if rating_count>0:

        perf_mult=1.0+(float(rating_avg)-6.5)*0.06

        perf_mult+=min(0.35,int(season_goals)*0.02+int(season_assists)*0.012+int(season_saves)*0.01)

        perf_mult=max(0.85,min(1.30,perf_mult))

    contract_mult=1.0

    if not is_free_agent:

        years=max(0,int(contract_years or 0))

        contract_mult=0.62 if years<=0 else 0.85 if years==1 else 1.0 if years==2 else 1.05 if years==3 else 1.08

    injury_days=int(injury_days or 0)

    injury_mult=0.88 if injury_days>60 else 0.94 if injury_days>30 else 0.97 if injury_days>14 else 1.0

    rep_mult=max(0.75,min(1.45,0.7+int(reputation or 0)*0.009))

    league_mult=1.0+(6-division)*0.18

    futsal_mult=max(0.90,min(1.18,1.0+(float(futsal_avg)-55.0)*0.0045))

    morale_mult=0.96 if int(morale or 0)<40 else 1.02 if int(morale or 0)>85 else 1.0

    value=base*age_mult*pot_prem*pos_mult*perf_mult*contract_mult*injury_mult*rep_mult*league_mult*futsal_mult*morale_mult

    floor=2500 if is_free_agent else 4000

    return round_money(max(floor,min(5_000_000,int(value))))





def compute_market_value_from_row(player,division=3,reputation=20):

    """Applique la formule de valeur à une ligne player de la base."""

    level=player_level_from_row(player)

    potential=player_potential_from_row(player)

    rating_count=int(row_get(player,"season_rating_count",0) or 0)

    rating_avg=(float(row_get(player,"season_rating_sum",0) or 0)/rating_count) if rating_count>0 else 0.0

    try:

        futsal_avg=(float(player["dribble"])+float(player["speed"])+float(player["positioning"]))/3

    except (IndexError, KeyError, TypeError):

        futsal_avg=55.0

    return compute_market_value(level,int(player["age"]),potential,player["position"],division,reputation,

                                row_get(player,"season_goals",0),row_get(player,"season_assists",0),

                                row_get(player,"season_saves",0),rating_avg,rating_count,

                                row_get(player,"contract_years",2),row_get(player,"injury_days",0),

                                int(row_get(player,"is_free_agent",0) or 0),futsal_avg,

                                int(row_get(player,"morale",70) or 70))





def compute_key_player_ids(conn):

    """Les deux joueurs les plus cotés de chaque effectif (prime de dimension sportive)."""

    top={}

    for row in conn.execute("SELECT club_id,market_value,id FROM player WHERE is_free_agent=0 ORDER BY market_value DESC"):

        lst=top.setdefault(int(row["club_id"]),[])

        if len(lst)<2:

            lst.append(int(row["id"]))

    return {pid for lst in top.values() for pid in lst}





def player_ask_price(player,season=1,key_player=False):

    """Prix DEMANDÉ par le club vendeur, distinct de la valeur estimée.



    Non listé : surcote ferme 1.30-1.60 (le club ne veut pas vendre) ;

    listé : 1.08-1.25 ; joueur clé de l'effectif : +20 % ; très long contrat : +8 %.

    Déterministe (même joueur, même saison, même prix) pour rester cohérent entre les vues.

    """

    if int(row_get(player,"is_free_agent",0) or 0):

        return 0

    value=int(row_get(player,"market_value",0) or 0)

    if value<=0:

        return 0

    rng=random.Random(f"ask|{player['id']}|{int(season)}")

    mult=rng.uniform(1.08,1.25) if int(row_get(player,"transfer_listed",0) or 0) else rng.uniform(1.30,1.60)

    if key_player:

        mult*=1.20

    if int(row_get(player,"contract_years",2) or 0)>=4:

        mult*=1.08

    return round_money(int(value*mult))





def mini_bar(v, color="#58bd72"):

    n = max(1, min(10, int(v/10)))

    return f"<span style='color:{color}'>" + ("■" * n) + "</span><span style='color:#3f5147'>" + ("■" * (10-n)) + "</span>"





