def normalize_club_names(conn):

    conn.execute("CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY, value TEXT)")

    universe=conn.execute("SELECT value FROM meta WHERE key='universe_seed'").fetchone()

    if universe and universe["value"]=="six_leagues_v1": return

    done = conn.execute("SELECT value FROM meta WHERE key='club_names_normalized'").fetchone()

    if done and done["value"] == "1":

        return

    rows = conn.execute("SELECT id,name FROM club WHERE id<>1 ORDER BY id").fetchall()

    for i, r in enumerate(rows):

        new_name = REALISTIC_CLUBS[i % len(REALISTIC_CLUBS)]

        conn.execute("UPDATE club SET name=? WHERE id=?", (new_name, r["id"]))

    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('club_names_normalized','1')")





def generate_player_roster(conn,club_id,division,reputation,roster_size=10,quality_delta=0):

    average_by_division={1:77,2:70,3:63,4:56,5:49,6:42}

    base=average_by_division[division]+(reputation-LEAGUE_DEFINITIONS[division-1][4])*.10+quality_delta

    base_positions=["Gardien","Gardien","Défenseur","Défenseur","Ailier","Ailier","Pivot","Pivot","Universel","Universel"]

    positions=(base_positions+(["Défenseur","Ailier","Pivot","Universel"]*3))[:max(10,int(roster_size))]

    many=min(len(PLAYER_FIRST_NAMES)*len(PLAYER_LAST_NAMES),1200)

    name_pairs=[random_player_name() for _ in range(max(10,int(roster_size)))]

    for index,(first,last,nat) in enumerate(name_pairs):

        position=positions[index]; age=random.randint(17,34); ability=random.gauss(base,7.5)

        modifiers={"Gardien":{"technique":-5,"passing":-2,"finishing":-18,"defense":4,"goalkeeper":20,"stamina":0,"dribble":-12,"speed":-2,"positioning":14},

                   "Défenseur":{"technique":-2,"passing":1,"finishing":-8,"defense":14,"goalkeeper":-35,"stamina":5,"dribble":2,"speed":4,"positioning":10},

                   "Ailier":{"technique":10,"passing":5,"finishing":4,"defense":-5,"goalkeeper":-40,"stamina":8,"dribble":14,"speed":14,"positioning":4},

                   "Pivot":{"technique":3,"passing":-2,"finishing":14,"defense":-4,"goalkeeper":-40,"stamina":2,"dribble":10,"speed":-2,"positioning":8},

                   "Universel":{"technique":3,"passing":5,"finishing":2,"defense":2,"goalkeeper":-40,"stamina":5,"dribble":6,"speed":6,"positioning":6}}[position]

        attributes={key:max(15,min(98,int(round(random.gauss(ability+offset,8))))) for key,offset in modifiers.items()}

        probe=dict(attributes); probe["position"]=position

        level=player_level_from_row(probe); potential=player_potential_from_row({**probe,"age":age})

        years=random.randint(1,4)

        salary=compute_fair_salary(level,division,age,potential)

        market_value=compute_market_value(level,age,potential,position,division,reputation,contract_years=years)

        conn.execute("""INSERT INTO player(club_id,first_name,last_name,age,position,technique,passing,finishing,defense,goalkeeper,stamina,condition,morale,nationality,salary,contract_years,market_value,is_free_agent,shirt_number,dribble,speed,positioning,potential_fixed)

                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,?,?,?,?,?)""",

                      (club_id,first,last,age,position,attributes["technique"],attributes["passing"],attributes["finishing"],attributes["defense"],attributes["goalkeeper"],attributes["stamina"],random.randint(72,100),random.randint(54,88),nat,salary,years,market_value,index+1,attributes["dribble"],attributes["speed"],attributes["positioning"],potential))

    # Historique de formation : chaque joueur du monde démarre tracé dans le club qui l'a formé.

    conn.execute("""INSERT INTO player_history(player_id,season,club_id,kind,detail)

                    SELECT p.id,1,p.club_id,'formation','Formation du club' FROM player p

                    WHERE p.club_id=? AND NOT EXISTS(SELECT 1 FROM player_history h WHERE h.player_id=p.id)""",(club_id,))





def generate_free_agents(conn,count):
    """Cree de VRAIS joueurs sans club pour alimenter le marche libre.

    Avant, `ensure_free_agents` liberait des joueurs deja sous contrat : les
    clubs de divisions basses perdaient jusqu'a 10 joueurs et commencaient la
    saison a 1 ou 2 elements. Le vivier est desormais genere en plus des
    effectifs, qui restent complets.
    """
    average_by_division={1:77,2:70,3:63,4:56,5:49,6:42}
    # Jamais le club du manager : un libre garde un club "d'affichage" pour
    # les jointures du marche, mais ne doit pas polluer l'effectif (briefs,
    # comptages, tactique).
    club_rows=[(int(r["id"]),int(r["division"] or 6)) for r in conn.execute("SELECT id,division FROM club WHERE id<>1").fetchall()]
    if not club_rows: return 0
    positions=("Gardien","Défenseur","Ailier","Pivot","Universel")
    weights=(10,26,26,20,18)
    modifiers={"Gardien":{"technique":-5,"passing":-2,"finishing":-18,"defense":4,"goalkeeper":20,"stamina":0,"dribble":-12,"speed":-2,"positioning":14},
               "Défenseur":{"technique":-2,"passing":1,"finishing":-8,"defense":14,"goalkeeper":-35,"stamina":5,"dribble":2,"speed":4,"positioning":10},
               "Ailier":{"technique":10,"passing":5,"finishing":4,"defense":-5,"goalkeeper":-40,"stamina":8,"dribble":14,"speed":14,"positioning":4},
               "Pivot":{"technique":3,"passing":-2,"finishing":14,"defense":-4,"goalkeeper":-40,"stamina":2,"dribble":10,"speed":-2,"positioning":8},
               "Universel":{"technique":3,"passing":5,"finishing":2,"defense":2,"goalkeeper":-40,"stamina":5,"dribble":6,"speed":6,"positioning":6}}
    try:
        _today=str(conn.execute('SELECT "current_date" d FROM career WHERE id=1').fetchone()["d"])
    except Exception:
        _today=date.today().isoformat()
    created=0
    for _ in range(max(0,int(count))):
        division=random.choices((1,2,3,4,5,6),weights=(6,10,16,22,24,22))[0]
        pool=[c for c in club_rows if c[1]==division] or club_rows
        last_club=random.choice(pool)[0]
        position=random.choices(positions,weights=weights)[0]
        age=random.randint(18,35)
        base=average_by_division[division]-2+random.gauss(0,6.5)
        attrs={k:max(15,min(98,int(round(random.gauss(base+off,7))))) for k,off in modifiers[position].items()}
        probe=dict(attrs); probe["position"]=position
        level=player_level_from_row(probe); potential=player_potential_from_row({**probe,"age":age})
        salary=compute_fair_salary(level,division,age,potential)
        value=compute_market_value(level,age,potential,position,division,35,contract_years=0,is_free_agent=1)
        first,last,nat=random_player_name()
        conn.execute("""INSERT INTO player(club_id,first_name,last_name,age,position,technique,passing,finishing,defense,goalkeeper,stamina,condition,morale,nationality,salary,contract_years,market_value,is_free_agent,free_agent_since,shirt_number,dribble,speed,positioning,potential_fixed)
                        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0,?,1,?,0,?,?,?,?)""",
                     (last_club,first,last,age,position,attrs["technique"],attrs["passing"],attrs["finishing"],attrs["defense"],attrs["goalkeeper"],attrs["stamina"],random.randint(70,95),random.randint(55,80),nat,salary,value,_today,attrs["dribble"],attrs["speed"],attrs["positioning"],potential))
        pid=int(conn.execute("SELECT id FROM player ORDER BY id DESC LIMIT 1").fetchone()["id"])
        try: set_birth_date(conn,pid,age,career_year_of(conn))
        except Exception: pass
        try: record_player_history(conn,pid,0,"free_agent","Sans club")
        except Exception: pass
        created+=1
    return created


def build_welcome_report(conn,club_name,division,budget):

    """Message de bienvenue complet : rapport d'effectif chiffré, amicaux de pré-saison et conseils budget.



    Les chiffres sont tirés du VRAI effectif fraîchement généré (club 1) : le rapport reflète

    la carrière qui démarre, pas un texte générique.

    """

    def fr(v):

        return f"{int(round(v)):,}".replace(","," ")

    def note(v):

        return (f"{v:.1f}/20").replace(".",",")

    rows=conn.execute("SELECT first_name,last_name,age,position,salary,contract_years,market_value,technique,passing,finishing,defense,goalkeeper,stamina FROM player WHERE club_id=1").fetchall()

    if not rows:

        return (f"Bienvenue à {club_name} !\n\nVous démarrez en Ligue {division}. Composez votre cinq, planifiez l'entraînement, engagez votre staff et surveillez le mercato.\n\nBonne saison !")

    levels=[player_level_from_row(r) for r in rows]

    avg_level=sum(levels)/len(levels)

    best_lv,best=max(zip(levels,rows),key=lambda t:t[0])

    youngest=min(rows,key=lambda r:int(r["age"])); oldest=max(rows,key=lambda r:int(r["age"]))

    avg_age=sum(int(r["age"]) for r in rows)/len(rows)

    wages=sum(int(r["salary"] or 0) for r in rows)

    value=sum(int(r["market_value"] or 0) for r in rows)

    short_ct=int(sum(1 for r in rows if int(r["contract_years"] or 0)<=1))

    def secteur(pred):

        sel=[lv for lv,r in zip(levels,rows) if pred(r)]

        return (sum(sel)/len(sel)) if sel else 0.0

    gk_def=secteur(lambda r: r["position"] in ("Gardien","Défenseur"))

    att_mid=secteur(lambda r: r["position"] in ("Ailier","Pivot"))

    universel=secteur(lambda r: r["position"]=="Universel")

    if att_mid>=gk_def:

        point_fort,point_faible="le secteur offensif (ailiers/pivots)","le volet défensif (gardiens/défenseurs)"

    else:

        point_fort,point_faible="le volet défensif (gardiens/défenseurs)","le secteur offensif (ailiers/pivots)"

    if division<=1:

        objectif="Objectif du board : décrocher le titre de champion. Les deux derniers seront relégués."

    else:

        objectif=f"Objectif du board : terminer dans les deux premiers pour monter en Ligue {division-1}."

        if division<6:

            objectif+=f" Les deux derniers descendront en Ligue {division+1}."

    pct=wages*100//max(1,budget) if budget else 0

    lignes=[

        f"Bonjour et bienvenue à {club_name} !",

        f"Le board vous confie les clés du club pour cette nouvelle carrière en Ligue {division}. Avant votre premier match, voici notre rapport de pré-saison.",

        "  RAPPORT DE L'EFFECTIF   ",

        f"• {len(rows)} joueurs sous contrat — âge moyen {avg_age:.0f} ans (plus jeune : {youngest['first_name']} {youngest['last_name']}, {youngest['age']} ans • doyen : {oldest['first_name']} {oldest['last_name']}, {oldest['age']} ans).",

        f"• Niveau moyen du groupe : {note(avg_level)}. Meilleur élément : {best['first_name']} {best['last_name']} ({best['position']}, {note(best_lv)}).",

        "• Structure d'effectif : 2 gardiens, 2 défenseurs, 2 ailiers, 2 pivots et 2 joueurs universels — vous pouvez faire tourner sans casser l'équilibre.",

        f"• Notre lecture : {point_fort} constitue votre point fort ; {point_faible} mérite un suivi particulier à l'entraînement."+(f" Le secteur universel tourne autour de {note(universel)}." if universel else ""),

        f"• Valeur marchande totale estimée : {fr(value)} € — masse salariale d'environ {fr(wages)} € par mois.",

        (f"• ⚠ {short_ct} contrat(s) expirent dans un an ou moins : pensez aux prolongations dès la pré-saison, sinon ces joueurs partiront libres." if short_ct else "• Aucun contrat urgent : l'effectif est engagé au moins deux saisons."),

        "  MATCHS AMICAUX DE PRÉ-SAISON   ",

        "La compétition officielle démarre en septembre. D'ici là, la pré-saison (juillet-août) est le moment idéal pour organiser un ou plusieurs matchs amicaux : rendez-vous dans Calendrier, onglet AMICAUX, choisissez une date et un adversaire.",

        "Les amicaux sont précieux pour jauger votre équipe : tester des compositions, mesurer la forme réelle des joueurs, faire le tour du cinq de départ avant l'objectif de la saison. Vous pouvez en programmer jusqu'à 5 cette saison (3 jours de repos minimum entre deux matchs). Les rapports complets (buts, notes, temps forts) arrivent dans votre messagerie après chaque match.",

        "  VIGILANCE BUDGET   ",

        f"Le board met à votre disposition un budget de {fr(budget)} €. La masse salariale mensuelle ({fr(wages)} €) ne doit jamais vous conduire dans le rouge : gardez une réserve pour le mercato, les primes et les imprévus.",

        "Chaque mois s'ajoutent les engagements du staff, les salaires des joueurs et l'entretien de l'infrastructure, pendant que rentrent les revenus (sponsors, billetterie, dotations). Le board surveille la santé financière du club : un budget négatif déclencherait son alerte. Avant tout recrutement, vérifiez que l'indemnité demandée et la couverture d'une année de salaires tiennent dans votre trésorerie, puis surveillez l'équilibre mensuel revenus / masse salariale.",

        "  NOS CONSEILS POUR BIEN DÉMARRER   ",

        "1. Organisez 2 ou 3 amicaux pour jauger le groupe et repérer qui est en forme.",

        "2. Composez votre cinq de départ dans Tactiques (rôles et consignes pèsent sur le match).",

        "3. Planifiez la semaine d'entraînement : dosez l'effort, une charge trop lourde fatigue et blesse.",

        "4. Engagez votre staff (entraîneurs, kiné, recruteurs) : leurs actions débloquent de vrais bonus.",

        "5. Surveillez le mercato et les joueurs libres dans Transferts — un bon renfort peut tout changer.",

        objectif,

        "Bonne saison, Manager. Le club compte sur vous !",

    ]

    diff_row=conn.execute("SELECT value FROM meta WHERE key='difficulty'").fetchone() if "meta" in [t[0] for t in conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()] else None

    diff_key=diff_row[0] if diff_row else "Normal"

    if diff_key=="Facile":

        lignes.append("• Contexte FACILE : le board a sécurisé des moyens au-dessus de la ligue — un effectif expérimenté et un budget renforcé pour démarrer sereinement.")

    elif diff_key=="Difficile":

        lignes.append("• Contexte DIFFICILE : l'effectif est modeste et le budget serré — chaque recrutement et chaque centime comptent. L'objectif du board restera exigé avec réalisme.")

    else:

        lignes.append("• Contexte NORMAL : moyens équilibrés de la ligue — la progression se jouera sur la technicité du mercato et de l'entraînement.")

    return "\n\n".join(lignes)





def seed_new_career_universe(conn,identity,selected_division,is_template=False):

    selected_division=max(1,min(6,int(selected_division)))

    conn.execute("CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT)")

    conn.execute("INSERT INTO career(id,club_id,matchday,current_date) VALUES(1,1,1,'2026-07-01')")

    for division,name,strength,budget,rep_base in LEAGUE_DEFINITIONS:

        conn.execute("INSERT OR IGNORE INTO league(id,name,strength,base_budget) VALUES(?,?,?,?)",(division,name,strength,budget))

    own_def=LEAGUE_DEFINITIONS[selected_division-1]

    difficulty_key=identity.get("difficulty","Normal") or "Normal"

    diff_mod=None

    for mod in DIFFICULTY_MODIFIERS.values():

        if mod["key"]==difficulty_key:

            diff_mod=mod; break

    diff_mod=diff_mod or DIFFICULTY_MODIFIERS[2]

    own_reputation=max(8,int(own_def[4]*.72)+(diff_mod["reputation"] if not is_template else 0))

    own_budget=max(90_000,int(own_def[3]*.75*diff_mod["budget"]))

    conn.execute("INSERT INTO club(id,name,reputation,budget,season,color1,color2,division,kit_pattern,logo_pattern,arena_name) VALUES(1,?,?,?,1,?,?,?,?,?,?)",

                 (identity["name"],own_reputation,own_budget,identity["color1"],identity["color2"],selected_division,identity.get("kit_pattern","vertical"),identity.get("logo_pattern","shield"),identity.get("arena_name","Arena Horizon")))

    clubs=[(1,selected_division,own_reputation)]

    for division,name,strength,budget,rep_base in LEAGUE_DEFINITIONS:

        for slot in range(10):

            if division==selected_division and slot==0: continue

            index=(division-1)*10+slot

            city=CLUB_CITIES[index]

            # Denomination de foot generique inspiree du reel (pas de "VILLE Futsal") :

            # le motif est stable par rang d'univers pour rester reproductible.

            club_name=CLUB_NAME_PATTERNS[(index*7+3)%len(CLUB_NAME_PATTERNS)].format(c=city)

            reputation=max(5,min(100,int(random.gauss(rep_base,6))))

            club_budget=max(120_000,int(budget*random.uniform(.70,1.30)))

            # Couleurs reelles de la ville/club de referencia ; palette neutre sinon.

            color1,color2=CLUB_CITY_COLORS.get(city,NEUTRAL_CITY_PALETTES[index%len(NEUTRAL_CITY_PALETTES)])

            arena_name=ARENA_NAMES[index%len(ARENA_NAMES)]

            cursor=conn.execute("INSERT INTO club(name,reputation,budget,season,color1,color2,division,arena_name) VALUES(?,?,?,1,?,?,?,?)",(club_name,reputation,club_budget,color1,color2,division,arena_name))

            clubs.append((int(cursor.lastrowid),division,reputation))

    database_size=identity.get("database_size","classic")

    roster_size=12

    for club_id,division,reputation in clubs:

        # La difficulte colore UNIQUEMENT le club du joueur : le monde reste

        # identique (ses setSize adversaires, leurs petits rosters, le marche).

        quality_delta=diff_mod["level"] if (club_id==1 and not is_template) else 0

        generate_player_roster(conn,club_id,division,reputation,roster_size,quality_delta)

    free_agent_target={"classic":140,"extended":280,"large":520}.get(database_size,140)

    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('database_size',?)",(database_size,))

    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('free_agent_target',?)",(str(free_agent_target),))
    try:
        generate_free_agents(conn,free_agent_target)
    except Exception:
        pass

    arena_start=max(1,min(8,7-selected_division))

    level_start=max(1,min(8,7-selected_division+own_reputation//55))

    if not is_template:

        arena_start=max(1,min(8,arena_start+diff_mod["facility"]))

        level_start=max(1,min(8,level_start+diff_mod["facility"]))

    conn.execute("INSERT OR IGNORE INTO facility(id,arena_level,medical_level,youth_level,marketing_level) VALUES(1,1,1,1,1)")

    conn.execute("UPDATE facility SET arena_level=?,medical_level=?,youth_level=?,marketing_level=?,lighting_level=?,parking_level=? WHERE id=1",

                 (arena_start,level_start,max(1,level_start-1),level_start,arena_start,arena_start))

    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('universe_seed','six_leagues_v1')")

    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('difficulty',?)",(difficulty_key,))

    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('division_selected',?)",(str(selected_division),))

    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('club_setup_done','1')")

    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('career_created',?)",("0" if is_template else "1",))

    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('club_names_normalized','1')")

    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('free_agents_seeded_v1','1')")

    # Nouvelle carriere : les salaires sont payes chaque mois des le depart.
    # Sans ce marqueur, la migration "prepaid" (pensee pour les anciennes
    # sauvegardes ou les contrats etaient pre-escomptes) exemptait toute
    # l'equipe de masse salariale jusqu'aux prolongations.
    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('payroll_reform_season','1')")

    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('save_slot_name',?)",(identity["name"],))

    add_news(conn,"Bienvenue au club",f"Bienvenue à {identity['name']} ! Votre carrière commence en pré-saison estivale : le rapport complet de l'effectif vous attend dans votre messagerie. Profitez de juillet et août pour préparer l'équipe (amicaux, tactiques, entraînement) avant les premiers matchs de septembre.")

    conn.execute("INSERT INTO manager_message(kind,title,body,created_date,due_date,status,action_data,is_read) VALUES('club_news',?,?,?,?, 'ready','{}',0)",

                 ("Bienvenue au club — Rapport de pré-saison", build_welcome_report(conn,identity["name"],selected_division,own_budget), "2026-07-01", "2026-07-01"))





class ArenaArtwork(QWidget):

    """Static panoramic, locally painted futsal arena for the title screen."""

    def __init__(self,*args,**kwargs):

        super().__init__(*args,**kwargs)

        self.setMinimumSize(430,540)

        self.setSizePolicy(QSizePolicy.Expanding,QSizePolicy.Expanding)



    def paintEvent(self,event):

        p=QPainter(self); p.setRenderHint(QPainter.Antialiasing)

        r=QRectF(self.rect()).adjusted(1,1,-1,-1); w=r.width(); h=r.height()

        bg=QLinearGradient(r.topLeft(),r.bottomRight()); bg.setColorAt(0,QColor("#18213a")); bg.setColorAt(.48,QColor("#10192c")); bg.setColorAt(1,QColor("#07111c"))

        p.setPen(QPen(QColor("#43506b"),1)); p.setBrush(bg); p.drawRoundedRect(r,18,18)

        camera=1

        labels=("DERRIÈRE LE BUT","VUE PANORAMIQUE DES TRIBUNES","AU BORD DU TERRAIN","VUE AÉRIENNE")

        badge=QRectF(r.left()+14,r.top()+12,w-28,30); p.setPen(Qt.NoPen); p.setBrush(QColor(5,10,20,150)); p.drawRoundedRect(badge,8,8)

        p.setPen(QColor("#a9e9d0")); p.setFont(QFont("Segoe UI",8,QFont.Bold)); p.drawText(badge.adjusted(10,0,-8,0),Qt.AlignLeft|Qt.AlignVCenter,"FUTSAL MANAGER 2027  •  SALLE PRINCIPALE")

        p.setPen(QColor("#ddd3ff")); p.drawText(badge.adjusted(8,0,-10,0),Qt.AlignRight|Qt.AlignVCenter,labels[camera])



        # Grandstands, seat rows and roof trusses establish the arena before the pitch.

        p.setPen(QPen(QColor(194,209,237,45),1))

        crowd_top=r.top()+h*.12; crowd_bottom=r.top()+h*.30

        for row in range(4):

            y=crowd_top+row*h*.035

            p.drawLine(QPointF(r.left()+w*.04,y),QPointF(r.right()-w*.04,y))

        stands=QRectF(r.left()+w*.075,r.top()+h*.17,w*.85,h*.19)

        stand_gradient=QLinearGradient(stands.topLeft(),stands.bottomRight()); stand_gradient.setColorAt(0,QColor("#25334b")); stand_gradient.setColorAt(1,QColor("#131e32"))

        p.setPen(QPen(QColor(159,183,216,100),1)); p.setBrush(stand_gradient); p.drawRoundedRect(stands,10,10)

        for row in range(5):

            y=stands.top()+stands.height()*(.20+row*.15)

            p.setPen(QPen(QColor(224,236,249,55),1)); p.drawLine(QPointF(stands.left()+8,y),QPointF(stands.right()-8,y))

            for seat in range(46):

                x=stands.left()+stands.width()*(.025+seat*.021)

                hue=(seat*7+row*13)%65

                p.setPen(Qt.NoPen); p.setBrush(QColor(110+hue,145+hue//2,190+hue//3,190)); p.drawRoundedRect(QRectF(x,y-7,4,6),1,1)

        lower_stands=QRectF(r.left()+w*.12,r.top()+h*.89,w*.76,h*.075)

        p.setPen(QPen(QColor(159,183,216,75),1)); p.setBrush(QColor("#151f32")); p.drawRoundedRect(lower_stands,7,7)

        for row in range(2):

            y=lower_stands.top()+lower_stands.height()*(.35+row*.38)

            for seat in range(40):

                x=lower_stands.left()+lower_stands.width()*(.025+seat*.024)

                p.setPen(Qt.NoPen); p.setBrush(QColor(120+seat%60,150+row*20,194,150)); p.drawEllipse(QPointF(x,y),2,2)

        for x in (.10,.90):

            center=QPointF(r.left()+w*x,r.top()+h*.16); light=QRadialGradient(center,w*.28)

            light.setColorAt(0,QColor(231,244,195,48)); light.setColorAt(1,QColor(231,244,195,0))

            p.setBrush(light); p.drawEllipse(center,w*.28,h*.30)



        views=[

            [QPointF(r.left()+w*.22,r.top()+h*.31),QPointF(r.left()+w*.78,r.top()+h*.31),QPointF(r.right()-w*.02,r.bottom()-h*.04),QPointF(r.left()+w*.02,r.bottom()-h*.04)],

            [QPointF(r.left()+w*.13,r.top()+h*.35),QPointF(r.left()+w*.88,r.top()+h*.32),QPointF(r.right()-w*.08,r.bottom()-h*.08),QPointF(r.left()+w*.08,r.bottom()-h*.08)],

            [QPointF(r.left()+w*.08,r.top()+h*.37),QPointF(r.left()+w*.92,r.top()+h*.37),QPointF(r.right()-w*.02,r.bottom()-h*.05),QPointF(r.left()+w*.02,r.bottom()-h*.05)],

            [QPointF(r.left()+w*.12,r.top()+h*.31),QPointF(r.right()-w*.12,r.top()+h*.31),QPointF(r.right()-w*.12,r.bottom()-h*.08),QPointF(r.left()+w*.12,r.bottom()-h*.08)],

        ]

        court=QPolygonF(views[camera]); turf=QLinearGradient(QPointF(r.left(),r.top()+h*.30),QPointF(r.left(),r.bottom()))

        turf.setColorAt(0,QColor("#24816e")); turf.setColorAt(1,QColor("#0d4846"))

        p.setBrush(turf); p.setPen(QPen(QColor(225,247,236,190),2)); p.drawPolygon(court)

        box=court.boundingRect(); mid_x=box.center().x(); mid_y=box.center().y()

        p.setPen(QPen(QColor(236,250,239,185),2)); p.setBrush(Qt.NoBrush)

        if camera==3:

            p.drawLine(QPointF(mid_x,box.top()),QPointF(mid_x,box.bottom()))

            p.drawEllipse(QPointF(mid_x,mid_y),box.height()*.20,box.height()*.20)

            p.drawRoundedRect(QRectF(box.left(),mid_y-box.height()*.22,box.width()*.17,box.height()*.44),5,5)

            p.drawRoundedRect(QRectF(box.right()-box.width()*.17,mid_y-box.height()*.22,box.width()*.17,box.height()*.44),5,5)

        else:

            # The perceived centre line tilts with the camera angle.

            p.drawLine(QPointF(box.left()+box.width()*.50,box.top()),QPointF(box.left()+box.width()*.50,box.bottom()))

            p.drawEllipse(QPointF(mid_x,mid_y),box.width()*.09,box.height()*.22)

            p.drawRoundedRect(QRectF(box.left(),mid_y-box.height()*.22,box.width()*.17,box.height()*.44),6,6)

            p.drawRoundedRect(QRectF(box.right()-box.width()*.17,mid_y-box.height()*.22,box.width()*.17,box.height()*.44),6,6)

        # Camera 1 has a close goal frame in the foreground; camera 2 peers from a stand.

        if camera==0:

            goal=QRectF(r.left()+w*.28,r.bottom()-h*.22,w*.44,h*.18)

            p.setPen(QPen(QColor(246,251,245,230),max(2,w*.006))); p.setBrush(Qt.NoBrush); p.drawRect(goal)

            p.setPen(QPen(QColor(255,255,255,90),1))

            for x in range(1,7): p.drawLine(QPointF(goal.left()+goal.width()*x/7,goal.top()),QPointF(goal.left()+goal.width()*x/7,goal.bottom()))

            for y in range(1,4): p.drawLine(QPointF(goal.left(),goal.top()+goal.height()*y/4),QPointF(goal.right(),goal.top()+goal.height()*y/4))

        elif camera==1:

            p.setPen(QPen(QColor(229,237,255,115),2))

            for idx in range(5): p.drawLine(QPointF(r.left()+w*.07,r.top()+h*(.38+idx*.045)),QPointF(r.left()+w*.93,r.top()+h*(.38+idx*.045)))

        p.end()





class ResponsivePageStack(QStackedWidget):

    """A page stack that never forces its widest hidden screen onto the layout."""

    def minimumSizeHint(self):

        page=self.currentWidget()

        return QSize(0,page.minimumSizeHint().height() if page else 0)



    def sizeHint(self):

        page=self.currentWidget()

        return QSize(0,page.minimumSizeHint().height() if page else 0)





class ResponsiveScrollContent(QWidget):

    """Size the career scroller from the visible page, not the widest/tallest hidden one."""

    def sizeHint(self):

        layout=self.layout()

        return QSize(0,layout.sizeHint().height() if layout else 0)



    def minimumSizeHint(self):

        layout=self.layout()

        return QSize(0,layout.minimumSize().height() if layout else 0)





def facility_capacity(arena_level,reputation):

    arena=max(1,min(8,int(arena_level))); rep=max(0,int(reputation))

    return max(160,200+(arena-1)*430+rep*8)





def facility_value(facility,key,default=0):

    """Lecture tolérante d'une colonne facility (sqlite3.Row ou dict)."""

    try:

        value=facility[key]

        return default if value is None else value

    except (KeyError,IndexError,TypeError):

        return default





def facility_parking_places(capacity,parking_level=None):

    """Places de stationnement : offre cohérente avec la salle (1 place / 5 spectateurs), plafonnée par le niveau du parking."""

    try: capacity=int(capacity or 0)

    except (TypeError,ValueError): capacity=0

    ideal=max(30,int(round(max(30,capacity/5.0)/10.0))*10)

    if parking_level is None: return ideal

    level=max(1,min(8,int(parking_level)))

    cap=90+(level-1)*88

    return max(30,int(round(min(ideal,cap)/10.0))*10)





def facility_parking_cars(attendance):

    """Véhicules attendus le jour de match : environ 22 % des spectateurs viennent en voiture."""

    try: attendance=int(attendance or 0)

    except (TypeError,ValueError): attendance=0

    return max(0,int(round(attendance*.22)))





def facility_broadcast_revenue(lighting_level,attendance,division):

    """Droits de diffusion : un éclairage homologué ouvre les matchs en nocturne et la retransmission."""

    try: attendance=int(attendance or 0)

    except (TypeError,ValueError): attendance=0

    level=max(1,min(8,int(lighting_level)))

    if level<2 or attendance<=0: return 0

    tier=1.0+max(0,6-max(1,min(6,int(division))))*.12

    return int((level-1)*attendance*.28*tier)





def facility_parking_revenue(parking_level,cars):

    """Recettes de stationnement : une part des véhicules stationnés paye son emplacement."""

    try: cars=int(cars or 0)

    except (TypeError,ValueError): cars=0

    if cars<=0: return 0

    level=max(1,min(8,int(parking_level)))

    return int(cars*(2.0+level*.35))





EXPLOITATION_DEFAULTS={"bar_drink":3,"bar_food":4,"shop_jersey":65,"shop_scarf":15,"shop_cap":20}

def exploitation_config(conn=None):
    """Prix des articles d'exploitation, lus dans meta avec valeurs par defaut."""
    own=False
    if conn is None:
        conn=db(); own=True
    try:
        keys=tuple("exploit_"+k for k in EXPLOITATION_DEFAULTS)
        marks=",".join("?" for _ in keys)
        rows=conn.execute(f"SELECT key,value FROM meta WHERE key IN ({marks})",keys).fetchall()
        found={str(r["key"]):int(float(r["value"] or 0)) for r in rows}
    except Exception:
        found={}
    finally:
        if own:
            try: conn.close()
            except Exception: pass
    def _v(key,lo,hi):
        try: value=int(found.get("exploit_"+key,EXPLOITATION_DEFAULTS[key]))
        except Exception: value=int(EXPLOITATION_DEFAULTS[key])
        return max(lo,min(hi,value))
    return {"bar_drink":_v("bar_drink",1,12),"bar_food":_v("bar_food",1,15),
            "shop_jersey":_v("shop_jersey",25,140),"shop_scarf":_v("shop_scarf",5,40),
            "shop_cap":_v("shop_cap",5,45)}

def exploitation_bar_units(attendance,cfg=None):
    cfg=cfg or exploitation_config()
    att=max(0,int(attendance or 0))
    drink_rate=max(0.25,min(0.80,0.62-0.05*(int(cfg["bar_drink"])-3)))
    food_rate=max(0.10,min(0.55,0.38-0.04*(int(cfg["bar_food"])-4)))
    return {"drink_rate":drink_rate,"food_rate":food_rate,
            "drink_units":int(round(att*drink_rate)),"food_units":int(round(att*food_rate)),
            "drink_revenue":int(round(att*drink_rate*int(cfg["bar_drink"]))),
            "food_revenue":int(round(att*food_rate*int(cfg["bar_food"])))}

def exploitation_shop_units(attendance,cfg=None):
    cfg=cfg or exploitation_config()
    att=max(0,int(attendance or 0))
    jersey_rate=max(0.008,min(0.045,0.020-0.0005*(int(cfg["shop_jersey"])-65)))
    scarf_rate=max(0.015,min(0.080,0.040-0.0015*(int(cfg["shop_scarf"])-15)))
    cap_rate=max(0.012,min(0.060,0.025-0.0015*(int(cfg["shop_cap"])-20)))
    return {"jersey_rate":jersey_rate,"scarf_rate":scarf_rate,"cap_rate":cap_rate,
            "jersey_units":int(round(att*jersey_rate)),"scarf_units":int(round(att*scarf_rate)),
            "cap_units":int(round(att*cap_rate)),
            "jersey_revenue":int(round(att*jersey_rate*int(cfg["shop_jersey"]))),
            "scarf_revenue":int(round(att*scarf_rate*int(cfg["shop_scarf"]))),
            "cap_revenue":int(round(att*cap_rate*int(cfg["shop_cap"])))}

def facility_parking_coverage(capacity,parking_level):

    """Part de la capacité de la salle que le parking peut absorber (1 place pour 5 spectateurs)."""

    try: capacity=int(capacity or 0)

    except (TypeError,ValueError): capacity=0

    if capacity<=0: return 1.0

    return min(1.0,(facility_parking_places(capacity,parking_level)*5.0)/float(capacity))





