def academy_unlocked(conn):

    """Le centre de formation est un investissement MAJEUR : il n'existe pas

    au démarrage du club et doit être ouvert via un gros chèque avant que

    la moindre promotion de jeunes ne soit produite."""

    row=conn.execute("SELECT value FROM meta WHERE key='academy_unlocked'").fetchone()

    return bool(row) and row["value"]=="1"



