def academy_dev_project(conn):
    """Chantier de developpement en cours (un seul a la fois)."""
    row=conn.execute("SELECT value FROM meta WHERE key='academy_dev_project'").fetchone()
    try:
        data=json.loads(row["value"] or "{}") if row else {}
    except Exception:
        data={}
    if not data.get("key"): return None
    try:
        data["key"]=str(data["key"]); data["target"]=int(data.get("target") or 0)
        data["cost"]=int(data.get("cost") or 0)
        data["start"]=str(data.get("start") or ""); data["due"]=str(data.get("due") or "")
    except Exception:
        return None
    return data


def academy_dev_project_active(conn,today=None):
    p=academy_dev_project(conn)
    if not p: return None
    if today is None:
        try: today=conn.execute('SELECT "current_date" FROM career WHERE id=1').fetchone()["current_date"]
        except Exception: today=""
    if p["due"] and str(today)>=str(p["due"]): return None
    return p


def complete_academy_dev_project(conn,today=None):
    """Applique un chantier arrive a echeance (sans commit : au caller)."""
    p=academy_dev_project(conn)
    if not p: return None
    if today is None:
        try: today=conn.execute('SELECT "current_date" FROM career WHERE id=1').fetchone()["current_date"]
        except Exception: today=""
    if not p["due"] or str(today)<str(p["due"]): return None
    key=p["key"]; target=min(3,max(1,int(p["target"])))
    row=conn.execute("SELECT value FROM meta WHERE key=?",(f"academy_dev_{key}",)).fetchone()
    cur=int(row["value"] or 0) if row else 0
    new=max(cur,target)
    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES(?,?)",(f"academy_dev_{key}",str(new)))
    conn.execute("DELETE FROM meta WHERE key='academy_dev_project'")
    defn=ACADEMY_DEV_PROJECTS.get(key) or {}
    label=str(defn.get("label") or key); effect=str(defn.get("effect") or "")
    try:
        add_news(conn,"Centre de formation",f"{label} niveau {new}/3 : chantier terminé. {effect}.")
    except Exception:
        pass
    try:
        queue_manager_message(conn,"club_news",f"Chantier terminé : {label}",
            f"Le chantier du centre de formation est terminé : {label} passe au niveau {new}/3. {effect}",
            str(today),str(today),{},is_read=False)
    except Exception:
        pass
    return {"key":key,"level":new,"label":label}


def academy_dev_levels(conn):
    keys=tuple(ACADEMY_DEV_PROJECTS.keys())
    marks=",".join("?" for _ in keys)
    try:
        rows=conn.execute(f"SELECT key,value FROM meta WHERE key IN ({marks})",
                          tuple("academy_dev_"+k for k in keys)).fetchall()
        found={str(r["key"]):int(r["value"] or 0) for r in rows}
    except Exception:
        found={}
    levels={k:max(0,min(3,found.get("academy_dev_"+k,0))) for k in keys}
    # Un chantier arrive a echeance compte tout de suite, meme avant l'application.
    p=academy_dev_project(conn)
    if p:
        try:
            today=conn.execute('SELECT "current_date" FROM career WHERE id=1').fetchone()["current_date"]
            if p["due"] and str(today)>=str(p["due"]):
                levels[p["key"]]=max(levels.get(p["key"],0),min(3,int(p["target"])))
        except Exception:
            pass
    return levels


def academy_dev_bonus(conn):
    lv=academy_dev_levels(conn)
    growth=(0.05*lv["school"]+0.03*lv["local"]+0.03*lv["foreign"]
            +0.04*lv["edu_technique"]+0.03*lv["edu_mental"]+0.04*lv["edu_physical"])
    detection=2*lv["local"]+4*lv["foreign"]
    return {"levels":lv,"growth":growth,"detection":detection,
            "foreign_level":lv["foreign"],
            "foreign_chance":min(0.75,0.20*lv["foreign"])}


def academy_detection_usage(conn,season=None):
    """Nombre de journées de détection déjà utilisées sur la saison en cours."""
    if season is None:
        try: season=int(conn.execute("SELECT season FROM club WHERE id=1").fetchone()["season"] or 1)
        except Exception: season=1
    season=int(season)
    try:
        srow=conn.execute("SELECT value FROM meta WHERE key='academy_detection_season'").fetchone()
        crow=conn.execute("SELECT value FROM meta WHERE key='academy_detection_count'").fetchone()
        stored=int(srow["value"] or 0) if srow else 0
        used=int(crow["value"] or 0) if crow else 0
    except Exception:
        stored=0; used=0
    if stored!=season: used=0
    return max(0,min(ACADEMY_DETECTION_SEASON_LIMIT,used)),season




def academy_profile(conn):

    """NOTE 0-100 du centre de formation du club.



    Composantes : niveau du centre (poids dominant), pôle médical (corps des

    jeunes protégés), préparateur physique (et son niveau de formation),

    recruteur (détection plus affûtée). La note module la QUALITÉ de la

    promotion annuelle de jeunes mais ne garantit jamais une pépite.

    Centre FERMÉ (non débloqué) : note 0, aucune composante active."""

    try:

        if not academy_unlocked(conn):

            fac=conn.execute("SELECT youth_level,medical_level FROM facility WHERE id=1").fetchone()

            youth=int(fac["youth_level"] or 1) if fac else 1

            medical=int(fac["medical_level"] or 1) if fac else 1

            return {"total":0,"youth_level":youth,"medical_level":medical,

                    "preparateur":False,"preparateur_level":0,

                    "recruteur":False,"centre":0,"medical_score":0,

                    "prep_score":0,"scout_score":0}

        fac=conn.execute("SELECT youth_level,medical_level FROM facility WHERE id=1").fetchone()

        youth=int(fac["youth_level"] or 1); medical=int(fac["medical_level"] or 1)

        metas={row["key"]:(row["value"] or "") for row in conn.execute("SELECT key,value FROM meta WHERE key IN ('preparateur_physique_hired','preparateur_physique_hired_level','scout_staff_hired')").fetchall()}

        prep_hired=bool(metas.get("preparateur_physique_hired")=="1")

        prepareur=int(metas.get("preparateur_physique_hired_level") or 0)

        scout_hired=bool(metas.get("scout_staff_hired")=="1")
        dev=academy_dev_bonus(conn)

    except sqlite3.Error:

        youth,medical,prep_hired,prepareur,scout_hired=1,1,False,0,False

    centre=20+(max(1,min(8,youth))-1)*8.0         # 20 -> 76 : socle du niveau du centre

    medical_score=min(10.0,(max(1,min(8,medical))-1)*1.5)

    prep_score=(8.0+min(7.0,max(0,prepareur-1)*3.5)) if prep_hired else 0.0

    scout_score=6.0 if scout_hired else 0.0

    dev=dev if 'dev' in locals() else {"levels":{}, "growth":0.0, "detection":0, "foreign_level":0}
    dev_score=min(14.0,2.5*int(dev["levels"].get("school",0))+2*int(dev["levels"].get("local",0))
                  +3*int(dev["levels"].get("foreign",0))
                  +1.5*(int(dev["levels"].get("edu_technique",0))+int(dev["levels"].get("edu_mental",0))
                        +int(dev["levels"].get("edu_physical",0))))
    total=max(0.0,min(100.0,centre+medical_score+prep_score+scout_score+dev_score))

    return {"total":int(round(total)),"youth_level":youth,"medical_level":medical,
            "dev_levels":dict(dev["levels"]),"dev_score":int(round(dev_score)),

            "preparateur":prep_hired,"preparateur_level":prepareur if prep_hired else 0,

            "recruteur":scout_hired,"centre":int(centre),"medical_score":int(medical_score),

            "prep_score":int(prep_score),"scout_score":int(scout_score)}



def academy_potential_draw(grade):

    """Potentiel de la promotion : la note du centre décale la loi mais un

    plafond de réussite subsiste — aucune pépite garantie, des déçus toujours

    possibles même dans un centre d'élite."""

    r=random.random()+random.random()*0.04

    p19=0.02+grade*0.0018

    p17=p19+(0.20+grade*0.0030)

    p16=min(p17+(0.15+grade*0.0022),0.94)

    if r<p19: return random.randint(19,20)

    if r<p17: return random.randint(17,18)

    if r<p16: return random.randint(15,16)

    return random.randint(12,15)



def academy_group_size(youth_level):

    """1 a 3 jeunes par saison ; les centres eleves livrent des groupes plus fournis."""

    lvl=max(1,min(8,int(youth_level)))

    if lvl<=2: weights=(0.60,0.30,0.10)

    elif lvl<=4: weights=(0.38,0.40,0.22)

    elif lvl<=6: weights=(0.26,0.42,0.32)

    else: weights=(0.18,0.40,0.42)

    return random.choices((1,2,3),weights=weights)[0]







def _drop_shadow(painter,rect,radius,offset=4,alpha=64):

    painter.setPen(Qt.NoPen); painter.setBrush(QColor(0,0,0,alpha))

    painter.drawRoundedRect(rect.translated(2.0,float(offset)),radius,radius)





def _soft_shadow(painter,rect,radius=10,offset=5,alpha=70,steps=3):

    """Ombre portee ADOUCIE : empilement de contours de plus en plus proches du

    volume (QPainter pur ne floute pas) — halo doux sous hall et entree."""

    painter.setPen(Qt.NoPen)

    for i in range(steps,0,-1):

        spread=float(i)*(4.0/max(1,steps))

        strength=int(alpha*(1.0-(i-1)/float(steps))*0.85)

        if strength<=0: continue

        painter.setBrush(QColor(0,0,0,strength))

        painter.drawRoundedRect(rect.translated(1.0,float(offset)).adjusted(-spread,-spread,spread,spread),radius+spread,radius+spread)





def _volume(painter,rect,height,radius,roof,wall,shadow=True):

    """Bloc vu de dessus avec un léger relief : ombre portée, façade visible, toiture."""

    if shadow: _drop_shadow(painter,rect,radius,offset=height*.45+3,alpha=70)

    painter.setPen(Qt.NoPen); painter.setBrush(wall)

    painter.drawRoundedRect(rect.translated(0.0,float(height)),radius,radius)

    painter.setPen(QPen(roof.lighter(138),1)); painter.setBrush(roof)

    painter.drawRoundedRect(rect,radius,radius)





def _roof_ribs(painter,rect,count,color):

    painter.setPen(QPen(color,1)); left=rect.left()+rect.width()*.06; span=rect.width()*.88

    for i in range(count):

        x=left+span*(i+.5)/count

        painter.drawLine(QPointF(x,rect.top()+rect.height()*.08),QPointF(x,rect.bottom()-rect.height()*.08))





def _tree(painter,x,y,radius):

    """Arbre vu de dessus : houppier en lobes superposés, ombre portée et reflet de lumière."""

    painter.setPen(Qt.NoPen)

    painter.setBrush(QColor(0,0,0,64)); painter.drawEllipse(QPointF(x+radius*.48,y+radius*.52),radius*.98,radius*.90)

    painter.setBrush(QColor("#16391f"))

    for dx,dy,sc in ((-.30,-.16,.58),(.30,-.20,.55),(-.20,.30,.53),(.28,.26,.49),(0,.02,.70)):

        painter.drawEllipse(QPointF(x+radius*dx,y+radius*dy),radius*sc,radius*sc*.97)

    painter.setBrush(QColor("#1f5030"))

    for dx,dy,sc in ((-.20,-.10,.44),(.18,-.14,.40),(-.06,.16,.46),(.10,.06,.30)):

        painter.drawEllipse(QPointF(x+radius*dx,y+radius*dy),radius*sc,radius*sc*.96)

    painter.setBrush(QColor("#2c6b45"))

    for dx,dy,sc in ((-.12,-.08,.26),(.06,-.10,.22),(.14,.10,.20)):

        painter.drawEllipse(QPointF(x+radius*dx,y+radius*dy),radius*sc,radius*sc*.94)

    painter.setBrush(QColor("#478e62"))

    painter.drawEllipse(QPointF(x-radius*.10,y-radius*.14),radius*.13,radius*.12)





def _car(painter,rect,color,horizontal=True,detail=True):

    """Voiture vue de dessus : carrosserie, habitacle vitré, toit, rétroviseurs et phares."""

    r=QRectF(rect).normalized()

    rad=min(r.width(),r.height())*.30

    painter.setPen(Qt.NoPen)

    painter.setBrush(QColor(0,0,0,72)); painter.drawRoundedRect(r.translated(1.2,1.8),rad,rad)

    painter.setBrush(color); painter.drawRoundedRect(r,rad,rad)

    if not detail: return

    glass=QColor(26,36,48,210); roof=color.lighter(124); dark=color.darker(134)

    if horizontal:

        L,W=r.width(),r.height()

        painter.setBrush(dark); painter.drawRoundedRect(QRectF(r.left()+L*.05,r.top()+W*.17,L*.88,W*.66),W*.16,W*.16)

        painter.setBrush(roof); painter.drawRoundedRect(QRectF(r.left()+L*.31,r.top()+W*.20,L*.32,W*.60),W*.15,W*.15)

        painter.setBrush(glass)

        painter.drawRoundedRect(QRectF(r.left()+L*.17,r.top()+W*.21,L*.10,W*.58),W*.10,W*.10)

        painter.drawRoundedRect(QRectF(r.left()+L*.67,r.top()+W*.21,L*.10,W*.58),W*.10,W*.10)

        painter.setBrush(QColor(255,244,206,200))

        painter.drawRect(QRectF(r.left()+L*.945,r.top()+W*.22,L*.045,W*.14))

        painter.drawRect(QRectF(r.left()+L*.945,r.bottom()-W*.36,L*.045,W*.14))

        painter.setBrush(dark)

        painter.drawRect(QRectF(r.left()+L*.31,r.top()-W*.10,L*.05,W*.12))

        painter.drawRect(QRectF(r.left()+L*.31,r.bottom()-W*.02,L*.05,W*.12))

    else:

        L,W=r.height(),r.width()

        painter.setBrush(dark); painter.drawRoundedRect(QRectF(r.left()+W*.17,r.top()+L*.05,W*.66,L*.88),W*.16,W*.16)

        painter.setBrush(roof); painter.drawRoundedRect(QRectF(r.left()+W*.20,r.top()+L*.31,W*.60,L*.32),W*.15,W*.15)

        painter.setBrush(glass)

        painter.drawRoundedRect(QRectF(r.left()+W*.21,r.top()+L*.17,W*.58,L*.10),W*.10,W*.10)

        painter.drawRoundedRect(QRectF(r.left()+W*.21,r.top()+L*.67,W*.58,L*.10),W*.10,W*.10)

        painter.setBrush(QColor(255,244,206,200))

        painter.drawRect(QRectF(r.left()+W*.22,r.top()+L*.945,W*.14,L*.045))

        painter.drawRect(QRectF(r.right()-W*.36,r.top()+L*.945,W*.14,L*.045))

        painter.setBrush(dark)

        painter.drawRect(QRectF(r.left()-W*.10,r.top()+L*.31,W*.12,L*.05))

        painter.drawRect(QRectF(r.right()-W*.02,r.top()+L*.31,W*.12,L*.05))





def _floodlight(painter,x,y,size,glow=True):

    if glow:

        light=QRadialGradient(QPointF(x,y),size*4.6); light.setColorAt(0,QColor(255,246,214,74)); light.setColorAt(.40,QColor(255,246,214,24)); light.setColorAt(1,QColor(255,246,214,0))

        painter.setPen(Qt.NoPen); painter.setBrush(light); painter.drawEllipse(QPointF(x,y),size*4.6,size*4.6)

    painter.setPen(Qt.NoPen); painter.setBrush(QColor(0,0,0,80))

    painter.drawPolygon(QPolygonF([QPointF(x,y),QPointF(x+size*3.6,y+size*1.9),QPointF(x+size*4.0,y+size*2.6),QPointF(x+size*.5,y+size*1.0)]))

    painter.setBrush(QColor("#2b3644")); painter.drawRoundedRect(QRectF(x-size*.7,y-size*.7,size*1.4,size*1.4),2,2)

    painter.setBrush(QColor("#f6e6a8"))

    for dx,dy in ((-.35,-.35),(.35,-.35),(-.35,.35),(.35,.35)):

        painter.drawEllipse(QPointF(x+size*dx,y+size*dy),size*.24,size*.24)





class FacilityArenaView(QWidget):

    """Vue INTÉRIEURE vue de dessus : le terrain de futsal entouré de ses quatre tribunes."""

    def __init__(self,*args,**kwargs):

        super().__init__(*args,**kwargs)

        self.setMinimumHeight(320); self.setSizePolicy(QSizePolicy.Expanding,QSizePolicy.Expanding)

        self.facility={"arena_level":1,"medical_level":1,"youth_level":1,"marketing_level":1,"has_bar":0,"has_vip":0,"has_shop":0,"ticket_price":12}

        self.club={"name":"Futsal Club","color1":"#1f8a4d","color2":"#0f3d27","reputation":30,"division":6}

        self.project=None; self.capacity=None; self.attendance=None



    def set_arena_state(self,facility,club,project=None,capacity=None,attendance=None):

        self.facility=dict(facility); self.club=dict(club); self.project=dict(project) if project else None

        self.capacity=capacity; self.attendance=attendance; self.update()



    def futsal_court_geometry(self,bounds):

        avail_w=max(10.0,bounds.width()*.94); avail_h=max(10.0,bounds.height()*.94)

        court_w=min(avail_w,avail_h*2.0); court_h=court_w/2.0

        return QRectF(bounds.center().x()-court_w/2,bounds.center().y()-court_h/2,court_w,court_h)



    def _tribune(self,painter,rect,row_depth,horizontal,seat_palette,fill,seed,label_base="A",front_at_end=True):

        """Tribune réaliste : gradins, sièges, escaliers d'accès, garde-corps, sections lettrées, vomitoires."""

        if rect.width()<6 or rect.height()<6: return 0

        length=rect.width() if horizontal else rect.height()

        breadth=rect.height() if horizontal else rect.width()

        rows=max(1,min(15,int(breadth/row_depth)))

        depth=breadth/rows

        sections=max(2,min(4,int(length/190)+1))

        stair_w=max(4.0,depth*.95)

        offsets=[length*i/sections for i in range(1,sections)]



        for row in range(rows):

            painter.setPen(Qt.NoPen)

            if horizontal:

                y=rect.top()+depth*row

                painter.setBrush(QColor("#2a3441") if row%2 else QColor("#242e3a"))

                painter.drawRect(QRectF(rect.left(),y,rect.width(),depth))

                painter.setPen(QPen(QColor(0,0,0,95),1)); painter.setBrush(Qt.NoBrush)

                painter.drawLine(QPointF(rect.left(),y+depth),QPointF(rect.right(),y+depth))

                painter.setPen(Qt.NoPen); painter.setBrush(QColor(255,255,255,13))

                painter.drawRect(QRectF(rect.left(),y,rect.width(),1.0))

            else:

                x=rect.left()+depth*row

                painter.setBrush(QColor("#2a3441") if row%2 else QColor("#242e3a"))

                painter.drawRect(QRectF(x,rect.top(),depth,rect.height()))

                painter.setPen(QPen(QColor(0,0,0,95),1)); painter.setBrush(Qt.NoBrush)

                painter.drawLine(QPointF(x+depth,rect.top()),QPointF(x+depth,rect.bottom()))

                painter.setPen(Qt.NoPen); painter.setBrush(QColor(255,255,255,13))

                painter.drawRect(QRectF(x,rect.top(),1.0,rect.height()))



        for off in offsets:

            painter.setPen(Qt.NoPen); painter.setBrush(QColor("#4c5766"))

            painter.setPen(QPen(QColor(0,0,0,70),1))

            if horizontal:

                painter.drawRect(QRectF(rect.left()+off-stair_w*.5,rect.top(),stair_w,rect.height()))

                step=max(4.0,depth); sy=rect.top()+step

                while sy<rect.bottom():

                    painter.drawLine(QPointF(rect.left()+off-stair_w*.5,sy),QPointF(rect.left()+off+stair_w*.5,sy)); sy+=step

            else:

                painter.drawRect(QRectF(rect.left(),rect.top()+off-stair_w*.5,rect.width(),stair_w))

                step=max(4.0,depth); sx=rect.left()+step

                while sx<rect.right():

                    painter.drawLine(QPointF(sx,rect.top()+off-stair_w*.5),QPointF(sx,rect.top()+off+stair_w*.5)); sx+=step



        pitch=max(6.2,depth*1.10); count=max(1,int(length/pitch)); cell=length/count

        seat_w=min(pitch,cell)*.60; seat_h=depth*.46

        painter.setPen(Qt.NoPen)

        for row in range(rows):

            for seat in range(count):

                pos=cell*(seat+.5)

                if any(abs(pos-off)<stair_w*.85 for off in offsets): continue

                if ((seed*977+row*131+seat*17)%1000)/1000.0<fill:

                    painter.setBrush(seat_palette[row%len(seat_palette)])

                else:

                    empty=QColor(seat_palette[row%len(seat_palette)]).darker(168)

                    if empty.lightness()<38: empty=empty.lighter(210)

                    painter.setBrush(empty)

                if horizontal:

                    painter.drawRect(QRectF(rect.left()+pos-seat_w/2,rect.top()+depth*row+depth*.5-seat_h/2,seat_w,seat_h))

                else:

                    painter.drawRect(QRectF(rect.left()+depth*row+depth*.5-seat_h/2,rect.top()+pos-seat_w/2,seat_h,seat_w))



        painter.setPen(QPen(QColor("#9aa7b6"),max(1.0,depth*.16))); painter.setBrush(Qt.NoBrush)

        if horizontal:

            edge=rect.bottom() if front_at_end else rect.top()

            painter.drawLine(QPointF(rect.left(),edge),QPointF(rect.right(),edge))

        else:

            edge=rect.right() if front_at_end else rect.left()

            painter.drawLine(QPointF(edge,rect.top()),QPointF(edge,rect.bottom()))



        painter.setPen(Qt.NoPen); painter.setBrush(QColor("#0d141c"))

        door=max(3.0,stair_w*.9)

        for off in offsets:

            if horizontal:

                back_y=(rect.top()-depth*.30) if front_at_end else (rect.bottom()-depth*.20)

                painter.drawRect(QRectF(rect.left()+off-door/2,back_y,door,max(3.0,depth*.50)))

            else:

                back_x=(rect.left()-depth*.30) if front_at_end else (rect.right()-depth*.20)

                painter.drawRect(QRectF(back_x,rect.top()+off-door/2,max(3.0,depth*.50),door))



        font=QFont("Segoe UI",max(5,int(min(depth*2.4,breadth*.20))),QFont.Bold)

        for s in range(sections):

            center=length*((s+.5)/sections)

            letter=chr(ord(label_base)+s)

            if horizontal:

                pill=QRectF(rect.left()+center-11,rect.top()+rect.height()*.5-8,22,16)

                painter.setPen(Qt.NoPen); painter.setBrush(QColor(10,16,24,205)); painter.drawRoundedRect(pill,4,4)

                painter.setPen(QColor("#c7d2e0")); painter.setFont(font); painter.drawText(pill,Qt.AlignCenter,letter)

            else:

                painter.save(); painter.translate(rect.left()+rect.width()*.5,rect.top()+center); painter.rotate(-90)

                painter.setPen(Qt.NoPen); painter.setBrush(QColor(10,16,24,205)); painter.drawRoundedRect(QRectF(-11,-8,22,16),4,4)

                painter.setPen(QColor("#c7d2e0")); painter.setFont(font); painter.drawText(QRectF(-11,-8,22,16),Qt.AlignCenter,letter); painter.restore()

        return rows



    def _paint_court(self,painter,court):

        painter.setPen(Qt.NoPen)

        stripes=max(6,int(court.width()/max(12.0,court.height()*.30)))

        band=court.width()/stripes

        for i in range(stripes):

            painter.setBrush(QColor("#1d6f52") if i%2 else QColor("#17624a"))

            painter.drawRect(QRectF(court.left()+i*band,court.top(),band+1.0,court.height()))

        line=max(1.1,court.height()*.013)

        painter.setBrush(Qt.NoBrush); painter.setPen(QPen(QColor(236,248,241,195),line))

        painter.drawRect(court)

        cx,cy=court.center().x(),court.center().y()

        painter.drawLine(QPointF(cx,court.top()),QPointF(cx,court.bottom()))

        painter.drawEllipse(QPointF(cx,cy),court.height()*.15,court.height()*.15)

        painter.setPen(Qt.NoPen); painter.setBrush(QColor(236,248,241,205))

        painter.drawEllipse(QPointF(cx,cy),max(2.0,court.height()*.020),max(2.0,court.height()*.020))

        radius=court.height()*.30; goal_half=court.height()*.075

        for left_side in (True,False):

            base=court.left() if left_side else court.right(); sign=1.0 if left_side else -1.0

            path=QPainterPath(); path.moveTo(base,cy-goal_half-radius)

            path.arcTo(QRectF(base-radius,cy-goal_half-radius,2*radius,2*radius),90.0,-90.0 if left_side else 90.0)

            path.lineTo(base+sign*radius,cy+goal_half)

            path.arcTo(QRectF(base-radius,cy+goal_half-radius,2*radius,2*radius),0.0 if left_side else 180.0,-90.0 if left_side else 90.0)

            painter.setPen(QPen(QColor(236,248,241,195),line)); painter.setBrush(Qt.NoBrush)

            painter.drawPath(path)

            painter.setPen(Qt.NoPen); painter.setBrush(QColor(236,248,241,205))

            painter.drawEllipse(QPointF(base+sign*radius,cy),max(1.6,court.height()*.016),max(1.6,court.height()*.016))

            painter.setBrush(QColor(236,248,241,150))

            painter.drawEllipse(QPointF(base+sign*court.height()*.50,cy),max(1.2,court.height()*.013),max(1.2,court.height()*.013))

            painter.setBrush(QColor(236,248,241,30))

            painter.drawRect(QRectF(base-sign*court.height()*.020,cy-goal_half,court.height()*.020,goal_half*2))

            painter.setPen(QPen(QColor("#eef6f1"),max(1.5,court.height()*.022)))

            painter.drawLine(QPointF(base,cy-goal_half),QPointF(base,cy+goal_half))

        corner=court.height()*.07

        painter.setPen(QPen(QColor(236,248,241,195),line)); painter.setBrush(Qt.NoBrush)

        for gx,gy,a0 in ((court.left(),court.bottom(),0.0),(court.right(),court.bottom(),90.0),(court.right(),court.top(),180.0),(court.left(),court.top(),270.0)):

            rad=math.radians(a0)

            path=QPainterPath(); path.moveTo(gx+corner*math.cos(rad),gy-corner*math.sin(rad))

            path.arcTo(QRectF(gx-corner,gy-corner,2*corner,2*corner),a0,90.0); painter.drawPath(path)

        painter.setPen(QPen(QColor(236,248,241,120),line))

        zone=court.width()*.13

        painter.drawLine(QPointF(cx-zone,court.bottom()),QPointF(cx-zone,court.bottom()+court.height()*.035))

        painter.drawLine(QPointF(cx+zone,court.bottom()),QPointF(cx+zone,court.bottom()+court.height()*.035))



    def paintEvent(self,event):

        p=QPainter(self); p.setRenderHint(QPainter.Antialiasing)

        r=QRectF(self.rect()).adjusted(1,1,-1,-1); w=r.width(); h=r.height()

        if w<=10 or h<=10:

            p.end(); return

        arena=max(1,min(8,int(self.facility.get("arena_level",1))))

        club1=QColor(self.club.get("color1") or "#1f8a4d"); club2=QColor(self.club.get("color2") or "#0f3d27")

        def _tone(color,keep=0.40):
            base=QColor("#111a26")
            return QColor(int(color.red()*keep+base.red()*(1-keep)),int(color.green()*keep+base.green()*(1-keep)),int(color.blue()*keep+base.blue()*(1-keep)))

        club1_soft=_tone(club1,0.42)

        project=self.project or {}; pk=project.get("facility_key","")

        capacity=self.capacity

        if capacity is None:

            try: capacity=int(facility_capacity(arena,int(self.club.get("reputation",30))))

            except Exception: capacity=2400+arena*1500

        fill=.5 if not self.attendance or not capacity else max(.03,min(1.0,self.attendance/float(max(1,capacity))))



        p.setPen(Qt.NoPen); p.setBrush(QColor("#070c12")); p.drawRoundedRect(r,12,12)

        halo=QRadialGradient(r.center(),max(w,h)*.52); halo.setColorAt(0,QColor(255,255,255,22)); halo.setColorAt(1,QColor(255,255,255,0))

        p.setBrush(halo); p.drawRoundedRect(r,12,12)



        scale=min(.92,.70+(arena-1)*.028)

        # Proportions FIXES : l'arena garde un ratio de salle (8:5) quelle que

        # soit la fenetre ou l'ecran — plus de hall/tribunes etires ni de

        # terrain ecrase sur un affichage large ou eleve. L'echelle est HAUTE

        # (la salle occupe l'essentiel du cadre, meme au niveau 1) : plus de

        # grand vide noir autour du hall.

        hall_ar=8.0/5.0

        availw=w*.96; availh=h*.82

        if availw/availh>hall_ar:

            boxw=availh*hall_ar; boxh=availh

        else:

            boxw=availw; boxh=availw/hall_ar

        bw=boxw*scale; bh=boxh*scale

        hall=QRectF(r.center().x()-bw/2,r.center().y()-bh/2,bw,bh)

        _drop_shadow(p,hall,18,offset=7,alpha=95)

        p.setPen(QPen(QColor("#22303f"),1)); p.setBrush(QColor("#0e151e")); p.drawRoundedRect(hall.adjusted(-7,-7,7,7),18,18)

        p.setPen(QPen(QColor("#31404f"),1)); p.setBrush(QColor("#1c2632")); p.drawRoundedRect(hall,15,15)



        wall=max(4.0,min(bw,bh)*.018)

        inner=hall.adjusted(wall,wall,-wall,-wall)

        row_depth=max(6.4,inner.height()*.037)

        couloir=max(6.4,inner.height()*.052)

        end_space=row_depth*max(2,min(4,arena))

        court=self.futsal_court_geometry(inner.adjusted(couloir+end_space,couloir+end_space,-(couloir+end_space),-(couloir+end_space)))

        left_rect=QRectF(inner.left(),inner.top(),max(0.0,court.left()-couloir-inner.left()),inner.height())

        right_rect=QRectF(court.right()+couloir,inner.top(),max(0.0,inner.right()-(court.right()+couloir)),inner.height())

        top_rect=QRectF(left_rect.right(),inner.top(),max(0.0,right_rect.left()-left_rect.right()),max(0.0,court.top()-couloir-inner.top()))

        bottom_rect=QRectF(left_rect.right(),court.bottom()+couloir,max(0.0,right_rect.left()-left_rect.right()),max(0.0,inner.bottom()-(court.bottom()+couloir)))



        p.setPen(Qt.NoPen); p.setBrush(QColor("#1f2937")); p.drawRoundedRect(inner,12,12)

        couloir_rect=QRectF(court.left()-couloir,court.top()-couloir,court.width()+2*couloir,court.height()+2*couloir)

        p.setPen(QPen(QColor("#4a5665"),1)); p.setBrush(QColor("#3d4854")); p.drawRoundedRect(couloir_rect,7,7)

        p.setPen(Qt.NoPen); p.setBrush(QColor("#333d49")); p.drawRect(couloir_rect.adjusted(2,2,-2,-2))



        seat_palette=[club1_soft.lighter(112),club1_soft.lighter(102)]

        p.setRenderHint(QPainter.Antialiasing,False)

        rows_end=self._tribune(p,top_rect,row_depth,True,seat_palette,fill,1,"A",True)

        rows_end=max(rows_end,self._tribune(p,bottom_rect,row_depth,True,seat_palette,fill,2,"D",False))

        if arena>2:

            rows_side=self._tribune(p,left_rect,row_depth,False,seat_palette,fill,3,"G",True)

            rows_side=max(rows_side,self._tribune(p,right_rect,row_depth,False,seat_palette,fill,4,"J",False))

        else:

            rows_side=0

            for rect in (left_rect,right_rect):

                p.setPen(QPen(QColor("#2c3846"),1)); p.setBrush(QColor("#232d39")); p.drawRect(rect)

                p.setPen(QPen(QColor(255,255,255,16),1))

                step=max(8.0,rect.height()*.10); y=rect.top()+step

                while y<rect.bottom():

                    p.drawLine(QPointF(rect.left()+2,y),QPointF(rect.right()-2,y)); y+=step

        p.setRenderHint(QPainter.Antialiasing,True)



        p.setPen(Qt.NoPen)

        # Bandes LED sur les QUATRE côtés du terrain (tunnel central préservé en bas).

        led_h=max(2.4,couloir*.30)

        segments=max(6,int(court.width()/max(26.0,court.height()*.55)))

        led_w=court.width()/segments

        tunnel_half=court.width()*.075/1.0*1.25

        for i in range(segments):

            seg=QRectF(court.left()+i*led_w,court.bottom()+couloir*.06,led_w-1.0,led_h)

            center_x=(seg.left()+seg.right())/2

            if abs(center_x-court.center().x())<tunnel_half: continue  # place du tunnel

            p.setBrush(club1_soft if i%2 else QColor("#c9d3df")); p.drawRect(seg)

            p.setBrush(club1_soft if (i+1)%2 else QColor("#c9d3df"))

            p.drawRect(QRectF(seg.left(),court.top()-(couloir*.06+led_h),led_w-1.0,led_h))

        v_segments=max(4,int(court.height()/max(26.0,court.height()*.42)))

        v_seg_h=court.height()/v_segments

        for i in range(v_segments):

            p.setBrush(club1_soft if i%2 else QColor("#c9d3df"))

            p.drawRect(QRectF(court.left()-(couloir*.38+led_h*.5),court.top()+i*v_seg_h,led_h,v_seg_h-1.0))

            p.setBrush(club1_soft if (i+1)%2 else QColor("#c9d3df"))

            p.drawRect(QRectF(court.right()+couloir*.38-led_h*.5,court.top()+i*v_seg_h,led_h,v_seg_h-1.0))



        _drop_shadow(p,court,10,offset=4,alpha=80)
        self._paint_court(p,court)
        # Structure de toit : poutres légères et luminaires suspendus
        p.setPen(QPen(QColor(255,255,255,16),max(1.0,h*.002)))
        for k in range(1,4):
            yy=inner.top()+inner.height()*k/4.0
            p.drawLine(QPointF(inner.left()+wall,yy),QPointF(inner.right()-wall,yy))
        p.setPen(Qt.NoPen)
        for i in range(7):
            lx=court.left()+court.width()*(i+0.5)/7.0
            p.setBrush(QColor(255,248,220,235)); p.drawRoundedRect(QRectF(lx-3,inner.top()+wall*1.6,6,2),1,1)
            glow=QRadialGradient(QPointF(lx,inner.top()+wall*2.0),court.width()*.05)
            glow.setColorAt(0,QColor(255,244,214,36)); glow.setColorAt(1,QColor(255,244,214,0))
            p.setBrush(glow); p.drawEllipse(QPointF(lx,inner.top()+wall*2.4),court.width()*.05,court.width()*.05)

        p.setPen(QPen(club1_soft,max(1.3,court.height()*.011))); p.setBrush(Qt.NoBrush)

        p.drawEllipse(court.center(),court.height()*.075,court.height()*.075)



        shade_top=QLinearGradient(QPointF(0,court.top()),QPointF(0,court.top()+court.height()*.15))

        shade_top.setColorAt(0,QColor(0,0,0,92)); shade_top.setColorAt(1,QColor(0,0,0,0))

        p.setPen(Qt.NoPen); p.setBrush(shade_top); p.drawRect(QRectF(court.left(),court.top(),court.width(),court.height()*.15))

        shade_left=QLinearGradient(QPointF(court.left(),0),QPointF(court.left()+court.width()*.05,0))

        shade_left.setColorAt(0,QColor(0,0,0,64)); shade_left.setColorAt(1,QColor(0,0,0,0))

        p.setBrush(shade_left); p.drawRect(QRectF(court.left(),court.top(),court.width()*.05,court.height()))



        # Halo de plafond : lumiere diffuse dans l'axe du terrain (additive).

        ceiling=QRadialGradient(court.center(),court.width()*.60)

        ceiling.setColorAt(0,QColor(255,250,235,30)); ceiling.setColorAt(1,QColor(255,250,235,0))

        p.setCompositionMode(QPainter.CompositionMode_Plus)

        p.setPen(Qt.NoPen); p.setBrush(ceiling)

        p.drawEllipse(court.center(),court.width()*.60,court.width()*.60)

        p.setCompositionMode(QPainter.CompositionMode_SourceOver)



        # Loge VIP : bandeau dore integre a la tribune laterale droite quand la loge existe.

        if int(self.facility.get("has_vip",0) or 0) and right_rect.width()>26 and right_rect.height()>40:

            vip_h=max(12.0,right_rect.height()*.18)

            vip_w=max(10.0,right_rect.width()*.72)

            vip=QRectF(right_rect.left()+1.5,right_rect.top()+right_rect.height()*.24,vip_w,vip_h)

            gold=QLinearGradient(vip.topLeft(),vip.bottomLeft())

            gold.setColorAt(0,QColor(240,206,131,70)); gold.setColorAt(1,QColor(90,68,30,105))

            p.setPen(QPen(QColor(240,206,131,200),1.0)); p.setBrush(gold); p.drawRoundedRect(vip,5,5)

            p.setPen(QPen(QColor(255,230,168,120),1.0))

            p.drawLine(QPointF(vip.left()+2,vip.bottom()-2),QPointF(vip.right()-2,vip.bottom()-2))

            p.setPen(QColor("#ffe6a8")); p.setFont(QFont("Segoe UI",max(4,int(vip.height()*.62)),QFont.Bold))

            p.drawText(vip,Qt.AlignCenter,"VIP")



        bench_h=max(3.6,couloir*.50); bench_y=court.bottom()+couloir*.30

        p.setPen(Qt.NoPen); p.setBrush(club2.lighter(155))

        p.drawRoundedRect(QRectF(court.left()+court.width()*.20,bench_y,court.width()*.24,bench_h),2,2)

        p.setBrush(club1.darker(135))

        p.drawRoundedRect(QRectF(court.right()-court.width()*.44,bench_y,court.width()*.24,bench_h),2,2)

        p.setBrush(QColor("#e8eef6"))

        for i in range(6):

            p.drawRect(QRectF(court.left()+court.width()*.215+i*court.width()*.037,bench_y+bench_h*.22,court.width()*.020,bench_h*.40))

            p.drawRect(QRectF(court.right()-court.width()*.425+i*court.width()*.037,bench_y+bench_h*.22,court.width()*.020,bench_h*.40))

        table=QRectF(court.center().x()-court.width()*.085,bench_y,court.width()*.17,bench_h)

        p.setBrush(QColor("#111a24")); p.setPen(QPen(QColor("#46536a"),1)); p.drawRoundedRect(table,3,3)

        p.setPen(Qt.NoPen); p.setBrush(QColor("#6ad398")); p.drawRect(table.adjusted(table.width()*.16,table.height()*.26,-table.width()*.16,-table.height()*.26))

        tun_w=max(6.0,court.width()*.075)

        tunnel=QRectF(court.center().x()-tun_w/2,court.bottom()+couloir*.05,tun_w,max(6.0,inner.bottom()-court.bottom()-couloir*.05))

        p.setPen(Qt.NoPen); p.setBrush(QColor("#4d5a6a")); p.drawRect(tunnel)

        p.setBrush(QColor("#697789")); p.drawRect(QRectF(tunnel.left(),tunnel.top(),tunnel.width(),max(1.4,tunnel.height()*.10)))

        p.setPen(QPen(QColor("#7b8899"),max(1.0,couloir*.10))); p.setBrush(Qt.NoBrush)

        p.drawLine(QPointF(tunnel.left(),tunnel.top()),QPointF(tunnel.left(),tunnel.bottom()))

        p.drawLine(QPointF(tunnel.right(),tunnel.top()),QPointF(tunnel.right(),tunnel.bottom()))

        door_w=tunnel.width()*.72

        door_h=max(4.0,tunnel.height()*.26)

        p.setPen(Qt.NoPen); p.setBrush(QColor("#0a1017"))

        p.drawRect(QRectF(tunnel.center().x()-door_w/2,tunnel.bottom()-door_h,door_w,door_h))



        p.setPen(QColor("#9fb0c4")); p.setFont(QFont("Segoe UI",max(6,int(min(h*.030,13))),QFont.Bold))

        label=f"TRIBUNES  •  NIVEAU {arena}/8  •  {rows_end} RANGÉES DERRIÈRE LES BUTS"

        if rows_side: label+=f"  •  {rows_side} SUR LES CÔTÉS"

        # Legende centree dans la zone libre (ni le nom du club a gauche, ni la ligue a droite).

        cap_y=max(r.top()+h*.034,hall.top()-h*.072)

        p.drawText(QRectF(w*.27,cap_y,w*.46,h*.048),Qt.AlignHCenter|Qt.AlignBottom,

                   p.fontMetrics().elidedText(label,Qt.ElideMiddle,int(w*.44)))

        p.setPen(QColor("#7e8ca0")); p.setFont(QFont("Segoe UI",max(5,int(min(h*.025,11))),QFont.Bold))

        p.drawText(QRectF(hall.left()-w*.05,hall.bottom()+h*.012,hall.width()+w*.10,h*.04),Qt.AlignHCenter|Qt.AlignTop,

                   f"TERRAIN 40 × 20 M   •   {capacity:,} PLACES   •   {int(round(fill*100))} % DE REMPLISSAGE".replace(","," "))

        p.setPen(QColor("#eef3f9")); p.setFont(QFont("Segoe UI",max(7,int(min(h*.042,w*.013,17))),QFont.Bold))

        p.drawText(QRectF(r.left()+w*.03,r.top()+h*.035,w*.5,h*.07),Qt.AlignVCenter|Qt.AlignLeft,

                   p.fontMetrics().elidedText(str(self.club.get("name","FUTSAL CLUB")).upper(),Qt.ElideRight,int(w*.46)))

        p.setPen(QColor("#7e8ca0")); p.setFont(QFont("Segoe UI",max(6,int(min(h*.03,w*.010,10))),QFont.Bold))

        p.drawText(QRectF(r.right()-w*.33,r.top()+h*.035,w*.30,h*.07),Qt.AlignVCenter|Qt.AlignRight,f"LIGUE {self.club.get('division',6)}  •  VUE INTÉRIEURE")

        # ---------- AMBIANCE : projecteurs, vignette, tableau de score ----------
        p.setCompositionMode(QPainter.CompositionMode_Plus)
        for cx,cy in ((court.left(),court.top()),(court.right(),court.top()),
                      (court.left(),court.bottom()),(court.right(),court.bottom())):
            glow=QRadialGradient(QPointF(cx,cy),court.width()*.20)
            glow.setColorAt(0,QColor(255,242,206,52)); glow.setColorAt(1,QColor(255,242,206,0))
            p.setPen(Qt.NoPen); p.setBrush(glow)
            p.drawEllipse(QPointF(cx,cy),court.width()*.20,court.width()*.20)
        p.setCompositionMode(QPainter.CompositionMode_SourceOver)
        vig=QRadialGradient(hall.center(),max(hall.width(),hall.height())*.74)
        vig.setColorAt(0.58,QColor(0,0,0,0)); vig.setColorAt(1,QColor(0,0,0,125))
        p.setPen(Qt.NoPen); p.setBrush(vig); p.drawRoundedRect(hall.adjusted(-3,-3,3,3),15,15)
        sb_w=min(court.width()*.36,270); sb_h=max(15.0,sb_w*.20)
        sb=QRectF(court.center().x()-sb_w/2, inner.top()+wall+3, sb_w, sb_h)
        if sb.height()>=13 and sb.top()>inner.top()+4:
            p.setPen(QPen(QColor("#0a1018"),1)); p.setBrush(QColor("#0f1925")); p.drawRoundedRect(sb,6,6)
            p.setPen(Qt.NoPen); p.setBrush(club1_soft); p.drawRoundedRect(QRectF(sb.left()+5,sb.top()+4,sb.width()*.22,sb.height()-8),3,3)
            p.setBrush(QColor("#e8eef6")); p.drawRoundedRect(QRectF(sb.right()-5-sb.width()*.10,sb.top()+4,sb.width()*.10,sb.height()-8),3,3)
            p.setBrush(club2.lighter(150)); p.drawRect(QRectF(sb.center().x()-1,sb.top()+3,2,sb.height()-6))
            p.setPen(QColor("#eaf2ff")); p.setFont(QFont("Segoe UI",max(5,int(sb.height()*.38)),QFont.Bold))
            p.drawText(sb,Qt.AlignCenter,f"{int(self.attendance or 0):,} / {capacity:,}".replace(","," "))
        if inner.bottom()-couloir > court.bottom():
            lab=QRectF(court.center().x()-court.width()*.09,inner.bottom()-couloir*.82,court.width()*.18,couloir*.6)
            p.setPen(QColor("#8fa2b8")); p.setFont(QFont("Segoe UI",max(4,int(lab.height()*.7)),QFont.Bold))
            p.drawText(lab,Qt.AlignCenter,"TUNNEL")

        # ---------- CHANTIER : simple contour, le détail vit dans le panneau latéral ----------
        if self.project:
            tape=QPen(QColor(242,193,78,190),max(1.6,h*.0045),Qt.DashLine)
            p.setPen(tape); p.setBrush(Qt.NoBrush); p.drawRoundedRect(hall.adjusted(3,3,-3,-3),14,14)

        p.end()





class FacilityCampusView(QWidget):
    """Vue EXTÉRIEURE 2.5D du campus : bâtiments illustrés, allées, parking,
    terrain d'entraînement, rivière et tous les équipements construits."""

    DESIGN_W = 1200
    DESIGN_H = 640

    def __init__(self,*args,**kwargs):
        super().__init__(*args,**kwargs)
        self.setMinimumHeight(340)
        self.setSizePolicy(QSizePolicy.Expanding,QSizePolicy.Expanding)
        self.facility={"arena_level":1,"medical_level":1,"youth_level":1,"marketing_level":1,
                       "lighting_level":1,"parking_level":1,"has_bar":0,"has_vip":0,"has_shop":0,
                       "has_fan_zone":0,"video_level":0,"volunteer_level":0,"restaurant_level":0,
                       "ticket_price":12}
        self.club={"name":"Futsal Club","arena_name":"Salle principale","color1":"#1f8a4d",
                   "color2":"#0f3d27","reputation":30,"division":6}
        self.project=None; self.capacity=None; self.attendance=None; self.night=False

    def set_arena_state(self,facility,club,project=None,capacity=None,attendance=None):
        self.facility=dict(facility or {})
        self.club=dict(club or {})
        self.project=dict(project) if project else None
        self.capacity=capacity; self.attendance=attendance
        self.update()

    def set_night_mode(self,value):
        """Compatibilité : la vue reste une scène de jour illustrée."""
        self.night=bool(value); self.update()

    def lighting_available(self):
        try: return int(self.facility.get("lighting_level",1) or 1)>=2
        except (TypeError,ValueError): return False

    def _int(self,key,default=0):
        try: return int(self.facility.get(key,default) or default)
        except (TypeError,ValueError): return default

    def paintEvent(self,event):
        p=QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        w=self.width(); h=self.height()
        p.fillRect(self.rect(),QColor("#07100c"))
        if w<=20 or h<=20:
            p.end(); return
        scale=min(w/self.DESIGN_W,h/self.DESIGN_H)
        ox=(w-self.DESIGN_W*scale)/2.0; oy=(h-self.DESIGN_H*scale)/2.0
        p.translate(ox,oy); p.scale(scale,scale)
        clip=QPainterPath(); clip.addRoundedRect(QRectF(0,0,self.DESIGN_W,self.DESIGN_H),20,20)
        p.setClipPath(clip)

        arena=max(1,min(8,self._int("arena_level",1)))
        med=max(1,min(8,self._int("medical_level",1)))
        youth=max(1,min(8,self._int("youth_level",1)))
        marketing=max(1,min(8,self._int("marketing_level",1)))
        lighting=max(1,min(8,self._int("lighting_level",1)))
        parking=max(1,min(8,self._int("parking_level",1)))
        video=max(0,min(3,self._int("video_level",0)))
        volunteers=max(0,min(3,self._int("volunteer_level",0)))
        restaurant=max(0,min(3,self._int("restaurant_level",0)))
        has_bar=bool(self._int("has_bar",0)); has_vip=bool(self._int("has_vip",0))
        has_shop=bool(self._int("has_shop",0)); has_fan=bool(self._int("has_fan_zone",0))

        club1=QColor(self.club.get("color1") or "#1f8a4d")
        club2=QColor(self.club.get("color2") or "#0f3d27")
        def rgba(color,alpha):
            c=QColor(color); c.setAlpha(alpha); return c
        def mix(color,other,t):
            return QColor(int(color.red()*(1-t)+other.red()*t),
                          int(color.green()*(1-t)+other.green()*t),
                          int(color.blue()*(1-t)+other.blue()*t))
        dark=QColor("#0b1118"); text=QColor("#eaf3fb"); muted=QColor("#a7b8ca")
        gold=QColor("#e2bf7a"); glass1=QColor("#bfe4f7"); glass2=QColor("#4f7e9c")
        capacity=self.capacity
        if capacity is None:
            try: capacity=int(facility_capacity(arena,int(self.club.get("reputation",30))))
            except Exception: capacity=2400+arena*1500
        attendance=self.attendance

        # ------------------------------------------------------------ helpers
        def shadow(rect,spread=10,alpha=70,radius=12,dy=8):
            for i,a in ((spread,alpha*0.35),(spread*0.62,alpha*0.55),(spread*0.30,alpha)):
                p.setPen(Qt.NoPen); p.setBrush(QColor(0,0,0,int(max(0,a))))
                p.drawRoundedRect(rect.adjusted(-i,-i*0.55,i,i*0.55).translated(0,dy),radius,radius)

        def surface(rect,top,bottom,radius=10,angle=None):
            g=QLinearGradient(rect.topLeft(),rect.bottomRight()) if angle is None else angle
            g.setColorAt(0,top); g.setColorAt(1,bottom)
            p.setPen(Qt.NoPen); p.setBrush(g); p.drawRoundedRect(rect,radius,radius)

        def pips(cx,cy,level,total,accent,width=44):
            seg=max(3.5,(width-3*(total-1))/total)
            x0=cx-width/2
            for i in range(total):
                p.setPen(Qt.NoPen)
                p.setBrush(QColor(accent) if i<level else QColor(255,255,255,34))
                p.drawRoundedRect(QRectF(x0+i*(seg+3),cy,seg,3.4),1.7,1.7)

        label_queue=[]
        def chip(cx,cy,label,accent,level=None,total=8,maxw=210,defer=True):
            # Les libellés sont empilés puis dessinés en dernier : aucun bâtiment
            # ne peut plus les recouvrir.
            if defer:
                label_queue.append((cx,cy,label,accent,level,total,maxw)); return
            f=QFont("Segoe UI",8,QFont.Bold); f.setPixelSize(13); p.setFont(f)
            fm=p.fontMetrics(); txt=fm.elidedText(str(label).upper(),Qt.ElideRight,int(maxw-27))
            tw=fm.horizontalAdvance(txt); cw=max(54,min(maxw,tw+24+(44 if level is not None else 0))); ch=23
            rect=QRectF(cx-cw/2,cy,cw,ch)
            p.setPen(QPen(QColor(255,255,255,30),1)); p.setBrush(QColor(7,13,20,228)); p.drawRoundedRect(rect,6,6)
            p.setPen(Qt.NoPen); p.setBrush(accent); p.drawRoundedRect(QRectF(rect.left()+1,rect.top()+3,3,ch-6),1.5,1.5)
            p.setPen(QColor("#edf4fb")); p.drawText(rect.adjusted(10,0,-6,0),Qt.AlignVCenter|Qt.AlignLeft,txt)
            if level is not None:
                pips(rect.right()-27,rect.center().y()-1.9,min(level,total),total,accent,44)

        def building(x,y,bw,bd,bh,roof,wall,accent,label=None,level=None,total=3,
                     windows=3,door=True,label_y=None,gable=False,label_maxw=None):
            sx=min(14.0,bw*0.055)
            base=QRectF(x,y,bw,bd)
            shadow(base,12,80,12,10)
            front=QPolygonF([QPointF(x,y+bd),QPointF(x+bw,y+bd),QPointF(x+bw+sx,y+bd-bh),QPointF(x+sx,y+bd-bh)])
            fg=QLinearGradient(x,y+bd-bh,x,y+bd); fg.setColorAt(0,wall.lighter(114)); fg.setColorAt(1,wall.darker(118))
            p.setPen(Qt.NoPen); p.setBrush(fg); p.drawPolygon(front)
            side=QPolygonF([QPointF(x+bw,y+bd),QPointF(x+bw,y),QPointF(x+bw+sx,y-bh),QPointF(x+bw+sx,y+bd-bh)])
            p.setBrush(wall.darker(142)); p.drawPolygon(side)
            roof_rect=QRectF(x+sx,y-bh,bw,bd)
            rg=QLinearGradient(roof_rect.topLeft(),roof_rect.bottomRight())
            rg.setColorAt(0,roof.lighter(116)); rg.setColorAt(0.55,roof); rg.setColorAt(1,roof.darker(112))
            p.setBrush(rg); p.setPen(QPen(accent.darker(125),1.1)); p.drawRoundedRect(roof_rect,7,7)
            inner=roof_rect.adjusted(8,7,-8,-7)
            if inner.width()>18 and inner.height()>12:
                p.setPen(QPen(QColor(255,255,255,26),1)); p.setBrush(QColor(255,255,255,9)); p.drawRoundedRect(inner,5,5)
                p.setPen(QPen(QColor(255,255,255,18),1))
                step=max(15.0,inner.width()/8.0); xx=inner.left()+step
                while xx<inner.right()-2:
                    p.drawLine(QPointF(xx,inner.top()+3),QPointF(xx,inner.bottom()-3)); xx+=step
            p.setPen(QPen(accent.lighter(128),1.2)); p.setBrush(Qt.NoBrush)
            p.drawRoundedRect(roof_rect.adjusted(1,1,-1,-1),7,7)
            if windows:
                n=max(1,int(windows)); gap=8.0; ww=max(6.0,(bw-(n+1)*gap)/n)
                for i in range(n):
                    wx=x+gap+i*(ww+gap); wy=y+bd-bh*0.72; wh=bh*0.34
                    gg=QLinearGradient(wx,wy,wx,wy+wh); gg.setColorAt(0,glass1); gg.setColorAt(1,glass2)
                    p.setPen(QPen(QColor(12,22,30,190),1)); p.setBrush(gg); p.drawRoundedRect(QRectF(wx,wy,ww,wh),2,2)
                    p.setPen(QPen(QColor(255,255,255,50),1)); p.drawLine(QPointF(wx+2,wy+2),QPointF(wx+ww*0.42,wy+wh*0.8))
            if door and bh>18:
                dw=min(bw*0.20,28.0); dh=bh*0.48; dx=x+bw/2-dw/2+sx*0.5; dy=y+bd-dh
                p.setPen(QPen(QColor(10,18,26,220),1.2)); p.setBrush(QColor(22,32,44,246))
                p.drawRoundedRect(QRectF(dx,dy,dw,dh),2,2)
                p.setPen(QPen(accent,1)); p.drawLine(QPointF(dx+dw/2,dy+2),QPointF(dx+dw/2,dy+dh-2))
            if gable and bh>20:
                ped=QPolygonF([QPointF(x+sx,y+bd-bh),QPointF(x+bw+sx,y+bd-bh),
                               QPointF(x+bw/2+sx,y+bd-bh-bh*0.38)])
                p.setPen(Qt.NoPen); p.setBrush(wall.darker(124)); p.drawPolygon(ped)
                p.setPen(QPen(accent,1.1)); p.setBrush(Qt.NoBrush); p.drawPolygon(ped)
            if label:
                chip(x+bw/2+sx*0.5,(y+bd+9) if label_y is None else label_y,label,accent,level,total,label_maxw or 190)

        def dashed_plot(x,y,bw,bd,label,accent):
            rect=QRectF(x,y,bw,bd)
            p.setPen(QPen(rgba(accent,130),1.5,Qt.DashLine)); p.setBrush(QColor(12,20,18,60))
            p.drawRoundedRect(rect,9,9)
            p.setPen(QPen(rgba(accent,180),2)); p.drawLine(QPointF(rect.center().x()-8,rect.center().y()),QPointF(rect.center().x()+8,rect.center().y()))
            p.drawLine(QPointF(rect.center().x(),rect.center().y()-8),QPointF(rect.center().x(),rect.center().y()+8))
            chip(rect.center().x(),rect.bottom()-24,label,accent,None,maxw=170)

        def car(rect,color):
            p.setPen(Qt.NoPen); p.setBrush(QColor(0,0,0,60)); p.drawRoundedRect(rect.translated(2,3),3,3)
            p.setBrush(QColor(color)); p.drawRoundedRect(rect,3,3)
            p.setBrush(QColor(170,210,235,170)); p.drawRoundedRect(QRectF(rect.left()+rect.width()*0.18,rect.top()+rect.height()*0.18,rect.width()*0.64,rect.height()*0.30),1.5,1.5)
            p.setBrush(QColor(20,28,36)); p.drawRoundedRect(QRectF(rect.left()+3,rect.bottom()-5,rect.width()-6,2.2),1,1)

        def tree(x,y,r):
            p.setPen(Qt.NoPen); p.setBrush(QColor(0,0,0,58)); p.drawEllipse(QPointF(x+r*0.45,y+r*0.5),r*1.05,r*0.86)
            for dx,dy,s in ((-0.32,-0.16,0.58),(0.30,-0.22,0.55),(-0.20,0.30,0.52),(0.28,0.26,0.48),(0,0,0.72)):
                p.setBrush(QColor("#173c23")); p.drawEllipse(QPointF(x+r*dx,y+r*dy),r*s,r*s*0.97)
            for dx,dy,s in ((-0.20,-0.10,0.44),(0.18,-0.14,0.40),(-0.10,0.18,0.38)):
                p.setBrush(QColor("#28643d")); p.drawEllipse(QPointF(x+r*dx,y+r*dy),r*s,r*s*0.97)
            p.setBrush(QColor("#3c8a58")); p.drawEllipse(QPointF(x-r*0.12,y-r*0.20),r*0.30,r*0.26)

        def lamp(x,y,on):
            p.setPen(QPen(QColor("#2a3948"),2.2)); p.drawLine(QPointF(x,y+14),QPointF(x,y-12))
            p.setPen(Qt.NoPen); p.setBrush(QColor("#3b4d60")); p.drawRoundedRect(QRectF(x-7,y-18,14,8),3,3)
            if on:
                glow=QRadialGradient(QPointF(x,y-14),22); glow.setColorAt(0,QColor(255,238,180,105)); glow.setColorAt(1,QColor(255,238,180,0))
                p.setBrush(glow); p.drawEllipse(QPointF(x,y-14),22,22)
                p.setBrush(QColor("#fff0bd")); p.drawRoundedRect(QRectF(x-5,y-16,10,4),2,2)

        def flag(x,y,color):
            p.setPen(QPen(QColor("#4a5f72"),1.5)); p.drawLine(QPointF(x,y+20),QPointF(x,y-8))
            p.setPen(Qt.NoPen); p.setBrush(color); p.drawPolygon(QPolygonF([QPointF(x+1,y-8),QPointF(x+17,y-3),QPointF(x+1,y+3)]))
            p.setBrush(QColor("#d8e2ed")); p.drawEllipse(QPointF(x,y-9),1.4,1.4)

        def path(points,width=12,color="#b8ad98"):
            pathobj=QPainterPath(); pathobj.moveTo(QPointF(*points[0]))
            for i in range(1,len(points)-1,2):
                if i+1<len(points):
                    pathobj.quadTo(QPointF(*points[i]),QPointF(*points[i+1]))
                else:
                    pathobj.lineTo(QPointF(*points[i]))
            if len(points)%2==0: pathobj.lineTo(QPointF(*points[-1]))
            p.setBrush(Qt.NoBrush)
            p.setPen(QPen(QColor(21,34,28,170),width+4,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin)); p.drawPath(pathobj)
            p.setPen(QPen(QColor(color),width,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin)); p.drawPath(pathobj)
            p.setPen(QPen(QColor(255,255,255,22),1.1,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin)); p.drawPath(pathobj)

        def pitch(x,y,bw,bd):
            rect=QRectF(x,y,bw,bd)
            p.setPen(Qt.NoPen); p.setBrush(QColor(0,0,0,80)); p.drawRoundedRect(rect.adjusted(-6,-6,6,8),12,12)
            p.setBrush(QColor("#2a6b48")); p.drawRoundedRect(rect,8,8)
            band=rect.height()/8.0
            for i in range(0,8,2):
                p.setBrush(QColor(255,255,255,10)); p.drawRect(QRectF(rect.left()+3,rect.top()+i*band,rect.width()-6,band))
            p.setPen(QPen(QColor(246,252,248,190),1.6)); p.setBrush(Qt.NoBrush)
            inner=rect.adjusted(8,7,-8,-7); p.drawRoundedRect(inner,3,3)
            p.drawLine(QPointF(inner.center().x(),inner.top()),QPointF(inner.center().x(),inner.bottom()))
            p.drawEllipse(inner.center(),inner.height()*0.18,inner.height()*0.18)
            goal_h=inner.height()*0.26
            p.setPen(QPen(QColor(246,252,248,170),1.4))
            p.drawLine(QPointF(inner.left()+inner.width()*0.20,inner.center().y()-goal_h/2),QPointF(inner.left()+inner.width()*0.20,inner.center().y()+goal_h/2))
            p.drawLine(QPointF(inner.right()-inner.width()*0.20,inner.center().y()-goal_h/2),QPointF(inner.right()-inner.width()*0.20,inner.center().y()+goal_h/2))
            p.setPen(QPen(QColor(239,248,242,210),2.2))
            p.drawLine(QPointF(inner.left(),inner.center().y()-goal_h/2),QPointF(inner.left(),inner.center().y()+goal_h/2))
            p.drawLine(QPointF(inner.right(),inner.center().y()-goal_h/2),QPointF(inner.right(),inner.center().y()+goal_h/2))
            p.setBrush(QColor(240,248,252,36)); p.setPen(QPen(QColor(240,248,252,160),1.2))
            p.drawRect(QRectF(inner.left()-5,inner.center().y()-goal_h*0.38,5,goal_h*0.76))
            p.drawRect(QRectF(inner.right(),inner.center().y()-goal_h*0.38,5,goal_h*0.76))
            for cx,cy in ((inner.left(),inner.top()),(inner.right(),inner.top()),(inner.left(),inner.bottom()),(inner.right(),inner.bottom())):
                p.setPen(Qt.NoPen); p.setBrush(club1); p.drawEllipse(QPointF(cx,cy),2.1,2.1)
            p.setPen(Qt.NoPen); p.setBrush(QColor(255,255,255,190)); p.drawEllipse(inner.center(),2.4,2.4)
