        # ------------------------------------------------------------ fond
        surface(QRectF(0,0,self.DESIGN_W,self.DESIGN_H),QColor("#0b1710"),QColor("#07100c"),18)
        glow=QRadialGradient(QPointF(470,210),720); glow.setColorAt(0,QColor(48,96,66,80)); glow.setColorAt(1,QColor(0,0,0,0))
        p.setPen(Qt.NoPen); p.setBrush(glow); p.drawRect(QRectF(0,0,self.DESIGN_W,self.DESIGN_H))

        site=QRectF(16,58,1168,566)
        sg=QLinearGradient(site.topLeft(),site.bottomRight())
        sg.setColorAt(0,QColor("#245f3d")); sg.setColorAt(0.5,QColor("#1d5134")); sg.setColorAt(1,QColor("#173f2a"))
        p.setPen(QPen(QColor(6,16,10,180),2)); p.setBrush(sg); p.drawRoundedRect(site,18,18)
        p.save()
        stripes=QPainterPath(); stripes.addRoundedRect(site,18,18); p.setClipPath(stripes)
        for i in range(0,14,2):
            p.setPen(Qt.NoPen); p.setBrush(QColor(255,255,255,7))
