        p.restore()

        # ------------------------------------------------------------ rivière / route
        river=QRectF(1122,58,62,566)
        rg=QLinearGradient(river.topLeft(),river.topRight()); rg.setColorAt(0,QColor("#2b6f9e")); rg.setColorAt(0.45,QColor("#3e91bd")); rg.setColorAt(1,QColor("#235d83"))
