        for x in range(45,1100,82):
            p.setPen(QPen(QColor(210,220,230,45),1)); p.drawLine(QPointF(x,road.top()+2),QPointF(x,road.top()+7))

        # ------------------------------------------------------------ allées / parvis
        path([(601,436),(598,500),(596,560)],20)
        path([(736,398),(790,424),(842,456)],10,"#b5a68f")
        plaza=QRectF(466,362,270,76)
        pg=QRadialGradient(plaza.center(),180); pg.setColorAt(0,QColor("#c9bfa9")); pg.setColorAt(1,QColor("#9e927d"))
        p.setPen(QPen(QColor(46,54,45,180),1.5)); p.setBrush(pg); p.drawRoundedRect(plaza,28,28)
