            p.setBrush(QColor("#222d38")); p.drawRoundedRect(QRectF(truck.left()+truck.width()*0.44,truck.top()+6,truck.width()*0.40,truck.height()*0.45),3,3)
            p.setBrush(QColor(190,225,245,170)); p.drawRoundedRect(QRectF(truck.left()+truck.width()*0.46,truck.top()+8,truck.width()*0.36,truck.height()*0.30),2,2)
            p.setBrush(QColor("#18202a")); p.drawEllipse(QPointF(truck.left()+truck.width()*0.22,truck.bottom()),4,4); p.drawEllipse(QPointF(truck.left()+truck.width()*0.78,truck.bottom()),4,4)
            p.setPen(QPen(club1,2)); p.drawLine(QPointF(truck.left()+6,truck.bottom()-3),QPointF(truck.left()+truck.width()-6,truck.bottom()-3))
            chip(truck.center().x(),truck.bottom()+7,"FOOD TRUCK",QColor("#e0b45f"),None,maxw=120)
