        super().__init__(host)
        self.host=host
        self.setWindowTitle("Colonnes du marché")
        self.setMinimumSize(520,620)
        root=QVBoxLayout(self); root.setContentsMargins(16,14,16,12); root.setSpacing(8)
        title=QLabel("COLONNES DU MARCHÉ")
        title.setStyleSheet("font-size:13pt;font-weight:1000;color:#eef6ff;letter-spacing:1px;")
        root.addWidget(title)
        hint=QLabel("Coche les colonnes à afficher et ajuste leur largeur. Le nom du joueur prend toujours l'espace restant. Tu peux aussi glisser les en-têtes pour réordonner.")
        hint.setObjectName("Muted"); hint.setWordWrap(True); root.addWidget(hint)
