        scroll.setStyleSheet("QScrollArea{background:transparent;border:0;} QScrollArea>QWidget>QWidget{background:transparent;}")
        body=QWidget(); grid=QGridLayout(body); grid.setContentsMargins(2,2,8,2)
        grid.setHorizontalSpacing(10); grid.setVerticalSpacing(5)
