class SplashWindow(QWidget):
    """Ouverture du jeu : logo du studio puis image d'introduction, avec fondus."""

    finished = Signal()

    def __init__(self, images, parent=None):
        super().__init__(parent)
        self.setWindowFlags(Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint)
        self.setAttribute(Qt.WA_DeleteOnClose, False)
        self.setCursor(Qt.PointingHandCursor)
        self.setWindowTitle("JGames")
        self._paths=[path for path in (images or []) if path and os.path.exists(path)]
        self._index=0; self._busy=False; self._closing=False; self._pending=False
        self._emitted=False; self._current=None
        self.image=QLabel(self); self.image.setAlignment(Qt.AlignCenter)
        self.image.setStyleSheet("background:transparent;")
        self.effect=QGraphicsOpacityEffect(self.image); self.effect.setOpacity(0.0)
        self.image.setGraphicsEffect(self.effect)
        self.anim=QPropertyAnimation(self.effect, b"opacity", self)
        self.anim.setDuration(420); self.anim.setEasingCurve(QEasingCurve.InOutCubic)
        self.anim.finished.connect(self._fade_done)
        self.hint=QLabel("CLIQUEZ POUR CONTINUER", self)
        self.hint.setAlignment(Qt.AlignCenter)
        self.hint.setStyleSheet("font-size:8pt;font-weight:900;letter-spacing:3px;color:#b9c8d8;background:transparent;")
        screen=QApplication.primaryScreen()
        if screen is not None: self.resize(screen.availableGeometry().size())
        QTimer.singleShot(0, self._load_current)

    def _apply_pixmap(self):
        if self._current is None: return
        scaled=self._current.scaled(self.size(), Qt.KeepAspectRatio, Qt.SmoothTransformation)
        self.image.setPixmap(scaled)

    def resizeEvent(self,event):
        super().resizeEvent(event)
        self.image.setGeometry(self.rect())
        self.hint.setGeometry(0, max(0,self.height()-62), self.width(), 24)
        self._apply_pixmap()

    def paintEvent(self,event):
        p=QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        bg=QLinearGradient(0,0,0,self.height())
        bg.setColorAt(0,QColor("#05090d")); bg.setColorAt(1,QColor("#0b141c"))
        p.fillRect(self.rect(),bg)
        vign=QRadialGradient(QPointF(self.width()/2,self.height()/2),max(self.width(),self.height())*0.62)
        vign.setColorAt(0,QColor(0,0,0,0)); vign.setColorAt(1,QColor(0,0,0,130))
        p.fillRect(self.rect(),vign)
        total=max(1,len(self._paths)); dot_y=self.height()-26
        start=self.width()/2-(total-1)*8
        for i in range(total):
            p.setPen(Qt.NoPen)
            p.setBrush(QColor("#d8c18a") if i==self._index else QColor(255,255,255,42))
            p.drawEllipse(QPointF(start+i*16,dot_y),3.2,3.2)
        p.end()

    def mousePressEvent(self,event):
        self.advance(); event.accept()

    def keyPressEvent(self,event):
        if event.key()==Qt.Key_Escape:
            self.skip(); return
        if event.key() in (Qt.Key_Space,Qt.Key_Return,Qt.Key_Enter):
            self.advance(); return
        super().keyPressEvent(event)

    def advance(self):
        if self._busy or self._current is None or self._closing: return
        if self._index>=len(self._paths)-1:
            self._closing=True; self._fade(0.0)
        else:
            self._pending=True; self._fade(0.0)

    def skip(self):
        if self._emitted: return
        self._closing=True
        if self._current is None:
            self._finish(); return
        self._fade(0.0)

    def _load_current(self):
        while self._index<len(self._paths):
            pix=QPixmap(self._paths[self._index])
            if not pix.isNull():
                self._current=pix; self._apply_pixmap()
                self.effect.setOpacity(0.0); self._fade(1.0); return
            self._index+=1
        self._finish()

    def _fade(self,target):
        self._busy=True
        self.anim.stop()
        self.anim.setStartValue(self.effect.opacity())
        self.anim.setEndValue(float(target))
        self.anim.start()

    def _fade_done(self):
        self._busy=False
        if self._closing:
            self._finish(); return
        if self._pending:
            self._pending=False; self._index+=1; self._load_current()

    def _finish(self):
        if self._emitted: return
        self._emitted=True
        self.finished.emit()
        self.close()

    def closeEvent(self,event):
        if not self._emitted:
            self._emitted=True
            self.finished.emit()
        super().closeEvent(event)


class MainWindow(QMainWindow):

    def __init__(self):

        super().__init__()

        self.setWindowTitle("Futsal Manager — Carrière locale")

        self.resize(1360, 820)

        self.setMinimumSize(960, 620)

        self.match_state = None

        self.match_rng = random.Random(0)

        self._refreshing = False

        self._career_nav_locked = False

        self._goal_slow_timer = None

        self._goal_saved_speed = None

        self._goal_celebration_timer = None

        self._market_refresh_timer = None

        self.market_page = 0

        self.market_page_size = 20

        self.game_options = load_game_options()

        self.timer = QTimer(self); self.timer.timeout.connect(self.advance_minute)

        self._build_ui()

        self._tactics_config_loaded=False

        self.load_tactics_settings()

        if not self._tactics_config_loaded and not self._selected_lineup_ids():

            self.auto_pick_lineup()

        self.refresh_all()

        self.refresh_save_catalog()

        self.app_stack.setCurrentWidget(self.start_screen)



    def _apply_global_layout_policies(self):

        """Passe de finition layout : privilégie l'espace disponible sans toucher au moteur."""

        for widget in self.findChildren(QWidget):

            if isinstance(widget, QTableWidget):

                widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)

                header = widget.horizontalHeader()

                header.setMinimumSectionSize(56)

                header.setStretchLastSection(True)

                count = widget.columnCount()

                for col in range(max(0, count - 1)):

                    header.setSectionResizeMode(col, QHeaderView.ResizeToContents)

                if count:

                    header.setSectionResizeMode(count - 1, QHeaderView.Stretch)

                widget.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)

            elif isinstance(widget, QSplitter):

                widget.setChildrenCollapsible(False)

                widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)

                for index in range(widget.count()):

                    widget.setStretchFactor(index, 1)

            elif isinstance(widget, QScrollArea):

                widget.setWidgetResizable(True)

                widget.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)

                widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)

        for page in getattr(self, "pages", []):

            page.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)

        self.stack.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)



    def closeEvent(self,event):

        if self.match_state and not self.match_state.get("finished",True):

            if self.match_state.get("finalization_failed") and self.match_state.get("elapsed_seconds",0)>=2400:

                leave=self.show_game_message("Rapport non enregistré","La rencontre est terminée mais sa sauvegarde a échoué. Quitter libérera le verrou de la base ; le match restera à rejouer depuis le dernier état enregistré.","warning",confirm=True,confirm_text="QUITTER SANS VALIDER LE MATCH")

                if leave:

                    self.timer.stop(); event.accept(); return

                event.ignore(); return

            event.ignore()

            self.show_game_message("Match en direct","Termine la rencontre avant de quitter : la partie en cours n'est pas encore validée.","warning")

            return

        self.save_active_career(show_notice=False)

        event.accept()



    def resizeEvent(self,event):

        super().resizeEvent(event)

        if hasattr(self,"stack"):

            if self.stack.currentIndex()==4: QTimer.singleShot(0,self.fit_training_layout)

            if self.stack.currentIndex()==2: QTimer.singleShot(0,self.fit_tactics_layout)

            if self.stack.currentIndex()==6: QTimer.singleShot(0,self._fit_mail_layout)

            if self.stack.currentIndex()==5: QTimer.singleShot(0,self._fit_facility_layout)

            if self.stack.currentIndex()==13: QTimer.singleShot(0,self._fit_academy_layout)

            if self.stack.currentIndex()==7: QTimer.singleShot(0,self._fit_offers_layout)

            QTimer.singleShot(0,self.fit_career_scroll_area)



    def log_error(self, context, exc):

        try:

            with open(ERROR_LOG, "a", encoding="utf-8") as f:

                f.write(f"[{datetime.now().isoformat(timespec='seconds')}] {context}\n")

                f.write("".join(traceback.format_exception(type(exc), exc, exc.__traceback__)))

                f.write("\n")

        except Exception:

            pass



    def log_trace(self, text):

        if not TRACE_ENABLED:

            return

        try:

            if os.path.exists(TRACE_LOG) and os.path.getsize(TRACE_LOG) > TRACE_MAX_BYTES:

                try:

                    os.replace(TRACE_LOG, TRACE_LOG + ".1")

                except OSError:

                    pass

            with open(TRACE_LOG, "a", encoding="utf-8") as f:

                f.write(f"[{datetime.now().isoformat(timespec='seconds')}] {text}\n")

        except Exception:

            pass



    def show_game_message(self,title,message,severity="info",confirm=False,confirm_text="CONFIRMER"):

        colors={"info":"#9863ed","warning":"#e3a943","error":"#e65373","success":"#36b882"}

        accent=colors.get(severity,"#9863ed")

        # Parent = fenetre modale active au-dessus de tout : la boite ne doit jamais

        # apparaitre DERRIERE une fiche club ou un autre dialog deja ouvert.

        parent=QApplication.activeModalWidget() or (QApplication.activeWindow() if QApplication.activeWindow() and QApplication.activeWindow() is not self else self) or self

        dialog=QDialog(parent); dialog.setWindowTitle(title); dialog.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dialog.setModal(True); dialog.setFixedWidth(520)

        root=QVBoxLayout(dialog); root.setContentsMargins(14,14,14,14); root.setSpacing(10)

        panel=QFrame(); panel.setObjectName("Panel"); layout=QVBoxLayout(panel); layout.setContentsMargins(14,12,14,12); layout.setSpacing(10)

        header=QHBoxLayout(); badge=QLabel("!" if severity in ("warning","error") else "✓" if severity=="success" else "i")

        badge.setAlignment(Qt.AlignCenter); badge.setFixedSize(32,32); badge.setStyleSheet(f"background:{accent};color:white;border-radius:16px;font-weight:900;font-size:14pt;")

        heading=QLabel(title.upper()); heading.setStyleSheet(f"color:{accent};font-weight:900;letter-spacing:1px;")

        header.addWidget(badge); header.addWidget(heading,1)

        close=QPushButton("×"); close.setFixedSize(32,30); close.clicked.connect(dialog.reject); header.addWidget(close)

        layout.addLayout(header)

        body=QLabel(str(message)); body.setWordWrap(True); body.setStyleSheet("color:#e4e9f4;font-size:10pt;padding:8px;background:#0c1321;border:1px solid #29334a;border-radius:9px;")

        layout.addWidget(body); root.addWidget(panel)

        buttons=QHBoxLayout(); buttons.addStretch()

        if confirm:

            cancel=QPushButton("ANNULER"); cancel.clicked.connect(dialog.reject); buttons.addWidget(cancel)

            ok=QPushButton(confirm_text); ok.setObjectName("Primary"); ok.clicked.connect(dialog.accept); buttons.addWidget(ok)

        else:

            ok=QPushButton("COMPRIS"); ok.setObjectName("Primary"); ok.clicked.connect(dialog.accept); buttons.addWidget(ok)

        root.addLayout(buttons)

        parent_geo=parent.frameGeometry()

        dialog.show()

        dialog.move(parent_geo.center()-dialog.rect().center())

        dialog.raise_(); dialog.activateWindow()

        result=dialog.exec()

        self._tr_after_modal(dialog)

        return result==QDialog.Accepted



    def counter_terms_dialog(self,title,prompt,amount,years=None,suffix=None,info=None):

        """Boîte de contre-proposition. `info` affiche EN CLAIR les exigences

        de l'autre partie (salaire réclamé par le joueur, indemnité demandée

        par le club) : les tours de négociation restent lisibles."""

        dialog=QDialog(self); dialog.setWindowTitle(title); dialog.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dialog.setFixedWidth(500)

        root=QVBoxLayout(dialog); root.setContentsMargins(16,16,16,16); root.setSpacing(10)

        panel=QFrame(); panel.setObjectName("HeroPanel"); pl=QVBoxLayout(panel); pl.setContentsMargins(14,12,14,12)

        heading=QLabel(title.upper()); heading.setStyleSheet("font-weight:900;color:#d3b4ff;letter-spacing:1px;")

        body=QLabel(prompt); body.setWordWrap(True); body.setObjectName("Muted")

        pl.addWidget(heading); pl.addWidget(body); root.addWidget(panel)

        form=QGridLayout(); rows=0

        if info:

            info_label=QLabel(info); info_label.setWordWrap(True); info_label.setStyleSheet("font-weight:900;color:#f4bd65;")

            form.addWidget(info_label,rows,0,1,2); rows+=1

        form.addWidget(QLabel("Montant proposé"),rows,0)

        amount_box=QSpinBox(); amount_box.setRange(250,999999999); amount_box.setSingleStep(10000); amount_box.setValue(max(250,int(amount))); amount_box.setSuffix(suffix or (" € / mois" if years is not None else " €")); amount_box.setObjectName("counterAmount")

        form.addWidget(amount_box,rows,1)

        years_box=None

        if years is not None:

            form.addWidget(QLabel("Durée du contrat"),rows+1,0)

            years_box=QSpinBox(); years_box.setRange(1,5); years_box.setValue(max(1,min(5,int(years)))); years_box.setSuffix(" an(s)"); form.addWidget(years_box,rows+1,1)

        root.addLayout(form)

        buttons=QHBoxLayout(); buttons.addStretch(); cancel=QPushButton("ANNULER"); cancel.clicked.connect(dialog.reject)

        send=QPushButton("CONFIRMER LA PROPOSITION"); send.setObjectName("Primary"); send.clicked.connect(dialog.accept)

        buttons.addWidget(cancel); buttons.addWidget(send); root.addLayout(buttons)

        if dialog.exec()!=QDialog.Accepted: return None

        return {"amount":amount_box.value(),"years":years_box.value() if years_box else None}



    def confirm_player_contract(self, player_id, player, fee, offer_salary, years, club_name):

        """Boîte de confirmation du contrat du joueur avant validation d'un transfert accepté par le club vendeur.



        Retourne (confirmed, salary, years) ou None si annulé.

        Vérifie que le club peut assumer l'indemnité + le coût salarial sur la durée du contrat.

        """

        dialog=QDialog(self); dialog.setWindowTitle("CONFIRMER LE CONTRAT DU JOUEUR"); dialog.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dialog.setFixedWidth(520)

        root=QVBoxLayout(dialog); root.setContentsMargins(16,16,16,16); root.setSpacing(10)

        panel=QFrame(); panel.setObjectName("HeroPanel"); pl=QVBoxLayout(panel); pl.setContentsMargins(14,12,14,12)

        heading=QLabel(f"CONTRAT : {player['first_name']} {player['last_name']}"); heading.setStyleSheet("font-weight:900;color:#d3b4ff;letter-spacing:1px;")

        conn_c=db(); club_signup=conn_c.execute("SELECT division,reputation FROM club WHERE id=1").fetchone(); conn_c.close()

        demand,_wants_move=player_salary_demand(player,club_signup)

        info=QLabel(f"Club vendeur : {club_name}  •  Indemnité de transfert : {fee:,} €  •  Le joueur exige un salaire d'au moins {demand:,} € / mois.".replace(","," ")); info.setWordWrap(True); info.setObjectName("Muted")

        pl.addWidget(heading); pl.addWidget(info); root.addWidget(panel)

        form=QGridLayout(); form.setSpacing(8)

        form.addWidget(QLabel("Salaire mensuel proposé"),0,0)

        salary_box=QSpinBox(); salary_box.setRange(max(500,demand),999999); salary_box.setSingleStep(500); salary_box.setValue(max(max(500,demand),int(offer_salary or player["salary"]*1.05))); salary_box.setSuffix(" € / mois"); form.addWidget(salary_box,0,1)

        form.addWidget(QLabel("Durée du contrat"),1,0)

        years_box=QSpinBox(); years_box.setRange(1,5); years_box.setValue(max(1,min(5,int(years or 3)))); years_box.setSuffix(" an(s)"); form.addWidget(years_box,1,1)

        root.addLayout(form)

        # Récap budgétaire

        self._contract_recap=QLabel(); self._contract_recap.setObjectName("Muted"); self._contract_recap.setWordWrap(True)

        def update_recap():

            s=salary_box.value(); y=years_box.value()

            total=fee+s*12

            conn2=db(); budget=conn2.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"]; conn2.close()

            ok = total<=budget

            self._contract_recap.setText(

                f"Salaire mensuel : {s:,} € (intégré à la masse salariale, payé chaque mois)  •  "

                f"Indemnité : {fee:,} €  •  Débit total à la signature ({int(fee)} € + 1 an de salaires) : {total:,} €  •  "

                f"Budget club : {budget:,} €  •  {'✓ dans les possibilités du club' if ok else '✗ au-dessus du budget'}".replace(","," ")

            )

            self._contract_recap.setStyleSheet(f"color:{'#6ce0ad' if ok else '#ff8291'};font-weight:800;")

        salary_box.valueChanged.connect(update_recap); years_box.valueChanged.connect(update_recap)

        root.addWidget(self._contract_recap)

        update_recap()

        buttons=QHBoxLayout(); buttons.addStretch(); cancel=QPushButton("ANNULER"); cancel.clicked.connect(dialog.reject)

        send=QPushButton("CONFIRMER LE TRANSFERT"); send.setObjectName("Primary"); send.clicked.connect(dialog.accept)

        buttons.addWidget(cancel); buttons.addWidget(send); root.addLayout(buttons)

        if dialog.exec()!=QDialog.Accepted: return None

        return (True, salary_box.value(), years_box.value())





    def message_badge_count(self):
        """Nombre de messages non lus VISIBLES (familles masquées exclues)."""
        try:
            c=db()
            rows=c.execute("SELECT kind FROM manager_message WHERE is_read=0").fetchall()
            c.close()
            hidden_media=self._media_messages_hidden()
            cats=getattr(self,"msg_categories",None)
            count=0
            for r in rows:
                kind=str(r["kind"] or "")
                if kind=="scout_report":
                    continue
                if kind=="media" and hidden_media:
                    continue
                if cats and not self._category_enabled(self._message_category(kind)):
                    continue
                count+=1
            return count
        except Exception:
            return 0

    def _apply_message_badges(self,count):
        text="99+" if int(count)>99 else str(int(count))
        for attr in ("inbox_nav_badge","msg_badge"):
            widget=getattr(self,attr,None)
            if widget is not None:
                widget.setText(text)
                widget.setVisible(int(count)>0)
        self._message_badge_last=int(count)

    def refresh_message_badges(self):
        """Rafraichissement ultra-leger : un COUNT, aucun widget de liste."""
        if not hasattr(self,"inbox_nav_badge") and not hasattr(self,"msg_badge"):
            return
        self._apply_message_badges(self.message_badge_count())

    def refresh_manager_message_queue(self,messages):

        if not hasattr(self,"action_message_list"): return

        # MESSAGERIE SANS PRESSE (retour « enlever les medias ») : si l'option

        # est coupee, les messages kind='media' ne s'affichent nulle part.

        if self._media_messages_hidden() and messages:

            def _msg_kind(m):

                try: return (m["kind"] if "kind" in m.keys() else "") or ""

                except Exception: return ""

            messages=[m for m in messages if _msg_kind(m)!="media"]
            messages=[m for m in messages if _msg_kind(m)!="scout_report"]

        # La page moderne utilise sa propre liste avec actions contextuelles.

        if hasattr(self,"msg_search"):

            self._manager_messages=list(messages)

            unread=self.message_badge_count()

            self._apply_message_badges(unread)

            try:
                if self.stack.currentIndex()!=6:
                    self._messages_dirty=True
                    return
            except Exception:
                pass

            self._messages_dirty=False
            self._refresh_messages_ui()

            return

        current_item=self.action_message_list.currentItem()

        current_id=current_item.data(Qt.UserRole) if current_item else None

        self._manager_messages=list(messages)

        self.action_message_list.blockSignals(True); self.action_message_list.clear()

        selected=-1

        kind_style={

            "match_report":("📊","#b99bff","Rapport de match"),

            "scout_report":(" ","#ad54d8","Rapport de scouting"),

            "contract_offer":("📄","#4a9e78","Offre de contrat"),
        "loan_request":("🔁","#5aa8d8","Demande de prêt"),

            "free_agent_contract":("📄","#4a9e78","Contrat joueur libre"),

            "market_offer":("⇄","#e6a341","Offre de transfert"),

            "transfer_sale":("💶","#a07a38","Vente de joueur"),

            "transfer_sale_counter":("💶","#a07a38","Contre-offre de vente"),

            "transfer_arrival":("🛬","#4a9e78","Recrutement finalisé"),

            "job_offer":("🔒","#d9b46a","Offre confidentielle"),

        }

        for index,message in enumerate(self._manager_messages):

            ready=message["status"]=="ready"

            kind=message.get("kind","")

            emoji,color,label=kind_style.get(kind,("✉","#9aa6bd","Message"))

            if not message["is_read"]:

                dot="  "

                prefix=f"{dot}{label}"

                fore=QColor("#ffd2e0")

            elif ready:

                dot="✓  "

                prefix=f"{dot}{label}"

                fore=QColor("#e9edf7")

            else:

                dot="○  "

                prefix=f"{dot}{label}"

                fore=QColor("#9aa6bd")

            due=message.get("due_date","")

            due_txt=f"  •  réponse le {fmt_date_fr(due)}" if due else ""

            item=QListWidgetItem(f"{emoji} {prefix}\n{message['title']}{due_txt}")

            item.setData(Qt.UserRole,message["id"])

            item.setForeground(fore)

            item.setToolTip(html.escape(message.get("body",""))[:200])

            self.action_message_list.addItem(item)

            if current_id==message["id"]: selected=index

        unread=sum(1 for m in self._manager_messages if not m["is_read"])

        ready_count=sum(1 for m in self._manager_messages if m["status"]=="ready" and m["kind"]!="match_report")

        waiting_count=sum(1 for m in self._manager_messages if m["status"]=="waiting")

        report_count=sum(1 for m in self._manager_messages if m["kind"]=="match_report" and not m["is_read"])

        self.action_queue_count.setText(f"{ready_count} À TRAITER  •  {waiting_count} EN ATTENTE"+(f"  •  {report_count} RAPPORT(S)" if report_count else ""))

        self.msg_badge.setText("99+" if unread>99 else str(unread))

        self.msg_badge.setVisible(unread>0)

        self.inbox_nav_badge.setText("99+" if unread>99 else str(unread))

        self.inbox_nav_badge.setVisible(unread>0)

        # vide la barre d'action contextuelle quand rien n'est sélectionné

        while self.msg_action_bar.count():

            item=self.msg_action_bar.takeAt(0)

            if item.widget(): item.widget().deleteLater()

        if selected>=0:

            self.action_message_list.setCurrentRow(selected)

        else:

            self.action_message_list.setCurrentRow(-1)

            if self._manager_messages:

                self.action_message_detail.setHtml("<div style='color:#99a6c0;padding:20px;text-align:center'><h3 style='color:#c7d2e0'>Sélectionne un dossier</h3><p>Les messages à traiter apparaissent en rose. Les réponses des agents arrivent après quelques jours de carrière.</p></div>")

            else:

                self.action_message_detail.setHtml("<div style='color:#99a6c0;padding:20px;text-align:center'><h3 style='color:#c7d2e0'>Aucun dossier à traiter</h3><p>Les réponses des agents et les offres de clubs arriveront ici après quelques jours de carrière.</p></div>")

            for button in (self.action_accept_btn,self.action_reject_btn,self.action_counter_btn): button.setEnabled(False); button.setVisible(False)

        self.action_message_list.blockSignals(False)

        if selected>=0: self.update_action_message_detail(selected,mark_read=self.stack.currentIndex()==6)



    def update_action_message_detail(self,row,mark_read=True):

        if row<0 or row>=len(getattr(self,"_manager_messages",[])):

            for button in (self.action_accept_btn,self.action_reject_btn,self.action_counter_btn): button.setEnabled(False); button.setVisible(False)

            while self.msg_action_bar.count():

                item=self.msg_action_bar.takeAt(0)

                if item.widget(): item.widget().deleteLater()

            return

        message=self._manager_messages[row]

        try: data=json.loads(message["action_data"] or "{}")

        except ValueError: data={}

        if mark_read and not message["is_read"]:

            conn=db()

            if message["kind"] in ("scout_report","match_report"): conn.execute("UPDATE manager_message SET is_read=1,status='handled' WHERE id=?",(message["id"],))

            else: conn.execute("UPDATE manager_message SET is_read=1 WHERE id=?",(message["id"],))

            conn.commit(); conn.close()

            updated=dict(message); updated["is_read"]=1

            if message["kind"] in ("scout_report","match_report"): updated["status"]="handled"

            self._manager_messages[row]=updated; message=updated

            unread=sum(1 for msg in self._manager_messages if not msg["is_read"])

            self.msg_badge.setText("99+" if unread>99 else str(unread)); self.msg_badge.setVisible(unread>0)

            self.inbox_nav_badge.setText("99+" if unread>99 else str(unread)); self.inbox_nav_badge.setVisible(unread>0)

            item=self.action_message_list.item(row)

            if item:

                prefix="✓ RAPPORT CONSULTÉ" if message["kind"] in ("scout_report","match_report") else " À TRAITER" if message["status"]=="ready" else "◷ EN ATTENTE"

                item.setText(f"{prefix}\n{message['title']}\nÉchéance : {fmt_date_fr(message['due_date'])}")

        ready=message["status"]=="ready"

        status="RAPPORT ARCHIVÉ" if message["kind"]=="match_report" else "RAPPORT CONSULTÉ" if message["kind"]=="scout_report" and message["is_read"] else "RAPPORT DISPONIBLE" if message["kind"]=="scout_report" else "DOSSIER À TRAITER" if ready else f"EN ATTENTE • réponse prévue le {fmt_date_fr(message['due_date'])}"

        body_html=html.escape(clean_message_text(message["body"])).replace("\n","<br>")

        if message["kind"]=="match_report": body_html+="<br><br><a href='page:8'>Ouvrir le Calendrier pour le rapport complet</a>"

        kind_color={"match_report":"#b99bff","scout_report":"#ad54d8","contract_offer":"#4a9e78","free_agent_contract":"#4a9e78","market_offer":"#e6a341","transfer_sale":"#a07a38","transfer_sale_counter":"#a07a38","transfer_arrival":"#4a9e78"}.get(message["kind"],"#9aa6bd")

        self.action_message_detail.setHtml(

            f"<div style='font-family:Segoe UI;color:#e9edf7;padding:10px'><div style='color:{kind_color};font-size:11px;font-weight:900;letter-spacing:1px'>{status}</div>"

            f"<h2 style='margin:8px 0;font-size:13pt'>{html.escape(message['title'])}</h2>"

            f"<p style='line-height:1.6;margin:8px 0'>{body_html}</p>"

            f"<p style='color:#9aa6bd;font-size:9px'>Reçu le {fmt_date_fr(message['created_date'])} • dossier traité depuis la messagerie.</p></div>"

        )

        actionable=message["kind"] in ("contract_offer","free_agent_contract","market_offer","transfer_sale","transfer_sale_counter")

        player_salary_counter=message["kind"]=="market_offer" and data.get("outcome")=="player_counter"

        self.action_accept_btn.setVisible(ready and actionable and not player_salary_counter); self.action_accept_btn.setEnabled(ready and actionable and not player_salary_counter)

        self.action_reject_btn.setVisible(ready and actionable); self.action_reject_btn.setEnabled(ready and actionable)

        can_counter=ready and message["kind"] in ("contract_offer","free_agent_contract","market_offer","transfer_sale","transfer_sale_counter")

        self.action_counter_btn.setVisible(can_counter)

        self.action_counter_btn.setEnabled(can_counter)

        if message["kind"] in ("contract_offer","free_agent_contract"):

            self.action_accept_btn.setText("SIGNER LE CONTRAT")

            self.action_counter_btn.setText("FAIRE UNE CONTRE-OFFRE")

        elif message["kind"]=="market_offer":

            self.action_accept_btn.setText("ACCEPTER LE TRANSFERT")

            self.action_counter_btn.setText("PROPOSER LE SALAIRE" if player_salary_counter else "FAIRE UNE CONTRE-OFFRE")

        else:

            self.action_accept_btn.setText("ACCEPTER L'OFFRE")

            self.action_counter_btn.setText("NÉGOCIER LE MONTANT")

        # --- Boutons d'accès rapide aux pages cibles ---

        while self.msg_action_bar.count():

            item=self.msg_action_bar.takeAt(0)

            if item.widget(): item.widget().deleteLater()

        kind=message["kind"]

        target_page=None; target_label=""

        if kind in ("market_offer","transfer_sale","transfer_sale_counter","transfer_departure"): target_page,target_label=7,"Voir le Mercato"

        elif kind in ("contract_offer","free_agent_contract"): target_page,target_label=1,"Voir l'effectif"

        elif kind in ("scout_report","scout_digest"): target_page,target_label=7,"Voir le Mercato"

        elif kind=="match_report": target_page,target_label=8,"Voir le Calendrier"

        if target_page is not None and ready:

            go_btn=QPushButton(f"→  {target_label}")

            go_btn.setMinimumHeight(34)

            go_btn.setStyleSheet(f"QPushButton{{background:#5b4b8e;border:1px solid #7d6fb3;border-radius:8px;color:#f3e8ff;font-weight:900;padding:6px 14px;}} QPushButton:hover{{background:#7d6fb3;}}")

            go_btn.clicked=lambda checked=False, idx=target_page: self.show_page(idx)

            self.msg_action_bar.addWidget(go_btn)

        # bouton "Tout marquer lu" si des non lus restent

        if any(not m["is_read"] for m in self._manager_messages):

            mark_btn=QPushButton("✓  Tout marquer lu")

            mark_btn.setMinimumHeight(34)

            mark_btn.setStyleSheet("QPushButton{background:#152030;border:1px solid #354352;border-radius:8px;color:#c7d2e0;font-weight:800;padding:6px 14px;} QPushButton:hover{background:#203040;}")

            mark_btn.clicked=self.mark_all_messages_read

            self.msg_action_bar.addWidget(mark_btn)



    def mark_all_messages_read(self):

        conn=db()

        rows=conn.execute("SELECT * FROM manager_message").fetchall()

        for m in rows:

            if not m["is_read"]:

                if m["kind"] in ("scout_report","match_report"): conn.execute("UPDATE manager_message SET is_read=1,status='handled' WHERE id=?",(m["id"],))

                else: conn.execute("UPDATE manager_message SET is_read=1 WHERE id=?",(m["id"],))

        handled_ids={m["id"] for m in rows if not m["is_read"] and m["kind"] in ("scout_report","match_report")}

        conn.commit(); conn.close()

        for m in self._manager_messages:

            if m["id"] in handled_ids: m["status"]="handled"

            m["is_read"]=1

        unread=sum(1 for m in self._manager_messages if not m["is_read"])

        self.msg_badge.setText("99+" if unread>99 else str(unread)); self.msg_badge.setVisible(unread>0)

        self.inbox_nav_badge.setText("99+" if unread>99 else str(unread)); self.inbox_nav_badge.setVisible(unread>0)

        self.refresh_all()



    def _selected_manager_message(self,message_id=None):

        if message_id is not None:

            return next((m for m in getattr(self,"_manager_messages",[]) if m["id"]==message_id),None)

        item=self.action_message_list.currentItem() if hasattr(self,"action_message_list") else None

        message_id=item.data(Qt.UserRole) if item else None

        return next((m for m in getattr(self,"_manager_messages",[]) if m["id"]==message_id),None)



    def close_player_dossiers(self, conn, player_id, keep_id=None, reason="Le joueur a rejoint le club."):
        """Ferme les autres dossiers en cours d'un joueur qui vient de signer :
        plus de « réponse à consulter » fantôme dans l'onglet OFFRES."""
        try:
            rows=conn.execute("""SELECT id,kind,action_data FROM manager_message
                                 WHERE status IN ('waiting','ready')
                                   AND kind IN ('market_offer','contract_offer','free_agent_contract',
                                                'transfer_sale','transfer_sale_counter')""").fetchall()
            for row in rows:
                if keep_id is not None and int(row["id"])==int(keep_id): continue
                try: data=json.loads(row["action_data"] or "{}")
                except Exception: continue
                if int(data.get("player_id") or 0)!=int(player_id): continue
                data["outcome"]="joined"; data["closed_reason"]=reason
                conn.execute("UPDATE manager_message SET status='handled',is_read=1,action_data=? WHERE id=?",
                             (json.dumps(data,ensure_ascii=False),row["id"]))
        except Exception as exc:
            self.log_error("close_player_dossiers",exc)

    def resolve_manager_message(self,action,message_id=None):

        message=self._selected_manager_message(message_id)

        if not message or message["status"]!="ready": return

        try: data=json.loads(message["action_data"] or "{}")

        except ValueError: data={}

        conn=db(); player_id=data.get("player_id")

        kind=message["kind"]

        if action=="counter":

            if kind in ("contract_offer","free_agent_contract"):

                prow_c=conn.execute("SELECT first_name,last_name,salary FROM player WHERE id=?" if player_id else "SELECT '' first_name,'' last_name,0 salary FROM player WHERE id=-1",(player_id if player_id else (),)).fetchone()

                prev_counter=int(data.get("counter_salary",0) or 0)

                info_lines=[]

                if prow_c and prow_c["first_name"]:

                    info_lines.append(f"{prow_c['first_name']} {prow_c['last_name']} — contrat actuel : {int(prow_c['salary'] or 0):,} € / mois".replace(","," "))

                if prev_counter:

                    info_lines.append(f"Exigence de l'agent : {prev_counter:,} € / mois".replace(","," "))

                proposed=self.counter_terms_dialog("Contre-offre de contrat","Propose tes nouvelles conditions. L'agent répondra après un délai de réflexion.",data.get("counter_salary",data.get("offer_salary",2500)),data.get("counter_years",data.get("offer_years",2)),info="\n".join(info_lines) or None)

                if not proposed: conn.close(); return

                new_data={"player_id":player_id,"offer_salary":proposed["amount"],"offer_years":proposed["years"],"rounds":int(data.get("rounds",0) or 0)}

                kind_new=kind; title="Contre-offre envoyée"; body="Ta nouvelle proposition est partie chez l'agent. La réponse arrivera dans deux jours de carrière."

            elif kind=="market_offer" and data.get("outcome")=="player_counter":

                offered_now=int(data.get("offer_salary",0) or 0)

                info=f"SALAIRE RÉCLAMÉ PAR LE JOUEUR : {int(data.get('counter_salary',0) or 0):,} € / mois".replace(","," ")

                if offered_now:

                    info+=f"\nTa dernière proposition : {offered_now:,} € / mois".replace(","," ")

                proposed=self.counter_terms_dialog("Contre-proposition salariale","Le club vendeur accepte l'indemnité. Ajuste le salaire mensuel pour convaincre le joueur.",data.get("counter_salary",data.get("offer_salary",2500)),suffix=" € / mois",info=info)

                if not proposed: conn.close(); return

                new_data={key:value for key,value in data.items() if key not in ("outcome","counter_salary","division_gap","final_fee","final_salary")}

                new_data["offer_salary"]=proposed["amount"]; new_data["salary_round"]=int(data.get("salary_round",0))+1

                kind_new="market_offer"; title="Contre-proposition salariale envoyée"; body=f"Tu proposes {proposed['amount']:,} € / mois. Le joueur et son club répondront après délai.".replace(","," ")

            elif kind=="market_offer":

                ask=int(data.get("counter_fee",data.get("seller_ask",0)) or 0)

                current_bid=int(data.get("bid",0) or 0)

                info=f"PRIX DEMANDÉ PAR LE CLUB : {ask:,} €".replace(","," ")

                if current_bid:

                    info+=f"\nTon offre : {current_bid:,} €".replace(","," ")

                proposed=self.counter_terms_dialog("Contre-offre de transfert","Le club vendeur attend une proposition révisée. Sa réponse arrivera après délai.",data.get("counter_fee",data.get("bid",0)),info=info)

                if not proposed: conn.close(); return

                new_data={**data,"bid":proposed["amount"],"round":int(data.get("round",0))+1}

                kind_new="market_offer"; title="Contre-offre envoyée"; body="Ta nouvelle offre est transmise. Le club vendeur répondra dans deux jours de carrière."

            else:

                my_ask=int(data.get("counter_fee",data.get("fee",0)) or 0)

                buyer_limit=int(data.get("buyer_limit",0) or 0)

                info=f"Ton prix demandé : {my_ask:,} €".replace(","," ")

                if buyer_limit:

                    info+=f"\nMoyens annoncés de l'acheteur : jusqu'à {buyer_limit:,} €".replace(","," ")

                proposed=self.counter_terms_dialog("Contre-offre de transfert","Propose un montant de vente révisé. Le club reviendra avec une réponse plus tard.",data.get("counter_fee",data.get("fee",0)),info=info)

                if not proposed: conn.close(); return

                new_data={**data,"counter_fee":proposed["amount"],"round":int(data.get("round",0))+1}

                kind_new="transfer_sale_counter"; title="Contre-offre envoyée"; body=f"Ta demande de {proposed['amount']:,} € est partie à {data.get('buyer_name','l’acheteur')} ; réponse attendue sous deux jours.".replace(","," ")

            current=self._current_date(conn); due=(parse_iso(current)+timedelta(days=2)).isoformat()

            conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(message["id"],))

            queue_manager_message(conn,kind_new,title,body,current,due,new_data,is_read=True); add_news(conn,title,body)

            conn.commit(); conn.close(); self.refresh_all(); self.show_game_message("Négociation envoyée",body,"success"); return



        if action=="reject":

            if kind in ("contract_offer","free_agent_contract") and player_id:

                conn.execute("UPDATE player SET morale=MAX(0,morale-2) WHERE id=?",(player_id,))

            conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(message["id"],))

            add_news(conn,"Dossier refusé",message["title"])

            conn.commit(); conn.close(); self.refresh_all(); self.show_game_message("Décision enregistrée","Le dossier a été refusé et archivé.","info"); return



        if kind in ("contract_offer","free_agent_contract"):

            if data.get("outcome")=="unavailable":

                conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(message["id"],)); conn.commit(); conn.close(); self.refresh_all(); return

            salary=int(data.get("final_salary",data.get("counter_salary",data.get("offer_salary",0))))

            years=int(data.get("final_years",data.get("counter_years",data.get("offer_years",2))))

            prow=conn.execute("SELECT * FROM player WHERE id=?",(player_id,)).fetchone() if player_id else None

            demand_floor=0

            if prow:

                csign=conn.execute("SELECT division,reputation FROM club WHERE id=1").fetchone()

                demand_floor,_mv=player_salary_demand(prow,csign)

                if salary<demand_floor:

                    # Le joueur n'acceptera jamais moins que sa valeur : salaire

                    # ajuste au plancher (c'est sa demande, pas celle du club).

                    add_news(conn,"Salaire ajusté",f"{prow['first_name']} {prow['last_name']} n'acceptera pas moins de {demand_floor:,} € / mois — le contrat est signé à ce chiffre.".replace(","," "))

                    salary=demand_floor

            try:
                from wage_budget import can_add_player as _can_add_player

                _old_salary=int(prow["salary"] or 0) if (kind=="contract_offer" and prow) else 0

                _ok_wage,_wst,_proj=_can_add_player(self,conn,salary,_old_salary)

                if not _ok_wage:

                    conn.execute("UPDATE manager_message SET status='ready',is_read=0 WHERE id=?",(message["id"],))

                    conn.commit(); conn.close()

                    self.show_game_message("Plafond salarial",
                        f"Ce contrat porterait la masse salariale à {_proj:,} € pour un plafond de {_wst['cap']:,} €/mois. "
                        f"Réduis le salaire, vends un joueur ou refuse le dossier.".replace(","," "),"warning")

                    self.refresh_all(); return
            except Exception:
                pass

            if kind=="free_agent_contract":

                # Les salaires sont payes chaque mois (masse salariale mensuelle) :

                # l'accessibilite exige une couverture d'une annee de salaires.

                wage_year=salary*12

                budget=conn.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"]

                if wage_year>budget:

                    conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(message["id"],)); conn.commit()

                    conn.close(); self.show_game_message("Signature impossible",f"Le club ne peut pas assumer une année de salaires ({wage_year:,} €, budget : {budget:,} €).".replace(","," "),"warning"); self.refresh_all(); return

                pname_row=conn.execute("SELECT first_name,last_name FROM player WHERE id=?",(player_id,)).fetchone()

                pname=f"{pname_row['first_name']} {pname_row['last_name']}" if pname_row else "joueur libre"

                _win=self.transfer_window_state(conn)

                if not _win["open"]:

                    current=self._current_date(conn); arr_due=_win["reopens"].isoformat()

                    payload={"player_id":player_id,"fee":0,"salary":salary,"years":years,
                             "club_name":"Joueur libre","player_name":pname,"is_free":1,
                             "deferred":True,"effective_date":arr_due}

                    queue_manager_message(conn,"transfer_arrival","Recrutement • signature à l'ouverture",
                        f"{pname} rejoindra le club à l'ouverture du mercato, le {fmt_date_fr(arr_due)} — contrat de {salary:,} € / mois sur {years} an(s).".replace(","," "),
                        current,arr_due,payload,is_read=False)

                    self.close_player_dossiers(conn,player_id,keep_id=int(message["id"]))

                    data.update({"deferred":True,"effective_date":arr_due})

                    add_news(conn,"Mercato",f"Accord avec {pname} : signature effective le {fmt_date_fr(arr_due)}, à l'ouverture du mercato.")

                else:

                    number=next_shirt_number(conn,1)

                    conn.execute("UPDATE player SET club_id=1,is_free_agent=0,free_agent_since='',transfer_listed=0,shirt_number=?,salary=?,contract_years=?,morale=MIN(100,morale+4) WHERE id=?",(number,salary,years,player_id))

                    self.close_player_dossiers(conn,player_id,keep_id=int(message["id"]))
                    record_player_history(conn,player_id,1,"free","Signature libre après une offre de contrat")

                    add_news(conn,"Contrat signé",f"Joueur libre signé pour {years} an(s) à {salary:,} € / mois — payé chaque mois dans la masse salariale.".replace(","," "))

            else:

                # Prolongation d'un contrat du club : pas de debit (les recrutements restent payants),

                # mais le club doit pouvoir assumer au moins une annee du nouveau salaire.

                annual_cost=salary*12

                budget=conn.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"]

                if annual_cost>budget:

                    conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(message["id"],)); conn.commit()

                    conn.close(); self.show_game_message("Prolongation impossible",f"Le club ne peut pas assumer ce salaire : {annual_cost:,} € pour un an de contrat (budget : {budget:,} €).".replace(","," "),"warning"); self.refresh_all(); return

                conn.execute("UPDATE player SET salary=?,contract_years=?,morale=MIN(100,morale+4) WHERE id=? AND club_id=1",(salary,years,player_id))

                _pp=self._prepaid_wage_discard(player_id,conn)

                add_news(conn,"Contrat signé",f"Un nouveau contrat est signé pour {years} an(s) à {salary:,} € / mois.".replace(","," "))

        elif kind=="market_offer":

            fee=int(data.get("final_fee") or data.get("counter_fee") or data.get("bid") or data.get("fee") or 0)

            outcome=data.get("outcome")

            player=conn.execute("SELECT * FROM player WHERE id=? AND club_id=?",(player_id,data.get("club_id"))).fetchone()

            if not player:

                conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(message["id"],)); conn.commit()

                conn.close(); self.show_game_message("Transfert impossible","Le joueur n'est plus disponible dans son club.","warning"); self.refresh_all(); return

            if outcome=="seller_accepted":

                # Le club vendeur a accepté l'indemnité : le manager doit confirmer le contrat du joueur.

                confirmed= self.confirm_player_contract(player_id, player, fee, data.get("offer_salary"), int(data.get("offer_years",3)), data.get("club_name",""))

                if not confirmed:

                    conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(message["id"],)); conn.commit()

                    conn.close(); self.show_game_message("Transfert annulé","Le contrat du joueur n'a pas été confirmé : le transfert est abandonné.","info"); self.refresh_all(); return

                salary=int(confirmed[1]); years=int(confirmed[2])

                csign=conn.execute("SELECT division,reputation FROM club WHERE id=1").fetchone()

                demand_tx,_mv=player_salary_demand(player,csign)

                if salary<demand_tx:

                    add_news(conn,"Salaire ajusté",f"{player['first_name']} {player['last_name']} n'accepte pas un salaire inférieur à {demand_tx:,} € / mois — le contrat passe à ce chiffre.".replace(","," "))

                    salary=demand_tx

                budget=conn.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"]

                total_cost=fee+salary*12

                if total_cost>budget:

                    conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(message["id"],)); conn.commit()

                    conn.close(); self.show_game_message("Budget insuffisant",f"Le club ne peut pas assumer ce transfert : {fee:,} € d'indemnité + une année de salaires ({salary*12:,} €) (budget : {budget:,} €).".replace(","," "),"warning"); self.refresh_all(); return

                data.update({"outcome":"accepted","final_fee":fee,"final_salary":salary,"final_years":years})

            elif outcome!="accepted":

                # legacy / autres cas : on tente quand même la finalisation avec les données disponibles

                pass

            # Finalisation commune (accepted ou seller_accepted confirmé) :

            # le club debite l'indemnite ; les salaires passent dans la masse

            # salariale mensuelle (payee le 1er de chaque mois).

            budget=conn.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"]

            salary=int(data.get("final_salary") or (data.get("counter_salary") if outcome in ("counter","player_counter") else 0) or data.get("offer_salary") or int(player["salary"]*1.05))

            years=int(data.get("final_years",data.get("offer_years",3)))

            csign=conn.execute("SELECT division,reputation FROM club WHERE id=1").fetchone()

            demand_tx,_mv=player_salary_demand(player,csign)

            if salary<demand_tx:

                add_news(conn,"Salaire ajusté",f"{player['first_name']} {player['last_name']} n'accepte pas un salaire inférieur à {demand_tx:,} € / mois — le contrat passe à ce chiffre.".replace(","," "))

                salary=demand_tx

            try:
                from wage_budget import can_add_player
                _ok_wage,_wst,_proj=can_add_player(self,conn,salary,0)
                if not _ok_wage:
                    conn.commit(); conn.close()
                    self.show_game_message("Plafond salarial",
                        f"Ce transfert porterait la masse salariale à {_proj:,} € pour un plafond de {_wst['cap']:,} €/mois. "
                        f"Réduis le salaire proposé ou vends un joueur.".replace(","," "),"warning")
                    self.refresh_all(); return
            except Exception:
                pass

            total_cost=fee+salary*12

            if total_cost>budget:

                conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(message["id"],)); conn.commit()

                conn.close(); self.show_game_message("Transfert impossible",f"Le budget ne permet pas d'assumer ce transfert : {fee:,} € d'indemnité + une année de salaires ({salary*12:,} €) (budget : {budget:,} €).".replace(","," "),"warning"); self.refresh_all(); return

            conn.execute("UPDATE club SET budget=budget-? WHERE id=1",(fee,))

            _seller_id=int(data.get("club_id") or 0)
            if _seller_id and _seller_id!=1:
                conn.execute("UPDATE club SET budget=budget+? WHERE id=?",(fee,_seller_id))

            conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",(f"Transfert entrant {player['first_name']} {player['last_name']}",-fee,career_timestamp(conn),"Transfert"))

            # ARRIVEE DIFFEREE (retour joueur « il n'arrive pas du jour au

            # lendemain ») : l'indemnite est reglee MAINTENANT, le joueur

            # honore son delai de sortie et rejoint l'effectif sous 2 a 3

            # jours — le message transfer_arrival pesera au fil des jours.

            current_arr=self._current_date(conn)

            _win=self.transfer_window_state(conn)

            if _win["open"]:
                arrival_days=random.choice((2,3))
                arr_due=(parse_iso(current_arr)+timedelta(days=arrival_days)).isoformat()
            else:
                arr_due=_win["reopens"].isoformat()

            arrival_data={"player_id":player_id,"fee":fee,"salary":salary,"years":years,"club_name":data.get("club_name",""),

                          "player_name":f"{player['first_name']} {player['last_name']}","seller_club_id":int(data.get("club_id") or 0),

                          "deferred":not _win["open"],"effective_date":arr_due}

            data.update({"deferred":not _win["open"],"effective_date":arr_due})

            arrival_body=(f"Transfert réglé : {player['first_name']} {player['last_name']} quitte {data.get('club_name','son club')} pour {fee:,} €. "

                          f"Arrivée officielle annoncée pour le {fmt_date_fr(arr_due)} — l'effectif l'enregistrera ce jour-là.".replace(","," "))

            queue_manager_message(conn,"transfer_arrival","Recrutement • arrivée annoncée",arrival_body,current_arr,arr_due,arrival_data,is_read=False)

            self.close_player_dossiers(conn,player_id,keep_id=int(message["id"]))

            add_news(conn,"Mercato",f"Accord signé : {player['first_name']} {player['last_name']} rejoindra l'effectif le {fmt_date_fr(arr_due)} ({fee:,} €).".replace(","," "))

        elif kind in ("transfer_sale","transfer_sale_counter"):

            if player_id and int(player_id) in self.pending_departure_ids(conn):
                data["outcome"]="already_sold"; data["closed_reason"]="Départ déjà programmé à l'ouverture"
                conn.execute("UPDATE manager_message SET status='handled',is_read=1,action_data=? WHERE id=?",
                             (json.dumps(data,ensure_ascii=False),message["id"]))
                conn.commit(); conn.close()
                self.show_game_message("Joueur déjà vendu",
                    f"{data.get('player_name','Ce joueur')} a déjà un départ programmé à l'ouverture du mercato. Cette offre est classée.",
                    "info")
                self.refresh_all(); return
            fee=int(data.get("final_fee",data.get("counter_fee",data.get("fee",0))))

            buyer_id=int(data.get("buyer_id",0))

            player=conn.execute("""SELECT * FROM player WHERE id=? AND club_id=1
                                   AND COALESCE(is_free_agent,0)=0 AND COALESCE(retired,0)=0""",(player_id,)).fetchone()

            buyer=conn.execute("SELECT name,budget FROM club WHERE id=?",(buyer_id,)).fetchone()

            if player and buyer and int(buyer["budget"] or 0)<fee:

                conn.close(); self.show_game_message("Offre retirée",f"{buyer['name']} ne peut plus financer cette offre.","warning"); self.refresh_all(); return

            if not player or not buyer:

                if not player:

                    conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(message["id"],)); conn.commit()

                conn.close(); self.show_game_message("Offre expirée","Le joueur ou le club acheteur n'est plus disponible.","warning"); self.refresh_all(); return

            available=conn.execute("SELECT COUNT(*) FROM player WHERE club_id=1 AND COALESCE(is_free_agent,0)=0 AND injury_matches<=0 AND injury_days<=0 AND suspension_matches<=0").fetchone()[0]

            if player["injury_matches"]<=0 and available<=5:

                conn.close(); self.show_game_message("Effectif trop réduit","Accepter cette vente laisserait moins de cinq joueurs valides. Recrute d'abord un remplaçant.","warning"); return

            _win=self.transfer_window_state(conn)

            if not _win["open"]:

                dep_due=_win["reopens"].isoformat(); current=self._current_date(conn)

                payload={"player_id":player_id,"buyer_id":buyer_id,"buyer_name":buyer["name"],
                         "fee":fee,"player_name":f"{player['first_name']} {player['last_name']}",
                         "deferred":True,"effective_date":dep_due}

                queue_manager_message(conn,"transfer_departure","Vente • départ à l'ouverture",
                    f"Accord avec {buyer['name']} : {player['first_name']} {player['last_name']} rejoindra le club à l'ouverture du mercato, le {fmt_date_fr(dep_due)}, pour {fee:,} €.".replace(","," "),
                    current,dep_due,payload,is_read=False)

                self.close_player_dossiers(conn,player_id,keep_id=int(message["id"]))

                data.update({"deferred":True,"effective_date":dep_due})

                add_news(conn,"Mercato",f"Accord de vente : {player['first_name']} {player['last_name']} partira à l'ouverture du mercato le {fmt_date_fr(dep_due)}.")

            else:

                number=next_shirt_number(conn,buyer_id)

                conn.execute("UPDATE player SET club_id=?,transfer_listed=0,shirt_number=? WHERE id=?",(buyer_id,number,player_id))

                self._prepaid_wage_discard(player_id,conn)

                record_player_history(conn,player_id,buyer_id,"transfer",f"Départ vers {buyer['name']}")

                conn.execute("UPDATE club SET budget=budget+? WHERE id=1",(fee,))

                conn.execute("UPDATE club SET budget=budget-? WHERE id=?",(fee,buyer_id))

                conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",(f"Vente {player['first_name']} {player['last_name']}",fee,career_timestamp(conn),"Transfert"))

                add_news(conn,"Départ mercato",f"{player['first_name']} {player['last_name']} rejoint {buyer['name']} pour {fee:,} €.".replace(","," "))



        # ISSUE DU DOSSIER : l'onglet OFFRES doit afficher « vendu » / « accord clos »,
        # jamais un dossier accepté qui semble encore en attente.
        try:
            if kind=="market_offer":
                data.update({"outcome":"accepted","final_fee":fee,"final_salary":locals().get("salary",data.get("offer_salary"))})
            elif kind in ("transfer_sale","transfer_sale_counter"):
                data.update({"outcome":"accepted","final_fee":fee})
            elif kind in ("contract_offer","free_agent_contract"):
                data.update({"outcome":"accepted",
                             "final_salary":locals().get("salary",data.get("offer_salary")),
                             "final_years":locals().get("years",data.get("offer_years",2))})
            if kind in ("market_offer","transfer_sale","transfer_sale_counter","contract_offer","free_agent_contract"):
                conn.execute("UPDATE manager_message SET action_data=? WHERE id=?",
                             (json.dumps(data,ensure_ascii=False),message["id"]))
        except Exception:
            pass
        conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(message["id"],))

        self._offers_dirty=True
        conn.commit(); conn.close()

        if player_id and not data.get("deferred"):

            for zone in getattr(self,"pitch_zones",{}).values():

                if zone.player_id==player_id: zone.reset_zone()

            self.persist_tactics_settings()

        if data.get("deferred"):
            _when=fmt_date_fr(str(data.get("effective_date") or "")) if data.get("effective_date") else "à l'ouverture du mercato"
            self.refresh_all()
            self.show_game_message("Accord enregistré",f"Le changement de club interviendra à l'ouverture du mercato, le {_when}.","info")
        elif kind in ("contract_offer","free_agent_contract"):
            _sal=int(locals().get("salary",0) or 0); _yrs=int(locals().get("years",0) or 0)
            self.refresh_all()
            self.show_game_message("Contrat signé",f"{_yrs} an(s) à {_sal:,} € / mois. Le dossier est classé et l'effectif mis à jour.".replace(","," "),"success")
        else:
            self.refresh_all(); self.show_game_message("Décision enregistrée","Le dossier est traité. La carrière et le budget ont été mis à jour.","success")



    def _load_top_banner(self):

        """Charge la banniere du coach (ban2.png) au-dessus de la recherche.

        Cherche dans data (dossier) puis a la racine ; absent -> invisible.

        Un refresh ulterieur la charge si le fichier apparait."""

        if getattr(self,"_top_banner_ready",False):

            return

        try:

            for cand in (os.path.join(DATA_DIR,"ban2.png"), os.path.join(ASSET_DIR,"ban2.png"), os.path.join(BASE_DIR,"ban2.png")):

                if os.path.isfile(cand):

                    pm=_transparent_key_pixmap(cand,"white")

                    if pm.isNull(): pm=QPixmap(cand)

                    if not pm.isNull():

                        self.top_banner.setPixmap(pm.scaled(286,96,Qt.KeepAspectRatio,Qt.SmoothTransformation))

                        self.top_banner.setAlignment(Qt.AlignCenter)

                        self.top_banner.setStyleSheet("background:qlineargradient(x1:0,y1:0,x2:1,y2:1,stop:0 #0b1420,stop:1 #101d2f);border:1px solid #24344a;border-radius:12px;padding:2px;")

                        self._top_banner_ready=True

                        return

        except Exception as exc:

            self.log_error("top_banner",exc)



    @staticmethod
    def _menu_icon_pixmap(size, color="#aebbd0"):
        """MENU : trois barres horizontales dessinées par QPainter — centrage
        parfait par construction, lisible à toutes les tailles (18/20/22/24 px)."""
        pm=QPixmap(size,size); pm.fill(Qt.transparent)
        p=QPainter(pm)
        try:
            p.setRenderHint(QPainter.Antialiasing)
            paint=QColor(color)
            p.setPen(Qt.NoPen); p.setBrush(paint)
            n=3
            h=max(1.5,size*0.085)           # épaisseur d'une barre
            span=size*0.58                  # largeur utile
            gap=(size*0.62-(n*h))/(n-1)     # répartition harmonieuse
            top=(size-(n*h+(n-1)*gap))/2.0
            left=(size-span)/2.0
            for k in range(n):
                y=top+k*(h+gap)
                p.drawRoundedRect(QRectF(left,y,span,h), h/2.0, h/2.0)
        finally:
            p.end()
        return pm



    def draw_badge(self, initials, size=64, bg1="#2f6b4c", bg2="#18492f", pattern="shield"):
        # COULEURS DE SECOURS (retour « écussons parfois sans couleur ») :
        # des clubs IA peuvent avoir color1/color2 vides (vieilles sauvegardes).
        # On dérive alors une teinte stable de l'identité, jamais de blason vide.
        def _valid_col(c):
            try:
                col=QColor(c)
                return col.isValid() and col.alpha()>0
            except Exception:
                return False
        if not _valid_col(bg1):
            _seed=sum((i+1)*ord(ch) for i,ch in enumerate(str(initials or "FC")))
            bg1=QColor.fromHsv((_seed*37)%360,150,190).name()
        if not _valid_col(bg2):
            bg2=QColor(bg1).darker(165).name()

        # CACHE PIXMAP (retour « en RAM ») : un blason identique (mêmes initiales/

        # couleurs/taille) est REGENERÉ à chaque refresh sinon — des dizaines de

        # QPixmap par seconde qui s'entassent. Ici : rendu une fois, réutilisé.

        cache=getattr(self,"_badge_cache",None)

        if cache is None: cache=self._badge_cache={}

        if len(cache)>=600: cache.clear()

        key=(str(initials),int(size),str(bg1),str(bg2),str(pattern))

        hit=self._badge_cache.get(key)

        if hit is not None: return hit

        pix=QPixmap(size,size); pix.fill(Qt.transparent)
        p=QPainter(pix)
        try:
            p.setRenderHint(QPainter.Antialiasing)
            paint_crest(p,QRectF(size*0.05,size*0.04,size*0.90,size*0.92),bg1,bg2,initials,pattern)
        finally:
            p.end()
        self._badge_cache[key]=pix

        return pix



    def _club_kit_cache_row(self,club_id):
        """Couleurs + motif d'un club (cache : les avatars sont redessinés en masse)."""
        cache=getattr(self,"_club_kit_rows",None)
        if cache is None: cache=self._club_kit_rows={}
        key=int(club_id)
        if key in cache: return cache[key]
        conn=db()
        try: row=conn.execute("SELECT color1,color2,kit_pattern FROM club WHERE id=?",(key,)).fetchone()
        finally: conn.close()
        if len(cache)>120: cache.clear()
        cache[key]=row
        return row

    def _club_jersey_identity(self, player):
        """(club_id, couleur1, couleur2, motif) du maillot d'un joueur.

        Les joueurs LIBRES portent un maillot UNI neutre (graphite) : ils se
        distinguent immédiatement des joueurs sous contrat, même quand leur
        ancienne colonne club_id pointe encore vers un club."""
        try:
            cid=int(player["club_id"] if "club_id" in player.keys() and player["club_id"] is not None else 0)
        except Exception:
            cid=0
        try:
            free=bool(int(player["is_free_agent"] or 0)) if "is_free_agent" in player.keys() else False
        except Exception:
            free=False
        if free or cid<=0:
            return 0,"#565f6d","#232831","solid"
        own=(cid==1)
        club1=getattr(self,"club_color1",None) if own else None
        club2=getattr(self,"club_color2",None) if own else None
        club_kit=getattr(self,"club_kit_pattern",None) if own else None
        if not club1:
            try:
                row=self._club_kit_cache_row(cid)
                if row is not None:
                    club1=row["color1"] or club1
                    club2=row["color2"] or club2
                    club_kit=row["kit_pattern"] or club_kit
            except Exception:
                pass
        club1=club1 or "#2f6cb3"; club2=club2 or "#12243d"
        pattern=kit_pattern_for(cid,"",(club_kit or "vertical") if own else None)
        return cid,club1,club2,pattern

    def draw_player_avatar(self, player, size=42):
        """Portrait vectoriel : buste de maillot aux couleurs du club, numéro
        de dossard, marqueur de poste et statut (blessure / suspension).

        Le cache inclut l'identité du CLUB (couleurs + motif) : un joueur
        transféré affiche immédiatement son NOUVEAU maillot."""
        cache=getattr(self,"_avatar_cache",None)
        if cache is None: cache=self._avatar_cache={}
        if len(cache)>=600: cache.clear()
        try:
            _pid=int(player["id"]); _shirt=int(player["shirt_number"] or 0)
        except Exception:
            _pid=0; _shirt=0
        try: _pos=str(player["position"]) if "position" in player.keys() else "-"
        except Exception: _pos="-"
        cid,club1,club2,pattern=self._club_jersey_identity(player)
        status=str(player_status_glyph(player) or "")
        _key=(_pid,int(size),_shirt,_pos,cid,str(club1),str(club2),str(pattern),status)
        hit=cache.get(_key)
        if hit is not None: return hit
        pix=self._render_player_avatar(player,size)
        cache[_key]=pix
        return pix

    def _render_player_avatar(self, player, size=42):
        """Buste de maillot (moteur `paint_kit`) avec fond, halo et badges."""
        palettes={
            "Gardien": ("#1d6d76", "#0e2f3d"),
            "Défenseur": ("#315d9b", "#132a52"),
            "Ailier": ("#7649a6", "#2c1a4a"),
            "Pivot": ("#a4515a", "#4d2338"),
            "Universel": ("#497c62", "#1d332f"),
        }
        accent1,accent2=palettes.get(player["position"],("#41657e","#1d2c40"))
        cid,club1,club2,pattern=self._club_jersey_identity(player)
        shirt=int(player["shirt_number"] or 0) if "shirt_number" in player.keys() else 0
        initials="".join(part[0] for part in f"{player['first_name']} {player['last_name']}".split()[:2]).upper()
        number=str(shirt) if shirt else initials
        pos_letter=str(player["position"])[:1].upper() if "position" in player.keys() else "J"

        pix=QPixmap(size,size); pix.fill(Qt.transparent)
        painter=QPainter(pix)
        try:
            painter.setRenderHint(QPainter.Antialiasing)
            # Fond sombre arrondi
            bg=QLinearGradient(0,0,size,size)
            bg.setColorAt(0.0,QColor("#1b2941")); bg.setColorAt(1.0,QColor("#0a111c"))
            painter.setPen(Qt.NoPen); painter.setBrush(bg)
            painter.drawRoundedRect(QRectF(1,1,size-2,size-2),size*.22,size*.22)
            # Halo aux couleurs du club derrière le buste
            glow=QColor(club1); glow.setAlpha(88)
            halo=QRadialGradient(QPointF(size*0.5,size*0.72),size*0.72)
            halo.setColorAt(0.0,glow); halo.setColorAt(1.0,QColor(0,0,0,0))
            painter.setBrush(halo)
            painter.drawRoundedRect(QRectF(1,1,size-2,size-2),size*.22,size*.22)
            # Buste du maillot (le numéro est dessiné par paint_kit)
            paint_kit(painter,QRectF(-size*0.03,size*0.31,size*1.06,size*0.73),
                      club1,club2,pattern,border=False,bust=True,number=number)
            # Ombre douce du bas + contour de la vignette
            shade=QLinearGradient(0,size*0.72,0,size)
            shade.setColorAt(0.0,QColor(0,0,0,0)); shade.setColorAt(1.0,QColor(0,0,0,120))
            painter.setPen(Qt.NoPen); painter.setBrush(shade)
            painter.drawRoundedRect(QRectF(1,1,size-2,size-2),size*.22,size*.22)
            painter.setBrush(Qt.NoBrush)
            painter.setPen(QPen(QColor(255,255,255,38),max(1.0,size*.02)))
            painter.drawRoundedRect(QRectF(1,1,size-2,size-2),size*.22,size*.22)
            # Marqueur de poste (coin supérieur droit)
            painter.setPen(Qt.NoPen); painter.setBrush(QColor(accent1))
            painter.drawEllipse(QRectF(size*.79,size*.05,size*.16,size*.16))
            painter.setPen(QPen(QColor("#eef4fb"),max(1,size*.012)))
            painter.setFont(QFont("Segoe UI",max(6,int(size*.10)),QFont.Black))
            painter.drawText(QRectF(size*.79,size*.05,size*.16,size*.16),Qt.AlignCenter,pos_letter)
            # Statut indisponible (coin supérieur gauche)
            status=player_status_glyph(player)
            if status:
                bx,by,bs=size*.05,size*.05,size*.16
                painter.setPen(QPen(QColor("#0c1320"),max(1,size*.014)))
                if status=="🚑":
                    painter.setBrush(QColor("#ff8291")); painter.drawEllipse(QRectF(bx,by,bs,bs))
                    painter.setPen(QPen(QColor("#ffffff"),max(1,size*.028)))
                    painter.drawLine(QPointF(bx+bs*.5,by+bs*.2),QPointF(bx+bs*.5,by+bs*.8))
                    painter.drawLine(QPointF(bx+bs*.2,by+bs*.5),QPointF(bx+bs*.8,by+bs*.5))
                else:
                    painter.setBrush(QColor("#e64545")); painter.drawRect(QRectF(bx+bs*.08,by+bs*.02,bs*.84,bs*.7))
                    painter.setPen(QPen(QColor("#0c1320"),max(1,size*.012)))
                    painter.drawRect(QRectF(bx+bs*.08,by+bs*.02,bs*.84,bs*.7))
        finally:
            painter.end()
        return pix

    def set_fixture_visual(self, home_name, away_name, manager_home=True, club_colors=("#702ce5", "#28205a")):

        """Synchronize the dashboard and match-center fixture crests and names."""

        # COULEURS RÉELLES DES DEUX CLUBS (retour « le logo adverse perd ses
        # couleurs dans le match ») : on lit la fiche du club par son nom.
        neutral = ("#3b5688", "#1d294d")
        def _club_identity(name, fallback):
            """(couleur1, couleur2, id, motif) : le MÊME maillot que la fiche club."""
            try:
                c=db()
                row=c.execute("SELECT id,color1,color2,kit_pattern FROM club WHERE name=?",(str(name),)).fetchone()
                c.close()
                if row and row["color1"]:
                    return (row["color1"], row["color2"] or fallback[1], int(row["id"]), row["kit_pattern"])
            except Exception:
                pass
            return (fallback[0], fallback[1], 0, None)
        own_identity=(club_colors[0] or neutral[0], club_colors[1] or neutral[1], 1, getattr(self,"club_kit_pattern",None))
        home_ident = own_identity if manager_home else _club_identity(home_name, neutral)
        away_ident = _club_identity(away_name, neutral) if manager_home else own_identity
        home_colors = home_ident[:2]
        away_colors = away_ident[:2]

        home_initials = "".join(part[0] for part in home_name.split()[:2]).upper() or "FC"

        away_initials = "".join(part[0] for part in away_name.split()[:2]).upper() or "FC"

        for label, text, initials, colors, size in (

            (getattr(self, "match_home_label", None), home_name, home_initials, home_colors, 76),

            (getattr(self, "match_away_label", None), away_name, away_initials, away_colors, 76),

            (getattr(self, "match_home_badge", None), None, home_initials, home_colors, 76),

            (getattr(self, "match_away_badge", None), None, away_initials, away_colors, 76),

            (getattr(self, "dashboard_home_badge", None), None, home_initials, home_colors, 48),

            (getattr(self, "dashboard_away_badge", None), None, away_initials, away_colors, 48),

        ):

            if label is None:

                continue

            if text is not None:

                label.setText(text)

            else:

                _size=max(16,int(label.width()) or int(size))

                label.setPixmap(self.draw_badge(initials, size=_size, bg1=colors[0], bg2=colors[1]))



        # MATCH 2D : le maillot remplace l'écusson dans l'en-tête du match
        # (motif stable par club, couleurs du club).
        try:
            for lbl, ident, size in ((getattr(self,"match_home_badge",None), home_ident, 66),
                                     (getattr(self,"match_away_badge",None), away_ident, 66)):
                if lbl is not None:
                    lbl.setPixmap(kit_pixmap(ident[0], ident[1], kit_pattern_for(ident[2], "", ident[3]), size))
        except Exception:
            pass

    def tactical_player_rating(self,player,zone_name):

        role=zone_name.upper()

        if "GARDIEN" in role: zone_name="Gardien"

        elif "DÉF" in role or "FIXO" in role: zone_name="Défenseur G"

        elif "PIVOT" in role: zone_name="Pivot"

        elif "ALA" in role or "AIL" in role: zone_name="Ailier"

        weights={

            "Gardien":{"goalkeeper":.60,"passing":.15,"defense":.10,"stamina":.15},

            "Défenseur G":{"defense":.45,"stamina":.25,"passing":.20,"technique":.10},

            "Défenseur D":{"defense":.45,"stamina":.25,"passing":.20,"technique":.10},

            "Ailier":{"technique":.35,"passing":.30,"stamina":.20,"finishing":.15},

            "Pivot":{"finishing":.40,"technique":.25,"stamina":.20,"passing":.15},

        }.get(zone_name,{"technique":.25,"passing":.2,"finishing":.2,"defense":.2,"stamina":.15})

        raw=sum(int(player[key])*weight for key,weight in weights.items())

        condition=float(player["condition"])/100

        return round(max(1,min(20,(raw*(.78+.22*condition))/5)),1)



    def set_tactical_zone_player(self,zone,player):

        zone.player_id=player["id"]

        zone.player_label=f"{player['first_name']} {player['last_name']}"

        zone.player_rating=self.tactical_player_rating(player,zone.rating_role)
        zone.player_status=player_status_glyph(player) or ""
        zone.player_number=int(player["shirt_number"] or 0)
        zone.player_form=rating20(player["condition"])
        zone.player_stats=(f"TEC {rating20(player['technique'])} · FIN {rating20(player['finishing'])} · "
                           f"DÉF {rating20(player['defense'])}")
        try:
            zone.kit=kit_pixmap(getattr(self,"club_color1","#1f8a4d"),getattr(self,"club_color2","#0f3d27"),
                                kit_pattern_for(1,"",getattr(self,"club_kit_pattern",None)),42)
        except Exception:
            zone.kit=None
        zone.update()

        short_name=zone.player_label if len(zone.player_label)<=16 else f"{player['first_name'][:1]}. {player['last_name']}"

        zone.setCursor(Qt.OpenHandCursor)

        status=player_status_glyph(player)

        if status=="🟥": edge="#f1a34f"

        elif status: edge="#ff8291"

        else: edge="#62e5a9" if zone.player_rating>=15 else "#c39cff"

        form=rating20(player["condition"])

        shirt=int(player["shirt_number"] or 0)

        prefix=f"{status} " if status else ""

        zone.setText(f"{prefix}#{shirt:02d}  {zone.position_label.upper()}\n{short_name}\n{stars5(round(zone.player_rating))} {zone.player_rating:.1f}/20 · F{form}")

        zone.setStyleSheet(f"QLabel{{background:rgba(10,16,29,225);color:#eaf0fb;border:1px solid {edge};border-radius:10px;padding:6px;font-weight:800;font-size:9pt;}} QLabel:hover{{border:2px solid #d5aaff;background:rgba(35,25,61,240);}}")

        if status:

            disc=player_discipline_text(player)

            zone.setToolTip(f"#{shirt:02d} • {zone.player_label} • {disc or player_status_glyph(player)}")

        else:

            zone.setToolTip(f"#{shirt:02d} • {zone.player_label} • {zone.position_label} • note {zone.player_rating:.1f}/20 • "
                            f"{zone.player_stats} • clique pour la fiche détaillée")



    ROLE_BY_POSITION={"Gardien":"Gardien","Défenseur":"Fixo","Ailier":"Ala","Pivot":"Pivot","Universel":"Universel"}

    def natural_tactical_role(self,position):
        return self.ROLE_BY_POSITION.get(str(position),"Universel")

    def tactical_instruction_rows(self,conn=None):
        own=False
        if conn is None: conn=db(); own=True
        try:
            return {int(r["player_id"]):dict(r) for r in conn.execute("SELECT * FROM tactical_instruction").fetchall()}
        finally:
            if own: conn.close()

    def set_tactical_instruction(self,player_id,field,value):
        if field not in ("role","pressing","defensive"): return
        try:
            c=db()
            c.execute("INSERT OR IGNORE INTO tactical_instruction(player_id) VALUES(?)",(int(player_id),))
            c.execute(f"UPDATE tactical_instruction SET {field}=? WHERE player_id=?",(str(value or ""),int(player_id)))
            c.commit(); c.close()
            self.refresh_tactical_familiarity()
        except Exception as exc:
            self.log_error("set_tactical_instruction",exc)

    def tactical_settings_signature(self,conn=None):
        own=False
        if conn is None: conn=db(); own=True
        try:
            parts=[self.formation.currentText(),self.mentality.currentText(),self.tempo.currentText(),
                   self.press_intensity.currentText(),self.block_height.currentText(),self.attack_width.currentText(),
                   self.attack_focus.currentText(),self.rotation_style.currentText(),self.goalkeeper_distribution.currentText()]
            for r in conn.execute("SELECT player_id,role,pressing,defensive FROM tactical_instruction ORDER BY player_id").fetchall():
                parts.append(f"{r['player_id']}:{r['role']}:{r['pressing']}:{r['defensive']}")
            for key in ("setpiece_corner","setpiece_freekick","setpiece_exit","powerplay"):
                row=conn.execute("SELECT value FROM meta WHERE key=?",(key,)).fetchone()
                parts.append(f"{key}={row['value'] if row else ''}")
            return hashlib.md5("|".join(parts).encode("utf-8")).hexdigest()
        finally:
            if own: conn.close()

    def update_tactical_familiarity(self,conn=None):
        own=False
        if conn is None: conn=db(); own=True
        try:
            sig=self.tactical_settings_signature(conn)
            prev=conn.execute("SELECT value FROM meta WHERE key='tactics_signature'").fetchone()
            row=conn.execute("SELECT value FROM meta WHERE key='tactics_familiarity'").fetchone()
            fam=int(row["value"] or 60) if row else 60
            if not prev:
                fam=60
            elif str(prev["value"] or "")==sig:
                try:
                    _vf=conn.execute("SELECT video_level FROM facility WHERE id=1").fetchone()
                    _vid=int(_vf["video_level"] or 0) if _vf else 0
                except Exception:
                    _vid=0
                fam=min(100,fam+8+2*_vid)
            else:
                fam=max(30,fam-35)
            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('tactics_signature',?)",(sig,))
            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('tactics_familiarity',?)",(str(fam),))
            if own: conn.commit()
            return fam
        except Exception as exc:
            self.log_error("update_tactical_familiarity",exc); return 60
        finally:
            if own: conn.close()

    def refresh_tactical_familiarity(self):
        if not hasattr(self,"tactical_familiarity_label"): return
        try:
            c=db(); row=c.execute("SELECT value FROM meta WHERE key='tactics_familiarity'").fetchone(); c.close()
            fam=int(row["value"] or 60) if row else 60
            color="#7de0aa" if fam>=80 else "#ffd166" if fam>=55 else "#ff9daa"
            self.tactical_familiarity_label.setText(f"FAMILIARITÉ {fam}%")
            self.tactical_familiarity_label.setStyleSheet(f"color:{color};font-weight:900;")
            self.tactical_familiarity_label.setToolTip("Un plan nouveau met quelques matchs à être pleinement efficace : plus la familiarité est haute, plus le collectif exprime son potentiel.")
        except Exception as exc:
            self.log_error("refresh_tactical_familiarity",exc)

    def open_tactical_instructions(self):
        try:
            dlg=self._build_tactical_instructions_dialog()
            if dlg is not None: dlg.exec()
        except Exception as exc:
            self.log_error("open_tactical_instructions",exc)

    def _build_tactical_instructions_dialog(self):
        """Construit le dialogue (séparé de exec pour rester testable)."""
        conn=db()
        players=conn.execute("""SELECT * FROM player WHERE club_id=1 AND COALESCE(is_free_agent,0)=0
                                 ORDER BY CASE position WHEN 'Gardien' THEN 0 WHEN 'Défenseur' THEN 1
                                          WHEN 'Ailier' THEN 2 WHEN 'Pivot' THEN 3 ELSE 4 END, last_name""").fetchall()
        instr=self.tactical_instruction_rows(conn)
        meta={r["key"]:(r["value"] or "") for r in conn.execute(
            "SELECT key,value FROM meta WHERE key IN ('setpiece_corner','setpiece_freekick','setpiece_exit','powerplay')").fetchall()}
        frow=conn.execute("SELECT value FROM meta WHERE key='tactics_familiarity'").fetchone()
        fam=max(0,min(100,int((frow["value"] if frow else 60) or 60)))
        conn.close()
        c1=str(getattr(self,"club_color1","#c47220")); c2=str(getattr(self,"club_color2","#14171f"))
        fam_color="#8fc4a8" if fam>=75 else "#d9b46a" if fam>=50 else "#c99a9a"

        dlg=QDialog(self); dlg.setWindowTitle("Consignes tactiques")
        dlg.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dlg.resize(900,700)
        dlg.setStyleSheet(
            "QDialog{background:#080f18;}"
            "QTabWidget::pane{border:0;background:transparent;margin-top:6px;}"
            "QTabBar::tab{background:#101b2a;border:1px solid #26374d;border-radius:8px;"
            "color:#9fb0c6;font-size:8pt;font-weight:900;letter-spacing:.6px;padding:6px 18px;margin-right:6px;}"
            "QTabBar::tab:selected{background:#1b3045;border-color:#4f6c8b;color:#edf5fc;}"
            "QTabBar::tab:hover{color:#eaf2fb;border-color:#3d5a7a;}")
