    def _matchday_pulse_tick(self):

        self._start_logo_breath()

        self._start_screen_tick()

        """Fait respirer le bouton MATCHDAY (halo vert neon) quand un match est prets a jouer."""

        btn=getattr(self,"play_matchday_btn",None)

        if not btn or not btn.isVisible(): return

        if not btn.isEnabled():

            if getattr(self,"_matchday_neon_on",False):

                self._matchday_neon_on=False

                btn.setStyleSheet("background:#202722;color:#8ea197;border:1px solid #35443a;font-weight:800;border-radius:14px;padding:10px 8px;font-size:11pt;")

            return

        self._matchday_neon_on=True

        self._matchday_phase=(getattr(self,"_matchday_phase",0.0)+0.085)%2.0

        t=self._matchday_phase if self._matchday_phase<=1.0 else 2.0-self._matchday_phase

        glow=int(55+45*t)

        btn.setStyleSheet(

            "QPushButton{background:qlineargradient(x1:0,y1:0,x2:1,y2:1,"

            f"stop:0 #{'3f8f6a' if t>.5 else '347a5b'},stop:1 #1f5a40);"

            "color:#eaf4ee;font-weight:1000;font-size:9.5pt;border-radius:11px;padding:7px 8px;"

            f"border:1px solid rgba(150,200,175,{glow});}}")

        btn.setToolTip("Matchday ! Clique pour ouvrir le centre de match.")



