        def _hero_kpi(title):
            fr=QFrame(); fr.setObjectName("StartHeroKpi")
            fr.setStyleSheet("QFrame#StartHeroKpi{background:rgba(7,13,24,150);border:1px solid #2b3c57;border-radius:9px;}")
