    def activate_career(self,path):

        global DB_PATH

        old_path=DB_PATH; DB_PATH=os.path.abspath(path)

        try:

            set_active_save_path(DB_PATH); init_db()

            self.ensure_club_setup()

            conn=db(); done=conn.execute("SELECT value FROM meta WHERE key='club_setup_done'").fetchone(); conn.close()

            if not done or done["value"]!="1":

                DB_PATH=old_path; set_active_save_path(old_path); self.refresh_save_catalog(); return

            self.match_state=None; self.timer.stop()

            self._set_career_nav_locked(False)

            self._tactics_config_loaded=False; self.load_tactics_settings()

            if not self._tactics_config_loaded and not self._selected_lineup_ids(): self.auto_pick_lineup()

            self.refresh_all(); self.show_page(0); self.app_stack.setCurrentWidget(self.game_shell)

            self.setWindowTitle(f"Futsal Manager — {self.club_label.text()}")

        except Exception as exc:

            DB_PATH=old_path; set_active_save_path(old_path); self.log_error("activate_career",exc)

            self.show_game_message("Sauvegarde",f"Impossible d'ouvrir cette partie : {exc}","error")

        self.refresh_save_catalog()



    def create_new_career(self):

        global DB_PATH

        dialog=ClubSetupDialog(self, LEAGUE_DEFINITIONS, facility_capacity)

        if dialog.exec()!=QDialog.Accepted: return

        identity=dialog.values()

        path=unique_save_path(identity["name"])

        old_path=DB_PATH; DB_PATH=path

        try:

            init_db(fresh_universe=True,selected_division=identity["division"],identity=identity)

            conn=db()

            conn.execute("UPDATE club SET name=?,color1=?,color2=?,season=1,division=? WHERE id=1",(identity["name"],identity["color1"],identity["color2"],identity["division"]))

            conn.execute("UPDATE career SET [current_date]='2026-07-01',matchday=1,wins=0,draws=0,losses=0,goals_for=0,goals_against=0,points=0 WHERE id=1")

            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('club_setup_done','1')")

            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('career_created','1')")

            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('save_slot_name',?)",(identity["name"],))

            add_news(conn,"Nouvelle carrière",f"{identity['name']} lance son projet le 1er août.")

            conn.commit(); conn.close()

            set_active_save_path(path); self.match_state=None; self.timer.stop()

            self._set_career_nav_locked(False)

            self._tactics_config_loaded=False; self.load_tactics_settings()

            if not self._tactics_config_loaded: self.auto_pick_lineup()

            self.refresh_all(); self.show_page(0); self.app_stack.setCurrentWidget(self.game_shell)

            self.setWindowTitle(f"Futsal Manager — {identity['name']}")

        except Exception as exc:

            DB_PATH=old_path; set_active_save_path(old_path); self.log_error("create_new_career",exc)

            self.show_game_message("Nouvelle carrière",f"La sauvegarde n'a pas pu être créée : {exc}","error")

        self.refresh_save_catalog()



    def show_start_screen(self):

        if self.match_state and not self.match_state.get("finished",True):

            self.show_game_message("Match en cours","Termine le match avant de retourner au menu de carrière.","warning"); return

        self.save_active_career(show_notice=False)

        self.refresh_save_catalog(); self.app_stack.setCurrentWidget(self.start_screen)



    def save_active_career(self,show_notice=True):

        temp_path=DB_PATH+".checkpoint.tmp"

        try:

            conn=db(); conn.execute("CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT)")

            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('last_saved_at',?)",(datetime.now().isoformat(timespec="minutes"),))

            conn.commit(); conn.close()

            source=db(); destination=db_path(temp_path)

            source.backup(destination); destination.close(); source.close()

            replaced=False; last_err=None

            for attempt in range(8):   # verrou transitoire (antivirus/indexeur) : on retente jusqu'a ~5 s

                try:

                    os.replace(temp_path,DB_PATH); replaced=True; break

                except PermissionError as perr:

                    last_err=perr; time.sleep(0.25*attempt+0.25)

            if not replaced: raise last_err

            set_active_save_path(DB_PATH); self.refresh_save_catalog()

            if show_notice: self.show_game_message("Partie sauvegardée",f"{self.club_label.text()} • {self.side_date_label.text()}\nTa carrière est enregistrée.","success")

            return True

        except Exception as exc:

            try:

                if os.path.exists(temp_path): os.remove(temp_path)

            except OSError:

                pass

            self.log_error("save_active_career",exc)

            self.show_game_message("Sauvegarde impossible",str(exc),"error")

            return False



    def save_career_as(self):

        global DB_PATH

        dialog=QDialog(self); dialog.setWindowTitle("Enregistrer sous"); dialog.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dialog.setFixedWidth(520)

        root=QVBoxLayout(dialog); root.setContentsMargins(16,16,16,16); root.setSpacing(10)

        panel=QFrame(); panel.setObjectName("HeroPanel"); pl=QVBoxLayout(panel); pl.setContentsMargins(14,12,14,12)

        head=QLabel("NOUVEL EMPLACEMENT DE SAUVEGARDE"); head.setStyleSheet("font-weight:900;color:#d3b4ff;")

        desc=QLabel("Une copie séparée sera créée. Ta sauvegarde actuelle restera intacte."); desc.setWordWrap(True); desc.setObjectName("Muted")

        pl.addWidget(head); pl.addWidget(desc); root.addWidget(panel)

        _season_txt=self.season_label.text().split('•')[0].strip()

        _mseason=re.search(r"\d+",_season_txt)

        name=QLineEdit(); name.setText(f"{self.club_label.text()} - Saison {_mseason.group(0) if _mseason else _season_txt}"); name.setPlaceholderText("Nom de cette sauvegarde"); root.addWidget(name)

        buttons=QHBoxLayout(); buttons.addStretch(); cancel=QPushButton("ANNULER"); cancel.clicked.connect(dialog.reject)

        save=QPushButton("CRÉER LA COPIE"); save.setObjectName("Primary"); save.clicked.connect(dialog.accept); buttons.addWidget(cancel); buttons.addWidget(save); root.addLayout(buttons)

        if dialog.exec()!=QDialog.Accepted: return False

        slot_name=name.text().strip() or self.club_label.text()

        if not self.save_active_career(show_notice=False): return False

        path=unique_save_path(slot_name)

        try:

            source=db(); destination=db_path(path); source.backup(destination); destination.close(); source.close()

            snapshot=db_path(path); snapshot.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('save_slot_name',?)",(slot_name,)); snapshot.commit(); snapshot.close()

            DB_PATH=path; set_active_save_path(path); self.refresh_save_catalog()

            self.show_game_message("Copie créée",f"La carrière est maintenant enregistrée sous « {slot_name} ». L'ancienne sauvegarde reste disponible.","success")

            return True

        except Exception as exc:

            self.log_error("save_career_as",exc); self.show_game_message("Copie impossible",str(exc),"error"); return False



