    def open_start_options(self):

        """Options accessibles DEPUIS L'ÉCRAN D'ACCUEIL (retour joueur) :

        thème, taille du texte et mode de fenêtre sans charger une carrière."""

        dlg=GameOptionsDialog(self.game_options,self)

        if dlg.exec()!=QDialog.Accepted: return

        self.game_options.update(dlg.values()); save_game_options(self.game_options)

        app=QApplication.instance()

        app.setFont(QFont("Segoe UI",int(self.game_options["font_size"])))

        app.setStyleSheet(style_for_theme(self.game_options["theme"]))
        apply_theme_to_tree(self,self.game_options["theme"]=="Clair")
        try: self.start_screen.light=(self.game_options["theme"]=="Clair"); self.start_screen.update()
        except Exception: pass

        if self.game_options["window_mode"]=="Plein écran": self.showFullScreen()

        elif self.game_options["window_mode"]=="Maximisé": self.showMaximized()

        else: self.showNormal(); self.resize(1440,900)

        self.refresh_save_catalog()



    def set_club_kit(self,key):
        """Change le motif de maillot du club depuis OPTIONS."""
        try:
            conn=db(); conn.execute("UPDATE club SET kit_pattern=? WHERE id=1",(str(key),))
            conn.commit()
            row=conn.execute("SELECT kit_pattern FROM club WHERE id=1").fetchone(); conn.close()
            self.club_kit_pattern=row["kit_pattern"] if row else key
            try: self._club_kit_rows={}
            except Exception: pass
            try: self._avatar_cache={}
            except Exception: pass
            self.refresh_all()
        except Exception as exc:
            self.log_error("set_club_kit",exc)

    def open_game_options(self):

        opts=dict(self.game_options or {})
        try:
            _c=db(); _r=_c.execute("SELECT kit_pattern FROM club WHERE id=1").fetchone(); _c.close()
            if _r and _r["kit_pattern"]: opts["kit_pattern"]=_r["kit_pattern"]
        except Exception: pass
        dlg=GameOptionsDialog(opts,self,cheat_cb=self.apply_cheat,kit_cb=self.set_club_kit)

        if dlg.exec()!=QDialog.Accepted: return

        values=dlg.values(); self.game_options.update(values)

        save_game_options(self.game_options)
        try:
            _dc=db(); _dc.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('difficulty_mode',?)",(self.game_options.get("difficulty","Normale"),)); _dc.commit(); _dc.close()
            self._difficulty_mode_cache=None
        except Exception: pass

        app=QApplication.instance(); app.setFont(QFont("Segoe UI",int(self.game_options["font_size"]))); app.setStyleSheet(style_for_theme(self.game_options["theme"]))
        apply_theme_to_tree(self,self.game_options["theme"]=="Clair")
        try: self.start_screen.light=(self.game_options["theme"]=="Clair"); self.start_screen.update()
        except Exception: pass

        if self.game_options["window_mode"]=="Plein écran": self.showFullScreen()

        elif self.game_options["window_mode"]=="Maximisé": self.showMaximized()

        else: self.showNormal(); self.resize(1440,900)

        self.refresh_all(); self.refresh_save_catalog()



    def apply_cheat(self,code):

        """Coups de pouce du panneau TRICHE : budget, condition, moral. Effets

        immediats dans la carriere ouverte — volontaires et sans sanction."""

        kinds={"budget_50000":50_000,"budget_250000":250_000,"budget_1000000":1_000_000}

        try:

            conn=db()

            if code in kinds:

                conn.execute("UPDATE club SET budget=budget+? WHERE id=1",(kinds[code],))

                conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,'Coup de main du board (triche)',?,?,'Divers')",(kinds[code],career_timestamp(conn)))

                conn.commit(); conn.close(); self.refresh_all()

                self.show_game_message("Triche",f"+{kinds[code]:,} € ajoutés au budget du club.".replace(","," "),"success")

                return

            if code=="heal_condition":

                conn.execute("UPDATE player SET condition=100 WHERE club_id=1"); conn.commit(); conn.close(); self.refresh_all()

                self.show_game_message("Triche","Tout l'effectif est à 100 % de condition.","success")

                return

            if code=="morale_max":

                conn.execute("UPDATE player SET morale=100 WHERE club_id=1"); conn.commit(); conn.close(); self.refresh_all()

                self.show_game_message("Triche","Le moral de tout l'effectif est au maximum.","success")

                return

            conn.close()

        except Exception as exc:

            self.log_error("apply_cheat",exc)

            self.show_game_message("Triche",f"Action impossible : {exc}","error")



    def _refresh_futsal_finance_panel(self,club):

        """Equilibre du mois en cours (lecture finance_tx du mois courant)."""

        if not hasattr(self,"fut_card_pay"):

            return

        try:

            conn=db()

            career=conn.execute('SELECT career."current_date" d FROM career WHERE id=1').fetchone()

            month=(career["d"] or "2026-01")[:7]

            rows=conn.execute("SELECT category,amount FROM finance_tx WHERE club_id=1 AND created_at LIKE ?",(month+"%",)).fetchall()

            conn.close()

            pay=sum(int(t["amount"]) for t in rows if t["category"] in ("Salaire","Staff"))

            incomes=sum(int(t["amount"]) for t in rows if int(t["amount"])>0)

            charges=abs(sum(int(t["amount"]) for t in rows if int(t["amount"])<0))

            net=incomes-charges

            def put(frame,value,negative_warn=False):

                big=frame.findChild(QLabel,"BigNumber")

                big.setText(f"{value:+,} €".replace(","," ") if not negative_warn else f"{value:,} €".replace(","," "))

                if negative_warn:

                    big.setStyleSheet("font-weight:900;color:#ff8d8d;" if value<0 else "")

            put(self.fut_card_pay,pay)

            put(self.fut_card_income,incomes)

            put(self.fut_card_charge,-charges)

            put(self.fut_card_net,net)

            try:
                from wage_budget import status as _wage_status
                _wc=db()
                try: _ws=_wage_status(self,_wc)
                finally: _wc.close()
                _label=("MARGE" if _ws["room"]>=0 else "DÉPASSEMENT")
                if hasattr(self,"wage_cap_label"):
                    self.wage_cap_label.setText(
                        f"PLAFOND MASSE SALARIALE  •  {_ws['total']:,} / {_ws['cap']:,} €/mois  •  "
                        f"{_label} {abs(_ws['room']):,} €  •  joueurs {_ws['players']:,} €  •  staff {_ws['staff']:,} €".replace(","," "))
                    self.wage_cap_label.setStyleSheet(
                        "font-size:7.5pt;font-weight:900;color:" +
                        ("#9ce6bf" if _ws["room"]>=0 else "#ff8d8d") + ";")
                    _cd=_ws.get("cap_details") or {}
                    self.wage_cap_label.setToolTip(
                        ("Plafond calculé sur 90 % des revenus estimés, 2,5 % du budget par mois "
                         "et l'ambition du club, ajusté à la réputation.\n"
                         f"Revenus estimés : {_cd.get('income',0):,} €/mois  •  "
                         f"budget : {_cd.get('budget',0):,} €  •  "
                         f"réputation : {_cd.get('reputation',0)}/100  •  "
                         f"facteur réputation : x{_cd.get('reputation_factor',1.0)}").replace(","," "))
            except Exception:
                pass

            big_net=self.fut_card_net.findChild(QLabel,"BigNumber")

            big_net.setStyleSheet("font-weight:1000;color:#ff8d8d;" if net<0 else "font-weight:1000;color:#9ce6bf;")

        except Exception as exc:

            self.log_error("futsal_finance_panel",exc)



    def eventFilter(self,obj,event):

        """Clic sur la barre de recherche globale -> page RECHERCHE.

        + TUILES JOUEURS EN VUE -> fiche du joueur (retour « joueurs cliquables »)."""

        try:

            if hasattr(self,"search_input") and obj is self.search_input and event.type()==QEvent.MouseButtonPress:

                if self.stack.currentIndex()!=12: self.show_page(12)

        except Exception:

            pass

        try:

            if event.type() in (QEvent.MouseButtonPress,QEvent.MouseButtonRelease) and isinstance(obj,QLabel) and int(obj.property("player_id") or 0)>0:

                if event.type()==QEvent.MouseButtonRelease and event.button()==Qt.LeftButton:

                    pid=int(obj.property("player_id") or 0)

                    try: self.open_player_profile(pid)

                    except Exception: pass

                return True

        except Exception:

            pass

        return super().eventFilter(obj,event)



    def _on_global_search(self, text):

        """Barre de recherche globale : ouvre la page RECHERCHE et applique le texte saisi."""

        text=(text or "").strip()

        if not text: return

        if hasattr(self,"search_query") and not getattr(self,"_search_sync",False):

            self._search_sync=True

            self.search_query.setText(text)

            self._search_sync=False

        if self.stack.currentIndex()!=12:

            self.show_page(12)



    def _search_entry_price(self,p):

        """Prix d'entree approximatif : 0 pour un libre, demande pour un liste, fourchette basse sinon."""

        if p["is_free_agent"]: return 0

        if p["transfer_listed"]: return int(p["market_value"] or 0)

        try:

            low,high,exact=scout_value_band(p,int(p["scout_knowledge"] or 0))

            return int(low)

        except Exception:

            return int(p["market_value"] or 0)



