    def _tr_after_modal(self,dialog):

        """DESTRUCTION D'UNE BOITE MODALE RECCURENTE (retour « la RAM montait

        pendant la saison ») : les rapports de match, avant-match, messages...

        s'ouvrent DOUZAINES de fois par saison ; si leur wrapper Python rescapé

        reste accroche, toute la carte QFrame#MatchPlayerCard (~14/widget) et les

        tuiles du match restent VIVANTES en C++. setParent(None) + deleteLater

        + flush garantit la libération réelle des charges qu'ils logent."""

        try:

            dialog.setParent(None); dialog.deleteLater()

        except Exception:

            pass

        self._flush_deleted_widgets()



    # --------------------------------------------------- COLONNES DE L'EFFECTIF

    # (retour « choisir les colonnes et les déplacer ») : un ordre logique

    # sauvegardé dans data/roster_columns.json + un dialogue cases à cocher

    # (visibilité) et flèches (ordre). Le remplissage par index logique reste

    # inchangé ; on ne fait qu'appliquer la position visuelle et la visibilité.

    def _roster_cols_load(self):

        self._roster_col_order=list(range(self.roster_table.columnCount()))

        self._roster_col_hidden=set()

        try:

            import json as _json

            with open(ROSTER_COLS_FILE,"r",encoding="utf-8") as f:

                spec=_json.load(f)

            n=self.roster_table.columnCount()

            order=[int(c) for c in (spec.get("order") or []) if 0<=int(c)<n]

            order += [c for c in range(n) if c not in order]

            self._roster_col_order=order[:n]

            self._roster_col_hidden={int(c) for c in (spec.get("hidden") or []) if 0<=int(c)<n}

        except Exception:

            pass

        self._apply_roster_columns()



    def _roster_cols_save(self):

        try:

            import json as _json

            hc=self.roster_table.horizontalHeader()

            order=[hc.logicalIndex(v) for v in range(self.roster_table.columnCount())]

            with open(ROSTER_COLS_FILE,"w",encoding="utf-8") as f:

                _json.dump({"order":order,"hidden":sorted(self._roster_col_hidden)},f)

            self._roster_col_order=order

        except Exception:

            pass



    def _apply_roster_columns(self):

        try:

            t=self.roster_table; hc=t.horizontalHeader()

            hc.blockSignals(True)

            n=t.columnCount()

            pos=0

            # ordre : on applique la sequence memorisee

            for c in self._roster_col_order[:n]:

                v=hc.visualIndex(c)

                if v!=pos and v>=0:

                    hc.moveSection(v,pos)

                pos+=1

            for c in range(n):

                t.setColumnHidden(c, c in self._roster_col_hidden)

            # STRETCH DYNAMIQUE (retour « la colonne joueur cache NIV/POT ») :

            # la colonne JOUEUR n'est plus en stretch permanent — elle voit une

            # largeur guidee (246 px) et la DERNIERE colonne visible absorbe le

            # reste ; deplacer/masquer redistribue l'espace sans ecraser la fin.

            last_vis=None

            for c in self._roster_col_order[:n]:

                if c not in self._roster_col_hidden: last_vis=c

            for c in range(n):

                hc.setSectionResizeMode(c, QHeaderView.Interactive)

            hc.setStretchLastSection(False)

            if t.isColumnHidden(2) is False and last_vis!=2:

                hc.resizeSection(2,182)

            # La colonne ETAT garde assez de place pour le point + le libelle.
            if not t.isColumnHidden(0):
                hc.resizeSection(0,82)

            # La DERNIERE colonne visible absorbe l'espace restant : le tableau
            # tient dans la page au lieu de deborder a droite.
            hc.setStretchLastSection(True)

            hc.blockSignals(False)

        except Exception as exc:

            self.log_error("roster_cols_apply",exc)



    def open_roster_columns_dialog(self):

        try:

            t=self.roster_table

            if t is None: return

            dialog=QDialog(self); dialog.setWindowTitle("Colonnes de l'effectif")

            dialog.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dialog.setFixedWidth(560)

            dialog.setAttribute(Qt.WA_StyledBackground,True)

            root=QVBoxLayout(dialog); root.setContentsMargins(18,16,18,16); root.setSpacing(10)

            panel=QFrame(); panel.setObjectName("HeroPanel"); pl=QVBoxLayout(panel); pl.setContentsMargins(14,10,14,10)

            ttl=QLabel("CHOISIR ET DÉPLACER LES COLONNES"); ttl.setStyleSheet("font-size:13pt;font-weight:1000;color:#f2f4fb;")

            sub=QLabel("Coche pour afficher, flèches pour ordonner. Le réglage est sauvegardé pour ta carrière.")

            sub.setObjectName("Muted"); sub.setWordWrap(True)

            pl.addWidget(ttl); pl.addWidget(sub); root.addWidget(panel)

            n=t.columnCount()

            hc=t.horizontalHeader()

            rows=[]

            def _rebuild_rows():

                while box_lay.count():

                    it=box_lay.takeAt(0)

                    wd=it.widget()

                    if wd is not None: wd.setParent(None); wd.deleteLater()

                rows.clear()

                vis_order=[hc.logicalIndex(v) for v in range(n) if not t.isColumnHidden(hc.logicalIndex(v))]

                hidden_extra=[hc.logicalIndex(v) for v in range(n) if t.isColumnHidden(hc.logicalIndex(v))]

                seq=vis_order+hidden_extra

                for pos_,c in enumerate(seq):

                    fr=QFrame(); fr.setStyleSheet("QFrame{background:#131c2e;border:1px solid #26334d;border-radius:10px;}")

                    fl=QHBoxLayout(fr); fl.setContentsMargins(10,4,6,4); fl.setSpacing(6)

                    chk=QCheckBox(hdr_name(c)); chk.setChecked(not t.isColumnHidden(c))

                    chk.setStyleSheet("QCheckBox{font-size:9.5pt;font-weight:800;color:#e8effa;}")

                    def _vis(state, chk=chk, c=c):

                        # ATTENTION : toggled(bool) passe l'etat en arg POSITIONNEL,

                        # il emplirait le parametre chk — on l'accepte dans `state`.

                        t.setColumnHidden(c, not chk.isChecked())

                        if chk.isChecked(): self._roster_col_hidden.discard(c)

                        else: self._roster_col_hidden.add(c)

                        self._apply_roster_columns()

                        self._roster_cols_save(); _rebuild_rows()

                    chk.toggled.connect(_vis)

                    fl.addWidget(chk,1)

                    up=QPushButton("▲"); up.setFixedSize(30,26); up.setToolTip("Remonter cette colonne")

                    dn=QPushButton("▼"); dn.setFixedSize(30,26); dn.setToolTip("Descendre cette colonne")

                    for b in (up,dn):

                        b.setStyleSheet("QPushButton{background:#1a2740;color:#cfe0f8;border:1px solid #33456a;border-radius:7px;font-size:9pt;}"

                                        "QPushButton:disabled{color:#556179;border-color:#28324a;}")

                        b.setEnabled(pos_>0 if b is up else pos_<n-1)

                    def _mv(delta,c=c):

                        seq2=[hc.logicalIndex(v) for v in range(n)]

                        i=seq2.index(c)

                        j=max(0,min(n-1,i+delta))

                        if i==j: return

                        seq2.insert(j,seq2.pop(i))

                        hc.blockSignals(True)

                        for v2,logical in enumerate(seq2):

                            vi=hc.visualIndex(logical)

                            if vi!=v2: hc.moveSection(vi,v2)

                        t.setColumnHidden(c, c in self._roster_col_hidden)

                        hc.blockSignals(False)

                        # l'ordre global peut avoir change : la DERNIERE visible

                        # repasse en stretch (sinon bandeau vide a droite)

                        self._roster_col_order=[hc.logicalIndex(v) for v in range(n)]

                        self._apply_roster_columns()

                        self._roster_cols_save(); _rebuild_rows()

                    up.clicked.connect(lambda _=False,d=-1: _mv(d))  # pas par c, on epingl ce qui est affiche depuis seq affichage courant

                    dn.clicked.connect(lambda _=False,d=1: _mv(d))

                    fl.addWidget(up); fl.addWidget(dn)

                    box_lay.addWidget(fr); rows.append(fr)

            hdr_name=lambda c: t.horizontalHeaderItem(c).text() if t.horizontalHeaderItem(c) else f"Col {c}"

            body=QScrollArea(); body.setWidgetResizable(True); body.setFrameShape(QFrame.NoFrame)

            box=QWidget(); box_lay=QVBoxLayout(box); box_lay.setContentsMargins(0,0,4,0); box_lay.setSpacing(5); box_lay.addStretch()

            body.setWidget(box); root.addWidget(body,1)

            btn_row=QHBoxLayout()

            reset_btn=QPushButton("⟲  RÉINITIALISER"); reset_btn.setObjectName("Primary"); reset_btn.setMinimumHeight(40)

            def _reset():

                self._roster_col_order=list(range(n)); self._roster_col_hidden=set()

                self._apply_roster_columns(); self._roster_cols_save(); _rebuild_rows()

            reset_btn.clicked.connect(_reset)

            close_btn=QPushButton("FERMER  ✓"); close_btn.setMinimumHeight(40)

            close_btn.clicked.connect(dialog.accept)

            btn_row.addWidget(reset_btn); btn_row.addStretch(); btn_row.addWidget(close_btn)

            root.addLayout(btn_row)

            _rebuild_rows()

            dialog.exec()

            self._tr_after_modal(dialog)

            # les etoiles POT/NIV peuvent avoir ete masquees : mettre a jour le detail si visible

            try: self.update_player_panel(self.roster_table.currentRow(),self.roster_table.currentColumn())

            except Exception: pass

        except Exception as exc:

            self.log_error("roster_cols_dialog",exc)



    def _purge_list_item_widgets(self,list_widget):

        """PURGE ANTI-FUITE (retour « grosses montees en RAM pendant la saison ») :

        PySide6 ne libere PAS les widgets posés via setItemWidget quand la liste est

        vidée (.clear()) — chaque refresh_all reconstruisait calendrier + classement

        (~300 QLabels par jour devenant des orphelins). Ici on detache puis

        deleteLater chaque widget d'item AVANT le clear."""

        if list_widget is None: return

        try:

            for i in range(list_widget.count()):

                item=list_widget.item(i)

                wid=list_widget.itemWidget(item)

                if wid is not None:

                    # Masquer AVANT de détacher : sinon le widget devient une
                    # fenêtre native top-level (icône Python) le temps du delete.
                    wid.hide(); wid.setAttribute(Qt.WA_DontShowOnScreen, True)

                    list_widget.removeItemWidget(item)

                    wid.setParent(None); wid.deleteLater()

        except Exception:

            pass



    def _flush_deleted_widgets(self):

        """TRAITEMENT DES SUPPRESSIONS DIFFEREES SANS ATTENDRE LA BOUCLE :

        deleteLater ne s'exécute que quand Qt traite ses evenements — pendant un

        match/sim (boucle getée) le backlog s'entasse sinon. SendPostedEvents

        (DeferredDelete) les commet immédiatement ; appelé en fin de refresh_all."""

        try:

            from PySide6.QtCore import QCoreApplication, QEvent

            QCoreApplication.sendPostedEvents(None,QEvent.DeferredDelete)

        except Exception:

            pass



