        rfl.addLayout(form_row)

        res_list=QListWidget(); res_list.setObjectName("ClubStandings"); res_list.setSpacing(3); res_list.setSelectionMode(QAbstractItemView.NoSelection); res_list.setAlternatingRowColors(False)

        res_list.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)

        for f in recent_all:

            own_home=int(f["home_club_id"])==club_id

            own_g=int(f["home_goals"] if own_home else f["away_goals"] or 0); opp_g=int(f["away_goals"] if own_home else f["home_goals"] or 0)

            tag="V" if own_g>opp_g else ("N" if own_g==opp_g else "D")

            rcolor="#6ce0ad" if tag=="V" else ("#aeb9d0" if tag=="N" else "#ff8d97")

            fx_name=str(f["fixture_type"]) if "fixture_type" in f.keys() else "championship"

            md_tag=fixture_tag(f["matchday"],fx_name)

            hg=int(f["home_goals"] or 0); ag=int(f["away_goals"] or 0)

            card=QFrame(); card.setObjectName("ResultCard")

            card.setStyleSheet(f"QFrame#ResultCard{{background:#101a2b;border:1px solid #26334c;border-left:3px solid {rcolor};border-radius:8px;}}")

            rrow=QHBoxLayout(card); rrow.setContentsMargins(8,4,10,4); rrow.setSpacing(9)

            badge=QLabel(tag); badge.setAlignment(Qt.AlignCenter); badge.setFixedSize(26,26)

            badge.setStyleSheet(f"background:{rcolor};color:#0a1420;border-radius:13px;font-weight:1000;font-size:10.5pt;")

            rrow.addWidget(badge)

            venue=QLabel("DOM" if own_home else "EXT"); venue.setAlignment(Qt.AlignCenter)

            venue.setStyleSheet("background:#1c2b44;color:#9db3d2;border-radius:7px;padding:2px 7px;font-size:7.5pt;font-weight:900;")

            rrow.addWidget(venue)

            opp_dot=QLabel(); opp_dot.setFixedSize(10,10)

            opp_c=str(f["away_c1"] if own_home else f["home_c1"] or "#8899aa")

            opp_dot.setStyleSheet(f"background:{opp_c};border:1px solid rgba(255,255,255,90);border-radius:5px;")

            opp_name=str(f["away_name"] if own_home else f["home_name"])

            opp_dot.setToolTip(opp_name)

            rrow.addWidget(opp_dot)

            teams=QLabel(opp_name); teams.setMinimumWidth(0); teams.setSizePolicy(QSizePolicy.Ignored,QSizePolicy.Preferred)

            teams.setStyleSheet("font-size:9.5pt;font-weight:900;color:#eff3fa;")

            rrow.addWidget(teams,1)

            score=QLabel(f"{hg}  —  {ag}"); score.setStyleSheet(f"font-size:11pt;font-weight:1000;color:{'#ffffff' if tag!='N' else '#dfe5f0'};")

            rrow.addWidget(score)

            try: short_date=f"{f['fixture_date'][8:10]}/{f['fixture_date'][5:7]}"

            except (TypeError,IndexError): short_date=fmt_date_fr(f['fixture_date'])

            meta=QLabel(f"{md_tag}  •  {short_date}"); meta.setToolTip(fmt_date_fr(f["fixture_date"]))

            meta.setStyleSheet("font-size:8pt;font-weight:800;color:#8b98b3;")

            rrow.addWidget(meta)

            item=QListWidgetItem(); item.setSizeHint(QSize(120,40)); res_list.addItem(item)

            self._set_item_widget(res_list,item,card)

        rfl.addWidget(res_list,1)

        rfl.addWidget(QLabel("PROCHAINS RENDEZ-VOUS"))

        up_list=QListWidget(); up_list.setObjectName("ClubStandings"); up_list.setSpacing(3); up_list.setSelectionMode(QAbstractItemView.NoSelection); up_list.setAlternatingRowColors(False)

        up_list.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)

        for f in [f for f in club_fixtures if not int(f["played"])][:4]:

            own_home=int(f["home_club_id"])==club_id

            fx_type=str(f["fixture_type"]) if "fixture_type" in f.keys() else "championship"

            tag=fixture_tag(f["matchday"],fx_type)

            ucard=QFrame(); ucard.setObjectName("UpcomingCard")

            ucard.setStyleSheet("QFrame#UpcomingCard{background:#0f1827;border:1px solid #243148;border-radius:8px;}")

            urow=QHBoxLayout(ucard); urow.setContentsMargins(8,4,10,4); urow.setSpacing(9)

            utag=QLabel(tag); utag.setAlignment(Qt.AlignCenter)

            utag.setStyleSheet("background:#2c2140;color:#d5bfff;border-radius:7px;padding:2px 7px;font-size:7.5pt;font-weight:900;")

            urow.addWidget(utag)

            uvenue=QLabel("DOM" if own_home else "EXT"); uvenue.setAlignment(Qt.AlignCenter)

            uvenue.setStyleSheet("background:#1c2b44;color:#9db3d2;border-radius:7px;padding:2px 7px;font-size:7.5pt;font-weight:900;")

            urow.addWidget(uvenue)

            uteams=QLabel(f"{f['home_name']}  —  {f['away_name']}"); uteams.setMinimumWidth(0); uteams.setSizePolicy(QSizePolicy.Ignored,QSizePolicy.Preferred)

            uteams.setStyleSheet("font-size:9pt;font-weight:700;color:#cdd7e6;")

            uteams.setToolTip(f"{f['home_name']} — {f['away_name']}")

            urow.addWidget(uteams,1)

            try: udate=f"{f['fixture_date'][8:10]}/{f['fixture_date'][5:7]}"

            except (TypeError,IndexError): udate=fmt_date_fr(f["fixture_date"])

            umeta=QLabel(udate); umeta.setToolTip(fmt_date_fr(f["fixture_date"]))

            umeta.setStyleSheet("font-size:8pt;font-weight:800;color:#8b98b3;")

            urow.addWidget(umeta)

            uitem=QListWidgetItem(); uitem.setSizeHint(QSize(120,34)); up_list.addItem(uitem)

            self._set_item_widget(up_list,uitem,ucard)

        rfl.addWidget(up_list,1)

        season_layout.addWidget(results_frame,1)

        if int(club_id)==1:

            club_tabs.addTab(season_page,"SAISON")



        # --- Onglet EFFECTIF (cartes joueurs, double-clic = fiche) ---

        roster_page=QWidget(); roster_layout=QVBoxLayout(roster_page); roster_layout.setContentsMargins(8,8,8,8); roster_layout.setSpacing(7)

        title_players=QHBoxLayout(); heading=QLabel("EFFECTIF DU CLUB"); heading.setStyleSheet("font-weight:900;letter-spacing:1px;color:#d6c4ff;")

        title_players.addWidget(heading); title_players.addStretch(); help_label=QLabel("Double-clique un joueur pour ouvrir sa fiche."); help_label.setObjectName("Muted"); title_players.addWidget(help_label)

        roster=QListWidget(); roster.setObjectName("ClubRosterCards"); roster.setSpacing(5); roster.setSelectionMode(QAbstractItemView.SingleSelection); roster.setEditTriggers(QAbstractItemView.NoEditTriggers)

        roster.itemDoubleClicked.connect(lambda item:self.open_club_player_profile(item.data(Qt.UserRole)))

        def _short_money(v):
            v=int(v or 0)
            if abs(v)>=1_000_000: return f"{v/1_000_000:.1f} M €".replace(".",",")
            if abs(v)>=1000: return f"{v//1000} k €"
            return f"{v} €"

        for player in players:

            item=QListWidgetItem(); item.setData(Qt.UserRole,player["id"]); item.setSizeHint(QSize(700,74))

            _pos_color={"Gardien":"#b9a56e","Défenseur":"#7e96b0","Ailier":"#7fa58f","Pivot":"#b08d7a","Universel":"#9789b0"}.get(str(player["position"]),"#7f91a8")

            card=QFrame(); card.setObjectName("ClubPlayerCard"); card.setStyleSheet(f"QFrame#ClubPlayerCard{{background:#111a2a;border:1px solid #27334a;border-left:3px solid {_pos_color};border-radius:9px;}}")

            row=QHBoxLayout(card); row.setContentsMargins(8,3,8,3); row.setSpacing(8)

            avatar=QLabel(); avatar.setFixedSize(40,40); avatar.setPixmap(self.draw_player_avatar(player,40)); row.addWidget(avatar)

            text=QVBoxLayout(); text.setSpacing(1); pname=QLabel(f"#{int(player['shirt_number'] or 0):02d}  {player['first_name']} {player['last_name']}"); pname.setMinimumWidth(0); pname.setStyleSheet("font-weight:900;color:#eff2fa;")

            level=player_level_from_row(player); knowledge=int(player["scout_knowledge"] or 0)

            club_query=db(); club_acc_row=club_query.execute("SELECT accuracy FROM scout_report WHERE player_id=?",(player["id"],)).fetchone(); club_query.close()

            club_acc=float(club_acc_row["accuracy"]) if club_acc_row and club_acc_row["accuracy"] is not None else 0.6

            evaluated=self.scout_staff_hired and knowledge>=75 or player["club_id"]==1

            _pgoals=int(player['season_goals'] or 0); _psaves=int(player['season_saves'] or 0)

            pstats=f"  •  {_pgoals} {'but' if _pgoals==1 else 'buts'}" if str(player["position"])!="Gardien" else f"  •  {_psaves} {'arrêt' if _psaves==1 else 'arrêts'}"

            shown_level=(f"{level}/20 {stars5(level)}" if evaluated else (scout_level_text(player,knowledge,club_acc) if knowledge>=25 else "Niveau à évaluer"))

            pmeta=QLabel(f"{player['position']}  •  {player['age']} ans  •  {shown_level}"+pstats)

            pmeta.setObjectName("Muted"); pmeta.setStyleSheet("font-size:8pt;color:#9eabc1;")

            disc=player_discipline_text(player)

            status=(disc.split(" (")[0] if disc else "LIBRE" if player["is_free_agent"] else "")

            if status: pmeta.setText(pmeta.text()+f"  •  {status}")

            _val=int(player["market_value"] or 0); _cy=int(player["contract_years"] or 0)
            _mor=int(player["morale"] or 0); _form=rating20(player["condition"])
            pmeta2=QLabel(f"Valeur {_short_money(_val)}  •  Contrat {_cy} {'an' if _cy==1 else 'ans'}  •  Moral {_mor}  •  Forme {_form}/20")
            pmeta2.setObjectName("Muted"); pmeta2.setStyleSheet("font-size:7.5pt;color:#8494ac;")
            text.addWidget(pname); text.addWidget(pmeta); text.addWidget(pmeta2); row.addLayout(text,1)

