    def club_facility_profile(self,club):

        if int(club["id"])==1:

            conn=db(); facility=conn.execute("SELECT * FROM facility WHERE id=1").fetchone(); conn.close()

            return dict(facility),True

        division=max(1,min(6,int(club["division"] or 3))); reputation=max(0,int(club["reputation"] or 0))

        arena=max(1,min(8,round((7-division)*.72+reputation/34)))

        level=max(1,min(6,7-division+reputation//55))

        return {"arena_level":arena,"medical_level":level,"youth_level":max(1,min(6,level-1+int(reputation>=45))),

                "marketing_level":max(1,min(6,level+int(reputation>=55))),"lighting_level":max(1,min(8,arena)),

                "parking_level":max(1,min(8,arena)),"has_bar":int(reputation>=25),

                "has_vip":int(reputation>=65),"has_shop":int(reputation>=40),"ticket_price":max(6,min(35,8+reputation//12+arena//3)),
                # Batiments secondaires : eux aussi propres au club, plus d'heritage.
                "has_rental_courts":int(reputation>=35 or division<=4),
                "has_events_hall":int(reputation>=55 or division<=3),
                "has_fan_zone":int(reputation>=45 or division<=4),
                "video_level":max(1,min(2,1+int(reputation>=60))),
                "volunteer_level":max(1,min(3,1+int(reputation>=40)+int(reputation>=70))),
                "restaurant_level":max(1,min(3,1+int(reputation>=50)+int(reputation>=75)))},False



    def open_club_player_profile(self,player_id):

        conn=db(); player=conn.execute("SELECT p.*,CASE WHEN p.is_free_agent=1 THEN 'Joueur libre' ELSE c.name||' · Ligue '||c.division END club_name,c.division club_division,COALESCE(sr.knowledge,0) scout_knowledge,COALESCE(sr.reports,0) scout_reports FROM player p JOIN club c ON c.id=p.club_id LEFT JOIN scout_report sr ON sr.player_id=p.id WHERE p.id=?",(player_id,)).fetchone(); conn.close()

        if player: self.show_player_profile(player)



    def _scout_player_from_club(self,player_id,club_dialog):

        if self.request_scout_report(player_id,effort="standard"): club_dialog.accept()



    def _fit_roster_columns(self):

        """Colonnes redimensionnables ; largeurs memorisees par l'utilisateur."""

        table=getattr(self,"roster_table",None)

        if table is None: return

        header=table.horizontalHeader()

        from PySide6.QtWidgets import QHeaderView as _HV

        if not getattr(self,"_roster_width_hook",False):

            header.setSectionResizeMode(_HV.Interactive)

            header.setStretchLastSection(False)

            header.sectionResized.connect(self._roster_width_changed)

            self._roster_width_hook=True

        saved=None

        try:

            conn=db(); row=conn.execute("SELECT value FROM meta WHERE key='roster_column_widths'").fetchone(); conn.close()

            if row and row["value"]: saved=json.loads(row["value"])

        except Exception:

            saved=None

        defaults={0:82,1:36,2:182,3:76,4:42,5:32,6:32,7:32,8:32,9:32,10:32,
                  11:44,12:66,13:66,14:46,15:58,16:70,17:74,18:36,19:44,
                  20:38,21:50}

        widths=defaults

        if isinstance(saved,dict):

            widths={int(k):int(v) for k,v in saved.items() if str(k).isdigit() and int(v)>=24}

        for column,width in widths.items():

            try: header.resizeSection(column,width)

            except Exception: pass

        # Les largeurs mémorisées peuvent déborder après un changement de fenêtre :
        # on les ramène proportionnellement dans la largeur visible.
        try:

            avail=max(540,self.width()-440)

            visible=[c for c in range(table.columnCount()) if not table.isColumnHidden(c)]

            total=sum(header.sectionSize(c) for c in visible)

            if total>int(avail*1.45):

                # Largeurs mémorisées trop larges (ancien écran / colonnes tirées) :
                # on repart des largeurs de référence, lisibles et compactes.
                for column,width in defaults.items():
                    try: header.resizeSection(column,width)
                    except Exception: pass

        except Exception: pass

        header.setStretchLastSection(True)

    def _roster_width_changed(self,*_args):

        timer=getattr(self,"_roster_width_timer",None)

        if timer is None:

            timer=QTimer(self); timer.setSingleShot(True); timer.setInterval(450)

            timer.timeout.connect(self._save_roster_column_widths)

            self._roster_width_timer=timer

        timer.start()

    def _save_roster_column_widths(self):

        try:

            table=getattr(self,"roster_table",None)

            if table is None: return

            header=table.horizontalHeader()

            widths={str(c):int(header.sectionSize(c)) for c in range(header.count())}

            conn=db(); conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('roster_column_widths',?)",(json.dumps(widths),)); conn.commit(); conn.close()

        except Exception as exc:

            self.log_error("roster_column_widths",exc)

