    def _tactics(self):

        w,l = self.page_shell("Tactiques", "PLACE TES JOUEURS  •  CHOISIS TON PLAN ET PRÉPARE LE MATCH", icon="🧠")

        # --- Barre de pilotage compacte : plan complet sur 2 lignes fines ; le terrain occupe le reste.

        def tactical_control(parent,label,items,row,col):

            box=QVBoxLayout(); box.setSpacing(2)

            caption=QLabel(label.upper()); caption.setObjectName("Muted"); caption.setWordWrap(True); caption.setMinimumWidth(0); caption.setStyleSheet("font-size:7pt;font-weight:800;letter-spacing:.5px;")

            combo=QComboBox(); combo.addItems(items); combo.setMinimumHeight(26); combo.setMinimumWidth(0); combo.setMaximumWidth(190); combo.setSizePolicy(QSizePolicy.Ignored,QSizePolicy.Fixed)
            combo.setSizeAdjustPolicy(QComboBox.AdjustToMinimumContentsLengthWithIcon)
            combo.setMinimumContentsLength(6)

            box.addWidget(caption); box.addWidget(combo); parent.addLayout(box,row,col)

            return combo

        # Panneau avancé (replié par défaut, dépliable d'un clic)

        self.tactical_advanced_panel=QFrame(); self.tactical_advanced_panel.setObjectName("Panel")

        ag=QGridLayout(self.tactical_advanced_panel); ag.setContentsMargins(10,6,10,6); ag.setHorizontalSpacing(10); ag.setVerticalSpacing(5)

