    def update_tactical_phase_cards(self):

        if not hasattr(self,"tactic_phase_cards"): return

        _width_label={"Étroit":"étroite","Équilibré":"équilibrée","Large":"large"}.get(self.attack_width.currentText(),self.attack_width.currentText().lower())

        self.tactic_phase_cards[0].setText(f"{self.formation.currentText()} • largeur {_width_label}"
                                           + (f" • axe {self.attack_focus.currentText().lower()}" if self.attack_focus.currentText()!="Équilibré" else ""))

        self.tactic_phase_cards[1].setText(f"Pressing {self.press_intensity.currentText().lower()} • relance {self.goalkeeper_distribution.currentText().lower()}")

        self.tactic_phase_cards[2].setText(f"Bloc {self.block_height.currentText().lower()} • rotations {self.rotation_style.currentText().lower()}")



