    def _calendar_tab_changed(self,index):

        try:

            if int(index)==2: self.refresh_calendar_cup()

            QTimer.singleShot(0,self.refresh_all)

        except Exception as exc:

            self.log_error("calendar_tab_changed",exc)

    def refresh_calendar_cup(self):
        """Onglet COUPE du calendrier : parcours du club, tour par tour."""
        if not hasattr(self,"calendar_cup_list"): return
        conn=db()
        try:
            club=conn.execute("SELECT season FROM club WHERE id=1").fetchone()
            season=int(club["season"] or 1) if club else 1
            rows=conn.execute("""SELECT f.*,hc.name hn,ac.name an
                                 FROM fixture f JOIN club hc ON hc.id=f.home_club_id
                                 JOIN club ac ON ac.id=f.away_club_id
                                 WHERE f.season=? AND f.fixture_type='cup'
                                   AND (f.home_club_id=1 OR f.away_club_id=1)
                                 ORDER BY f.matchday,f.fixture_date""",(season,)).fetchall()
        finally:
            conn.close()
        self.calendar_cup_list.blockSignals(True); self.calendar_cup_list.clear()
        won=0; lost=0
        for f in rows:
            played=int(f["played"] or 0); home=bool(int(f["home_club_id"])==1)
            hg=int(f["home_goals"] or 0); ag=int(f["away_goals"] or 0)
            our,their=(hg,ag) if home else (ag,hg)
            if played:
                if our>their: won+=1
                else: lost+=1
            opponent=str(f["an"] if home else f["hn"])
            tag=fixture_tag(int(f["matchday"]),"cup")
            venue="DOM" if home else "EXT"
            score=f"{our} - {their}" if played else "à jouer"
            it=QListWidgetItem(f"  {tag}   ·   {fmt_date_fr(f['fixture_date'])}   ·   {venue} vs {opponent}   ·   {score}")
            it.setSizeHint(QSize(320,34))
            it.setData(Qt.UserRole,{"id":int(f["id"]),"played":played,"home":home,"our":our,"their":their,
                                    "opp":opponent,"date":str(f["fixture_date"]),"tag":tag,"score":score})
            it.setForeground(QColor("#8fe0a3" if played and our>their else "#ff9daa" if played else "#e6c07a"))
            self.calendar_cup_list.addItem(it)
        self.calendar_cup_list.blockSignals(False)
        if hasattr(self,"cup_empty_label"):
            self.cup_empty_label.setVisible(self.calendar_cup_list.count()==0)
        if hasattr(self,"cup_calendar_hint"):
            if not rows: status="AUCUN TOUR TIRÉ (la coupe démarre en novembre)"
            elif lost: status="ÉLIMINÉ"
            elif won: status="ENCORE EN LICE"
            else: status="À JOUER"
            self.cup_calendar_hint.setText(f"{len(rows)} tour(s)  •  {won} qualification(s)  •  {status}")
        if self.calendar_cup_list.count():
            self.calendar_cup_list.setCurrentRow(0)
        else:
            self.cup_calendar_browser.setHtml("<div style='font-family:Segoe UI;color:#9ba9c0;padding:18px'>Aucun tour de coupe pour l'instant : le tirage arrive en cours de saison.</div>")

    def on_calendar_cup_selected(self,row):
        if row<0 or not hasattr(self,"cup_calendar_browser"): return
        it=self.calendar_cup_list.item(row)
        d=it.data(Qt.UserRole) if it else None
        if not d: return
        if not d.get("played"):
            self.cup_calendar_browser.setHtml(
                f"<div style='font-family:Segoe UI;color:#c7d2e0;padding:16px'>"
                f"<h3 style='color:#ffe6a6;margin:0 0 6px'>{d['tag']}  •  {d['opp']}</h3>"
                f"<p>Match à jouer le <b>{fmt_date_fr(d['date'])}</b> ({'domicile' if d['home'] else 'extérieur'}).</p></div>")
            return
        conn=db()
        try: rep=conn.execute("SELECT * FROM ai_match_report WHERE fixture_id=?",(int(d["id"]),)).fetchone()
        finally: conn.close()
        events=[]
        if rep:
            try: events=json.loads(rep["scorers"] or "[]")
            except Exception: events=[]
        lines="".join(
            f"<div style='padding:5px 2px;border-bottom:1px solid #22314d'>"
            f"<span style='color:#9da9c2'>{int(e.get('minute',0))}'</span>  "
            f"<b>{html.escape(str(e.get('scorer','?')))}</b> ({html.escape(str(e.get('team','')))})</div>"
            for e in events) or "<div style='color:#9da9c2'>Aucun buteur enregistré.</div>"
        self.cup_calendar_browser.setHtml(
            f"<div style='font-family:Segoe UI;color:#bac6d9;padding:12px'>"
            f"<h2 style='margin:0 0 4px;color:#ffe6a6'>{d['opp']}  <span style='color:#b59aff'>{d['score']}</span></h2>"
            f"<p style='margin:0 0 10px'>{d['tag']}  •  {fmt_date_fr(d['date'])}  •  {'domicile' if d['home'] else 'extérieur'}</p>"
            f"<h3 style='margin:6px 0;color:#98e3bd'>BUTEURS</h3>{lines}</div>")

