    def _cup_round_chips(self,rounds):
        """Boutons de filtre : TOUS + un bouton par tour présent."""
        while self.cup_round_bar.count():
            it=self.cup_round_bar.takeAt(0)
            wdg=it.widget()
            if wdg is not None: wdg.deleteLater()
        self.cup_round_buttons.clear()
        base="QPushButton{background:#131c2a;border:1px solid #33415a;border-radius:8px;padding:5px 12px;font-weight:800;font-size:8pt;color:#c7d2e0;} QPushButton:checked{background:#5b4b8e;border-color:#b899ff;color:#ffffff;}"
        def add(btn,round_index):
            btn.setCheckable(True); btn.setAutoExclusive(True); btn.setStyleSheet(base); btn.setMinimumHeight(28)
            btn.clicked.connect(lambda checked=False,r=round_index: self._select_cup_round(r))
            self.cup_round_bar.addWidget(btn); self.cup_round_buttons[round_index]=btn
        tous=QPushButton("TOUS LES TOURS"); add(tous,0)
        for r in rounds:
            add(QPushButton(f"TOUR {r}"),r)
        self.cup_round_bar.addStretch()
        btn=self.cup_round_buttons.get(self._cup_round_filter) or self.cup_round_buttons.get(0)
        if btn: btn.setChecked(True)

    def _select_cup_round(self,round_index):
        self._cup_round_filter=int(round_index or 0)
        try: self.refresh_cup_page(keep_filter=True)
        except Exception: pass

    def _cup_match_card(self,f,teams_start=None,divisions=None):
        """Carte de confrontation : deux lignes de clubs, score central, date,
        tour et mention 10 m. Le club du joueur est mis en avant."""
        own=(int(f["home_club_id"])==1 or int(f["away_club_id"])==1)
        played=int(f["played"] or 0); hg=int(f["home_goals"] or 0); ag=int(f["away_goals"] or 0)
        round_index=max(1,int(f["matchday"])-100)
        if teams_start is None:
            _c=db()
            try: teams_start=cup_round_teams(_c,int(f["season"] or 1),int(f["matchday"]))
            finally: _c.close()
        round_name=cup_round_name(teams_start)
        stamp=str(f["fixture_date"] or "")[5:10].replace("-","/")
        card=QFrame(); card.setObjectName("CupTieCard")
        border="#b899ff" if own else "#2b3953"
        bg="#17203a" if own else "#111a2b"
        card.setStyleSheet(f"QFrame#CupTieCard{{background:{bg};border:1px solid {border};border-radius:8px;}}")
        row=QHBoxLayout(card); row.setContentsMargins(8,4,8,4); row.setSpacing(8)
        divs=divisions or {}
        _dh=int(divs.get(int(f["home_club_id"]),0) or 0); _da=int(divs.get(int(f["away_club_id"]),0) or 0)
        upset=bool(played and _dh and _da and ((hg>ag and _dh>=_da+2) or (ag>hg and _da>=_dh+2)))
        if upset:
            card.setStyleSheet("QFrame#CupTieCard{background:#1a1a12;border:1px solid #c9a227;border-radius:8px;}")
        short_name=CUP_ROUND_SHORT.get(int(teams_start),"TOUR")
        tag=QLabel(f"{short_name}  ·  {stamp}"); tag.setAlignment(Qt.AlignCenter); tag.setFixedWidth(104)
        tag.setStyleSheet("color:#8fa0bb;font-size:6.5pt;font-weight:900;letter-spacing:.3px;")
        row.addWidget(tag)
        if upset:
            ex=QLabel("EXPLOIT"); ex.setAlignment(Qt.AlignCenter); ex.setFixedWidth(52)
            ex.setStyleSheet("background:#3a2c10;border:1px solid #d1a94f;border-radius:6px;"
                             "color:#f2d98a;font-size:6.5pt;font-weight:900;padding:1px 0;")
            row.addWidget(ex)
        col=QVBoxLayout(); col.setSpacing(0)
        DCOL={1:("#3a2c10","#ffd98a"),2:("#22303f","#a9c8e0"),3:("#173a2b","#8fe0a3"),4:("#3d2413","#ffb27a")}
        def _club_html(club_id,name):
            nm=html.escape(str(name))
            d=int(divs.get(int(club_id),0) or 0)
            if not d: return nm
            bg,fg=DCOL.get(d,("#26303f","#c3cfdf"))
            return (f"{nm}&nbsp; <span style='background:{bg};color:{fg};font-size:6.5pt;"
                    f"font-weight:900;'>&nbsp;L{d}&nbsp;</span>")
        home=QLabel(_club_html(f["home_club_id"],f["home_name"]))
        away=QLabel(_club_html(f["away_club_id"],f["away_name"]))
        home.setTextFormat(Qt.RichText); away.setTextFormat(Qt.RichText)
        _cup_winner_id=None
        if played:
            try: _cup_winner_id=int(_cup_winner_of(f))
            except Exception: _cup_winner_id=None
        for lab,is_own,winner in ((home,int(f["home_club_id"])==1,played and _cup_winner_id==int(f["home_club_id"])),(away,int(f["away_club_id"])==1,played and _cup_winner_id==int(f["away_club_id"]))):
            lab.setMinimumWidth(0)
            if is_own: lab.setStyleSheet("font-size:8.5pt;font-weight:1000;color:#f2f4fb;")
            elif winner: lab.setStyleSheet("font-size:8.5pt;font-weight:900;color:#8fe0a3;")
            else: lab.setStyleSheet("font-size:8.5pt;font-weight:700;color:#b9c6da;")
        col.addWidget(home); col.addWidget(away); row.addLayout(col,1)
        if played:
            score=QLabel(f"{hg} — {ag}"); score.setAlignment(Qt.AlignCenter); score.setFixedWidth(56)
            score.setStyleSheet("font-size:10.5pt;font-weight:1000;color:#f2f4fb;")
            row.addWidget(score)
            if hg==ag:
                try:
                    _ph=f["pen_home"]; _pa=f["pen_away"]
                except (KeyError,IndexError):
                    _ph=_pa=None
                note_txt=f"10 m {int(_ph)}-{int(_pa)}" if _ph is not None and _pa is not None else "10 m"
                note=QLabel(note_txt); note.setAlignment(Qt.AlignCenter); note.setFixedWidth(64 if _ph is not None and _pa is not None else 38)
                note.setStyleSheet("background:#3a2c10;border:1px solid #d1a94f;border-radius:6px;color:#f2d98a;font-size:6.5pt;font-weight:900;")
                note.setToolTip("Égalité : qualification décidée aux tirs au but à 10 m.")
                row.addWidget(note)
            else:
                spacer=QLabel(""); spacer.setFixedWidth(38); row.addWidget(spacer)
        else:
            vs=QLabel("VS"); vs.setAlignment(Qt.AlignCenter); vs.setFixedWidth(56)
            vs.setStyleSheet("font-size:9pt;font-weight:900;color:#72829c;")
            row.addWidget(vs)
            spacer=QLabel(""); spacer.setFixedWidth(38); row.addWidget(spacer)
        return card

    def refresh_cup_page(self,keep_filter=False):
        """Remplit l'onglet COUPE (appelé quand l'onglet est affiché)."""
        if not getattr(self,"cup_matches",None): return
        try: self.ensure_cup_recap()
        except Exception: pass
        fx=[]; pal=[]
        conn=db()
        try:
            club=conn.execute("SELECT name,season FROM club WHERE id=1").fetchone()
            season=int(club["season"] or 1) if club else 1
            fx=conn.execute("""SELECT f.*,hc.name home_name,ac.name away_name
                               FROM fixture f JOIN club hc ON hc.id=f.home_club_id
                               JOIN club ac ON ac.id=f.away_club_id
                               WHERE f.season=? AND f.fixture_type='cup' ORDER BY f.matchday,f.id""",(season,)).fetchall()
            import json as _json
            prow=conn.execute("SELECT value FROM meta WHERE key='cup_palmares'").fetchone()
            try: pal=_json.loads(prow["value"] or "[]") if prow else []
            except Exception: pal=[]
        except Exception:
            fx=[]; pal=[]
        self.cup_matches.clear(); self.cup_palmares.clear()
        divisions={}
        try:
            _dc=db()
            for _r in _dc.execute("SELECT id,division FROM club").fetchall():
                divisions[int(_r["id"])]=int(_r["division"] or 0)
            _dc.close()
        except Exception:
            divisions={}
        rounds=sorted({max(1,int(f["matchday"])-100) for f in fx})
        current=max(rounds) if rounds else 0
        if not keep_filter:
            # A l'ouverture, on montre le tour courant (pas le 32es d'il y a 4 mois).
            self._cup_round_filter=current if current>1 else 0
        self._cup_round_chips(rounds)
        _slots_row=conn.execute("SELECT value FROM meta WHERE key=?",(f"cup_slots_{int(season)}",)).fetchone()
        try: _slots=int(_slots_row["value"] or 0) if _slots_row else 0
        except Exception: _slots=0
        if _slots<=0:
            _slots=cup_round_teams(conn,season,CUP_MATCHDAY_OFFSET+1)
        total_rounds=max(1,int(_slots).bit_length()-1)
        winner_name=None
        for _e in pal:
            try:
                if int(_e.get("season",0) or 0)==int(season):
                    winner_name=str(_e.get("club") or "") or None; break
            except Exception:
                continue
        cup_finished=bool(winner_name)
        club_name=str(club["name"] or "") if club else ""
        user_won=bool(cup_finished and winner_name==club_name)
        # EXEMPTÉS : indication dynamique selon le tour atteint.
        try:
            _bconn=db()
            _byes=cup_read_byes(_bconn,season,1)
            _names=[]
            for _bid in _byes:
                _r=_bconn.execute("SELECT name FROM club WHERE id=?",(int(_bid),)).fetchone()
                if _r: _names.append(_r["name"])
            _bconn.close()
            if not _byes:
                self.cup_byes_label.setText("EXEMPTÉS : aucun (tableau plein)")
            elif cup_finished or current>1:
                self.cup_byes_label.setText(f"EXEMPTÉS D'ENTRÉE ({len(_byes)}) : intégrés au 2e tour")
            else:
                self.cup_byes_label.setText(f"EXEMPTÉS DU 1ER TOUR ({len(_byes)}) : "+" • ".join(_names))
        except Exception:
            pass
        if not fx:
            self.cup_banner.setText("TIRAGE À VENIR")
            self.cup_path.setText("PARCOURS : en attente du tirage (vers fin septembre)")
            self.cup_kpi_round.setText("—"); self.cup_kpi_matches.setText("—"); self.cup_kpi_status.setText("TIRAGE À VENIR")
            self.cup_table_title.setText("TABLEAU")
        else:
            self.cup_banner.setText(f"SAISON {season}  •  {'TERMINÉE' if cup_finished else 'EN COURS'}")
            short=CUP_ROUND_SHORT.get(cup_round_teams(conn,season,CUP_MATCHDAY_OFFSET+max(1,current)),"TOUR")
            self.cup_kpi_round.setText(f"{current}/{total_rounds}  ·  {short}")
            try:
                _nc=int(conn.execute("SELECT COUNT(*) n FROM club").fetchone()["n"])
                _nd=int(conn.execute("SELECT COUNT(DISTINCT division) n FROM club").fetchone()["n"])
                _nb=len(cup_read_byes(conn,season,1))
                self.cup_hero_edition.setText(f"ÉDITION {season}  •  SAISON {season}  •  {_nc} CLUBS  •  {_nd} DIVISIONS  •  {_nb} EXEMPTÉ(S)")
            except Exception:
                pass
            _cur_fx=[f for f in fx if int(f["matchday"])==CUP_MATCHDAY_OFFSET+max(1,current)]
            self.cup_kpi_matches.setText(str(len(_cur_fx)))
            own=[f for f in fx if int(f["home_club_id"])==1 or int(f["away_club_id"])==1]
            if not own:
                path="PARCOURS : le club n'est pas engagé cette saison."
                status="NON ENGAGÉ"
            else:
                last=sorted(own,key=lambda f:int(f["matchday"]))[-1]
                opp_name=last["away_name"] if int(last["home_club_id"])==1 else last["home_name"]
                if int(last["played"] or 0):
                    hg=int(last["home_goals"] or 0); ag=int(last["away_goals"] or 0)
                    our=hg if int(last["home_club_id"])==1 else ag
                    theirs=ag if int(last["home_club_id"])==1 else hg
                    won=our>theirs
                    rounds_played=len({int(f["matchday"]) for f in own})
                    if user_won:
                        status="VAINQUEUR"
                        path=f"PARCOURS : vainqueur de la Coupe Inter-Ligue • dernier résultat {our}-{theirs} contre {opp_name}"
                    elif cup_finished:
                        status="ÉLIMINÉ"
                        path=f"PARCOURS : éliminé • {winner_name} remporte la Coupe Inter-Ligue"
                    else:
                        status="QUALIFIÉ" if won else "ÉLIMINÉ"
                        path=f"PARCOURS : {rounds_played} tour(s) joué(s) • dernier résultat {our}-{theirs} contre {opp_name}"
                else:
                    status="À JOUER"
                    path=f"PARCOURS : encore en lice — prochaine confrontation contre {opp_name}"
            try:
                _prizes=0
                for _f in fx:
                    if not int(_f["played"] or 0): continue
                    if not (int(_f["home_club_id"])==1 or int(_f["away_club_id"])==1): continue
                    _home=int(_f["home_club_id"])==1
                    _our=int(_f["home_goals"] if _home else _f["away_goals"] or 0)
                    _their=int(_f["away_goals"] if _home else _f["home_goals"] or 0)
                    if _our>_their:
                        _prizes+=cup_prize_for(cup_round_teams(conn,season,int(_f["matchday"])))
                if cup_finished and user_won:
                    _prizes+=CUP_WINNER_PRIZE
                if hasattr(self,"cup_prizes_label"):
                    self.cup_prizes_label.setText(f"PRIMES DU PARCOURS : {_prizes:,} €".replace(","," "))
            except Exception:
                pass
            self.cup_kpi_status.setText(status)
            self.cup_path.setText(path)
            # PRIME EN JEU : gain du prochain tour du club (ou cagnotte finale).
            try:
                _next=[f for f in own if not int(f["played"] or 0)]
                if cup_finished:
                    if user_won:
                        self.cup_hero_stake.setText("COUPE GAGNÉE  •  +1 000 000 €")
                    else:
                        self.cup_hero_stake.setText(f"TERMINÉE  •  1 000 000 € pour {winner_name}")
                elif _next:
                    _nf=min(_next,key=lambda f:int(f["matchday"]))
                    _ts=cup_round_teams(conn,season,int(_nf["matchday"]))
                    _pz=cup_prize_for(_ts)
                    self.cup_hero_stake.setText(f"{cup_round_name(_ts)} : {_pz:,} €".replace(","," "))
                elif status=="ÉLIMINÉ":
                    self.cup_hero_stake.setText("ÉLIMINÉ  •  1 000 000 € au vainqueur")
                else:
                    self.cup_hero_stake.setText("VAINQUEUR : 1 000 000 €")
            except Exception:
                pass
            # PETIT POUCET : recalculé sur le tour courant (plus de byes fantômes).
            try:
                if cup_finished:
                    self.cup_minnow_label.setText(f"COUPE TERMINÉE  •  VAINQUEUR : {winner_name}")
                    _win_style=("background:#153225;border:1px solid #4f8a68;border-radius:9px;"
                                "padding:6px 10px;color:#b9f0cd;font-weight:1000;font-size:9pt;"
                                if user_won else
                                "background:#1b2233;border:1px solid #3a4a68;border-radius:9px;"
                                "padding:6px 10px;color:#b9c6da;font-weight:900;font-size:9pt;")
                    self.cup_minnow_label.setStyleSheet(_win_style)
                    self.cup_minnow_sub.setText("Tableau clos — rendez-vous la saison prochaine.")
                else:
                    last_md=max(int(f["matchday"]) for f in fx)
                    last_idx=last_md-CUP_MATCHDAY_OFFSET
                    last_fixtures=[f for f in fx if int(f["matchday"])==last_md]
                    round_complete=all(int(f["played"] or 0) for f in last_fixtures)
                    alive=set()
                    for f in last_fixtures:
                        if int(f["played"] or 0):
                            try: alive.add(int(_cup_winner_of(f)))
                            except Exception:
                                hg=int(f["home_goals"] or 0); ag=int(f["away_goals"] or 0)
                                alive.add(int(f["home_club_id"] if hg>=ag else f["away_club_id"]))
                        else:
                            alive.add(int(f["home_club_id"])); alive.add(int(f["away_club_id"]))
                    if last_idx<=1:
                        for _b in cup_read_byes(conn,season,1): alive.add(int(_b))
                    display_idx=last_idx+1 if (round_complete and last_idx<total_rounds) else last_idx
                    _ts_alive=cup_round_teams(conn,season,CUP_MATCHDAY_OFFSET+max(1,display_idx))
                    names={}
                    for cid in alive:
                        r=conn.execute("SELECT name FROM club WHERE id=?",(cid,)).fetchone()
                        if r: names[int(cid)]=r["name"]
                    by_div={}
                    for cid in alive:
                        if cid not in names: continue
                        d=int(divisions.get(cid,0) or 0)
                        by_div.setdefault(d,[]).append(names[cid])
                    if by_div:
                        low=max(by_div); crew=sorted(by_div[low])
                        others=sum(len(v) for d,v in by_div.items() if d>=2)
                        if low>=2:
                            more=f"  (+{len(crew)-1} autre(s) en L{low})" if len(crew)>1 else ""
                            stage=CUP_ROUND_SHORT.get(_ts_alive,"TOUR")
                            self.cup_minnow_label.setText(f"PETIT POUCET  •  L{low}  •  {crew[0]}{more}  ·  encore en lice au {stage}")
                            self.cup_minnow_label.setStyleSheet("background:#2a2416;border:1px solid #b08a3c;border-radius:9px;"
                                                                "padding:6px 10px;color:#ffd98a;font-weight:1000;font-size:9pt;")
                        else:
                            self.cup_minnow_label.setText("AUCUN PETIT POUCET — l'élite a verrouillé le tableau.")
                            self.cup_minnow_label.setStyleSheet("background:#1b2233;border:1px solid #3a4a68;border-radius:9px;"
                                                                "padding:6px 10px;color:#b9c6da;font-weight:900;font-size:9pt;")
                        dist="  ·  ".join(f"L{d} ×{len(v)}" for d,v in sorted(by_div.items()))
                        self.cup_minnow_sub.setText(f"Survivants par division : {dist}  —  {others} club(s) hors L1 encore en course")
                    else:
                        self.cup_minnow_label.setText("PETIT POUCET : tableau en préparation.")
                        self.cup_minnow_sub.setText("Survivants par division : —")
            except Exception:
                pass
            if self._cup_round_filter:
                _md=100+self._cup_round_filter
                self.cup_table_title.setText(f"TABLEAU  •  {cup_round_name(cup_round_teams(conn,season,_md))}")
            else:
                self.cup_table_title.setText("TABLEAU  •  TOUS LES TOURS")
            shown=[f for f in fx if not self._cup_round_filter or int(f["matchday"])-100==self._cup_round_filter]
            # Les exemptés apparaissent comme lignes qualifiées au 1er tour.
            if (not self._cup_round_filter or self._cup_round_filter==1):
                try:
                    _bc=db(); _bn=cup_read_byes(_bc,season,1)
                    _rows=[]
                    for _bid in _bn:
                        _r=_bc.execute("SELECT name FROM club WHERE id=?",(int(_bid),)).fetchone()
                        if _r: _rows.append(_r["name"])
                    _bc.close()
                    for _nm in _rows:
                        _it=QListWidgetItem(); _it.setSizeHint(QSize(300,32))
                        _it.setData(Qt.UserRole,0)
                        self.cup_matches.addItem(_it)
                        _lab=QLabel(f"32es  ·  EXEMPTÉ  ·  {_nm}")
                        _lab.setStyleSheet("background:#1c1730;border:1px dashed #6f5aa8;border-radius:8px;"
                                           "color:#cdb8ff;font-weight:900;font-size:8pt;padding:3px 10px;")
                        _lab.setParent(self.cup_matches.viewport())
                        self.cup_matches.setItemWidget(_it,_lab)
                except Exception:
                    pass
            _teams_cache={}
            for f in shown:
                md=int(f["matchday"])
                if md not in _teams_cache:
                    _teams_cache[md]=cup_round_teams(conn,season,md)
                it=QListWidgetItem(); it.setSizeHint(QSize(300,44))
                it.setData(Qt.UserRole,int(f["id"]))
                self._set_item_widget(self.cup_matches,it,self._cup_match_card(f,_teams_cache[md],divisions))
        if hasattr(self,"cup_bracket_empty"):
            self.cup_bracket_empty.setVisible(self.cup_matches.count()==0)
            self.cup_matches.setVisible(self.cup_matches.count()>0)
        try: conn.close()
        except Exception: pass
        for entry in pal:
            try:
                e=QListWidgetItem(f"SAISON {entry.get('season','?')} :  🏆 {entry.get('club','?')}")
                e.setForeground(QColor("#f2d98a")); self.cup_palmares.addItem(e)
            except Exception: pass
        if not pal:
            e=QListWidgetItem("Aucune édition archivée pour le moment.")
            e.setForeground(QColor("#6f829c")); self.cup_palmares.addItem(e)

    def open_cup_row(self,item):
        """Clic sur une confrontation : menu des deux clubs, puis fiche du CLUB
        choisi (et non la fiche d'un joueur)."""
        gid=int(item.data(Qt.UserRole) or 0)
        if not gid: return
        c=db()
        row=c.execute("""SELECT f.home_club_id h1,f.away_club_id a1,hc.name hn,ac.name an
                         FROM fixture f JOIN club hc ON hc.id=f.home_club_id
                         JOIN club ac ON ac.id=f.away_club_id
                         WHERE f.id=? AND f.fixture_type='cup'""",(gid,)).fetchone()
        c.close()
        if not row: return
        menu=QMenu(self)
        act_h=menu.addAction(f"DOMICILE  •  {row['hn']}  —  fiche du club")
        act_a=menu.addAction(f"EXTÉRIEUR  •  {row['an']}  —  fiche du club")
        chosen=menu.exec(self.cursor().pos())
        if chosen is act_h: self.show_club_profile(int(row["h1"]))
        elif chosen is act_a: self.show_club_profile(int(row["a1"]))




    def _stats_page(self):

        """Onglet Statistiques du Classement : 2 classements joueurs (buteurs, arrêts) pour la ligue affichée."""

        w=QWidget(); l=QVBoxLayout(w); l.setContentsMargins(0,0,0,0); l.setSpacing(10)

        hero=QFrame(); hero.setObjectName("HeroPanel"); hh=QHBoxLayout(hero); hh.setContentsMargins(14,9,14,9); hh.setSpacing(10)

        emblem=QLabel(); emblem.setFixedSize(44,44); emblem.setAlignment(Qt.AlignCenter); emblem.setPixmap(self._make_icon(9,26,"#e9f2ff")); emblem.setStyleSheet("background:#16273f;border:1px solid #4d88e8;border-radius:12px;font-size:16pt;"); hh.addWidget(emblem)

        ident=QVBoxLayout(); ident.setSpacing(2)

        hero_title=QLabel("CLASSEMENTS JOUEURS  •  LA SAISON EN CHIFFRES"); hero_title.setStyleSheet("font-size:12pt;font-weight:1000;color:#f2f4fb;letter-spacing:.5px;")

        hero_sub=QLabel("Buts et arrêts des joueurs de la ligue. Cliquez un joueur pour ouvrir sa fiche complète."); hero_sub.setObjectName("Muted"); hero_sub.setWordWrap(True); hero_sub.setMinimumWidth(0); hero_sub.setSizePolicy(QSizePolicy.Ignored,QSizePolicy.Preferred)

        ident.addWidget(hero_title); ident.addWidget(hero_sub); hh.addLayout(ident,1)

        self.stats_division_combo=QComboBox(); self.stats_division_combo.setMinimumHeight(32); self.stats_division_combo.setMinimumWidth(210); self.stats_division_combo.setToolTip("Choix du championnat à afficher"); self.stats_division_combo.currentIndexChanged.connect(self.apply_calendar_division); hh.addWidget(self.stats_division_combo)

        l.addWidget(hero)

        panel=QFrame(); panel.setObjectName("Panel"); pl=QVBoxLayout(panel); pl.setContentsMargins(12,10,12,10); pl.setSpacing(8)

        self.stats_division_combo.addItem("MON CLUB"); self.stats_division_combo.addItems([name for _,name,_,_,_ in LEAGUE_DEFINITIONS]); self.stats_division_combo.setCurrentIndex(0)

        self.stats_meta=QLabel("SAISON EN COURS  •  JOUEURS AYANT JOUÉ AU MOINS UN MATCH"); self.stats_meta.setObjectName("Muted"); pl.addWidget(self.stats_meta)

        tabs=QTabWidget(); tabs.setDocumentMode(True); self.stats_tabs=tabs

        self.stats_leaders={}

        for key,label in (("buteurs","BUTEURS"),("arrets","GARDIENS  •  ARRÊTS")):

            lst=QListWidget(); lst.setObjectName("ClubStandings"); lst.setSpacing(3)

            lst.setSelectionMode(QAbstractItemView.SingleSelection); lst.setEditTriggers(QAbstractItemView.NoEditTriggers)

            lst.itemClicked.connect(self._open_stats_player)

            lst.itemDoubleClicked.connect(self._open_stats_player)

            self.stats_leaders[key]=lst; tabs.addTab(lst,label)

        pl.addWidget(tabs,1)

        l.addWidget(panel,1); return w



    def _stats_row_value(self,row,kind):

        """(valeur affichée, couleur, légende) selon l'onglet demandé."""

        if kind=="buteurs":

            return str(int(row["g"] or 0)),"#ffd98a","BUTS"

        return str(int(row["sv"] or 0)),"#a8e6b8","ARRÊTS"



    def add_stats_leader_row(self,lst,rank,row,kind):

        item=QListWidgetItem(); item.setData(Qt.UserRole,row["id"]); item.setSizeHint(QSize(500,56))

        is_own=int(row["club_id"])==1

        own_color=getattr(self,"_own_color",None) or row["color1"] or "#476a91"

        wrap=QFrame(); wrap.setObjectName("ClubStandingRow")

        wrap.setStyleSheet(f"QFrame#ClubStandingRow{{background:{'#182338' if is_own else '#10192a'};border:1px solid {'#3a5478' if is_own else '#263550'};border-left:4px solid {own_color if is_own else (row['color1'] or '#476a91')};border-radius:11px;}}")

        layout=QHBoxLayout(wrap); layout.setContentsMargins(9,4,10,4); layout.setSpacing(9)

        rank_label=QLabel(f"{rank:02d}"); rank_label.setAlignment(Qt.AlignCenter); rank_label.setFixedSize(30,36)

        rank_color="#f2c46d" if rank==1 else "#d0d9e8" if rank==2 else "#d69d7a" if rank==3 else "#8493ad"

        rank_label.setStyleSheet(f"background:#1a2436;color:{rank_color};border:1px solid {rank_color};border-radius:10px;font-size:9pt;font-weight:1000;")

        avatar=QLabel(); avatar.setFixedSize(36,36); avatar.setAlignment(Qt.AlignCenter)

        try: avatar.setPixmap(self.draw_player_avatar(row,34))

        except Exception: pass

        info=QVBoxLayout(); info.setContentsMargins(0,1,0,1); info.setSpacing(1)

        name=QLabel(f"{row['first_name']} {row['last_name']}"); name.setStyleSheet(f"font-size:9pt;font-weight:1000;color:{own_color if is_own else '#eef2fa'};")

        meta=QLabel(f"{row['club_name']}  •  {row['position']}  •  {int(row['m'] or 0)} MJ"); meta.setObjectName("Muted"); meta.setStyleSheet("font-size:7pt;color:#99a7bd;")

        info.addWidget(name); info.addWidget(meta)

        value,value_color,caption=self._stats_row_value(row,kind)

        value_col=QVBoxLayout(); value_col.setSpacing(0)

        value_lbl=QLabel(value); value_lbl.setAlignment(Qt.AlignCenter); value_lbl.setStyleSheet(f"font-size:14pt;font-weight:1000;color:{value_color};")

        cap=QLabel(caption); cap.setAlignment(Qt.AlignCenter); cap.setStyleSheet("font-size:6.5pt;font-weight:900;color:#8998b1;")

        value_col.addWidget(value_lbl); value_col.addWidget(cap)

        layout.addWidget(rank_label); layout.addWidget(avatar); layout.addLayout(info,1); layout.addLayout(value_col)

        self._set_item_widget(lst,item,wrap)



    def _fill_stats_page(self):

        """Remplit les 4 classements joueurs pour la ligue actuellement affichée."""

        try:

            if not hasattr(self,"stats_leaders"): return

            # REBUILD SUR VISIBILITE (retour « RAM qui grimpe ») : idem classement.

            _sl=self.stats_leaders

            if hasattr(_sl,"isVisible") and not _sl.isVisible(): return

            conn=db()

            club=conn.execute("SELECT * FROM club WHERE id=1").fetchone()

            selected_division=int(getattr(self,"calendar_division_view",0) or (int(club["division"]) if club else 3))

            try: league_label=LEAGUE_DEFINITIONS[int(selected_division)-1][1]

            except Exception: league_label=f"Ligue {selected_division}"

            players=conn.execute("""SELECT p.id,p.first_name,p.last_name,p.position,p.club_id,

                                    p.season_matches m,p.season_goals g,p.season_saves sv,

                                    c.name club_name,c.color1,c.color2

                                    FROM player p JOIN club c ON c.id=p.club_id

                                    WHERE c.division=? AND p.season_matches>0""",(selected_division,)).fetchall()

            conn.close()

            by_goals=sorted(players,key=lambda p:(int(p["g"] or 0),int(p["m"] or 0)),reverse=True)

            keepers=[p for p in players if str(p["position"])=="Gardien"]

            by_saves=sorted(keepers,key=lambda p:(int(p["sv"] or 0),int(p["m"] or 0)),reverse=True)

            groups={"buteurs":by_goals,"arrets":by_saves}

            for key,lst in self.stats_leaders.items():

                lst.clear()

                rows=groups.get(key) or []

                if not rows:

                    ph=QListWidgetItem("AUCUNE STATISTIQUE GRAVÉE POUR LE MOMENT\nLes classements se remplissent dès que les matchs de la saison sont joués.")

                    ph.setFlags(Qt.NoItemFlags); ph.setForeground(QColor("#8fa4b9")); ph.setSizeHint(QSize(500,64)); lst.addItem(ph)

                else:

                    for rank,p in enumerate(rows[:15],1):

                        self.add_stats_leader_row(lst,rank,p,key)

            if hasattr(self,"stats_meta"):

                self.stats_meta.setText(f"{league_label.upper()}  •  SAISON EN COURS  •  {len(players)} JOUEURS CLASSÉS")

        except Exception as exc: self.log_error("stats_fill",exc)



    def _open_stats_player(self,item):

        player_id=item.data(Qt.UserRole) if item else None

        if player_id is None: return

        now=QTime.currentTime()

        last=getattr(self,"_last_profile_open",None)

        if last and last.msecsTo(now)<350: return

        self._last_profile_open=now

        conn=db()

        player=conn.execute("""SELECT p.*,c.name||' · Ligue '||c.division club_name,COALESCE(sr.knowledge,0) scout_knowledge,COALESCE(sr.reports,0) scout_reports

                               FROM player p JOIN club c ON c.id=p.club_id LEFT JOIN scout_report sr ON sr.player_id=p.id WHERE p.id=?""",(int(player_id),)).fetchone()

        conn.close()

        if player: self.show_player_profile(player)



    def schedule_friendly_match(self):

        """Crée un amical à la date choisie sans le mélanger au classement officiel."""

        conn = None

        try:

            raw=self.friendly_date_edit.date()

            if not raw.isValid():

                self.show_game_message("Amical","Date invalide : utilise le calendrier ou l'une des dates libres suggérées.","warning"); return

            chosen=raw.toPython().isoformat()

            conn=db()

            career=conn.execute('SELECT "current_date" AS current_date FROM career WHERE id=1').fetchone()

            season=int(conn.execute("SELECT season FROM club WHERE id=1").fetchone()["season"] or 1)

            if chosen < str(career["current_date"]):

                self.show_game_message("Amical",f"La date choisie ({fmt_date_fr(chosen)}) est passée : le calendrier de carrière est au {fmt_date_fr(str(career['current_date']))}.","warning"); return

            opponent_id=int(self.friendly_opponent_combo.currentData() or 0)

            if not opponent_id:

                self.show_game_message("Amical","Choisissez un adversaire.","warning"); return

            if int(conn.execute("SELECT COUNT(*) n FROM fixture WHERE season=? AND fixture_type='friendly' AND (home_club_id=1 OR away_club_id=1)",(season,)).fetchone()["n"]) >= 5:

                self.show_game_message("Amical","Limite de 5 matchs amicaux atteinte pour cette saison.","info"); return

            busy=conn.execute("SELECT 1 FROM fixture WHERE season=? AND fixture_date=? AND (home_club_id=1 OR away_club_id=1) LIMIT 1",(season,chosen)).fetchone()

            opponent_busy=conn.execute("SELECT 1 FROM fixture WHERE season=? AND fixture_date=? AND (home_club_id=? OR away_club_id=?) LIMIT 1",(season,chosen,opponent_id,opponent_id)).fetchone()

            if busy:

                suggest="  •  ".join(fmt_date_fr(d) for d in self._friendly_free_dates(chosen,3,60)) or "aucune date libre proche"

                self.show_game_message("Amical",f"Ton club joue déjà à cette date. Dates libres proches : {suggest}.","warning"); return

            if opponent_busy:

                suggest="  •  ".join(fmt_date_fr(d) for d in self._friendly_free_dates(chosen,3,60)) or "aucune date libre proche"

                self.show_game_message("Amical",f"{self.friendly_opponent_combo.currentText()} est déjà engagé ce jour-là. Dates libres proches pour ton club : {suggest}.","warning"); return

            rest_block=conn.execute("SELECT 1 FROM fixture WHERE season=? AND (home_club_id IN (1,?) OR away_club_id IN (1,?)) AND ABS(julianday(fixture_date)-julianday(?))<=2 LIMIT 1",(season,opponent_id,opponent_id,chosen)).fetchone()

            if rest_block:

                suggest="  •  ".join(fmt_date_fr(d) for d in self._friendly_free_dates(chosen,3,60)) or "aucune date libre proche"

                self.show_game_message("Amical","Repos de 3 jours minimum entre deux matchs (ton club et l'adversaire). Dates libres proches : {0}.".format(suggest),"warning"); return

            conn.execute("INSERT INTO fixture(season,matchday,fixture_date,home_club_id,away_club_id,fixture_type) VALUES(?,?,?,?,?,'friendly')",(season,0,chosen,1,opponent_id)); conn.commit()

            self.friendly_hint.setText("Amical programmé : date libre et adversaire disponible.")

            conn.close(); conn=None

            self.refresh_all()

        except Exception as exc: self.log_error("schedule_friendly_match",exc); self.show_game_message("Amical",f"Impossible de programmer l'amical : {exc}","error")

        finally:

            if conn is not None:

                conn.close()



    def _friendly_window_end(self, season_start):

        """Fin de la fenêtre de programmation : 400 jours après la date de carrière."""

        return season_start.addDays(400)



    def _friendly_free_dates(self, current_iso, limit=4, horizon=60):

        """Propose les prochaines dates libres du club (hors matchs, avec un jour de récupération)."""

        dates=[]

        try:

            conn=db()

            season=int(conn.execute("SELECT season FROM club WHERE id=1").fetchone()["season"] or 1)

            try: start=parse_iso(current_iso)

            except Exception: start=date.today()

            for offset in range(2,horizon+1):

                cand=start+timedelta(days=offset)

                iso=cand.isoformat()

                busy=conn.execute("SELECT 1 FROM fixture WHERE season=? AND fixture_date=? AND (home_club_id=1 OR away_club_id=1) LIMIT 1",(season,iso)).fetchone()

                if busy: continue

                near=conn.execute("SELECT 1 FROM fixture WHERE season=? AND (home_club_id=1 OR away_club_id=1) AND ABS(julianday(fixture_date)-julianday(?))<=2 LIMIT 1",(season,iso)).fetchone()

                if near: continue

                # Un championnat ne joue jamais un amical le même jour que le sien : l'adversaire sera validé au clic.

                dates.append(iso)

                if len(dates)>=limit: break

        except Exception as exc:

            self.log_error("friendly_free_dates",exc)

        finally:

            try: conn.close()

            except Exception: pass

        return dates



    def refresh_friendly_planner(self, career, club):

        """Met à jour la zone de programmation d'amicaux : dates limites, quota et suggestions."""

        if not hasattr(self,"friendly_date_edit"): return

        try:

            cd=parse_iso(career["current_date"])

        except Exception:

            return

        self._friendly_career_iso=str(career["current_date"])

        qmin=QDate(cd.year,cd.month,cd.day)

        conn=None

        try:

            conn=db()

            season=int(club["season"] or 1)

            quota=int(conn.execute("SELECT COUNT(*) n FROM fixture WHERE season=? AND fixture_type='friendly' AND (home_club_id=1 OR away_club_id=1)",(season,)).fetchone()["n"])

        except Exception as exc:

            self.log_error("friendly_planner",exc); quota=0

        finally:

            if conn is not None: conn.close()

        self.friendly_date_edit.blockSignals(True)

        previous=self.friendly_date_edit.date()

        qmax=self._friendly_window_end(qmin)

        self.friendly_date_edit.setMinimumDate(qmin)

        self.friendly_date_edit.setMaximumDate(qmax)

        in_window=previous.isValid() and previous>=qmin and previous<=qmax

        touched=bool(getattr(self,"_friendly_date_touched",False))

        # Le sélecteur suit la date FICTIVE de la carrière, jamais la date système :

        # - tant que l'utilisateur n'a pas touché la date -> synchro sur la date de carrière ;

        # - un choix utilisateur valide (dans la fenêtre) est toujours conservé.

        if not in_window or not touched:

            self.friendly_date_edit.setDate(qmin)

            self._friendly_date_touched=False

        self.friendly_date_edit.blockSignals(False)

        if hasattr(self,"friendly_quota_label"):

            self.friendly_quota_label.setText(f"{quota} / 5 CETTE SAISON")

            reached=quota>=5

            self.friendly_quota_label.setStyleSheet(

                "font-size:8.5pt;font-weight:900;color:%s;background:%s;border:1px solid %s;border-radius:10px;padding:5px 10px;" % (

                    "#f07989" if reached else "#7de0aa",

                    "rgba(240,121,137,32)" if reached else "rgba(52,211,153,32)",

                    "rgba(240,121,137,128)" if reached else "rgba(52,211,153,128)"))

        if hasattr(self,"schedule_friendly_btn"):

            self.schedule_friendly_btn.setEnabled(quota<5)

            self.schedule_friendly_btn.setText("QUOTA ATTEINT" if quota>=5 else "PROGRAMMER L’AMICAL")

        self.refresh_friendly_suggestions()

        if hasattr(self,"friendly_hint"):

            self.friendly_hint.setText(f"{5-quota} amical(aux) encore programmable(s) cette saison  •  calendrier de la carrière au {fmt_date_fr(str(career['current_date']))}." if quota<5 else "Tous les amicaux de la saison sont programmés.")



    def refresh_friendly_suggestions(self):

        """Recrée les pastilles de dates libres cliquables."""

        if not hasattr(self,"friendly_suggest_holder"): return

        while self.friendly_suggest_layout.count():

            it=self.friendly_suggest_layout.takeAt(0)

            w=it.widget()

            if w is not None: w.deleteLater()

        # Les suggestions partent toujours de la date de la carrière ( jamais d'une date de widget obsolète ).

        base=getattr(self,"_friendly_career_iso",None) or str(self.friendly_date_edit.date().toString('yyyy-MM-dd'))

        dates=self._friendly_free_dates(base)

        if not dates:

            empty=QLabel("Aucune date libre dans les 60 prochains jours"); empty.setObjectName("Muted"); empty.setStyleSheet("font-size:7.5pt;")

            self.friendly_suggest_layout.addWidget(empty)

            return

        for iso in dates:

            try: d=parse_iso(iso)

            except Exception: continue

            chip_date=d.strftime("%a %d %b").replace(".","")

            chip=QPushButton(f"🗓 {chip_date}".replace("É","É"))

            chip.setToolTip(f"Choisir le {fmt_date_fr(iso)} pour l'amical")

            chip.setCursor(Qt.PointingHandCursor)

            chip.setStyleSheet("QPushButton{background:#142039;color:#bfd4f2;border:1px solid #2c425f;border-radius:10px;padding:4px 9px;font-weight:800;font-size:8pt;}"

                               "QPushButton:hover{border-color:#4ec9f2;color:#eaf6ff;background:#182a47;}")

            chip.clicked.connect(lambda checked=False, iso=iso: self.apply_friendly_suggested_date(iso))

            self.friendly_suggest_layout.addWidget(chip)

        self.friendly_suggest_layout.addStretch(1)



    def apply_friendly_suggested_date(self, iso):

        """Applique une date suggérée au sélecteur et vérifie l'adversaire courant."""

        try:

            d=parse_iso(iso)

            self.friendly_date_edit.setDate(QDate(d.year,d.month,d.day))

        except Exception:

            return



    def on_friendly_date_changed(self,qdate):

        """L'utilisateur a modifié la date manuellement : on respecte son choix (signal en direct)."""

        self._friendly_date_touched=True

        self.update_friendly_insight(qdate)



    def _fill_friendly_opponents(self):

        """LISTE D'ADVERSAIRES AMICAUX FILTREES (retour « liste trop longue ») :

        TOUTES / L1..L6 / MA LIGUE ± 1 / NIVEAU PROCHE (réputation ±15). Les

        clubs sont presents par ligue puis reputation pour lire les niveaux,

        et la sélection courante est conservée si elle survit au filtre."""

        combo=self.friendly_opponent_combo

        fcombo=getattr(self,"friendly_filter_combo",None)

        flt=fcombo.currentIndex() if fcombo is not None else 0

        keep=combo.currentData()

        conn=db()

        try:

            own=conn.execute("SELECT division,reputation FROM club WHERE id=1").fetchone()

            own_div=int(own["division"] or 1); own_rep=int(own["reputation"] or 30)

            base="SELECT id,name,division,reputation FROM club WHERE id<>1"

            order=" ORDER BY division,reputation DESC,name"

            if 1<=flt<=6:

                rows=conn.execute(base+(" AND division=?" if flt<=6 else "")+order,(flt,) if flt<=6 else ()).fetchall()

            elif flt==7:

                lo=max(1,own_div-1); hi=min(6,own_div+1)

                rows=conn.execute(f"{base} AND division BETWEEN ? AND ?{order}",(lo,hi)).fetchall()

            elif flt==8:

                rows=conn.execute(f"{base} AND reputation BETWEEN ? AND ?{order}",(own_rep-15,own_rep+15)).fetchall()

            else:

                rows=conn.execute(base+order+" LIMIT 300").fetchall()

        finally:

            conn.close()

        combo.blockSignals(True); combo.clear()

        keep_idx=-1

        for i,opp in enumerate(rows):

            rep=int(opp["reputation"] or 0)

            label=f"{opp['name']}  •  L{int(opp['division'] or 1)}  •  rép {rep}"

            combo.addItem(label,int(opp["id"]))

            if keep is not None and int(opp["id"])==int(keep): keep_idx=i

        combo.setCurrentIndex(keep_idx if keep_idx>=0 else (0 if combo.count() else -1))

        combo.blockSignals(False)

        try: self.update_friendly_insight()

        except Exception: pass



    def update_friendly_insight(self,*_args):

        """Vérification en direct : le hint reflète l'état de la date et de l'adversaire choisis."""

        if not hasattr(self,"friendly_hint"): return

        try:

            d_iso=self.friendly_date_edit.date().toString('yyyy-MM-dd')

            try: parse_iso(d_iso)

            except Exception: return

            conn=db()

            season=int(conn.execute("SELECT season FROM club WHERE id=1").fetchone()["season"] or 1)

            today=str(conn.execute('SELECT "current_date" AS current_date FROM career WHERE id=1').fetchone()["current_date"])

            self_busy=conn.execute("SELECT 1 FROM fixture WHERE season=? AND fixture_date=? AND (home_club_id=1 OR away_club_id=1) LIMIT 1",(season,d_iso)).fetchone() is not None

            near=conn.execute("SELECT 1 FROM fixture WHERE season=? AND (home_club_id=1 OR away_club_id=1) AND ABS(julianday(fixture_date)-julianday(?))<=2 LIMIT 1",(season,d_iso)).fetchone() is not None

            quota=int(conn.execute("SELECT COUNT(*) n FROM fixture WHERE season=? AND fixture_type='friendly' AND (home_club_id=1 OR away_club_id=1)",(season,)).fetchone()["n"])

            opponent_id=self.friendly_opponent_combo.currentData()

            opp_busy=False

            if opponent_id:

                opp_busy=conn.execute("SELECT 1 FROM fixture WHERE season=? AND fixture_date=? AND (home_club_id=? OR away_club_id=?) LIMIT 1",(season,d_iso,int(opponent_id),int(opponent_id))).fetchone() is not None

            opp_name=self.friendly_opponent_combo.currentText() if opponent_id else ""

            conn.close()

            if d_iso<today:

                self.friendly_hint.setText(f"⛔ {fmt_date_fr(d_iso)} est passée (carrière au {fmt_date_fr(today)}). Choisis une date à partir d'aujourd'hui, ou une suggestion ci-dessous.")

            elif near:

                self.friendly_hint.setText(f"⛔ {fmt_date_fr(d_iso)} : trop proche d'un autre match (repos de 3 jours minimum).")

            elif self_busy:

                self.friendly_hint.setText(f"⛔ {fmt_date_fr(d_iso)} : ton club a déjà un match ce jour-là.")

            elif quota>=5:

                self.friendly_hint.setText("⛔ Quota de 5 amicaux atteint pour cette saison.")

            elif opp_busy:

                self.friendly_hint.setText(f"⚠ {fmt_date_fr(d_iso)} libre pour ton club, mais {opp_name} joue ce jour-là. Autre adversaire ou autre date.")

            elif self.schedule_friendly_btn.isEnabled():

                self.friendly_hint.setText(f"✔ {fmt_date_fr(d_iso)} est libre pour ton club et pour {opp_name}. Prêt à programmer.")

        except Exception as exc:

            self.log_error("update_friendly_insight",exc)



    def apply_calendar_filter(self,index=0):

        """Applique le filtre de la liste calendrier puis rafraîchit l'affichage."""

        if not getattr(self,"_ui_ready",False): return

        self.refresh_all()



    def apply_calendar_division(self,index):

        """Synchronise les trois sélecteurs de championnat et rafraîchit la vue."""

        if not getattr(self,"_ui_ready",False): return

        combos=[getattr(self,name,None) for name in ("results_division_combo","standings_division_combo","stats_division_combo")]

        combos=[c for c in combos if c is not None]

        if not combos: return

        if getattr(self,"_syncing_division_combo",False): return

        self._syncing_division_combo=True

        for combo in combos:

            if combo.currentIndex()!=index: combo.setCurrentIndex(index)

        self._syncing_division_combo=False

        self.calendar_division_view=None if index<=0 else index

        # Historique / Palmarès : leurs sélecteurs listent Ligue 1..6.
        target_div=int(index) if index>=1 else 0
        if not target_div:
            try:
                _c=db(); target_div=int(_c.execute("SELECT division FROM club WHERE id=1").fetchone()["division"] or 1); _c.close()
            except Exception:
                target_div=1
        for _name in ("history_division_combo","history_palmares_combo","palmares_league"):
            _combo=getattr(self,_name,None)
            if _combo is not None and _combo.count():
                _combo.blockSignals(True)
                _combo.setCurrentIndex(max(0,min(_combo.count()-1,target_div-1)))
                _combo.blockSignals(False)

        self.refresh_all()



    def build_calendar_fixture_card(self,fixture,has_report):

        played=bool(fixture["played"]); home_goals=fixture["home_goals"]; away_goals=fixture["away_goals"]

        is_home=int(fixture["home_club_id"])==1

        is_friendly=str(fixture["fixture_type"] if "fixture_type" in fixture.keys() else "championship")=="friendly"

        is_cup=str(fixture["fixture_type"] if "fixture_type" in fixture.keys() else "championship")=="cup"

        manager_goals=int(home_goals if is_home else away_goals) if played else None

        opponent_goals=int(away_goals if is_home else home_goals) if played else None

        accent="#4ec9f2" if is_friendly and not played else "#53627e" if not played else "#51d99b" if manager_goals>opponent_goals else "#f2bf6f" if manager_goals==opponent_goals else "#f07989"

        card=QFrame(); card.setObjectName("CalendarFixtureCard")

        own_color=getattr(self,"_own_color",None) or "#5ad18e"

        card.setStyleSheet(f"QFrame#CalendarFixtureCard{{background:#111a2b;border:1px solid #283753;border-left:3px solid {accent};border-radius:10px;}}")

        layout=QHBoxLayout(card); layout.setContentsMargins(8,6,8,6); layout.setSpacing(8)

        if is_cup:

            _round=max(1,int(fixture["matchday"] or CUP_MATCHDAY_OFFSET+1)-CUP_MATCHDAY_OFFSET)

            _tag=f"C{_round}"

        else:

            _tag="AM" if is_friendly else f"J{int(fixture['matchday']):02d}"

        day=QLabel(_tag); day.setAlignment(Qt.AlignCenter); day.setFixedSize(42,42); day.setStyleSheet(f"background:#102b3b;border:1px solid {accent};border-radius:10px;color:#e9edf6;font-weight:900;font-size:{'8pt' if is_cup else '10pt'};"); layout.addWidget(day)

        teams=QVBoxLayout(); teams.setSpacing(2)

        home=QLabel(("  " if is_home else "")+f"{fixture['home_name']}"); home.setStyleSheet(f"font-size:8pt;font-weight:900;color:{own_color};" if is_home else "font-size:9pt;font-weight:700;color:#d6dcea;")

        away=QLabel(("  " if not is_home else "")+f"{fixture['away_name']}"); away.setStyleSheet(f"font-size:8pt;font-weight:900;color:{own_color};" if not is_home else "font-size:9pt;font-weight:700;color:#d6dcea;")

        teams.addWidget(home); teams.addWidget(away); layout.addLayout(teams,1)

        score=QLabel(f"{home_goals} : {away_goals}" if played else "VS"); score.setAlignment(Qt.AlignCenter); score.setMinimumWidth(58); score.setStyleSheet(f"font-size:12pt;font-weight:1000;color:{accent};"); layout.addWidget(score)

        meta=QVBoxLayout(); meta.setSpacing(2)

        status=QLabel("RAPPORT →" if played and has_report else "TERMINÉ" if played else "À VENIR"); status.setAlignment(Qt.AlignRight|Qt.AlignVCenter); status.setStyleSheet(f"font-size:7pt;font-weight:900;color:{accent};")

        date_label=QLabel(("AMICAL  •  " if is_friendly else "COUPE  •  " if is_cup else "")+fmt_date_fr(fixture["fixture_date"])); date_label.setAlignment(Qt.AlignRight|Qt.AlignVCenter); date_label.setObjectName("Muted"); date_label.setStyleSheet("font-size:7pt;color:#8f9bb2;")

        meta.addWidget(status)

        try:
            _ph=fixture["pen_home"]; _pa=fixture["pen_away"]
        except (KeyError,IndexError):
            _ph=_pa=None
        if played and _ph is not None and _pa is not None:
            pen_label=QLabel(f"10 m {int(_ph)}-{int(_pa)}"); pen_label.setAlignment(Qt.AlignRight|Qt.AlignVCenter); pen_label.setStyleSheet("font-size:6.8pt;font-weight:900;color:#ffd98a;")
            meta.addWidget(pen_label)

        meta.addWidget(date_label); layout.addLayout(meta)

        return card



    def build_division_fixture_card(self,fixture):

        played=bool(fixture["played"]); home_goals=fixture["home_goals"]; away_goals=fixture["away_goals"]

        own_home=int(fixture["home_club_id"] if "home_club_id" in fixture.keys() else 0)==1

        own_away=int(fixture["away_club_id"] if "away_club_id" in fixture.keys() else 0)==1

        is_own=own_home or own_away

        own_color=getattr(self,"_own_color",None) or "#5ad18e"

        accent=own_color if is_own and not played else "#53627e" if not played else "#51d99b" if (home_goals if played else 0)>(away_goals if played else 1) else "#f2bf6f" if played else "#53627e"

        card=QFrame(); card.setObjectName("CalendarFixtureCard"); card.setStyleSheet(f"QFrame#CalendarFixtureCard{{background:{'#152034' if is_own else '#111a2b'};border:1px solid {'#3a4f74' if is_own else '#283753'};border-left:4px solid {accent};border-radius:10px;}}")

        layout=QHBoxLayout(card); layout.setContentsMargins(8,6,8,6); layout.setSpacing(8)

        day=QLabel(f"J{int(fixture['matchday']):02d}"); day.setAlignment(Qt.AlignCenter); day.setFixedSize(42,42); day.setStyleSheet(f"background:{'#223148' if is_own else '#202b42'};border:1px solid {accent};border-radius:10px;color:#e9edf6;font-weight:900;"); layout.addWidget(day)

        teams=QVBoxLayout(); teams.setSpacing(2)

        home_style=f"font-size:8pt;font-weight:900;color:{own_color};" if own_home else "font-size:8pt;font-weight:800;color:#eef2fa;"

        away_style=f"font-size:8pt;font-weight:900;color:{own_color};" if own_away else "font-size:8pt;color:#aab5c8;"

        home=QLabel(("  " if own_home else "")+str(fixture["home_name"])); home.setStyleSheet(home_style)

        away=QLabel(("  " if own_away else "")+str(fixture["away_name"])); away.setStyleSheet(away_style)

        teams.addWidget(home); teams.addWidget(away); layout.addLayout(teams,1)

        if is_own:
            chip=QLabel("TON CLUB"); chip.setAlignment(Qt.AlignCenter)
            chip.setStyleSheet(f"background:{own_color};color:#081018;font-size:6.5pt;font-weight:900;border-radius:6px;padding:2px 5px;")
            layout.addWidget(chip)

        score=QLabel(f"{home_goals} : {away_goals}" if played else "VS"); score.setAlignment(Qt.AlignCenter); score.setMinimumWidth(58); score.setStyleSheet(f"font-size:12pt;font-weight:1000;color:{accent};"); layout.addWidget(score)

        meta=QVBoxLayout(); meta.setSpacing(2)

        status=QLabel("TERMINÉ" if played else "À VENIR"); status.setAlignment(Qt.AlignRight|Qt.AlignVCenter); status.setStyleSheet(f"font-size:7pt;font-weight:900;color:{accent};")

        date_label=QLabel(fmt_date_fr(fixture["fixture_date"])); date_label.setAlignment(Qt.AlignRight|Qt.AlignVCenter); date_label.setObjectName("Muted"); date_label.setStyleSheet("font-size:7pt;color:#8f9bb2;")

        meta.addWidget(status); meta.addWidget(date_label); layout.addLayout(meta)

        return card



    def division_report_html(self,fixture,scorers_json):

        """Rapport simple d'un match IA : score global + buteurs enregistrés."""

        try: scorers=json.loads(scorers_json or "[]")

        except ValueError: scorers=[]

        home=html.escape(str(fixture["home_name"])); away=html.escape(str(fixture["away_name"]))

        hg=int(fixture["home_goals"] or 0); ag=int(fixture["away_goals"] or 0)

        lines=[]

        for ev in scorers:

            side=int(ev.get("side","h")=="a"); minute=int(ev.get("minute") or 0)

            club=html.escape(str(ev.get("team") or "")); scorer=html.escape(str(ev.get("scorer") or "?"))

            detail=f"<b>{scorer}</b> ({club})"

            lines.append(f"<div style='padding:6px 2px;border-bottom:1px solid #22314d'><span style='color:#9da9c2'>{minute}'</span>  {detail}</div>")

        scorers_block="".join(lines) or "<div style='color:#9da9c2'>Aucun buteur enregistré.</div>"

        return (f"<div style=\"font-family:Segoe UI;color:#bac6d9\">"

                f"<h2 style=\"margin:0 0 4px;color:#e7dcff\">{home} <span style='color:#b59aff'>{hg}</span> : <span style='color:#b59aff'>{ag}</span> {away}</h2>"

                f"<p style='margin:0 0 12px'>{fixture_tag(fixture['matchday'],fixture['fixture_type'] if 'fixture_type' in fixture.keys() else 'championship')}  •  {fmt_date_fr(fixture['fixture_date'])}  •  rapport simplifié</p>"

                f"<h3 style='margin:6px 0;color:#98e3bd'>⚽ BUTEURS</h3>{scorers_block}</div>")



    def on_calendar_fixture_selected(self,row,source=None):

        source_list=self.calendar_friendly_list if source=="friendly" and hasattr(self,"calendar_friendly_list") else getattr(self,"calendar_fixture_list",None)

        if row<0 or source_list is None: return

        item=source_list.item(row)

        if not item: return

        data=item.data(Qt.UserRole)

        if isinstance(data,dict) and data.get("type")=="fx":

            conn=db(); fixture=conn.execute("""SELECT f.*,hc.name home_name,ac.name away_name FROM fixture f

                                               JOIN club hc ON hc.id=f.home_club_id JOIN club ac ON ac.id=f.away_club_id

                                               WHERE f.id=?""",(int(data["fixture_id"]),)).fetchone()

            if not fixture: conn.close(); return

            _ft=str(fixture["fixture_type"] or "championship") if "fixture_type" in fixture.keys() else "championship"
            _date=str(fixture["fixture_date"])
            record=conn.execute("""SELECT * FROM match_record WHERE home=? AND away=? AND substr(created_at,1,10)=?
                                   AND COALESCE(fixture_type,'championship')=? ORDER BY id DESC LIMIT 1""",
                                (fixture["home_name"],fixture["away_name"],_date,_ft)).fetchone()
            if not record and _ft=="championship":
                record=conn.execute("SELECT * FROM match_record WHERE matchday=? AND home=? AND away=? ORDER BY id DESC LIMIT 1",
                                    (int(fixture["matchday"]),fixture["home_name"],fixture["away_name"])).fetchone()
            _cup_round=None
            if _ft=="cup":
                try: _cup_round=cup_round_name(cup_round_teams(conn,int(fixture["season"] or 1),int(fixture["matchday"])))
                except Exception: _cup_round=None

            scorers_row=conn.execute("SELECT * FROM ai_match_report WHERE fixture_id=?",(int(data["fixture_id"]),)).fetchone(); conn.close()

            keys=fixture.keys()

            is_friendly=(str(fixture["fixture_type"])=="friendly") if "fixture_type" in keys else False
            is_cup=(str(fixture["fixture_type"])=="cup") if "fixture_type" in keys else False

            home,away,md=fixture["home_name"],fixture["away_name"],int(fixture["matchday"])

            if is_friendly:
                head=f"AMICAL  •  {home}  —  {away}"; meta=f"{fmt_date_fr(fixture['fixture_date'])}  •  match de préparation"
            elif is_cup:
                head=f"{_cup_round or fixture_tag(md,'cup')}  •  {home}  —  {away}"; meta=f"{fmt_date_fr(fixture['fixture_date'])}  •  Coupe Inter-Ligue"
            else:
                head=f"JOURNÉE {md:02d}  •  {home}  —  {away}"; meta=f"{fmt_date_fr(fixture['fixture_date'])}  •  rapport du championnat"


            if fixture["played"]:

                score_text=f"{int(fixture['home_goals'] or 0)}  :  {int(fixture['away_goals'] or 0)}"

                try:
                    _ph=fixture["pen_home"]; _pa=fixture["pen_away"]
                except (KeyError,IndexError):
                    _ph=_pa=None
                if _ph is not None and _pa is not None:
                    score_text+=f"  ({int(_ph)} — {int(_pa)} aux 10 m)"

                if record and record["report"]:

                    html_content=self.archived_report_html(record["report"])

                elif scorers_row:

                    html_content=self.division_report_html(fixture,scorers_row["scorers"])

                else:

                    html_content="<div style='padding:24px;color:#aebbd0'>Score enregistré sans détail de buteurs pour ce match IA.</div>"

            else:

                score_text="À VENIR"

                contexte=("Match de préparation inscrit au calendrier. Le résultat et le rapport seront disponibles après la rencontre."

                          if is_friendly else

                          "Match inscrit au calendrier du championnat sélectionné. Le résultat sera enregistré après la journée.")

                html_content=f"<div style='font-family:Segoe UI;color:#bac6d9;padding:20px'><h2 style='color:#e7dcff'>{html.escape(head)}</h2><p>{html.escape(home)} — {html.escape(away)}</p><p>{contexte}</p></div>"

            if is_friendly and hasattr(self,"friendly_report_browser"):

                self.friendly_report_browser.setHtml(html_content)

            else:

                self.calendar_report_title.setText(head)

                self.calendar_report_meta.setText(meta)

                self.calendar_report_score.setText(score_text)

                self.calendar_report_browser.setHtml(html_content)

            return

        if not isinstance(data,int): return

        matchday=data

        if matchday is None: return

        conn=db(); fixture=conn.execute("SELECT f.*,hc.name home_name,ac.name away_name FROM fixture f JOIN club hc ON hc.id=f.home_club_id JOIN club ac ON ac.id=f.away_club_id WHERE f.matchday=? AND (f.home_club_id=1 OR f.away_club_id=1)",(int(matchday),)).fetchone()

        _cup_match=(str(fixture["fixture_type"])=="cup") if "fixture_type" in fixture.keys() else False
        if _cup_match:
            record=None   # coupe : hors championnat (matchday=0 dans match_record)
        else:
            record=conn.execute("SELECT * FROM match_record WHERE matchday=? ORDER BY id DESC LIMIT 1",(int(matchday),)).fetchone(); conn.close()

        if not fixture: return

        self.calendar_report_title.setText(f"JOURNÉE {int(matchday):02d}  •  {'RAPPORT COMPLET' if record and record['report'] else 'AVANT-MATCH'}")

        self.calendar_report_meta.setText(f"{fmt_date_fr(fixture['fixture_date'])}  •  {fixture['home_name']}  —  {fixture['away_name']}")

        if fixture["played"]:

            self.calendar_report_score.setText(f"{fixture['home_goals']}  :  {fixture['away_goals']}")

            if record and record["report"]:

                self.calendar_report_browser.setHtml(self.archived_report_html(record["report"]))

            else:

                self.calendar_report_browser.setHtml("<div style='padding:24px;color:#aebbd0'>Score enregistré. Aucun rapport détaillé n'est disponible pour cette journée.</div>")

        else:

            self.calendar_report_score.setText("À VENIR")

            self.calendar_report_browser.setHtml(f"<div style='font-family:Segoe UI;color:#bac6d9;padding:20px'><h2 style='color:#e7dcff'>Prochain rendez-vous</h2><p>{html.escape(fixture['home_name'])} reçoit {html.escape(fixture['away_name'])}.</p><p>Prépare ton cinq, ajuste la tactique et consulte le rapport après le coup de sifflet final.</p></div>")



    def archived_report_html(self,report_text):

        section_names={"STATISTIQUES","PLAN DE MATCH","BILAN MÉDICAL","DISCIPLINE","BUTEURS","NOTES DU CLUB","TEMPS FORTS"}

        section_labels={"STATISTIQUES":"📈  STATISTIQUES DU MATCH","PLAN DE MATCH":"🧠  PLAN DE MATCH","BILAN MÉDICAL":"🩺  BILAN MÉDICAL","DISCIPLINE":"🟨  DISCIPLINE","BUTEURS":"⚽  BUTEURS","NOTES DU CLUB":"  NOTES DU CLUB","TEMPS FORTS":"🎬  TEMPS FORTS"}

        lines=[line.strip() for line in str(report_text or "").splitlines()]

        intro=[]; sections=[]; current=None

        for line in lines[1:]:

            if not line: continue

            if line in section_names:

                current={"title":line,"lines":[]}; sections.append(current); continue

            if current is None: intro.append(line)

            else: current["lines"].append(line)

        outcome=html.escape(intro[0] if intro else "Compte-rendu de la rencontre")

        halftime=html.escape(intro[1] if len(intro)>1 else "")

        cards=[]

        for section in sections:

            items=[]

            for line in section["lines"]:

                safe=html.escape(line)

                if section["title"]=="STATISTIQUES" and ":" in line:

                    label,value=line.split(":",1); items.append(f"<div style='background:#111b2d;border:1px solid #2a3852;border-radius:8px;padding:8px 10px'><span style='color:#8fa1bc'>{html.escape(label)}</span><br><b style='color:#edf2fb'>{html.escape(value.strip())}</b></div>")

                else:

                    color="#98e3bd" if section["title"]=="BUTEURS" else "#e8edf7"

                    items.append(f"<div style='padding:5px 2px;border-bottom:1px solid #202b40;color:{color}'>{safe}</div>")

            if not items: items=["<span style='color:#8f9bb0'>Aucune donnée disponible.</span>"]

            if section["title"]=="STATISTIQUES":

                table_rows=[]

                for index in range(0,len(items),2):

                    left_cell=f"<td width='50%' style='padding:3px'>{items[index]}</td>"

                    right_cell=f"<td width='50%' style='padding:3px'>{items[index+1]}</td>" if index+1<len(items) else "<td width='50%'></td>"

                    table_rows.append(f"<tr>{left_cell}{right_cell}</tr>")

                section_body=f"<table width='100%' cellspacing='0' cellpadding='0'>{''.join(table_rows)}</table>"

            else:

                section_body="".join(items)

            cards.append(f"<section style='background:#0e1727;border:1px solid #25334b;border-radius:11px;padding:10px 12px;margin:9px 0'><h3 style='font-size:10pt;color:#cdb8ff;margin:0 0 7px'>{section_labels[section['title']]}</h3>{section_body}</section>")

        return ("<html><body style='font-family:Segoe UI,Arial;background:#090f1b;color:#e9edf5;font-size:9pt;margin:8px'>"

                f"<div style='color:#90e4b8;font-size:12pt;font-weight:800;margin:3px 0 5px'>{outcome}</div>"

                f"<div style='color:#9cabc2;margin-bottom:9px'>{halftime}</div>{''.join(cards)}</body></html>")



    def show_saved_match_report(self,matchday=None,record_id=None):

        conn=db()

        if record_id is not None:

            record=conn.execute("SELECT * FROM match_record WHERE id=?",(int(record_id),)).fetchone()

        else:

            record=conn.execute("SELECT * FROM match_record WHERE matchday=? ORDER BY id DESC LIMIT 1",(int(matchday or 0),)).fetchone()

        _kind=str(record["fixture_type"] or "championship") if record else "championship"

        _cup_name=None

        if record and _kind=="cup":

            try:

                _fx=conn.execute("""SELECT f.matchday,f.season FROM fixture f
                                    JOIN club h ON h.id=f.home_club_id JOIN club a ON a.id=f.away_club_id
                                    WHERE f.fixture_type='cup' AND f.fixture_date=? AND h.name=? AND a.name=?
                                    ORDER BY f.id DESC LIMIT 1""",
                                 (str(record["created_at"] or "")[:10],record["home"],record["away"])).fetchone()

                if _fx: _cup_name=cup_round_name(cup_round_teams(conn,int(_fx["season"] or 1),int(_fx["matchday"])))

            except Exception:

                _cup_name=None

        conn.close()

        if not record or not record["report"]:

            self.show_game_message("Rapport indisponible","Aucun rapport détaillé n'est enregistré pour cette journée.","info"); return

        if _kind=="cup": _title=f"RAPPORT ARCHIVÉ  •  COUPE" + (f"  •  {_cup_name}" if _cup_name else "")

        elif _kind=="friendly": _title="RAPPORT ARCHIVÉ  •  AMICAL"

        else: _title=f"RAPPORT ARCHIVÉ  •  JOURNÉE {int(record['matchday'])}"

        dialog=QDialog(self); dialog.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dialog.setWindowTitle("Rapport archivé"); dialog.resize(860,680); dialog.setMinimumSize(680,520)

        root=QVBoxLayout(dialog); root.setContentsMargins(16,16,16,16); root.setSpacing(10)

        header=QFrame(); header.setObjectName("HeroPanel"); hl=QHBoxLayout(header); hl.setContentsMargins(14,10,14,10)

        title=QLabel(_title); title.setStyleSheet("font-size:13pt;font-weight:900;color:#dfcfff;")

        _score_txt=f"{record['home_goals']} — {record['away_goals']}"

        try:
            _ph=record["pen_home"]; _pa=record["pen_away"]
        except (KeyError,IndexError):
            _ph=_pa=None
        if _ph is not None and _pa is not None:
            _score_txt+=f"  ({int(_ph)} — {int(_pa)} aux 10 m)"

        score=QLabel(_score_txt); score.setStyleSheet("font-size:20pt;font-weight:900;color:#fff;")

        hl.addWidget(title,1); hl.addWidget(score); root.addWidget(header)

        text=QTextBrowser(); text.setOpenLinks(False); text.setHtml(self.archived_report_html(record["report"])); root.addWidget(text,1)

        close=QPushButton("FERMER LE RAPPORT"); close.setObjectName("Primary"); close.clicked.connect(dialog.accept); root.addWidget(close)

        dialog.exec()



    def show_latest_saved_match_report(self):

        # Rapport du dernier match OFFICIEL joué (championnat ou coupe) : les amicaux restent dans l'onglet Amicaux.

        conn=db(); row=conn.execute("SELECT id FROM match_record WHERE COALESCE(report,'')<>'' AND COALESCE(fixture_type,'championship')<>'friendly' ORDER BY id DESC LIMIT 1").fetchone(); conn.close()

        if row: self.show_saved_match_report(record_id=int(row["id"]))

        else: self.show_game_message("Rapport indisponible","Aucun rapport de match n'est encore archivé.","info")



    def _training_page(self):

        w,l = self.page_shell("Entraînement", "PLAN COLLECTIF  •  FOCUS INDIVIDUELS  •  PROGRESSION", icon=" ")

        l.setSpacing(8)

        # ---------------- BANDEAU COLLECTIF (onglet 2 SEMAINES) ----------------
