        actions.addWidget(self.training_save_btn)
        hv.addLayout(actions)
        group_layout.addWidget(hero)

        # ---------------- CONTEXTE : STAFF, MATCH, CHARGE, FORME ----------------
        context_row=QHBoxLayout(); context_row.setSpacing(7)

        def context_card(caption, value_color="#e7eef7"):
            card=QFrame(); card.setObjectName("TrainingContext")
            card.setStyleSheet("QFrame#TrainingContext{background:#0f1926;border:1px solid #24344a;border-radius:9px;}")
            card.setMinimumHeight(54); card.setMaximumHeight(62)
            box=QVBoxLayout(card); box.setContentsMargins(9,4,9,4); box.setSpacing(0)
            cap=QLabel(caption); cap.setStyleSheet("font-size:6.5pt;font-weight:900;color:#7f93ad;letter-spacing:.7px;")
            value=QLabel("—"); value.setMinimumWidth(0); value.setSizePolicy(QSizePolicy.Ignored,QSizePolicy.Preferred)
