        def _stat(value,caption,color):
            card=QFrame(); card.setObjectName("AcademyStat")
            card.setStyleSheet("QFrame#AcademyStat{background:#0f1926;border:1px solid #24344a;border-radius:9px;}")
            card.setFixedSize(82,50)
            v=QVBoxLayout(card); v.setContentsMargins(8,3,8,3); v.setSpacing(0)
            val=QLabel(value); val.setStyleSheet(f"font-size:12pt;font-weight:1000;color:{color};")
            cap=QLabel(caption); cap.setStyleSheet("font-size:5.8pt;font-weight:900;color:#7f93ad;letter-spacing:.5px;")
            v.addWidget(val); v.addWidget(cap)
            return card,val
        stats=QHBoxLayout(); stats.setSpacing(6)
        _sy,self.academy_stat_youth=_stat("—","JEUNES","#e8f0f9")
        _st,self.academy_stat_talents=_stat("—","TALENTS","#d9b46a")
