        self.academy_stat_talents.setToolTip("Jeunes du centre avec un potentiel de 17 à 20.")
        self.academy_stat_detect.setToolTip("Journées de détection utilisées cette saison (2 maximum).")
        for _wc in (_sy,_st,_sd): stats.addWidget(_wc)
