    def _status_dot_pixmap(self,color,size=14):
        """Pastille d'état pleine, dessinée : fiable sur tous les écrans."""
        pm=QPixmap(size,size); pm.fill(Qt.transparent)
        p=QPainter(pm)
        try:
            p.setRenderHint(QPainter.Antialiasing)
            col=QColor(color)
            p.setPen(Qt.NoPen)
            halo=QColor(col); halo.setAlpha(70)
            p.setBrush(halo); p.drawEllipse(QPointF(size/2.0,size/2.0),size*0.48,size*0.48)
            p.setBrush(col); p.drawEllipse(QPointF(size/2.0,size/2.0),size*0.32,size*0.32)
        finally:
            p.end()
        return pm

    def _make_icon(self, kind, size=40, color="#9aa6bd"):
        """Icône vectorielle CENTRÉE au pixel près.

        Tout est dessiné dans un repère translaté au centre exact du pixmap :
        aucune conversion en entiers, donc plus de décalage d'un demi-pixel.
        L'épaisseur de trait suit la taille (lisible de 14 à 44 px) et le
        dessin reste dans une marge de sécurité de ~14 % de chaque côté."""
        pix = QPixmap(size, size)
        pix.fill(Qt.transparent)
        p = QPainter(pix)
        try:
            p.setRenderHint(QPainter.Antialiasing)
            p.setRenderHint(QPainter.SmoothPixmapTransform)
            stroke = max(1.25, size * 0.075)
            p.setPen(QPen(QColor(color), stroke, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
            p.setBrush(Qt.NoBrush)
            # Centre EXACT : sur une largeur paire le centre géométrique tombe
            # entre deux pixels, d'où un demi-pixel de compensation.
            c = size / 2.0 + (0.5 if size % 2 == 0 else 0.0)
            p.translate(c, c)          # repère centré : (0,0) = centre de l'icône
            r = size * 0.33            # rayon utile : ~16 % de marge de chaque côté

            def rect(x, y, w, h):
                p.drawRect(QRectF(x, y, w, h))

            def ell(x, y, w, h):
                p.drawEllipse(QRectF(x, y, w, h))

            def line(x1, y1, x2, y2):
                p.drawLine(QPointF(x1, y1), QPointF(x2, y2))

            if kind == 0:      # Trophée/général : grille 2x2
                s = r * 0.86
                for sx in (-1, 1):
                    for sy in (-1, 1):
                        rect(sx * s * 0.52 - s * 0.40, sy * s * 0.52 - s * 0.40, s * 0.80, s * 0.80)
            elif kind == 1:    # Effectif : silhouette
                p.translate(0, r * 0.26)
                ell(-r * 0.34, -r * 0.86, r * 0.68, r * 0.68)
                p.drawArc(QRectF(-r * 0.62, -r * 0.10, r * 1.24, r * 1.05), 0, 180 * 16)
            elif kind == 2:    # Tactiques : trois couches
                p.drawPolygon(QPolygonF([QPointF(0, -r * 0.92), QPointF(r * 0.92, -r * 0.40), QPointF(0, r * 0.12), QPointF(-r * 0.92, -r * 0.40)]))
                line(-r * 0.92, 0, 0, r * 0.52); line(0, r * 0.52, r * 0.92, 0)
                line(-r * 0.92, r * 0.42, 0, r * 0.94); line(0, r * 0.94, r * 0.92, r * 0.42)
            elif kind == 3:    # Match : terrain
                rect(-r * 0.92, -r * 0.58, r * 1.84, r * 1.16)
                line(0, -r * 0.58, 0, r * 0.58)
                ell(-r * 0.26, -r * 0.26, r * 0.52, r * 0.52)
            elif kind == 4:    # Entraînement : chrono/sifflet
                ell(-r * 0.80, -r * 0.80, r * 1.60, r * 1.60)
                line(0, -r * 0.42, 0, 0); line(0, 0, r * 0.46, r * 0.26)
                line(-r * 0.30, -r * 1.00, r * 0.30, -r * 1.00)
            elif kind == 5:    # Bâtiment
                p.translate(0, r * 0.24)
                rect(-r * 0.72, -r * 0.62, r * 1.44, r * 1.24)
                line(-r * 0.72, -r * 0.10, r * 0.72, -r * 0.10)
                rect(-r * 0.22, r * 0.16, r * 0.44, r * 0.46)
                line(-r * 0.72, -r * 0.62, 0, -r * 0.98); line(r * 0.72, -r * 0.62, 0, -r * 0.98)
            elif kind == 6:    # Enveloppe
                rect(-r * 0.94, -r * 0.62, r * 1.88, r * 1.24)
                line(-r * 0.94, -r * 0.62, 0, r * 0.10); line(r * 0.94, -r * 0.62, 0, r * 0.10)
            elif kind == 7:    # Transferts : double flèche
                line(-r * 0.80, -r * 0.26, r * 0.66, -r * 0.26)
                line(r * 0.66, -r * 0.26, r * 0.30, -r * 0.58); line(r * 0.66, -r * 0.26, r * 0.30, r * 0.06)
                line(r * 0.80, r * 0.34, -r * 0.66, r * 0.34)
                line(-r * 0.66, r * 0.34, -r * 0.30, r * 0.02); line(-r * 0.66, r * 0.34, -r * 0.30, r * 0.66)
            elif kind == 8:    # Calendrier
                rect(-r * 0.82, -r * 0.68, r * 1.64, r * 1.50)
                line(-r * 0.82, -r * 0.22, r * 0.82, -r * 0.22)
                line(-r * 0.40, -r * 1.00, -r * 0.40, -r * 0.66)
                line(r * 0.40, -r * 1.00, r * 0.40, -r * 0.66)
            elif kind == 9:    # Finances : courbe
                line(-r * 0.84, r * 0.56, r * 0.84, r * 0.56)
                p.drawPolyline(QPolygonF([QPointF(-r * 0.72, r * 0.30), QPointF(-r * 0.24, -r * 0.16),
                                          QPointF(r * 0.16, r * 0.14), QPointF(r * 0.74, -r * 0.52)]))
            elif kind == 10:   # Staff : deux personnes
                p.translate(0, r * 0.30)
                ell(-r * 0.62, -r * 0.80, r * 0.62, r * 0.62)
                p.drawArc(QRectF(-r * 0.96, -r * 0.14, r * 1.28, r * 1.00), 0, 180 * 16)
                ell(r * 0.14, -r * 0.66, r * 0.50, r * 0.50)
                p.drawArc(QRectF(-r * 0.12, -r * 0.06, r * 1.02, r * 0.86), 0, 180 * 16)
            elif kind == 11:   # Trophée
                rect(-r * 0.60, -r * 0.90, r * 1.20, r * 0.98)
                p.drawArc(QRectF(-r * 1.12, -r * 0.78, r * 0.86, r * 0.94), 90 * 16, 180 * 16)
                p.drawArc(QRectF(r * 0.26, -r * 0.78, r * 0.86, r * 0.94), -90 * 16, 180 * 16)
                line(-r * 0.26, r * 0.10, r * 0.26, r * 0.10)
                line(0, r * 0.10, 0, r * 0.62)
                line(-r * 0.46, r * 0.64, r * 0.46, r * 0.64)
            elif kind == 12:   # Loupe
                ell(-r * 0.90, -r * 0.90, r * 1.28, r * 1.28)
                line(r * 0.34, r * 0.34, r * 0.86, r * 0.86)
            elif kind == 13:   # Disquette
                rect(-r * 0.86, -r * 0.86, r * 1.72, r * 1.72)
                rect(-r * 0.40, -r * 0.86, r * 0.80, r * 0.52)
                rect(-r * 0.56, r * 0.06, r * 1.12, r * 0.80)
            elif kind == 14:   # Livre / archives
                rect(-r * 0.74, -r * 0.88, r * 1.48, r * 1.76)
                line(-r * 0.74, -r * 0.46, r * 0.74, -r * 0.46)
                line(0, -r * 0.88, 0, r * 0.88)
            elif kind == 15:   # Cadenas
                rect(-r * 0.76, -r * 0.10, r * 1.52, r * 1.06)
                p.drawArc(QRectF(-r * 0.52, -r * 0.96, r * 1.04, r * 1.24), 0, 180 * 16)
                ell(-r * 0.12, r * 0.26, r * 0.24, r * 0.24)
            elif kind == 17:   # Plus
                line(-r * 0.70, 0, r * 0.70, 0); line(0, -r * 0.70, 0, r * 0.70)
            elif kind == 18:   # Lecture
                p.drawPolygon(QPolygonF([QPointF(-r * 0.42, -r * 0.62), QPointF(r * 0.72, 0),
                                         QPointF(-r * 0.42, r * 0.62)]))
            elif kind == 16:   # Cartes / documents
                rect(-r * 0.88, -r * 0.70, r * 1.66, r * 1.34)
                line(-r * 0.58, -r * 0.22, r * 0.52, -r * 0.22)
                line(-r * 0.58, r * 0.20, r * 0.24, r * 0.20)
            elif kind == 31:   # Médical : croix dans un cercle
                ell(-r * 0.92, -r * 0.92, r * 1.84, r * 1.84)
                line(-r * 0.46, 0, r * 0.46, 0); line(0, -r * 0.46, 0, r * 0.46)
            elif kind == 32:   # Haltère (préparateur physique)
                line(-r * 0.86, -r * 0.58, -r * 0.86, r * 0.58)
                line(-r * 0.54, -r * 0.32, -r * 0.54, r * 0.32)
                line(r * 0.54, -r * 0.32, r * 0.54, r * 0.32)
                line(r * 0.86, -r * 0.58, r * 0.86, r * 0.58)
                line(-r * 0.54, 0, r * 0.54, 0)
            elif kind == 33:   # Mégaphone (marketing)
                p.drawPolygon(QPolygonF([QPointF(-r * 0.88, -r * 0.30), QPointF(r * 0.18, -r * 0.82),
                                         QPointF(r * 0.18, r * 0.82), QPointF(-r * 0.88, r * 0.30)]))
                line(r * 0.18, -r * 0.82, r * 0.62, -r * 0.98)
                line(r * 0.18, r * 0.82, r * 0.62, r * 0.98)
                line(r * 0.18, -r * 0.82, r * 0.18, r * 0.82)
                line(-r * 0.52, r * 0.56, -r * 0.34, r * 0.96)
            elif kind == 34:   # Presse-papiers (directeur sportif)
                rect(-r * 0.62, -r * 0.76, r * 1.24, r * 1.66)
                rect(-r * 0.24, -r * 0.98, r * 0.48, r * 0.36)
                line(-r * 0.30, -r * 0.26, r * 0.32, -r * 0.26)
                line(-r * 0.30, r * 0.14, r * 0.32, r * 0.14)
                line(-r * 0.30, r * 0.54, r * 0.08, r * 0.54)
            elif kind == 35:   # Sifflet (adjoint)
                ell(-r * 0.92, -r * 0.36, r * 1.12, r * 0.80)
                line(r * 0.16, -r * 0.10, r * 0.88, -r * 0.10)
                line(r * 0.88, -r * 0.10, r * 0.88, r * 0.26)
                line(r * 0.16, r * 0.26, r * 0.88, r * 0.26)
                ell(-r * 0.62, -r * 0.16, r * 0.30, r * 0.30)
            elif kind == 36:   # Équerre (architecte)
                line(-r * 0.80, r * 0.74, r * 0.80, r * 0.74)
                line(-r * 0.80, r * 0.74, -r * 0.80, -r * 0.80)
                line(-r * 0.34, r * 0.74, -r * 0.34, r * 0.16)
                line(-r * 0.34, r * 0.16, r * 0.34, r * 0.16)
                line(r * 0.34, r * 0.16, r * 0.34, -r * 0.34)
            elif kind == 38:   # Calculatrice (comptable)
                rect(-r * 0.62, -r * 0.92, r * 1.24, r * 1.84)
                rect(-r * 0.34, -r * 0.70, r * 0.68, r * 0.30)
                for _gx in (-r * 0.30, 0.0, r * 0.30):
                    for _gy in (-r * 0.06, r * 0.34, r * 0.70):
                        ell(_gx - r * 0.09, _gy - r * 0.09, r * 0.18, r * 0.18)
            elif kind == 40:   # Tribunes : gradins
                for k in range(3):
                    rect(-r*0.88, -r*0.30+k*r*0.36, r*1.76-k*r*0.30, r*0.17)
            elif kind == 41:   # Projecteur / éclairage
                p.drawPolygon(QPolygonF([QPointF(-r*0.34,-r*0.88),QPointF(r*0.34,-r*0.88),
                                         QPointF(r*0.18,-r*0.46),QPointF(-r*0.18,-r*0.46)]))
                line(-r*0.18,-r*0.46,-r*0.54,r*0.34); line(r*0.18,-r*0.46,r*0.54,r*0.34)
                line(-r*0.54,r*0.34,r*0.54,r*0.34)
            elif kind == 42:   # Parking : P
                p.drawRoundedRect(QRectF(-r*0.80,-r*0.80,r*1.60,r*1.60),r*0.24,r*0.24)
                line(-r*0.26,-r*0.50,-r*0.26,r*0.50)
                line(-r*0.26,-r*0.50,r*0.02,-r*0.50)
                line(-r*0.26,r*0.02,r*0.02,r*0.02)
                p.drawArc(QRectF(-r*0.26,-r*0.52,r*0.70,r*0.55),-90*16,180*16)
            elif kind == 44:   # Centre de formation : chapeau
                p.drawPolygon(QPolygonF([QPointF(0,-r*0.52),QPointF(r*0.88,-r*0.10),
                                         QPointF(0,r*0.32),QPointF(-r*0.88,-r*0.10)]))
                line(-r*0.50,-r*0.10,-r*0.50,r*0.42)
                line(-r*0.50,r*0.42,-r*0.26,r*0.54)
                line(0,-r*0.02,0,r*0.46)
            elif kind == 46:   # Bar : verre
                p.drawPolygon(QPolygonF([QPointF(-r*0.44,-r*0.74),QPointF(r*0.44,-r*0.74),
                                         QPointF(r*0.18,r*0.08),QPointF(-r*0.18,r*0.08)]))
                line(0,r*0.08,0,r*0.56); line(-r*0.36,r*0.60,r*0.36,r*0.60)
                line(-r*0.32,-r*0.48,r*0.32,-r*0.48)
            elif kind == 47:   # Étoile (loge / VIP)
                from math import cos, sin, radians
                pts=[QPointF(cos(radians(-90+k*36))*r*(0.94 if k%2==0 else 0.40),
                             sin(radians(-90+k*36))*r*(0.94 if k%2==0 else 0.40)) for k in range(10)]
                p.drawPolygon(QPolygonF(pts))
            elif kind == 48:   # Boutique : sac
                p.drawRoundedRect(QRectF(-r*0.62,-r*0.24,r*1.24,r*1.08),r*0.10,r*0.10)
                p.drawArc(QRectF(-r*0.34,-r*0.76,r*0.68,r*0.70),0,180*16)
            elif kind == 49:   # Fan zone / événement : drapeau
                line(-r*0.62,-r*0.86,-r*0.62,r*0.88)
                p.drawPolygon(QPolygonF([QPointF(-r*0.62,-r*0.78),QPointF(r*0.80,-r*0.48),
                                         QPointF(-r*0.62,-r*0.10)]))
            elif kind == 50:   # Snack : hot-dog
                p.drawRoundedRect(QRectF(-r*0.80,-r*0.26,r*1.60,r*0.52),r*0.26,r*0.26)
                line(-r*0.46,0,r*0.46,0)
            elif kind == 51:   # Écharpe supporters
                p.drawRoundedRect(QRectF(-r*0.82,-r*0.18,r*1.64,r*0.36),r*0.08,r*0.08)
                for _k in range(3):
                    line(-r*0.70+_k*r*0.30,r*0.18,-r*0.70+_k*r*0.30,r*0.50)
            elif kind == 52:   # Casquette
                p.drawArc(QRectF(-r*0.60,-r*0.62,r*1.20,r*1.08),0,180*16)
                line(-r*0.86,r*0.24,r*0.48,r*0.24)
                line(r*0.48,r*0.24,r*0.74,r*0.40)
            elif kind == 60:   # Courrier : drapeau « à traiter »
                line(-r*0.56,-r*0.86,-r*0.56,r*0.88)
                p.drawPolygon(QPolygonF([QPointF(-r*0.56,-r*0.80),QPointF(r*0.74,-r*0.52),
                                         QPointF(-r*0.56,-r*0.20)]))
            elif kind == 61:   # Dossier
                p.drawRoundedRect(QRectF(-r*0.86,-r*0.56,r*1.72,r*1.24),r*0.16,r*0.16)
                line(-r*0.86,-r*0.24,-r*0.24,-r*0.24)
                line(-r*0.24,-r*0.56,-r*0.24,-r*0.72)
            elif kind == 62:   # Journal / presse
                rect(-r*0.82,-r*0.60,r*1.64,r*1.28)
                line(-r*0.62,-r*0.32,r*0.08,-r*0.32)
                line(-r*0.62,-r*0.04,r*0.08,-r*0.04)
                line(r*0.28,-r*0.32,r*0.62,-r*0.32)
                line(r*0.28,-r*0.04,r*0.62,-r*0.04)
            elif kind == 63:   # Horloge / historique
                ell(-r*0.78,-r*0.78,r*1.56,r*1.56)
                line(0,-r*0.42,0,0); line(0,0,r*0.42,r*0.26)
            elif kind == 65:   # Couronne de champion
                p.drawPolygon(QPolygonF([
                    QPointF(-r*0.88, r*0.30), QPointF(-r*0.66,-r*0.56), QPointF(-r*0.22, 0.0),
                    QPointF(0.0,-r*0.76), QPointF(r*0.22, 0.0), QPointF(r*0.66,-r*0.56),
                    QPointF(r*0.88, r*0.30)]))
                line(-r*0.88, r*0.30, r*0.88, r*0.30)
                line(-r*0.72, r*0.64, r*0.72, r*0.64)
            elif kind == 66:   # Flèche haut (promotion)
                line(0, r*0.72, 0, -r*0.72)
                line(0, -r*0.72, -r*0.46, -r*0.24); line(0, -r*0.72, r*0.46, -r*0.24)
            elif kind == 67:   # Flèche bas (relégation)
                line(0, -r*0.72, 0, r*0.72)
                line(0, r*0.72, -r*0.46, r*0.24); line(0, r*0.72, r*0.46, r*0.24)
            elif kind == 64:   # Point « non lu »
                p.setPen(Qt.NoPen); p.setBrush(QBrush(QColor(color)))
                ell(-r*0.34,-r*0.34,r*0.68,r*0.68)
            elif kind == 300:  # Menu : 3 barres
                for y in (-r * 0.46, 0.0, r * 0.46):
                    line(-r * 0.78, y, r * 0.78, y)
            elif kind == 301:  # Options : engrenage
                ell(-r * 0.52, -r * 0.52, r * 1.04, r * 1.04)
                ell(-r * 0.18, -r * 0.18, r * 0.36, r * 0.36)
                from math import cos, sin, radians
                for ang in range(0, 360, 45):
                    a = radians(ang)
                    line(cos(a) * r * 0.62, sin(a) * r * 0.62, cos(a) * r * 0.88, sin(a) * r * 0.88)
            elif kind == 302:  # Retour
                line(r * 0.70, 0, -r * 0.62, 0)
                line(-r * 0.62, 0, -r * 0.14, -r * 0.44); line(-r * 0.62, 0, -r * 0.14, r * 0.44)
            elif kind == 303:  # Quitter : symbole power
                p.drawArc(QRectF(-r * 0.74, -r * 0.74, r * 1.48, r * 1.48), 60 * 16, 240 * 16)
                line(0, -r * 0.95, 0, -r * 0.10)
            else:
                ell(-r * 0.62, -r * 0.62, r * 1.24, r * 1.24)
        finally:
            p.end()
        return pix

