    def _mail_folder_combo_changed(self, index):

        if not hasattr(self, "mail_folder_combo") or index < 0:

            return

        key = self.mail_folder_combo.itemData(index)

        if key and key != getattr(self, "msg_filter", "all"):

            self._set_message_filter(key)

    def _set_message_filter(self, key):

        self.msg_filter=key

        for k,chip in getattr(self,"msg_filter_chips",{}).items():

            chip.setChecked(k==key)

        combo=getattr(self,"mail_folder_combo",None)

        if combo is not None:

            index=combo.findData(key)

            if index>=0:

                combo.blockSignals(True); combo.setCurrentIndex(index); combo.blockSignals(False)

        title=getattr(self,"mail_folder_title",None)

        if title is not None and key in getattr(self,"msg_categories",{}):

            title.setText(self.msg_categories[key][0])

        self._refresh_messages_ui()



    def delete_all_messages(self):

        """Supprime la totalite de la messagerie apres confirmation manuelle.

        PROTECTION : les dossiers EN ATTENTE restent vivants — leur reponse
        arrivera quand meme."""

        conn=db()

        count=int(conn.execute("SELECT COUNT(*) n FROM manager_message").fetchone()["n"])

        pending=int(conn.execute("SELECT COUNT(*) n FROM manager_message WHERE status='waiting'").fetchone()["n"])

        conn.close()

        if count==0:

            self.show_game_message("Messagerie","La boite de reception est deja vide.","info"); return

        keep=f" {pending} dossier(s) en cours resteront actifs : les reponses arriveront normalement." if pending else ""

        if not self.show_game_message("Tout supprimer", f"{count} message(s) seront supprimes definitivement.{keep}", "warning", confirm=True, confirm_text="TOUT SUPPRIMER"):

            return

        conn=db(); conn.execute("DELETE FROM manager_message WHERE status<>'waiting'"); conn.commit(); conn.close()

        self._manager_messages=[]

        if hasattr(self,"msg_badge"): self.msg_badge.setVisible(False)

        if hasattr(self,"inbox_nav_badge"): self.inbox_nav_badge.setVisible(False)

        self.show_game_message("Messagerie", f"{count} message(s) supprimes.", "info")

        conn=db(); rows=conn.execute("SELECT * FROM manager_message ORDER BY id DESC LIMIT 400").fetchall(); conn.close()

        self.refresh_manager_message_queue(rows)

        self._refresh_messages_ui()



    def _message_outcome(self, msg):
        """Issue enregistrée dans le dossier (accepted, rival, refused…)."""
        try:
            data=json.loads(msg.get("action_data") or "{}")
        except Exception:
            data={}
        return str(data.get("outcome") or "")

    def _message_is_actionable(self, msg):
        """Un message qui attend VRAIMENT une décision du manager.

        Un dossier clos (accepté, refusé, signé ailleurs, joueur parti) reste
        lisible mais ne doit plus compter dans « À traiter » ni afficher de
        boutons d'action.
        """
        if str(msg.get("status") or "")!="ready":
            return False
        if self._message_outcome(msg) in ("accepted","refused","rejected","rival","unavailable",
                                          "joined","already_sold","cancelled","closed","expired"):
            return False
        return str(msg.get("kind") or "") in ("market_offer","transfer_sale","transfer_sale_counter",
                                              "contract_offer","free_agent_contract")

    def _message_category(self, kind):

        """Categorie de la messagerie qui regroupe ce type de message."""

        for key,meta in getattr(self,"msg_categories",{}).items():

            kinds=meta[1] if len(meta)>1 else None

            if kinds and kind in kinds:

                return key

        return "club"



    def _category_enabled(self, key):

        """Option MESSAGERIE : afficher ou masquer une famille de messages."""

        opts=getattr(self,"game_options",None) or {}

        if key=="presse":

            return bool(opts.get("msg_media", False))

        option={"dossiers":"msg_cat_dossiers","scouting":"msg_cat_scouting","matchs":"msg_cat_matchs",
                "club":"msg_cat_club","saison":"msg_cat_saison","carriere":"msg_cat_carriere",
                "systeme":"msg_cat_systeme"}.get(key)

        return bool(opts.get(option, True)) if option else True



    def _media_messages_hidden(self):

        return not bool((getattr(self,"game_options",None) or {}).get("msg_media", False))



    def _scout_digest_table(self,profiles):
        """Fiches du mois : cartes compactes, une par joueur trouvé."""
        cards=""
        for pr in profiles[:12]:
            try:
                club=str(pr.get("club") or "Joueur libre")
                if int(pr.get("division") or 0): club=f"{club} · L{int(pr['division'])}"
                age=int(pr.get("age") or 0)
                know=max(0,min(100,int(pr.get("knowledge") or 0)))
                val=int(pr.get("value") or 0)
            except Exception:
                continue
            tone=("#7de0aa" if know>=80 else "#c9d6e6" if know>=50 else "#93a6bf")
            meta=" • ".join([club,str(pr.get("position") or "—")]+([f"{age} ans"] if age else []))
            value_line=(f"<div style='color:#9fb0c4;font-size:8pt;margin-top:2px'>Valeur estimée "
                        f"{html.escape(format_euros(val))}</div>") if val else ""
            cards+=("<tr><td style='padding:0 0 6px 0'>"
                    "<table width='100%' cellspacing='0' cellpadding='0' "
                    "style='background:#0e1a29;border:1px solid #22344c'>"
                    "<tr><td style='padding:8px 11px'>"
                    f"<div style='font-size:9.5pt;font-weight:700;color:#eef4fb'>{html.escape(str(pr.get('name') or '—'))}"
                    f"<span style='color:{tone};font-size:8.5pt;font-weight:700'> &nbsp;·&nbsp; fiche {know} %</span></div>"
                    f"<div style='color:#a9bccf;font-size:8pt;margin-top:2px'>{html.escape(meta)}</div>"
                    f"{value_line}"
                    "</td></tr></table></td></tr>")
        if not cards: return ""
        return ("<div style='color:#7f93ad;font-size:7.5pt;font-weight:900;letter-spacing:.6px;"
                "margin:16px 0 6px 0'>FICHES OUVERTES CE MOIS-CI</div>"
                f"<table width='100%' cellspacing='0' cellpadding='0'>{cards}</table>"
                "<div style='color:#7f93ad;font-size:8pt;margin-top:2px'>"
                "La fiabilité progresse à chaque mission de scouting.</div>")

    def _message_kind_meta(self, kind, status=""):

        """(badge, couleur, libelle) pour la liste et le detail."""

        kind=str(kind or "")

        if kind=="match_report": return "MA","#a99bd0","RAPPORT DE MATCH"

        if kind=="scout_report": return "SC","#9d8fc4","SCOUTING"
        if kind=="scout_digest": return "SC","#9d8fc4","RAPPORT MENSUEL"

        if kind in ("contract_offer","free_agent_contract"): return "CT","#6fa58a","CONTRAT"

        if kind in ("market_offer","transfer_arrival"): return "TR","#8fa9c4","TRANSFERT"

        if kind in ("transfer_sale","transfer_sale_counter","transfer_departure"): return "VE","#b08d6a","VENTE"

        if kind in ("loan_request","loan_out_request"): return "PR","#7f9db8","PRÊT"

        if kind in ("contract_departure","contract_expired"): return "CT","#b08d6a","CONTRAT"

        if kind=="media": return "PS","#9a8496","PRESSE"

        if kind in ("season_summary","season_title","season_break","season_ready"): return "SA","#8d9bb5","SAISON"

        if kind in ("facility_complete","training_injury"): return "CL","#7fa58f","CLUB"

        if kind=="system": return "SY","#7f8fa8","SYSTÈME"

        if kind=="club_news": return "CL","#7f93ad","INFO CLUB"

        if kind=="job_offer": return "SE","#d9b46a","SECRET • OFFRE DE CLUB"

        return "MS","#7f93ad","MESSAGE"



    def _message_status_code(self, msg):

        kind=str(msg.get("kind") or "")

        if kind in ("match_report","scout_report"):

            return "report"

        outcome=self._message_outcome(msg)

        if outcome=="rival":

            return "rival"

        if outcome in ("accepted","joined"):

            return "accepted"

        if outcome in ("refused","rejected","unavailable","cancelled","already_sold","closed","expired"):

            return "closed"

        status=str(msg.get("status") or "")

        if status=="ready": return "ready"

        if status=="waiting": return "waiting"

        return "done"



    def _refresh_messages_ui(self):

        """Reconstruit la liste : familles, non-lus, a traiter, tri et recherche."""

        if not hasattr(self, "action_message_list"):

            return

        current_item=self.action_message_list.currentItem()

        selected_id=current_item.data(Qt.UserRole) if current_item else None

        self.action_message_list.blockSignals(True); self.action_message_list.clear()

        search = (self.msg_search.text() or "").strip().lower()

        conn = db()

        # Identite du club : un changement de club doit se voir ici aussi.
        try:
            _club = conn.execute("SELECT name,color1 FROM club WHERE id=1").fetchone()
            if _club is not None and str(_club["name"] or "").strip():
                _name = str(_club["name"]); _color = str(_club["color1"] or "#6f8fb5")
                self.mail_club_name = _name
                self.mail_club_address = "direction@%s.fm" % self._mail_slug(_name)
                if hasattr(self, "mail_name_label"):
                    self.mail_name_label.setText(_name if len(_name) <= 21 else _name[:20] + "…")
                    self.mail_name_label.setToolTip(_name)
                if hasattr(self, "mail_addr_label"):
                    _addr = self.mail_club_address
                    self.mail_addr_label.setText(_addr if len(_addr) <= 29 else _addr[:28] + "…")
                    self.mail_addr_label.setToolTip(_addr)
                if hasattr(self, "mail_avatar_label"):
                    _ini = "".join(part[0] for part in _name.split()[:2]).upper() or "FC"
                    self.mail_avatar_label.setPixmap(self._mail_avatar(_ini, 38, _color))
        except Exception:
            pass

        messages = conn.execute("SELECT * FROM manager_message ORDER BY id DESC LIMIT 240").fetchall()

        conn.close()

        # Familles masquees par les options.
        visible=[]
        for message in messages:
            category=self._message_category(message.get("kind",""))
            if not self._category_enabled(category):
                continue
            if str(message.get("kind") or "")=="scout_report":
                continue
            if str(message.get("kind") or "")=="media" and self._media_messages_hidden():
                continue
            visible.append(message)
        messages=[message for message in visible if str(message.get("kind") or "")!="scout_report"]
        unread_count=self.message_badge_count()
        action_count=sum(1 for message in messages if self._message_is_actionable(message))

        self._apply_message_badges(unread_count)

        dossiers_count=sum(1 for message in messages if self._message_category(message.get("kind",""))=="dossiers")

        if hasattr(self,"msg_hero_unread"):
            self.msg_hero_unread.setText(str(unread_count))
        if hasattr(self,"msg_hero_action"):
            self.msg_hero_action.setText(str(action_count))
        if hasattr(self,"msg_hero_dossiers"):
            self.msg_hero_dossiers.setText(str(dossiers_count))
        if hasattr(self,"msg_hero_sub"):
            self.msg_hero_sub.setText(f"{getattr(self,'mail_club_address','boite@club.fm')}  •  "
                                      f"{len(messages)} message(s)  •  {unread_count} non lu(s)")

        # Compteurs des pastilles.
        if hasattr(self,"msg_filter_chips") and hasattr(self,"msg_categories"):
            folder_counts=getattr(self,"msg_folder_counts",{})
            for key,chip in self.msg_filter_chips.items():
                if key=="all":
                    count=len(messages)
                elif key=="unread":
                    count=unread_count
                elif key=="action":
                    count=action_count
                else:
                    kinds=self.msg_categories[key][1]
                    count=sum(1 for message in messages if message.get("kind") in kinds)
                badge=folder_counts.get(key)
                if badge is not None:
                    badge.setText(str(count) if count else "")
                    badge.setVisible(count>0)

        filtered=[]
        for msg in messages:

            title = msg["title"] or ""

            body = msg["body"] or ""

            kind = msg.get("kind", "")

            current_filter=getattr(self,"msg_filter","all")

            if current_filter=="unread" and msg["is_read"]:

                continue

            if current_filter=="action" and not self._message_is_actionable(msg):

                continue

            if current_filter not in ("all","unread","action") and self._message_category(kind)!=current_filter:

                continue

            if search:

                hay=" ".join((str(title),str(body),str(kind),self._message_kind_meta(kind)[2])).lower()

                if search not in hay:

                    continue

            filtered.append(msg)

        sort_mode=self.msg_sort.currentText() if hasattr(self,"msg_sort") else "Plus récents"

        if sort_mode=="Plus anciens":
            filtered.sort(key=lambda m:int(m["id"] or 0))
        elif sort_mode=="Prioritaires":
            filtered.sort(key=lambda m:(0 if str(m.get("status") or "")=="ready" else 1,
                                        0 if not m["is_read"] else 1,
                                        -int(m["id"] or 0)))
        else:
            filtered.sort(key=lambda m:int(m["id"] or 0), reverse=True)

        if hasattr(self,"inbox_subtitle"):

            plural="s" if len(filtered)>1 else ""

            self.inbox_subtitle.setText(f"{len(filtered)} message{'s' if len(filtered)>1 else ''}  •  "
                                        f"{unread_count} non lu{'s' if unread_count>1 else ''}")

        for msg in filtered:

            title = str(msg["title"] or "")

            body = str(msg["body"] or "")

            kind = str(msg.get("kind", ""))

            badge,color,label=self._message_kind_meta(kind,msg.get("status",""))

            preview=" ".join(body.split())[:118]

            if len(body)>118: preview+="…"

            status_code=self._message_status_code(msg)

            date_label = fmt_date_fr(msg["created_date"]) if msg["created_date"] else ""

            item = QListWidgetItem()

            item.setData(Qt.UserRole, msg["id"])

            item.setData(MessageListDelegate.ROLE_TITLE, title)

            item.setData(MessageListDelegate.ROLE_PREVIEW, preview or label)

            item.setData(MessageListDelegate.ROLE_DATE, date_label)

            item.setData(MessageListDelegate.ROLE_STATUS, status_code)

            item.setData(MessageListDelegate.ROLE_UNREAD, not bool(msg["is_read"]))

            item.setData(MessageListDelegate.ROLE_COLOR, color)

            item.setData(MessageListDelegate.ROLE_BADGE, badge)

            item.setData(MessageListDelegate.ROLE_KIND, label)
            sender, _address, initials, _sender_color = self._message_sender(msg)
            item.setData(MessageListDelegate.ROLE_SENDER, sender)
            item.setData(MessageListDelegate.ROLE_INITIALS, initials)

            item.setSizeHint(QSize(360, 76))

            item.setToolTip(f"{title}\n{body[:180]}")

            self.action_message_list.addItem(item)

        self.action_message_list.blockSignals(False)

        # Selection conservee si le message est toujours visible.
        reselected=False

        if selected_id is not None:

            for row in range(self.action_message_list.count()):

                if self.action_message_list.item(row).data(Qt.UserRole)==selected_id:

                    if self.action_message_list.currentRow()==row:

                        self._on_message_selected(row)

                    else:

                        self.action_message_list.setCurrentRow(row)

                    reselected=True; break

        if not reselected:

            if self.action_message_list.count()==0:

                while self.msg_action_bar.count():

                    bar_item=self.msg_action_bar.takeAt(0)

                    w=bar_item.widget()

                    if w is not None:
                        w.setParent(None); w.deleteLater()

                if hasattr(self,"msg_detail_hint"):
                    self.msg_detail_hint.setText("Aucun message")
                self.action_message_detail.setHtml(
                    "<div style='color:#93a6bf;padding:28px;text-align:center;font-family:Segoe UI'>"
                    "<h3 style='color:#e6eef8'>Aucun message dans ce filtre</h3>"
                    "<p>Essaie une autre famille, efface la recherche ou change le tri.</p></div>")
            elif not self.action_message_list.currentItem():

                # Pas de sélection automatique : ouvrir un filtre ne doit pas
                # marquer le premier message comme lu à la place du manager.
                if hasattr(self,"msg_detail_hint"):
                    self.msg_detail_hint.setText("Sélectionne un message")
                self.action_message_detail.setHtml(
                    "<div style='color:#93a6bf;padding:28px;text-align:center;font-family:Segoe UI'>"
                    "<h3 style='color:#e6eef8'>Sélectionne un message</h3>"
                    "<p>Clique une ligne à gauche pour lire le courrier et afficher ses actions.</p></div>")

    def _on_message_selected(self, row):

        if getattr(self, "_mail_refresh_guard", False):

            return

        if row < 0 or not hasattr(self, "action_message_list"):

            return

        item = self.action_message_list.item(row)

        if not item:

            return

        msg_id = item.data(Qt.UserRole)

        conn = db()

        msg = conn.execute("SELECT * FROM manager_message WHERE id=?", (msg_id,)).fetchone()

        conn.close()

        if not msg:

            return

        # Marquer comme lu (option de lecture + compteur resynchronise en fin de lecture).
        _skip_read = getattr(self, "_skip_read_once", None)

        if _skip_read is not None and int(msg_id) == int(_skip_read):

            self._skip_read_once = None

        elif not msg["is_read"] and bool((getattr(self, "game_options", None) or {}).get("msg_mark_read", True)):

            conn = db()

            conn.execute("UPDATE manager_message SET is_read=1 WHERE id=?", (msg_id,))

            conn.commit(); conn.close()

            msg = dict(msg); msg["is_read"] = 1

            item.setData(MessageListDelegate.ROLE_UNREAD, False)

        kind = msg.get("kind", "")

        badge, kind_color, kind_label = self._message_kind_meta(kind, msg.get("status", ""))

        status_value = msg.get("status", "")

        outcome = self._message_outcome(msg)

        if outcome == "rival":

            status_html="<span style='background:#3a1b22;color:#ff9daa;padding:3px 11px;border-radius:9px;font-size:9px;font-weight:900;letter-spacing:1px'>SIGNÉ AILLEURS</span>"

        elif outcome in ("accepted", "joined"):

            status_html="<span style='background:#12251c;color:#7de0aa;padding:3px 11px;border-radius:9px;font-size:9px;font-weight:900;letter-spacing:1px'>ACCEPTÉ</span>"

        elif outcome in ("refused", "rejected"):

            status_html="<span style='background:#1a2436;color:#9fb0c8;padding:3px 11px;border-radius:9px;font-size:9px;font-weight:900;letter-spacing:1px'>REFUSÉ</span>"

        elif outcome in ("unavailable", "already_sold", "cancelled", "closed", "expired"):

            status_html="<span style='background:#1a2436;color:#9fb0c8;padding:3px 11px;border-radius:9px;font-size:9px;font-weight:900;letter-spacing:1px'>DOSSIER CLOS</span>"

        elif outcome in ("counter", "player_counter"):

            status_html="<span style='background:#3a3413;color:#e0b25c;padding:3px 11px;border-radius:9px;font-size:9px;font-weight:900;letter-spacing:1px'>CONTRE-OFFRE</span>"

        elif str(kind or "") == "job_offer":

            status_html="<span style='background:#3a2c12;color:#f0c674;padding:3px 11px;border-radius:9px;font-size:9px;font-weight:900;letter-spacing:1px'>CONFIDENTIEL</span>"

        elif str(kind or "") == "scout_digest":
            status_html="<span style='background:#1c2536;color:#a9bccc;padding:3px 11px;border-radius:9px;font-size:9px;font-weight:900;letter-spacing:1px'>RAPPORT MENSUEL</span>"

        elif status_value == "ready":

            status_html="<span style='background:#3a3413;color:#e0b25c;padding:3px 11px;border-radius:9px;font-size:9px;font-weight:900;letter-spacing:1px'>À TRAITER</span>"

        elif status_value == "waiting":

            status_html="<span style='background:#152a3f;color:#9fc4ff;padding:3px 11px;border-radius:9px;font-size:9px;font-weight:900;letter-spacing:1px'>EN ATTENTE</span>"

        else:

            status_html="<span style='background:#1a2436;color:#8b96af;padding:3px 11px;border-radius:9px;font-size:9px;font-weight:900;letter-spacing:1px'>LU</span>"

        data = {}

        try:

            data = json.loads(msg.get("action_data", "{}") or "{}")

        except Exception:

            data = {}

        body_html = html.escape(clean_message_text(msg.get("body", ""))).replace("\n", "<br>")
        if str(kind or "") == "scout_digest" and isinstance(data.get("players_info"), list) and data["players_info"]:
            body_html += self._scout_digest_table(data["players_info"])

        facts=[]

        def fact(label,value):
            if value not in (None,"",0):
                facts.append((str(label),str(value)))

        fact("JOUEUR",data.get("player_name"))
        fact("CLUB",data.get("buyer_name"))
        if data.get("fee"): fact("MONTANT",f"{int(data['fee']):,} €".replace(","," "))
        if data.get("buyer_limit"): fact("PLAFOND ACHETEUR",f"{int(data['buyer_limit']):,} €".replace(","," "))
        if data.get("offer_salary"): fact("SALAIRE PROPOSÉ",f"{int(data['offer_salary']):,} €/mois".replace(","," "))
        if data.get("offer_years"): fact("DURÉE",f"{int(data['offer_years'])} an(s)")
        if data.get("premium_pct"): fact("PRIME SUR VALEUR",f"+{int(data['premium_pct'])} %")
        if data.get("interest_reason"): fact("PROJET DU CLUB",data.get("interest_reason"))
        facts_html=""
        if facts:
            rows="".join(f"<tr><td style='color:#7f93ad;font-size:8.5px;font-weight:900;padding:4px 12px 4px 0'>{html.escape(k)}</td>"
                         f"<td style='color:#dce7f4;font-size:9.5px;padding:4px 0'>{html.escape(v)}</td></tr>" for k,v in facts)
            facts_html=("<table cellspacing='0' cellpadding='0' style='margin:12px 0;background:#0d1927;"
                        "border:1px solid #22344c;border-radius:8px;padding:8px 12px'>"+rows+"</table>")

        due_line=""
        if msg.get("due_date") and (status_value=="waiting" or self._message_is_actionable(msg)):
            due_line=f"  •  échéance : {fmt_date_fr(msg.get('due_date',''))}"

        sender_name, sender_address, _sender_initials, sender_color = self._message_sender(msg)

        club_address = getattr(self, "mail_club_address", "boite@club.fm")

        html_content = f"""
        <body style='background:#0c1622;color:#dce7f3'>
        <table width='100%' cellspacing='0' cellpadding='0'><tr>
          <td width='4' bgcolor='{sender_color}'></td>
          <td style='padding-left:12px'>
            <div style='font-size:11.5pt;font-weight:700;color:#f4f8fd'>{html.escape(sender_name)}</div>
            <div style='font-size:8pt;color:#8296ad;margin-top:2px'>{html.escape(sender_address)}
              &nbsp;•&nbsp; à {html.escape(club_address)}</div>
          </td>
          <td align='right' valign='top' style='padding-left:10px'>
            <div style='font-size:8pt;color:#8296ad'>{fmt_date_fr(msg.get('created_date',''))}</div>
            <div style='margin-top:6px'>{status_html}</div>
          </td>
        </tr></table>
        <h1 style='font-size:16pt;color:#f6f9fd;margin:14px 0 5px 0'>{html.escape(msg.get('title',''))}</h1>
        <div style='font-size:8pt;color:#7f93ad;margin-bottom:4px'>{kind_label}  •  reçu le {fmt_date_fr(msg.get('created_date',''))}{due_line}</div>
        {facts_html}
        <hr style='border:0;border-top:1px solid #22344c;margin:14px 0'>
        <p style='line-height:1.7;margin:8px 0;font-size:10.5pt'>{body_html}</p>
        <hr style='border:0;border-top:1px solid #1e2e44;margin:20px 0 10px 0'>
        <div style='font-size:8pt;color:#7f93ad;line-height:1.55'>
          <b style='color:#9fb2c8'>{html.escape(sender_name)}</b><br>
          {html.escape(sender_address)}<br>
          Envoyé à {html.escape(club_address)}
        </div>
        </body>
        """

        self.action_message_detail.setHtml(html_content)

        try:

            self.action_message_detail.verticalScrollBar().setValue(0)

            self.action_message_detail.repaint()

        except Exception:

            pass

        if hasattr(self,"msg_detail_hint"):
            self.msg_detail_hint.setText(f"{kind_label}  •  {fmt_date_fr(msg.get('created_date',''))}")

        # Boutons d'action contextuels.
        while self.msg_action_bar.count():

            it = self.msg_action_bar.takeAt(0)

            w = it.widget()

            if w is not None:

                w.setParent(None); w.deleteLater()

        ready = self._message_is_actionable(msg)

        player_id = data.get("player_id")

        if kind in ("market_offer", "transfer_sale", "transfer_sale_counter") and ready:

            _accept_label="ACCEPTER LE PRIX" if outcome == "counter" else "ACCEPTER"

            btn_accepter = QPushButton(_accept_label); btn_accepter.setObjectName("Primary"); btn_accepter.setMinimumHeight(34)

            btn_accepter.clicked.connect(lambda: self._resolve_message(msg_id, "accept"))

            self.msg_action_bar.addWidget(btn_accepter)

            btn_refuser = QPushButton("REFUSER"); btn_refuser.setMinimumHeight(34)

            btn_refuser.clicked.connect(lambda: self._resolve_message(msg_id, "reject"))

            self.msg_action_bar.addWidget(btn_refuser)

        elif kind in ("contract_offer", "free_agent_contract") and ready:

            _sign_label="ACCEPTER LA CONTRE-OFFRE" if outcome == "counter" else "SIGNER"

            btn_signer = QPushButton(_sign_label); btn_signer.setObjectName("Primary"); btn_signer.setMinimumHeight(34)

            btn_signer.clicked.connect(lambda: self._resolve_message(msg_id, "accept"))

            self.msg_action_bar.addWidget(btn_signer)

            btn_refuser = QPushButton("REFUSER"); btn_refuser.setMinimumHeight(34)

            btn_refuser.clicked.connect(lambda: self._resolve_message(msg_id, "reject"))

            self.msg_action_bar.addWidget(btn_refuser)

        elif kind == "scout_report" and ready:

            btn_voir = QPushButton("VOIR LE RAPPORT"); btn_voir.setObjectName("Primary"); btn_voir.setMinimumHeight(34)

            btn_voir.clicked.connect(lambda: self.show_page(7))

            self.msg_action_bar.addWidget(btn_voir)

        elif kind == "match_report" and ready:

            btn_voir = QPushButton("VOIR LE RAPPORT"); btn_voir.setObjectName("Primary"); btn_voir.setMinimumHeight(34)

            btn_voir.clicked.connect(lambda: self.show_page(8))

            self.msg_action_bar.addWidget(btn_voir)

        elif kind == "job_offer":

            btn_offres = QPushButton("VOIR LES OFFRES DE CLUB"); btn_offres.setObjectName("Primary"); btn_offres.setMinimumHeight(34)

            btn_offres.clicked.connect(lambda: self.show_page(0))

            self.msg_action_bar.addWidget(btn_offres)

        self.msg_action_bar.addStretch()

        more = QToolButton(); more.setText("PLUS"); more.setPopupMode(QToolButton.InstantPopup)
        more.setMinimumHeight(34); more.setCursor(Qt.PointingHandCursor)
        more.setStyleSheet("QToolButton{background:#152238;color:#cfe0f5;border:1px solid #2c3d57;"
                           "border-radius:8px;padding:6px 12px;font-weight:900;}"
                           "QToolButton:hover{background:#1b2b45;border-color:#3f5f8a;}")
        more_menu = QMenu(more)
        if ready and kind in ("market_offer", "transfer_sale", "transfer_sale_counter",
                              "contract_offer", "free_agent_contract"):
            act_counter = more_menu.addAction("Contre-offre")
            act_counter.triggered.connect(lambda _=False, mid=msg_id: self._resolve_message(mid, "counter"))
        if player_id:
            act_player = more_menu.addAction("Fiche joueur")
            act_player.triggered.connect(lambda _=False, pid=player_id: self.open_club_player_profile(int(pid)))
        if more_menu.actions():
            more_menu.addSeparator()
        act_unread = more_menu.addAction("Marquer non lu")
        act_unread.triggered.connect(lambda _=False, mid=msg_id: self._mark_message_unread(mid))
        act_delete = more_menu.addAction("Supprimer le message")
        act_delete.triggered.connect(lambda _=False, mid=msg_id: self._delete_message(mid))
        more.setMenu(more_menu)
        self.msg_action_bar.addWidget(more)

        # Resynchronise compteurs et pastilles sans relancer la lecture.
        self._mail_refresh_guard = True

        try:

            self._refresh_messages_ui()

        finally:

            self._mail_refresh_guard = False



    def _mark_message_unread(self, msg_id):

        try:

            conn = db()

            conn.execute("UPDATE manager_message SET is_read=0 WHERE id=?", (int(msg_id),))

            conn.commit(); conn.close()

            self._skip_read_once = int(msg_id)

            self._refresh_messages_ui()

            if hasattr(self,"msg_detail_hint"):

                self.msg_detail_hint.setText("Marqué non lu")

        except Exception as exc:

            self.log_error("mark_message_unread", exc)



    def _delete_message(self, msg_id):

        try:

            conn = db()

            row = conn.execute("SELECT status,title FROM manager_message WHERE id=?", (int(msg_id),)).fetchone()

            conn.close()

            if not row:

                return

            if str(row["status"] or "") == "waiting":

                self.show_game_message("Dossier en attente", "Ce dossier attend une réponse : il ne peut pas être supprimé maintenant.", "warning")

                return

            if not self.show_game_message("Supprimer le message", f"« {row['title']} » sera supprimé définitivement.", "warning", confirm=True, confirm_text="SUPPRIMER"):

                return

            conn = db()

            conn.execute("DELETE FROM manager_message WHERE id=?", (int(msg_id),))

            conn.commit(); conn.close()

            self._refresh_messages_ui()

            self.show_game_message("Messagerie", "Message supprimé.", "info")

        except Exception as exc:

            self.log_error("delete_message", exc)



    def _resolve_message(self, msg_id, action):

        """Dispatcher de la messagerie moderne : delegue vers resolve_manager_message avec la selection repositionnee."""

        conn = db()

        msg = conn.execute("SELECT * FROM manager_message WHERE id=?", (msg_id,)).fetchone()

        conn.close()

        if not msg:

            return

        message = dict(msg)

        current = list(getattr(self, "_manager_messages", []))

        replaced = False

        for index, entry in enumerate(current):

            if entry["id"] == msg_id:

                current[index] = message; replaced = True; break

        if not replaced:

            current.insert(0, message)

        self._manager_messages = current

        self.resolve_manager_message(action, msg_id)

        conn = db(); rows = conn.execute("SELECT * FROM manager_message ORDER BY id DESC LIMIT 400").fetchall(); conn.close()

        self._manager_messages = list(rows)

        self.refresh_manager_message_queue(rows)

        self._refresh_messages_ui()



    def open_message_archive(self):

        """HISTORIQUE EN DB (lecture sur demande) : messages resolus archives.

        La fenetre charge 200 lignes d'un coup dans un lecteur transversal —

        elle ne tient qu'a l'ouverture, la partie vivante ne la connait pas."""

        try:

            c=db()

            try:

                rows=c.execute("SELECT kind,title,body,created_date,is_read,archived_date FROM manager_message_archive ORDER BY id DESC LIMIT 200").fetchall()

            finally: c.close()

            dialog=QDialog(self); dialog.setWindowTitle("Historique de la messagerie"); dialog.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dialog.setFixedWidth(640)

            dialog.setAttribute(Qt.WA_StyledBackground,True)

            root=QVBoxLayout(dialog); root.setContentsMargins(18,16,18,16); root.setSpacing(10)

            panel=QFrame(); panel.setObjectName("HeroPanel"); pl=QHBoxLayout(panel); pl.setContentsMargins(16,12,16,12); pl.setSpacing(10)

            mark=QLabel(); mark.setAlignment(Qt.AlignCenter); mark.setFixedSize(42,42); mark.setPixmap(self._make_icon(14,25,"#e9f2ff"))

            mark.setStyleSheet("background:#20273f;border:1px solid #4d6fb0;border-radius:13px;font-size:15pt;")

            pl.addWidget(mark)

            hcol=QVBoxLayout(); hcol.setSpacing(3)

            hcol.addWidget(QLabel(f"HISTORIQUE  •  {len(rows)} MESSAGE(S) ARCHIVE(S)"),0)

            sub=QLabel("Messages resolus depuis plus de 3 semaines, migres vers la base de donnees.")

            sub.setObjectName("Muted"); hcol.addWidget(sub)

            pl.addLayout(hcol,1)

            close=QPushButton("×"); close.setFixedSize(34,32)

            close.setStyleSheet("background:#17243a;color:#aebbd0;border:1px solid #2a3b58;border-radius:11px;font-size:12pt;font-weight:900;")

            close.clicked.connect(dialog.reject); pl.addWidget(close)

            root.addWidget(panel)

            if not rows:

                empty=QLabel("L'historique est vide : les messages archives apparaitront au fil de la saison (au-dela de 3 semaines).")

                empty.setObjectName("Muted"); empty.setWordWrap(True); empty.setAlignment(Qt.AlignCenter)

                root.addWidget(empty,1)

            else:

                view=QListWidget(); view.setSpacing(4)

                view.setStyleSheet("QListWidget{background:#0e1523;border:1px solid #243248;border-radius:12px;}"

                                   "QListWidget::item{background:#131c2e;border:1px solid #202b42;border-radius:10px;margin:2px 4px;padding:9px 10px;color:#dfe6f2;}"

                                   "QListWidget::item:hover{border-color:#3d5170;}")

                ic={"contract_offer":"📄","free_agent_contract":"📄","market_offer":"⇄","transfer_sale":"💶",

                    "transfer_sale_counter":"💶","transfer_arrival":"🛬","match_report":"📊","scout_report":" ",

                    "club_news":"📰","media":"🗞","system":"⚙","training":" "}

                for r in rows:

                    icn=ic.get(str(r["kind"] or ""),"•")

                    date=str(r["archived_date"] or r["created_date"] or "")

                    item=QListWidgetItem(f"{icn}  {r['title']}   ·   {fmt_date_fr(date)}\n{(r['body'] or '')[:150].replace('\n','  ')}")

                    view.addItem(item)

                root.addWidget(view,1)

            okb=QPushButton("FERMER"); okb.setMinimumHeight(40); okb.clicked.connect(dialog.accept); root.addWidget(okb)

            dialog.exec()

        except Exception as exc:

            self.log_error("open_message_archive",exc)



    def _reject_message(self, msg_id):

        conn = db()

        conn.execute("UPDATE manager_message SET status='handled', is_read=1 WHERE id=?", (msg_id,))

        conn.commit(); conn.close()

        self.show_game_message("Message", "Message refusé et archivé.", "info")

        conn = db(); rows = conn.execute("SELECT * FROM manager_message ORDER BY id DESC LIMIT 400").fetchall(); conn.close()

        self.refresh_manager_message_queue(rows)

        self._refresh_messages_ui()



    def _accept_contract_offer(self, msg, data):

        player_id = data.get("player_id")

        conn = db()

        player = conn.execute("SELECT * FROM player WHERE id=?", (player_id,)).fetchone()

        if not player:

            conn.close(); self.show_game_message("Erreur", "Joueur introuvable.", "error"); return

        

        salary = int(data.get("offer_salary", 0))

        years = int(data.get("offer_years", 2))

        club = conn.execute("SELECT * FROM club WHERE id=1").fetchone()

        budget = int(club["budget"] or 0)

        

        # Vérifier le budget sur la durée du contrat

        total_cost = salary * 12 * years

        if budget < total_cost:

            conn.close(); self.show_game_message("Budget insuffisant", f"Le club ne peut pas assumer ce contrat ({total_cost:,} € sur {years} an(s)).", "warning"); return

        

        conn.execute("UPDATE club SET budget=budget-? WHERE id=1", (total_cost,))

        _num=next_shirt_number(conn,1)
        conn.execute("UPDATE player SET club_id=1, is_free_agent=0, transfer_listed=0, shirt_number=?, salary=?, contract_years=?, morale=MIN(100,morale+5) WHERE id=?", (_num, salary, years, player_id))

        record_player_history(conn,player_id,1,"free","Signature libre")

        conn.execute("UPDATE manager_message SET status='handled', is_read=1 WHERE id=?", (msg["id"],))

        add_news(conn, "Recrutement", f"{player['first_name']} {player['last_name']} a signé pour {years} an(s) à {salary:,} €/mois.")

        conn.commit(); conn.close()

        self.show_game_message("Transfert", f"{player['first_name']} {player['last_name']} a signé !", "success")



    def _accept_transfer_offer(self, msg, data):

        player_id = data.get("player_id")

        fee = int(data.get("final_fee", data.get("bid", 0)))

        conn = db()

        player = conn.execute("SELECT * FROM player WHERE id=?", (player_id,)).fetchone()

        if not player:

            conn.close(); self.show_game_message("Erreur", "Joueur introuvable.", "error"); return

        

        club = conn.execute("SELECT * FROM club WHERE id=1").fetchone()

        budget = int(club["budget"] or 0)

        if budget < fee:

            conn.close(); self.show_game_message("Budget insuffisant", f"Le club ne peut pas payer {fee:,} €.", "warning"); return

        

        salary = int(data.get("final_salary", data.get("offer_salary", int(player["salary"] * 1.05))))

        years = int(data.get("offer_years", 3))

        total_cost = fee + salary * 12 * years

        if budget < total_cost:

            conn.close(); self.show_game_message("Budget insuffisant", f"Le club ne peut pas assumer ce transfert ({total_cost:,} € total).", "warning"); return

        

        conn.execute("UPDATE club SET budget=budget-? WHERE id=1", (total_cost,))

        number = next_shirt_number(conn, 1)

        conn.execute("UPDATE player SET club_id=1, is_free_agent=0, transfer_listed=0, shirt_number=?, contract_years=?, salary=?, morale=MIN(100,morale+5) WHERE id=?", (number, years, salary, player_id))

        record_player_history(conn,player_id,1,"transfer","Arrivée via le marché des transferts")

        conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)", (f"Transfert {player['first_name']} {player['last_name']}", -fee, career_timestamp(conn), "Transfert"))

        conn.execute("UPDATE manager_message SET status='handled', is_read=1 WHERE id=?", (msg["id"],))

        add_news(conn, "Mercato", f"Signature de {player['first_name']} {player['last_name']} pour {fee:,} €.")

        conn.commit(); conn.close()

        self.show_game_message("Transfert", f"{player['first_name']} {player['last_name']} a signé !", "success")



    def _counter_transfer_offer(self, msg, data):

        player_id = data.get("player_id")

        conn = db()

        player = conn.execute("SELECT * FROM player WHERE id=?", (player_id,)).fetchone()

        if not player:

            conn.close(); self.show_game_message("Erreur", "Joueur introuvable.", "error"); return

        

        # Ouvrir le dialog de contre-offre sur le mercato

        conn.close()

        self.show_page(7)  # Mercato

        self.show_game_message("Transfert", "Ouvrez le mercato pour faire une contre-offre sur ce joueur.", "info")



    def _accept_sale_offer(self, msg, data):

        """Accepte l'offre d'un club acheteur : le joueur rejoint son nouveau club, la trésorerie est créditée."""

        player_id = data.get("player_id")

        fee = round_money(int(data.get("final_fee", data.get("counter_fee", data.get("bid", data.get("fee", 0))))))

        conn = db()

        player = conn.execute("SELECT * FROM player WHERE id=? AND club_id=1", (player_id,)).fetchone()

        buyer_id = int(data.get("buyer_id", 0))

        buyer = conn.execute("SELECT name FROM club WHERE id=? AND id<>1", (buyer_id,)).fetchone()

        if not player or not buyer:

            conn.close(); self.show_game_message("Offre expirée", "Le joueur ou le club acheteur n'est plus disponible.", "warning"); return

        available=conn.execute("SELECT COUNT(*) FROM player WHERE club_id=1 AND COALESCE(is_free_agent,0)=0 AND injury_matches<=0 AND injury_days<=0 AND suspension_matches<=0").fetchone()[0]

        if int(player["injury_matches"])<=0 and available<=5:

            conn.close(); self.show_game_message("Effectif trop réduit","Accepter cette vente laisserait moins de cinq joueurs valides. Recrute d'abord un remplaçant.","warning"); return

        number=next_shirt_number(conn,buyer_id)

        conn.execute("UPDATE player SET club_id=?, transfer_listed=0, shirt_number=? WHERE id=?", (buyer_id, number, player_id))

        record_player_history(conn,player_id,buyer_id,"transfer",f"Départ vers {buyer['name']}")

        if fee>0:

            conn.execute("UPDATE club SET budget=budget+? WHERE id=1", (fee,))

            conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)", (f"Vente {player['first_name']} {player['last_name']}", fee, career_timestamp(conn), "Transfert"))

        conn.execute("UPDATE manager_message SET status='handled', is_read=1 WHERE id=?", (msg["id"],))

        add_news(conn, "Départ mercato", f"{player['first_name']} {player['last_name']} rejoint {buyer['name']} pour {fee:,} €.".replace(","," "))

        conn.commit(); conn.close()

        for zone in getattr(self,"pitch_zones",{}).values():

            if zone.player_id==player_id: zone.reset_zone()

        self.persist_tactics_settings()

        self.refresh_all()

        self.show_game_message("Transfert", f"{player['first_name']} {player['last_name']} a été vendu pour {fee:,} €.".replace(","," "), "success")



