    def market_safe_mode(self):

        """Désactive les interactions sensibles si l'environnement GUI est instable."""

        try:

            self.market_table.blockSignals(True)

            self.market_table.itemSelectionChanged.disconnect(self.update_market_compare)

        except Exception:

            pass

        self.market_table.blockSignals(False)

        self.market_offer_info.setText("Mode sécurisé activé: comparatif auto désactivé. Utilisez le bouton Offre après sélection.")



    def _finances(self):

        w,l = self.page_shell("Finances", "TRÉSORERIE  •  INVESTISSEMENTS ET SANTÉ DU CLUB", icon="💶")

        tabs=QTabWidget(); tabs.setDocumentMode(True); tabs.setObjectName("CenterTabs"); self.finance_tabs=tabs
