        tabs.addTab(self._finances_overview(),"VUE D'ENSEMBLE")

        tabs.addTab(self._finances_exploitation(),"EXPLOITATION")

        tabs.addTab(self._finances_loan(),"PRÊT BANCAIRE")

        tabs.addTab(self._finances_sponsor(),"SPONSORS")

        l.addWidget(tabs,1)

        self.loan_amount_spin.valueChanged.connect(self.update_loan_offer)

        self.loan_term_combo.currentIndexChanged.connect(self.update_loan_offer)

        self.loan_take_btn.clicked.connect(self.subscribe_loan)

        self.loan_repay_btn.clicked.connect(self.repay_loan_early)

        return w



