    def _finances_exploitation(self):
        page=QWidget(); outer=QVBoxLayout(page); outer.setContentsMargins(0,0,0,0)
        scroll=QScrollArea(); scroll.setWidgetResizable(True); scroll.setFrameShape(QFrame.NoFrame)
        scroll.setStyleSheet("QScrollArea{background:transparent;border:0;} QScrollArea>QWidget>QWidget{background:transparent;}")
        content=QWidget(); l=QVBoxLayout(content); l.setContentsMargins(4,6,4,6); l.setSpacing(7)
        scroll.setWidget(content); outer.addWidget(scroll)

        # ---------------- HERO COMPACT ----------------
        hero=MatchdayHero(); self.fin_matchday_hero=hero; hero.setFixedHeight(100)
        hv=QVBoxLayout(hero); hv.setContentsMargins(16,8,16,8); hv.setSpacing(4)
        top=QHBoxLayout(); top.setSpacing(12)
        left=QVBoxLayout(); left.setSpacing(0)
        cap=QLabel("SOIRÉE DE MATCH"); cap.setStyleSheet("font-size:6.4pt;font-weight:900;color:#f0d9a8;letter-spacing:1.7px;")
        self.fin_hero_arena=QLabel("ARENA"); self.fin_hero_arena.setStyleSheet("font-size:14pt;font-weight:1000;color:#f7fbff;letter-spacing:.4px;")
        self.fin_hero_match=QLabel("Prochaine réception à définir"); self.fin_hero_match.setStyleSheet("font-size:7.2pt;color:#c6d6e7;")
        left.addWidget(cap); left.addWidget(self.fin_hero_arena); left.addWidget(self.fin_hero_match)
        top.addLayout(left,1)
        right=QVBoxLayout(); right.setSpacing(0)
        cap2=QLabel("RECETTE / MATCH"); cap2.setAlignment(Qt.AlignRight)
        cap2.setStyleSheet("font-size:6.4pt;font-weight:900;color:#f0d9a8;letter-spacing:1.4px;")
        self.fin_hero_total=QLabel("—"); self.fin_hero_total.setAlignment(Qt.AlignRight)
        self.fin_hero_total.setStyleSheet("font-size:19pt;font-weight:1000;color:#e6d0a6;")
        self.fin_hero_season=QLabel("—"); self.fin_hero_season.setAlignment(Qt.AlignRight)
        self.fin_hero_season.setStyleSheet("font-size:6.8pt;color:#c6d6e7;")
        right.addWidget(cap2); right.addWidget(self.fin_hero_total); right.addWidget(self.fin_hero_season)
        top.addLayout(right); hv.addLayout(top)
        fill_row=QHBoxLayout(); fill_row.setSpacing(7)
        fill_cap=QLabel("AFFLUENCE"); fill_cap.setStyleSheet("font-size:6.1pt;font-weight:900;color:#e8d4a6;letter-spacing:.9px;")
        self.fin_hero_fill=QProgressBar(); self.fin_hero_fill.setRange(0,100); self.fin_hero_fill.setTextVisible(False)
        self.fin_hero_fill.setFixedHeight(7)
        self.fin_hero_fill.setStyleSheet("QProgressBar{background:rgba(6,12,20,180);border:1px solid #4b5f74;border-radius:4px;}"
                                         "QProgressBar::chunk{background:qlineargradient(x1:0,y1:0,x2:1,y2:0,stop:0 #5f7f9a,stop:1 #9fb6cc);border-radius:3px;}")
        self.fin_hero_fill_label=QLabel("—"); self.fin_hero_fill_label.setStyleSheet("font-size:6.6pt;font-weight:800;color:#e4eef8;")
        fill_row.addWidget(fill_cap); fill_row.addWidget(self.fin_hero_fill,1); fill_row.addWidget(self.fin_hero_fill_label)
        hv.addLayout(fill_row)
        l.addWidget(hero)

        # ---------------- KPI ----------------
        def kpi(caption,key,tone,icon_kind):
            tile=QFrame(); tile.setObjectName("ExploitKPI")
            tile.setStyleSheet("QFrame#ExploitKPI{background:#0f1a28;border:1px solid #26374d;border-radius:9px;}")
            h=QHBoxLayout(tile); h.setContentsMargins(8,4,8,4); h.setSpacing(7)
            badge=QLabel(); badge.setFixedSize(24,24); badge.setAlignment(Qt.AlignCenter)
            badge.setPixmap(self._make_icon(icon_kind,14,tone)); badge.setStyleSheet(f"background:{tone}18;border:1px solid {tone}55;border-radius:7px;")
            h.addWidget(badge)
            v=QVBoxLayout(); v.setSpacing(0)
            cap=QLabel(caption); cap.setStyleSheet("font-size:6.2pt;font-weight:900;color:#91a5bb;letter-spacing:.7px;")
            val=QLabel("—")
            val_color=tone if key=="fin_exploit_total" else "#e8f0f8"
            val.setStyleSheet(f"font-size:9.5pt;font-weight:1000;color:{val_color};")
            v.addWidget(cap); v.addWidget(val); h.addLayout(v,1)
            setattr(self,key,val); return tile
        kr=QHBoxLayout(); kr.setSpacing(7)
        kr.addWidget(kpi("BILLETTERIE","fin_exploit_ticket","#a8bccf",3),1)
        kr.addWidget(kpi("BAR","fin_exploit_bar","#a8bccf",46),1)
        kr.addWidget(kpi("BOUTIQUE","fin_exploit_shop","#a8bccf",48),1)
        kr.addWidget(kpi("RESTAURATION","fin_exploit_restaurant","#a8bccf",50),1)
        kr.addWidget(kpi("TOTAL / MATCH","fin_exploit_total","#d8bc8a",9),1)
        l.addLayout(kr)

        def panel():
            f=QFrame(); f.setObjectName("ExploitPanel")
            f.setStyleSheet("QFrame#ExploitPanel{background:qlineargradient(x1:0,y1:0,x2:1,y2:1,stop:0 #101b2a,stop:1 #0c1622);"
                            "border:1px solid #26374d;border-radius:11px;}")
            return f
        def panel_header(layout,kind,title,accent="#9fb0c8"):
            head=QHBoxLayout(); head.setSpacing(6)
            badge=QLabel(); badge.setFixedSize(24,24); badge.setAlignment(Qt.AlignCenter)
            badge.setPixmap(self._make_icon(kind,15,accent))
            badge.setStyleSheet(f"background:{accent}18;border:1px solid {accent}55;border-radius:7px;")
            lab=QLabel(title); lab.setStyleSheet("font-size:7.8pt;font-weight:900;color:#c7d6e6;letter-spacing:.9px;")
            head.addWidget(badge); head.addWidget(lab); head.addStretch()
