    def refresh_finance_exploitation(self,club=None):
        if not hasattr(self,"fin_ticket_spin"): return
        conn=db()
        try:
            club=club or conn.execute("SELECT * FROM club WHERE id=1").fetchone()
            facility=conn.execute("SELECT * FROM facility WHERE id=1").fetchone()
            cfg=exploitation_config(conn)
            try:
                today=self._career_day()
                fixture=conn.execute("""SELECT f.fixture_date,ac.name away_name
                                         FROM fixture f JOIN club ac ON ac.id=f.away_club_id
                                         WHERE f.home_club_id=1 AND f.played=0 AND f.fixture_date>=?
                                         ORDER BY f.fixture_date LIMIT 1""",(today,)).fetchone()
            except Exception:
                fixture=None
        finally:
            conn.close()
        if facility is None or club is None: return
        pairs=((self.fin_ticket_spin,int(facility["ticket_price"] or 12)),
               (self.fin_bar_drink_spin,cfg["bar_drink"]),(self.fin_bar_food_spin,cfg["bar_food"]),
               (self.fin_shop_jersey_spin,cfg["shop_jersey"]),(self.fin_shop_scarf_spin,cfg["shop_scarf"]),
               (self.fin_shop_cap_spin,cfg["shop_cap"]))
        for spin,value in pairs:
            spin.blockSignals(True); spin.setValue(int(value)); spin.blockSignals(False)
        if hasattr(self,"fin_matchday_hero"):
            self.fin_matchday_hero.set_colors(club["color1"] if "color1" in club.keys() else "#c47220",
                                              club["color2"] if "color2" in club.keys() else "#14171f")
        if hasattr(self,"fin_hero_arena"):
            arena=club["arena_name"] if "arena_name" in club.keys() and club["arena_name"] else "Arena"
            self.fin_hero_arena.setText(f"{arena}  •  LIGUE {int(club['division'] or 1)}")
        if hasattr(self,"fin_hero_match"):
            if fixture:
                self.fin_hero_match.setText(f"Prochaine réception : vs {fixture['away_name']} • {fmt_date_fr(str(fixture['fixture_date']))}")
            else:
                self.fin_hero_match.setText("Aucune réception programmée pour l'instant")
        if hasattr(self,"fin_shop_jersey_icon"):
            try:
                self.fin_shop_jersey_icon.setPixmap(kit_pixmap(
                    club["color1"] if "color1" in club.keys() else "#c47220",
                    club["color2"] if "color2" in club.keys() else "#14171f",
                    kit_pattern_for(1,"",getattr(self,"club_kit_pattern",None)),28))
            except Exception:
                pass
        has_bar=bool(int(facility["has_bar"] or 0)); has_shop=bool(int(facility["has_shop"] or 0))
        self.fin_bar_body.setVisible(has_bar); self.fin_bar_locked.setVisible(not has_bar)
        self.fin_bar_build_btn.setVisible(not has_bar); self.fin_bar_apply_btn.setEnabled(has_bar)
        self.fin_shop_body.setVisible(has_shop); self.fin_shop_locked.setVisible(not has_shop)
        self.fin_shop_build_btn.setVisible(not has_shop); self.fin_shop_apply_btn.setEnabled(has_shop)
        self.update_finance_exploitation_preview()

    def update_finance_exploitation_preview(self,*_):
        if not hasattr(self,"fin_ticket_spin"): return
        conn=db()
        try:
            club=conn.execute("SELECT * FROM club WHERE id=1").fetchone()
            facility=conn.execute("SELECT * FROM facility WHERE id=1").fetchone()
        finally:
            conn.close()
        if club is None or facility is None: return
        cfg={"bar_drink":self.fin_bar_drink_spin.value(),"bar_food":self.fin_bar_food_spin.value(),
             "shop_jersey":self.fin_shop_jersey_spin.value(),"shop_scarf":self.fin_shop_scarf_spin.value(),
             "shop_cap":self.fin_shop_cap_spin.value()}
        price=int(self.fin_ticket_spin.value())
        try:
            attendance,capacity,_=self.projected_attendance(club,facility,price)
        except Exception:
            attendance,capacity=0,0
        parts=self.facility_matchday_revenue(club,facility,attendance,price,cfg=cfg)
        bar_units=exploitation_bar_units(attendance,cfg); shop_units=exploitation_shop_units(attendance,cfg)
        money=lambda value: f"{int(value):,} €".replace(","," ")
        self.fin_exploit_ticket.setText(money(parts['tickets']))
        self.fin_exploit_bar.setText(money(parts['bar']) if parts["bar"] else "—")
        self.fin_exploit_shop.setText(money(parts['shop']) if parts["shop"] else "—")
        if hasattr(self,"fin_exploit_restaurant"):
            self.fin_exploit_restaurant.setText(money(parts.get('restaurant',0)) if parts.get("restaurant") else "—")
        self.fin_exploit_total.setText(money(parts['total']))
        fill=int(attendance*100/max(1,capacity))
        self.fin_ticket_forecast.setText(f"{attendance:,} spectateurs prévus / {capacity:,} places ({fill} %) • {price} € / place".replace(","," "))
        for prefix,data in (("bar",bar_units),("shop",shop_units)):
            if prefix=="bar":
                self.fin_bar_drink_units.setText(f"{data['drink_units']} u."); self.fin_bar_drink_rev.setText(money(data['drink_revenue']))
                self.fin_bar_food_units.setText(f"{data['food_units']} u."); self.fin_bar_food_rev.setText(money(data['food_revenue']))
                self.fin_bar_preview.setText(f"Bar : {money(parts['bar'])} / match")
            else:
                self.fin_shop_jersey_units.setText(f"{data['jersey_units']} u."); self.fin_shop_jersey_rev.setText(money(data['jersey_revenue']))
                self.fin_shop_scarf_units.setText(f"{data['scarf_units']} u."); self.fin_shop_scarf_rev.setText(money(data['scarf_revenue']))
                self.fin_shop_cap_units.setText(f"{data['cap_units']} u."); self.fin_shop_cap_rev.setText(money(data['cap_revenue']))
                self.fin_shop_preview.setText(f"Boutique : {money(parts['shop'])} / match")
        rest_level=int(facility["restaurant_level"] or 0) if "restaurant_level" in facility.keys() else 0
        if hasattr(self,"fin_restaurant_line"):
            self.fin_restaurant_line.setText(
                f"Restaurant niv. {rest_level}/3 • {money(parts.get('restaurant',0))} / match" if rest_level
                else "Restaurant : non construit (recette supplémentaire par spectateur).")
        # Totaux du bandeau
        fill=int(attendance*100/max(1,capacity))
        if hasattr(self,"fin_hero_total"):
            self.fin_hero_total.setText(money(parts['total']))
        if hasattr(self,"fin_hero_season"):
            self.fin_hero_season.setText(f"Projection 19 matchs : {money(int(parts['total'])*19)}")
        if hasattr(self,"fin_hero_fill"):
            self.fin_hero_fill.setValue(max(0,min(100,fill)))
            self.fin_hero_fill_label.setText(f"{attendance:,} / {capacity:,} places • {fill} %".replace(","," "))
        if hasattr(self,"fin_ticket_curve"):
            try:
                points=[(p,self.projected_attendance(club,facility,p)[0]) for p in range(5,41)]
                self.fin_ticket_curve.set_data(points,capacity,price)
            except Exception:
                pass
        # Autres recettes
        others_parts={"vip":parts.get("vip",0),"fanzone":parts.get("fanzone",0),"parking":parts.get("parking",0),
                      "broadcast":parts.get("broadcast",0),"restaurant":parts.get("restaurant",0)}
        active={"vip":bool(int(facility["has_vip"] or 0)),
                "fanzone":bool(int(facility["has_fan_zone"] or 0)) if "has_fan_zone" in facility.keys() else False,
                "parking":int(facility["parking_level"] or 1)>=2 if "parking_level" in facility.keys() else False,
                "broadcast":int(facility["lighting_level"] or 1)>=2 if "lighting_level" in facility.keys() else False,
                "restaurant":rest_level>0}
        labels={"vip":"Loges ouvertes","fanzone":"Animations les jours de match","parking":"Stationnement actif",
                "broadcast":"Diffusion nocturne","restaurant":f"Restaurant niv. {rest_level}/3"}
        for key,value in others_parts.items():
            if key in getattr(self,"fin_other_values",{}):
                self.fin_other_values[key].setText(money(value) if active.get(key) and value else "—")
                self.fin_other_status[key].setText(labels.get(key,"—") if active.get(key) else "À construire")
        other_total=int(sum(others_parts.values()))
        total=max(1,int(parts['total']))
        season_total=int(parts['total'])*19
        if hasattr(self,"fin_season_total"):
            self.fin_season_total.setText(money(season_total))
            self.fin_season_hint.setText(f"19 matchs à domicile • {money(parts['total'])} par match")
        shares={"tickets":int(parts['tickets'])/total,
                "bar":int(parts['bar']+parts.get('restaurant',0))/total,
                "shop":int(parts['shop'])/total,
                "others":other_total/total}
        share_amounts={"tickets":int(parts['tickets']),"bar":int(parts['bar']+parts.get('restaurant',0)),
                       "shop":int(parts['shop']),"others":other_total}
        for key,frac in shares.items():
            if key in getattr(self,"fin_share_bars",{}):
                self.fin_share_bars[key].set_frac(frac)
                self.fin_share_values[key].setText(f"{money(share_amounts[key])} • {int(round(frac*100))} %")
        # Conseil du soir
        reputation=int(club["reputation"] or 20)
        marketing=int(facility["marketing_level"] or 1) if "marketing_level" in facility.keys() else 1
        recommended=max(5,min(35,10+reputation//16+marketing//2))
        self.fin_recommended_price=recommended
        if hasattr(self,"fin_advice_price"):
            self.fin_advice_price.setText(f"Prix conseillé : {recommended} € / place")
            self.fin_advice_fill.setValue(max(0,min(100,fill)))
            self.fin_advice_fill_label.setText(f"Remplissage estimé : {fill} %")
        self.fin_exploit_summary.setText(
            f"Billetterie {money(parts['tickets'])}  •  bar {money(parts['bar'])}  •  boutique {money(parts['shop'])}  •  autres {money(other_total)}  =  {money(parts['total'])} / match")
        self.fin_exploit_season.setText(f"Projection sur 19 matchs à domicile : {money(season_total)}")

    def _use_recommended_ticket_price(self):
        price=int(getattr(self,"fin_recommended_price",12))
        if hasattr(self,"fin_ticket_spin"):
            self.fin_ticket_spin.setValue(max(5,min(40,price)))

    def save_finance_ticket_price(self):
        try:
            conn=db(); conn.execute("UPDATE facility SET ticket_price=? WHERE id=1",(int(self.fin_ticket_spin.value()),))
            conn.commit()
            club=conn.execute("SELECT * FROM club WHERE id=1").fetchone()
            conn.close()
        except Exception as exc:
            self.log_error("save_ticket_price",exc); return
        # Rafraîchissement CIBLÉ : le tarif ne doit pas déclencher un refresh
        # global (la confiance des supporters bougeait et l'affluence estimée
        # changeait sous les yeux après chaque application).
        try:
            self.refresh_finance_exploitation(club)
            self.refresh_finance_visuals([],club)
        except Exception:
            self.refresh_all()
        self.show_game_message("Billetterie",f"Tarif fixé à {self.fin_ticket_spin.value()} € par place.","success")

    def save_finance_items(self,kind):
        keys={"bar":(("bar_drink",self.fin_bar_drink_spin),("bar_food",self.fin_bar_food_spin)),
              "shop":(("shop_jersey",self.fin_shop_jersey_spin),("shop_scarf",self.fin_shop_scarf_spin),
                      ("shop_cap",self.fin_shop_cap_spin))}.get(kind,())
        try:
            conn=db()
            for key,spin in keys:
                conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES(?,?)",("exploit_"+key,str(int(spin.value()))))
            conn.commit()
            club=conn.execute("SELECT * FROM club WHERE id=1").fetchone()
            conn.close()
        except Exception as exc:
            self.log_error("save_finance_items",exc); return
        try:
            self.refresh_finance_exploitation(club)
            self.refresh_finance_visuals([],club)
        except Exception:
            self.refresh_all()
        self.show_game_message("Exploitation","Prix enregistrés : les recettes du prochain match utilisent ces tarifs.","success")

