    def sponsor_logo_pixmap(self,name,accent=None,size=52):
        """Logo vectoriel fictif et déterministe pour un sponsor."""
        name=str(name or "Sponsor")
        palette=["#d8bc8a","#9fb6cc","#a8c4b0","#c9a9a0","#b8a6c9","#8fb3c9"]
        if not accent:
            accent=palette[sum(ord(c) for c in name)%len(palette)]
        seed=sum((i+1)*ord(c) for i,c in enumerate(name))
        pix=QPixmap(size,size); pix.fill(Qt.transparent)
        p=QPainter(pix)
        try:
            p.setRenderHint(QPainter.Antialiasing)
            rect=QRectF(0.8,0.8,size-1.6,size-1.6)
            bg=QLinearGradient(rect.topLeft(),rect.bottomRight())
            bg.setColorAt(0,QColor("#1a2638")); bg.setColorAt(1,QColor("#0b1420"))
            p.setPen(QPen(QColor(accent),max(1.0,size*.045))); p.setBrush(bg)
            p.drawRoundedRect(rect,size*.22,size*.22)
            cx=size*.5; cy=size*.37; r=size*.21
            p.setPen(QPen(QColor(accent),max(1.3,size*.05),Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            p.setBrush(Qt.NoBrush)
            kind=seed%5
            if kind==0:
                p.drawPolyline(QPolygonF([QPointF(cx-r,cy+r*.45),QPointF(cx,cy-r*.55),QPointF(cx+r,cy+r*.45)]))
                p.drawPolyline(QPolygonF([QPointF(cx-r*.55,cy+r*.05),QPointF(cx,cy+r*.72),QPointF(cx+r*.55,cy+r*.05)]))
            elif kind==1:
                p.drawEllipse(QPointF(cx,cy),r*.82,r*.82)
                p.drawLine(QPointF(cx-r*1.05,cy+r*.95),QPointF(cx+r*1.05,cy+r*.95))
            elif kind==2:
                p.drawPolygon(QPolygonF([QPointF(cx,cy-r),QPointF(cx+r*.78,cy),QPointF(cx,cy+r),QPointF(cx-r*.78,cy)]))
                p.setBrush(QColor(accent)); p.drawEllipse(QPointF(cx,cy),max(1.5,size*.045),max(1.5,size*.045))
            elif kind==3:
                ang=[-90,-18,54,126,198]
                pts=[QPointF(cx+r*__import__("math").cos(__import__("math").radians(a)),
                             cy+r*__import__("math").sin(__import__("math").radians(a))) for a in ang]
                p.drawPolygon(QPolygonF(pts))
            else:
                p.drawArc(QRectF(cx-r,cy-r*.55,r*2,r*1.1),200*16,140*16)
                p.drawArc(QRectF(cx-r,cy-r*.05,r*2,r*1.1),20*16,140*16)
            words=[w for w in name.replace("-"," ").split() if w]
            initials=(words[0][:1]+words[1][:1]).upper() if len(words)>=2 else name.replace(" ","")[:2].upper()
            f=QFont("Segoe UI",8,QFont.Black); f.setPixelSize(max(8,int(size*.19))); p.setFont(f)
            p.setPen(QColor("#eef4fb")); p.drawText(QRectF(0,size*.62,size,size*.21),Qt.AlignCenter,initials)
            p.setPen(QPen(QColor(accent),max(1.0,size*.03)))
            p.drawLine(QPointF(size*.32,size*.60),QPointF(size*.68,size*.60))
        finally:
            p.end()
        return pix

