    def _staff_refresh_impl(self):
        """Met à jour noms, niveaux, effets réels (actuel → suivant), salaires,
        synthèse et bannière de formation."""
        conn=db()
        try:
            current=self._current_date(conn)
            self.process_staff_training(conn,current)
            conn.commit()
            scout_level_meta=conn.execute("SELECT value FROM meta WHERE key='scout_level'").fetchone()
            scout_level=int(scout_level_meta["value"] or 0) if scout_level_meta else 0
            physio_row=conn.execute("SELECT value FROM meta WHERE key='physio_hired'").fetchone()
            prep_row=conn.execute("SELECT value FROM meta WHERE key='preparateur_physique_hired'").fetchone()
            statuses={"scout_staff_hired":scout_level>0,
                      "physio_hired":bool(physio_row and physio_row["value"]=="1"),
                      "preparateur_physique_hired":bool(prep_row and prep_row["value"]=="1")}
            for key in ("comptable_hired","directeur_sportif_hired","adjoint_hired","marketing_hired","architecte_hired"):
                statuses[key]=self.staff_meta_active(key)
            levels={k:self.staff_level(conn,k) for k,v in statuses.items() if v}
            hired=[k for k in statuses if statuses[k]]
            from wage_budget import staff_bill as _staff_bill, status as _wage_status
            payroll=_staff_bill(self,conn)
            _ws=_wage_status(self,conn)
            avg=(sum(levels.values())/len(levels)) if levels else 0.0
            if hasattr(self,"staff_subtitle"):
                self.staff_subtitle.setText(f"{len(hired)}/{len(self.staff_cards)} postes pourvus  •  niveau moyen {avg:.1f}/5")
            if hasattr(self,"staff_hero_payroll"):
                self.staff_hero_payroll.setText(f"{payroll:,} € / mois".replace(","," "))
            if hasattr(self,"staff_hero_grade"):
                _gross=sum(self.staff_effective_salary(conn,k) for k in hired)
                _saving=max(0,_gross-payroll)
                self.staff_hero_grade.setText(f"{len(hired)}/{len(self.staff_cards)} POSTES  ·  NIVEAU MOYEN {avg:.1f}"
                                              + (f"  ·  REMISE COMPTABLE −{_saving:,} €".replace(","," ") if _saving else ""))
            if getattr(self,'staff_summary',None) is not None and self.staff_summary.isVisible():
                self._staff_summary_chips(levels)

            krow=conn.execute("SELECT value FROM meta WHERE key='staff_training_key'").fetchone()
            drow=conn.execute("SELECT value FROM meta WHERE key='staff_training_due'").fetchone()
            training_active=bool(krow and krow["value"] and drow and drow["value"] and str(drow["value"])>=str(current))
            training_key=krow["value"] if training_active else None
            training_due=drow["value"] if training_active else None

            for meta_key,info in self.staff_cards.items():
                hired_now=statuses.get(meta_key,False)
                level=self.staff_level(conn,meta_key) if hired_now else 0
                if hired_now:
                    person=self._staff_person_name(conn,meta_key)
                    nat=self._staff_person_nat(conn,meta_key)
                    info["person"].setText(f"{person}  •  {nat}  •  {self._staff_rank(level)}")
                    info["train"].setVisible(True)
                else:
                    info["person"].setText("Aucun titulaire")
                    info["train"].setVisible(False)
                info["btn"].setText("LICENCIER" if hired_now else "EMBAUCHER")
                info["btn"].setObjectName("TileButton")
                info["btn"].setStyleSheet("")
                info["card"].setStyleSheet("QFrame#StaffCard{background:#111a2b;border:1px solid #2b3953;"
                                           "border-left:2px solid #4b6484;border-radius:9px;}")
                if hired_now:
                    eff_salary=self.staff_effective_salary(conn,meta_key,level=level)
                    info["status"].setText("EN POSTE")
                    info["pips"].setText(self._staff_pips_text(level))
                    now_txt,next_txt=self._staff_effect_texts(meta_key,level,conn)
                    info["eff_now"].setText(now_txt)
                    if level<5:
                        info["eff_next"].setText(f"→ niv. {level+1} : {next_txt}")
                        info["eff_next"].setVisible(True)
                    else:
                        info["eff_next"].setText("")
                        info["eff_next"].setVisible(False)
                    info["eff_now"].setToolTip(f"Actuel : {now_txt}" + (f"\nSuivant : {next_txt}" if level<5 else "\nNiveau maximal"))
                    if level>=5:
                        info["cost_lbl"].setText(f"{eff_salary:,} €/mois  •  niveau max".replace(","," "))
                    elif meta_key=="scout_staff_hired":
                        info["cost_lbl"].setText(f"{eff_salary:,} €/mois  •  mise à niveau {self.SCOUT_LEVEL_COSTS[level]:,} € (immédiate)".replace(","," "))
                    else:
                        fcost=self._staff_formation_cost(meta_key,level)
                        fdays=self._staff_formation_days(meta_key,level)
                        info["cost_lbl"].setText(f"{eff_salary:,} €/mois  •  formation {fcost:,} € / {fdays} j".replace(","," "))
                else:
                    info["status"].setText("VACANT")
                    info["pips"].setText(self._staff_pips_text(0))
                    now_txt,_next=self._staff_effect_texts(meta_key,1,conn)
                    info["eff_now"].setText(now_txt)
                    info["eff_next"].setText("")
                    info["eff_next"].setVisible(False)
                    info["eff_now"].setToolTip("Effet dès l'embauche : "+now_txt)
                    info["cost_lbl"].setText(f"Embauche {info['cost']:,} €  •  {self.STAFF_BASE_SALARY.get(meta_key,2000):,} €/mois".replace(","," "))
                info["status"].setStyleSheet(f"color:{'#8fc4a8' if hired_now else '#8fa4bf'};font-size:6.5pt;font-weight:900;")
                if meta_key=="scout_staff_hired":
                    # Le recruteur s'améliore au tarif officiel du scouting (pas de formation à 3 200 €).
                    info["train"].setEnabled(bool(hired_now) and level<5)
                elif training_active or not hired_now:
                    info["train"].setEnabled(False)
                else:
                    info["train"].setEnabled(level<5)
                if meta_key=="scout_staff_hired":
                    info["train"].setText("AMÉLIORER" if (hired_now and level<5) else "NIV. MAX" if hired_now else "AMÉLIORER")
                elif training_active and info.get("meta_key")==training_key:
                    info["train"].setText("EN COURS")
                elif hired_now and level<5:
                    info["train"].setText("FORMER")
                else:
                    info["train"].setText("NIV. MAX" if hired_now else "FORMER")

            self._refresh_staff_delegations(conn)

            if hasattr(self,"staff_training_frame"):
                if training_active:
                    other=self.STAFF_TITLES.get(training_key,training_key)
                    try: days_left=max(0,(parse_iso(str(training_due))-parse_iso(str(current))).days)
                    except Exception: days_left=0
                    self.staff_training_label.setText(f"FORMATION EN COURS  •  {other}  •  fin le "
                                                      f"{fmt_date_fr(str(training_due))} ({days_left} j)  —  un seul staff formé à la fois")
                    self.staff_training_frame.setVisible(True)
                else:
                    self.staff_training_frame.setVisible(False)
        finally:
            conn.close()

    STAFF_BASE_SALARY={"scout_staff_hired":1800,"physio_hired":2600,"preparateur_physique_hired":2800,"comptable_hired":2200,"directeur_sportif_hired":3500,"adjoint_hired":2500,"marketing_hired":2400,"architecte_hired":3200}

    # Tarif officiel d'une mise à niveau du service de scouting (niveau → niveau+1).
    SCOUT_LEVEL_COSTS=(18000,30000,45000,65000,90000)

    # COMPTABLE : place la trésorerie positive (0,15 %/niveau et par mois, plafonné).
    # Sans ce levier, sa remise sur la paie du staff ne couvrait jamais son salaire.
    COMPTABLE_PLACEMENT_RATE=0.0015
    COMPTABLE_PLACEMENT_CAP=12000

    STAFF_FORMATION_COST={"scout_staff_hired":3200,"physio_hired":3400,"preparateur_physique_hired":3600,"comptable_hired":2600,"directeur_sportif_hired":4200,"adjoint_hired":3000,"marketing_hired":3800,"architecte_hired":5800}

    STAFF_FORMATION_DAYS=14

    STAFF_TITLES={"scout_staff_hired":"Recruteur","physio_hired":"Kiné","preparateur_physique_hired":"Préparateur physique","comptable_hired":"Comptable","directeur_sportif_hired":"Directeur sportif","adjoint_hired":"Adjoint","marketing_hired":"Responsable marketing","architecte_hired":"Architecte"}



    def _staff_level_meta_key(self,key):

        """Meta stockant le niveau : scout_level pour le recruteur, architecte_level pour l'architecte, sinon <key>_level."""

        if key=="scout_staff_hired": return "scout_level"

        if key=="architecte_hired": return "architecte_level"

        return key+"_level"



    def staff_level(self,conn,key):

        """Niveau d'un membre du staff (1..5)."""

        row=conn.execute("SELECT value FROM meta WHERE key=?",(self._staff_level_meta_key(key),)).fetchone()

        if not row: return 1

        try: value=int(row["value"] or 0)

        except (TypeError,ValueError): return 1

        return 1 if value<1 else min(5,value)



    def staff_effective_salary(self,conn,key,level=None):

        """Salaire mensuel effectif : base + 15 % par niveau au-dela du premier."""

        base=self.STAFF_BASE_SALARY.get(key,2000)

        level=self.staff_level(conn,key) if level is None else level

        return int(round(base*(1+0.15*(level-1))/50))*50



    def comptable_placement_monthly(self,conn,level=None):

        """Revenu mensuel des placements du comptable (trésorerie positive).

        Rend le poste réellement rentable : 0,15 % du solde par niveau, plafonné."""

        try:

            if level is None:

                row=conn.execute("SELECT value FROM meta WHERE key='comptable_hired'").fetchone()

                if not (row and row["value"]=="1"): return 0

                level=self.staff_level(conn,"comptable_hired")

            budget=max(0,int(conn.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"] or 0))

            level=max(1,min(5,int(level or 1)))

            amount=budget*self.COMPTABLE_PLACEMENT_RATE*level

            return min(self.COMPTABLE_PLACEMENT_CAP,int(amount/50.0+0.5)*50)

        except Exception:

            return 0

    def _staff_wage_ok(self,conn,key,name,level=1,hire=False):

        """Verifie que l'embauche/formation tient dans le plafond joueurs+staff."""

        try:

            from wage_budget import can_set_staff_level

            ok,st,proj=can_set_staff_level(self,conn,key,level,hire=hire)

            if not ok:

                self.show_game_message("Plafond salarial",

                    f"Cette évolution ({name}) porterait la masse salariale à {proj:,} € pour un plafond de {st['cap']:,} €/mois. "
                    f"Vends un joueur ou libère un salaire.".replace(","," "),"warning")

            return ok

        except Exception:

            return True



    def _staff_pips_text(self,level):

        """Pastilles de niveau (5 ronds) en HTML pour la page Staff."""

        on="#8fb0cf"; off="#2e3d57"

        spans="".join(f"<span style='color:{on if i<level else off};'>&#9679;</span>&nbsp;&nbsp;" for i in range(5))

        return f"<span style='font-size:8.5pt;font-weight:900;'>{spans}</span>"



    STAFF_LEVEL_NAMES={1:"DÉBUTANT",2:"CONFIRMÉ",3:"EXPERT",4:"ÉLITE",5:"LÉGENDE"}

    def _staff_rank(self,level):
        lv=max(1,min(5,int(level or 1)))
        return f"{self.STAFF_LEVEL_NAMES.get(lv,'DÉBUTANT')} · {lv}/5"

    def _staff_level_color(self,level):
        return {1:"#4a5c7a",2:"#3f7f63",3:"#3b6ea8",4:"#7a5bb5",5:"#b8912f"}.get(max(1,min(5,int(level or 1))),"#3a4a66")

    def _staff_effect_texts(self,key,level,conn=None):
        """(effet AU niveau, effet AU niveau suivant) — l'effet démarre petit
        et grandit à chaque formation."""
        lv=max(1,min(5,int(level or 1))); nx=min(5,lv+1)
        def placement(l):
            c=conn
            owned=c is None
            if owned: c=db()
            try: return self.comptable_placement_monthly(c,l)
            finally:
                if owned: c.close()
        def fmt(l):
            if key=="scout_staff_hired": txt=f"{'1 mission' if l==1 else f'{l} missions'} en parallèle • +{2*l} connaissance"
            elif key=="physio_hired": txt=(f"Soin : −{1+(l-1)//2} j de blessure" + (f" • +{3*(l-1)} pts de réussite" if l>1 else ""))
            elif key=="preparateur_physique_hired": txt=f"Progression à l'entraînement : +{10*l} %"
            elif key=="comptable_hired": txt=f"Paie staff −{4+2*(l-1)} % • placements +{placement(l):,} €/mois"
            elif key=="directeur_sportif_hired": txt=f"Shortlist : +{2*l}/lundi sur {2*l} cibles"
            elif key=="adjoint_hired": txt=f"Forme : +{l}/jour (en plus des +3 quotidiens)"
            elif key=="marketing_hired": txt=f"Réputation : +{1+(l-1)//2} / lundi"
            elif key=="architecte_hired": txt=f"Devis −{int(1.5*l)} % • délais −{int(3*l)} % • {1+l} chantiers"
            else: txt="—"
            return txt.replace(","," ")
        def short(l):
            if key=="scout_staff_hired": txt=f"{'1 mission' if l==1 else f'{l} missions'} • +{2*l} conn."
            elif key=="physio_hired": txt=(f"−{1+(l-1)//2} j" + (f" • +{3*(l-1)} pts" if l>1 else ""))
            elif key=="preparateur_physique_hired": txt=f"+{10*l} %"
            elif key=="comptable_hired": txt=f"−{4+2*(l-1)} % • +{placement(l):,} €/mois"
            elif key=="directeur_sportif_hired": txt=f"+{2*l}/lundi sur {2*l} cibles"
            elif key=="adjoint_hired": txt=f"+{l}/jour"
            elif key=="marketing_hired": txt=f"+{1+(l-1)//2}/lundi"
            elif key=="architecte_hired": txt=f"−{int(1.5*l)} % • −{int(3*l)} % • {1+l} chantiers"
            else: txt="—"
            return txt.replace(","," ")
        return fmt(lv),short(nx)

    def _staff_formation_cost(self,key,level):
        base=int(self.STAFF_FORMATION_COST.get(key,3000))
        return int(round(base*(1+0.4*(max(1,int(level or 1))-1))/100))*100

    def _staff_formation_days(self,key,level):
        return int(self.STAFF_FORMATION_DAYS+3*(max(1,int(level or 1))-1))

    def _staff_person_name(self,conn,key):
        meta=f"staff_name_{key}"
        try:
            row=conn.execute("SELECT value FROM meta WHERE key=?",(meta,)).fetchone()
            if row and row["value"]: return row["value"]
            first,last,nat=random_player_name()
            name=f"{first} {last}"
            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES(?,?)",(meta,name))
            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES(?,?)",(f"staff_nat_{key}",nat))
            return name
        except Exception:
            return "—"

    def _staff_person_nat(self,conn,key):
        try:
            row=conn.execute("SELECT value FROM meta WHERE key=?",(f"staff_nat_{key}",)).fetchone()
            return row["value"] if row and row["value"] else "—"
        except Exception:
            return "—"

    def _staff_summary_chips(self,levels):
        row=getattr(self,"staff_summary_row",None)
        if row is None: return
        while row.count():
            it=row.takeAt(0); wdg=it.widget()
            if wdg is not None: wdg.deleteLater()
        chips=[]
        if "scout_staff_hired" in levels: chips.append((f"SCOUTING ×{levels['scout_staff_hired']}","#8fd8ff"))
        if "physio_hired" in levels: chips.append((f"SOIN −{1+(levels['physio_hired']-1)//2} j","#7de0aa"))
        if "preparateur_physique_hired" in levels: chips.append((f"ENTRAÎNEMENT +{10*levels['preparateur_physique_hired']} %","#ffd98a"))
        if "comptable_hired" in levels: chips.append((f"PAIE −{4+2*(levels['comptable_hired']-1)} %","#8fd8ff"))
        if "directeur_sportif_hired" in levels: chips.append((f"SHORTLIST +{2*levels['directeur_sportif_hired']}/sem","#c9b6ff"))
        if "adjoint_hired" in levels: chips.append((f"FORME +{levels['adjoint_hired']}/j","#7de0aa"))
        if "marketing_hired" in levels: chips.append((f"RÉPUTATION +{1+(levels['marketing_hired']-1)//2}/sem","#ffb37a"))
        if "architecte_hired" in levels: chips.append((f"CHANTIERS ×{levels['architecte_hired']}","#ffd98a"))
        if not chips:
            lab=QLabel("AUCUN EMPLOYÉ  •  LE CLUB TOURNE AVEC UN ENCADREMENT MINIMAL")
            lab.setStyleSheet("color:#8ea3bd;font-size:7.5pt;font-weight:900;letter-spacing:.5px;")
            row.addWidget(lab)
        else:
            head=QLabel("EFFETS ACTIFS"); head.setStyleSheet("color:#7f93ad;font-size:6.5pt;font-weight:900;letter-spacing:1px;")
            row.addWidget(head)
            for text,fg in chips:
                lab=QLabel(text)
                lab.setStyleSheet(f"background:#0f1a2a;border:1px solid {fg};border-radius:8px;padding:2px 9px;"
                                  f"color:{fg};font-size:7pt;font-weight:900;")
                row.addWidget(lab)
        row.addStretch()

    def process_staff_training(self,conn,current_iso_date):

        """Termine une formation de staff arrivee a echeance : niveau +1 (max 5) et salaire revalorise."""

        try:

            krow=conn.execute("SELECT value FROM meta WHERE key='staff_training_key'").fetchone()

            drow=conn.execute("SELECT value FROM meta WHERE key='staff_training_due'").fetchone()

            if not krow or not krow["value"] or not drow or not drow["value"]: return

            due=str(drow["value"])

            if due>str(current_iso_date): return

            key=krow["value"]

            level=self.staff_level(conn,key)

            target=min(5,level+1)

            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES(?,?)",(self._staff_level_meta_key(key),str(target)))

            conn.execute("DELETE FROM meta WHERE key IN ('staff_training_key','staff_training_due')")

            salary=self.staff_effective_salary(conn,key)

            name=self.STAFF_TITLES.get(key,key.replace("_hired","").replace("_"," "))

            add_news(conn,"Formation terminée",f"{name} termine sa formation (niveau {target}/5). Salaire mensuel : {salary:,} €.".replace(","," "))

        except Exception as exc:

            self.log_error("process_staff_training",exc)



    def staff_meta_active(self,key):

        conn=db(); row=conn.execute("SELECT value FROM meta WHERE key=?",(key,)).fetchone(); conn.close()

        return bool(row and row["value"]=="1")



    def hire_architect(self):

        cost=32000

        conn=db()

        current=conn.execute("SELECT value FROM meta WHERE key='architecte_hired'").fetchone()

        if current and current["value"]=="1":

            conn.close(); self.show_game_message("Staff déjà engagé","L'architecte est déjà en poste.","info"); return False

        budget=int(conn.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"])

        if budget<cost:

            conn.close(); self.show_game_message("Budget insuffisant","L'embauche de l'architecte coûte 32 000 €.","warning"); return False

        if not self._staff_wage_ok(conn,"architecte_hired","architecte",1,hire=True):

            conn.close(); return False

        conn.execute("UPDATE club SET budget=budget-? WHERE id=1",(cost,))

        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('architecte_hired','1')")

        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('architecte_level','1')")

        conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",("Embauche architecte",-cost,career_timestamp(conn),"Staff"))

        add_news(conn,"Nouveau staff","L'architecte rejoint le club : les chantiers coûteront moins cher et livreront plus vite.")

        conn.commit(); conn.close()

        self.refresh_all(); return True



    def dismiss_architect(self):

        conn=db()

        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('architecte_hired','0')")

        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('architecte_level','0')")

        add_news(conn,"Staff","L'architecte du club a été licencié.")

        conn.commit(); conn.close()

        self.show_game_message("Staff","L'architecte a été licencié. Les chantiers reviennent aux conditions standards.","info")



    def _staff_train_action(self,key,name):

        """Le recruteur s'améliore via le tarif officiel du scouting, les autres suivent une formation."""

        if key=="scout_staff_hired": return self.hire_scout_staff()

        return self.train_staff(key,name)



    def _staff_toggle(self,meta_key,hire_fn,dismiss_fn):

        hired=(int(self.scout_level)>0) if meta_key=="scout_staff_hired" else self.staff_meta_active(meta_key)

        if hired:

            title=self.STAFF_TITLES.get(meta_key,"membre du staff")

            if not self.show_game_message("Licencier ?",

                f"{title} quitte le club : son niveau, sa formation et son effet sont perdus. Aucune indemnité n'est versée.",

                kind="warning",confirm=True,confirm_text="LICENCIER"):

                return

            dismiss_fn()

        else:

            hire_fn()

        self._staff_refresh()

        self.refresh_all()



    def dismiss_scout_staff(self):

        conn=db()

        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('scout_staff_hired','0')")

        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('scout_level','0')")

        add_news(conn,"Staff","Le recruteur du club a été licencié.")

        conn.commit(); conn.close(); self.show_game_message("Staff","Le recruteur a été licencié. Les rapports de scouting en cours sont conservés.","info")



    def dismiss_physiotherapist(self):

        conn=db(); conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('physio_hired','0')"); conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('physio_hired_level','0')")

        add_news(conn,"Staff","Le kiné du club a été licencié.")

        conn.commit(); conn.close(); self.show_game_message("Staff","Le kiné a été licencié. Les protocoles médicaux individuels ne sont plus disponibles.","info")



    def dismiss_physical_trainer(self):

        conn=db(); conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('preparateur_physique_hired','0')"); conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('preparateur_physique_hired_level','0')")

        add_news(conn,"Staff","Le préparateur physique du club a été licencié.")

        conn.commit(); conn.close(); self.show_game_message("Staff","Le préparateur physique a été licencié. Plus d'entraînement automatique le lundi.","info")



    def _refresh_quick_icons(self):

        if not hasattr(self,"quick_shortcuts"): return

        idx = self.stack.currentIndex() if hasattr(self,"stack") else -1

        for shortcut in self.quick_shortcuts:

            page_index = shortcut.accessibleName()

            try: page_index = int(page_index)

            except Exception: continue

            shortcut.setIcon(self._make_icon(page_index, size=28, color=self._icon_color(page_index)))



    def _match_is_live(self):

        """True tant qu'un match est lance (direct, pause, mi-temps) : la

        session de match est verrouillee jusqu'a la finalisation du rapport."""

        s = getattr(self, "match_state", None)

        return bool(s and not s.get("finished", True))



    def _set_career_nav_locked(self, locked):

        """Pendant le direct : pages de la sidebar, CONTINUER et JOUER LE MATCH

        desactives (etat du moteur protege : aucune avance de calendrier ni de

        reponse de message qui pourrait corrompre le match en cours)."""

        try:

            for b in self.nav_buttons:

                b.setEnabled(not locked)

        except Exception:

            pass

        try:

            self.advance_button.setEnabled(not locked)

        except Exception:

            pass

        try:

            self.play_matchday_btn.setEnabled(not locked)

        except Exception:

            pass



    def _restore_match_phase_text(self):

        s = getattr(self, "match_state", None)

        if not s or s.get("finished", True):

            return

        if s.get("half_time_break"):

            self.match_phase.setText("MI-TEMPS  •  CHRONO BLOQUÉ")

        elif int(s.get("elapsed_seconds", 0)) < 1200:

            self.match_phase.setText("1RE MI-TEMPS  •  EN DIRECT")

        else:

            self.match_phase.setText("2E MI-TEMPS  •  EN DIRECT")



    def _reset_matchday_view(self):

        """FENETRE MATCH DAY CLEAN (retour « l'ancien match encore affiche ») :

        sans match en direct, l'ecran se presente AVANT-MATCH — score 0-0,

        chrono 00:00, banniere cachee/purgee, terrain 2D reinitialise, journal

        vide. Le rapport du dernier match reste consultable via son bouton."""

        self.match_state = None

        try: self.timer.stop()

        except Exception: pass

        banner = getattr(self, "match_banner", None)

        if banner is not None:

            try: banner.stop_animation()

            except Exception: pass

            try: banner.clear()

            except Exception: pass

            try: banner.setVisible(False)

            except Exception: pass

            try: banner._engine_user_side = "h"   # defaut : a domicile la coincidence moteur/coach

            except Exception: pass

        pitch = getattr(self, "match_pitch", None)

        if pitch is not None:

            try: pitch.reset_all()

            except Exception: pass

        try: self.event_log.clear()

        except Exception: pass

        try:

            self.score_label.setText("0  -  0"); self.clock_label.setText("00:00")

            self.match_progress.setValue(0); self.match_phase.setText("AVANT-MATCH")

            self.match_clock_context.setText("Coup d'envoi en attente — calendrier de carrière")

        except Exception: pass



    def show_page(self, index):

        if index != 3 and self._match_is_live():

            # Direct en cours : retour force au centre de match, menus verrouilles.

            for page_index, button in self.page_nav_buttons.items():

                button.setChecked(page_index == 3)

            try:

                self.match_phase.setText("DIRECT EN COURS  •  MENUS VERROUILLÉS")

                QTimer.singleShot(1500, self._restore_match_phase_text)

            except Exception:

                pass

            return

        if index == 3 and not (self.match_state and not self.match_state.get("finished", True)):

            # FENETRE CLEAN : ouvrir le centre de match SANS match en direct

            # repart d'un ecran vierge (purge l'affichage de l'ancien match).

            try: self._reset_matchday_view()

            except Exception: pass

            conn = db()

            fixture = self._today_fixture_for_user(conn)

            conn.close()

            if not fixture:

                # Pas de match aujourd'hui : le clic ne doit pas rester silencieux.
                try:

                    _nc = db(); _next = self._next_fixture_for_user(_nc); _nc.close()

                except Exception:

                    _next = None

                if _next:

                    _date = fmt_date_fr(str(_next["fixture_date"] or ""))

                    _msg = (f"Aucun match aujourd'hui. Prochain match le {_date} : "
                            f"{_next['home_name']} — {_next['away_name']}.")

                else:

                    _msg = "Aucun match programmé pour le moment. Consulte le calendrier."

                self.show_game_message("Centre de match", _msg, "info")

                return

        self.log_trace(f"show_page start idx={index}")

        self.stack.setCurrentIndex(index)

        self._animate_page_reveal(index)

        if index==4:

            QTimer.singleShot(0,self.fit_training_layout)

            if getattr(self,"_training_dirty",True): QTimer.singleShot(0,self._refresh_training_page)

        elif index==2: QTimer.singleShot(0,self.fit_tactics_layout)

        elif index==6:
            QTimer.singleShot(0,self._fit_mail_layout)
            if getattr(self,"_messages_dirty",True): QTimer.singleShot(0,self._refresh_messages_ui)

        elif index==5:

            QTimer.singleShot(0,self._fit_facility_layout)

            if getattr(self,"_facility_dirty",True): QTimer.singleShot(0,self._refresh_facility_page)

        elif index==8:

            if getattr(self,"_calendar_dirty",True): QTimer.singleShot(0,self._refresh_calendar_page)

        elif index==11:

            QTimer.singleShot(0,self._refresh_competitions_page)

        elif index==12 and getattr(self,"_ui_ready",False): QTimer.singleShot(0,self._refresh_search_page)

        elif index==13:
            self._facility_page_dirty=True
            QTimer.singleShot(0,self._fit_academy_layout)
            QTimer.singleShot(0,self._refresh_academy_page)
        elif index==7 and getattr(self,"_ui_ready",False):
            # Ouvrir TRANSFERTS doit toujours être rapide et lisible : ne pas
            # rouvrir l'historique lourd laissé par la dernière visite.
            try:
                if hasattr(self,"mercato_tabs"):
                    self.mercato_tabs.setCurrentIndex(1)  # MARCHÉ
            except Exception:
                pass
            QTimer.singleShot(0,self._fit_offers_layout)

            if getattr(self,"_market_dirty",True): QTimer.singleShot(0,self._refresh_market_page)

        for page_index,button in self.page_nav_buttons.items(): button.setChecked(page_index==index)

        self._refresh_nav_chips()

        self._refresh_quick_icons()

        # Navigation fluide : les données sont déjà rafraîchies après chaque
        # journée/action. On ne relance plus tout le jeu à chaque clic de menu.
        if index==9 and getattr(self,"_finance_dirty",True):
            QTimer.singleShot(0, self._refresh_finance_page)
        elif index==10 and getattr(self,"_staff_dirty",True):
            QTimer.singleShot(0, self._staff_refresh)
        if str((getattr(self,"game_options",{}) or {}).get("theme",""))=="Clair":
            QTimer.singleShot(120, lambda: apply_theme_to_tree(self, True))

        QTimer.singleShot(0,self.fit_career_scroll_area)

        self.log_trace(f"show_page end idx={index}")



    def _refresh_classement_tab(self,*_):

        """Onglet actif du Classement : rafraichit uniquement la vue visible.

        Statistiques (tab 1) et Historique (tab 2) vivent desormais dans la page

        Classement — plus de pages dediees dans la barre laterale."""

        try:

            tabs=getattr(self,"classement_tabs",None)

            if tabs is None: return

            idx=tabs.currentIndex()

            if idx==1 and getattr(self,"_ui_ready",False): self.refresh_cup_page()
            elif idx==2 and getattr(self,"_ui_ready",False): self._fill_stats_page()
            elif idx==3 and getattr(self,"_ui_ready",False): self._refresh_history_page()
            elif idx==4 and getattr(self,"_ui_ready",False): self._refresh_palmares_page()

        except Exception as exc:

            self.log_error("classement_tabs",exc)



