    def open_contract_offers_tab(self,player_id=None):
        """Ouvre la page Transferts sur OFFRES, contrats internes visibles."""
        try:
            self.show_page(7)
            if hasattr(self,"mercato_tabs"):
                self.mercato_tabs.setCurrentIndex(0)
            self._refresh_offers_tab()
            table=getattr(self,"offers_contract_table",None)
            if table is None or not table.rowCount(): return
            pids=list(getattr(self,"_contract_player_ids",[]))
            target=0
            if player_id is not None and int(player_id) in pids:
                target=pids.index(int(player_id))
            table.selectRow(min(target,table.rowCount()-1))
            self._offer_selection_changed(table)
            item=table.item(min(target,table.rowCount()-1),0)
            if item is not None: table.scrollToItem(item)
            table.setFocus()
        except Exception as exc:
            self.log_error("open_contract_offers_tab",exc)

    def negotiate_player_contract(self,player_id):

        conn=db(); player=conn.execute("SELECT * FROM player WHERE id=? AND club_id=1",(player_id,)).fetchone(); current_date=self._current_date(conn)

        active=conn.execute("SELECT action_data FROM manager_message WHERE kind='contract_offer' AND status IN ('waiting','ready')").fetchall()

        already_open=any(json.loads(row["action_data"] or "{}").get("player_id")==player_id for row in active)

        conn.close()

        if already_open:

            self.show_game_message("Négociation en cours","Une proposition pour ce joueur est déjà en attente : retrouve-la dans les contrats internes de la page Transferts.","info")
            self.open_contract_offers_tab(player_id); return False

        if not player: return False

        if int(player["loan_from_club"] or 0) if "loan_from_club" in player.keys() else 0:
            self.show_game_message("Joueur en prêt","Ce joueur appartient à un autre club : sa prolongation n'est pas possible. Il repartira en fin de saison.","info"); return False

        level=player_level_from_row(player)

        current_salary=int(player["salary"])

        current_years=int(player["contract_years"])

        dlg=QDialog(self); dlg.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dlg.setWindowTitle(f"Négociation de contrat — {player['first_name']} {player['last_name']}"); dlg.resize(520,360)

        lay=QVBoxLayout(dlg); lay.setContentsMargins(18,18,18,18); lay.setSpacing(12)

        header=QFrame(); header.setObjectName("HeroPanel"); hl=QHBoxLayout(header); hl.setContentsMargins(12,10,12,10)

        avatar=QLabel(); avatar.setFixedSize(58,58); avatar.setPixmap(self.draw_player_avatar(player,58)); hl.addWidget(avatar)

        info=QVBoxLayout(); info.addWidget(QLabel(f"{player['first_name']} {player['last_name']}")); meta=QLabel(f"{player['position']} • niveau {level}/20 {stars5(level)} • contrat actuel {current_years} an(s)"); meta.setObjectName("Muted"); info.addWidget(meta); hl.addLayout(info,1); lay.addWidget(header)

        demand=QLabel("Ta proposition sera transmise à l'agent. Sa réponse arrivera sous deux jours dans la page Transferts (contrats internes)."); demand.setWordWrap(True); demand.setObjectName("Muted"); lay.addWidget(demand)

        # Attente de l'agent : même barème que la résolution et les pré-contrats
        # (salaire juste selon niveau, âge, potentiel et division).
        _ask_salary=max(250,int(current_salary*1.02))
        try:
            _ac=db(); _arow=_ac.execute("SELECT division,reputation,season FROM club WHERE id=1").fetchone(); _ac.close()
            _ask_salary=max(_ask_salary,int(player_salary_demand(player,_arow)[0]))
        except Exception:
            pass
        expectation=QLabel(f"Attente de l'agent : environ {format_euros(_ask_salary,' € / mois')} "
                           f"(actuel : {format_euros(current_salary,' € / mois')}).")
        expectation.setWordWrap(True); expectation.setStyleSheet("color:#e8c98f;font-size:8pt;font-weight:800;")
        lay.addWidget(expectation)

        try:
            from wage_budget import status as _wstatus
            _wc=db(); _ws=_wstatus(self,_wc); _wc.close()
            _hint=QLabel(f"Masse salariale : {_ws['total']:,} / plafond {_ws['cap']:,} €/mois. "
                         f"Le nouveau salaire REMPLACE l'actuel ({current_salary:,} €) : seule la différence compte.".replace(","," "))
            _hint.setWordWrap(True); _hint.setStyleSheet("color:#9ce6bf;font-size:8pt;font-weight:800;")
            lay.addWidget(_hint)
        except Exception:
            pass

        form=QGridLayout(); form.addWidget(QLabel("Ta proposition mensuelle"),0,0)

        salary=QSpinBox(); salary.setObjectName("contractOfferSalary"); salary.setRange(250,9999999); salary.setSingleStep(250); salary.setValue(max(250,int(_ask_salary))); salary.setSuffix(" € / mois"); form.addWidget(salary,0,1)

        form.addWidget(QLabel("Durée"),1,0); years=QSpinBox(); years.setObjectName("contractOfferYears"); years.setRange(1,5); years.setValue(max(1,current_years)); years.setSuffix(" an(s)"); form.addWidget(years,1,1); lay.addLayout(form)

        replace_hint=QLabel(""); replace_hint.setObjectName("Muted"); replace_hint.setWordWrap(True)
        def _update_replace_hint(*_):
            offered=max(1,int(years.value()))
            if current_years>0:
                replace_hint.setText(f"Nouveau contrat : {offered} an(s). Il REMPLACE le contrat actuel ({current_years} an(s) restant(s)) : la durée ne s'y ajoute pas.")
            else:
                replace_hint.setText(f"Nouveau contrat : {offered} an(s) à compter de la signature.")
        years.valueChanged.connect(_update_replace_hint); _update_replace_hint()
        lay.addWidget(replace_hint)

        result=QHBoxLayout(); result.addStretch(); cancel=QPushButton("ANNULER"); cancel.clicked.connect(dlg.reject); accept=QPushButton("SOUMETTRE L'OFFRE"); accept.setObjectName("Primary"); accept.clicked.connect(dlg.accept); result.addWidget(cancel); result.addWidget(accept); lay.addLayout(result)

        if dlg.exec()!=QDialog.Accepted: return False

        offer_salary=salary.value(); offer_years=years.value(); due=(parse_iso(current_date)+timedelta(days=2)).isoformat()

        conn=db()

        try:
            from wage_budget import can_add_player
            _ok,_st,_proj=can_add_player(self,conn,offer_salary,current_salary)
            if not _ok:
                conn.close()
                self.show_game_message("Plafond salarial",
                    f"Cette prolongation porterait la masse salariale à {_proj:,} € pour un plafond de {_st['cap']:,} €/mois. "
                    f"Vends un joueur ou réduis la proposition.".replace(","," "), "warning")
                return False
        except Exception:
            pass

        queue_manager_message(conn,"contract_offer","Proposition de contrat envoyée",f"Ta proposition pour {player['first_name']} {player['last_name']} est partie à l'agent. Réponse attendue le {fmt_date_fr(due)}.",current_date,due,{"player_id":player_id,"player_name":f"{player['first_name']} {player['last_name']}","offer_salary":offer_salary,"offer_years":offer_years},is_read=True)

        add_news(conn,"Négociation de contrat",f"Une proposition a été envoyée à l'agent de {player['first_name']} {player['last_name']}.")

        conn.commit(); conn.close(); self.refresh_all()

        self.open_contract_offers_tab(player_id)

        return True



    def _terminate_loan_from_profile(self,player_id,profile_dialog):

        if self.terminate_loan(player_id): profile_dialog.accept()

    def terminate_loan(self,player_id):
        """Met fin au prêt : retour IMMÉDIAT au club propriétaire (jamais libre/fantôme)."""
        if self.match_state and not self.match_state.get("finished",True):
            self.show_game_message("Match en cours","Impossible de mettre fin à un prêt pendant un match.","warning"); return False
        conn=db()
        player=conn.execute("SELECT * FROM player WHERE id=? AND club_id=1",(player_id,)).fetchone()
        if not player:
            conn.close(); return False
        parent=int(player["loan_from_club"] or 0) if "loan_from_club" in player.keys() else 0
        if not parent:
            conn.close(); self.show_game_message("Fin de prêt","Ce joueur n'est pas prêté : utilise le licenciement classique.","info"); return False
        parent_club=conn.execute("SELECT id,name FROM club WHERE id=?",(parent,)).fetchone()
        where=f"à {parent_club['name']}" if parent_club else "dans son club d'origine"
        answer=self.show_game_message("Mettre fin au prêt",
            f"Mettre fin au prêt de {player['first_name']} {player['last_name']} ?\nIl retournera immédiatement {where} et ne sera pas libre.",
            "warning",confirm=True,confirm_text="METTRE FIN AU PRÊT")
        if not answer:
            conn.close(); return False
        if parent_club:
            conn.execute("UPDATE player SET club_id=?,is_free_agent=0,loan_from_club=0,loan_until_season=0,loan_promise='',transfer_listed=0,shirt_number=0 WHERE id=?",(parent,int(player_id)))
            record_player_history(conn,int(player_id),parent,"transfer","Fin de prêt — retour au club")
            add_news(conn,"Mercato",f"{player['first_name']} {player['last_name']} retourne à {parent_club['name']} : le prêt est terminé.")
        else:
            conn.execute("UPDATE player SET club_id=0,is_free_agent=1,loan_from_club=0,loan_until_season=0,loan_promise='',transfer_listed=0,shirt_number=0 WHERE id=?",(int(player_id),))
            record_player_history(conn,int(player_id),0,"free_agent","Fin de prêt — club d'origine introuvable")
            add_news(conn,"Mercato",f"Le prêt de {player['first_name']} {player['last_name']} se termine : son club d'origine n'existe plus, il est libre.")
        try: self.close_player_dossiers(conn,int(player_id),reason="Prêt terminé")
        except Exception: pass
        try: repair_shirt_numbers(conn)
        except Exception: pass
        conn.commit(); conn.close()
        for zone in getattr(self,"pitch_zones",{}).values():
            if zone.player_id==player_id: zone.reset_zone()
        self.refresh_all(); self.persist_tactics_settings(); self.show_page(1)
        self.show_game_message("Prêt terminé",f"{player['first_name']} {player['last_name']} a quitté l'effectif {where}.","success")
        return True

    def _dismiss_from_profile(self,player_id,profile_dialog):

        if self.dismiss_player(player_id): profile_dialog.accept()



    def dismiss_player(self,player_id):

        _lc=db(); _lrow=_lc.execute("SELECT loan_from_club FROM player WHERE id=?",(player_id,)).fetchone(); _lc.close()

        if _lrow and int(_lrow["loan_from_club"] or 0):
            self.show_game_message("Joueur en prêt","Impossible de licencier un joueur prêté : il appartient à un autre club et repartira en fin de saison.","info"); return False

        if self.match_state and not self.match_state.get("finished",True):

            self.show_game_message("Match en cours","Impossible de licencier un joueur pendant un match.","warning"); return False

        conn=db(); player=conn.execute("SELECT * FROM player WHERE id=? AND club_id=1",(player_id,)).fetchone()

        if not player:

            conn.close(); return False

        count=conn.execute("SELECT COUNT(*) FROM player WHERE club_id=1 AND COALESCE(is_free_agent,0)=0").fetchone()[0]

        available=conn.execute("SELECT COUNT(*) FROM player WHERE club_id=1 AND COALESCE(is_free_agent,0)=0 AND injury_matches<=0 AND injury_days<=0 AND suspension_matches<=0").fetchone()[0]

        available_after=available-(1 if player["injury_matches"]<=0 and player["suspension_matches"]<=0 else 0)

        if count<=5 or available_after<5:

            conn.close(); self.show_game_message("Effectif trop réduit","Ce départ laisserait moins de cinq joueurs valides. Recrute ou attends le retour des blessés avant de licencier.","warning"); return False

        indemnity=int(player["salary"]*max(1,int(player["contract_years"]))*2)

        answer=self.show_game_message("Confirmer le licenciement",f"Licencier {player['first_name']} {player['last_name']} ?\nIndemnité estimée : {indemnity:,} €.".replace(","," "),"warning",confirm=True,confirm_text="CONFIRMER LE DÉPART")

        if not answer:

            conn.close(); return False

        conn.execute("DELETE FROM player WHERE id=?",(player_id,)); conn.execute("UPDATE club SET budget=budget-? WHERE id=1",(indemnity,))

        conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",(f"Indemnité de départ {player['first_name']} {player['last_name']}",-indemnity,career_timestamp(conn),"Contrat"))

        add_news(conn,"Départ joueur",f"{player['first_name']} {player['last_name']} quitte le club après rupture de contrat.")

        conn.commit(); conn.close()

        for zone in getattr(self,"pitch_zones",{}).values():

            if zone.player_id==player_id: zone.reset_zone()

        self.refresh_all(); self.persist_tactics_settings(); self.show_page(1)

        return True



    def market_compare_html(self, target, own):

        scouting=bool(getattr(self,"scout_staff_hired",False))

