    def _reflow_offers_columns(self,cols=None):
        grid=getattr(self,"offers_columns",None)
        if not isinstance(grid,QGridLayout): return
        left=getattr(self,"offers_left_panel",None); right=getattr(self,"offers_right_panel",None)
        if left is None or right is None: return
        if cols is None:
            width=int(self.width()) if hasattr(self,"width") else 1300
            cols=2 if width>=1180 else 1
        while grid.count():
            grid.takeAt(0)
        if cols>=2:
            grid.addWidget(left,0,0); grid.addWidget(right,0,1)
            grid.setColumnStretch(0,1); grid.setColumnStretch(1,1)
            grid.setRowStretch(0,1); grid.setRowStretch(1,0)
            left.setMinimumHeight(0); right.setMinimumHeight(0)
        else:
            grid.addWidget(left,0,0); grid.addWidget(right,1,0)
            grid.setColumnStretch(0,1); grid.setColumnStretch(1,0)
            grid.setRowStretch(0,1); grid.setRowStretch(1,1)
            left.setMinimumHeight(320); right.setMinimumHeight(280)

    def _fit_offers_layout(self):
        if not hasattr(self,"offers_columns"): return
        width=int(self.width()) if hasattr(self,"width") else 1300
        cols=2 if width>=1180 else 1
        if getattr(self,"_offers_cols",None)!=cols:
            self._offers_cols=cols
            self._reflow_offers_columns(cols)

    def _offer_card_action(self,mid,action):
        self._offer_selected_id=int(mid)
        self._offer_selected_meta={}
        self._offer_action(action)

    def _make_offer_card(self,mid,title,subtitle,statut,state,metrics,icon,section):
        colors={"wait":"#e6c07a","counter":"#c9b6ff","decision":"#7de0aa","closed":"#8ea3bd","sold":"#7de0aa","rival":"#ff9daa","arrival":"#8fa9c4"}
        tone=colors.get(state,"#8ea3bd")
        card=QFrame(); card.setObjectName("OfferCard")
        card.setSizePolicy(QSizePolicy.Ignored,QSizePolicy.Preferred)
        card.setStyleSheet("QFrame#OfferCard{background:#101b2a;border:1px solid #24344a;border-left:3px solid %s;border-radius:11px;}" % tone)
        root=QVBoxLayout(card); root.setContentsMargins(11,8,11,8); root.setSpacing(6)
        top=QHBoxLayout(); top.setSpacing(8)
        avatar=QLabel(); avatar.setFixedSize(32,32); avatar.setAlignment(Qt.AlignCenter)
        if icon is not None:
            avatar.setPixmap(icon)
        else:
            avatar.setPixmap(self._mail_avatar(self._mail_initials(title),32,"#5f7d9e"))
        top.addWidget(avatar)
        head=QVBoxLayout(); head.setSpacing(0)
        nm=QLabel(title); nm.setMinimumWidth(0); nm.setSizePolicy(QSizePolicy.Ignored,QSizePolicy.Preferred)
        nm.setStyleSheet("font-size:9pt;font-weight:1000;color:#f3f8fd;")
        sub=QLabel(subtitle); sub.setMinimumWidth(0); sub.setSizePolicy(QSizePolicy.Ignored,QSizePolicy.Preferred)
        sub.setStyleSheet("font-size:7pt;color:#8296ad;")
        head.addWidget(nm); head.addWidget(sub); top.addLayout(head,1)
        pill=QLabel(statut.split(" • ")[0]); pill.setAlignment(Qt.AlignCenter); pill.setWordWrap(False)
        pill.setMinimumWidth(0); pill.setSizePolicy(QSizePolicy.Preferred,QSizePolicy.Fixed)
        pill.setToolTip(statut)
        pill.setStyleSheet("font-size:7pt;font-weight:900;color:%s;background:rgba(0,0,0,0);border:1px solid %s;border-radius:7px;padding:2px 6px;" % (tone,tone))
        top.addWidget(pill,0); root.addLayout(top)
        metrics_row=QHBoxLayout(); metrics_row.setSpacing(7)
        for label,value in metrics:
            box=QVBoxLayout(); box.setSpacing(0)
            cap=QLabel(label); cap.setStyleSheet("font-size:6.5pt;font-weight:900;color:#8b9cb5;letter-spacing:.7px;")
            val=QLabel(str(value)); val.setMinimumWidth(0); val.setSizePolicy(QSizePolicy.Ignored,QSizePolicy.Preferred)
            val.setStyleSheet("font-size:8pt;font-weight:900;color:#dce7f4;")
            box.addWidget(cap); box.addWidget(val); metrics_row.addLayout(box,1)
        root.addLayout(metrics_row)
        actions=QHBoxLayout(); actions.setSpacing(5)
        def _act(text,cb,primary=False):
            btn=QPushButton(text)
            if primary: btn.setObjectName("Primary")
            btn.setMinimumHeight(26); btn.setMinimumWidth(0)
            btn.setSizePolicy(QSizePolicy.Ignored,QSizePolicy.Fixed)
            if not primary:
                btn.setStyleSheet("font-size:7pt;font-weight:800;padding:2px 5px;")
            btn.setCursor(Qt.PointingHandCursor)
            btn.clicked.connect(cb); actions.addWidget(btn,1); return btn
        _act("OUVRIR",lambda _=False,mid=mid: self._offer_card_action(mid,"open"))
        if state in ("counter","decision"):
            _act("CONTRE",lambda _=False,mid=mid: self._offer_card_action(mid,"counter"))
            _act("REFUSER",lambda _=False,mid=mid: self._offer_card_action(mid,"reject"))
            _act("ACCEPTER",lambda _=False,mid=mid: self._offer_card_action(mid,"accept"),True)
        elif state=="wait":
            _act("REFUSER",lambda _=False,mid=mid: self._offer_card_action(mid,"reject"))
        root.addLayout(actions)
        return card

    @staticmethod
    def _clear_offer_cards(layout):
        """Retire les cartes, séparateurs et ressorts, conserve les labels d'état vide."""
        if layout is None: return
        keep=[]
        while layout.count():
            item=layout.takeAt(0)
            widget=item.widget()
            if widget is None: continue
            if widget.objectName() in ("OfferCard","OfferDivider"):
                widget.hide(); widget.setParent(None); widget.deleteLater()
            else:
                keep.append(widget)
        for widget in keep:
            layout.addWidget(widget)

    def _refresh_offer_cards(self,out_rows,out_ids,out_states,out_icons,ct_rows,ct_ids,ct_states,ct_icons,in_rows,in_ids,in_states,in_icons):
        out_layout=getattr(self,"offers_out_cards_layout",None)
        in_layout=getattr(self,"offers_in_cards_layout",None)
        out_empty=getattr(self,"offers_out_card_empty",None)
        in_empty=getattr(self,"offers_in_card_empty",None)
        for layout in (out_layout,in_layout):
            self._clear_offer_cards(layout)
        for empty,has_rows in ((out_empty,bool(out_rows or ct_rows)),(in_empty,bool(in_rows))):
            if empty is not None:
                empty.setVisible(not has_rows)
        _out_cta=getattr(self,"offers_out_cta",None)
        if _out_cta is not None: _out_cta.setVisible(not (out_rows or ct_rows))
        for index,row in enumerate(out_rows):
            card=self._make_offer_card(out_ids[index],row[1],row[2],row[0],out_states[index],
                                       [("OFFRE",row[3]),("SALAIRE",row[4]),("DURÉE",row[5]),("ÉCHÉANCE",row[7])],
                                       out_icons[index] if index<len(out_icons) else None,"out")
            out_layout.addWidget(card)
        if ct_rows:
            divider=QLabel("CONTRATS INTERNES  •  PROLONGATIONS")
            divider.setObjectName("OfferDivider")
            divider.setStyleSheet("font-size:6.5pt;font-weight:900;letter-spacing:1px;color:#8fc4a8;padding:4px 2px 0 2px;")
            out_layout.addWidget(divider)
        for index,row in enumerate(ct_rows):
            card=self._make_offer_card(ct_ids[index],row[1],row[2],row[0],ct_states[index],
                                       [("SALAIRE",row[3]),("DURÉE",row[4]),("ÉCHÉANCE",row[5])],
                                       ct_icons[index] if index<len(ct_icons) else None,"contract")
            out_layout.addWidget(card)
        for index,row in enumerate(in_rows):
            card=self._make_offer_card(in_ids[index],row[1],row[2],row[0],in_states[index],
                                       [("OFFRE",row[3]),("DOSSIER",row[4]),("ÉCHÉANCE",row[5])],
                                       in_icons[index] if index<len(in_icons) else None,"in")
            in_layout.addWidget(card)
        for layout in (out_layout,in_layout):
            layout.addStretch(1)

    def _refresh_offers_tab(self):
        """ONGLET OFFRES : dossiers d'ACHAT envoyés et offres REÇUES sur nos
        joueurs, avec avatars, statuts colorés et dossiers clos clairement
        distingués (un dossier traité n'est plus présenté comme « en attente »)."""
        if not hasattr(self,"offers_out_table"): return
        try: self.repair_pending_departures()
        except Exception: pass
        keep_id=self._current_offer_id()
        conn=db()
        try:
            rows=conn.execute("SELECT * FROM manager_message WHERE kind IN "
                              "('market_offer','free_agent_contract','transfer_arrival','transfer_sale','transfer_sale_counter','contract_offer') "
                              "ORDER BY id DESC LIMIT 300").fetchall()
            try: budget=int(conn.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"] or 0)
            except Exception: budget=0
        finally:
            conn.close()

        def _data(m):
            try: return json.loads(m["action_data"] or "{}")
            except Exception: return {}

        def _due(m):
            try:
                v=m["due_date"]
                return fmt_date_fr(v) if v else "—"
            except Exception:
                return "—"

        players={}
        def _player(pid):
            if not pid: return None
            if pid in players: return players[pid]
            c=db()
            try: p=c.execute("SELECT * FROM player WHERE id=?",(int(pid),)).fetchone()
            finally: c.close()
            players[pid]=p
            return p

        STATE_COLORS={"wait":"#e6c07a","counter":"#c9b6ff","decision":"#7de0aa","closed":"#8ea3bd","sold":"#7de0aa","rival":"#ff9daa","arrival":"#8fa9c4"}

        # ----- ACHATS -----
        out_rows=[]; out_ids=[]; out_states=[]; out_icons=[]; out_active=0; closed=0
        ct_rows=[]; ct_ids=[]; ct_states=[]; ct_icons=[]; ct_pids=[]; ct_active=0
        for m in rows:
            k=m["kind"]
            if k in ("transfer_sale","transfer_sale_counter"): continue
            d=_data(m); pid=d.get("player_id")
            p=_player(pid)
            pname=(p["first_name"]+" "+p["last_name"]) if p else str(d.get("player_name","—"))
            _contract=(k=="contract_offer")
            if _contract:
                # Prolongation interne : ligne dediee dans le bloc CONTRATS INTERNES.
                _salary=int(d.get("offer_salary",0) or 0)
                _years=int(d.get("offer_years",0) or 0)
                _st=m["status"]; _outcome=str(d.get("outcome","") or "")
                _pos=str((p["position"] if p is not None else "—") or "—")
                if _st=="waiting":
                    _statut="EN ATTENTE DE RÉPONSE"; _state="wait"; ct_active+=1
                elif _st=="ready":
                    if _outcome in ("counter","player_counter"):
                        _statut="CONTRE-PROPOSITION DE L'AGENT"; _state="counter"
                        _salary=int(d.get("counter_salary",_salary) or 0)
                        _years=int(d.get("counter_years",_years) or 0)
                    elif _outcome=="accepted":
                        _statut="ACCORD  •  À CONFIRMER"; _state="decision"
                        _salary=int(d.get("final_salary",_salary) or 0)
                        _years=int(d.get("final_years",_years) or 0)
                    elif _outcome=="unavailable":
                        _statut="REFUS  •  DOSSIER MORT"; _state="rival"
                    else:
                        _statut="RÉPONSE À CONSULTER"; _state="decision"
                    ct_active+=1
                else:
                    _statut="DOSSIER CLOS"; _state="closed"; closed+=1
                ct_rows.append([_statut,pname,_pos,
                                (f"{_salary:,} € /mois".replace(","," ") if _salary else "—"),
                                (f"{_years} an(s)" if _years else "—"),
                                _due(m)])
                ct_ids.append(int(m["id"])); ct_states.append(_state)
                ct_icons.append(self.draw_player_avatar(p,26) if p is not None else None)
                ct_pids.append(int(pid) if pid else 0)
                continue
            club_name=str(d.get("club_name","") or ("Joueur libre" if k=="free_agent_contract" else ""))
            if k=="transfer_arrival":
                fee=d.get("final_fee",d.get("bid")) or d.get("fee") or 0
                fee_s=f"{int(fee or 0):,} €".replace(","," ") if fee else "—"
                salary_s="—"; years_s="—"
            else:
                fee=d.get("bid",d.get("fee")) if k=="market_offer" else 0
                fee_s=f"{int(fee or 0):,} €".replace(","," ") if fee else "—"
                salary=d.get("offer_salary")
                salary_s=f"{int(salary):,} € /mois".replace(","," ") if salary else "—"
                y=d.get("offer_years") or d.get("final_years")
                years_s=f"{int(y)} an(s)" if y else "—"
            st=m["status"]; outcome=str(d.get("outcome","") or "")
            if k=="transfer_arrival":
                if st=="waiting":
                    statut="ARRIVÉE PROGRAMMÉE"; state="arrival"; out_active+=1
                elif outcome in ("unavailable","cancelled","rival"):
                    statut="ARRIVÉE ANNULÉE"; state="closed"; closed+=1
                else:
                    statut="ARRIVÉE CONFIRMÉE"; state="closed"; closed+=1
            elif st=="waiting":
                statut="EN ATTENTE"; state="wait"; out_active+=1
            elif st=="ready":
                if outcome in ("counter","player_counter"):
                    statut="CONTRE-OFFRE  •  À TOI DE JOUER"; state="counter"
                elif outcome in ("accepted","seller_accepted"):
                    statut="ACCORD  •  À CONFIRMER"; state="decision"
                elif outcome=="rival":
                    statut="SIGNÉ AILLEURS"; state="rival"
                else:
                    statut="RÉPONSE À CONSULTER"; state="decision"
                out_active+=1
            else:
                statut="ACCORD  •  CLOS" if (outcome=="accepted" and k=="market_offer") else "DOSSIER CLOS"
                state="closed"; closed+=1
            if outcome=="rival": statut="SIGNÉ À "+str(d.get("rival_club","UN AUTRE CLUB")).upper(); state="rival"
            out_rows.append([statut,pname,club_name,fee_s,salary_s,years_s,f"R{int(d.get('round',0) or 0)}",_due(m)])
            out_ids.append(int(m["id"])); out_states.append(state)
            out_icons.append(self.draw_player_avatar(p,26) if p is not None else None)

        # ----- VENTES -----
        in_rows=[]; in_ids=[]; in_states=[]; in_icons=[]; in_active=0
        for m in rows:
            k=m["kind"]
            if k not in ("transfer_sale","transfer_sale_counter"): continue
            d=_data(m); pid=d.get("player_id"); p=_player(pid)
            pname=(p["first_name"]+" "+p["last_name"]) if p else str(d.get("player_name","—"))
            still_own=bool(p is not None and int(p["club_id"] or 0)==1
                           and not int(p["is_free_agent"] or 0)
                           and not (int(p["retired"] or 0) if "retired" in p.keys() else 0))
            st=m["status"]; outcome=str(d.get("outcome","") or "")
            fee=d.get("counter_fee",d.get("bid",d.get("fee",0))) or 0
            fee_s=f"{int(fee or 0):,} €".replace(","," ") if fee else "—"
            dossier="VENTE" if k=="transfer_sale" else "CONTRE-OFFRE ENVOYÉE"
            if not still_own:
                statut="JOUEUR PARTI  •  DOSSIER CLOS"; state="closed"; closed+=1
            elif st=="waiting":
                statut="OFFRE EN PRÉPARATION"; state="wait"
            elif st=="ready":
                statut="DÉCISION ATTENDUE  •  À TOI DE JOUER"; state="decision"; in_active+=1
            else:
                if outcome=="accepted": statut="VENDU  •  ACCEPTÉ"; state="sold"
                else: statut="DOSSIER CLOS"; state="closed"; closed+=1
            if d.get("unsolicited") and st in ("waiting","ready"):
                statut="OFFRE SPONTANÉE  •  "+statut
            in_rows.append([statut,pname,str(d.get("buyer_name","—")),fee_s,dossier,_due(m)])
            in_ids.append(int(m["id"])); in_states.append(state)
            in_icons.append(self.draw_player_avatar(p,26) if p is not None else None)

        def _fill(table,rws,rws_ids,states=None,icons=None):
            table.blockSignals(True); table.setSortingEnabled(False)
            table.clearSelection(); table.setCurrentCell(-1,-1)
            table.setRowCount(len(rws))
            for i,vals in enumerate(rws):
                for j,v in enumerate(vals):
                    it=QTableWidgetItem(str(v)); it.setToolTip(str(v))
                    if j==0:
                        it.setData(Qt.UserRole,int(rws_ids[i]) if i<len(rws_ids) else 0)
                        if states:
                            it.setForeground(QColor(STATE_COLORS.get(states[i],"#c7d2e0")))
                            fnt=it.font(); fnt.setBold(True); it.setFont(fnt)
                    if j==1 and icons and i<len(icons) and icons[i] is not None:
                        it.setIcon(QIcon(icons[i]))
                    table.setItem(i,j,it)
            table.setSortingEnabled(False); table.blockSignals(False)

        show_closed=bool(getattr(self,"offers_show_closed",None) is not None and self.offers_show_closed.isChecked())
        if not show_closed:
            def _active_only(rows,ids,states,icons):
                keep=[i for i,st in enumerate(states) if st not in ("closed","sold","rival")]
                return ([rows[i] for i in keep],[ids[i] for i in keep],[states[i] for i in keep],[icons[i] for i in keep])
            out_rows,out_ids,out_states,out_icons=_active_only(out_rows,out_ids,out_states,out_icons)
            in_rows,in_ids,in_states,in_icons=_active_only(in_rows,in_ids,in_states,in_icons)
            _keep=[i for i,st in enumerate(ct_states) if st not in ("closed","rival")]
            ct_rows=[ct_rows[i] for i in _keep]; ct_ids=[ct_ids[i] for i in _keep]
            ct_states=[ct_states[i] for i in _keep]; ct_icons=[ct_icons[i] for i in _keep]
            ct_pids=[ct_pids[i] for i in _keep]

        def _ordered(rows,ids,states,icons):
            idx=sorted(range(len(rows)),key=lambda i:(states[i]=="closed" or states[i]=="sold",-ids[i]))
            return ([rows[i] for i in idx],[ids[i] for i in idx],[states[i] for i in idx],[icons[i] for i in idx])

        out_rows,out_ids,out_states,out_icons=_ordered(out_rows,out_ids,out_states,out_icons)
        in_rows,in_ids,in_states,in_icons=_ordered(in_rows,in_ids,in_states,in_icons)
        if ct_rows:
            _cidx=sorted(range(len(ct_rows)),key=lambda i:(ct_states[i] in ("closed","rival"),-ct_ids[i]))
            ct_rows=[ct_rows[i] for i in _cidx]; ct_ids=[ct_ids[i] for i in _cidx]
            ct_states=[ct_states[i] for i in _cidx]; ct_icons=[ct_icons[i] for i in _cidx]
            ct_pids=[ct_pids[i] for i in _cidx]
        _fill(self.offers_out_table,out_rows,out_ids,out_states,out_icons)
        self.offers_out_table.setVisible(bool(out_rows))
        if hasattr(self,"offers_out_empty"): self.offers_out_empty.setVisible(not out_rows)
        if hasattr(self,"offers_contract_table"):
            _fill(self.offers_contract_table,ct_rows,ct_ids,ct_states,ct_icons)
            if ct_rows:
                self.offers_contract_table.setFixedHeight(min(226,46+38*len(ct_rows)))
            self.offers_contract_table.setVisible(bool(ct_rows))
            self.offers_contract_count.setText(f"CONTRATS : {ct_active} EN COURS")
            self._contract_player_ids=list(ct_pids)
        if hasattr(self,"offers_contract_empty"):
            self.offers_contract_empty.setVisible(not ct_rows)

        _fill(self.offers_in_table,in_rows,in_ids,in_states,in_icons)
        self.offers_in_table.setVisible(bool(in_rows))
        if hasattr(self,"offers_in_empty"): self.offers_in_empty.setVisible(not in_rows)
        self._refresh_offer_cards(out_rows,out_ids,out_states,out_icons,ct_rows,ct_ids,ct_states,ct_icons,in_rows,in_ids,in_states,in_icons)
        for _tbl in (self.offers_out_table,self.offers_contract_table,self.offers_in_table):
            _tbl.setVisible(False)
        for _empty in (getattr(self,"offers_out_empty",None),getattr(self,"offers_contract_empty",None),getattr(self,"offers_in_empty",None)):
            if _empty is not None: _empty.setVisible(False)
        self.offers_out_count.setText(f"ACHATS : {out_active} ACTIF(S)")
        self.offers_in_count.setText(f"VENTES : {in_active} À TRAITER")
        if hasattr(self,"offers_left_title"):
            self.offers_left_title.setText(f"NOS DÉMARCHES  •  {out_active} ACHAT(S)  •  {ct_active} CONTRAT(S)")
        if hasattr(self,"offers_right_title"):
            self.offers_right_title.setText(f"OFFRES REÇUES  •  {in_active} À TRAITER")
        if hasattr(self,"offers_hero_budget"):
            self.offers_hero_budget.setText(f"{budget:,} €".replace(","," "))
        if hasattr(self,"offers_hero_next"):
            due=[str(r["due_date"]) for r in rows if r["status"] in ("waiting","ready") and r["due_date"]]
            nxt=min(due) if due else None
            self.offers_hero_next.setText(fmt_date_fr(nxt) if nxt else "Aucune")
        if hasattr(self,"offers_hero_sub"):
            _tail=(f"  •  {closed} dossier(s) clos" if show_closed else (f"  •  {closed} dossier(s) clos masqué(s)" if closed else ""))
            _win=self.transfer_window_state()
            _win_txt=(f"{_win['label']} • ferme le {fmt_date_fr(_win['closes'].isoformat())}" if _win["open"]
                      else f"{_win['label']} • réouverture le {fmt_date_fr(_win['reopens'].isoformat())}")
            self.offers_hero_sub.setText(f"{out_active} achat(s) actif(s)  •  {ct_active} prolongation(s)  •  {in_active} offre(s) reçue(s) à traiter  •  {_win_txt}"+_tail)
        # La selection est videe au remplissage : les boutons repartent neutres,
        # puis on restaure le dossier precedent s'il est toujours a l'ecran.
        self._offer_selected_id=None; self._offer_selected_meta={}
        for _btn in (getattr(self,"offer_open_btn",None),getattr(self,"offer_accept_btn",None),
                     getattr(self,"offer_reject_btn",None),getattr(self,"offer_counter_btn",None)):
            if _btn is not None: _btn.setEnabled(False)
        if keep_id:
            for _name in ("offers_out_table","offers_contract_table","offers_in_table"):
                _tbl=getattr(self,_name,None)
                if _tbl is None: continue
                _found=False
                for _r in range(_tbl.rowCount()):
                    _it=_tbl.item(_r,0)
                    if _it is not None and int(_it.data(Qt.UserRole) or 0)==int(keep_id):
                        _tbl.selectRow(_r); self._offer_selection_changed(_tbl); _found=True; break
                if _found: break
        self._offers_dirty=False
        self._offers_out_rows=out_rows; self._offers_in_rows=in_rows
        try: self._refresh_precontracts()
        except Exception: pass

    def _refresh_precontracts(self):
        """Bandeau ARRIVÉES PRÉVUES : pré-contrats signés + dossiers en réflexion."""
        strip=getattr(self,"precontract_strip",None)
        lay=getattr(self,"precontract_row",None)
        if strip is None or lay is None:
            return
        rows=[]; pending=[]
        try:
            conn=db()
            rows=conn.execute("""SELECT p.id,p.first_name,p.last_name,p.position,p.salary,p.precontract_salary,
                                        p.precontract_years,c.name AS from_name
                                 FROM player p LEFT JOIN club c ON c.id=p.precontract_from
                                 WHERE COALESCE(p.precontract_club,0)=1
                                 ORDER BY p.last_name,p.first_name""").fetchall()
            pending=conn.execute("""SELECT o.*,p.first_name,p.last_name,p.position,p.salary,c.name AS from_name
                                    FROM precontract_offer o JOIN player p ON p.id=o.player_id
                                    LEFT JOIN club c ON c.id=o.from_club
                                    WHERE o.status='waiting' ORDER BY o.decision_date,o.id""").fetchall()
            conn.close()
        except Exception:
            rows=[]; pending=[]
        while lay.count():
            it=lay.takeAt(0)
            w=it.widget()
            if w is not None:
                # Détacher tout de suite : deleteLater n'est pas traité tant que
                # la boucle d'événements n'a pas repris (sinon cartes fantômes).
                w.setParent(None); w.deleteLater()
        if not rows and not pending:
            strip.setVisible(False)
            return
        strip.setVisible(True)
        self.precontract_title.setText(
            f"ARRIVÉES PRÉVUES  •  {len(rows)} PRÉ-CONTRAT(S)" + (f"  •  {len(pending)} EN RÉFLEXION" if pending else ""))
        head=QLabel(f"ARRIVÉES PRÉVUES  •  {len(rows)} PRÉ-CONTRAT(S)" + (f"  •  {len(pending)} EN RÉFLEXION" if pending else ""))
        head.setStyleSheet("font-size:8pt;font-weight:1000;letter-spacing:1px;color:#8fc4a8;padding-right:4px;")
        lay.addWidget(head)
        for o in pending[:4]:
            card=QFrame(); card.setObjectName("PreCardPending")
            card.setStyleSheet("QFrame#PreCardPending{background:#1b1a12;border:1px solid #6b5a2a;border-radius:10px;}")
            cl=QVBoxLayout(card); cl.setContentsMargins(10,7,10,7); cl.setSpacing(2)
            name=QLabel(f"{o['first_name']} {o['last_name']}")
            name.setStyleSheet("font-size:9pt;font-weight:900;color:#f7eed2;")
            wage=int(o["salary"] or 0)
            meta=QLabel(f"EN RÉFLEXION  •  de {o['from_name'] or 'club'}  •  {wage:,} €/mois  •  "
                        f"décision le {fmt_date_fr(str(o['decision_date']))}".replace(",", " "))
            meta.setStyleSheet("font-size:7.5pt;color:#d9c38a;")
            cl.addWidget(name); cl.addWidget(meta)
            if int(o["counter_salary"] or 0)>0:
                counter=QLabel(f"Contre-offre de son club : {int(o['counter_salary']):,} €/mois".replace(",", " "))
                counter.setStyleSheet("font-size:7.2pt;font-weight:900;color:#ffb37a;")
                cl.addWidget(counter)
            card.setToolTip(f"{o['first_name']} {o['last_name']} étudie l'offre. Son club peut proposer une prolongation. Décision le {fmt_date_fr(str(o['decision_date']))}.")
            lay.addWidget(card)
        for p in rows[:6]:
            card=QFrame(); card.setObjectName("PreCard")
            card.setStyleSheet("QFrame#PreCard{background:#0f1c2a;border:1px solid #274a3c;border-radius:10px;}")
            cl=QVBoxLayout(card); cl.setContentsMargins(10,7,10,7); cl.setSpacing(2)
            name=QLabel(f"{p['first_name']} {p['last_name']}")
            name.setStyleSheet("font-size:9pt;font-weight:900;color:#eaf7ef;")
            wage=int(p["precontract_salary"] or p["salary"] or 0)
            meta=QLabel(f"{p['position']}  •  de {p['from_name'] or 'club'}  •  "
                        f"{wage:,} €/mois  •  {int(p['precontract_years'] or 2)} an(s)".replace(",", " "))
            meta.setStyleSheet("font-size:7.5pt;color:#9fc4af;")
            cl.addWidget(name); cl.addWidget(meta)
            lay.addWidget(card)
        if len(rows)>6:
            more=QLabel(f"+{len(rows)-6} autre(s) — voir la messagerie")
            more.setStyleSheet("font-size:7.5pt;font-weight:900;color:#7f93ad;padding-left:4px;")
            more.setToolTip("Tous les pré-contrats signés sont listés dans la messagerie (messages « Pré-contrat signé »).")
            lay.addWidget(more)
        lay.addStretch(1)

    def _open_message_by_id(self,mid):
        """Sélectionne un message précis dans la messagerie (depuis OFFRES)."""
        try:
            if hasattr(self,"action_message_list"):
                for i in range(self.action_message_list.count()):
                    it=self.action_message_list.item(i)
                    if it and int(it.data(Qt.UserRole) or 0)==int(mid):
                        self.action_message_list.setCurrentItem(it); return True
        except Exception:
            pass
        return False

    def _offer_selection_changed(self,table=None):
        """Active/désactive les boutons d'action selon le dossier choisi."""
        try:
            tbl=table if table is not None else self.sender()
            if tbl is None: return
            row=tbl.currentRow(); mid=None
            if row>=0:
                it=tbl.item(row,0)
                if it is not None: mid=it.data(Qt.UserRole)
            self._offer_selected_id=int(mid) if mid else None
            meta={}
            if self._offer_selected_id:
                c=db()
                m=c.execute("SELECT * FROM manager_message WHERE id=?",(self._offer_selected_id,)).fetchone()
                c.close()
                if m:
                    try: meta=json.loads(m["action_data"] or "{}")
                    except Exception: meta={}
                    meta["_kind"]=m["kind"]; meta["_status"]=m["status"]
            self._offer_selected_meta=meta
            ready=(meta.get("_status")=="ready")
            kind=str(meta.get("_kind",""))
            known=kind in ("market_offer","transfer_sale","transfer_sale_counter","contract_offer","free_agent_contract")
            can_decide=ready and known
            can_reject=known and meta.get("_status") in ("ready","waiting")
            for b in (getattr(self,"offer_accept_btn",None),getattr(self,"offer_counter_btn",None)):
                if b is not None: b.setEnabled(bool(can_decide))
            reject_btn=getattr(self,"offer_reject_btn",None)
            if reject_btn is not None: reject_btn.setEnabled(bool(can_reject))
            accept_btn=getattr(self,"offer_accept_btn",None)
            if accept_btn is not None:
                if kind=="contract_offer": accept_btn.setText("SIGNER LE CONTRAT")
                elif kind=="free_agent_contract": accept_btn.setText("SIGNER LE JOUEUR")
                else: accept_btn.setText("ACCEPTER")
            if getattr(self,"offer_open_btn",None) is not None:
                self.offer_open_btn.setEnabled(bool(self._offer_selected_id))
        except Exception:
            pass

    def _current_offer_id(self):
        """Dossier sélectionné, même si le refresh a nettoyé l'identifiant interne."""
        mid=getattr(self,"_offer_selected_id",None)
        if mid: return int(mid)
        for name in ("offers_out_table","offers_contract_table","offers_in_table"):
            table=getattr(self,name,None)
            if table is None: continue
            row=table.currentRow()
            item=table.item(row,0) if row>=0 else None
            if item is not None:
                value=item.data(Qt.UserRole)
                if value: return int(value)
        return None

    def _offer_action(self,action):
        """Agit sur le dossier sélectionné depuis l'onglet OFFRES."""
        mid=self._current_offer_id()
        if not mid:
            self.show_game_message("Offres","Sélectionne un dossier dans un des deux tableaux.","info"); return
        if action=="open":
            self.show_page(6)
            try: self._open_message_by_id(int(mid))
            except Exception: pass
            return
        # Un dossier encore « en préparation » n'a pas de réponse formelle :
        # on peut déjà l'écarter, sans passer par la messagerie.
        try:
            probe=db()
            row=probe.execute("SELECT status FROM manager_message WHERE id=?",(int(mid),)).fetchone()
            probe.close()
            if action=="reject" and row is not None and row["status"]!="ready":
                conn=db()
                conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(int(mid),))
                conn.commit(); conn.close()
                self._offers_dirty=True
                self._offer_selected_id=None
                self.refresh_all(); self._refresh_offers_tab()
                self.show_game_message("Dossier écarté","L'offre est refusée et classée sans suite.","info")
                return
        except Exception as exc:
            self.log_error("offer_action_precheck",exc)
        try:
            self._resolve_message(int(mid),action)
        finally:
            self._offer_selected_id=None
            self._refresh_offers_tab()

    def _open_offer_row_in_market(self,row,column):

        table=self.sender()
        if not isinstance(table,QTableWidget): table=self.offers_out_table

        it=table.item(row,1) if row>=0 else None

        pname=it.text() if it else ""

        pid=None

        if pname:

            c=db()

            r=c.execute("SELECT id FROM player WHERE first_name||' '||last_name=?",(pname,)).fetchone(); c.close()

            if r: pid=int(r["id"])

        if pid:

            c=db(); player=c.execute("SELECT p.*,c.name club_name,c.division club_division FROM player p JOIN club c ON c.id=p.club_id WHERE p.id=?",(pid,)).fetchone()

            c.close()

            if player: self.show_player_profile(player)



    def _mercato_tab_changed(self,index):

        """Retour sur l'onglet HISTORIQUE : reconstruit SEULEMENT si les donnees

        ont bouge depuis la derniere construction (retour joueur : l'onglet

        doit rester fluide a l'ouverture)."""

        try:

            if index==4 and (getattr(self,"_transfer_history_dirty",True) or not getattr(self,"_history_built",False)):
                QTimer.singleShot(0, lambda: self.refresh_transfer_history())

            if index==5:

                self.refresh_loans_tab()

            if index==0 or (getattr(self,"_offers_dirty",False) and index==0):

                self._refresh_offers_tab()

        except Exception as exc:

            self.log_error("mercato_tab_changed",exc)



    def _loan_club_played(self,conn,club_id,season,since=None):
        if since:
            try:
                row=conn.execute("SELECT COUNT(*) n FROM fixture WHERE season=? AND played=1 "
                                 "AND fixture_date>=? AND (home_club_id=? OR away_club_id=?)",
                                 (int(season),str(since),int(club_id),int(club_id))).fetchone()
                _n=int(row["n"] or 0)
                if _n>0: return _n
            except Exception:
                pass
        try:
            row=conn.execute("SELECT played FROM league_standing WHERE club_id=? LIMIT 1",
                             (int(club_id),)).fetchone()
            if row is not None and row["played"] is not None:
                return int(row["played"] or 0)
        except Exception:
            pass
        try:
            row=conn.execute("SELECT COUNT(*) n FROM fixture WHERE season=? AND played=1 "
                             "AND COALESCE(fixture_type,'championship')='championship' "
                             "AND (home_club_id=? OR away_club_id=?)",
                             (int(season),int(club_id),int(club_id))).fetchone()
            return int(row["n"] or 0)
        except Exception:
            return 0

    @staticmethod
    def _loan_expected(player,played):
        ratio=0.65 if str(player["loan_promise"] or "").upper()=="TITULAIRE" else 0.35
        return int(math.ceil(max(0,played)*ratio)),ratio

    def _loan_evolution(self,player,baselines):
        cur=player_level_from_row(player)
        base=baselines.get(int(player["id"]))
        if not base: return cur,None,None
        attrs=("technique","passing","finishing","defense","goalkeeper","stamina","speed","dribble","positioning")
        try:
            base_map={k:int(base[k] or 0) for k in attrs}
            base_map["position"]=player["position"]
            before=player_level_from_row(base_map)
        except Exception:
            return cur,None,None
        delta_points=sum(int(player[k] or 0) for k in attrs)-sum(int(base[k] or 0) for k in attrs)
        return cur,cur-before,delta_points

    @staticmethod
    def _loan_evolution_text(delta_level,delta_points):
        if delta_level is None: return "—"
        if delta_level>0: return f"+{delta_level} niv."
        if delta_level<0: return f"{delta_level} niv."
        if delta_points>0: return f"+{delta_points} pts"
        if delta_points<0: return f"{delta_points} pts"
        return "stable"

    def refresh_loans_tab(self):
        """Onglet PRÊTS : suivi, évolution, fiche et fin de prêt."""
        if not hasattr(self,"loans_out_table"): return
        try:
            conn=db()
            season=int((conn.execute("SELECT season FROM club WHERE id=1").fetchone() or {"season":1})["season"] or 1)
            out_rows=conn.execute("""SELECT p.*, c.name club_name, c.division club_division
                                     FROM player p JOIN club c ON c.id=p.club_id
                                     WHERE COALESCE(p.loan_from_club,0)=1 AND p.club_id<>1
                                       AND COALESCE(p.retired,0)=0
                                     ORDER BY p.loan_until_season, p.last_name""").fetchall()
            in_rows=conn.execute("""SELECT p.*, COALESCE(c.name,'Club inconnu') club_name
                                    FROM player p LEFT JOIN club c ON c.id=p.loan_from_club
                                    WHERE p.club_id=1 AND COALESCE(p.loan_from_club,0)>0
                                    ORDER BY p.last_name""").fetchall()
            baselines={int(r["player_id"]): r for r in
                       conn.execute("SELECT * FROM player_attr_baseline WHERE season=?",(season,)).fetchall()}
            out_played={int(p["id"]): self._loan_club_played(conn,int(p["club_id"]),season,(p["loan_start_date"] or None))
                        for p in out_rows}
            in_played={int(p["id"]): self._loan_club_played(conn,1,season,(p["loan_start_date"] or None))
                       for p in in_rows}
            conn.close()

            def note(p):
                rc=int(p["season_rating_count"] or 0)
                return (float(p["season_rating_sum"] or 0)/rc) if rc else 0.0

            self.loans_out_table.setSortingEnabled(False); self.loans_out_table.setRowCount(0)
            under=0
            for p in out_rows:
                r=self.loans_out_table.rowCount(); self.loans_out_table.insertRow(r)
                cur,dl,dp=self._loan_evolution(p,baselines)
                played=int(out_played.get(int(p["id"]),0))
                matches=int(p["season_matches"] or 0)
                start_m=int(p["loan_start_matches"] or 0)
                has_start=bool(p["loan_start_date"])
                since=max(0,matches-start_m) if has_start else matches
                expected,ratio=self._loan_expected(p,played)
                missing=played>=3 and since<expected
                if missing: under+=1
                play_txt=(f"{since}/{played}" if has_start else f"{matches} m. saison")
                if missing: play_txt+="  ⚠"
                cells=[f"{p['first_name']} {p['last_name']}", p["position"], str(int(p["age"] or 0)),
                       p["club_name"], f"Ligue {p['club_division']}",
                       str(p["loan_promise"] or "ROTATION").capitalize(),
                       f"{cur}/20", self._loan_evolution_text(dl,dp), play_txt,
                       f"{note(p):.1f}" if int(p["season_rating_count"] or 0) else "—",
                       "Fin de saison"]
                for c,text in enumerate(cells):
                    item=QTableWidgetItem(text)
                    if c==0: item.setData(Qt.UserRole,int(p["id"]))
                    if c==7:
                        item.setToolTip((f"Niveau {cur}/20 • {dl:+d} niveau(x) • {dp:+d} pts d'attributs"
                                         if dl is not None else "Pas de référence en début de saison"))
                    if c==8:
                        _basis=(f"{since} match(s) depuis le prêt sur {played}"
                                if has_start else f"{matches} match(s) cette saison • club : {played} match(s)")
                        item.setToolTip(f"{_basis} • promesse {str(p['loan_promise'] or 'ROTATION').lower()} "
                                        f"(attendu ~{round(ratio*100)} %)")
                        if missing:
                            item.setForeground(QColor("#ff8d97")); _f=item.font(); _f.setBold(True); item.setFont(_f)
                        elif since>=expected:
                            item.setForeground(QColor("#8fe0a3"))
                        else:
                            item.setForeground(QColor("#ffd98a"))
                    self.loans_out_table.setItem(r,c,item)
            self.loans_out_table.setSortingEnabled(True)

            self.loans_in_table.setSortingEnabled(False); self.loans_in_table.setRowCount(0)
            for p in in_rows:
                r=self.loans_in_table.rowCount(); self.loans_in_table.insertRow(r)
                cur,dl,dp=self._loan_evolution(p,baselines)
                matches=int(p["season_matches"] or 0)
                start_m=int(p["loan_start_matches"] or 0)
                has_start=bool(p["loan_start_date"])
                since=max(0,matches-start_m) if has_start else matches
                played=int(in_played.get(int(p["id"]),0))
                expected,ratio=self._loan_expected(p,played)
                play_txt=(f"{since}/{played}" if has_start else f"{matches} m. saison")
                cells=[f"{p['first_name']} {p['last_name']}", p["position"], str(int(p["age"] or 0)),
                       p["club_name"], f"{cur}/20", self._loan_evolution_text(dl,dp), play_txt,
                       f"{note(p):.1f}" if int(p["season_rating_count"] or 0) else "—",
                       "Fin de saison"]
                for c,text in enumerate(cells):
                    item=QTableWidgetItem(text)
                    if c==0: item.setData(Qt.UserRole,int(p["id"]))
                    if c==5:
                        item.setToolTip((f"Niveau {cur}/20 • {dl:+d} niveau(x) • {dp:+d} pts d'attributs"
                                         if dl is not None else "Pas de référence en début de saison"))
                    if c==6:
                        _basis=(f"{since} match(s) depuis le prêt sur {played}"
                                if has_start else f"{matches} match(s) cette saison • club : {played} match(s)")
                        item.setToolTip(f"{_basis} • promesse {str(p['loan_promise'] or 'ROTATION').lower()} "
                                        f"(attendu ~{round(ratio*100)} %)")
                    self.loans_in_table.setItem(r,c,item)
            self.loans_in_table.setSortingEnabled(True)

            self.loans_out_count.setText(f"PRÊTS SORTANTS : {len(out_rows)} / 3")
            self.loans_in_count.setText(f"PRÊTS ENTRANTS : {len(in_rows)}")
            self.loans_out_empty.setVisible(not out_rows); self.loans_out_table.setVisible(bool(out_rows))
            self.loans_in_empty.setVisible(not in_rows); self.loans_in_table.setVisible(bool(in_rows))
            self.loans_out_watch.setVisible(bool(under))
            if under:
                self.loans_out_watch.setText(
                    f"⚠ {under} prêt(s) sans temps de jeu — sélectionne le joueur puis METTRE FIN AU PRÊT.")
            self.loans_recall_btn.setEnabled(bool(out_rows)); self.loans_end_btn.setEnabled(bool(in_rows or out_rows))
            self.loans_profile_btn.setEnabled(bool(out_rows or in_rows))
            self._loans_dirty=False
        except Exception as exc:
            self.log_error("refresh_loans_tab",exc)

    def _loan_row_pid(self,table):
        row=table.currentRow()
        if row<0: return 0
        item=table.item(row,0)
        try: return int(item.data(Qt.UserRole) or 0) if item else 0
        except Exception: return 0

    def _recall_selected_loan(self):
        from loan_engine import recall_loaned_player
        pid=self._loan_row_pid(self.loans_out_table)
        if not pid:
            self.show_game_message("Prêt","Sélectionne d'abord un joueur prêté dans la liste.","info"); return
        if recall_loaned_player(self,pid):
            self.refresh_loans_tab()

    def _set_loan_side(self,side):
        self._last_loan_side=str(side)
        try:
            self.loans_profile_btn.setEnabled(
                bool(self._loan_row_pid(self.loans_out_table) or self._loan_row_pid(self.loans_in_table)))
        except Exception:
            pass

    def _open_loan_player(self,table,row):
        item=table.item(int(row),0)
        try: pid=int(item.data(Qt.UserRole) or 0) if item else 0
        except Exception: pid=0
        if pid: self.open_club_player_profile(pid)

    def _open_selected_loan_profile(self):
        out_pid=self._loan_row_pid(self.loans_out_table)
        in_pid=self._loan_row_pid(self.loans_in_table)
        if in_pid and not out_pid:
            self._open_loan_player(self.loans_in_table,self.loans_in_table.currentRow()); return
        if out_pid:
            self._open_loan_player(self.loans_out_table,self.loans_out_table.currentRow()); return
        self.show_game_message("Prêt","Sélectionne d'abord un joueur dans une des deux listes.","info")

    def _end_selected_loan(self):
        out_pid=self._loan_row_pid(self.loans_out_table)
        in_pid=self._loan_row_pid(self.loans_in_table)
        side=getattr(self,"_last_loan_side","out")
        if out_pid and not in_pid: side="out"
        elif in_pid and not out_pid: side="in"
        if side=="out":
            if not out_pid:
                self.show_game_message("Prêt","Sélectionne d'abord un joueur prêté dans NOS PRÊTS SORTANTS.","info"); return
            conn=db()
            try:
                p=conn.execute("SELECT * FROM player WHERE id=?",(int(out_pid),)).fetchone()
                season=int((conn.execute("SELECT season FROM club WHERE id=1").fetchone() or {"season":1})["season"] or 1)
                played=self._loan_club_played(conn,int(p["club_id"]),season)
            finally:
                conn.close()
            if p is None:
                self.show_game_message("Prêt","Ce joueur n'existe plus.","warning"); return
            matches=int(p["season_matches"] or 0)
            expected,ratio=self._loan_expected(p,played)
            if played>=3 and matches>=expected:
                self.show_game_message("Prêt",
                    f"{p['first_name']} {p['last_name']} joue ({matches}/{played} matchs) : le prêt est utile. "
                    "Utilise RAPPELER LE JOUEUR s'il doit revenir malgré tout.","info"); return
            from loan_engine import recall_loaned_player
            if recall_loaned_player(self,int(out_pid)):
                self.refresh_loans_tab()
            return
        if not in_pid:
            self.show_game_message("Prêt","Sélectionne d'abord un joueur prêté par un autre club.","info"); return
        if self.terminate_loan(int(in_pid)):
            self.refresh_loans_tab()

    def open_loan_out_dialog(self,player_id=None):
        """Prête un jeune du club : choix du club d'accueil et de la promesse."""
        try:
            from loan_engine import loan_candidates, loan_out_block_reason, request_loan_out
            conn=db()
            win=self.transfer_window_state(conn)
            all_players=conn.execute("""SELECT p.*, c.name club_name FROM player p JOIN club c ON c.id=p.club_id
                                        WHERE p.club_id=1 AND COALESCE(p.is_free_agent,0)=0
                                          AND COALESCE(p.retired,0)=0
                                        ORDER BY p.age ASC, p.last_name""").fetchall()
            reasons={int(p["id"]):loan_out_block_reason(conn,p) for p in all_players}
            eligible=[p for p in all_players if not reasons.get(int(p["id"]))]
            conn.close()
            if player_id is not None and int(player_id) not in {int(p["id"]) for p in eligible}:
                reason=next((reasons.get(int(p["id"])) for p in all_players if int(p["id"])==int(player_id)),None)
                self.show_game_message("Prêt impossible",reason or "Ce joueur ne peut pas être prêté.","warning"); return False
            if not win["open"]:
                self.show_game_message("Mercato fermé",f"Les prêts se règlent pendant une fenêtre (réouverture le {fmt_date_fr(win['reopens'].isoformat())}).","warning"); return False
            if not eligible:
                self.show_game_message("Aucun jeune à prêter","Aucun joueur éligible (23 ans ou moins, effectif suffisant, aucun prêt en cours).","info"); return False

            dlg=QDialog(self); dlg.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dlg.setWindowTitle("Prêter un jeune")
            dlg.setMinimumWidth(560); lay=QVBoxLayout(dlg); lay.setContentsMargins(18,18,18,18); lay.setSpacing(10)
            title=QLabel("PRÊTER UN JEUNE JOUEUR"); title.setStyleSheet("font-size:13pt;font-weight:1000;color:#f4f7fd;letter-spacing:.6px;")
            note=QLabel("Le joueur quitte l'effectif jusqu'à la fin de la saison : il joue chaque semaine selon la promesse, progresse, et revient automatiquement. Son salaire sort de tes charges pendant le prêt.")
            note.setObjectName("Muted"); note.setWordWrap(True)
            lay.addWidget(title); lay.addWidget(note)

            form=QGridLayout(); form.setSpacing(8)
            form.addWidget(QLabel("JOUEUR"),0,0)
            player_combo=QComboBox()
            for p in eligible:
                player_combo.addItem(f"{p['first_name']} {p['last_name']} • {p['position']} • {p['age']} ans • niveau {player_level_from_row(p)}/20",int(p["id"]))
            if player_id is not None:
                idx=next((i for i in range(player_combo.count()) if int(player_combo.itemData(i) or 0)==int(player_id)),-1)
                if idx>=0: player_combo.setCurrentIndex(idx)
            form.addWidget(player_combo,0,1)
            form.addWidget(QLabel("CLUB D'ACCUEIL"),1,0)
            club_combo=QComboBox(); form.addWidget(club_combo,1,1)
            form.addWidget(QLabel("PROMESSE"),2,0)
            promise=QComboBox(); promise.addItems(["TITULAIRE","ROTATION"]); promise.setCurrentText("ROTATION"); form.addWidget(promise,2,1)
            lay.addLayout(form)

            detail=QLabel(""); detail.setWordWrap(True); detail.setStyleSheet("color:#9ce6bf;font-weight:800;")
            lay.addWidget(detail)
            state={"candidates":[]}

            def refresh_detail(*_):
                cands=state["candidates"]
                pid=int(player_combo.currentData() or 0)
                chosen=next((c for c in cands if c["id"]==int(club_combo.currentData() or 0)),None)
                share="environ 85 % des matchs" if promise.currentText()=="TITULAIRE" else "environ 55 % des matchs"
                if chosen:
                    detail.setText(f"{chosen['name']} • Ligue {chosen['division']} • effectif {chosen['count']} • "
                                   f"promesse {promise.currentText().lower()} : {share}. Réponse sous 1 à 3 jours.")
                else:
                    detail.setText("Aucun club disponible pour ce profil : réessaie avec un autre jeune ou plus tard.")

            def refresh_clubs(*_):
                pid=int(player_combo.currentData() or 0)
                c2=db(); cands=loan_candidates(c2,pid); c2.close()
                state["candidates"]=cands
                club_combo.blockSignals(True); club_combo.clear()
                if not cands:
                    club_combo.addItem("Aucun club disponible",0)
                for c in cands:
                    club_combo.addItem(f"{c['name']} • Ligue {c['division']} • effectif {c['count']}",c["id"])
                club_combo.blockSignals(False)
                refresh_detail()

            player_combo.currentIndexChanged.connect(refresh_clubs)
            club_combo.currentIndexChanged.connect(refresh_detail)
            promise.currentIndexChanged.connect(refresh_detail)
            refresh_clubs()

            btns=QHBoxLayout(); btns.addStretch()
            cancel=QPushButton("ANNULER"); cancel.clicked.connect(dlg.reject); btns.addWidget(cancel)
            send=QPushButton("ENVOYER LA DEMANDE"); send.setObjectName("Primary"); send.clicked.connect(dlg.accept); btns.addWidget(send)
            lay.addLayout(btns)

            if dlg.exec()!=QDialog.Accepted: return False
            pid=int(player_combo.currentData() or 0); did=int(club_combo.currentData() or 0)
            if not pid or not did:
                self.show_game_message("Prêt impossible","Choisis un club d'accueil pour envoyer la demande.","warning"); return False
            ok=request_loan_out(self,pid,did,promise.currentText())
            if ok: self.refresh_loans_tab()
            return ok
        except Exception as exc:
            self.log_error("open_loan_out_dialog",exc); return False

    def refresh_transfer_history(self, force=False):

        """Onglet HISTORIQUE : arrivées/départs du club (player_history) avec

        l'indemnité réelle de la transaction, retrouvée dans finance_tx.



        Performance : la construction est CHÈRE (centaines de cellules Qt) —

        elle est passée en LAZY :

          • si l'onglet n'est PAS affiché et que le tableau existe déjà, on

            marque seulement « dirty » (quasi instantané) ;

          • la reconstruction se déclenche à l'ouverture de l'onglet (ou via

            le filtre de saison).

        Filtre : VOIR TOUT par défaut, ou une saison précise."""

        if not hasattr(self,"transfer_history_table"): return

        try:

            lazy=getattr(self,"mercato_tabs",None)
            if not force:
                if lazy is not None and lazy.currentIndex()!=4:
                    # Hors onglet : on ne reconstruit pas, on marque seulement.
                    self._transfer_history_dirty=True
                    return
                if getattr(self,"_history_built",False) and not getattr(self,"_transfer_history_dirty",False):
                    return

            season_filter=getattr(self,"history_season_filter",None)

            season=None

            if season_filter is not None:

                season=season_filter.currentData()

            conn=db()

            where="h.kind IN ('transfer','free') AND (h.club_id=1 OR h.detail LIKE 'Départ vers%' OR h.detail LIKE 'Recruté par %')"

            args=[]

            if season is not None:

                where+=" AND h.season=?"; args.append(season)

            rows=conn.execute(f"""SELECT h.player_id,h.season,h.detail,h.created_at,p.first_name,p.last_name,p.position

                                 FROM player_history h LEFT JOIN player p ON p.id=h.player_id

                                 WHERE {where}

                                 ORDER BY h.created_at DESC, h.id DESC LIMIT 250""",args).fetchall()

            fee_map={}
            for t in conn.execute("SELECT label,amount,created_at FROM finance_tx WHERE club_id=1 AND category='Transfert'").fetchall():
                fee_map[(str(t["label"] or ""),str(t["created_at"] or ""))]=int(t["amount"] or 0)

            conn.close()

            # Recompose la liste des saisons disponibles en preservant la selection.

            if season_filter is not None:

                seasons=sorted({int(r["season"]) for r in rows if r["season"] is not None})

                wanted=season_filter.currentData()

                season_filter.blockSignals(True); season_filter.clear()

                season_filter.addItem("VOIR TOUT", None)

                for s in seasons: season_filter.addItem(f"SAISON {s}", s)

                pos=season_filter.findData(wanted)

                season_filter.setCurrentIndex(pos if pos>=0 else 0)

                season_filter.blockSignals(False)

            self.transfer_history_table.setUpdatesEnabled(False)
            self.transfer_history_table.setSortingEnabled(False)
            self.transfer_history_table.setRowCount(len(rows))

            default_h=36  # section par defaut posee a la creation (plus de setRowHeight par ligne a re-payer)

            self._history_player_ids=[]
            _arr=0; _dep=0; _spent=0; _recv=0

            for r,h in enumerate(rows):

                detail=str(h["detail"] or "")

                is_departure=detail.startswith("Départ") or detail.startswith("Recruté par")

                name=" ".join(x for x in (h["first_name"],h["last_name"]) if x) or f"Joueur #{h['player_id']}"

                labels=(f"Vente {name}",) if is_departure else (f"Transfert entrant {name}",f"Transfert {name}")

                amount=None
                _created=str(h["created_at"] or "")
                for tag in labels:
                    amt=fee_map.get((tag,_created))
                    if amt is not None:
                        amount=amt; break

                sens=(("➡  DÉPART") if is_departure else ("⬅  ARRIVÉE"))

                self._history_player_ids.append(int(h["player_id"]))
                if is_departure:
                    _dep+=1; _recv+=abs(int(amount or 0))
                else:
                    _arr+=1; _spent+=abs(int(amount or 0))

                for c,text in enumerate((fmt_date_fr(str(h["created_at"] or "")[:10]),f"Saison {h['season']}",sens,name,str(h["position"] or "—"),detail or ("—" if is_departure else "Arrivée"),("—" if amount is None else format_euros(abs(amount))))):

                    it=QTableWidgetItem(str(text)); it.setData(Qt.UserRole,int(h["player_id"]))

                    if c in (4,6): it.setTextAlignment(Qt.AlignRight|Qt.AlignVCenter)

                    self.transfer_history_table.setItem(r,c,it)



            self.transfer_history_table.setSortingEnabled(True)
            self.transfer_history_table.setUpdatesEnabled(True)
            if hasattr(self,"history_stats"):
                _net=_recv-_spent
                if rows:
                    _net_color="#7de0aa" if _net>=0 else "#ff9daa"
                    self.history_stats.setText(
                        f'<span style="color:#7de0aa;font-weight:900;">{_arr} ARRIVÉE(S)</span>'
                        f'<span style="color:#8ea3bd;">  •  </span>'
                        f'<span style="color:#e6c07a;font-weight:900;">{_dep} DÉPART(S)</span>'
                        f'<span style="color:#8ea3bd;">  •  </span>'
                        f'<span style="color:#c9b6ff;font-weight:900;">DÉPENSES {format_euros(_spent)}</span>'
                        f'<span style="color:#8ea3bd;">  •  </span>'
                        f'<span style="color:#a8d8c0;font-weight:900;">RECETTES {format_euros(_recv)}</span>'
                        f'<span style="color:#8ea3bd;">  •  </span>'
                        f'<span style="color:{_net_color};font-weight:900;">SOLDE {"+" if _net>=0 else "-"}{format_euros(abs(_net))}</span>')
                else:
                    self.history_stats.setText("AUCUN MOUVEMENT ENREGISTRÉ POUR CETTE PÉRIODE")
            self._history_built=True; self._transfer_history_dirty=False

        except Exception as exc:

            self._transfer_history_dirty=True
            self.log_error("refresh_transfer_history",exc)



    def open_history_row_card(self,row,column=None):

        it=self.transfer_history_table.item(row,3) if 0<=row<self.transfer_history_table.rowCount() else None

        if not it: return

        player_id=it.data(Qt.UserRole)

        try: conn=db(); prow=conn.execute("SELECT p.*,CASE WHEN p.is_free_agent=1 THEN 'Joueur libre' ELSE c.name||' · Ligue '||c.division END club_name,c.division club_division FROM player p JOIN club c ON c.id=p.club_id WHERE p.id=?",(player_id,)).fetchone(); conn.close()

        except Exception: prow=None

        if prow is not None: self.show_player_profile(prow)



    def refresh_shortlist_tab(self):

        if not hasattr(self,"shortlist_table"): return

        rows=self.shortlist_rows()

        self.shortlist_table.setSortingEnabled(False)

        if hasattr(self,"shortlist_empty"):
            self.shortlist_table.setVisible(bool(rows)); self.shortlist_empty.setVisible(not bool(rows))
        self.shortlist_table.setRowCount(len(rows))

        pricing_season,pricing_keys=self.market_pricing_context()

        for r,p in enumerate(rows):

            knowledge=int(p["scout_knowledge"] or 0)

            tier,tier_color=scout_tier_label(knowledge)

            if p["is_free_agent"]:

                value_text="SANS INDEMNITÉ"; value_sort=0.0

            else:

                low,high,exact=scout_value_band(p,knowledge,season=pricing_season,key_player=int(p["id"]) in pricing_keys)

                if p["transfer_listed"]:

                    try:

                        conn=db(); ask=player_ask_price(p,season=pricing_season,key_player=int(p["id"]) in pricing_keys); conn.close()

                    except Exception: ask=(low+high)//2

                    value_text=f"DEMANDÉ • {(ask//1000)} k€"; value_sort=float(ask)

                elif exact:

                    value_text=f"VALEUR • {(low//1000)} k€"; value_sort=float(low)

                else:

                    value_text=f"≈ {(low//1000)}-{high//1000} k€"; value_sort=float((low+high)/2)

            added_value=int(p["added_value"] or 0)

            delta=value_sort-added_value if added_value>0 else None

            delta_sort=delta if delta is not None else -999999.0

            vals=[f"{p['first_name']} {p['last_name']}",p["club_name"],p["position"],int(p["age"] or 0),

                  tier,value_text,("+" if delta is not None and delta>=0 else "")+f"{delta:,.0f} €".replace(","," ") if delta is not None else "—",

                  fmt_date_fr(str(p["added_date"] or ""))]

            sortv=[f"{p['first_name']} {p['last_name']}",p["club_name"],p["position"],int(p["age"] or 0),

                   100-knowledge,value_sort if not p["is_free_agent"] else -1.0,delta_sort,str(p["added_date"] or "")]

            for col,value in enumerate(vals):

                item=SortableTableWidgetItem(str(value))

                item.setData(Qt.UserRole+1,sortv[col])

                item.setTextAlignment(Qt.AlignVCenter|(Qt.AlignLeft if col in (0,1) else Qt.AlignCenter))

                if col==0:

                    item.setData(Qt.UserRole,int(p["id"]))

                    item.setIcon(QIcon(self.draw_player_avatar(p,40)))

                elif col==4: item.setForeground(QColor(tier_color))

                elif col==6 and delta is not None:

                    item.setForeground(QColor("#66e5a8") if delta>=0 else QColor("#ff8291"))

                elif col==5: item.setForeground(QColor("#b8caff"))

                self.shortlist_table.setItem(r,col,item)

            self.shortlist_table.setRowHeight(r,46)

        self.shortlist_table.setSortingEnabled(True)



    def open_shortlist_row(self,row,column):

        item=self.shortlist_table.item(row,0) if row>=0 else None

        player_id=item.data(Qt.UserRole) if item else None

        if not player_id: return

        c=db(); player=c.execute("SELECT p.*,c.name club_name,c.division club_division,COALESCE(sr.knowledge,0) scout_knowledge FROM player p JOIN club c ON c.id=p.club_id LEFT JOIN scout_report sr ON sr.player_id=p.id WHERE p.id=?",(player_id,)).fetchone(); c.close()

        if player:

            self.mercato_tabs.setCurrentIndex(1)

            self.show_player_profile(player)



    def scout_report_pending(self,player_id):

        conn=db(); rows=conn.execute("SELECT action_data FROM manager_message WHERE kind='scout_report' AND status='waiting'").fetchall(); conn.close()

        for row in rows:

            try:

                if int(json.loads(row["action_data"] or "{}").get("player_id",0))==int(player_id): return True

            except (ValueError,TypeError):

                continue

        return False



    def selected_market_player_id(self):

        if not hasattr(self,"market_table"): return None

        for item in self.market_table.selectedItems():

            candidate=self.market_table.item(item.row(),2)

            player_id=candidate.data(Qt.UserRole) if candidate else None

            if player_id: return int(player_id)

        row=self.market_table.currentRow()

        candidate=self.market_table.item(row,2) if row>=0 else None

        player_id=candidate.data(Qt.UserRole) if candidate else None

        if player_id: return int(player_id)

        # Le bouton peut prendre le focus et faire perdre currentRow selon le style Qt.

        player_id=getattr(self,"_selected_market_player_id",None)

        if player_id and any(int(p["id"])==int(player_id) for p in getattr(self,"_market_rows",[])):

            return int(player_id)

        return None



    # ------------------------- SELECTIONS CUMULATIVES ----------------------------

    def _table_selection_ids(self,table,col=0,role=None):

        """Ids (colonne col, UserRole) de toutes les lignes sélectionnées, uniques, ordonnées."""

        ids=[]

        if table is None or table.rowCount()==0: return ids

        if role is None: role=Qt.UserRole

        seen=set()

        for item in table.selectedItems():

            cell=table.item(item.row(),col)

            value=cell.data(role) if cell else None

            try: value=int(value or 0)

            except (TypeError,ValueError): value=0

            if value>0 and value not in seen:

                seen.add(value); ids.append(value)

        return ids



    def market_selection_player_ids(self):

        return self._table_selection_ids(self.market_table if hasattr(self,"market_table") else None,2)



    def shortlist_batch_add(self):

        ids=self.market_selection_player_ids()

        if not ids:

            self.show_game_message("Shortlist","Sélectionne au moins un joueur du marché (CTRL + clic pour en cumuler).","info"); return

        conn=db(); added=0

        for pid in ids:

            if self._shortlisted(pid): continue

            player=conn.execute("SELECT * FROM player WHERE id=?",(pid,)).fetchone()

            if player is None: continue

            report=conn.execute("SELECT knowledge FROM scout_report WHERE player_id=?",(pid,)).fetchone()

            conn.execute("INSERT OR REPLACE INTO shortlist(player_id,added_date,added_value,added_knowledge) VALUES(?,?,?,?)",

                         (pid,self._current_date(conn),int(player["market_value"] or 0),int(report["knowledge"] or 0) if report else 0))

            added+=1

        conn.commit(); conn.close()

        self.refresh_shortlist_tab(); self.refresh_market_only()

        self.show_game_message("Shortlist",f"{added} joueur(s) épinglé(s) dans ta shortlist." if added else "Les joueurs sélectionnés sont déjà épinglés.","info")



    def shortlist_batch_remove(self):

        if getattr(self,"mercato_tabs",None) is not None and self.mercato_tabs.currentIndex()==3:

            ids=self._table_selection_ids(self.shortlist_table if hasattr(self,"shortlist_table") else None,0)

        else:

            ids=self.market_selection_player_ids()

        if not ids:

            self.show_game_message("Shortlist","Sélectionne au moins un joueur à retirer (CTRL + clic pour en cumuler).","info"); return

        conn=db()

        for pid in ids:

            conn.execute("DELETE FROM shortlist WHERE player_id=?",(pid,))

        conn.commit(); conn.close()

        self.refresh_shortlist_tab(); self.refresh_market_only()

        self.show_game_message("Shortlist",f"{len(ids)} cible(s) retirée(s) de la shortlist.","info")



    def shortlist_batch_clear(self):

        rows=self.shortlist_rows()

        if not rows:

            self.show_game_message("Shortlist","La shortlist est déjà vide.","info"); return

        answer=self.show_game_message("Vider la shortlist",

            f"Désépingler les {len(rows)} cible(s) de la shortlist ?","warning",confirm=True,confirm_text="VIDER")

        if not answer: return

        conn=db(); conn.execute("DELETE FROM shortlist") ; conn.commit(); conn.close()

        self.refresh_shortlist_tab(); self.refresh_market_only()

        self.show_game_message("Shortlist",f"Shortlist vidée ({len(rows)} cible(s) retirée(s)).","info")



    def scouting_batch_consult(self):

        if not hasattr(self,"scouting_table"): return

        msg_ids=self._table_selection_ids(self.scouting_table,2)

        if not msg_ids:

            self.show_game_message("Scouting","Sélectionne au moins un rapport (CTRL + clic pour en cumuler).","info"); return

        conn=db(); consulted=0; active=0

        for mid in msg_ids:

            msg=conn.execute("SELECT kind,status FROM manager_message WHERE id=?",(mid,)).fetchone()

            if msg is None or str(msg["kind"])!="scout_report": continue

            if str(msg["status"])=="waiting": active+=1; continue

            if str(msg["status"])=="ready":

                conn.execute("UPDATE manager_message SET status='handled',is_read=1 WHERE id=?",(mid,))

                consulted+=1

        conn.commit(); conn.close()

        self.refresh_scouting_tracker()

        if consulted:

            self.show_game_message("Scouting",f"{consulted} rapport(s) consulté(s) : la liste active est nettoyée.","info")

        elif active:

            self.show_game_message("Scouting","Les missions en cours ne peuvent pas être archivées : attends le rapport final.","info")

        else:

            self.show_game_message("Scouting","Aucun rapport prêt dans la sélection (utilise le filtre CONSULTÉS pour l'historique).","info")



    def hire_scout_staff(self):

        current_level=int(getattr(self,"scout_level",0))

        if current_level>=5:

            self.show_game_message("Recrutement","Ton service de scouting est déjà au niveau maximal.","info"); return False

        costs=self.SCOUT_LEVEL_COSTS

        next_level=current_level+1; cost=costs[current_level]

        conn=db(); budget=conn.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"]

        if budget<cost:

            conn.close(); self.show_game_message("Budget insuffisant",f"Il faut {cost:,} € pour passer le service de scouting au niveau {next_level}.".replace(","," "),"warning"); return False

        if not self._staff_wage_ok(conn,"scout_staff_hired","service de scouting",next_level,hire=(current_level==0)):

            conn.close(); return False

        capacity_text=f"Tu pourras superviser jusqu'à {next_level} joueur(s) simultanément. Les rapports arrivent après quelques jours de carrière."

        action="Engager un recruteur" if current_level==0 else "Améliorer le service de scouting"

        if not self.show_game_message(action,f"{capacity_text}\nCoût : {cost:,} €.".replace(","," "),"warning",confirm=True,confirm_text="CONFIRMER"):

            conn.close(); return False

        conn.execute("UPDATE club SET budget=budget-? WHERE id=1",(cost,))

        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('scout_staff_hired','1')")

        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('scout_level',?)",(str(next_level),))

        label="Embauche du recruteur" if current_level==0 else f"Amélioration scouting niveau {next_level}"

        conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",(label,-cost,career_timestamp(conn),"Staff"))

        body=f"Le recruteur est {'recruté' if current_level==0 else 'formé'} : niveau {next_level}, jusqu'à {next_level} joueur(s) supervisé(s) en parallèle."

        add_news(conn,"Staff recruté / formé",body)

        today=self._current_date(conn); queue_manager_message(conn,"club_news","Recruteur recruté / formé",body,today,today,{},is_read=False)

        conn.commit(); conn.close(); self.refresh_all(); self.show_game_message("Service amélioré",f"Scouting niveau {next_level} : capacité de {next_level} joueur(s) en parallèle.","success"); return True



    def request_scout_report(self,player_id=None,force=True,effort="express"):

        if isinstance(player_id,bool): player_id=None

        if effort not in SCOUT_EFFORTS: effort="express"

        effort_meta=SCOUT_EFFORTS[effort]

        if not getattr(self,"scout_level",0):

            self.show_game_message("Aucun recruteur","Engage un recruteur dans le Centre de recrutement pour lancer une supervision.","warning"); return False

        if player_id is None:

            player_id=self.selected_market_player_id()

        if not player_id:

            self.show_game_message("Scouting","Sélectionne d'abord un joueur à superviser.","info"); return False

        if self.scout_report_pending(player_id):

            self.show_game_message("Rapport en cours","Ce joueur est déjà dans une mission de scouting.","info"); self.mercato_tabs.setCurrentIndex(2); return False

        conn=db(); player=conn.execute("SELECT first_name,last_name,market_value FROM player WHERE id=? AND club_id<>1",(player_id,)).fetchone()

        if not player:

            conn.close(); self.show_game_message("Scouting","Cette cible n'est plus disponible sur le marché.","warning"); return False

        active_count=conn.execute("SELECT COUNT(*) FROM manager_message WHERE kind='scout_report' AND status='waiting'").fetchone()[0]

        capacity=int(self.scout_level)

        # La supervision en tache de fond ne bloque JAMAIS une demande : les missions

        # au-dela des slots simultanes partent quand meme, mais le recruteur les

        # traite en serie -> +2 jours de delai par mission en attente de slot.

        queue_delay=2*max(0,active_count-capacity+1)

        cost=int(effort_meta["cost"] or 0)

        if cost>0:

            budget=conn.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"]

            if int(budget)<cost:

                conn.close(); self.show_game_message("Budget insuffisant",f"Cette mission {effort_meta['label'].lower()} coûte {cost:,} €.".replace(","," "),"warning"); return False

            conn.execute("UPDATE club SET budget=budget-? WHERE id=1",(cost,))

            conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",(f"Déplacement scouting • {effort_meta['label'].lower()}",-cost,career_timestamp(conn),"Scouting"))

        report=conn.execute("SELECT knowledge,reports FROM scout_report WHERE player_id=?",(player_id,)).fetchone()

        knowledge=int(report["knowledge"]) if report else 0

        reports=int(report["reports"]) if report else 0

        if knowledge>=100:

            conn.close(); self.show_game_message("Rapport complet","Le staff possède déjà une évaluation complète de ce joueur.","info"); return False

        gain=scout_gain_for(player_id,reports,self.scout_level,effort)

        accuracy=scout_accuracy_for(player_id,reports,self.scout_level,effort)

        current=self._current_date(conn); due=(parse_iso(current)+timedelta(days=effort_meta["days"]+queue_delay)).isoformat()

        name=f"{player['first_name']} {player['last_name']}"

        queue_txt=f" (+{queue_delay} jour(s) de file d'attente du recruteur)" if queue_delay else ""

        # Confirmation lisible AVANT lancement : effort, duree, cout, file, echeance.

        confirm_body=(f"{name}\n"

                      f"Mission {effort_meta['label'].lower()} • {effort_meta['days']} jour(s){queue_txt} • fiabilité attendue {int(round(accuracy*100))} %\n"

                      + (f"Coût : {format_euros(cost)}\n" if cost else "Mission gratuite\n")

                      + f"Rapport attendu le {fmt_date_fr(due)}.\n"

                        "La cible sera automatiquement épinglée dans ta shortlist et suivie par le recruteur.")

        if not self.show_game_message("Lancer la supervision",confirm_body,"info",confirm=True,confirm_text=f"LANCER • {effort_meta['label']}"):

            conn.close(); return False

        body=(f"Mission {effort_meta['label'].lower()} ({effort_meta['days']} jour(s), fiabilité attendue {int(round(accuracy*100))} %){queue_txt}. "

              f"Le recruteur observe {name}. Rapport attendu le {fmt_date_fr(due)}. Missions en cours : {active_count+1} (slots simultanés : {capacity}).")

        queue_manager_message(conn,"scout_report","Mission de scouting lancée",body,current,due,

                              {"player_id":player_id,"previous_knowledge":knowledge,"reports":reports,

                               "effort":effort,"scout_level":int(self.scout_level),"gain":gain,"accuracy":accuracy},is_read=True)

        # Toute cible supervisee est automatiquement epinglee dans la shortlist.

        conn.execute("INSERT OR IGNORE INTO shortlist(player_id,added_date,added_value,added_knowledge) VALUES(?,?,?,?)",

                     (player_id,current,int(player["market_value"] or 0),(int(report["knowledge"]) if report and "knowledge" in report.keys() else 0)))

        add_news(conn,"Scouting",f"Le staff commence l'observation ({effort_meta['label'].lower()}) de {name} ; cible épinglée à la shortlist.")

        conn.commit(); conn.close(); self.refresh_all()

        self.show_game_message("Mission lancée",

                               f"Supervision {effort_meta['label'].lower()} de {name} : rapport attendu le {fmt_date_fr(due)}.\n"

                               f"Cible épinglée dans ta shortlist — l'onglet ★ SHORTLIST du mercato suit sa valeur et sa connaissance.",

                               "success")

        return True



    def market_pricing_context(self,conn=None):

        """Contexte de prix du mercato : (saison courante, ids des joueurs cles)."""

        opened=conn is None

        if opened:

            conn=db()

        try:

            row=conn.execute("SELECT season FROM club WHERE id=1").fetchone()

            season=int(row["season"] or 1) if row else 1

            return season,compute_key_player_ids(conn)

        except sqlite3.Error:

            return 1,set()

        finally:

            if opened:

                conn.close()



    def update_market_compare(self, *_):

        if self._refreshing:

            return

        if not hasattr(self, "market_table"):

            return

        try:

            pid=self.selected_market_player_id()

            if not pid:

                self._selected_market_player_id=None

                self.market_compare.setText("Sélectionnez un joueur dans la liste pour lancer un comparatif.")

                return

            self._selected_market_player_id=int(pid)

            conn = db()

            target = conn.execute("SELECT p.*,CASE WHEN p.is_free_agent=1 THEN 'Joueur libre' ELSE c.name||' · Ligue '||c.division END club_name,c.division club_division,COALESCE(sr.knowledge,0) scout_knowledge,COALESCE(sr.reports,0) scout_reports FROM player p JOIN club c ON c.id=p.club_id LEFT JOIN scout_report sr ON sr.player_id=p.id WHERE p.id=?", (pid,)).fetchone()

            best_own = conn.execute("SELECT * FROM player WHERE club_id=1 ORDER BY market_value DESC, technique DESC LIMIT 1").fetchone()

            signing_club = conn.execute("SELECT division,reputation,season FROM club WHERE id=1").fetchone()

            pricing_season, pricing_keys = self.market_pricing_context(conn)

            ask_price=player_ask_price(target,season=pricing_season,key_player=int(target["id"]) in pricing_keys) if target else 0

            conn.close()

            if not best_own or not target:

                return

            self.market_selected_name.setText(f"{target['first_name']} {target['last_name']}")

            self.market_selected_avatar.setPixmap(self.draw_player_avatar(target,54))

            if hasattr(self, "precontract_btn"):
                try:
                    _can_pre=(int(target["club_id"] or 0)!=1
                              and not int(target["is_free_agent"] or 0)
                              and not int(target["loan_from_club"] or 0)
                              and int(target["contract_years"] or 0)<=1
                              and not int(target["precontract_club"] or 0))
                except Exception:
                    _can_pre=False
                self.precontract_btn.setVisible(bool(_can_pre))

            if hasattr(self, "offer_amount"):

                if target["is_free_agent"]:

                    self.offer_type_label.setText("SALAIRE PROPOSÉ / MOIS")

                    self.offer_amount.setSuffix(" € / mois")

                    self.offer_amount.setValue(free_agent_ask_salary(target, signing_club)[0])

                    self.offer_years_frame.setVisible(True)

                    self.transfer_salary_frame.setVisible(False)

                    self.offer_btn.setText("PROPOSER LE CONTRAT")

                else:

                    self.offer_type_label.setText(f"PRIX DEMANDÉ • {format_euros(ask_price)}" if ask_price>0 else "OFFRE DE TRANSFERT")

                    self.offer_amount.setSuffix(" €")

                    self.offer_amount.setValue(float(max(500,ask_price)) if ask_price>0 else float(max(500,int(target["market_value"]))))

                    self.offer_years_frame.setVisible(False)

                    self.transfer_salary_spin.setValue(max(500,int(target["salary"]*1.05)))

                    self.transfer_salary_frame.setVisible(True)

                    self.offer_btn.setText("ENVOYER L'OFFRE")

            self.market_compare.setHtml(self.market_compare_html(target, best_own))

            knowledge=int(target["scout_knowledge"] or 0)

            pending=self.scout_report_pending(pid)

            conn=db(); active_count=conn.execute("SELECT COUNT(*) FROM manager_message WHERE kind='scout_report' AND status='waiting'").fetchone()[0]; conn.close()

            capacity=int(getattr(self,"scout_level",0))

            queue_delay=2*max(0,active_count-capacity+1) if capacity else 0

            mission_ok=self.scout_staff_hired and knowledge<100 and not pending

            self.scout_report_btn.setVisible(self.scout_staff_hired)

            self.scout_report_btn.setEnabled(mission_ok)

            self.scout_report_btn.setText("SUPERVISION EN COURS" if pending else "RAPPORT COMPLET" if knowledge>=100 else (f"FILE D'ATTENTE • +{queue_delay} J" if queue_delay else "EXPRESS • 2 J • 1 200 €"))

            self.scout_report_btn.setToolTip("La supervision de fond ne bloque jamais une demande : au-delà des slots simultanés, la mission part en file et prend +2 j." if queue_delay else "Rapport rapide, gain et fiabilité réduits.")

            if hasattr(self,"scout_deep_btn"):

                self.scout_deep_btn.setVisible(self.scout_staff_hired)

                self.scout_deep_btn.setEnabled(mission_ok)

                self.scout_deep_btn.setText("MISSION EN COURS" if pending else (f"FILE D'ATTENTE • +{queue_delay} J" if queue_delay else "APPROFONDIE • 6 J • 2 400 €"))

            if hasattr(self,"shortlist_btn"):

                self.shortlist_btn.setEnabled(pid is not None)

                shortlisted=self._shortlisted(int(pid)) if pid else False

                self.shortlist_btn.setText("★ RETIRER SHORTLIST" if shortlisted else "★ SHORTLIST")

                self.shortlist_btn.setToolTip("Retirer cette cible de ta shortlist." if shortlisted else "Épingler ce joueur : suivi de sa valeur dans l'onglet Shortlist du mercato.")

        except Exception as e:

            self.log_error("update_market_compare", e)



    def open_selected_market_player_card(self):

        player_id=self.selected_market_player_id()

        player=next((p for p in getattr(self,"_market_rows",[]) if p["id"]==player_id),None)

