    def propose_market_offer(self):

        player_id=self.selected_market_player_id()

        if not player_id:

            self.show_game_message("Mercato","Sélectionne d'abord un joueur cible.","info"); return

        years=self.offer_years_spin.value() if hasattr(self,"offer_years_spin") else 3

        player_salary=self.transfer_salary_spin.value() if self.transfer_salary_frame.isVisible() else None

        self.submit_market_offer(player_id,self.offer_amount.value(),years,player_salary)



    def transfer_window_state(self,conn=None):
        """Fenêtres de transfert : été (1 juil. → 15 sept.) et hiver (1 → 31 janv.)."""
        try:
            today=parse_iso(self._current_date(conn)) if conn is not None else parse_iso(self._career_day())
        except Exception:
            today=date.today()
        y=today.year
        if date(y,7,1)<=today<=date(y,9,15):
            return {"open":True,"label":"MERCATO D'ÉTÉ","closes":date(y,9,15),"reopens":None}
        if date(y,1,1)<=today<=date(y,1,31):
            return {"open":True,"label":"MERCATO D'HIVER","closes":date(y,1,31),"reopens":None}
        candidates=[date(y,7,1),date(y+1,1,1)]
        reopens=min([d for d in candidates if d>today] or [date(y+1,7,1)])
        return {"open":False,"label":"MERCATO FERMÉ","closes":None,"reopens":reopens}

    def transfer_effective_date(self,conn,days=2):
        """Date du changement de club : immédiate dans la fenêtre, sinon ouverture."""
        win=self.transfer_window_state(conn)
        try: today=parse_iso(self._current_date(conn))
        except Exception: today=date.today()
        if win["open"]:
            return today+timedelta(days=max(0,int(days)))
        return win["reopens"]

    def submit_market_offer(self,player_id,amount,years=3,player_salary=None):

        try:

            conn=db()

            # Embargo financier : trésorerie dans le rouge, le board bloque

            # toute nouvelle dépense (banqueroute, chaîne process_board_financial_watch).

            _b=conn.execute("SELECT budget FROM club WHERE id=1").fetchone()

            if _b and int(_b["budget"] or 0)<0:

                conn.close(); self.market_offer_info.setText("Embargo financier : le board bloque toute dépense tant que la trésorerie est négative.")

                self.show_game_message("Embargo financier","Le board refuse toute dépense tant que la trésorerie est négative. Vends des joueurs ou attend le retour au vert.","warning"); return False

            player=conn.execute("SELECT p.*,CASE WHEN p.is_free_agent=1 THEN 'Joueur libre' ELSE c.name||' · Ligue '||c.division END club_name,c.division club_division FROM player p JOIN club c ON c.id=p.club_id WHERE p.id=?",(player_id,)).fetchone()

            if player and not int(player["is_free_agent"] or 0):
                _freeze=conn.execute("SELECT value FROM meta WHERE key='board_transfer_freeze'").fetchone()
                if _freeze and str(_freeze["value"] or "") == "1":
                    conn.close()
                    _msg="Le board gèle les transferts tant que la confiance ne remonte pas (résultats, finances, jeunes). Les signatures de joueurs libres restent possibles."
                    try: self.market_offer_info.setText(_msg)
                    except Exception: pass
                    self.show_game_message("Transferts gelés",_msg,"warning"); return False

            if not player or player["club_id"]==1:

                conn.close(); self.show_game_message("Mercato","Cette cible n'est plus disponible sur le marché.","warning"); return False

            if int(player["loan_from_club"] or 0):

                conn.close(); self.show_game_message("Joueur prêté","Ce joueur est sous contrat ailleurs et prêté : attends son retour avant de négocier.","info"); return False

            from wage_budget import can_add_player

            _proposed=int(player_salary or player["salary"] or 0)

            _ok,_wst,_proj=can_add_player(self,conn,_proposed,0)

            if not _ok:

                conn.close(); self.show_game_message("Plafond salarial",
                    f"Cette recrue porterait la masse salariale à {_proj:,} € pour un plafond de {_wst['cap']:,} €/mois. "
                    f"Vends un joueur ou propose un salaire plus bas.".replace(","," "),"warning"); return False

            current_date=self._current_date(conn)

            active=conn.execute("SELECT action_data FROM manager_message WHERE kind IN ('market_offer','free_agent_contract','transfer_arrival') AND status IN ('waiting','ready')").fetchall()

            if any(json.loads(row["action_data"] or "{}").get("player_id")==player_id for row in active):

                conn.close(); self.show_game_message("Négociation en cours","Une proposition est déjà en attente pour ce joueur. Suis son dossier dans la messagerie.","info"); self.show_page(6); return False

            bid=max(250,int(amount))

            due=(parse_iso(current_date)+timedelta(days=2)).isoformat()

            player_name=f"{player['first_name']} {player['last_name']}"

            if player["is_free_agent"]:

                payload={"player_id":player_id,"player_name":player_name,"offer_salary":bid,"offer_years":max(1,min(5,int(years)))}

                body=f"Proposition de contrat envoyée à {player_name} : {bid:,} € / mois sur {payload['offer_years']} an(s). Réponse attendue le {fmt_date_fr(due)}.".replace(","," ")

                queue_manager_message(conn,"free_agent_contract","Offre de contrat à un joueur libre",body,current_date,due,payload,is_read=True)

                add_news(conn,"Recrutement","Une offre de contrat à un joueur libre attend une réponse dans la messagerie.")

            else:

                budget=conn.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"]

                if bid>budget:

                    conn.close(); self.market_offer_info.setText("Budget insuffisant pour formuler une offre crédible."); self.show_game_message("Budget insuffisant","L'offre dépasse la trésorerie disponible.","warning"); return False

                if player["transfer_listed"]:

                    pricing_season, pricing_keys = self.market_pricing_context(conn)

                    ask=player_ask_price(player,season=pricing_season,key_player=int(player["id"]) in pricing_keys)

                    ask=max(int(ask),int(player["market_value"])) if ask>0 else int(player["market_value"]*random.uniform(0.85,1.10))

                else:

                    pricing_season, pricing_keys = self.market_pricing_context(conn)

                    ask=player_ask_price(player,season=pricing_season,key_player=int(player["id"]) in pricing_keys)

                    ask=max(int(ask),int(player["market_value"]*1.15)) if ask>0 else int(player["market_value"]*random.uniform(1.15,1.45))

                offer_salary=round_money(max(500,int(player_salary if player_salary is not None else player["salary"]*1.05)))

                payload={"player_id":player_id,"player_name":player_name,"club_id":player["club_id"],"club_name":player["club_name"],"bid":bid,"seller_ask":ask,"offer_salary":offer_salary,"offer_years":max(1,min(5,int(years or 3))),"round":0}

                difficulty=" • joueur déjà sur le marché : négociation facilitée" if player["transfer_listed"] else " • joueur sous contrat : indemnité renforcée"

                body=f"Offre de {bid:,} € + {offer_salary:,} € / mois transmise à {player['club_name']} pour {player_name}{difficulty}. Réponse attendue le {fmt_date_fr(due)}.".replace(","," ")

                queue_manager_message(conn,"market_offer","Offre de transfert envoyée",body,current_date,due,payload,is_read=True)

                add_news(conn,"Mercato","Une offre de recrutement attend une réponse dans la messagerie.")

            conn.commit(); conn.close()

            self.market_offer_info.setText(body); self.refresh_all(); self.show_page(7)

            return True

        except Exception as exc:

            self.log_error("submit_market_offer",exc); self.show_game_message("Mercato","Erreur lors de la création du dossier de négociation.","error"); return False



    def open_market_columns(self):
        if not hasattr(self,"market_table"): return
        MarketColumnsDialog(self).exec()

    def apply_market_columns(self,hidden=None,widths=None,save=True):
        """Applique les colonnes choisies et leurs largeurs au tableau du marché."""
        table=getattr(self,"market_table",None)
        if table is None: return
        header=table.horizontalHeader()
        if hidden is not None:
            hidden=set(hidden or []); hidden.discard("name")
            for index,(key,_label,_default) in enumerate(MARKET_COLUMN_SPECS):
                table.setColumnHidden(index,key in hidden)
        if widths:
            for index,(key,_label,default) in enumerate(MARKET_COLUMN_SPECS):
                if key=="name": continue
                try: value=int(widths.get(key,default))
                except (TypeError,ValueError): value=default
                header.resizeSection(index,max(32,min(600,value)))
        if save: self._save_market_header_state()

    def _restore_market_header_state(self):
        state=(getattr(self,"game_options",{}) or {}).get("market_header_state")
        if not state: return
        try:
            self.market_table.horizontalHeader().restoreState(QByteArray.fromHex(str(state).encode("ascii")))
        except Exception:
            pass

    def _schedule_market_header_save(self):
        if not getattr(self,"_market_header_ready",False): return
        if not getattr(self,"_market_user_resize",False): return
        timer=getattr(self,"_market_header_timer",None)
        if timer is None:
            timer=QTimer(self); timer.setSingleShot(True)
            timer.timeout.connect(self._save_market_header_state)
            self._market_header_timer=timer
        timer.start(500)

    def _save_market_header_state(self):
        if not getattr(self,"_market_header_ready",False): return
        table=getattr(self,"market_table",None)
        if table is None: return
        try:
            state=bytes(table.horizontalHeader().saveState().toHex()).decode("ascii")
            self.game_options["market_header_state"]=state
            save_game_options(self.game_options)
        except Exception as exc:
            self.log_error("market_header_save",exc)
        finally:
            self._market_user_resize=False

    def _toggle_market_detail(self):
        try:
            panel=getattr(self,"market_side_panel",None)
            split=getattr(self,"market_split",None)
            if panel is None: return
            show=not panel.isVisible()
            panel.setVisible(show)
            if split is not None:
                if show: split.setSizes([700,320])
                else: split.setSizes([1,0])
            if hasattr(self,"market_detail_btn"):
                self.market_detail_btn.setText("MASQUER LE DÉTAIL" if show else "DÉTAIL / OFFRE")
        except Exception as exc:
            self.log_error("market_detail_toggle",exc)

    def _market_search_changed(self):

        """Débounce la recherche mercato : ne rafraîchit le marché qu'après une pause de frappe."""

        self.market_page = 0

        if self._market_refresh_timer is not None:

            self._market_refresh_timer.stop()

        self._market_refresh_timer = QTimer(self)

        self._market_refresh_timer.setSingleShot(True)

        self._market_refresh_timer.timeout.connect(lambda: self.refresh_market_only(reset_page=False))

        self._market_refresh_timer.start(300)



    def market_page_change(self, delta):

        self.market_page = max(0, self.market_page + delta)

        self.refresh_market_only(reset_page=False)

    def _market_header_clicked(self, column):

        """Clic sur un en-tête : trie TOUT le marché puis revient page 1."""

        if column is None or column < 0:

            return

        previous = getattr(self, "_market_sort_column", -1)

        if previous == column:

            self._market_sort_order = (Qt.DescendingOrder

                                       if getattr(self, "_market_sort_order", Qt.AscendingOrder) == Qt.AscendingOrder

                                       else Qt.AscendingOrder)

        else:

            self._market_sort_order = Qt.AscendingOrder

        self._market_sort_column = column

        try:

            header = self.market_table.horizontalHeader()

            header.setSortIndicatorShown(True)

            header.setSortIndicator(column, self._market_sort_order)

        except Exception as exc:

            self.log_error("market_sort_indicator", exc)

        self.refresh_market_only(reset_page=True)

    def _market_sort_key(self, p, column, season, pricing_keys):

        """Clé de tri d'un joueur pour une colonne (0=valeur, 1=texte, 2=inconnu)."""

        knowledge = int(p["scout_knowledge"] or 0)

        accuracy = float(p["scout_accuracy"] if "scout_accuracy" in p.keys() and p["scout_accuracy"] is not None else 0.6)

        reveal_stats = bool(getattr(self, "scout_staff_hired", False) and knowledge >= 75)

        reveal_potential = bool(getattr(self, "scout_staff_hired", False) and knowledge >= 100)

        free = bool(p["is_free_agent"])

        if column == 0:

            return 0, (0 if free else 1 if not reveal_stats else 2 if int(p["injury_days"] or 0) > 0 else 3)

        if column == 1:

            shirt = int(p["shirt_number"] or 0)

            return 0, float(shirt if shirt and not free else -1)

        if column == 2:

            return 1, f"{p['first_name']} {p['last_name']}".casefold()

        if column == 3:

            return 1, str(p["club_name"] or "").casefold()

        if column == 4:

            return 1, str(p["position"] or "").casefold()

        if column == 5:

            return 0, float(int(p["age"] or 0))

        if column == 6:

            return 1, str(p["nationality"] or "N/A").upper()[:3].casefold()

        if column == 7:

            if knowledge >= 75:

                return 0, float(player_level_from_row(p))

            if knowledge >= 25:

                txt = str(scout_level_text(p, knowledge, accuracy)).split("-")[0].replace("≈", "").strip()

                try:

                    return 0, float(txt)

                except (TypeError, ValueError):

                    return 2, 0.0

            return 2, 0.0

        if column == 8:

            return (0, float(player_potential_from_row(p))) if reveal_potential else (2, 0.0)

        if column == 9:

            return (0, float(rating20(p["condition"]))) if reveal_stats else (2, 0.0)

        if column == 10:

            return 0, float(int(p["contract_years"] or 0))

        if column == 11:

            if free:

                return 0, 0.0

            low, high, exact = scout_value_band(p, knowledge, season=season, key_player=int(p["id"]) in pricing_keys)

            if p["transfer_listed"] or exact:

                return 0, float(low)

            return 0, float((low + high) // 2)

        if column == 12:

            return 0, float(int(p["club_division"] or 6) if not free else 99)

        if column == 13:

            return (0, float(int(p["salary"] or 0))) if knowledge >= 60 and not free else (2, 0.0)

        if column == 14:

            return 0, float(knowledge)

        if column == 15:

            return (0, float(rating20(p["morale"]))) if reveal_stats else (2, 0.0)

        return 2, 0.0

    def _market_sorted_rows(self, rows, column, order, season, pricing_keys):

        """Trie toutes les lignes filtrées (valeurs connues d'abord, inconnues à la fin)."""

        if not rows or column is None or column < 0:

            return rows

        descending = (order == Qt.DescendingOrder)

        numeric, text, unknown = [], [], []

        for p in rows:

            try:

                group, value = self._market_sort_key(p, column, season, pricing_keys)

            except Exception:

                group, value = 2, 0.0

            if group == 0:

                numeric.append((value, p))

            elif group == 1:

                text.append((value, p))

            else:

                unknown.append(p)

        numeric.sort(key=lambda item: item[0], reverse=descending)

        text.sort(key=lambda item: item[0], reverse=descending)

        return [p for _, p in numeric] + [p for _, p in text] + unknown



    def refresh_market_only(self, reset_page=True):

        """Recharge uniquement le tableau du mercato (recherche + filtre de poste).



        N'impacte pas le reste de l'interface (roster, calendrier, finances…), contrairement

        à refresh_all(). Appelé par le champ de recherche, le filtre de poste et la pagination.

        """

        if not hasattr(self, "market_table") or self._refreshing:

            return

        if reset_page:

            self.market_page = 0

        self.log_trace("refresh_market_only start")

        try:

            conn = db()

            club = conn.execute("SELECT * FROM club WHERE id=1").fetchone()

            scout_staff_meta = conn.execute("SELECT value FROM meta WHERE key='scout_staff_hired'").fetchone()

            scout_level_meta = conn.execute("SELECT value FROM meta WHERE key='scout_level'").fetchone()

            self.scout_level = int(scout_level_meta["value"] or 0) if scout_level_meta else int(bool(scout_staff_meta and scout_staff_meta["value"] == "1"))

            if self.scout_level == 0 and scout_staff_meta and scout_staff_meta["value"] == "1": self.scout_level = 1

            self.scout_staff_hired = self.scout_level > 0

            market_rows = conn.execute("""SELECT p.*,CASE WHEN p.is_free_agent=1 THEN 'Joueur libre' ELSE c.name||' · Ligue '||c.division END club_name,c.division club_division,

                                                  COALESCE(sr.knowledge,0) scout_knowledge,COALESCE(sr.reports,0) scout_reports,COALESCE(sr.accuracy,0.6) scout_accuracy

                                          FROM player p

                                          JOIN club c ON c.id=p.club_id

                                          LEFT JOIN scout_report sr ON sr.player_id=p.id

                                          WHERE p.club_id<>1 AND COALESCE(p.retired,0)=0

                                          ORDER BY p.is_free_agent DESC, p.transfer_listed DESC, p.market_value DESC""").fetchall()

            best_own = conn.execute("SELECT * FROM player WHERE club_id=1 ORDER BY market_value DESC, technique DESC LIMIT 1").fetchone()

            _win=self.transfer_window_state(conn)
            if hasattr(self,"market_window_label"):
                if _win["open"]:
                    self.market_window_label.setText(f"{_win['label']}  •  ferme le {fmt_date_fr(_win['closes'].isoformat())}")
                    self.market_window_label.setStyleSheet("font-size:8pt;font-weight:900;color:#7de0aa;")
                else:
                    self.market_window_label.setText(f"MERCATO FERMÉ  •  accords possibles  •  changements le {fmt_date_fr(_win['reopens'].isoformat())}")
                    self.market_window_label.setStyleSheet("font-size:8pt;font-weight:900;color:#d8bc8a;")

            conn.close()

            budget_value=int(club["budget"] or 0)

            if budget_value<0:

                self.market_budget_label.setText(f"DÉFICIT  {abs(budget_value):,} €  •  vends ou réduis les charges".replace(","," "))

                self.market_budget_label.setStyleSheet("font-size:11pt;font-weight:900;color:#ff8d8d;")

            else:

                self.market_budget_label.setText(f"BUDGET DISPONIBLE  {budget_value:,} €".replace(","," "))

                self.market_budget_label.setStyleSheet("font-size:11pt;font-weight:900;color:#9ce6bf;")

        except Exception as exc:

            self.log_error("refresh_market_only_db", exc)

            return

        prev_selected_id = None

        row_cur = self.market_table.currentRow()

        if row_cur >= 0 and self.market_table.item(row_cur, 2):

            prev_selected_id = self.market_table.item(row_cur, 2).data(Qt.UserRole)

        search = self.mercato_search.text().strip().lower() if hasattr(self, "mercato_search") else ""

        pos = self.mercato_pos.currentText() if hasattr(self, "mercato_pos") else "Tous"

        status_filter=self.mercato_status.currentText() if hasattr(self,"mercato_status") else "Tous les profils"

        age_filter=self.mercato_age.currentText() if hasattr(self,"mercato_age") else "Tous les âges"

        attr_filter=self.mercato_attr.currentText() if hasattr(self,"mercato_attr") else "Atout recherché : aucun"

        stat_filter=self.mercato_stat.currentText() if hasattr(self,"mercato_stat") else "Aucun filtre"

        budget_filter=self.mercato_budget.currentText() if hasattr(self,"mercato_budget") else "Tous les prix"

        shortlist_ids=set()

        if status_filter=="Ma shortlist":

            try:

                c=db(); shortlist_ids={int(r["player_id"]) for r in c.execute("SELECT player_id FROM shortlist").fetchall()}; c.close()

            except sqlite3.Error: shortlist_ids=set()

        attr_rules=[("Finition ≥ 14","finishing",14),("Technique ≥ 14","technique",14),("Passe ≥ 14","passing",14),

                    ("Dribble ≥ 14","dribble",14),("Défense ≥ 13","defense",13),("Gardien ≥ 13","goalkeeper",13),

                    ("Explosivité ≥ 14","speed",14),("Endurance ≥ 13","stamina",13)]

        attr_rule=None

        if attr_filter!="Atout recherché : aucun":

            wanted=attr_filter.rsplit(" ≥ ",1)[0]

            attr_rule=next(((key,threshold) for label,key,threshold in attr_rules if label.startswith(wanted)),None)

        pricing_season,pricing_keys=self.market_pricing_context()

        filtered = []

        for m in market_rows:

            name = f"{m['first_name']} {m['last_name']}"

            if search and search not in name.lower() and search not in m["club_name"].lower():

                continue

            if pos != "Tous" and m["position"] != pos:

                continue

            if status_filter=="Joueurs libres" and not m["is_free_agent"]: continue

            if status_filter=="Sur le marché" and not (m["transfer_listed"] and not m["is_free_agent"]): continue

            if status_filter=="Sous contrat" and (m["is_free_agent"] or m["transfer_listed"]): continue

            if status_filter=="Joueurs observés" and int(m["scout_knowledge"] or 0)<=0: continue

            if status_filter=="Ma shortlist" and int(m["id"]) not in shortlist_ids: continue

            age=int(m["age"] or 0)

            if age_filter=="-21 ans" and age>=21: continue

            if age_filter=="21-28 ans" and not 21<=age<=28: continue

            if age_filter=="29+ ans" and age<29: continue

            if attr_rule:

                key,threshold=attr_rule

                acc=float(m["scout_accuracy"] or 0.6) if "scout_accuracy" in m.keys() else 0.6

                if scout_attr_low_band(m,key,int(m["scout_knowledge"] or 0),acc)<threshold: continue

            if stat_filter!="Aucun filtre":

                stats_ok=( (stat_filter=="Buteurs 5+" and int(m["season_goals"] or 0)>=5)

                           or (stat_filter=="Gardiens 20+ arrêts" and int(m["season_saves"] or 0)>=20) )

                if not stats_ok: continue

            if budget_filter=="Dans mon budget" and not m["is_free_agent"]:

                if m["transfer_listed"]:

                    try:

                        conn_b=db(); ask_b=player_ask_price(m,season=pricing_season,key_player=False); conn_b.close()

                    except Exception: ask_b=int(m["market_value"])

                    if int(ask_b)>int(club["budget"]): continue

                else:

                    low_b,high_b,exact_b=scout_value_band(m,int(m["scout_knowledge"] or 0),season=pricing_season)

                    if int(low_b)>int(club["budget"]): continue

            filtered.append(m)

        sort_column = getattr(self, "_market_sort_column", -1)

        sort_order = getattr(self, "_market_sort_order", Qt.AscendingOrder)

        if sort_column is not None and sort_column >= 0:

            filtered = self._market_sorted_rows(filtered, sort_column, sort_order, pricing_season, pricing_keys)

        self._market_rows = filtered

        total = len(filtered)

        total_pages = max(1,(total+self.market_page_size-1)//self.market_page_size)

        if self.market_page >= total_pages: self.market_page = max(0,total_pages-1)

        start_page = self.market_page*self.market_page_size

        page_rows = filtered[start_page:start_page+self.market_page_size]

        self.market_candidate_count.setText(f"{total} CANDIDATS")

        self.market_page_label.setText(f"PAGE {self.market_page+1} / {total_pages}")

        self.market_prev_btn.setEnabled(self.market_page>0)

        self.market_next_btn.setEnabled(self.market_page<total_pages-1)

        self.market_table.setUpdatesEnabled(False)

        self.market_table.blockSignals(True)

        self.market_table.clearSelection()

        self.market_table.setRowCount(len(page_rows))

        new_selected_row = -1

        pricing_season, pricing_keys = self.market_pricing_context()

        for r, p in enumerate(page_rows):

            knowledge = int(p["scout_knowledge"] or 0)

            accuracy=float(p["scout_accuracy"] if "scout_accuracy" in p.keys() and p["scout_accuracy"] is not None else 0.6)

            reveal_stats = bool(self.scout_staff_hired and knowledge >= 75)

            reveal_potential = bool(self.scout_staff_hired and knowledge >= 100)

            _inj, _unit = self._player_injury_left(p)

            status = ("LIBRE" if p["is_free_agent"] else "SUR LE MARCHÉ" if p["transfer_listed"]

                      else "OBSERVÉ" if knowledge >= 25 else "APERÇU" if knowledge >= 1 else "NON SCOUTÉ")

            if _inj>0 and knowledge >= 25:

                status=f"BLESSÉ {_inj}" if reveal_stats else "OBSERVÉ"

            condition = f"{rating20(p['condition'])}/20" if reveal_stats else "—"

            if p["is_free_agent"]:

                value_label = "SANS INDEMNITÉ"; value=0

            else:

                low,high,exact=scout_value_band(p,knowledge,season=pricing_season,key_player=int(p["id"]) in pricing_keys)

                value=(low+high)//2

                _mfmt = (lambda x: f"{x / 1_000_000:.1f} M€" if x >= 1_000_000 else f"{x // 1000} k€")

                if p["transfer_listed"]:

                    value=high=low

                    value_label = "DEMANDÉ • " + _mfmt(low)

                elif exact:

                    value_label = "VALEUR • " + _mfmt(low)

                else:

                    value_label = "VALEUR ~ " + _mfmt(low) + "-" + _mfmt(high).replace("k€","k€").replace(" M€","M")

            contract_label = "LIBRE" if p["is_free_agent"] else ("LISTÉ" if p["transfer_listed"] else f"{p['contract_years']} an(s)" if scout_contract_known(knowledge) else f"≈ {max(1,int(p['contract_years'])-1)}-{int(p['contract_years'])+1} an(s)")

            shirt = int(p["shirt_number"] or 0)

            lvl = player_level_from_row(p)

            potential = player_potential_from_row(p)

            level_text = (f"{stars5(lvl)} {lvl}/20" if reveal_stats else scout_level_text(p,knowledge,accuracy))

            potential_text = (f"{stars5(potential)} {potential}/20" if reveal_potential else scout_potential_text(p,knowledge,accuracy))

            sort_values = {1: shirt if shirt and not p["is_free_agent"] else -1, 5: int(p["age"]),

                           7: (lvl if knowledge>=75 else int(str(scout_level_text(p,knowledge,accuracy)).split("-")[0].replace("≈","")) if knowledge>=25 else None),

                           8: (potential if reveal_potential else None),

                           9: rating20(p["condition"]) if reveal_stats else None, 10: int(p["contract_years"]),

                           11: 0 if p["is_free_agent"] else (low if exact else value),
                           12: int(p["club_division"] or 6) if not p["is_free_agent"] else 99,
                           13: int(p["salary"] or 0) if knowledge>=60 and not p["is_free_agent"] else None,
                           14: knowledge,
                           15: rating20(p["morale"]) if reveal_stats else None}

            _salary_label = (f"{int(p['salary']):,} €".replace(","," ") if knowledge>=60 and not p["is_free_agent"] else "—")
            _morale_label = (f"{rating20(p['morale'])}/20" if reveal_stats else "—")
            vals = [status, f"{shirt:02d}" if shirt and not p["is_free_agent"] else "—", f"{p['first_name']} {p['last_name']}", p["club_name"], p["position"], p["age"], (str(p["nationality"]).upper()[:3] if p["nationality"] else "—"), level_text, potential_text, condition, contract_label, value_label,
                    (f"L{int(p['club_division'])}" if not p["is_free_agent"] else "—"), _salary_label, f"{knowledge} %", _morale_label]

            for c, v in enumerate(vals):

                it = SortableTableWidgetItem(str(v))

                if c in sort_values and sort_values[c] is not None:

                    it.setData(Qt.UserRole + 1, sort_values[c])

                if c == 0:

                    it.setData(Qt.UserRole + 1, 0 if p["is_free_agent"] else 1 if not reveal_stats else 2 if int(p["injury_days"] or 0) > 0 else 3)

                if c == 2:

                    it.setData(Qt.UserRole, p["id"])

                    it.setIcon(QIcon(self.draw_player_avatar(p, 40)))

                    tier_now,tier_color_now=scout_tier_label(knowledge)

                    it.setToolTip(f"{tier_now} • {knowledge} % de connaissance (fiabilité {int(round(accuracy*100))} %)\n{p['first_name']} {p['last_name']} • {p['position']} • {p['age']} ans")

                it.setTextAlignment(Qt.AlignVCenter | (Qt.AlignLeft if c in (2, 3) else Qt.AlignCenter))

                if c == 0:

                    it.setForeground(QColor("#c89aff") if p["is_free_agent"] else QColor("#ffd36b") if p["transfer_listed"] else QColor("#77839c") if knowledge < 25 else QColor("#ff8296") if int(p["injury_days"] or 0) > 0 else QColor("#66dda9"))

                elif c in (7, 8):

                    if (c == 7 and knowledge>=75) or (c == 8 and reveal_potential):

                        score = lvl if c == 7 else potential

                        it.setForeground(QColor("#66e5a8") if score >= 15 else QColor("#ffc969" if c == 7 else "#c89aff"))

                        if score >= 15: it.setFont(QFont("Segoe UI", 9, QFont.Bold))

                    elif c==7 and knowledge>=25 or c==8 and knowledge>=75:

                        it.setForeground(QColor("#9aa8c4")); it.setToolTip("Fourchette du rapport : une mission approfondie affine l'estimation.")

                    else:

                        it.setForeground(QColor("#6a7690")); it.setToolTip("Non évalué : lance une(s) mission(s) de scouting.")

                elif c == 9:

                    form_score = rating20(p["condition"])

                    if reveal_stats: it.setForeground(QColor("#6ce0ad") if form_score >= 15 else QColor("#ffc36b") if form_score >= 10 else QColor("#ff8291"))

                    else: it.setForeground(QColor("#6a7690")); it.setToolTip("Forme non évaluée par le recruteur.")

                elif c == 12:

                    it.setForeground(QColor("#8fa4bf"))

                elif c == 13:

                    it.setForeground(QColor("#b9c9da") if knowledge>=60 else QColor("#5f7088"))

                elif c == 14:

                    it.setForeground(QColor("#8fc4a8") if knowledge>=75 else QColor("#8fa4bf"))

                elif c == 15:

                    it.setForeground(QColor("#8fc4a8") if reveal_stats and rating20(p["morale"])>=14 else QColor("#8fa4bf") if reveal_stats else QColor("#5f7088"))

                elif c == 11:

                    it.setForeground(QColor("#b8caff"))

                    if p["is_free_agent"]: it.setForeground(QColor("#7de0aa"))

                    if p["is_free_agent"]: it.setToolTip("Aucune indemnité de transfert")

                    elif p["transfer_listed"]: it.setToolTip(f"Prix demandé publique : {low:,} €".replace(",", " "))

                    elif knowledge>=60: it.setToolTip(f"Estimation valeur : {low:,} €".replace(",", " "))

                    else: it.setToolTip("Fourchette intuitive : la valeur precise demande une observation (60 %+).")

                self.market_table.setItem(r, c, it)



            if prev_selected_id is not None and p["id"] == prev_selected_id:

                new_selected_row = r

        self.market_table.blockSignals(False)

        self.market_table.setUpdatesEnabled(True)

        new_selected_row = -1

        if prev_selected_id is not None:

            for r in range(self.market_table.rowCount()):

                it = self.market_table.item(r, 2)

                if it and it.data(Qt.UserRole) == prev_selected_id: new_selected_row = r; break

        if new_selected_row >= 0: self.market_table.selectRow(new_selected_row)

        self._selected_market_player_id = prev_selected_id if new_selected_row >= 0 else None



        # Comparatif de la sélection courante.

        current = self.market_table.currentRow()

        if 0 <= current < len(filtered) and best_own:

            current_item = self.market_table.item(current, 2)

            current_id = current_item.data(Qt.UserRole) if current_item else None

            target = next((candidate for candidate in filtered if candidate["id"] == current_id), None)

            if target is None: target = filtered[0] if filtered else None

        else: target = None

        if target and best_own:

            self.market_selected_name.setText(f"{target['first_name']} {target['last_name']}")

            self.market_selected_avatar.setPixmap(self.draw_player_avatar(target, 54))

            if hasattr(self, "offer_amount"):

                if target["is_free_agent"]:

                    self.offer_type_label.setText("SALAIRE PROPOSÉ / MOIS")

                    self.offer_amount.setSuffix(" € / mois")

                    self.offer_amount.setValue(free_agent_ask_salary(target, club)[0])

                    self.offer_years_frame.setVisible(True)

                    self.transfer_salary_frame.setVisible(False)

                    self.offer_btn.setText("PROPOSER LE CONTRAT")

                else:

                    self.offer_type_label.setText("OFFRE DE TRANSFERT")

                    self.offer_amount.setSuffix(" €")

                    self.offer_amount.setValue(int(target["market_value"]))

                    self.offer_years_frame.setVisible(False)

                    self.transfer_salary_spin.setValue(max(500, int(target["salary"] * 1.05)))

                    self.transfer_salary_frame.setVisible(True)

                    self.offer_btn.setText("ENVOYER L'OFFRE")

            self.market_compare.setHtml(self.market_compare_html(target, best_own))

            knowledge = int(target["scout_knowledge"] or 0)

            pending = self.scout_report_pending(target["id"])

            conn = db(); active_count = conn.execute("SELECT COUNT(*) FROM manager_message WHERE kind='scout_report' AND status='waiting'").fetchone()[0]; conn.close()

            capacity = int(getattr(self, "scout_level", 0))

            queue_delay2 = 2*max(0, active_count-capacity+1) if capacity else 0

            mission_ok = self.scout_staff_hired and knowledge < 100 and not pending

            self.scout_report_btn.setVisible(self.scout_staff_hired)

            self.scout_report_btn.setEnabled(mission_ok)

            self.scout_report_btn.setText("SUPERVISION EN COURS" if pending else "RAPPORT COMPLET" if knowledge >= 100 else (f"FILE D'ATTENTE • +{queue_delay2} J" if queue_delay2 else "EXPRESS • 2 J • 1 200 €"))

            if hasattr(self, "scout_deep_btn"):

                self.scout_deep_btn.setVisible(self.scout_staff_hired)

                self.scout_deep_btn.setEnabled(mission_ok)

                self.scout_deep_btn.setText("MISSION EN COURS" if pending else (f"FILE D'ATTENTE • +{queue_delay2} J" if queue_delay2 else "APPROFONDIE • 6 J • 2 400 €"))

            if hasattr(self, "shortlist_btn"):

                self.shortlist_btn.setEnabled(True)

                self.shortlist_btn.setText("★ RETIRER SHORTLIST" if self._shortlisted(int(target["id"])) else "★ SHORTLIST")

        else:

            self.market_selected_name.setText("AUCUNE CIBLE SÉLECTIONNÉE")

            self.market_selected_avatar.clear()

            self.market_compare.setText("Sélectionnez un joueur dans la liste pour lancer un comparatif.")

            if hasattr(self, "shortlist_btn"): self.shortlist_btn.setEnabled(False)

            if hasattr(self, "scout_deep_btn"): self.scout_deep_btn.setEnabled(False)



        # ONGLET OFFRES (retour « bien voir nos offres ») : rebuild seulement

        # quand l'onglet est sur ecran (doctrine visibilite), sinon dirty.

        if getattr(self,"mercato_tabs",None) is not None and hasattr(self,"offers_out_table"):

            if self.mercato_tabs.currentIndex()==0:

                try: self._refresh_offers_tab()

                except Exception as exc: self.log_error("refresh_offers_tab",exc)

            else:

                self._offers_dirty=True

        # ONGLET PRÊTS : même doctrine de visibilité.
        if getattr(self,"mercato_tabs",None) is not None and hasattr(self,"loans_out_table"):

            if self.mercato_tabs.currentIndex()==5:

                try: self.refresh_loans_tab()

                except Exception as exc: self.log_error("refresh_loans_tab",exc)

            else:

                self._loans_dirty=True



    @staticmethod
    def _champion_is_clinched(standings, remaining, remaining_known=True):

        """Vrai si le premier ne peut plus être rejoint (ou saison terminée)."""

        if not remaining_known or not standings:

            return False

        try:

            leader=standings[0]; played=int(leader["played"] or 0)

        except (KeyError, TypeError, ValueError):

            return False

        if played<=0:

            return False

        if sum(remaining.values())//2==0:

            return True

        leader_pts=int(leader["pts"] or 0)

        for other in standings[1:]:

            try:

                rival=int(other["pts"] or 0)+3*remaining.get(int(other["club_id"]),0)

            except (KeyError, TypeError, ValueError):

                return False

            if rival>=leader_pts:

                return False

        return True

    def _fill_standalone_standings(self):

        """Remplit la page Classement en cartes (auto-suffisant : peut être rappelé à l'ouverture de la page)."""

        try:

            if not hasattr(self,"standalone_standings"): return

            # REBUILD SUR VISIBILITE (retour « RAM qui grimpe pendant la saison ») :

            # ~20 cartes x ~12 etiquettes reconstruites a chaque jour sinon. La page

            # se remplit a l'ouverture (show_page) et a chaque avance quand visible.

            if not self.standalone_standings.isVisible():

                return

            conn=db()

            club=conn.execute("SELECT * FROM club WHERE id=1").fetchone()

            selected_division=int(getattr(self,"calendar_division_view",0) or (int(club["division"]) if club else 3))

            standings=conn.execute("""SELECT c.id,c.name,c.division,c.color1,c.color2,s.* FROM league_standing s

                                      JOIN club c ON c.id=s.club_id

                                      WHERE c.division=?

                                      ORDER BY s.pts DESC,(s.gf-s.ga) DESC,s.gf DESC,c.name ASC""",(selected_division,)).fetchall()

            matches=conn.execute("SELECT * FROM match_record ORDER BY id DESC LIMIT 400").fetchall()

            remaining={}

            remaining_known=True

            try:

                remaining_rows=conn.execute("""SELECT f.home_club_id h,f.away_club_id a FROM fixture f
                                               JOIN club hc ON hc.id=f.home_club_id
                                               JOIN club ac ON ac.id=f.away_club_id
                                               WHERE f.season=? AND f.played=0
                                                 AND COALESCE(f.fixture_type,'championship')='championship'
                                                 AND hc.division=? AND ac.division=?""",
                                            (int(club["season"] or 1) if club else 1,
                                             selected_division, selected_division)).fetchall()

                for fr in remaining_rows:

                    for key in (int(fr["h"]), int(fr["a"])):

                        remaining[key]=remaining.get(key,0)+1

            except Exception:

                remaining={}; remaining_known=False

            conn.close()

            # Forme = resultats des 5 derniers matchs de LA SAISON COURANTE, depuis les fixture

            # joues (toutes divisions) : la forme existe pour CHAQUE club, pas seulement ceux

            # croises par le club du manager dans le dossier match_record.

            conn=db()

            book_season=int(club["season"] or 1) if club else 1

            form_rows=conn.execute("""SELECT home_club_id hcid,away_club_id acid,home_goals hg,away_goals ag

                                      FROM fixture WHERE played=1 AND season=?

                                        AND COALESCE(fixture_type,'championship')='championship'

                                      ORDER BY fixture_date DESC,id DESC""",(book_season,)).fetchall()

            conn.close()

            form_by_club={}

            for f in form_rows:

                try:

                    hg=int(f["hg"] or 0); ag=int(f["ag"] or 0)

                except (TypeError,ValueError): continue

                for cid,goals,against in ((int(f["hcid"]),hg,ag),(int(f["acid"]),ag,hg)):

                    bucket=form_by_club.setdefault(cid,[])

                    if len(bucket)<5: bucket.append("V" if goals>against else ("N" if goals==against else "D"))

            # Ordre chronologique (le plus ancien à gauche), comme le tableau de bord.
            for cid in list(form_by_club.keys()):
                form_by_club[cid]=list(reversed(form_by_club[cid]))

            lst=self.standalone_standings

            # PURGE ANTI-FUITE (retour « RAM qui monte ») : ~20 cartes de clubs

            # reconstruites a chaque refresh — les widgets d'item ne suivaient pas.

            self._purge_list_item_widgets(lst)

            lst.clear()

            if not standings:

                ph=QListWidgetItem("LE CHAMPIONNAT EST EN PRÉPARATION\nLes cartes apparaissent dès que la ligue est initialisée. Vérifie le sélecteur de ligue.")

                ph.setFlags(Qt.NoItemFlags); ph.setForeground(QColor("#8fa4b9")); ph.setSizeHint(QSize(500,64)); lst.addItem(ph)

            else:

                zone_division=int(selected_division); zone_count=len(standings)

                # Couronne seulement si le titre est acquis : saison terminée ou
                # avance mathématique irrattrapable sur tous les poursuivants.
                champion_clinched=self._champion_is_clinched(standings, remaining, remaining_known)

                for r,row in enumerate(standings):

                    rank=r+1

                    zone=None

                    if rank==1 and champion_clinched: zone="champion"

                    elif zone_division>1 and rank<=2: zone="promotion"

                    elif zone_division<6 and zone_count>=2 and rank>=zone_count-1: zone="relegation"

                    self.add_club_standing_card(lst,rank,row,compact=True,form=form_by_club.get(int(row["club_id"])),zone=zone)

            # Tuiles de synthèse en tête de page Classement.

            if hasattr(self,"standings_kpi_pos"):

                own_rank=None; own_pts="—"; own_name=None

                for i,srow in enumerate(standings):

                    skeys=srow.keys(); scid=int(srow["club_id"]) if "club_id" in skeys else int(srow["id"])

                    if scid==1:

                        own_rank=i+1; own_pts=srow["pts"]; own_name=srow["name"]

                        self._own_record=(int(srow["wins"]),int(srow["draws"]),int(srow["losses"]),int(srow["pts"]))

                self.standings_kpi_pos.setText(f"{own_rank if own_rank else '—'}ᵉ  ·  {own_pts} PTS" if own_name else "—")

                if own_name:

                    form=form_by_club.get(1) or []

                    self.standings_kpi_form.setText(" ".join(form) or "—")

                else:

                    self.standings_kpi_form.setText("—")

                self.standings_kpi_form.setToolTip("Forme en championnat : du plus ancien (gauche) au plus récent (droite)")

                try: kpi_league=LEAGUE_DEFINITIONS[int(selected_division)-1][1]

                except Exception: kpi_league=f"Ligue {selected_division}"

                self.standings_kpi_league.setText(str(kpi_league))

        except Exception as exc: self.log_error("standings_fill",exc)



    def _history_table(self,headers,stretch_col=1):

        """Tableau d'archive : en-tetes clairs, lignes aerees, aucune cheztrise."""

        t=QTableWidget(); t.setColumnCount(len(headers)); t.setHorizontalHeaderLabels(headers)

        t.verticalHeader().setVisible(False); t.verticalHeader().setDefaultSectionSize(34)

        t.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeToContents)

        t.horizontalHeader().setStretchLastSection(True)

        if 0<=stretch_col<len(headers):

            t.horizontalHeader().setSectionResizeMode(stretch_col,QHeaderView.Stretch)

        t.setEditTriggers(QAbstractItemView.NoEditTriggers)

        t.setSelectionMode(QAbstractItemView.NoSelection); t.setShowGrid(False)

        t.setAlternatingRowColors(True); t.setWordWrap(True)
        t.setFrameShape(QFrame.NoFrame)
        t.setStyleSheet("QTableWidget{background:#0d1420;border:1px solid #2a3548;border-radius:8px;color:#e6ebf3;alternate-background-color:#101a28;gridline-color:#1e2937;}"
                        "QHeaderView::section{background:#152030;color:#9aa6bd;font-weight:900;font-size:8pt;padding:6px 8px;border:0;border-bottom:2px solid #3f7f63;}"
                        "QTableWidget::item{padding:5px 8px;}")

        return t



    def _history_season_year(self,conn,season):

        """Annee de debut de la saison demandee (S1 = annee du debut de carriere)."""

        try:

            d=parse_iso(conn.execute('SELECT "current_date" cd FROM career LIMIT 1').fetchone()["cd"])

            s=int(conn.execute("SELECT season FROM club WHERE id=1").fetchone()["season"])

            base=(d.year if d.month>=7 else d.year-1)

            return base+(int(season)-s)

        except Exception:

            return None



    def _history_cell_open(self,row,col):

        """Ouvre la fiche du club clique dans un tableau d'archive."""

        sender=self.sender()

        item=sender.item(row,col) if sender is not None else None

        if item is None and sender is not None: item=sender.item(row,1)

        club_id=item.data(Qt.UserRole) if item is not None else None

        if club_id is None or int(club_id)<=0: return

        now=QTime.currentTime()

        last=getattr(self,"_last_profile_open",None)

        if last and last.msecsTo(now)<350: return

        self._last_profile_open=now

        self.show_club_profile(int(club_id))



