            def _rgba(hex_color, alpha):

                h=str(hex_color).lstrip("#"); h=h[:6]

                r=int(h[0:2],16); g=int(h[2:4],16); b=int(h[4:6],16); return f"rgba({r},{g},{b},{alpha})"

            tint=QColor(c1)

