            tint2=QColor(c2)

            if tint2.lightness()<60: tint2=tint2.lighter(150)

            def _mixhex(a,b,f):

                ca,cb=QColor(a),QColor(b)

                r=ca.red()+int((cb.red()-ca.red())*f); g=ca.green()+int((cb.green()-ca.green())*f); bl=ca.blue()+int((cb.blue()-ca.blue())*f)

                return f"#{r:02x}{g:02x}{bl:02x}"

            def _dark_channel(color):

                """Ramène une couleur club dans la gamme du bandeau : jamais trop claire, jamais boueuse."""

                q=QColor(color)

                if q.lightness()>140: q=q.darker(220)

                elif q.lightness()<42: q=q.lighter(120)

                return q

