            status_filter = self.roster_status_filter.currentText() if hasattr(self, "roster_status_filter") else "Tout l'effectif"

            filtered_players = []

            for p in players:

                name_and_nation = f"{p['first_name']} {p['last_name']} {p['nationality']}".lower()

                if search and search not in name_and_nation:

                    continue

                if position_filter != "Tous les postes" and p["position"] != position_filter:

                    continue

                unavailable=p["injury_matches"]>0 or int(p["injury_days"] or 0)>0 or p["suspension_matches"]>0

                if status_filter == "Disponibles" and unavailable:

                    continue

                if status_filter == "Fatigués" and (unavailable or int(p["condition"] or 0) >= 60):

                    continue

                if status_filter == "Blessés" and (p["injury_matches"] <= 0 and int(p["injury_days"] or 0) <= 0):

                    continue

                if status_filter == "Suspendus" and p["suspension_matches"]<=0:

                    continue

                if status_filter == "Sur le marché" and not p["transfer_listed"]:

                    continue

                if status_filter == "Fin de contrat" and int(p["contract_years"] or 0) > 1:

                    continue

                if status_filter == "Jeunes à prolonger" and not (
                        int(p["age"] or 0) <= 21 and int(p["contract_years"] or 0) <= 1
                        and int(p["loan_from_club"] or 0) == 0):

                    continue

                filtered_players.append(p)



            self.roster_summary.setText(

                f"{len(players)} JOUEURS SOUS CONTRAT  •  {sum(1 for p in players if p['injury_matches']<=0 and int(p['injury_days'] or 0)<=0 and p['suspension_matches']<=0)} DISPONIBLES  •  5 SUR LE TERRAIN"

            )

            if hasattr(self,"roster_fit_value"):

                available=sum(1 for p in players if p["injury_matches"]<=0 and p["injury_days"]<=0 and p["suspension_matches"]<=0)

                injured=sum(1 for p in players if p["injury_matches"]>0 or p["injury_days"]>0)

                average_level=round(sum(player_level_from_row(p) for p in players)/max(1,len(players)),1)

                wages=sum(int(p["salary"] or 0) for p in players)

                total_value=sum(int(p["market_value"] or 0) for p in players)

                avg_age=round(sum(int(p["age"] or 0) for p in players)/max(1,len(players)),1)

                expiring=sum(1 for p in players if int(p["contract_years"] or 0)<=1)

                youth_expiring=sum(1 for p in players
                                   if int(p["age"] or 0)<=21 and int(p["contract_years"] or 0)<=1
                                   and int(p["loan_from_club"] or 0)==0)

                self.roster_fit_value.setText(str(available)); self.roster_injured_value.setText(str(injured))

                self.roster_avg_value.setText(f"{average_level}/20"); self.roster_wage_value.setText(format_euros(wages, " / mois"))

                self.roster_value_value.setText(format_euros(total_value))

                self.roster_age_value.setText(f"{avg_age} ans")

                self.roster_contracts_value.setText(f"{expiring}" + (" ⚠" if expiring else ""))
                self.roster_contracts_value.setToolTip(
                    f"{expiring} contrat(s) à 1 an ou moins, dont {youth_expiring} jeune(s) U21 à prolonger.\n"
                    f"Utilise le filtre « Jeunes à prolonger » dans la barre de recherche.")

                if hasattr(self,"roster_role_labels"):

                    for role,label in self.roster_role_labels.items(): label.setText(f"{role.upper()}  {sum(1 for p in players if p['position']==role)}")

            self.roster_count_label.setText(f"{len(filtered_players)} JOUEUR(S)")

            self.roster_table.setSortingEnabled(False)

