    def refresh_scouting_tracker(self,current_date=None):

        if not hasattr(self,"scouting_table"): return

        conn=db()

        if not current_date:

            row=conn.execute('SELECT "current_date" FROM career WHERE id=1').fetchone()

            current_date=row["current_date"] if row else "2026-08-01"

        show_all=(getattr(self,"scouting_filter",None) is not None and self.scouting_filter.currentIndex()==1)

        show_done=(getattr(self,"scouting_filter",None) is not None and self.scouting_filter.currentIndex()==2)

        if show_all:

            missions=conn.execute("SELECT * FROM manager_message WHERE kind='scout_report' ORDER BY id DESC LIMIT 100").fetchall()

        elif show_done:

            missions=conn.execute("SELECT * FROM manager_message WHERE kind='scout_report' AND status NOT IN ('waiting','ready') ORDER BY id DESC LIMIT 100").fetchall()

        else:

            missions=conn.execute("SELECT * FROM manager_message WHERE kind='scout_report' AND status IN ('waiting','ready') ORDER BY id DESC LIMIT 100").fetchall()

        players={p["id"]:p for p in conn.execute("SELECT p.*,CASE WHEN p.is_free_agent=1 OR p.club_id=0 THEN 'Joueur libre' ELSE COALESCE(c.name,'Joueur libre')||' · Ligue '||COALESCE(c.division,0) END club_name,COALESCE(sr.knowledge,0) scout_knowledge,COALESCE(sr.reports,0) scout_reports FROM player p LEFT JOIN club c ON c.id=p.club_id LEFT JOIN scout_report sr ON sr.player_id=p.id").fetchall()}

        active_count=conn.execute("SELECT COUNT(*) FROM manager_message WHERE kind='scout_report' AND status='waiting'").fetchone()[0]

        conn.close()

        level=int(getattr(self,"scout_level",0)); capacity=max(0,min(5,level))

        wait_count=max(0,active_count-capacity)

        if not capacity:

            self.scouting_capacity_label.setText("MISSIONS EN COURS : aucun recruteur")

        else:

            self.scouting_capacity_label.setText(

                f"SLOTS SIMULTANÉS : {min(active_count,capacity)} / {capacity}" + (f"  •  EN FILE : {wait_count} (+2 j / mission)" if wait_count else ""))

        if hasattr(self,"scouting_empty"):
            self.scouting_table.setVisible(bool(missions))
            self.scouting_empty.setVisible(not bool(missions))
        self.scouting_table.setRowCount(len(missions))

        try: today=parse_iso(current_date)

        except Exception: today=date(2026,8,1)

        for row_index,message in enumerate(missions):

            try: data=json.loads(message["action_data"] or "{}")

            except (ValueError,TypeError): data={}

            player_id=int(data.get("player_id",0) or 0); player=players.get(player_id)

            player_name=f"{player['first_name']} {player['last_name']}" if player else data.get("player_name","Joueur indisponible")

            club_name=player["club_name"] if player else "—"

            report=player["scout_reports"] if player else int(data.get("reports",0))

            if message["status"]=="waiting":

                try:

                    start=parse_iso(message["created_date"]); due=parse_iso(message["due_date"])

                    span=max(1,(due-start).days); elapsed=max(0,(today-start).days)

                    progress=max(0,min(99,int(elapsed*100/span)))

                except Exception: progress=0

                status="SUPERVISION EN COURS"

            elif message["status"]=="ready":

                progress=100; status="RAPPORT À CONSULTER"

            else:

                progress=100; status="RAPPORT REÇU"

            effort=str(data.get("effort","standard") or "standard")

            effort_meta=SCOUT_EFFORTS.get(effort,SCOUT_EFFORTS["standard"])

            accuracy=float(data.get("accuracy") or 0.0)

            knowledge=player["scout_knowledge"] if player else 0

            tier,tier_color=scout_tier_label(int(knowledge or 0))

            knowledge_label=f"{tier} · {int(knowledge or 0)} %" + (f" · {effort_meta['label'].lower()}" if effort!="standard" else "")

            values=(player_name,club_name,status,"",knowledge_label,str(report),fmt_date_fr(message["due_date"]))

            for col,value in enumerate(values):

                item=SortableTableWidgetItem(str(value))

                item.setTextAlignment(Qt.AlignVCenter | (Qt.AlignLeft if col in (0,1,2) else Qt.AlignCenter))

                if col==0: item.setData(Qt.UserRole,player_id)

                if col==2: item.setData(Qt.UserRole,int(message["id"]))  # id du message pour l'archivage groupé

                if col==2:
                    item.setForeground(QColor("#d8bc8a") if message["status"]=="waiting" else QColor("#93bda8") if message["status"]=="ready" else QColor("#9fb4c8"))

                if col==4:

                    item.setForeground(QColor(tier_color))

                    if accuracy>0: item.setToolTip(f"Mission {effort_meta['label'].lower()} • fiabilité du rapport {int(round(accuracy*100))} %.")

                self.scouting_table.setItem(row_index,col,item)

            bar=QProgressBar(); bar.setRange(0,100); bar.setValue(progress)
            bar.setFormat(f"{progress} %"); bar.setTextVisible(True); bar.setFixedHeight(18)
            bar.setStyleSheet("QProgressBar{background:#0b1420;border:1px solid #2a3d54;border-radius:5px;"
                              "color:#dfe9f5;font-size:7pt;font-weight:900;text-align:center;}"
                              "QProgressBar::chunk{background:%s;border-radius:4px;}" % ("#6f887c" if progress>=100 else "#7d8fa8"))

            self.scouting_table.setCellWidget(row_index,3,bar)

            self.scouting_table.setRowHeight(row_index,44)



    def open_scouting_row_in_market(self,row,column):

        item=self.scouting_table.item(row,0) if row>=0 else None

        player_id=item.data(Qt.UserRole) if item else None

        player=next((p for p in getattr(self,"_market_rows",[]) if int(p["id"])==int(player_id or 0)),None)
        # Le tableau marché est filtré/paginé : un rapport de scouting peut
        # concerner un joueur absent de _market_rows sans qu'il soit disparu.
        # Recharge donc la fiche complète avant d'annoncer « indisponible ».
        if player is None and player_id:
            c=db()
            player=c.execute("""SELECT p.*,COALESCE(c.name,'Joueur libre') club_name,COALESCE(c.division,0) club_division,
                                      COALESCE(sr.knowledge,0) scout_knowledge,
                                      COALESCE(sr.reports,0) scout_reports,
                                      COALESCE(sr.accuracy,0.60) scout_accuracy
                               FROM player p LEFT JOIN club c ON c.id=p.club_id
                               LEFT JOIN scout_report sr ON sr.player_id=p.id
                               WHERE p.id=?""",(int(player_id),)).fetchone()
            c.close()

        if player:

            self.mercato_tabs.setCurrentIndex(1)

            self.show_player_profile(player)

        else:

            self.show_game_message("Scouting","Ce joueur n'est plus disponible dans le mercato.","info")



    def apply_tactical_preset(self,key):

        presets={

            "equilibre":("Équilibré · contrôle",{"formation":"3-1 · Pivot","mentality":"Équilibrée","tempo":"Normal","press_intensity":"Médian","block_height":"Médian","attack_width":"Équilibré","attack_focus":"Équilibré","rotation_style":"Équilibrées","goalkeeper_distribution":"Équilibrée"}),

            "possession":("Possession · mouvement et largeur",{"formation":"4-0 · Mouvement","mentality":"Équilibrée","tempo":"Patient","press_intensity":"Médian","block_height":"Médian","attack_width":"Large","attack_focus":"Ailes","rotation_style":"Équilibrées","goalkeeper_distribution":"Courte"}),

            "contre":("Contre · bloc compact et sortie rapide",{"formation":"2-2 · Largeur","mentality":"Prudente","tempo":"Rapide","press_intensity":"Bas","block_height":"Bas","attack_width":"Étroit","attack_focus":"Pivot","rotation_style":"Équilibrées","goalkeeper_distribution":"Directe"}),

            "pressing":("Pressing haut · récupération agressive",{"formation":"3-1 · Pivot","mentality":"Pressing haut","tempo":"Rapide","press_intensity":"Haut","block_height":"Haut","attack_width":"Large","attack_focus":"Ailes","rotation_style":"Agressives","goalkeeper_distribution":"Rapide"}),

            "powerplay":("Powerplay · gardien volant, risque maximal",{"formation":"Gardien volant · Risqué","mentality":"Offensive","tempo":"Rapide","press_intensity":"Haut","block_height":"Haut","attack_width":"Large","attack_focus":"Axe central","rotation_style":"Agressives","goalkeeper_distribution":"Directe"}),

        }

        if key not in presets: return

        description,values=presets[key]

        self._applying_tactic_preset=True

        for attr,value in values.items(): getattr(self,attr).setCurrentText(value)

        self._applying_tactic_preset=False

        self.active_tactic_preset=key

        for button_key,button in self.tactic_preset_buttons.items(): button.setChecked(button_key==key)

        self.preset_description.setText(description)

        self.persist_tactics_settings()

        self.tactic_feedback.setText(f"PRÉRÉGLAGE APPLIQUÉ  •  {description}. Tu peux ensuite l'affiner.")



    def clear_tactical_preset_selection(self,*_):

        if getattr(self,"_applying_tactic_preset",False): return

        self.active_tactic_preset=None

        for button in getattr(self,"tactic_preset_buttons",{}).values(): button.setChecked(False)

        self.update_tactical_summary()



    def update_tactical_summary(self):

        if not hasattr(self,"tactic_fit_label"):

            return

        formation=self.formation.currentText(); mentality=self.mentality.currentText(); tempo=self.tempo.currentText()

        pressing=self.press_intensity.currentText(); block=self.block_height.currentText()

        fit="Très bonne" if formation.startswith(("3-1","2-2")) else "Bonne" if formation.startswith(("4-0","1-2")) else "À surveiller"

        risk="Élevé" if mentality in ("Offensive","Pressing haut") or pressing=="Haut" or formation.startswith("Gardien") else "Modéré" if tempo=="Rapide" else "Faible"

        control="Fort" if mentality=="Équilibrée" and tempo!="Rapide" and block!="Haut" else "Équilibré" if block=="Médian" else "Fragile"

        tone_fit={"Très bonne":"#8de5b9","Bonne":"#cfe3a8","À surveiller":"#e6bd69"}.get(fit,"#e6ebf3")
        tone_risk={"Faible":"#8de5b9","Modéré":"#e6bd69","Élevé":"#ff9daa"}.get(risk,"#e6ebf3")
        tone_control={"Fort":"#8de5b9","Équilibré":"#bcd3ef","Fragile":"#ff9daa"}.get(control,"#e6ebf3")
        cap=lambda text: f"<span style='color:#8fa4bf;font-weight:800'>{text}</span>"
        val=lambda text,tone: f"<span style='color:{tone};font-weight:900'>{text}</span>"
        self.tactic_fit_label.setText(f"{cap('COMPATIBILITÉ')} {val(fit,tone_fit)}")
        self.tactic_risk_label.setText(f"{cap('RISQUE')} {val(risk,tone_risk)}")
        self.tactic_control_label.setText(f"{cap('CONTRÔLE')} {val(control,tone_control)}")



