    def persist_tactics_settings(self):

        settings={

            "formation":self.formation.currentText(), "mentality":self.mentality.currentText(), "tempo":self.tempo.currentText(),

            "press_intensity":self.press_intensity.currentText(), "block_height":self.block_height.currentText(),

            "attack_width":self.attack_width.currentText(), "attack_focus":self.attack_focus.currentText(),

            "rotation_style":self.rotation_style.currentText(), "goalkeeper_distribution":self.goalkeeper_distribution.currentText(),

            "preset":self.active_tactic_preset,

            "lineup":{name:zone.player_id for name,zone in self.pitch_zones.items() if zone.player_id is not None},

        }

        conn=db(); conn.execute("CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT)")

        conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('tactics_config',?)",(json.dumps(settings,ensure_ascii=False),))

        conn.commit(); conn.close()



    def load_tactics_settings(self):

        self._tactics_config_loaded=False

        self._applying_tactic_preset=True

        defaults={"formation":"3-1 · Pivot","mentality":"Équilibrée","tempo":"Normal","press_intensity":"Médian","block_height":"Médian","attack_width":"Équilibré","attack_focus":"Équilibré","rotation_style":"Équilibrées","goalkeeper_distribution":"Équilibrée"}

        for key,value in defaults.items(): getattr(self,key).setCurrentText(value)

        self._applying_tactic_preset=False

        self.active_tactic_preset="equilibre"

        for key,button in self.tactic_preset_buttons.items(): button.setChecked(key=="equilibre")

        self.preset_description.setText("Équilibré · contrôle")

        self.tactical_advanced_panel.setVisible(False); self.advanced_settings_btn.setText("⚙  RÉGLAGES +")

        for zone in self.pitch_zones.values(): zone.reset_zone()

        conn=db(); conn.execute("CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT)")

        saved=conn.execute("SELECT value FROM meta WHERE key='tactics_config'").fetchone()

        if not saved or not saved["value"]:

            conn.close(); return

        self._tactics_config_loaded=True

        try:

            settings=json.loads(saved["value"])

        except (TypeError,ValueError):

            conn.close(); return

        for key in ("formation","mentality","tempo","press_intensity","block_height","attack_width","attack_focus","rotation_style","goalkeeper_distribution"):

            combo=getattr(self,key,None)

            if combo and settings.get(key): combo.setCurrentText(settings[key])

        self.active_tactic_preset=settings.get("preset")

        for button_key,button in self.tactic_preset_buttons.items(): button.setChecked(button_key==self.active_tactic_preset)

        if self.active_tactic_preset and self.active_tactic_preset in self.tactic_preset_buttons:

            self.preset_description.setText({"equilibre":"Équilibré · contrôle","possession":"Possession · mouvement et largeur","contre":"Contre · bloc compact et sortie rapide","pressing":"Pressing haut · récupération agressive","powerplay":"Powerplay · gardien volant, risque maximal"}.get(self.active_tactic_preset,"Préréglage enregistré"))

        else:

            self.preset_description.setText("Plan personnalisé sauvegardé • modifie-le ou choisis un préréglage.")

        saved_lineup=settings.get("lineup",{})

        if isinstance(saved_lineup,list):

            saved_lineup=dict(zip(self.pitch_zones.keys(),saved_lineup))

        ids=[int(pid) for pid in saved_lineup.values() if str(pid).isdigit()]

        if ids:

            placeholders=",".join("?" for _ in ids)

            rows=conn.execute(f"SELECT * FROM player WHERE club_id=1 AND COALESCE(is_free_agent,0)=0 AND injury_matches<=0 AND injury_days<=0 AND suspension_matches<=0 AND id IN ({placeholders})",ids).fetchall()

            by_id={p["id"]:p for p in rows}

            for zone_name,pid in saved_lineup.items():

                pid=int(pid)

                if pid in by_id:

                    p=by_id[pid]; zone=self.pitch_zones[zone_name]

                    self.set_tactical_zone_player(zone,p)

        conn.close()



    def on_tactical_player_dropped(self,target,pid,payload):

        conn=db(); player=conn.execute("SELECT position,first_name,last_name,injury_matches,injury_days,suspension_matches FROM player WHERE id=? AND club_id=1",(pid,)).fetchone(); conn.close()

        flying=self.formation.currentText().startswith("Gardien volant")

        if player and not flying and ((target.zone_name=="Gardien" and player["position"]!="Gardien") or (target.zone_name!="Gardien" and player["position"]=="Gardien")):

            target.reset_zone(); self.refresh_all()

            self.show_game_message("Poste incompatible","Pour placer un joueur de champ au poste de gardien, choisis d'abord la formation Gardien volant.","warning")

            return

        if player and (int(player["injury_matches"] or 0)>0 or int(player["injury_days"] or 0)>0 or int(player["suspension_matches"] or 0)>0):

            disc=player_discipline_text(player)

            target.reset_zone(); self.refresh_all()

            self.show_game_message("Joueur indisponible",f"{player['first_name']} {player['last_name']} — {disc}. Il reste au banc : impossible de l'intégrer au cinq.","warning")

            return

        for zone in self.pitch_zones.values():

            if zone is not target and zone.player_id==pid:

                zone.reset_zone()

        self.refresh_all()

        self.persist_tactics_settings()

        self.tactic_feedback.setText(f"{target.player_label} placé en {target.zone_name}. Composition enregistrée.")



    def on_tactical_player_returned(self,pid):

        for zone in self.pitch_zones.values():

            if zone.player_id==pid:

                zone.reset_zone()

        self.refresh_all()

        self.persist_tactics_settings()

        self.tactic_feedback.setText("Joueur renvoyé sur le banc. Composition enregistrée.")



    def refresh_tactical_bench(self, players=None, available=None):
        """BANC : fiches enrichies, tri et recherche. Les indisponibles restent
        visibles, grises, en fin de liste."""
        if not hasattr(self, "tactic_bench"): return
        try:
            if players is None or available is None:
                conn=db()
                players=conn.execute("SELECT * FROM player WHERE club_id=1 AND COALESCE(is_free_agent,0)=0 ORDER BY id").fetchall()
                conn.close()
                available=None
            if available is None:
                available=[p for p in players if int(p["injury_matches"] or 0)<=0 and int(p["injury_days"] or 0)<=0 and int(p["suspension_matches"] or 0)<=0]
            available=[p for p in available if int(p["injury_matches"] or 0)<=0 and int(p["injury_days"] or 0)<=0 and int(p["suspension_matches"] or 0)<=0]
            selected_ids=set(self._selected_lineup_ids())
            old_item=self.tactic_bench.currentItem()
            old_id=old_item.data(Qt.UserRole) if old_item else None
            query=(self.bench_search.text() if hasattr(self,"bench_search") else "").strip().lower()
            mode=(self.bench_sort.currentData() if hasattr(self,"bench_sort") else "note") or "note"

            def _match(p):
                if not query: return True
                return query in f"{p['first_name']} {p['last_name']} {p['position']}".lower()

            def _key(p):
                level=player_level_from_row(p)
                if mode=="poste":
                    order={"Gardien":0,"Défenseur":1,"Ailier":2,"Pivot":3}.get(str(p["position"]),9)
                    return (order,-level,str(p["last_name"]).lower())
                if mode=="nom": return (str(p["last_name"]).lower(),str(p["first_name"]).lower())
                if mode=="forme": return (-int(p["condition"] or 0),-level)
                if mode=="age": return (int(p["age"] or 0),-level)
                if mode=="contrat": return (int(p["contract_years"] or 0),-level)
                if mode=="salaire": return (-int(p["salary"] or 0),-level)
                return (-level,-int(p["condition"] or 0))

            def _line(p, level, extra=""):
                shirt=int(p["shirt_number"] or 0)
                first=f"#{shirt:02d}  {p['first_name']} {p['last_name']}   •   {level:.1f}/20"
                flags=[]
                if int(p["contract_years"] or 0)<=1: flags.append("FIN DE CONTRAT")
                if int(p["transfer_listed"] or 0): flags.append("LISTÉ")
                if extra: flags.append(extra)
                second=f"{p['position']} · {int(p['age'] or 0)} a · F{rating20(p['condition'])} · C{int(p['contract_years'] or 0)} an"
                if flags: second+=" · "+" · ".join(flags)
                return first+"\n"+second

            self.tactic_bench.blockSignals(True)
            self.tactic_bench.clear()
            shown=0
            for p in sorted([p for p in available if p["id"] not in selected_ids and _match(p)],key=_key):
                level=player_level_from_row(p)
                it=QListWidgetItem(_line(p,level))
                it.setData(Qt.UserRole,p["id"]); it.setData(Qt.UserRole+1,False)
                it.setData(Qt.UserRole+2,{"name":f"{p['first_name']} {p['last_name']}",
                                          "number":f"#{int(p['shirt_number'] or 0):02d}",
                                          "note":round(level,1),"form_label":f"F{rating20(p['condition'])}",
                                          "sub":f"{p['position']} · {int(p['age'] or 0)} ans · contrat {int(p['contract_years'] or 0)} an(s)",
                                          "stats":f"TEC {rating20(p['technique'])} · PAS {rating20(p['passing'])} · FIN {rating20(p['finishing'])} · DÉF {rating20(p['defense'])} · END {rating20(p['stamina'])} · MOR {rating20(p['morale'])}",
                                          "flags":"FIN DE CONTRAT" if int(p['contract_years'] or 0)<=1 else ("LISTÉ" if int(p['transfer_listed'] or 0) else "")})
                it.setIcon(QIcon(self.draw_player_avatar(p,44)))
                it.setForeground(QColor("#8de5b9") if level>=15 else QColor("#d8e968") if level>=12 else QColor("#dce5f0"))
                it.setToolTip(f"{p['first_name']} {p['last_name']}\n{p['position']} · {int(p['age'] or 0)} ans · {level:.1f}/20 {stars5(level)}\nForme {rating20(p['condition'])}/20 · moral {rating20(p['morale'])}/20\nContrat {int(p['contract_years'] or 0)} an(s) · {format_salary_monthly(p)}\nGlisser sur le terrain • double-clic : fiche")
                it.setSizeHint(QSize(300,76))
                self.tactic_bench.addItem(it); shown+=1

            available_ids={p["id"] for p in available}
            unavailable=[p for p in players if p["id"] not in available_ids and _match(p)]
            for p in sorted(unavailable,key=_key):
                level=player_level_from_row(p); disc=player_discipline_text(p)
                it=QListWidgetItem(_line(p,level,disc))
                it.setData(Qt.UserRole,p["id"]); it.setData(Qt.UserRole+1,True)
                it.setData(Qt.UserRole+2,{"name":f"{p['first_name']} {p['last_name']}",
                                          "number":f"#{int(p['shirt_number'] or 0):02d}",
                                          "note":round(level,1),"form_label":f"F{rating20(p['condition'])}",
                                          "sub":f"{p['position']} · {int(p['age'] or 0)} ans · indisponible",
                                          "stats":f"TEC {rating20(p['technique'])} · PAS {rating20(p['passing'])} · FIN {rating20(p['finishing'])} · DÉF {rating20(p['defense'])} · END {rating20(p['stamina'])} · MOR {rating20(p['morale'])}",
                                          "flags":disc})
                it.setForeground(QColor("#6f7d97"))
                it.setIcon(QIcon(self.draw_player_avatar(p,44)))
                it.setToolTip(f"{disc} • indisponible : impossible de l'intégrer au cinq • double-clic = fiche")
                it.setSizeHint(QSize(300,76))
                self.tactic_bench.addItem(it)

            self.lineup_counter.setText(f"{len(selected_ids & available_ids)}/5 TITULAIRES")
            self.bench_count.setText(f"{shown} DISPO  •  {len(unavailable)} INDISPO")
            if self.tactic_bench.count()==0:
                empty=QListWidgetItem("Aucun joueur ne correspond à la recherche." if query else "Tous les joueurs disponibles sont sur le terrain.")
                empty.setFlags(Qt.NoItemFlags); empty.setForeground(QColor("#7f93ad"))
                empty.setTextAlignment(Qt.AlignCenter); empty.setSizeHint(QSize(300,52))
                self.tactic_bench.addItem(empty)
            select_row=next((i for i in range(self.tactic_bench.count()) if self.tactic_bench.item(i).data(Qt.UserRole)==old_id),0 if self.tactic_bench.count() else -1)
            if select_row>=0 and self.tactic_bench.item(select_row).data(Qt.UserRole) is None: select_row=-1
            if select_row>=0: self.tactic_bench.setCurrentRow(select_row)
            self.tactic_bench.blockSignals(False)
            self.update_tactical_bench_preview()
        except Exception as exc:
            try: self.tactic_bench.blockSignals(False)
            except Exception: pass
            self.log_error("refresh_tactical_bench",exc)

