    def _selected_lineup_ids(self):

        ids = []

        zones = getattr(self, "pitch_zones", None)

        if not zones:

            return ids

        for zone in zones.values():

            pid = zone.player_id

            if pid is not None and pid not in ids:

                ids.append(pid)

        return ids



    def auto_pick_lineup(self):

        conn = db()

        rows = conn.execute("""SELECT * FROM player WHERE club_id=1 AND COALESCE(is_free_agent,0)=0 AND injury_matches<=0 AND injury_days<=0 AND suspension_matches<=0

                              ORDER BY condition DESC, stamina DESC, technique DESC""").fetchall()

        conn.close()

        if len(rows)<5:

            self.tactic_feedback.setText("Il faut cinq joueurs valides pour composer le cinq."); return

        gks=sorted((p for p in rows if p["position"]=="Gardien"),key=lambda p:(p["goalkeeper"],p["condition"]),reverse=True)

        keeper=gks[0] if gks else rows[0]

        outfield=[p for p in rows if p["id"]!=keeper["id"]]

        defenders=sorted(outfield,key=lambda p:(p["defense"]+p["stamina"],p["condition"]),reverse=True)

        def_left,def_right=defenders[:2]

        used={keeper["id"],def_left["id"],def_right["id"]}

        remaining=[p for p in outfield if p["id"] not in used]

        winger=max(remaining,key=lambda p:(p["technique"]+p["passing"],p["condition"]))

        remaining.remove(winger)

        pivot=max(remaining,key=lambda p:(p["finishing"]+p["technique"],p["condition"]))

        picks={"Gardien":keeper,"Défenseur G":def_left,"Défenseur D":def_right,"Ailier":winger,"Pivot":pivot}

        for name,zone in self.pitch_zones.items():

            p=picks[name]; self.set_tactical_zone_player(zone,p)

        self.refresh_all(); self.persist_tactics_settings()

        self.tactic_feedback.setText("Cinq auto-composé : gardien, deux défenseurs, ailier et pivot. Ajuste les postes par glisser-déposer.")



    def reset_drag_lineup(self):

        for z in self.pitch_zones.values():

            z.reset_zone()

        self.refresh_all(); self.persist_tactics_settings()

        self.tactic_feedback.setText("Terrain vidé. Glisse maintenant les cinq joueurs titulaires depuis le banc.")



    def _get_opponents(self, conn):

        rows = conn.execute("SELECT name FROM club WHERE id<>1 ORDER BY reputation DESC, id").fetchall()

        names = [r["name"] for r in rows]

        if names:

            return names

        return ["FC Dynamo","Sporting Nord","AS Montferrand","Futsal Élite","Union des Cinq","Olympique Indoor","Étoile du Sud"]



    def emergency_sign_free_agent(self,conn,club_id):

        """Recrutement d'urgence : l'IA n'aligne JAMAIS un blessé ou un suspendu.

        Si les joueurs valides passent sous cinq, le club engaite un joueur libre

        sain proche du niveau du groupe, avec un salaire qu'il peut assumer

        (6 mois). Retourne la ligne signée, sinon None (→ forfait)."""

        try:

            club=conn.execute("SELECT budget,division FROM club WHERE id=?",(club_id,)).fetchone()

            if not club: return None

            division=max(1,min(6,int(club["division"] or 3)))

            roster=conn.execute("SELECT * FROM player WHERE club_id=? AND is_free_agent=0",(club_id,)).fetchall()

            levels=[player_level_from_row(p) for p in roster]

            avg=(sum(levels)/len(levels)) if levels else LEAGUE_DEFINITIONS[division-1][2]*0.5

            budget=int(club["budget"] or 0)

            market=conn.execute("""SELECT * FROM player WHERE is_free_agent=1 AND COALESCE(retired,0)=0

                                   AND injury_matches<=0 AND injury_days<=0 AND suspension_matches<=0""").fetchall()

            in_band=[p for p in market if abs(player_level_from_row(p)-avg)<=2.5]

            candidates=in_band or market

            candidates=[p for p in candidates if int(p["salary"] or 0)*6<=budget]

            if not candidates: return None

            pick=sorted(candidates,key=lambda p:(abs(player_level_from_row(p)-avg),-self.match_outfield_rating(p)))[0]

            pick=dict(pick)

            # (aucune limite : un club en effectif réduit peut toujours signer un libre)

            conn.execute("UPDATE player SET club_id=?,is_free_agent=0,free_agent_since='',shirt_number=?,contract_years=2 WHERE id=?",(club_id,next_shirt_number(conn,int(club_id)),int(pick["id"])))

            pick["club_id"]=club_id; pick["is_free_agent"]=0; pick["contract_years"]=2

            record_player_history(conn,int(pick["id"]),club_id,"transfert","Signature d'urgence (effectif réduit)")

            return pick

        except sqlite3.Error as exc:

            self.log_error("emergency_sign_free_agent",exc)

            return None



    def _load_match_roster(self):

        conn = db()

        rows = conn.execute("""SELECT * FROM player

                               WHERE club_id=1 AND COALESCE(is_free_agent,0)=0 AND injury_matches<=0 AND injury_days<=0 AND suspension_matches<=0

                               ORDER BY condition DESC, stamina DESC, technique DESC""").fetchall()

        conn.close()

        if len(rows) < 5:

            return None, None



        by_id={p["id"]:p for p in rows}

        zones=getattr(self,"pitch_zones",{})

        preferred_ids={name:zone.player_id for name,zone in zones.items()}

        gks=sorted((p for p in rows if p["position"]=="Gardien"),key=lambda p:(p["goalkeeper"],p["condition"]),reverse=True)

        selected_keeper=by_id.get(preferred_ids.get("Gardien"))

        if selected_keeper and (selected_keeper["position"]=="Gardien" or self.formation.currentText().startswith("Gardien volant")):

            starter_gk=selected_keeper

        else:

            starter_gk=gks[0] if gks else rows[0]

        starters=[starter_gk]

        for zone_name in ("Défenseur G","Défenseur D","Ailier","Pivot"):

            pid=preferred_ids.get(zone_name)

            player=by_id.get(pid)

            if player and player["id"] not in {p["id"] for p in starters}:

                starters.append(player)

        outfield=sorted((p for p in rows if p["position"]!="Gardien" and p["id"] not in {x["id"] for x in starters}),key=lambda p:(p["condition"],p["stamina"],p["technique"]),reverse=True)

        starters.extend(outfield[:max(0,5-len(starters))])

        starters=starters[:5]

        used_ids = {p["id"] for p in starters}

        bench = [r for r in rows if r["id"] not in used_ids]

        return starters, bench



    def _load_opponent_match_roster(self,club_id):

        # L'IA ne peut PAS aligner un joueur blessé, suspendu ou déjà libre (is_free_agent).

        conn=db()

        rows=conn.execute("SELECT * FROM player WHERE club_id=? AND is_free_agent=0 AND injury_matches<=0 AND injury_days<=0 AND suspension_matches<=0 ORDER BY id",(club_id,)).fetchall()

        if len(rows)<5:

            for _ in range(3):

                signed=self.emergency_sign_free_agent(conn,club_id)

                if not signed: break

                rows.append(signed)

        conn.commit(); conn.close()

        selected=self.select_club_match_five(rows) if len(rows)>=5 else []

        if len(selected)<5: return [],[]

        selected_ids={p["id"] for p in selected}

        players=[dict(row) for row in rows]

        bench=sorted((p for p in players if p["id"] not in selected_ids),key=self.match_outfield_rating,reverse=True)

        return selected,bench



    def match_outfield_rating(self,player):

        return (int(player["finishing"])*.28+int(player["technique"])*.24+int(player["passing"])*.20+

                int(player["defense"])*.14+int(player["stamina"])*.10+int(player["condition"])*.04)



    def select_club_match_five(self,rows):

        players=[dict(row) for row in rows]

        if len(players)<5: return []

        keepers=sorted((p for p in players if p["position"]=="Gardien"),key=lambda p:(int(p["goalkeeper"])*.72+int(p["condition"])*.18+int(p["stamina"])*.10),reverse=True)

        keeper=keepers[0] if keepers else max(players,key=lambda p:int(p["goalkeeper"]))

        selected=[keeper]

        for role in ("Défenseur","Ailier","Pivot","Universel"):

            options=[p for p in players if p["id"] not in {q["id"] for q in selected} and p["position"]==role]

            if options: selected.append(max(options,key=self.match_outfield_rating))

            if len(selected)==5: break

        remaining=sorted((p for p in players if p["id"] not in {q["id"] for q in selected} and p["id"]!=keeper["id"]),key=self.match_outfield_rating,reverse=True)

        selected.extend(remaining[:max(0,5-len(selected))])

        return selected[:5]



    def _tactical_profile_mods(self,state):
        """Facteurs du plan : familiarité/consignes (calculés une fois), puis dynamique."""
        try:
            static=state.get("static_tactical_mods")
            if static is None:
                c=db()
                meta={r["key"]:(r["value"] or "") for r in c.execute("SELECT key,value FROM meta WHERE key IN ('tactics_familiarity','setpiece_corner','setpiece_freekick','setpiece_exit','powerplay')").fetchall()}
                ids=[int(pl["id"]) for pl in (state.get("lineup") or []) if pl.get("id")]
                rows={}
                if ids:
                    marks=",".join("?" for _ in ids)
                    rows={int(r["player_id"]):dict(r) for r in c.execute(f"SELECT * FROM tactical_instruction WHERE player_id IN ({marks})",ids).fetchall()}
                c.close()
                fam=int(meta.get("tactics_familiarity",60) or 60)
                famf=0.93+0.10*fam/100
                att=fin=pas=famf
                def_=max(0.90,famf-0.01)
                natural={"Gardien":"Gardien","Défenseur":"Fixo","Ailier":"Ala","Pivot":"Pivot","Universel":"Universel"}
                lineup=list(state.get("lineup") or [])
                att_team=def_team=fin_team=1.0
                for pl in lineup:
                    pos=str(pl.get("position","") or ""); pid=int(pl.get("id") or 0)
                    ins=rows.get(pid,{})
                    role=str(ins.get("role") or natural.get(pos,"Universel"))
                    a=d=f=1.0
                    if role==natural.get(pos):
                        if role in ("Fixo","Gardien"): d*=1.012
                        elif role=="Ala": a*=1.010
                        elif role=="Pivot": f*=1.015
                    else:
                        a*=0.985; d*=0.985
                    pressing=str(ins.get("pressing") or "Normal")
                    if pressing=="Haut": d*=1.020
                    elif pressing=="Bas": a*=0.990
                    defensive=str(ins.get("defensive") or "Normal")
                    if defensive=="Agressif": d*=1.015; a*=0.995
                    elif defensive=="Relâché": a*=1.015; d*=0.990
                    att_team*=a; def_team*=d; fin_team*=f
                _n=max(1,len(lineup))
                att*=att_team**(1.0/_n); def_*=def_team**(1.0/_n); fin*=fin_team**(1.0/_n)
                corner=meta.get("setpiece_corner","Poteau"); fk=meta.get("setpiece_freekick","Direct"); exit_=meta.get("setpiece_exit","Court")
                if corner=="Poteau": att*=1.010
                elif corner=="Court": pas*=1.010
                if fk=="Direct": fin*=1.020
                else: pas*=1.010
                if exit_=="Court": pas*=1.012
                else: att*=1.006
                state["pp_setting"]=meta.get("powerplay","Automatique")
                static=[att,def_,fin,pas]
                state["static_tactical_mods"]=static
            else:
                att,def_,fin,pas=static
            if state.get("pp_setting","Automatique")!="Jamais" and int(state.get("minute",0))>=35:
                hg,ag=int(state.get("hg",0)),int(state.get("ag",0)); home=bool(state.get("is_home",True))
                if (hg<ag) if home else (ag<hg):
                    att*=1.10; def_*=0.90
            if int(state.get("minute",0))<20:
                pre=getattr(self,"_prematch_mods",{}) or {}
                att*=float(pre.get("attack",1) or 1); def_*=float(pre.get("defense",1) or 1)
            mom=float(state.get("momentum",0) or 0)
            att*=1.0+max(-0.08,min(0.08,mom*0.004))
            talk=state.get("talk_mods") or {}
            att*=float(talk.get("attack",1) or 1); def_*=float(talk.get("defense",1) or 1)
            clamp=lambda v: max(0.82,min(1.18,v))
            return clamp(att),clamp(def_),clamp(fin),clamp(pas)
        except Exception as exc:
            self.log_error("tactical_profile_mods",exc); return 1.0,1.0,1.0,1.0


    def match_team_profile(self,players,condition_overrides=None):

        condition_overrides=condition_overrides or {}

        field=[p for p in players if p.get("position")!="Gardien"]

        keepers=[p for p in players if p.get("position")=="Gardien"]

        if not field: field=list(players)

        if not field:

            return {"attack":45.0,"defense":45.0,"passing":45.0,"finishing":45.0,"keeper":45.0,"stamina":45.0}

        def average(key,source=field):

            return sum(float(p.get(key,45) or 45) for p in source)/max(1,len(source))

        effective_stamina=sum(min(float(p.get("stamina",45) or 45),float(condition_overrides.get(p.get("id"),p.get("condition",70)) or 70)) for p in field)/len(field)

        # Notes futsal : dribble serré (espaces réduits), explosivité (contres/retours), placement (rotations 4-0/3-1).

        dribble_avg=average("dribble") if "dribble" in field[0] else 50.0

        speed_avg=average("speed") if "speed" in field[0] else 50.0

        posn_avg=average("positioning") if "positioning" in field[0] else 50.0

        keeper_rating=max((float(p.get("goalkeeper",45) or 45)*.70+float(p.get("condition",70) or 70)*.12+float(p.get("stamina",45) or 45)*.08+float(p.get("positioning",50) or 50)*.10 for p in keepers),default=average("defense",field)*.55+average("stamina",field)*.45)

        return {"attack":average("finishing")*.32+average("technique")*.24+dribble_avg*.14+speed_avg*.08+average("passing")*.14+effective_stamina*.08,

                "defense":average("defense")*.42+posn_avg*.17+average("stamina")*.19+average("technique")*.12+average("passing")*.10,

                "passing":average("passing")*.54+average("technique")*.30+posn_avg*.16,"finishing":average("finishing"),

                "keeper":keeper_rating,"stamina":effective_stamina,

                "dribble":dribble_avg,"speed":speed_avg,"positioning":posn_avg}



    def opponent_tactical_identity(self,club_id,division,reputation):

        try:
            from club_profiles import identity_for_club
            _conn=db()
            try: _identity=identity_for_club(_conn,club_id)
            finally: _conn.close()
            if _identity:
                return _identity
        except Exception:
            pass

        identities=(

            {"style":"possession","formation":"4-0","pressing":"Médian","tempo":"Patient"},

            {"style":"contre","formation":"2-2","pressing":"Bas","tempo":"Rapide"},

            {"style":"pressing","formation":"3-1","pressing":"Haut","tempo":"Rapide"},

            {"style":"equilibre","formation":"3-1","pressing":"Médian","tempo":"Normal"},

        )

        identity=dict(identities[(int(club_id)+int(division))%len(identities)])

        if int(reputation)>=75 and identity["style"]=="contre": identity["style"]="pressing"

        return identity



    def _current_date(self, conn):

        return conn.execute('SELECT career."current_date" AS current_date FROM career WHERE id=1').fetchone()["current_date"]



    def _next_fixture_for_user(self, conn):

        return conn.execute(

            """SELECT f.*, hc.name home_name, ac.name away_name

               FROM fixture f

               JOIN club hc ON hc.id=f.home_club_id

               JOIN club ac ON ac.id=f.away_club_id

               WHERE (f.home_club_id=1 OR f.away_club_id=1) AND f.played=0

               ORDER BY f.fixture_date, f.matchday LIMIT 1"""

        ).fetchone()



    def _today_fixture_for_user(self, conn):

        d = self._current_date(conn)

        return conn.execute(

            """SELECT f.*, hc.name home_name, ac.name away_name

               FROM fixture f

               JOIN club hc ON hc.id=f.home_club_id

               JOIN club ac ON ac.id=f.away_club_id

               WHERE (f.home_club_id=1 OR f.away_club_id=1) AND f.played=0 AND f.fixture_date<=?

               ORDER BY f.fixture_date, f.matchday LIMIT 1""",

            (d,),

        ).fetchone()



    def advance_calendar_days(self, days=None):

        """Avance la date de carrière sans modifier le numéro de journée de match.



        On ne peut pas avancer le calendrier si un match du club attend d'être joué

        aujourd'hui : il faut d'abord le disputer. Une avance de plusieurs jours

        s'arrête aussi le jour du prochain match non joué.

        """

        conn = None

        try:

            if self.match_state and not self.match_state.get("finished", True):

                self.show_game_message("Calendrier", "Termine d'abord le match en cours.","warning")

                return

            # NOUVELLE SAISON : le bouton lancela bascule au 1er juillet.
            try:
                _c=db()
                _row=_c.execute("SELECT value FROM meta WHERE key='season_ready'").fetchone()
                _ready=bool(_row and _row["value"]=="1")
                _c.close()
            except Exception:
                _ready=False
            if _ready:
                self.start_new_season(); return



            conn = db()

            # Un match officiel est programme aujourd'hui ou est en retard : on le joue avant d'avancer.

            waiting = self._today_fixture_for_user(conn)

            if waiting:

                conn.close()

                conn = None

                self.show_game_message(

                    "Calendrier",

                    f"Un match vous attend aujourd'hui : {waiting['home_name']} vs {waiting['away_name']}.\n"

                    "Jouez-le avant d'avancer le calendrier.",

                    "warning",

                )

                return



            career = conn.execute('SELECT career."current_date" AS current_date FROM career WHERE id=1').fetchone()

            if career is None:

                raise RuntimeError("Carrière introuvable dans la base de données.")



            start_cd = parse_iso(career["current_date"])

            auto_mode = days is None

            days = 30 if auto_mode else max(1, min(30, int(days)))

            cd = start_cd

            conn.execute("BEGIN IMMEDIATE")

            for _ in range(days):

                ready_before=int(conn.execute("SELECT COUNT(*) n FROM manager_message WHERE status='ready' AND is_read=0").fetchone()["n"])

                cd += timedelta(days=1)

                conn.execute("UPDATE career SET current_date=? WHERE id=1", (cd.isoformat(),))

                if cd.weekday()==0 and self.preparateur_physique_hired:

                    existing=conn.execute("SELECT COUNT(*) n FROM training_session WHERE planned_date BETWEEN ? AND ? AND completed=0",(cd.isoformat(),(cd+timedelta(days=6)).isoformat())).fetchone()

                    if existing and int(existing["n"])==0:

                        pattern=[("Technique","Normale"),("Défense","Normale"),("Tactique","Faible"),("Repos","Normale"),("Finition","Normale"),("Récupération","Faible"),("Repos","Normale")]

                        for i,(activity,intensity) in enumerate(pattern):

                            pdate=(cd+timedelta(days=i)).isoformat()

                            conn.execute("INSERT INTO training_session(focus,intensity,quality,created_at,planned_date,activity_key,completed) VALUES(?,?,0,?,?,?,0)",

                                         (activity,intensity,career_timestamp(conn),pdate,activity))

                        self.apply_training_schedule(conn,cd.isoformat())

                        if getattr(self,"game_options",{}).get("msg_staff", True):

                            add_news(conn,"Préparateur physique","Le staff a planifié l'entraînement de la semaine (équilibré, avec deux jours de repos).")

                self.process_contract_expiries(conn,cd.isoformat())

                self.process_precontract_offers(conn,cd.isoformat())

                self.process_facility_projects(conn,cd.isoformat())
                try: complete_academy_dev_project(conn,cd.isoformat())
                except Exception: pass

                self.process_loan_repayments(conn,cd.isoformat())

                self.process_staff_payroll(conn,cd.isoformat())

                self.process_player_payroll(conn,cd.isoformat())

                self.process_ai_finances(conn,cd.isoformat())

                self.process_ai_transfer_market(conn,cd.isoformat())

                self.process_board_financial_watch(conn,cd.isoformat())

                self.process_staff_training(conn,cd.isoformat())

                self.process_sponsor_weekly(conn,cd.isoformat())

                self.process_facility_revenue(conn,cd.isoformat())

                self.process_league_distribution(conn,cd.isoformat())

                conn.execute("UPDATE player SET condition=MIN(100, condition+3) WHERE condition<100")

                # STAFF A EFFET REEL : adjoint (récupération), marketing (réputation),
                # directeur sportif (shortlist) — méthode dédiée pour être testable.

                self.process_daily_staff_effects(conn,cd.isoformat())

                if parse_iso(cd.isoformat()).weekday()==0:

                    # Filet de securite : un club ne doit jamais avoir deux fois le
                    # meme numero (recrutements IA, retours de pret, sauvegardes anciennes).
                    try: repair_shirt_numbers(conn)
                    except Exception: pass

                    # Libres : date d'entree sur le marche / nettoyage apres signature.
                    try:
                        conn.execute("""UPDATE player SET free_agent_since=? WHERE COALESCE(is_free_agent,0)=1
                                        AND COALESCE(free_agent_since,'')=''""",(cd.isoformat(),))
                        conn.execute("""UPDATE player SET free_agent_since='' WHERE COALESCE(is_free_agent,0)=0
                                        AND COALESCE(free_agent_since,'')<>''""")
                    except Exception: pass

                conn.execute("UPDATE player SET injury_days=MAX(0, injury_days-1) WHERE injury_days>0")

                conn.execute("UPDATE player SET suspension_days=MAX(0, suspension_days-1) WHERE suspension_days>0")

                self.process_player_birthdays(conn, cd.isoformat())

                self.apply_daily_background_events(conn, cd.isoformat())

                self.auto_delegate_training(conn,cd.isoformat())
                self.auto_delegate_ticket_price(conn,cd.isoformat())
                self.auto_delegate_scouting(conn,cd.isoformat())

                self.apply_training_schedule(conn,cd.isoformat())

                self.process_ai_recruitment(conn,cd.isoformat())

                self.process_ai_club_plans(conn,cd.isoformat())

                self.process_ai_squad_rebuild(conn,cd.isoformat())

                self.process_ai_training(conn,cd.isoformat())

                self.process_outgoing_loans(conn,cd.isoformat())

                self.process_autonomous_scouting(conn,cd.isoformat())
                self.process_monthly_scouting_digest(conn,cd.isoformat())

                self.process_due_manager_messages(conn,cd.isoformat())

                self.generate_transfer_interest(conn,cd.isoformat())

                # COUPE INTER-LIGUE : les confrontations IA de arrivées à 

                # échéance se jouent chaque jour ; le tour suivant est tiré quand

                # le tour courant est achevé (élimination directe).

                self._simulate_other_fixtures(conn,-1,today=cd.isoformat())

                ensure_cup_progress(conn,cd.isoformat())
                self.check_season_end(conn)
                self.maybe_open_new_season(conn,cd.isoformat())

                fixture = conn.execute(

                    """SELECT f.matchday, f.fixture_type, hc.name AS home_name, ac.name AS away_name

                       FROM fixture f

                       JOIN club hc ON hc.id=f.home_club_id

                       JOIN club ac ON ac.id=f.away_club_id

                       WHERE f.played=0 AND f.fixture_date=?

                         AND (f.home_club_id=1 OR f.away_club_id=1)

                       LIMIT 1""",

                    (cd.isoformat(),),

                ).fetchone()

                if fixture:

                    add_news(conn, "Matchday", f"Aujourd'hui : {fixture['home_name']} vs {fixture['away_name']} ({fixture_tag(fixture['matchday'],fixture['fixture_type'])})")



                # Évolution des prix des joueurs (stats, âge, performances)

                self.update_player_market_values(conn)

                # Messages de club vivants (transfert, entraînement, évolution de joueur…)

                if cd.weekday()==0:

                    self.generate_transfer_market_listings(conn, cd.isoformat())

                self.generate_live_club_messages(conn, cd.isoformat())

                self.generate_media_messages(conn, cd.isoformat())

                ready_after=int(conn.execute("SELECT COUNT(*) n FROM manager_message WHERE status='ready' AND is_read=0").fetchone()["n"])

                # Un match non joué est un point d'arrêt obligatoire (mode auto ET manuel) :

                # impossible de laisser la carrière dépasser un match officiel.

                if cd.weekday()==0:
                    self.process_player_development(conn,cd.isoformat())
                if fixture or cd.weekday()==0 or ready_after>ready_before:

                    if auto_mode:

                        break

                    # Mode manuel : on s'arrête sur le match à jouer, mais on laisse

                    # la journée continuer pour les événements vocabulaires suivants seulement si rien d'autre.

                    if fixture:

                        break



            # ARCHIVE ECONOME : les vieux messages resolus quittent la table

            # vivante pour la DB (lecture sur demande) — la RAM ne grimpe

            # plus avec l'age de la saison.

            archive_old_history(conn, cd.isoformat())

            conn.commit()

            new_date = cd.isoformat()

            advanced_days = (cd - start_cd).days

            # Mise à jour UI après commit : le calendrier ne doit pas avancer la journée sportive.

            self.refresh_all()

            if hasattr(self, "side_date_label"):

                self.side_date_label.setText(fmt_date_fr(new_date))

            if hasattr(self, "advance_status_label"):

                self.advance_status_label.setText(f"Date de carrière : {fmt_date_fr(new_date)}  ·  +{advanced_days} jour(s)")

        except Exception as e:

            if conn is not None:

                try:

                    conn.rollback()

                except sqlite3.Error:

                    pass

            self.log_error("advance_calendar_days", e)

            self.show_game_message("Calendrier",f"Erreur lors de l'avance du calendrier : {e}","error")

        finally:

            if conn is not None:

                conn.close()



    def update_player_market_values(self, conn):

        """Recalcule une valeur marchande cohérente pour TOUT le monde, avec dérive douce.



        La formule (compute_market_value) croise niveau, âge, potentiel, poste,

        performances, contrat, blessure, réputation du club, division, qualités

        futsal et moral. La valeur ne saute jamais : elle dérive vers la cible

        (25 % de l'écart par jour), comme une vraie cote de marché.

        """

        try:

            players=conn.execute("""SELECT p.*,c.division division_,c.reputation reputation_

                                    FROM player p LEFT JOIN club c ON c.id=p.club_id""").fetchall()

            # Mises a jour collectees puis appliquees en 2 ordres groupés

            # (executemany) : la boucle quotidienne reste fluide meme avec ~1000 joueurs.

            mv_updates=[]

            sal_updates=[]

            for p in players:

                division=int(p["division_"] or 3)

                target=compute_market_value_from_row(p,division,int(p["reputation_"] or 20))

                mv=int(p["market_value"] or 0)

                if mv<=0:

                    new_mv=target

                elif mv>target*12 or mv<target/12:

                    new_mv=round_money(target)  # cote absurde (>12x la cible) : correction immediate

                else:

                    new_mv=round_money(int(mv+(target-mv)*0.25))

                if int(p["is_free_agent"] or 0):

                    new_mv=round_money(target)  # un libre suit la cote du marché immédiatement

                if new_mv!=mv and new_mv>0:

                    mv_updates.append((max(2500,new_mv),p["id"]))

                # Convergence salariale : les joueurs IA retrouvent un salaire cohérent

                # avec leur niveau ; celui des joueurs du club n'est jamais forcé.

                sal=self._converge_ai_salary(p,division)

                if sal is not None:

                    sal_updates.append((sal,p["id"]))

            if mv_updates:

                conn.executemany("UPDATE player SET market_value=? WHERE id=?",mv_updates)

            if sal_updates:

                conn.executemany("UPDATE player SET salary=? WHERE id=?",sal_updates)

        except Exception as e:

            self.log_error("update_player_market_values", e)



    def _converge_ai_salary(self,p,division):

        """Moyenne doucement le salaire des joueurs IA vers le barème de référence.



        Version pure : renvoie le salaire candidat (ou None) — l'écriture est

        batchée par l'appelant."""

        try:

            if int(p["club_id"])==1 or int(p["is_free_agent"] or 0):

                return None

            level=player_level_from_row(p)

            fair=compute_fair_salary(level,division,int(p["age"]),player_potential_from_row(p))

            salary=int(p["salary"] or 0)

            if fair<=0 or salary<=0:

                return None

            raw=int(salary+(fair-salary)*0.04)

            new_salary=round_money(raw)

            if new_salary==salary and abs(fair-salary)>200:

                new_salary=max(500,raw)  # progresse meme si le palier d'arrondi buche

            if salary>fair*5 or salary<fair/5:

                new_salary=round_money(fair)  # cote aberrante (5x le bareme) : alignement direct

            if new_salary!=salary and new_salary>=500:

                return new_salary

            return None

        except Exception as e:

            self.log_error("_converge_ai_salary", e)

            return None



    def process_player_birthdays(self, conn, current_iso_date):

        """Controle quotidien global : chaque joueur du monde fete son anniversaire le jour voulu

        (age +1 et declins physiques aplicables), les messages restent limites au club du manager."""

        try:

            today = parse_iso(current_iso_date)

            rows = conn.execute("SELECT id,club_id,first_name,last_name,age,birth_date FROM player WHERE birth_date IS NOT NULL").fetchall()

            for p in rows:

                birthday = parse_iso(p["birth_date"])

                if birthday.month == today.month and birthday.day == today.day:

                    new_age = int(p["age"] or 0) + 1

                    pid = int(p["id"])

                    conn.execute("UPDATE player SET age=? WHERE id=?", (new_age, pid))

                    is_manager_club = int(p["club_id"] or 0) == 1

                    message = f"🎂 {p['first_name']} {p['last_name']} fête ses {new_age} ans."

                    deltas = age_decline_deltas(new_age)

                    if deltas:

                        labels={"stamina":"endurance","technique":"technique","passing":"passes","finishing":"finition","defense":"défense"}

                        sets=",".join(f"{k}=MAX(10,{k}+({v}))" for k,v in deltas.items())

                        conn.execute(f"UPDATE player SET {sets} WHERE id=?", (pid,))

                        detail=" • ".join(f"{labels[k]} {v:+d}" for k,v in deltas.items())

                        message += f"  L'âge se fait sentir : {detail}."

                    if is_manager_club:

                        # Filtre MESSAGERIE (options) : les anniversaires restent traités

                        # (age, déclins) mais leurs messages peuvent être éteints.

                        if getattr(self,"game_options",{}).get("msg_anniversaire", False):

                            add_news(conn, "Anniversaire", message)

                            conn.execute("INSERT INTO manager_message(kind,title,body,created_date,due_date,status,action_data,is_read) VALUES('club_news',?,?,?,?, 'ready','{}',0)",

                                         ("Anniversaire joueur", f"{p['first_name']} {p['last_name']} fête ses {new_age} ans.", current_iso_date, current_iso_date))

        except Exception as e:

            self.log_error("process_player_birthdays", e)



    def process_league_distribution(self,conn,current_iso_date):

        """Dotations mensuelles de la ligue : droits TV versés le 1er du mois selon la division."""

        try:

            if parse_iso(current_iso_date).day != 1: return

            club=conn.execute("SELECT division FROM club WHERE id=1").fetchone()

            if not club: return

            division=max(1,min(6,int(club["division"] or 3)))

            # Plancher de 4 000 €/mois : la dotation TV doit couvrir une part

            # realiste de la masse salariale des petites divisions (les salaires

            # sont preleves chaque mois depuis la reforme de la paie).

            amount=4000+6500*max(1,7-division)

            conn.execute("UPDATE club SET budget=budget+? WHERE id=1",(amount,))

            conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",

                         (f"Droits TV & dotations • Ligue {division}",amount,career_timestamp(conn),"Diffusion"))

            add_news(conn,"Dotations",f"Versement mensuel des droits TV de la Ligue {division} : +{amount:,} €.".replace(","," "))

        except Exception as exc:

            self.log_error("process_league_distribution",exc)



    def process_player_development(self,conn,current_iso_date):
        """ÉVOLUTION CONTINUE DES JOUEURS (retour « +1 à l'entraînement mais
        fiche statique ») : chaque lundi, chaque joueur accumule des POINTS de
        progression fractionnaires. Quand un point est complet, l'attribut
        adapté gagne +1 : la fiche bouge donc régulièrement, pas seulement
        quand le hasard d'une séance le veut.

        Facteurs : âge, écart au potentiel, niveau du centre de formation,
        temps de jeu, assiduité à l'entraînement et moral. Après 29 ans, une
        RÉGRESSION progressive touche les qualités physiques."""
        try:
            conn.execute("""CREATE TABLE IF NOT EXISTS player_dev_progress(
                                player_id INTEGER PRIMARY KEY,
                                points REAL NOT NULL DEFAULT 0,
                                regress REAL NOT NULL DEFAULT 0,
                                updated_date TEXT)""")
            today=parse_iso(current_iso_date)
            try:
                _squad_now=int(conn.execute("SELECT COUNT(*) n FROM player WHERE club_id=1 AND COALESCE(is_free_agent,0)=0").fetchone()["n"] or 0)
                if 0<_squad_now<12:
                    self.maintain_minimum_squad(conn,12)
            except Exception:
                pass

            # niveau du centre du club manager (les clubs IA n'en ont pas)
            try:
                youth=int(conn.execute("SELECT youth_level FROM facility WHERE id=1").fetchone()["youth_level"] or 1)
            except Exception:
                youth=1
            academy=0.55+0.06*max(1,min(8,youth))     # 0.61 … 1.03
            trained=set()
            for r in conn.execute("""SELECT DISTINCT player_id FROM player_training_log
                                     WHERE created_at>=?""",((today-timedelta(days=21)).isoformat(),)).fetchall():
                trained.add(int(r["player_id"]))
            rows=conn.execute("""SELECT p.*,c.division club_division FROM player p JOIN club c ON c.id=p.club_id
                                 WHERE p.is_free_agent=0""").fetchall()
            attr_by_pos={
                "Gardien":(("goalkeeper",.50),("positioning",.20),("passing",.15),("technique",.10),("stamina",.05)),
                "Défenseur":(("defense",.42),("positioning",.20),("stamina",.16),("passing",.12),("technique",.10)),
                "Ailier":(("dribble",.30),("speed",.24),("technique",.18),("finishing",.16),("stamina",.12)),
                "Pivot":(("finishing",.34),("positioning",.24),("technique",.18),("defense",.14),("stamina",.10)),
                "Universel":(("technique",.24),("passing",.22),("positioning",.20),("stamina",.18),("defense",.16)),
            }
            for p in rows:
                pid=int(p["id"]); age=int(p["age"] or 24)
                level=player_level_from_row(p); potential=player_potential_from_row(p)
                room=max(0,potential-level)
                own=(int(p["club_id"])==1)
                # courbe d'âge : forte chez les jeunes, nulle après 32
                age_growth=1.45 if age<=18 else 1.15 if age<=21 else 0.85 if age<=25 else 0.50 if age<=28 else 0.20 if age<=31 else 0.0
                room_factor=max(0.30,min(1.9,0.35+0.32*room))
                matches=int(p["season_matches"] or 0)
                play_factor=0.72+0.28*min(1.0,matches/10.0)
                train_factor=1.15 if pid in trained else 0.80
                morale_factor=0.82+0.30*(int(p["morale"] or 60)/100.0)
                academy_factor=academy if own else (0.62+0.05*max(1,int(p["club_division"] or 6)))
                # JEUNES DU CLUB (-18 ans) : le centre de formation amplifie la
                # progression au-delà de l'entraînement collectif.
                if own and age<18:
                    academy_factor*=1.0+0.10*max(0,youth-1)
                # Calibration : un jeune à fort potentiel gagne ~1 note /20
                # toutes les 6 à 8 semaines ; un senior ~+0.7/saison.
                gain=0.95*age_growth*room_factor*play_factor*train_factor*morale_factor*academy_factor
                if own and age<=21:
                    try:
                        mentor=conn.execute("SELECT 1 FROM player WHERE club_id=1 AND age>=30 AND (technique+passing+defense+finishing)/4>=65 LIMIT 1").fetchone()
                        if mentor: gain*=1.06
                    except Exception:
                        pass
                if age<=20 and room>=4: gain*=1.30
                if age_growth<=0: gain=0.0
                prog=conn.execute("SELECT points,regress FROM player_dev_progress WHERE player_id=?",(pid,)).fetchone()
                pts=float(prog["points"] or 0) if prog else 0.0
                reg=float(prog["regress"] or 0) if prog else 0.0
                pts+=gain
                attr_plan=attr_by_pos.get(str(p["position"]),attr_by_pos["Universel"])
                _pfocus=str(p["training_focus"] or "") if "training_focus" in p.keys() else ""
                if _pfocus:
                    attr_plan=tuple((a,w*(2.4 if a==_pfocus else 1.0)) for a,w in attr_plan)
                    if _pfocus not in [a for a,_w in attr_plan]:
                        attr_plan=attr_plan+((_pfocus,.55),)
                    gain*=1.04
                cap=potential*5
                applied=[]
                while pts>=1.0:
                    pts-=1.0
                    # attribut choisi au hasard pondéré, seulement s'il reste de la marge
                    choices=[(a,w) for a,w in attr_plan if int(p[a] or 0)<cap]
                    if not choices:
                        # repli : tout attribut encore perfectible (un gardien
                        # dont les arrêts sont au plafond progresse ailleurs)
                        fallback=[("technique",.22),("passing",.20),("positioning",.18),
                                  ("speed",.14),("dribble",.14),("defense",.12)]
                        choices=[(a,w) for a,w in fallback if int(p[a] or 0)<cap and a!="goalkeeper"]
                    if not choices: pts=0.0; break
                    total_w=sum(w for _,w in choices)
                    pick=random.uniform(0,total_w); acc=0.0; attr=choices[-1][0]
                    for a,w in choices:
                        acc+=w
                        if pick<=acc: attr=a; break
                    conn.execute(f"UPDATE player SET {attr}=MIN(?,{attr}+1) WHERE id=?",(cap,pid))
                    applied.append(attr)
                    conn.execute("INSERT INTO player_training_log(player_id,attribute_key,delta,activity_key,created_at) VALUES(?,?,1,'Développement',?)",
                                 (pid,attr,current_iso_date))
                # RÉGRESSION : 29 ans et plus, qualités physiques d'abord
                if age>=29:
                    reg+= (0.75 if age>=34 else 0.60 if age>=32 else 0.45 if age>=31 else 0.32)
                    while reg>=1.0:
                        reg-=1.0
                        decline={"stamina":.55,"speed":.30,"positioning":.15}
                        pick=random.uniform(0,1.0); acc=0.0; attr="stamina"
                        for a,w in decline.items():
                            acc+=w
                            if pick<=acc: attr=a; break
                        conn.execute(f"UPDATE player SET {attr}=MAX(20,{attr}-1) WHERE id=?",(pid,))
                        conn.execute("INSERT INTO player_training_log(player_id,attribute_key,delta,activity_key,created_at) VALUES(?,?,-1,'Vieillissement',?)",
                                     (pid,attr,current_iso_date))
                        applied.append(attr+"-")
                conn.execute("""INSERT INTO player_dev_progress(player_id,points,regress,updated_date) VALUES(?,?,?,?)
                                ON CONFLICT(player_id) DO UPDATE SET points=excluded.points,regress=excluded.regress,updated_date=excluded.updated_date""",
                             (pid,pts,reg,current_iso_date))
                if applied and own:
                    new_level=player_level_from_row(conn.execute("SELECT * FROM player WHERE id=?",(pid,)).fetchone())
                    if new_level!=level:
                        add_news(conn,"Évolution joueur",
                                 f"{p['first_name']} {p['last_name']} : niveau {level}/20 → {new_level}/20 ({', '.join(a.rstrip('-')+(' ▼' if a.endswith('-') else ' ▲') for a in applied)}).")
        except Exception as exc:
            self.log_error("player_development",exc)

    def process_daily_staff_effects(self,conn,current_iso_date):

        """Effets quotidiens vérifiables du staff :

        - ADJOINT : récupération supplémentaire (+1 forme par niveau et par jour) ;
        - RESPONSABLE MARKETING : réputation +1 (et +1 tous les 2 niveaux) le lundi ;
        - DIRECTEUR SPORTIF : connaissance de la shortlist +2 par niveau le lundi."""

        try:

            adjoint=conn.execute("SELECT value FROM meta WHERE key='adjoint_hired'").fetchone()

            if adjoint and adjoint["value"]=="1":

                _adj_lv=self.staff_level(conn,"adjoint_hired")
                conn.execute("UPDATE player SET condition=MIN(100, condition+?) WHERE club_id=1 AND condition<100",(_adj_lv,))

            if parse_iso(str(current_iso_date)).weekday()==0:

                mkt=conn.execute("SELECT value FROM meta WHERE key='marketing_hired'").fetchone()

                if mkt and mkt["value"]=="1":

                    _mkt_lv=self.staff_level(conn,"marketing_hired")
                    _mkt_gain=1+(_mkt_lv-1)//2
                    conn.execute("UPDATE club SET reputation=MIN(100,reputation+?) WHERE id=1",(_mkt_gain,))

                dsd=conn.execute("SELECT value FROM meta WHERE key='directeur_sportif_hired'").fetchone()

                if dsd and dsd["value"]=="1":

                    self._director_scout_bump(conn,str(current_iso_date))

        except Exception as exc:

            self.log_error("daily_staff_effects",exc)



    def _director_scout_bump(self,conn,current_iso_date):

        """Directeur sportif : chaque lundi, il nourrit l'observation de la shortlist.

        +2 points de connaissance par niveau sur les cibles les moins connues,

        jusqu'à 2 cibles par niveau (il fait travailler plusieurs dossiers de front)."""

        try:

            level=self.staff_level(conn,"directeur_sportif_hired")

            gain=2*level

            limit=max(1,min(10,2*level))

            rows=conn.execute("""SELECT s.player_id,COALESCE(sr.knowledge,0) knowledge

                                 FROM shortlist s

                                 LEFT JOIN scout_report sr ON sr.player_id=s.player_id

                                 ORDER BY COALESCE(sr.knowledge,0) ASC, s.added_date ASC

                                 LIMIT ?""",(limit,)).fetchall()

            for row in rows:

                if int(row["knowledge"] or 0)>=100: continue

                new_k=min(100,int(row["knowledge"] or 0)+gain)

                conn.execute("""INSERT INTO scout_report(player_id,knowledge,reports,updated_date)

                                VALUES(?,?,1,?)

                                ON CONFLICT(player_id) DO UPDATE SET

                                  knowledge=?,

                                  updated_date=excluded.updated_date""",

                             (int(row["player_id"]),new_k,current_iso_date,new_k))

        except Exception as exc:

            self.log_error("director_scout_bump",exc)



    def process_staff_payroll(self, conn, current_iso_date):

        """Prélève les salaires mensuels du staff le premier jour du mois.

        Le COMPTABLE optimise la paie (4 % au niveau 1, +2 % par niveau, 12 % au 5)

        et place la trésorerie positive (0,15 % par niveau, plafonné)."""

        try:

            if parse_iso(current_iso_date).day != 1: return

            comptable=conn.execute("SELECT value FROM meta WHERE key='comptable_hired'").fetchone()

            # RABAIS PROGRESSIF : 4 % au niveau 1, +2 % par niveau (12 % au 5).
            _discount=1.0
            if comptable and comptable["value"]=="1":
                _discount=1.0-min(0.12,0.04+0.02*(self.staff_level(conn,"comptable_hired")-1))

            total=0; labels=[]

            for key in self.STAFF_BASE_SALARY:

                row=conn.execute("SELECT value FROM meta WHERE key=?",(key,)).fetchone()

                if row and row["value"]=="1":

                    total+=self.staff_effective_salary(conn,key)

                    labels.append(self.STAFF_TITLES.get(key,key.replace("_hired","").replace("_"," ")))

            if total:

                total=int(round(total*_discount/50))*50

                conn.execute("UPDATE club SET budget=budget-? WHERE id=1",(total,))

                conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",(f"Salaires du staff · mois {parse_iso(current_iso_date).month:02d} (paie mensuelle)",-total,career_timestamp(conn),"Salaire"))

                add_news(conn,"Masse salariale staff",f"Salaires mensuels du staff : {total:,} € ({', '.join(labels)}).".replace(","," "))

            if comptable and comptable["value"]=="1":

                placement=self.comptable_placement_monthly(conn)

                if placement>0:

                    conn.execute("UPDATE club SET budget=budget+? WHERE id=1",(placement,))

                    conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",(f"Placements du comptable · mois {parse_iso(current_iso_date).month:02d} (trésorerie placée)",placement,career_timestamp(conn),"Placement"))

        except Exception as e:

            self.log_error("process_staff_payroll",e)



    def process_player_payroll(self, conn, current_iso_date):

        """Prélève les salaires mensuels des joueurs le 1er du mois.



        Les salaires ne sont PLUS prépayés sur toute la durée du contrat à la

        signature : ils font partie des charges mensuelles, comme le staff.

        Migration douce : les contrats signés AVANT la réforme ont déjà été

        prélevés d'un coup (ancienne règle) — ils sont exclus de la paie

        mensuelle jusqu'à leur prochaine prolongation."""

        try:

            if parse_iso(current_iso_date).day != 1: return

            reform=conn.execute("SELECT value FROM meta WHERE key='payroll_reform_season'").fetchone()

            prepaid=set()

            if not reform:

                # Première paie sous la nouvelle règle : les contrats en cours

                # étaient pré-escomptés. On les marque pour ne pas payer deux fois.

                conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('payroll_reform_season',?)",

                             (str(int(conn.execute("SELECT season FROM club WHERE id=1").fetchone()["season"] or 1)),))

                ids=[int(r["id"]) for r in conn.execute("SELECT id FROM player WHERE club_id=1 AND COALESCE(is_free_agent,0)=0").fetchall()]

                conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('prepaid_wage_ids',?)",(json.dumps(ids),))

                # Ces contrats ont DEJA ete payes d'avance sous l'ancienne regle :
                # on les exclut de la premiere paie mensuelle (le set local etait
                # reste vide, donc la migration facturait une seconde fois).
                prepaid=set(ids)

            else:

                row=conn.execute("SELECT value FROM meta WHERE key='prepaid_wage_ids'").fetchone()

                try: prepaid=set(int(x) for x in json.loads(row["value"]) if True) if row else set()

                except (ValueError,TypeError): prepaid=set()

            rows=conn.execute("SELECT id,salary FROM player WHERE club_id=1 AND COALESCE(is_free_agent,0)=0").fetchall()

            total=0; labelled=[]

            for r in rows:

                pid=int(r["id"])

                if pid in prepaid: continue

                sal=int(r["salary"] or 0)

                if sal>0: total+=sal; labelled.append(pid)

            if total:

                conn.execute("UPDATE club SET budget=budget-? WHERE id=1",(total,))

                conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",

                             (f"Salaires des joueurs · mois {parse_iso(current_iso_date).month:02d} (masse salariale, chargé chaque mois)",-total,career_timestamp(conn),"Salaire"))

        except Exception as e:

            self.log_error("process_player_payroll",e)



    def process_board_financial_watch(self, conn, current_iso_date):

        """Regard quotidien du board sur la trésorerie : la chaîne de banqueroute.



        Niveau 1 — passage dans le rouge : alerte du board ET embargo implicite

        (les signatures, prêts et chantiers vérifient le budget au moment de la

        dépense, donc un club déficitaire ne peut plus creuser).

        Niveau 2 — 60 jours consécutifs dans le rouge, puis tous les 60 jours :

        le board FORCE la mise en vente du joueur le plus dispendieux pour

        renflouer la caisse (plan de redressement ; jamais sous un noyau de 8).

        Niveau 3 — à la clôture de saison, la réputation est pénalisée

        (process_reputation_update : −1,2 à −2,5 selon la profondeur du rouge).

        Réaliste sans être frustrant : vendre reste possible et le prêt

        redevient accessible au retour au vert."""

        try:

            row=conn.execute("SELECT budget FROM club WHERE id=1").fetchone()

            if row is None: return

            budget=int(row["budget"] or 0)

            red=0

            meta=conn.execute("SELECT value FROM meta WHERE key='club1_red_days'").fetchone()

            try: red=int(meta["value"] or 0) if meta else 0

            except (ValueError,TypeError): red=0

            if budget>=0:

                if red:

                    conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('club1_red_days','0')")

                    add_news(conn,"Retour au vert",f"La trésorerie est repassée au-dessus de zéro ({budget:,} €) : embargo levé, le board respire.".replace(","," "))

                return

            red+=1

            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('club1_red_days',?)",(str(red),))

            if red==1:

                add_news(conn,"Trésorerie négative",

                         f"Le budget est passé sous zéro ({budget:,} €). Le board déclenche l'embargo : aucune dépense tant que la trésorerie n'est pas revenue au vert (recrutement, prêt, chantiers).".replace(","," "))

            elif red>=60 and (red-60)%60==0:

                n=int(conn.execute("SELECT COUNT(*) n FROM player WHERE club_id=1").fetchone()["n"] or 0)

                if n<=8: return

                victim=conn.execute("""SELECT id,first_name,last_name,market_value FROM player

                                       WHERE club_id=1 AND COALESCE(transfer_listed,0)=0

                                       ORDER BY COALESCE(market_value,0) DESC LIMIT 1""").fetchone()

                if victim:

                    conn.execute("UPDATE player SET transfer_listed=1 WHERE id=?",(int(victim["id"]),))

                    add_news(conn,"Plan de redressement",

                             f"Le board force la mise en vente de {victim['first_name']} {victim['last_name']} (valeur {int(victim['market_value'] or 0):,} €) pour renflouer la trésorerie ({budget:,} €) — négatif depuis {red} jours.".replace(","," "))

        except Exception as e:

            self.log_error("process_board_financial_watch",e)



    def _prepaid_wage_discard(self, player_id, conn=None):

        """Après la réforme de paie, un joueur prolongé est payé au mois :

        on le sort du pool des salaires pré-escomptés (ancienne règle).



        AJAX IMPORTANT : la connexion du flux appelant est réutilisée quand elle

        est fournie — ouvrir une SECONDE connexion en écriture alors que le

        flux appelant retient des écritures non commitées provoque

        "database is locked" (vu en carrière longue)."""

        try:

            own=conn is None

            if own: conn=db()

            row=conn.execute("SELECT value FROM meta WHERE key='prepaid_wage_ids'").fetchone()

            if not row:

                if own: conn.close()

                return False

            try: ids=[int(x) for x in json.loads(row["value"])]

            except (ValueError,TypeError): ids=[]

            if player_id not in ids:

                if own: conn.close()

                return False

            ids=[i for i in ids if i!=player_id]

            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('prepaid_wage_ids',?)",(json.dumps(ids),))

            if own: conn.commit(); conn.close()

            return True

        except Exception as e:

            self.log_error("_prepaid_wage_discard",e); return False



    def process_autonomous_scouting(self, conn, current_iso_date):

        """Le recruteur travaille seul :

        1) priorite a la shortlist : chaque jour, la cible epinglee la plus ancienne sans

           rapport complet ni mission part en supervision STANDARD gratuite. Quand les

           slots simultanes sont satures, la mission prend +2 jours (file du recruteur).

        2) sinon, veille aleatoire sur le marche quand des slots restent libres."""

        try:

            meta=conn.execute("SELECT value FROM meta WHERE key='scout_level'").fetchone()

            level=int(meta["value"] or 0) if meta else 0

            if level<=0: return

            active=int(conn.execute("SELECT COUNT(*) n FROM manager_message WHERE kind='scout_report' AND status='waiting'").fetchone()["n"])

            busy=set()

            for w_ in conn.execute("SELECT action_data FROM manager_message WHERE kind='scout_report' AND status='waiting'").fetchall():

                try: busy.add(int(json.loads(w_["action_data"] or "{}").get("player_id",0)))

                except (ValueError,TypeError): continue

            # --- 1) Auto-supervision des cibles epinglees (une nouvelle mission par jour max).

            sl_rows=conn.execute("""SELECT s.player_id AS sid,p.first_name,p.last_name,

                                           COALESCE(sr.knowledge,0) knowledge,COALESCE(sr.reports,0) reports

                                    FROM shortlist s

                                    JOIN player p ON p.id=s.player_id

                                    LEFT JOIN scout_report sr ON sr.player_id=p.id

                                    ORDER BY s.added_date ASC""").fetchall()

            for target in sl_rows:

                pid=int(target["sid"] or 0)

                if pid in busy: continue

                if int(target["knowledge"] or 0)>=100: continue

                if int(active)>=level+4: break  # file plafinee pour les missions automatiques

                queue_delay=2*max(0,active-level+1)

                days=max(1,4-level)+queue_delay

                due=(parse_iso(current_iso_date)+timedelta(days=days)).isoformat()

                name=f"{target['first_name']} {target['last_name']}"

                queue_txt=f" (file d'attente du recruteur : +{queue_delay} jour(s))" if queue_delay else ""

                body=(f"Le recruteur prend en charge l'observation de {name} ({target['knowledge']} %), epingle dans ta shortlist."

                      f" Mission standard{queue_txt}. Rapport attendu le {fmt_date_fr(due)}.")

                queue_manager_message(conn,"scout_report","Auto-supervision shortlist",body,current_iso_date,due,

                                      {"player_id":pid,"previous_knowledge":int(target["knowledge"] or 0),"reports":int(target["reports"] or 0),

                                       "effort":"standard","scout_level":level,

                                       "gain":scout_gain_for(pid,int(target["reports"] or 0),level,"standard"),

                                       "accuracy":scout_accuracy_for(pid,int(target["reports"] or 0),level,"standard")},

                                      is_read=False)

                add_news(conn,"Scouting",body)

                active+=1; busy.add(pid)

                break  # une seule nouvelle auto-supervision par jour : la file suit la charge

            # --- 2) Veille aleatoire si des slots restent libres.

            if int(active)<level and random.random()<=min(.75,.18+level*.10):

                target=conn.execute("""SELECT p.id,p.first_name,p.last_name,COALESCE(sr.knowledge,0) knowledge,COALESCE(sr.reports,0) reports

                                      FROM player p LEFT JOIN scout_report sr ON sr.player_id=p.id

                                      WHERE p.club_id<>1 AND COALESCE(p.retired,0)=0 AND p.is_free_agent=0 AND COALESCE(sr.knowledge,0)<100

                                      ORDER BY RANDOM() LIMIT 1""").fetchone()

                if target:

                    current=parse_iso(current_iso_date); due=(current+timedelta(days=max(1,4-level))).isoformat()

                    name=f"{target['first_name']} {target['last_name']}"

                    body=f"Le recruteur a repéré {name} et lance une observation automatique. Rapport prévu le {fmt_date_fr(due)}."

                    queue_manager_message(conn,"scout_report","Veille scouting : nouvelle cible",body,current_iso_date,due,

                                          {"player_id":target["id"],"previous_knowledge":int(target["knowledge"] or 0),"reports":int(target["reports"] or 0),

                                           "effort":"standard","scout_level":level,

                                           "gain":scout_gain_for(target["id"],int(target["reports"] or 0),level,"standard"),

                                           "accuracy":scout_accuracy_for(target["id"],int(target["reports"] or 0),level,"standard")},

                                          is_read=False)

                    add_news(conn,"Scouting",body)

        except Exception as e:

            self.log_error("process_autonomous_scouting",e)



    def process_youth_intakes(self, conn, new_season):

        """Vivier de la cloture : un jeune par club majoritairement, relache d'un ainé si

        l'effectif depasse le plafond. Cote manager, le centre de formation (niveau >=1)

        ouvre le droit a son propre prospect — l'infrastructure a donc un moteur reel."""

        try:

            averages={1:77,2:70,3:63,4:56,5:49,6:42}

            base_positions=("Défenseur","Défenseur","Ailier","Ailier","Pivot","Universel")

            modifiers={"Gardien":{"technique":-5,"passing":-2,"finishing":-18,"defense":4,"goalkeeper":20,"stamina":0,"dribble":-12,"speed":-2,"positioning":14},

                       "Défenseur":{"technique":-2,"passing":1,"finishing":-8,"defense":14,"goalkeeper":-35,"stamina":5,"dribble":2,"speed":4,"positioning":10},

                       "Ailier":{"technique":10,"passing":5,"finishing":4,"defense":-5,"goalkeeper":-40,"stamina":8,"dribble":14,"speed":14,"positioning":4},

                       "Pivot":{"technique":3,"passing":-2,"finishing":14,"defense":-4,"goalkeeper":-40,"stamina":2,"dribble":10,"speed":-2,"positioning":8},

                       "Universel":{"technique":3,"passing":5,"finishing":2,"defense":2,"goalkeeper":-40,"stamina":5,"dribble":6,"speed":6,"positioning":6}}

            created=[]

            def _make(cid,division,label):

                has_gk=int(conn.execute("SELECT COUNT(*) n FROM player WHERE club_id=? AND is_free_agent=0 AND position='Gardien'",(cid,)).fetchone()["n"])

                position="Gardien" if not has_gk else random.choice(base_positions)

                age=random.randint(16,18)

                base=averages[division]*0.80
                if cid!=1:
                    try:
                        from club_profiles import youth_multiplier
                        base*=youth_multiplier(conn,cid)
                    except Exception:
                        pass
                if cid==1:
                    try:
                        _yl=int(conn.execute("SELECT youth_level FROM facility WHERE id=1").fetchone()["youth_level"] or 1)
                        base*=1.0+0.02*max(0,_yl-1)
                    except Exception:
                        pass

                attributes={key:max(15,min(98,int(round(random.gauss(base+offset,6))))) for key,offset in modifiers[position].items()}

                probe=dict(attributes); probe["position"]=position

                level=player_level_from_row(probe); potential=player_potential_from_row({**probe,"age":age})

                salary=compute_fair_salary(level,division,age,potential)

                club=conn.execute("SELECT reputation FROM club WHERE id=?",(cid,)).fetchone()

                value=compute_market_value(level,age,potential,position,division,int(club["reputation"] or 20),contract_years=3)

                first,last,nat=random_player_name()

                shirt=int(conn.execute("SELECT COALESCE(MAX(shirt_number),0) v FROM player WHERE club_id=?",(cid,)).fetchone()["v"])+1

                conn.execute("""INSERT INTO player(club_id,first_name,last_name,age,position,technique,passing,finishing,defense,goalkeeper,stamina,condition,morale,nationality,salary,contract_years,market_value,is_free_agent,shirt_number,dribble,speed,positioning,potential_fixed)

                               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,3,?,0,?,?,?,?,?)""",

                              (cid,first,last,age,position,attributes["technique"],attributes["passing"],attributes["finishing"],attributes["defense"],

                               attributes["goalkeeper"],attributes["stamina"],random.randint(85,100),random.randint(62,84),

                               nat,salary,value,shirt,attributes["dribble"],attributes["speed"],attributes["positioning"],potential))

                pid=int(conn.execute("SELECT id FROM player ORDER BY id DESC LIMIT 1").fetchone()["id"])

                set_birth_date(conn,pid,age,career_year_of(conn))

                record_player_history(conn,pid,cid,"formation",f"Centre de formation {label}")

                return (first,last,age,position,level,potential)

            for club in conn.execute("SELECT id,name,division FROM club WHERE id<>1").fetchall():

                cid=int(club["id"]); division=max(1,min(6,int(club["division"] or 3)))

                size=int(conn.execute("SELECT COUNT(*) n FROM player WHERE club_id=? AND is_free_agent=0",(cid,)).fetchone()["n"])

                if size<5: continue  # la consolidation a deja refait la cohorte

                if random.random()>(0.62 if size<11 else 0.50): continue

                world=int(conn.execute("SELECT COUNT(*) v FROM player").fetchone()["v"])

                if world>=720 and size>=12: continue  # pas d'inflation du monde : un plein reste plein

                made=_make(cid,division,club["name"])

                created.append(made)

                if size+1>12:

                    senior=conn.execute("""SELECT id FROM player WHERE club_id=? AND is_free_agent=0 AND age>=30

                                           ORDER BY age DESC,(technique+passing+finishing+defense+goalkeeper+stamina) ASC LIMIT 1""",(cid,)).fetchone()

                    if senior:

                        srow=conn.execute("SELECT age FROM player WHERE id=?",(int(senior["id"]),)).fetchone()

                        age=int(srow["age"] or 30)

                        if age>=34:

                            conn.execute("DELETE FROM player WHERE id=?",(int(senior["id"]),))

                            record_player_history(conn,int(senior["id"]),0,"retraite","Fin de carriere")

                        else:

                            conn.execute("UPDATE player SET is_free_agent=1,contract_years=0 WHERE id=?",(int(senior["id"]),))

                            record_player_history(conn,int(senior["id"]),0,"free_agent","Premier contrat — élargi du groupe professionnel")

                    else:

                        fallback=conn.execute("""SELECT id FROM player WHERE club_id=? AND is_free_agent=0

                                                 ORDER BY (technique+passing+finishing+defense+goalkeeper+stamina) ASC,age ASC LIMIT 1""",(cid,)).fetchone()

                        if fallback:

                            conn.execute("UPDATE player SET is_free_agent=1,contract_years=0 WHERE id=?",(int(fallback["id"]),))

                            record_player_history(conn,int(fallback["id"]),0,"free_agent","Quitte le groupe professionnel")

            # Vivier du manager : remplace par le moteur du centre de formation (process_academy_intake).

            if created:

                summary=" ; ".join(f"{f} {l} ({age} ans, {pos})" for f,l,age,pos,_,_ in created[:4])

                add_news(conn,"Vivier",f"Les autres clubs présentent {len(created)} jeune(s) cette saison : {summary}…")

        except sqlite3.Error as exc:

            self.log_error("youth_intakes",exc)



    ACADEMY_POSITION_POOL=("Défenseur","Défenseur","Ailier","Ailier","Pivot","Universel")



    def process_academy_intake(self, conn, new_season):

        """Génération annuelle du centre de formation : un groupe de 1 à 3 jeunes

        (taille liée au niveau du centre), dont la QUALITÉ suit la note du centre

        (infrastructure, préparateur, recruteur, pôle médical) — sans pépite garantie.



        Profils variés : âge 15-17, archétype technique/athlétique/buteur…,

        précoce (fort tout de suite, plafond plus bas) ou tardif (grain à

        semer, plafond plus haut). Chaque prospect est gravé dans player_history :

        le manager peut suivre ses promotions dans la durée."""

        try:

            if not academy_unlocked(conn):

                # Centre non ouvert : aucune promotion de jeunes (verrou majeur).

                return

            profile=academy_profile(conn)

            grade=int(profile["total"])

            # Investissement engagé dans la saison : +8 points pour UNE génération.

            invested=conn.execute("SELECT value FROM meta WHERE key='academy_invest_season'").fetchone()

            club_season=conn.execute("SELECT season FROM club WHERE id=1").fetchone()

            boost=0

            if invested and club_season and int(invested["value"] or 0)==int(club_season["season"] or 0):

                boost=8

            grade_eff=min(100,grade+boost)

            youth=int(profile["youth_level"] or 1)

            n=academy_group_size(youth)

            averages={1:77,2:70,3:63,4:56,5:49,6:42}

            modifiers={"Gardien":{"technique":-5,"passing":-2,"finishing":-18,"defense":4,"goalkeeper":20,"stamina":0,"dribble":-12,"speed":-2,"positioning":14},

                       "Défenseur":{"technique":-2,"passing":1,"finishing":-8,"defense":14,"goalkeeper":-35,"stamina":5,"dribble":2,"speed":4,"positioning":10},

                       "Ailier":{"technique":10,"passing":5,"finishing":4,"defense":-5,"goalkeeper":-40,"stamina":8,"dribble":14,"speed":14,"positioning":4},

                       "Pivot":{"technique":3,"passing":-2,"finishing":14,"defense":-4,"goalkeeper":-40,"stamina":2,"dribble":10,"speed":-2,"positioning":8},

                       "Universel":{"technique":3,"passing":5,"finishing":2,"defense":2,"goalkeeper":-40,"stamina":5,"dribble":6,"speed":6,"positioning":6}}

            own_div=max(1,min(6,int(conn.execute("SELECT division FROM club WHERE id=1").fetchone()["division"] or 3)))

            base=averages[own_div]*0.80*(0.78+grade_eff*0.0035)

            made=[]

            taken=[]

            for gi in range(n):

                # Poste : le besoin du groupe d'abord (gardien), puis variété au sein de la promotion.

                has_gk=int(conn.execute("SELECT COUNT(*) n FROM player WHERE club_id=1 AND is_free_agent=0 AND position='Gardien'").fetchone()["n"])

                if not has_gk: position="Gardien"

                else:

                    pool=[p for p in self.ACADEMY_POSITION_POOL if p not in taken] if gi else list(self.ACADEMY_POSITION_POOL)

                    position=random.choice(pool) if pool else random.choice(self.ACADEMY_POSITION_POOL)

                taken.append(position)

                w15=max(0.08,0.05+grade_eff*0.0022)

                w17=max(0.25,0.55-grade_eff*0.0028)

                age=random.choices((15,16,17),weights=(w15,1.0-w15-w17,w17))[0]

                # Maturité : précoce (prêt de suite, plafond moindre) / tardif (grain à semer).

                maturity=random.random()

                if maturity<0.30: maturity_label,mult,pot_shift="précoce",1.10,-1

                elif maturity<0.80: maturity_label,mult,pot_shift="affirmé",1.0,0

                else: maturity_label,mult,pot_shift="tardif",0.88,1

                archetype=random.choice(["Gardien de race"] if position=="Gardien" else list(ACADEMY_ARCHETYPES))

                arch_offset=ACADEMY_ARCHETYPES[archetype]

                attributes={key:max(12,min(72,int(round(random.gauss(base*mult+offset,6.5))))) for key,offset in modifiers[position].items()}

                probe=dict(attributes); probe["position"]=position

                level=player_level_from_row(probe)

                # Attention aux surchargers archétype : recalage du probe pour le niveau affiché.

                potential=min(20,max(level+2,academy_potential_draw(grade_eff)+pot_shift))

                attributes={key:min(int(attributes[key]),potential*5) for key in attributes}

                probe=dict(attributes); probe["position"]=position

                level=player_level_from_row(probe)

                salary=compute_fair_salary(level,own_div,age,potential)

                club=conn.execute("SELECT reputation FROM club WHERE id=1").fetchone()

                value=compute_market_value(level,age,potential,position,own_div,int(club["reputation"] or 20),contract_years=3)

                first,last,nat=random_player_name()

                shirt=int(conn.execute("SELECT COALESCE(MAX(shirt_number),0) v FROM player WHERE club_id=1").fetchone()["v"])+1

                conn.execute("""INSERT INTO player(club_id,first_name,last_name,age,position,technique,passing,finishing,defense,goalkeeper,stamina,condition,morale,nationality,salary,contract_years,market_value,is_free_agent,shirt_number,dribble,speed,positioning,potential_fixed)

                               VALUES(1,?,?,?,?,?,?,?,?,?,?,?,?,?,?,3,?,0,?,?,?,?,?)""",

                              (first,last,age,position,attributes["technique"],attributes["passing"],attributes["finishing"],attributes["defense"],

                               attributes["goalkeeper"],attributes["stamina"],random.randint(85,100),random.randint(62,84),

                               nat,salary,value,shirt,attributes["dribble"],attributes["speed"],attributes["positioning"],potential))

                pid=int(conn.execute("SELECT id FROM player ORDER BY id DESC LIMIT 1").fetchone()["id"])

                set_birth_date(conn,pid,age,career_year_of(conn))

                record_player_history(conn,pid,1,"formation",f"Formation — {archetype}, {maturity_label}, promotion {new_season}")

                made.append((first,last,age,position,level,potential))

            if made:

                # L'investissement saisonnier est consommé : une génération seulement.

                if boost:

                    conn.execute("DELETE FROM meta WHERE key='academy_invest_season'")

                names=" • ".join(f"{f} {l} ({age} ans, {pos}, {lvl}/20)" for f,l,age,pos,lvl,_ in made)

                note=f"note {grade_eff}/100{' (investissement +8)' if boost else ''}"

                add_news(conn,"Centre de formation",f"Promotion {new_season} : {len(made)} jeune(s) intègre(nt) le groupe professionnel — {names}. {note}.")

        except sqlite3.Error as exc:

            self.log_error("academy_intake",exc)





    def process_youth_gems(self, conn, new_season):

        """Pepites : de temps en temps (pas a chaque cloture), un tres jeune joueur

        faible mais au potentiel exceptionnel emerge — la moitie libre sans club,

        l'autre moitie cachee dans un effectif IA. A detecter au scouting, a signer

        jeune, a faire progresser a l'entrainement puis a revendre : la formule

        marchande (bonus age<=20 x marge de progression) fait alors exploser sa valeur.

        Aucune annonce nominative : la decouverte passe par le scouting."""

        try:

            roll=random.random()

            if roll<0.30: return  # ~30% des saisons sans pepite : l'evenement reste rare

            count=2 if roll>=0.90 else 1

            # Pas de garde-fou monde ici : 1-2 jeunes par saison, impact nul sur

            # l'inflation ; couper au-dela d'un seuil ferait disparaitre la mecanique

            # de duree de vie (scouting -> progression -> revente) apres 5-8 saisons.

            averages={1:77,2:70,3:63,4:56,5:49,6:42}

            base_positions=("Gardien","Défenseur","Ailier","Ailier","Pivot","Universel")

            modifiers={"Gardien":{"technique":-5,"passing":-2,"finishing":-18,"defense":4,"goalkeeper":20,"stamina":0,"dribble":-12,"speed":-2,"positioning":14},

                       "Défenseur":{"technique":-2,"passing":1,"finishing":-8,"defense":14,"goalkeeper":-35,"stamina":5,"dribble":2,"speed":4,"positioning":10},

                       "Ailier":{"technique":10,"passing":5,"finishing":4,"defense":-5,"goalkeeper":-40,"stamina":8,"dribble":14,"speed":14,"positioning":4},

                       "Pivot":{"technique":3,"passing":-2,"finishing":14,"defense":-4,"goalkeeper":-40,"stamina":2,"dribble":10,"speed":-2,"positioning":8},

                       "Universel":{"technique":3,"passing":5,"finishing":2,"defense":2,"goalkeeper":-40,"stamina":5,"dribble":6,"speed":6,"positioning":6}}

            for _ in range(count):

                host=conn.execute("SELECT id,division FROM club WHERE id<>1 ORDER BY RANDOM() LIMIT 1").fetchone()

                if host is None: return

                cid=int(host["id"]); division=max(1,min(6,int(host["division"] or 3)))

                as_free=random.random()<0.5

                # Heberge : potentiel plafonne a 17 — les tres hauts potentiels

                # (19-20) restent libres pour laisser sa chance a la detection

                # du manager et eviter de confier un talent d'elite a un club IA

                # deja solide (effet dynastie observe en simulation 4 saisons).

                has_gk=int(conn.execute("SELECT COUNT(*) n FROM player WHERE club_id=? AND is_free_agent=0 AND position='Gardien'",(cid,)).fetchone()["n"])

                position="Gardien" if not has_gk else random.choice(base_positions)

                age=random.randint(15,17)

                # Faible aujourd'hui : ~62% de la moyenne de sa division (sous le vivier normal).

                base=averages[division]*0.62

                attributes={key:max(12,min(62,int(round(random.gauss(base+offset,6))))) for key,offset in modifiers[position].items()}

                probe=dict(attributes); probe["position"]=position

                level=player_level_from_row(probe)

                # Gros potentiel : 16-20, super-pepite (19-20) dans ~22% des cas.

                r=random.random()

                potential=20 if r<0.08 else 19 if r<0.22 else 18 if r<0.45 else 17 if r<0.72 else 16

                if not as_free and potential>=18:

                    potential=17 if random.random()<0.5 else 16  # heberge : pastilla max 17

                salary=compute_fair_salary(level,division,age,potential)

                club=conn.execute("SELECT reputation FROM club WHERE id=?",(cid,)).fetchone()

                value=compute_market_value(level,age,potential,position,division,int(club["reputation"] or 20),

                                           contract_years=0 if as_free else 3,is_free_agent=1 if as_free else 0)

                first,last,nat=random_player_name()

                shirt=0 if as_free else int(conn.execute("SELECT COALESCE(MAX(shirt_number),0) v FROM player WHERE club_id=?",(cid,)).fetchone()["v"])+1

                conn.execute("""INSERT INTO player(club_id,first_name,last_name,age,position,technique,passing,finishing,defense,goalkeeper,stamina,condition,morale,nationality,salary,contract_years,market_value,is_free_agent,shirt_number,dribble,speed,positioning,potential_fixed)

                               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",

                              (cid,first,last,age,position,attributes["technique"],attributes["passing"],attributes["finishing"],attributes["defense"],

                               attributes["goalkeeper"],attributes["stamina"],random.randint(85,100),random.randint(62,84),

                               nat,salary,0 if as_free else 3,value,1 if as_free else 0,shirt,

                               attributes["dribble"],attributes["speed"],attributes["positioning"],potential))

                pid=int(conn.execute("SELECT id FROM player ORDER BY id DESC LIMIT 1").fetchone()["id"])

                set_birth_date(conn,pid,age,career_year_of(conn))

                record_player_history(conn,pid,cid,"formation","Pépite — jeune talent sans club" if as_free else "Pépite — jeune talent détecté")

                if as_free:

                    add_news(conn,"Rumeurs",f" Les recruteurs murmurent qu'un joueur de {age} ans, actuellement sans club, suscite la curiosité de plusieurs écuries — à surveiller dans Transferts → Joueurs libres.")

        except sqlite3.Error as exc:

            self.log_error("youth_gems",exc)



    def process_ai_training(self, conn, current_iso_date):

        """Entrainement quotidien des clubs IA : la meme mathematique que le club du manager

        (qualite, poids par atelier, age, plafond de potentiel), mardi et jeudi — sans

        blessures ni numeros de billets — pour que le vivier du monde progresse reellement

        au fil du calendrier."""

        try:

            today=parse_iso(current_iso_date)

            if today.weekday() not in (1,3,4): return  # trois ateliers par semaine (lundi repose, samedi = match)

            week_index=today.isocalendar()[1]

            plans={"Technique":(("technique",.62),("passing",.38)),

                   "Finition":(("finishing",.64),("technique",.36)),

                   "Défense":(("defense",.62),("stamina",.38)),

                   "Physique":(("stamina",.72),("defense",.28)),

                   "Tactique":(("passing",.58),("defense",.42))}

            activities=list(plans.keys())

            for club in conn.execute("SELECT id,division FROM club WHERE id<>1").fetchall():

                if random.random()>0.75: continue

                cid=int(club["id"])

                prep_factor=1.0 if int(club["division"] or 3)<=2 else 0.9 if int(club["division"])<=4 else 0.8

                activity=activities[(cid+week_index)%len(activities)]

                rotation=(cid*3+week_index)%10

                players=conn.execute("""SELECT * FROM player WHERE club_id=? AND is_free_agent=0 AND injury_days<=0

                                        ORDER BY (shirt_number+?)%10 LIMIT 6""",(cid,rotation)).fetchall()

                quality=random.randint(52,82)

                stamp=career_timestamp(conn)

                for player in players:

                    age=int(player["age"] or 24)

                    level20=player_level_from_row(player); potential20=player_potential_from_row(player)

                    room=max(1,int(potential20-level20))

                    headroom=min(1.0,0.35+0.65*room/4.0)

                    cap=int(round(potential20*5))

                    progressed=[]

                    for attr,weight in plans[activity]:

                        if int(player[attr] or 0)>=cap: continue

                        if random.random()<training_growth_probability(quality,"Normale",weight,age,headroom,prep_factor):

                            progressed.append(attr)

                    if progressed:

                        sets=",".join("%s=MIN(%d,%s+2)"%(a,cap,a) for a in progressed)

                        conn.execute("UPDATE player SET %s,condition=MAX(20,condition-2) WHERE id=?"%sets,(int(player["id"]),))

                        for attr in progressed:

                            conn.execute("INSERT INTO player_training_log(player_id,attribute_key,delta,activity_key,created_at) VALUES(?,?,2,?,?)",

                                         (int(player["id"]),attr,activity,stamp))

        except Exception as e:

            self.log_error("process_ai_training",e)



