    def update_squad_action_buttons(self,current_date=None):

        if not hasattr(self,"squad_brief_btn"): return

        current_date=current_date or self._career_day()

        conn=db(); used={row["action_key"] for row in conn.execute("SELECT action_key FROM squad_action_log WHERE player_id=0 AND action_date=?",(current_date,)).fetchall()}; budget=conn.execute("SELECT budget FROM club WHERE id=1").fetchone()["budget"]

        morale_need=conn.execute("SELECT COUNT(*) FROM player WHERE club_id=1 AND morale<100").fetchone()[0]

        medical_need=conn.execute("SELECT COUNT(*) FROM player WHERE club_id=1 AND (condition<100 OR injury_matches>0 OR injury_days>0)").fetchone()[0]; conn.close()

        self.squad_brief_btn.setEnabled("brief" not in used and morale_need>0)

        self.squad_brief_btn.setText("✓ BRIEF" if "brief" in used else "MORAL MAX" if morale_need==0 else "BRIEF ÉQUIPE")

        self.squad_recovery_btn.setEnabled("recovery" not in used and budget>=1800 and medical_need>0)

        self.squad_recovery_btn.setText("✓ RÉCUP" if "recovery" in used else "RAS" if medical_need==0 else "RÉCUP • 1 800 €")

        self.squad_physio_btn.setText("✓ KINÉ" if getattr(self,"physiotherapist_hired",False) else "KINÉ • 30 000 €")

        self.squad_physio_btn.setEnabled(not getattr(self,"physiotherapist_hired",False))

        self.squad_physio_btn.setToolTip("Ouvre la fiche d'un joueur blessé pour lancer un protocole à 2 100 €, avec risque d'échec." if self.physiotherapist_hired else "Recrute un kiné pour 30 000 €. Ses protocoles coûtent 2 100 € et comportent un risque d'échec.")



