    def reopen_last_match_report(self):

        if getattr(self,"last_match_report",None):

            self.show_match_report(self.last_match_report)



    def toggle_auto(self):

        if not self.match_state or self.match_state.get("finished",True): return

        if self.timer.isActive():

            self.timer.stop(); self.auto_btn.setText("▶  REPRENDRE")

        elif self.match_state.get("half_time_break"):

            self.resume_second_half()

        else:

            self.timer.start(self.match_interval_ms()); self.auto_btn.setText("Ⅱ  PAUSE")



    def apply_match_instruction(self):

        state=self.match_state

        if not state or state.get("finished",True): return False

        instructions={

            "pressing":("Pressing haut",{"mentality":"Pressing haut","tempo":"Rapide","press_intensity":"Haut","block_height":"Haut"}),

            "counter":("Bloc bas & contre",{"formation":"2-2 · Largeur","mentality":"Prudente","tempo":"Rapide","press_intensity":"Bas","block_height":"Bas","attack_focus":"Pivot"}),

            "possession":("Conserver le ballon",{"mentality":"Équilibrée","tempo":"Patient","press_intensity":"Médian","block_height":"Médian","attack_width":"Large","goalkeeper_distribution":"Courte"}),

            "wings":("Attaquer les ailes",{"formation":"4-0 · Mouvement","mentality":"Offensive","tempo":"Rapide","attack_width":"Large","attack_focus":"Ailes"}),

            "powerplay":("Gardien volant",{"formation":"Gardien volant · Risqué","mentality":"Offensive","tempo":"Rapide","press_intensity":"Haut","block_height":"Haut"}),

        }

        key=self.coach_instruction_combo.currentData(); instruction=instructions.get(key)

        if not instruction: return False

        name,values=instruction

        if not state.get("coach_instruction_remaining",0):

            state["coach_original_tactics"]={key:getattr(self,key).currentText() for key in values}

        previous_flag=getattr(self,"_applying_tactic_preset",False); self._applying_tactic_preset=True

        for control,value in values.items(): getattr(self,control).setCurrentText(value)

        self._applying_tactic_preset=previous_flag

        state["coach_instruction"]=name; state["coach_instruction_remaining"]=5

        short_name={"Pressing haut":"PRESSING HAUT","Bloc bas & contre":"BLOC BAS","Conserver le ballon":"POSSESSION","Attaquer les ailes":"JEU SUR LES AILES","Gardien volant":"GARDIEN VOLANT"}.get(name,name.upper())

        state["coach_instruction_short"]=short_name

        self.coach_status_label.setText(f"{short_name}  •  5 MIN")

        stamp=self.current_match_timestamp()

        self.log_match_event(f"<span style='color:#c9a8ff'><b>{stamp} — Consigne coach :</b></span> {name} (5 minutes).","coach",state["minute"])

        side="h" if state.get("is_home",True) else "a"; self.match_banner.animate_action(side,"build")

        return True



    def _restore_match_instruction(self,state,announce=False):

        original=state.get("coach_original_tactics") or {}

        if not original: return

        previous_flag=getattr(self,"_applying_tactic_preset",False); self._applying_tactic_preset=True

        for control,value in original.items():

            if hasattr(self,control): getattr(self,control).setCurrentText(value)

        self._applying_tactic_preset=previous_flag

        old_name=state.get("coach_instruction","Consigne")

        state["coach_original_tactics"]={}; state["coach_instruction_remaining"]=0; state["coach_instruction"]=""

        if announce:

            self.log_match_event(f"{self.current_match_timestamp()} — Fin de la consigne « {old_name} ». Retour au plan initial.","coach",state["minute"])

        if hasattr(self,"coach_status_label"): self.coach_status_label.setText("PLAN INITIAL")



    def tick_match_instruction(self,minute):

        state=self.match_state

        if not state or not state.get("coach_instruction_remaining",0): return

        state["coach_instruction_remaining"]-=1

        if state["coach_instruction_remaining"]<=0:

            self._restore_match_instruction(state,announce=True)

        else:

            self.coach_status_label.setText(f"{state.get('coach_instruction_short',state.get('coach_instruction','')).upper()}  •  {state['coach_instruction_remaining']} MIN")



    def open_live_substitution_dialog(self):

        state=self.match_state

        if not state or state.get("finished",True):

            self.show_game_message("Remplacement","Les changements seront disponibles au coup d'envoi.","info"); return False

        manager_side="h" if state.get("is_home",True) else "a"

        if int(state.get("players_on",{}).get(manager_side,5))<5:

            self.show_game_message("Infériorité numérique","Attends la fin des deux minutes d'exclusion ou un but encaissé qui autorise le remplacement.","info"); return False

        if not state.get("bench"):

            self.show_game_message("Banc vide","Aucun remplaçant n'est disponible.","warning"); return False

        dialog=QDialog(self); dialog.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dialog.setWindowTitle("Remplacement en direct"); dialog.setFixedWidth(560)

        root=QVBoxLayout(dialog); root.setContentsMargins(16,16,16,16); root.setSpacing(10)

        panel=QFrame(); panel.setObjectName("HeroPanel"); layout=QVBoxLayout(panel); layout.setContentsMargins(14,12,14,12)

        title=QLabel("CHANGEMENT VOLANT"); title.setStyleSheet("font-size:12pt;font-weight:900;color:#cdb8ff;")

        layout.addWidget(title); layout.addWidget(QLabel("Choisis le joueur qui sort et son remplaçant. Le changement est immédiat.")); root.addWidget(panel)

        out_combo=QComboBox(); in_combo=QComboBox()

        for player in state.get("lineup",[]): out_combo.addItem(f"#{int(player['shirt_number'] or 0):02d}  {player['first_name']} {player['last_name']}  •  {player['position']}",player["id"])

        for player in state.get("bench",[]): in_combo.addItem(f"#{int(player['shirt_number'] or 0):02d}  {player['first_name']} {player['last_name']}  •  {player['position']}",player["id"])

        root.addWidget(QLabel("JOUEUR À SORTIR")); root.addWidget(out_combo); root.addWidget(QLabel("REMPLAÇANT À FAIRE ENTRER")); root.addWidget(in_combo)

        buttons=QHBoxLayout(); buttons.addStretch(); cancel=QPushButton("ANNULER"); cancel.clicked.connect(dialog.reject); confirm=QPushButton("EFFECTUER LE CHANGEMENT"); confirm.setObjectName("Primary"); confirm.clicked.connect(dialog.accept); buttons.addWidget(cancel); buttons.addWidget(confirm); root.addLayout(buttons)

        if dialog.exec()==QDialog.Accepted:

            return self.perform_live_substitution(out_combo.currentData(),in_combo.currentData())

        return False



    def perform_live_substitution(self,out_player_id,in_player_id,minute=None,source="coach"):

        state=self.match_state

        if not state or state.get("finished",True): return False

        manager_side="h" if state.get("is_home",True) else "a"

        if int(state.get("players_on",{}).get(manager_side,5))<5: return False

        out_index=next((i for i,p in enumerate(state.get("lineup",[])) if p["id"]==out_player_id),None)

        in_index=next((i for i,p in enumerate(state.get("bench",[])) if p["id"]==in_player_id),None)

        if out_index is None or in_index is None or out_player_id==in_player_id: return False

        outgoing=state["lineup"][out_index]; incoming=state["bench"][in_index]

        state["lineup"][out_index]=incoming; state["bench"][in_index]=outgoing; state["subs_used"]+=1

        stamp=int(state.get("minute",0) if minute is None else minute)

        source="coach" if source=="coach" else "automatique"

        self.log_match_event(f"{self.current_match_timestamp()} — Remplacement {source} : {outgoing['first_name']} {outgoing['last_name']} ⇢ {incoming['first_name']} {incoming['last_name']}.","substitution",stamp)

        self._update_live_match_widgets()

        side="h" if state.get("is_home",True) else "a"; self.match_banner.animate_action(side,"substitution",detail=f"{outgoing['first_name']} {outgoing['last_name']} ⇢ {incoming['first_name']} {incoming['last_name']}")

        self.coach_status_label.setText(f"{ 'ENTRÉE' if source=='coach' else 'ROTATION' } : {incoming['last_name'].upper()}")

        return True



    def match_interval_ms(self):

        intervals={1:900,2:600,3:400,4:250,5:140}

        return intervals.get(self.match_speed_slider.value() if hasattr(self,"match_speed_slider") else 2,600)



    def _set_match_speed(self,value):

        """Clic sur un bouton du segment de vitesse (1x..5x)."""

        try:

            self.match_speed_slider.setValue(int(value))

        except Exception:

            pass



    def _sync_speed_buttons(self,value):

        try:

            btns=self.match_speed_buttons.buttons()

            for idx,b in enumerate(btns,start=1): b.setChecked(idx==value)

        except Exception:

            pass



    def update_simulation_speed(self,value):

        value=int(value)

        labels={1:"1×  •  LENT",2:"2×  •  NORMAL",3:"3×  •  RAPIDE",4:"4×  •  TRÈS RAPIDE",5:"5×  •  TURBO"}

        self.match_speed_label.setText(labels.get(value,f"{value}×"))

        self._sync_speed_buttons(value)

        if self.timer.isActive(): self.timer.setInterval(self.match_interval_ms())



    def step_match_minute(self):

        if not self.match_state or self.match_state.get("finished",True): return

        if self.match_state.get("half_time_break"): return

        self.timer.stop(); self.auto_btn.setText("▶  REPRENDRE"); self.advance_minute()



    def _slow_for_goal(self, milliseconds=GOAL_SLOW_MS):

        """Ralentit la simulation quelques secondes après un but (effet 'ralenti').

        FILTRE ANTI-PIEGE (retour « la vitesse revient a 1 toute seule apres les

        actions ») : si un ralenti est DEJA en cours, on ne re-capte PAS la

        vitesse — sinon la valeur sauvegardee serait ecrasee par la valeur

        ralentie (1x) et le match resterait bloque en 1x apres deux actions

        rapprochees. On conserve la vitesse d'ORIGINE et on prolonge le

        ralenti."""

        if not hasattr(self, "match_speed_slider"):

            return

        if getattr(self,"_goal_slow_timer",None) is not None and self._goal_slow_timer.isActive() and getattr(self,"_goal_saved_speed",None) is not None:

            self._goal_slow_timer.start(milliseconds)

            return

        self._goal_saved_speed = self.match_speed_slider.value()

        self.match_speed_slider.setValue(1)

        self.update_simulation_speed(1)

        if self._goal_slow_timer is None:

            self._goal_slow_timer = QTimer(self)

            self._goal_slow_timer.setSingleShot(True)

            self._goal_slow_timer.timeout.connect(self._restore_speed_after_goal)

        self._goal_slow_timer.start(milliseconds)



    def _restore_speed_after_goal(self):

        if not hasattr(self, "match_speed_slider") or not hasattr(self, "_goal_saved_speed"):

            return

        if self._goal_saved_speed is None:

            return  # deja restaure (timer expire avant la fin du match)

        self.match_speed_slider.setValue(self._goal_saved_speed)

        self.update_simulation_speed(self._goal_saved_speed)

        self._goal_saved_speed = None



    def _bside(self, side):

        """COULEURS EXTÉRIEUR (retour « buteur / couleur du club inversés sur

        le rendu et la popup à l'extérieur ») : le moteur travaille en cotes

        RÉELLES (h = domicile), le bandeau/le terrain en cotes COACH (h = club

        du joueur). À domicile les deux coïncident ; à l'extérieur, sans ce

        remappage, les actions et buts adverses s'affichaient avec le nom et

        la couleur du club du joueur."""

        try:

            user = "h" if (self.match_state or {}).get("is_home", True) else "a"

        except Exception:

            user = "h"

        return "h" if side == user else "a"



    def goal_celebration(self, side, scorer, team_name):

        """Affiche un flash 'BUT !' au centre de la page match, aux couleurs de l'equipe."""

        if not hasattr(self, "goal_overlay"):

            return

        color = self.match_banner.home_color if self._bside(side) == "h" else self.match_banner.away_color

        qc = QColor(color)

        if not qc.isValid():

            qc = QColor("#ffffff")

        self._goal_celebration_color = qc.name()

        page = self.pages[3] if hasattr(self, "pages") and len(self.pages) > 3 else None

        target = page if page is not None else self

        self.goal_overlay.setParent(target)

        self.goal_overlay.move((target.width() - self.goal_overlay.width()) // 2,

                               (target.height() - self.goal_overlay.height()) // 2)

        # POPUP BUT : le nom du joueur sur SA PROPRE LIGNE (retour utilisateur).

        main_line = f"BUT !   {team_name.upper()}"
        txt = f"{main_line}\n{scorer}"

        self.goal_overlay.setWordWrap(True)

        # POPUP A LA LARGEUR DU TEXTE (retour « les textes depassent ») :

        # mesure reelle du libelle, clamp sur la largeur de la page, recentrage.

        f = QFont("Segoe UI"); f.setBold(True); f.setPixelSize(30)
        _fm = QFontMetrics(f)
        _need = max(_fm.horizontalAdvance(main_line) + 2 * len(main_line),
                    _fm.horizontalAdvance(scorer) + 2 * len(scorer)) + 60
        w_txt = min(max(_need, 420), max(420, target.width() - 48))
        _fs = 22 if _need <= target.width() - 48 else 18

        self.goal_overlay.setText(txt)

        self.goal_overlay.setStyleSheet(

            f"QLabel{{background:{qc.name()};color:#0b1017;border:4px solid {qc.lighter(140).name()};"

            f"border-radius:14px;font-size:{_fs}pt;font-weight:900;letter-spacing:2px;padding:6px 18px;}}"

        )

        self.goal_overlay.setFixedSize(int(w_txt), 138)

        self.goal_overlay.move((target.width() - self.goal_overlay.width()) // 2,

                               (target.height() - self.goal_overlay.height()) // 2)

        self.goal_overlay.show()

        self.goal_overlay.raise_()

        self._goal_flash_on = True

        if self._goal_celebration_timer is None:

            self._goal_celebration_timer = QTimer(self)

            self._goal_celebration_timer.timeout.connect(self._tick_goal_celebration)

        self._goal_celebration_ticks = 0

        self._goal_celebration_timer.start(300)



    def hide_goal_celebration(self):

        if self._goal_celebration_timer is not None:

            self._goal_celebration_timer.stop()

        self._goal_celebration_ticks = 0

        self._goal_flash_on = False

        if hasattr(self, "goal_overlay"):

            self.goal_overlay.hide()



    def _tick_goal_celebration(self):

        self._goal_celebration_ticks += 1

        self._goal_flash_on = not self._goal_flash_on

        if hasattr(self, "goal_overlay") and self.goal_overlay.isVisible():

            base = getattr(self, "_goal_celebration_color", "#ffffff")

            if self._goal_flash_on:

                self.goal_overlay.setStyleSheet(

                    f"QLabel{{background:#fff7b3;color:#7a5c00;border:4px solid #ffd540;"

                    f"border-radius:14px;font-size:22pt;font-weight:900;letter-spacing:2px;padding:6px 18px;}}"

                )

            else:

                self.goal_overlay.setStyleSheet(

                    f"QLabel{{background:{base};color:#0b1017;border:4px solid {QColor(base).lighter(140).name()};"

                    f"border-radius:14px;font-size:22pt;font-weight:900;letter-spacing:2px;padding:6px 18px;}}"

                )

        if self._goal_celebration_ticks >= 8:

            self.hide_goal_celebration()



    def finish_match_now(self):

        if not self.match_state or self.match_state.get("finished",True): return

        self.timer.stop(); self.auto_btn.setText("▶  REPRENDRE"); self.finish_match_btn.setEnabled(False)

        self._fast_forward_match=True

        try:

            while self.match_state and not self.match_state.get("finished",True) and self.match_state.get("elapsed_seconds",0)<2400:

                self.advance_minute()

        finally:

            self._fast_forward_match=False

        if self.match_state and not self.match_state.get("finished",True): self.finish_match()

        self._pitch_sync()



    def current_match_timestamp(self):

        state=self.match_state or {}; elapsed=int(state.get("elapsed_seconds",int(state.get("minute",0))*60))

        return f"{elapsed//60:02d}:{elapsed%60:02d}"



    def advance_minute(self):

        s=self.match_state

        if not s or s["finished"]: return

        s["elapsed_seconds"]=min(2400,int(s.get("elapsed_seconds",0))+20)

        elapsed=s["elapsed_seconds"]; minute=max(1,min(40,(elapsed+59)//60)); s["minute"]=minute

        boundary=(elapsed%60)==0; halftime=elapsed==1200; fulltime=elapsed>=2400

        if boundary:

            # Exclusions and fatigue are counted in game minutes, not simulation ticks.

            for side in ("h","a"):

                if s["red_penalty"][side]>0:

                    s["red_penalty"][side]-=1

                    if s["red_penalty"][side]==0:

                        self.restore_team_after_red(side,minute,"fin des deux minutes")

        if halftime or fulltime:

            self.simulate_event(minute)

            if halftime and boundary: self.apply_fatigue_and_rotation(minute)

            phase="Mi-temps" if halftime else "Fin du match"

            self.log_match_event(f"<b>{self.current_match_timestamp()} — {phase}</b>","halftime" if halftime else "fulltime",minute)

            if halftime:

                s["half_time_score"]=(s["hg"],s["ag"]); s["fouls_half"]={"h":0,"a":0}

                s["possession_side"]="a" if s.get("kickoff_side")=="h" else "h"

                s["build_up"]={"h":0,"a":0}; s["set_piece"]=None

        else:

            self.simulate_event(minute)

            if boundary and elapsed<2400: self.apply_fatigue_and_rotation(minute)

        if boundary: self.tick_match_instruction(minute)

        self.clock_label.setText(f"{elapsed//60:02d}:{elapsed%60:02d}")

        self.score_label.setText(f"{s['hg']}  —  {s['ag']}")

        self.match_progress.setValue(elapsed)

        # BANDEAU orienté coach : "h" = club du joueur (score et noms dans ce sens).

        _is_home = s.get("is_home", True)

        self.match_banner.set_clock(elapsed, s["hg"] if _is_home else s["ag"],

                                            s["ag"] if _is_home else s["hg"])

        if elapsed<1200:

            self.match_phase.setText("1RE MI-TEMPS  •  EN DIRECT")

        elif halftime:

            self.match_phase.setText("MI-TEMPS  •  CHRONO BLOQUÉ" if s.get("half_time_break") else "MI-TEMPS")

        elif elapsed<2400:

            self.match_phase.setText("2E MI-TEMPS  •  EN DIRECT")

        total_shots=s["shots_h"]+s["shots_a"]

        self.stats_labels["shots"].setText(f"{s['shots_h']} — {s['shots_a']}")

        self.stats_labels["target"].setText(f"{s['target_h']} — {s['target_a']}")

        phase_side=s.pop("last_possession_duration_side",s.get("possession_side","h"))

        if phase_side in ("h","a"):

            s["possession_seconds"][phase_side]=int(s["possession_seconds"].get(phase_side,0))+20

        played_seconds=sum(s["possession_seconds"].values())

        poss=round(100*s["possession_seconds"].get("h",0)/played_seconds) if played_seconds else 50

        s["last_possession_home"]=poss; s["possession_samples"].append(poss)

        self.stats_labels["possession"].setText(f"{poss}% — {100-poss}%")

        if getattr(self, "poss_bar", None) is not None:

            # BARRE COACH : les secondes possédées sont comptées en cotes

            # moteurs (h = domicile) ; la barre lit la part du CLUB DU JOUEUR.

            try: self.poss_bar.set_values(poss if _is_home else 100 - poss)

            except Exception as exc: self.log_error("poss_bar",exc)

        self.stats_labels["passes"].setText(f"{s['passes_completed']['h']}/{s['passes']['h']} — {s['passes_completed']['a']}/{s['passes']['a']}")

        self.stats_labels["interceptions"].setText(f"{s['interceptions']['h']} — {s['interceptions']['a']}")

        self.stats_labels["corners"].setText(f"{s['corners']['h']} — {s['corners']['a']}")

        self.stats_labels["fouls"].setText(f"{s['fouls_h']} — {s['fouls_a']}")

        self.stats_labels["cards"].setText(f"J {s['yellow_h']}–{s['yellow_a']}  •  R {s['red_h']}–{s['red_a']}")

        if halftime and not getattr(self,"_fast_forward_match",False) and not s.get("half_time_break"):

            self._enter_half_time_break()

        if fulltime and not getattr(self,"_fast_forward_match",False): self.finish_match()

        self._pitch_sync()



    def _enter_half_time_break(self):

        """Coupe le chrono à la mi-temps : le coach dispose de tout son temps pour ses changements."""

        s=self.match_state

        if not s: return

        s["half_time_break"]=True
        self._prematch_mods={}

        self.timer.stop()

        self.match_phase.setText("MI-TEMPS  •  CHRONO BLOQUÉ")

        self.auto_btn.setText("▶  REPRENDRE LA 2E MI-TEMPS")

        self.next_btn.setEnabled(False)

        self.coach_sub_btn.setEnabled(bool(s.get("bench")))

        self.coach_status_label.setText("MI-TEMPS : choisis ta causerie, effectue tes changements puis reprends la 2e période.")
        try: self._show_halftime_talk()
        except Exception as _exc: self.log_error("halftime_talk",_exc)

        self.match_clock_context.setText("MI-TEMPS  •  chrono bloqué — effectue tes changements puis lance la seconde période.")

        self.log_match_event(f"<b>{self.current_match_timestamp()} — MI-TEMPS</b> : le chrono est bloqué. Effectue tes remplacements puis reprends la seconde période.","halftime",s.get("minute",20))



    def _assistant_prematch_choice(self,fx=None):
        """Choix de causerie de l'adjoint selon le contexte du match."""
        try:
            conn=db()
            me=conn.execute("SELECT reputation FROM club WHERE id=1").fetchone()
            opp=None
            if fx is not None:
                oid=int(fx["away_club_id"] if int(fx["home_club_id"])==1 else fx["home_club_id"])
                opp=conn.execute("SELECT reputation FROM club WHERE id=?",(oid,)).fetchone()
            avg=conn.execute("SELECT AVG(morale) m,AVG(condition) c FROM player WHERE club_id=1").fetchone()
            conn.close()
            if getattr(self,"_current_derby",False): return "pression"
            if avg and float(avg["m"] or 70)<58: return "capitaine"
            if avg and float(avg["c"] or 80)<62: return "laisser"
            if opp and int(me["reputation"] or 30)+8<=int(opp["reputation"] or 30): return "solidarite"
            return "confiance"
        except Exception:
            return "confiance"

    def _assistant_halftime_choice(self,s):
        """Choix de causerie de mi-temps : protéger, réagir ou garder le cap."""
        hg=int(s.get("hg",0) or 0); ag=int(s.get("ag",0) or 0)
        diff=(hg-ag) if bool(s.get("is_home",True)) else (ag-hg)
        mom=float(s.get("momentum",0) or 0)
        if diff<0:
            return "gueule" if diff<=-2 else "motivant"
        if diff>0:
            return "bloc" if mom<0 else "calme"
        return "tactique" if mom<-3 else "confiance"

    def _assistant_interview_choice(self,outcome):
        """Réponse de l'adjoint selon le résultat et l'état du club."""
        outcome=str(outcome or "")
        try:
            conn=db()
            avg=conn.execute("SELECT AVG(morale) m FROM player WHERE club_id=1").fetchone()
            fan_row=conn.execute("SELECT value FROM meta WHERE key='fan_confidence'").fetchone()
            conn.close()
            morale=float(avg["m"] or 65) if avg else 65
            fans=int(fan_row["value"]) if fan_row else 55
        except Exception:
            morale,fans=65,55
        if outcome=="VICTOIRE":
            if fans<58: return "supporters"
            return "humble"
        if "NUL" in outcome:
            return "travail"
        if morale<55: return "proteger"
        if fans<55: return "supporters"
        return "assumer"

    def _show_prematch_talk(self,fx=None):
        """Causerie d'avant-match : plusieurs tons, effets réels avant le coup d'envoi."""
        self._prematch_mods={}
        try:
            if getattr(self,"_fast_forward_match",False): return
            if self._delegation_active("prematch_talk"):
                self._apply_prematch_talk(self._assistant_prematch_choice(fx),
                                          derby=bool(getattr(self,"_current_derby",False)))
                return
            dlg=QDialog(self); dlg.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dlg.setModal(True); dlg.setFixedWidth(570)
            chosen={"kind":None}
            root=QVBoxLayout(dlg); root.setContentsMargins(16,14,16,14); root.setSpacing(7)
            derby=bool(getattr(self,"_current_derby",False))
            context="Match équilibré"
            try:
                if fx is not None:
                    opp_id=int(fx["away_club_id"] if int(fx["home_club_id"])==1 else fx["home_club_id"])
                    c=db()
                    opp=c.execute("SELECT reputation FROM club WHERE id=?",(opp_id,)).fetchone()
                    me=c.execute("SELECT reputation FROM club WHERE id=1").fetchone()
                    c.close()
                    diff=int((me["reputation"] if me else 30) or 30)-int((opp["reputation"] if opp else 30) or 30)
                    if diff>=8: context="Favori • le public attend une victoire"
                    elif diff<=-8: context="Outsider • joue sans pression"
            except Exception:
                context="Match équilibré"
            head=QLabel("CAUSERIE D'AVANT-MATCH" + ("  •  DERBY" if derby else ""))
            head.setStyleSheet("font-size:12pt;font-weight:1000;letter-spacing:.6px;color:"+("#ffb36b" if derby else "#f2c46d")+";")
            sub=QLabel(f"{context}. Choisis le ton avant le coup d'envoi : le choix agit sur le moral, la forme et le début de match.")
            sub.setObjectName("Muted"); sub.setWordWrap(True)
            root.addWidget(head); root.addWidget(sub)
            def _pick(kind):
                chosen["kind"]=kind; dlg.accept()
            for talk in PREMATCH_TALKS:
                b=QPushButton(f"{talk['label']}\n{talk['effect']}")
                b.setMinimumHeight(42); b.setStyleSheet("text-align:left;padding:5px 10px;")
                b.clicked.connect(lambda checked=False,k=talk["key"]: _pick(k)); root.addWidget(b)
            skip=QPushButton("AUCUNE CAUSERIE"); skip.clicked.connect(dlg.reject); root.addWidget(skip)
            if dlg.exec()!=QDialog.Accepted or not chosen["kind"]: return
            self._apply_prematch_talk(chosen["kind"],derby=derby)
        except Exception as exc:
            self.log_error("prematch_talk",exc)

    def _apply_prematch_talk(self,kind,derby=False):
        talk=next((t for t in PREMATCH_TALKS if t["key"]==kind),None)
        if talk is None: return None
        self._prematch_mods={k:float(talk[k]) for k in ("attack","defense") if float(talk.get(k,1) or 1)!=1.0}
        msg=talk["message"]
        c=None
        try:
            c=db()
            if talk.get("morale"):
                c.execute("UPDATE player SET morale=MIN(100,MAX(0,morale+?)) WHERE club_id=1",(int(talk["morale"]),))
            if talk.get("condition"):
                c.execute("UPDATE player SET condition=MIN(100,condition+?) WHERE club_id=1",(int(talk["condition"]),))
            if talk.get("fans"):
                row=c.execute("SELECT value FROM meta WHERE key='fan_confidence'").fetchone()
                base=int(row["value"]) if row else 55
                c.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('fan_confidence',?)",(str(max(0,min(100,base+int(talk["fans"])))),))
            if derby:
                c.execute("UPDATE player SET morale=MIN(100,morale+2) WHERE club_id=1")
                msg+=" Derby : le vestiaire est encore plus concerné (moral +2)."
            add_news(c,"Vestiaire",msg); c.commit()
        except Exception as exc:
            self.log_error("apply_prematch_talk",exc)
        finally:
            if c is not None:
                try: c.close()
                except Exception: pass
        try: self.coach_status_label.setText(msg)
        except Exception: pass
        return msg

    def _show_postmatch_interview(self,report,state):
        """Interview d'après-match : réponses adaptées au résultat."""
        try:
            if getattr(self,"_fast_forward_match",False): return
            outcome=str(report.get("outcome","NUL"))
            if self._delegation_active("postmatch_interview"):
                self._apply_postmatch_answer(self._assistant_interview_choice(outcome),outcome)
                return
            answers=POSTMATCH_ANSWERS.get(outcome) or POSTMATCH_ANSWERS["NUL"]
            dlg=QDialog(self); dlg.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dlg.setModal(True); dlg.setFixedWidth(590)
            chosen={"kind":None}
            root=QVBoxLayout(dlg); root.setContentsMargins(16,14,16,14); root.setSpacing(7)
            hg=int(state.get("hg",0) or 0) if isinstance(state,dict) else 0
            ag=int(state.get("ag",0) or 0) if isinstance(state,dict) else 0
            is_home=bool(state.get("is_home",True)) if isinstance(state,dict) else True
            ours,thers=(hg,ag) if is_home else (ag,hg)
            head=QLabel(f"INTERVIEW D'APRÈS-MATCH  •  {outcome} {ours}-{thers}")
            head.setStyleSheet("font-size:12pt;font-weight:1000;letter-spacing:.6px;color:#9cc9ff;")
            question={"VICTOIRE":"Comment jugez-vous cette victoire ?","DÉFAITE":"Comment analysez-vous cette défaite ?"}.get(outcome,"Ce match nul, quel regard portez-vous dessus ?")
            q=QLabel(question); q.setWordWrap(True); q.setStyleSheet("font-weight:900;color:#eaf0fb;")
            root.addWidget(head); root.addWidget(q)
            def _pick(kind):
                chosen["kind"]=kind; dlg.accept()
            for ans in answers:
                b=QPushButton(f"{ans['label']}\n{ans['effect']}")
                b.setMinimumHeight(42); b.setStyleSheet("text-align:left;padding:5px 10px;")
                b.clicked.connect(lambda checked=False,k=ans["key"]: _pick(k)); root.addWidget(b)
            skip=QPushButton("PASSER"); skip.clicked.connect(dlg.reject); root.addWidget(skip)
            if dlg.exec()!=QDialog.Accepted or not chosen["kind"]: return
            self._apply_postmatch_answer(chosen["kind"],outcome)
        except Exception as exc:
            self.log_error("postmatch_interview",exc)

    def _apply_postmatch_answer(self,kind,outcome):
        answers=POSTMATCH_ANSWERS.get(outcome) or POSTMATCH_ANSWERS["NUL"]
        ans=next((a for a in answers if a["key"]==kind),None)
        if ans is None: return None
        c=None
        try:
            c=db()
            if ans.get("morale"):
                c.execute("UPDATE player SET morale=MIN(100,MAX(0,morale+?)) WHERE club_id=1",(int(ans["morale"]),))
            if ans.get("fans"):
                row=c.execute("SELECT value FROM meta WHERE key='fan_confidence'").fetchone()
                base=int(row["value"]) if row else 55
                c.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('fan_confidence',?)",(str(max(0,min(100,base+int(ans["fans"])))),))
            add_news(c,"Presse",ans["message"]); c.commit()
        except Exception as exc:
            self.log_error("apply_postmatch_answer",exc)
        finally:
            if c is not None:
                try: c.close()
                except Exception: pass
        self.show_game_message("Interview",ans["message"],"info")
        return ans["message"]

    def _show_halftime_talk(self):
        s=self.match_state
        if not s or getattr(self,"_fast_forward_match",False): return
        if self._delegation_active("halftime_talk"):
            self._apply_halftime_talk(self._assistant_halftime_choice(s))
            return
        if getattr(self,"_halftime_dialog",None) is not None:
            try: self._halftime_dialog.close()
            except Exception: pass
        dlg=QDialog(self); dlg.setWindowFlags(Qt.Dialog|Qt.FramelessWindowHint); dlg.setModal(False); dlg.setFixedWidth(560)
        root=QVBoxLayout(dlg); root.setContentsMargins(16,14,16,14); root.setSpacing(7)
        head=QLabel("CAUSERIE DE MI-TEMPS"); head.setStyleSheet("font-size:12pt;font-weight:1000;letter-spacing:.6px;color:#f2c46d;")
        mom=float(s.get("momentum",0) or 0)
        hg=int(s.get("hg",0) or 0); ag=int(s.get("ag",0) or 0); home=bool(s.get("is_home",True))
        diff=(hg-ag) if home else (ag-hg)
        status="Vous menez" if diff>0 else "Égalité" if diff==0 else "Vous êtes menés"
        info=QLabel(f"{status} {hg}-{ag} • momentum {mom:+.0f}. Choisis le ton de ta causerie : l'effet s'applique à la seconde période.")
        info.setObjectName("Muted"); info.setWordWrap(True)
        root.addWidget(head); root.addWidget(info)
        def _pick(kind):
            self._apply_halftime_talk(kind); dlg.close()
        for talk in HALFTIME_TALKS:
            b=QPushButton(f"{talk['label']}\n{talk['effect']}")
            b.setMinimumHeight(42); b.setStyleSheet("text-align:left;padding:5px 10px;")
            b.clicked.connect(lambda checked=False,k=talk["key"]: _pick(k)); root.addWidget(b)
        skip=QPushButton("PASSER"); skip.clicked.connect(dlg.close); root.addWidget(skip)
        self._halftime_dialog=dlg; dlg.show()

    def _apply_halftime_talk(self,kind):
        s=self.match_state
        if not s: return
        talk=next((t for t in HALFTIME_TALKS if t["key"]==kind),None)
        if talk is None: return
        ids=[int(pl["id"]) for pl in (s.get("lineup") or []) if pl.get("id")]
        mods={k:float(talk[k]) for k in ("attack","defense") if float(talk.get(k,1) or 1)!=1.0}
        s["talk_mods"]=mods
        if talk.get("momentum_set"):
            s["momentum"]=max(-20,min(20,float(talk.get("momentum",0) or 0)))
        elif talk.get("momentum"):
            s["momentum"]=max(-20,min(20,float(s.get("momentum",0) or 0)+float(talk["momentum"])))
        condition=float(talk.get("condition",0) or 0)
        if condition:
            for pid in ids:
                s.setdefault("conditions",{})[pid]=min(100,float(s.get("conditions",{}).get(pid,70) or 70)+condition)
        morale=int(talk.get("morale",0) or 0)
        if morale:
            c=None
            try:
                c=db(); c.execute("UPDATE player SET morale=MIN(100,MAX(0,morale+?)) WHERE club_id=1",(morale,)); c.commit()
            except Exception as exc:
                self.log_error("halftime_morale",exc)
            finally:
                if c is not None:
                    try: c.close()
                    except Exception: pass
        msg=talk["message"]
        try: self.coach_status_label.setText(msg)
        except Exception: pass
        try: self.log_match_event(f"<b>{self.current_match_timestamp()} — CAUSERIE</b> : {msg}","coach",s.get("minute",20))
        except Exception: pass

    def resume_second_half(self):

        s=self.match_state

        if not s or s.get("finished",True) or not s.get("half_time_break"): return False

        s["half_time_break"]=False

        self.log_match_event(f"{self.current_match_timestamp()} — Reprise : seconde période lancée.","kickoff",s.get("minute",20))

        date_text=fmt_date_fr(s["current_date"]) if s.get("current_date") else "—"

        self.match_clock_context.setText(f"TEMPS EFFECTIF  •  5 CONTRE 5  •  {date_text}")

        self.match_phase.setText("2E MI-TEMPS  •  EN DIRECT")

        self.coach_status_label.setText(f"{s.get('coach_instruction_short','').upper()}  •  {s['coach_instruction_remaining']} MIN" if s.get("coach_instruction_remaining") else "COACH PRÊT")

        self.next_btn.setEnabled(True)

        self.auto_btn.setText("Ⅱ  PAUSE")

        self.timer.start(self.match_interval_ms())

        return True



    def remove_sent_off_player(self,side,player_id):

        s=self.match_state

        if not s: return False

        manager_side="h" if s.get("is_home",True) else "a"

        lineup_key="lineup" if side==manager_side else "opponent_lineup"

        lineup=s.get(lineup_key,[])

        index=next((i for i,p in enumerate(lineup) if p.get("id")==player_id),None)

        if index is None: return False

        player=lineup.pop(index)

        s.setdefault("sent_off_players",{"h":[],"a":[]}).setdefault(side,[]).append({"player":player,"index":index})

        self._update_live_match_widgets(); return True



    def restore_team_after_red(self,side,minute,reason):

        s=self.match_state

        if not s: return False

        s["red_penalty"][side]=0

        manager_side="h" if s.get("is_home",True) else "a"

        lineup_key="lineup" if side==manager_side else "opponent_lineup"

        bench_key="bench" if side==manager_side else "opponent_bench"

        lineup=s.get(lineup_key,[]); bench=s.get(bench_key,[])

        sent=s.get("sent_off_players",{}).get(side,[])

        expelled=sent[-1] if sent else None

        incoming=None

        if expelled and bench:

            expelled_player=expelled["player"]

            options=[p for p in bench if p.get("position")==expelled_player.get("position")]

            if not options: options=[p for p in bench if p.get("position")!="Gardien"] or list(bench)

            incoming=max(options,key=lambda p:(float(p.get("stamina",45))*.30+float(p.get("technique",45))*.25+

                                                float(p.get("condition",70))*.25+float(p.get("morale",60))*.20))

            bench.remove(incoming); lineup.insert(min(int(expelled["index"]),len(lineup)),incoming)

            if side==manager_side:

                s["conditions"].setdefault(incoming["id"],float(incoming.get("condition",70))); s["subs_used"]+=1

            else:

                s["opponent_conditions"].setdefault(incoming["id"],float(incoming.get("condition",70))); s["opponent_subs_used"]+=1

            s["players_on"][side]=5

            self.log_match_event(f"{self.current_match_timestamp()} — {s['home'] if side=='h' else s['away']} remplace l'expulsé par {incoming['first_name']} {incoming['last_name']} ({reason}).","substitution",minute)

            self.match_banner.animate_action(side,"substitution",detail=f"⇢ {incoming['first_name']} {incoming['last_name']}")

        else:

            s["players_on"][side]=len(lineup)

            self.log_match_event(f"{self.current_match_timestamp()} — Fin de l'infériorité numérique pour {s['home'] if side=='h' else s['away']}, mais aucun remplaçant n'est disponible.","red",minute)

        self._update_live_match_widgets(); return incoming is not None



    def apply_fatigue_and_rotation(self, minute):

        s = self.match_state

        if not s:

            return

        rng=self.match_rng

        manager_side="h" if s.get("is_home",True) else "a"

        opponent_side="a" if manager_side=="h" else "h"

        tempo_factor = 1.2 if self.tempo.currentText() == "Rapide" else 0.85 if self.tempo.currentText() == "Patient" else 1.0

        pressing = self.press_intensity.currentText()

        rotation = self.rotation_style.currentText()

        for p in list(s["lineup"]):

            # RECALIBRAGE : une rencontre COMPLETE coute ~13 pts de condition en

            # tactique neutre (avant : ~49 — remontee utilisateur « endurance

            # fond anormalement vite »). Les tactiques d'effort gardent l'ecart.

            loss = rng.uniform(0.15, 0.45) * tempo_factor * self._individual_effect(manager_side, "fatigue")

            if self.mentality.currentText() == "Pressing haut":

                loss += 0.10

            if pressing == "Haut": loss += 0.12

            elif pressing == "Médian": loss += 0.04

            s["conditions"][p["id"]] = max(10.0, s["conditions"][p["id"]] - loss)



            inj_base = 0.0012

            if s["conditions"][p["id"]] < 45:

                inj_base += 0.005

            # Plafond de sûreté : jamais plus d'une blessure par rencontre (côté coach).

            if not s["injuries"] and rng.random() < inj_base:

                out_days = rng.randint(3, 10)

                s["injuries"][p["id"]] = out_days

                stamp=self.current_match_timestamp()

                self.log_match_event(f"<span style='color:#f3ad4d'><b>{stamp} — Blessure :</b></span> {p['first_name']} {p['last_name']} doit sortir ({out_days} jour(s)).","injury",minute)

                self._try_substitute_player(p["id"], minute)



        opponent_lineup=s.get("opponent_lineup",[]); opponent_bench=s.get("opponent_bench",[])

        opponent_side="a" if s.get("is_home",True) else "h"

        opponent_tactics=s.get("opponent_tactics",{})

        opponent_tempo=1.12 if opponent_tactics.get("tempo")=="Rapide" else .88 if opponent_tactics.get("tempo")=="Patient" else 1.0

        opponent_press=.12 if opponent_tactics.get("pressing")=="Haut" else .04 if opponent_tactics.get("pressing")=="Médian" else 0

        for player in opponent_lineup:

            pid=player["id"]; condition=float(s["opponent_conditions"].get(pid,player.get("condition",75)))

            loss=rng.uniform(.15,.45)*tempo_factor*opponent_tempo+opponent_press

            s["opponent_conditions"][pid]=max(10.0,condition-loss)

        if s["players_on"].get(opponent_side,5)>=5 and minute%6==0 and opponent_bench and s.get("opponent_subs_used",0)<5:

            tired=[p for p in opponent_lineup if p.get("position")!="Gardien" and s["opponent_conditions"].get(p["id"],75)<72]

            if tired:

                outgoing=min(tired,key=lambda p:s["opponent_conditions"].get(p["id"],75))

                options=[p for p in opponent_bench if p.get("position")==outgoing.get("position")] or [p for p in opponent_bench if p.get("position")!="Gardien"] or opponent_bench

                incoming=max(options,key=lambda p:(float(p.get("stamina",45))*.3+float(p.get("technique",45))*.3+float(p.get("condition",70))*.4))

                out_index=opponent_lineup.index(outgoing); in_index=opponent_bench.index(incoming)

                opponent_lineup[out_index]=incoming; opponent_bench[in_index]=outgoing; s["opponent_subs_used"]+=1

                s["opponent_conditions"].setdefault(incoming["id"],float(incoming.get("condition",75)))

                self.log_match_event(f"{self.current_match_timestamp()} — {s['away'] if opponent_side=='a' else s['home']} fait entrer {incoming['first_name']} {incoming['last_name']} pour faire tourner.","substitution",minute)

                self.match_banner.animate_action(opponent_side,"substitution"); self._update_live_match_widgets()



        if s["players_on"].get(manager_side,5)<5: return

        interval = 5 if rotation == "Agressives" else 10 if rotation == "Conserver le cinq" else 6

        threshold = 48 if rotation == "Agressives" else 24 if rotation == "Conserver le cinq" else 35

        if minute % interval == 0:

            tired = [p for p in s["lineup"] if s["conditions"][p["id"]] < threshold]

            for p in tired:

                self._try_substitute_player(p["id"], minute)



    def _try_substitute_player(self, out_player_id, minute):

        s = self.match_state

        if not s or not s["bench"]:

            return False

        out_idx = next((i for i,pl in enumerate(s["lineup"]) if pl["id"] == out_player_id), None)

        if out_idx is None:

            return False

        out_pl = s["lineup"][out_idx]

        candidates = [b for b in s["bench"] if b["position"] == out_pl["position"]]

        if not candidates:

            candidates = sorted(s["bench"], key=lambda x: s["conditions"][x["id"]], reverse=True)

        in_pl = candidates[0]

        return self.perform_live_substitution(out_pl["id"],in_pl["id"],minute,source="automatique")



    def _update_live_match_widgets(self):

        s = self.match_state

        if not s:

            self.live_lineup_label.setText("—"); self.live_bench_label.setText("—"); return

        if hasattr(self,"match_banner"):

            own=s.get("lineup",[]); opposition=s.get("opponent_lineup",[])

            # "h" = club du joueur : nom utilisateur a gauche, nom adverse a droite.

            _user_name=s["home"] if s.get("is_home",True) else s["away"]

            _opp_name=s["away"] if s.get("is_home",True) else s["home"]

            self.match_banner.set_teams(_user_name,_opp_name,own,opposition)

        lineup=s.get("lineup",[]); opponent_lineup=s.get("opponent_lineup",[])

        def fill_list(lst, players, bench, own):

            lst.clear()

            for section, roster in (("CINQ DE DÉPART", players),("BANC", bench)):

                header=QListWidgetItem(section); header.setData(Qt.UserRole,None); header.setFlags(Qt.ItemIsEnabled); lst.addItem(header)

                for player in roster:

                    pid=player.get("id"); condition=float(s.get("conditions" if own else "opponent_conditions",{}).get(pid,player.get("condition",75)))

                    instr=s.get("individual_instructions",{}).get(str(pid)) if own else None

                    spec=INDIVIDUAL_INSTRUCTION_MODIFIERS.get(instr)

                    card=QListWidgetItem(); card.setData(Qt.UserRole,pid)

                    role=f"{player.get('position','—')}  •  #{int(player.get('shirt_number') or 0):02d}"

                    status=f"  |  forme {rating20(condition)}/20"

                    if spec: status += f"  {spec['icon']} {spec['label']}"

                    card.setText(f"{player.get('first_name','')} {player.get('last_name','')}\n{role}{status}")

                    card.setToolTip("Clic pour modifier la consigne individuelle" if own else role)

                    lst.addItem(card)

            if own and not getattr(lst,"_instruction_handler_connected",False):

                lst.itemClicked.connect(self._on_live_team_item_clicked)

                lst._instruction_handler_connected=True

        fill_list(self.live_team_lists["own"],lineup,s.get("bench",[]),True)

        fill_list(self.live_team_lists["opponent"],opponent_lineup,s.get("opponent_bench",[]),False)

        lineup_txt=", ".join(f"{p['first_name']} {p['last_name']}" for p in lineup)

        bench_txt=", ".join(f"{p['first_name']} {p['last_name']}" for p in s.get("bench",[])[:6])

        self.live_lineup_label.setText(f"Cinq : {lineup_txt or '—'}")

        self.live_bench_label.setText(f"Banc : {bench_txt or '—'}")



    def _on_live_team_item_clicked(self,item):
        """Ouvre la consigne individuelle sans reconnecter le signal à chaque tick."""
        try:
            pid=item.data(Qt.UserRole) if item is not None else None
            if pid: self.open_individual_instruction_menu(int(pid))
        except Exception as exc:
            self.log_error("live_team_instruction",exc)

    def _pitch_sync(self):

        """Terrain 2D (mouchard) : lecture seule de l'etat moteur a chaque tick.



        N'ECRIT JAMAIS dans match_state ni dans la base ; toute surprise est

        avalee localement (le match continue quoi qu'il arrive au visuel)."""

        pitch=getattr(self,"match_pitch",None)

        if pitch is None: return

        s=self.match_state

        if not s: return

        try:

            pitch.set_pace(self.match_interval_ms())

        except Exception:

            pass

        try:

            pitch.note_state(s, animate=not getattr(self,"_fast_forward_match",False))

        except Exception as exc:

            self.log_error("pitch_sync",exc)



    def _individual_effect(self, side, field, default=1.0):

        s=self.match_state or {}; manager_side="h" if s.get("is_home",True) else "a"

        players=s.get("lineup",[]) if side==manager_side else s.get("opponent_lineup",[])

        vals=[]

        for player in players:

            key=s.get("individual_instructions",{}).get(str(player.get("id")))

            if key in INDIVIDUAL_INSTRUCTION_MODIFIERS:

                vals.append(float(INDIVIDUAL_INSTRUCTION_MODIFIERS[key].get(field,default)))

        return sum(vals)/len(vals) if vals else default



    def set_individual_instruction(self, player_id, instruction_key):

        s=self.match_state

        if not s or s.get("finished",True) or instruction_key not in INDIVIDUAL_INSTRUCTION_MODIFIERS: return False

        s.setdefault("individual_instructions",{})[str(player_id)]=instruction_key

        player=next((p for p in s.get("lineup",[]) if p.get("id")==player_id),None)

        if player:

            self.log_match_event(f"{self.current_match_timestamp()} — Consigne individuelle : {player['first_name']} {player['last_name']} → {INDIVIDUAL_INSTRUCTION_MODIFIERS[instruction_key]['label']}.","instruction",s.get("minute",0))

        self._update_live_match_widgets(); return True



    def open_individual_instruction_menu(self, player_id, anchor=None):

        menu=QMenu(self); menu.setTitle("Consigne individuelle")

        current=(self.match_state or {}).get("individual_instructions",{}).get(str(player_id))

        for key,spec in INDIVIDUAL_INSTRUCTION_MODIFIERS.items():

            action=QAction(f"{spec['icon']}  {spec['label']}",menu); action.setCheckable(True); action.setChecked(key==current)

            action.triggered.connect(lambda checked=False,k=key:self.set_individual_instruction(player_id,k)); menu.addAction(action)

        menu.addSeparator(); clear=QAction("✕  Aucune consigne",menu); clear.triggered.connect(lambda:self._clear_individual_instruction(player_id)); menu.addAction(clear)

        menu.exec(anchor or self.cursor().pos())



    def _clear_individual_instruction(self, player_id):

        s=self.match_state

        if s: s.setdefault("individual_instructions",{}).pop(str(player_id),None); self._update_live_match_widgets()



    def simulate_event(self, minute):

        s=self.match_state

        if not s: return

        rng=self.match_rng

        manager_side="h" if s.get("is_home",True) else "a"

        opponent_side="a" if manager_side=="h" else "h"

        try: s["momentum"]=float(s.get("momentum",0) or 0)*0.985
        except Exception: s["momentum"]=0

        pressing=self.press_intensity.currentText()

        manager_profile=self.match_team_profile(s.get("lineup",[]),s.get("conditions",{}))

        _att_m,_def_m,_fin_m,_pas_m=self._tactical_profile_mods(s)
        manager_profile=dict(manager_profile)
        manager_profile["attack"]=float(manager_profile.get("attack",45))*_att_m
        manager_profile["defense"]=float(manager_profile.get("defense",45))*_def_m
        manager_profile["finishing"]=float(manager_profile.get("finishing",45))*_fin_m
        manager_profile["passing"]=float(manager_profile.get("passing",45))*_pas_m

        opponent_profile=self.match_team_profile(s.get("opponent_lineup",[]),s.get("opponent_conditions",{}))

        opponent_tactics=s.get("opponent_tactics",{})

        # MENTALITE : vrai arbitrage. Offensive pousse mais s'expose, Prudente
        # se protege mais se prive d'occasions. Le meme bareme s'applique a l'IA.
        _MINDSET={"Offensive":(1.075,0.940,1.05),"Prudente":(0.945,1.075,0.96)}
        _mind=_MINDSET.get(self.mentality.currentText(),(1.0,1.0,1.0))
        manager_profile=dict(manager_profile)
        manager_profile["attack"]=float(manager_profile["attack"])*_mind[0]
        manager_profile["defense"]=float(manager_profile["defense"])*_mind[1]
        manager_conv=_mind[2]
        _omind=_MINDSET.get(str(opponent_tactics.get("mentality") or "Équilibrée"),(1.0,1.0,1.0))
        opponent_profile=dict(opponent_profile)
        opponent_profile["attack"]=float(opponent_profile["attack"])*_omind[0]
        opponent_profile["defense"]=float(opponent_profile["defense"])*_omind[1]
        opponent_conv=_omind[2]

        manager_intent=0

        if self.tempo.currentText()=="Rapide": manager_intent+=.020

        elif self.tempo.currentText()=="Patient": manager_intent-=.010

        manager_attack=(manager_profile["attack"]-opponent_profile["defense"])*.0012

        opponent_attack=(opponent_profile["attack"]-manager_profile["defense"])*.0012

        # ECART DE NIVEAU AMPLIFIE (retour « une equipe enorme gagne trop peu

        # contre une equipe faible ») : au-dela de 15 points d'ecart

        # (attaque-de defense), un boost concave s'ajoute (jusqu'a ~+0.055 pour

        # 40 pts) — la superiorite sportive redevient la force dominante,

        # devant les reglages tactiques.

        def _gap_boost(edge):

            e=float(edge)

            if e<=15: return 0.0

            return min(0.055,(e-15)*0.0022)

        manager_attack+=_gap_boost(manager_profile["attack"]-opponent_profile["defense"])

        opponent_attack+=_gap_boost(opponent_profile["attack"]-manager_profile["defense"])

        formation=self.formation.currentText()

        if formation.startswith("4-0"): manager_attack+=.025

        elif formation.startswith("2-2"): manager_attack+=.015

        elif formation.startswith("Gardien volant"): manager_attack+=.045; opponent_attack+=.035

        elif formation.startswith("1-1-2"): manager_attack+=.020; opponent_attack+=.008

        elif formation.startswith("1-2-1"): manager_attack+=.010

        if pressing=="Haut": manager_attack+=.02

        elif pressing=="Bas": manager_attack-=.01

        if self.attack_width.currentText()=="Large": manager_attack+=.012

        elif self.attack_width.currentText()=="Étroit": manager_attack+=.006

        focus=self.attack_focus.currentText()

        if focus=="Pivot" and formation.startswith("2-2"): manager_attack+=.018

        elif focus=="Ailes" and self.attack_width.currentText()=="Large": manager_attack+=.018

        elif focus=="Axe central": manager_attack+=.01

        style=opponent_tactics.get("style","equilibre")

        opponent_formation=opponent_tactics.get("formation","")

        if opponent_formation.startswith("4-0"): opponent_attack+=.02

        elif opponent_formation.startswith("2-2"): opponent_attack+=.012

        if style=="pressing": opponent_attack+=.02

        elif style=="contre": opponent_attack+=.012

        elif style=="possession": opponent_attack+=.006

        manager_goals=s["hg"] if manager_side=="h" else s["ag"]

        opponent_goals=s["hg"] if opponent_side=="h" else s["ag"]

        remaining=2400-int(s.get("elapsed_seconds",0))

        if opponent_goals<manager_goals and remaining<=360: opponent_attack+=.035

        if opponent_goals<manager_goals and remaining<=120: opponent_attack+=.025

        if opponent_goals>manager_goals and remaining<=180: opponent_attack-=.015

        # Gestion du score : la mentalite se voit dans les 8 dernieres minutes.
        if remaining<=480:

            _lead=manager_goals-opponent_goals

            if self.mentality.currentText()=="Prudente":

                if _lead>0: opponent_attack-=.020; manager_attack-=.010

                elif _lead<0: manager_attack+=.012

            elif self.mentality.currentText()=="Offensive":

                if _lead>0: manager_attack+=.012; opponent_attack+=.010

                elif _lead<0: manager_attack+=.025; opponent_attack+=.012

        block=self.block_height.currentText()

        if block=="Haut": opponent_attack-=.012

        elif block=="Bas": opponent_attack+=.012



        possession_edge=(manager_profile["passing"]-opponent_profile["passing"])*.003

        possession_edge+=.035 if pressing=="Haut" else .015 if pressing=="Médian" else -.012

        distribution=self.goalkeeper_distribution.currentText()

        possession_edge += 0.025 if distribution=="Courte" else 0.015 if distribution=="Équilibrée" else -0.005

        if style=="possession": possession_edge-=.035

        elif style=="pressing": possession_edge-=.015

        manager_possession=max(.30,min(.70,.5+possession_edge))

        restart=s.get("set_piece")

        side=restart.get("side") if restart and restart.get("side") in ("h","a") else s.get("possession_side")

        if side not in ("h","a"): side=manager_side if rng.random()<manager_possession else opponent_side

        s["possession_side"]=side

        s["last_possession_duration_side"]=side

        other_side="a" if side=="h" else "h"

        prefix=s["home"] if side=="h" else s["away"]

        stamp=self.current_match_timestamp()

        def award_corner():

            s["corners"][side]+=1; s["possession_side"]=side; s["possession_ticks"]=0; s["build_up"][side]=0

            s["set_piece"]={"side":side,"type":"corner"}

            self.match_banner.animate_action(side,"corner")

            self.log_match_event(f"{stamp} — Corner pour {prefix} après une déviation défensive.","corner",minute)

        self.match_banner.animate_action(side,"build")

        # Le compte des quatre secondes ne concerne pas une possession ordinaire;

        # les pertes de balle proviennent ici du pressing de l'équipe sans ballon.

        press_level=(opponent_tactics.get("pressing")=="Haut") if side==manager_side else pressing=="Haut"

        turnover_chance=.018+(.027 if press_level else .008)+min(.10,max(0,int(s.get("possession_ticks",0))-2)*.025)

        if rng.random()<turnover_chance:

            regain_side=other_side

            s["interceptions"][regain_side]+=1; s["possession_side"]=regain_side; s["possession_ticks"]=0; s["build_up"][side]=0; s["set_piece"]=None

            self.match_banner.animate_action(regain_side,"turnover")

            self.log_match_event(f"{stamp} — Interception sous pression : {s['home'] if regain_side=='h' else s['away']} récupère le ballon.","interception",minute)

            return



        attack_quality=manager_attack+manager_intent if side==manager_side else opponent_attack+(.025 if style=="pressing" else .012 if style=="contre" else 0)

        numeric_edge=int(s["players_on"].get(side,5))-int(s["players_on"].get(opponent_side,5))

        attack_quality+=.032*numeric_edge

        shooting_profile=manager_profile if side==manager_side else opponent_profile

        defending_profile=opponent_profile if side==manager_side else manager_profile

        build_count=min(4,int(s.get("build_up",{}).get(side,0)))

        restart_bonus=.105 if restart else 0

        # VRAIE PHASE DE JEU (retour « eviter les buts surprises ») : une

        # possession doit CONSTRUIRE avant de frapper — au moins 2 passes

        # nettes (1 seulement si le pressing haut fabrique l'occasion), sauf

        # sur phase arrete (corner / coup franc / 10 m / penalti) : la

        # sequencetronnee passe-passe-passe-tir devient visible sur le terrain.

        min_build = 0 if restart else (1 if press_level else 2)

        phase_blocked = (build_count < min_build)

        # CALIBRATION (retour « ne pas empecher trop les buts » / banc

        # numerique) : base .21 + accroche per-build .055 redonnent ~90 % de

        # la production de buts d'avant-garde en gardant la phase lisible.

        shot_probability=max(.10,min(.52,.21+attack_quality*.40+build_count*.055+restart_bonus))

        if side == manager_side:

            shot_probability=max(.05,min(.60,shot_probability*self._individual_effect(side,"shot")*.5 + shot_probability*self._individual_effect(side,"dribble")*.5))

        chance=rng.random()

        foul_threshold=shot_probability+.12

        if side == manager_side: foul_threshold=shot_probability + .12*self._individual_effect(side,"foul")

        timeout_threshold=foul_threshold+.02

        if phase_blocked:

            # construction obligatoire : ni frappe, ni faute, ni temps mort —

            # l'equipe joue une passe de plus (la phase reste lisible en 2D)

            chance=1.0

        if chance < shot_probability:

            self.match_banner.animate_action(side,"shot")

            if restart:

                self.match_banner.rename_last_action("FRAPPE SUR CORNER" if restart.get("type")=="corner" else "FRAPPE SUR COUP FRANC")

            s[f"shots_{side}"]+=1

            # Le dribble serré crée l'espace qui augmente la précision de la frappe (futsal).

            target_chance=max(.43,min(.78,.61+(shooting_profile["attack"]-60)*.0015+(shooting_profile.get("dribble",55)-58)*.0009))

            if side == manager_side: target_chance=max(.30,min(.88,target_chance*self._individual_effect(side,"shot")))

            if rng.random()<target_chance:

                s[f"target_{side}"]+=1

                finishing_edge=(shooting_profile["finishing"]-defending_profile["keeper"])*.0022

                conversion=max(.13,min(.58,.30+finishing_edge+attack_quality*.30))

                conversion*=manager_conv if side==manager_side else opponent_conv

                if rng.random() < conversion:

                    s["hg" if side=="h" else "ag"]+=1

                    # Fin de pénalité rouge si l'équipe en infériorité encaisse.

                    conceded_side=other_side

                    if s["red_penalty"][conceded_side] > 0:

                        self.restore_team_after_red(conceded_side,minute,"but encaissé")

                    scorer,scorer_id=self.random_scorer(side)

                    if scorer_id is not None: s["player_goals"][scorer_id]=s["player_goals"].get(scorer_id,0)+1

                    _mgr="h" if s.get("is_home",True) else "a"
                    _swing=12*(1.3 if self.mentality.currentText()=="Offensive" else 0.8 if self.mentality.currentText()=="Prudente" else 1.0)

                    s["momentum"]=max(-20,min(20,float(s.get("momentum",0) or 0)+(_swing if side==_mgr else -_swing)))

                    elapsed=int(s.get("elapsed_seconds",0))

                    s["goals"].append({"minute":elapsed//60,"second":elapsed%60,"team":prefix,"scorer":scorer,"player_id":scorer_id,"type":"Jeu"})

                    s["possession_side"]=other_side; s["possession_ticks"]=0; s["build_up"]={"h":0,"a":0}; s["set_piece"]=None

                    self.match_banner.animate_action(side,"goal",detail=scorer)

                    self.match_banner.goal_flash(self.match_banner.home_color if self._bside(side)=="h" else self.match_banner.away_color)

                    self.goal_celebration(side, scorer, prefix)

                    self._slow_for_goal()

                    self.log_match_event(f"<span style='color:#8fe0a3'><b>{stamp} — BUT ! {prefix}</b></span> • {scorer} conclut l’action.","goal",minute)

                else:

                    if rng.random()<.18:

                        award_corner()

                    else:

                        s["possession_side"]=other_side; s["possession_ticks"]=0; s["build_up"]={"h":0,"a":0}; s["set_piece"]=None

                        keeper_roster=(s.get("opponent_lineup",[]) if side==manager_side else s.get("lineup",[]))

                        keeper=next((p for p in keeper_roster if p.get("position")=="Gardien"),None)

                        keeper_name=f" {keeper['last_name']}" if keeper else ""

                        if keeper is not None: s["player_saves"][keeper["id"]]=s["player_saves"].get(keeper["id"],0)+1

                        self.match_banner.animate_action(other_side,"save",detail=(f"Arrêt de {keeper['last_name']}" if keeper else "Arrêt du gardien"))

                        self.log_match_event(f"{stamp} — Frappe cadrée de {prefix}, arrêt du gardien{keeper_name}.","shot",minute)

            else:

                if rng.random()<.055:

                    award_corner()

                else:

                    s["possession_side"]=other_side; s["possession_ticks"]=0; s["build_up"]={"h":0,"a":0}; s["set_piece"]=None

                    self.log_match_event(f"{stamp} — Tentative de {prefix}, le ballon passe à côté. Remise en jeu pour {s['home'] if other_side=='h' else s['away']}.","shot",minute)

        elif chance < foul_threshold:

            self.match_banner.animate_action(side,"foul")

            s[f"fouls_{side}"]+=1

            s["fouls_half"][side] += 1

            fouled_side=other_side

            s["possession_side"]=fouled_side; s["possession_ticks"]=0; s["build_up"][side]=0

            s["set_piece"]={"side":fouled_side,"type":"free_kick"} if s["fouls_half"][side]<6 else None

            self.log_match_event(f"{stamp} — Faute sifflée contre {prefix}.","foul",minute)

            discipline_roll=rng.random()

            # Discipline apaisée : les jugements suivent toujours les fautes,

            # mais les fenêtres sont resserrées (~11 % de jaunes, ~0,7 % de rouges par faute).

            if discipline_roll<.115:

                card_elapsed=int(s.get("elapsed_seconds",0)); card_minute=card_elapsed//60; card_second=card_elapsed%60

                if side==manager_side and s.get("lineup"):

                    sent_off={card.get("player_id") for card in s.get("card_events",[]) if card.get("type")=="red"}

                    eligible=[player for player in s["lineup"] if player["id"] not in sent_off]

                    carded=rng.choice(eligible or s["lineup"]); carded_name=f"{carded['first_name']} {carded['last_name']}"; player_id=carded["id"]

                    s["card_events"].append({"type":"yellow","side":side,"player_id":player_id,"player_name":carded_name,"minute":card_minute,"second":card_second})

                else:

                    opponent_players=s.get("opponent_lineup",[]); eligible=[p for p in opponent_players if p.get("position")!="Gardien"]

                    carded=rng.choice(eligible or opponent_players) if opponent_players else {"first_name":"Adversaire","last_name":""}

                    carded_name=f"{carded['first_name']} {carded['last_name']}".strip(); player_id=carded.get("id")

                    s["card_events"].append({"type":"yellow","side":side,"player_id":player_id,"player_name":carded_name,"minute":card_minute,"second":card_second})

                s[f"yellow_{side}"]+=1

                self.log_match_event(f"<span style='color:#ffd55f'><b>{stamp} — CARTON JAUNE</b></span> pour {carded_name} ({prefix}).","yellow_card",minute)

            # Une faute donne un avertissement ou un rouge direct, jamais deux tirages de cartes simultanés.

            elif discipline_roll<.122 and s["players_on"][side]==5:

                card_elapsed=int(s.get("elapsed_seconds",0)); card_minute=card_elapsed//60; card_second=card_elapsed%60

                if side==manager_side and s.get("lineup"):

                    already_sent={card.get("player_id") for card in s.get("card_events",[]) if card.get("type")=="red"}

                    candidates=[p for p in s["lineup"] if p["id"] not in already_sent]

                    carded=rng.choice(candidates or s["lineup"]); carded_name=f"{carded['first_name']} {carded['last_name']}"; player_id=carded["id"]

                    s["card_events"].append({"type":"red","side":side,"player_id":player_id,"player_name":carded_name,"minute":card_minute,"second":card_second})

                else:

                    opponent_players=s.get("opponent_lineup",[]); eligible=[p for p in opponent_players if p.get("position")!="Gardien"]

                    carded=rng.choice(eligible or opponent_players) if opponent_players else {"first_name":"Adversaire","last_name":""}

                    carded_name=f"{carded['first_name']} {carded['last_name']}".strip(); player_id=carded.get("id")

                    s["card_events"].append({"type":"red","side":side,"player_id":player_id,"player_name":carded_name,"minute":card_minute,"second":card_second})

                s["players_on"][side] = 4

                s["red_penalty"][side] = 2

                s["red_cards"] += 1

                s[f"red_{side}"]+=1

                self.remove_sent_off_player(side,player_id)

                self.log_match_event(f"<span style='color:#ff6b6b'><b>{stamp} — CARTON ROUGE</b></span> pour {carded_name} ({prefix}). Infériorité 2 minutes.","red",minute)

            # 6e faute cumulée par mi-temps => 10m sans mur

            if s["fouls_half"][side] >= 6:

                other = "a" if side == "h" else "h"

                self.match_banner.animate_action(other,"shot")

                self.log_match_event(f"{stamp} — 6e faute cumulée : coup franc direct à 10m sans mur pour {s['home'] if other=='h' else s['away']}.","ten_metre",minute)

                kick_profile=manager_profile if other==manager_side else opponent_profile

                kick_keeper=opponent_profile if other==manager_side else manager_profile

                conversion=max(.16,min(.45,.28+(kick_profile["finishing"]-60)*.0025-(kick_keeper["keeper"]-60)*.0018))

                if rng.random() < conversion:

                    s["hg" if other=="h" else "ag"] += 1

                    team=s["home"] if other=="h" else s["away"]

                    elapsed=int(s.get("elapsed_seconds",0))

                    conceded_side="a" if other=="h" else "h"

                    if s["red_penalty"][conceded_side]>0: self.restore_team_after_red(conceded_side,minute,"but encaissé sur 10 m")

                    scorer,scorer_id=self.random_scorer(other); scorer_name=f"{scorer} (10 m)"

                    if scorer_id is not None: s["player_goals"][scorer_id]=s["player_goals"].get(scorer_id,0)+1

                    _mgr="h" if s.get("is_home",True) else "a"
                    s["momentum"]=max(-20,min(20,float(s.get("momentum",0) or 0)+(12 if other==_mgr else -12)))

                    s["goals"].append({"minute":elapsed//60,"second":elapsed%60,"team":team,"scorer":scorer_name,"player_id":scorer_id,"type":"10 m"})

                    s["possession_side"]=conceded_side; s["possession_ticks"]=0; s["build_up"]={"h":0,"a":0}; s["set_piece"]=None

                    self.match_banner.animate_action(other,"goal",detail=scorer_name)

                    self.match_banner.goal_flash(self.match_banner.home_color if self._bside(other)=="h" else self.match_banner.away_color)

                    self.goal_celebration(other, scorer_name, team)

                    self._slow_for_goal()

                    self.log_match_event(f"<span style='color:#8fe0a3'><b>{stamp} — BUT sur 10 m !</b></span> • {scorer}","goal",minute)

                else:

                    s["possession_side"]=side; s["possession_ticks"]=0; s["build_up"]={"h":0,"a":0}; s["set_piece"]=None

        elif chance < timeout_threshold:

            half = "1" if minute <= 20 else "2"

            key = f"{side}{half}"

            if s["timeouts"][key] == 0:

                s["timeouts"][key] = 1

                self.log_match_event(f"{stamp} — Temps mort (1 min) demandé par {prefix}.","timeout",minute)

        else:

            roster=s.get("lineup",[]) if side==manager_side else s.get("opponent_lineup",[])

            sent_off={event.get("player_id") for event in s.get("card_events",[]) if event.get("type")=="red" and event.get("side")==side}

            passers=[player for player in roster if player.get("id") not in sent_off]

            if len(passers)<2:

                s["possession_side"]=other_side; s["possession_ticks"]=0; s["build_up"][side]=0; s["set_piece"]=None

                self.log_match_event(f"{stamp} — Relance imprécise de {prefix}, ballon rendu à l'adversaire.","turnover",minute)

                return

            passer_weights=[max(1,float(player.get("passing",45))*.58+float(player.get("technique",45))*.24+float(player.get("positioning",50))*.18) for player in passers]

            passer=rng.choices(passers,weights=passer_weights,k=1)[0]

            receivers=[player for player in passers if player.get("id")!=passer.get("id")]

            receiver_weights=[max(1,float(player.get("technique",45))*.44+float(player.get("passing",45))*.34+float(player.get("speed",50))*.22) for player in receivers]

            receiver=rng.choices(receivers,weights=receiver_weights,k=1)[0]

            s["passes"][side]+=1

            passing_edge=(shooting_profile["passing"]-defending_profile["defense"])*.0022

            passing_edge+=possession_edge if side==manager_side else -possession_edge

            if side==manager_side:

                if self.tempo.currentText()=="Patient": passing_edge+=.035

                if self.goalkeeper_distribution.currentText()=="Courte": passing_edge+=.025

                elif self.goalkeeper_distribution.currentText()=="Directe": passing_edge-=.02

                if formation.startswith("4-0"): passing_edge+=.025

            elif style=="possession": passing_edge+=.035

            if restart: passing_edge+=.035

            completion_chance=max(.52,min(.92,.73+passing_edge))

            if side == manager_side: completion_chance=max(.35,min(.97,completion_chance*self._individual_effect(side,"pass")))

            receiver_index=roster.index(receiver) if receiver in roster else 0

            self.match_banner.animate_pass(side,receiver_index,detail=f"{passer['last_name']} → {receiver['last_name']}")

            if rng.random()<completion_chance:

                s["passes_completed"][side]+=1; s["possession_ticks"]=int(s.get("possession_ticks",0))+1

                # CONSTRUCTION VIVE (banc numerique) : une passe vaut 2 crans de

                # build — une seule passe ouvre TOUTES les options d'attaque.

                s["build_up"][side]=min(6,int(s["build_up"].get(side,0))+2)

                s["possession_side"]=side; s["set_piece"]=None

                s["player_passes"][passer["id"]]=s["player_passes"].get(passer["id"],0)+1

                self.log_match_event(f"{stamp} — Passe réussie : {passer['last_name']} trouve {receiver['last_name']} ({prefix}).","pass",minute)

            else:

                interception_chance=max(.30,min(.86,.57+(defending_profile["defense"]-60)*.004+(defending_profile.get("positioning",55)-58)*.0016+(.10 if press_level else 0)))

                if rng.random()<interception_chance:

                    s["interceptions"][other_side]+=1

                    self.log_match_event(f"{stamp} — Interception de {s['home'] if other_side=='h' else s['away']} sur la passe de {passer['last_name']}.","interception",minute)

                else:

                    self.log_match_event(f"{stamp} — Passe trop appuyée de {passer['last_name']}, ballon rendu à l'adversaire.","turnover",minute)

                self.match_banner.animate_action(other_side,"turnover",detail=f"{passer['last_name']}")

                s["possession_side"]=other_side; s["possession_ticks"]=0; s["build_up"][side]=0; s["build_up"][other_side]=0; s["set_piece"]=None



    def random_scorer(self,side=None):

        s = self.match_state or {}

        manager_side="h" if s.get("is_home",True) else "a"; side=side or manager_side

        roster=s.get("lineup",[]) if side==manager_side else s.get("opponent_lineup",[])

        sent_off={card.get("player_id") for card in s.get("card_events",[]) if card.get("type")=="red" and card.get("side")==side}

        active=[p for p in roster if p.get("position")!="Gardien" and p.get("id") not in sent_off]

        if active:

            # Buteur : la finition domine, le dribble crée la demi-mesure, l'explosivité place dans les contre-attaques.

            weights=[max(1,float(p.get("finishing",45))*.52+float(p.get("technique",45))*.20+float(p.get("dribble",50))*.12+float(p.get("speed",50))*.06+float(p.get("condition",70))*.10) for p in active]

            p=self.match_rng.choices(active,weights=weights,k=1)[0]

            return f"{p['first_name']} {p['last_name']}",p.get("id")

        return ("Buteur" if side==manager_side else "Adversaire"),None



    SPONSOR_NAMES=("AeroFly","BlueVolt","Carasu","Deltagaz","Elysium Sport","Ferrolux","GreenPulse","HyperNet","IronSide","KimoRent")



    def _sponsor_deal(self,conn):

        """Contrat de sponsor en cours (JSON meta), invalidé hors de sa saison."""

        row=conn.execute("SELECT value FROM meta WHERE key='sponsor_deal'").fetchone()

        if not row: return None

        try: deal=json.loads(row["value"])

        except (ValueError,TypeError): return None

        club=conn.execute("SELECT season FROM club WHERE id=1").fetchone()

        if not club or int(deal.get("season",-1))!=int(club["season"] or 1): return None

        return deal



    def _sponsor_win_bonus(self,conn):

        deal=self._sponsor_deal(conn)

        return int(deal.get("win_bonus",0)) if deal else 0



    def negotiate_sponsor(self):

        """Ouvre la session de negociation : 3 partenaires concurrents remettent une offre (1 session par saison)."""

        conn=db()

        try:

            club=conn.execute("SELECT * FROM club WHERE id=1").fetchone(); facility=conn.execute("SELECT * FROM facility WHERE id=1").fetchone()

            season=int(club["season"] or 1)

            used=conn.execute("SELECT value FROM meta WHERE key='sponsor_used_season'").fetchone()

            if used and int(used["value"] or 0)==season:

                self.show_game_message("Négociation déjà ouverte",f"Le club a déjà négocié ses sponsors pour la saison {season}.","info")

                return False

            marketing=max(1,int(facility_value(facility,"marketing_level",1)))

            reputation=max(0,int(facility_value(club,"reputation",30)))

            names=random.sample(list(self.SPONSOR_NAMES),3)

            offers=[]

            base_value=3400+reputation*210+marketing*1100

            # Equite et rapprochement : weekly + 0,40 x prime ≈ base pour les 3 profils,

            # avec des ecarts MAITRISES entre profils (le meilleur choix depend du style :

            # garanti vs primes). stable le plus de fixe, prestige le plus de primes/signature.

            for name,(profile,weekly_k,bonus_k,sign_lo,sign_hi) in zip(names,(

                ("stable",0.94,0.30,1.4,2.2),("performance",0.84,0.55,1.8,3.0),("prestige",0.76,0.75,2.2,3.6))):

                jitter=random.uniform(0.90,1.12)

                weekly=int(round(base_value*weekly_k*jitter/100.0))*100

                win_bonus=int(round(base_value*bonus_k*jitter/100.0))*100

                sign_on=int(round(weekly*random.uniform(sign_lo,sign_hi)/500.0))*500

                if profile=="stable": desc="Mécène sûr : versement hebdomadaire le plus élevé, prime de victoire raisonnable. Idéal pour sécuriser un petit budget."

                elif profile=="performance": desc="Partenaire équilibré : compromis versement/prime de victoire. Rentabilise par un club régulier qui gagne 4 matchs sur 10."

                else: desc="Grand groupe : versement légèrement réduit mais primes de victoire nettement supérieures et signature généreuse, pour une équipe qui gagne beaucoup."

                offers.append({"profile":profile,"name":name,"weekly":weekly,"win_bonus":win_bonus,"sign_on":sign_on,"desc":desc})

            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('sponsor_offers',?)",(json.dumps(offers),))

            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('sponsor_used_season',?)",(str(season),))

            add_news(conn,"Sponsors","Trois partenaires concurrents déposent leurs offres : signez le contrat le plus avantageux.")

            conn.commit()

        except Exception as exc:

            self.log_error("negotiate_sponsor",exc); self.show_game_message("Sponsors",f"Impossible de lancer la négociation : {exc}","error"); return False

        finally:

            if conn is not None: conn.close()

        self.refresh_all(); return True



    def sign_sponsor(self,index):

        """Signe l'offre no index : prime a la signature creditée, versements hebdo + primes de victoire."""

        conn=db()

        try:

            row=conn.execute("SELECT value FROM meta WHERE key='sponsor_offers'").fetchone()

            try: offers=json.loads(row["value"]) if row else []

            except (ValueError,TypeError): offers=[]

            if not offers or index<0 or index>=len(offers):

                self.show_game_message("Sponsors","Aucune offre à la table des négociations.","warning"); return False

            if self._sponsor_deal(conn) is not None:

                self.show_game_message("Accord déjà signé","Le club honore déjà un contrat de sponsoring cette saison.","info"); return False

            offer=offers[index]; name=str(offer.get("name","Sponsor"))

            sign_on=int(offer.get("sign_on",0))

            club=conn.execute("SELECT season FROM club WHERE id=1").fetchone()

            deal={"name":name,"profile":str(offer.get("profile","stable")),"weekly":int(offer.get("weekly",0)),

                  "win_bonus":int(offer.get("win_bonus",0)),"season":int(club["season"] or 1)}

            conn.execute("UPDATE club SET budget=budget+? WHERE id=1",(sign_on,))

            conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",

                         (f"Signature sponsor {name}",sign_on,career_timestamp(conn),"Sponsoring"))

            conn.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('sponsor_deal',?)",(json.dumps(deal),))

            conn.execute("DELETE FROM meta WHERE key='sponsor_offers'")

            body=(f"{name} rejoint le club : {deal['weekly']:,} €/semaine + {deal['win_bonus']:,} € par victoire, "

                  f"et {sign_on:,} € de prime à la signature.".replace(","," "))

            add_news(conn,"Sponsor signé",body)

            queue_manager_message(conn,"club_news","Sponsors",body,self._current_date(conn),self._current_date(conn),{},is_read=False)

            conn.commit()

        except Exception as exc:

            self.log_error("sign_sponsor",exc); self.show_game_message("Sponsors",f"Impossible de signer : {exc}","error"); return False

        finally:

            if conn is not None: conn.close()

        self.show_game_message("Sponsor signé","Le contrat de sponsoring entre en vigueur : versements hebdomadaires chaque lundi.","info")

        self.refresh_all(); return True



    def process_sponsor_weekly(self,conn,current_iso_date):

        """Verse le soutien hebdomadaire du sponsor le lundi, pendant que le contrat court."""

        try:

            if parse_iso(current_iso_date).weekday()!=0: return

            row=conn.execute("SELECT value FROM meta WHERE key='sponsor_deal'").fetchone()

            if not row: return

            try: deal=json.loads(row["value"])

            except (ValueError,TypeError): return

            season=int(conn.execute("SELECT season FROM club WHERE id=1").fetchone()["season"] or 1)

            if int(deal.get("season",-1))!=season:

                conn.execute("DELETE FROM meta WHERE key='sponsor_deal'")

                add_news(conn,"Sponsors",f"Le contrat {deal.get('name','sponsor')} arrive à expiration avec la saison écoulée.")

                return

            weekly=int(deal.get("weekly",0))
            if self.hard_mode(conn): weekly=int(weekly*0.90)

            if weekly<=0: return

            conn.execute("UPDATE club SET budget=budget+? WHERE id=1",(weekly,))

            conn.execute("INSERT INTO finance_tx(club_id,label,amount,created_at,category) VALUES(1,?,?,?,?)",

                         (f"Sponsoring {deal.get('name','')} • versement hebdomadaire",weekly,career_timestamp(conn),"Sponsoring"))

        except Exception as exc:

            self.log_error("process_sponsor_weekly",exc)



