    def estimate_monthly_finance(self, conn, club, facility):
        """Estimation des revenus/charges MENSUELS du club (indicative, pour la
        santé financière affichée)."""
        div=max(1,min(6,int(club["division"] or 3)))
        payroll=sum(int(p["salary"] or 0) for p in conn.execute(
            "SELECT salary FROM player WHERE club_id=1 AND COALESCE(is_free_agent,0)=0").fetchall())
        try:
            from wage_budget import staff_bill as _staff_bill
            staff=int(_staff_bill(self,conn))
        except Exception:
            staff=sum(self.staff_effective_salary(conn,key) for key in self.STAFF_BASE_SALARY
                      if (conn.execute("SELECT value FROM meta WHERE key=?",(key,)).fetchone() or {"value":"0"})["value"]=="1")
        loans=int(conn.execute("SELECT COALESCE(SUM(weekly_due),0) s FROM loan WHERE status='active'").fetchone()["s"] or 0)
        try:
            att,cap,gate=self.projected_attendance(club,facility)
            gate=int(self.facility_matchday_revenue(club,facility,att,int(facility["ticket_price"]))["total"])
        except Exception:
            gate=0
        tv=4000+6500*max(1,7-div)
        sponsor=0
        try:
            deal=self._sponsor_deal(conn)
            if deal: sponsor=int(deal.get("weekly",0))
        except Exception:
            sponsor=0
        fac_week=0
        try:
            if facility_value(facility,"has_rental_courts",0): fac_week+=2200+int(facility_value(facility,"marketing_level",1))*950
            if facility_value(facility,"has_events_hall",0): fac_week+=1800+int(facility_value(facility,"arena_level",1))*1400
        except Exception:
            fac_week=0
        placements=self.comptable_placement_monthly(conn)
        income=int(gate*2+tv+sponsor*4.33+fac_week*4.33)+placements
        expense=int(payroll+staff+loans*4.33)
        net=income-expense
        budget=int(club["budget"] or 0)
        runway=(budget/abs(net)) if net<0 else 99.0
        return {"income":income,"expense":expense,"net":net,"payroll":payroll,"staff":staff,
                "loans":int(loans*4.33),"tv":tv,"sponsor":int(sponsor*4.33),"gate":gate*2,
                "facility":int(fac_week*4.33),"placements":placements,
                "runway":runway,"budget":budget}

