    def refresh_finance_visuals(self, tx, club):

        """Actualise le tableau de bord financier visuel sans modifier les données."""

        if not hasattr(self,"finance_hero_balance"): return

        balance=int(club["budget"] or 0)

        incomes=sum(int(t["amount"]) for t in tx if int(t["amount"])>0)

        expenses=-sum(int(t["amount"]) for t in tx if int(t["amount"])<0)

        net=incomes-expenses

        try:
            _c=db(); _f=_c.execute("SELECT * FROM facility WHERE id=1").fetchone()
            est=self.estimate_monthly_finance(_c,club,_f); _c.close()
            net=est["net"]
            if net>=50000:
                tone,label="#9ce6bf","SANTÉ FINANCIÈRE  •  SAINE"
            elif net>=0:
                tone,label="#9ce6bf","SANTÉ FINANCIÈRE  •  ÉQUILIBRÉE"
            elif est["runway"]<3:
                tone,label="#ff8d8d","SANTÉ FINANCIÈRE  •  TRÉSORERIE CRITIQUE"
            else:
                tone,label="#ff8d8d","SANTÉ FINANCIÈRE  •  DÉFICIT"
            self.finance_health_label.setText(f"{label}  •  {'+' if net>=0 else ''}{net:,} € / MOIS".replace(","," "))
            self.finance_health_label.setStyleSheet(f"font-size:8pt;font-weight:900;color:{tone};letter-spacing:1px;")
            if balance<0:
                runway="trésorerie négative — le board surveille"
            elif net>=0:
                runway="réserve confortable"
            else:
                runway=f"réserve : {est['runway']:.1f} mois"
            placement_txt=(f" • placements {est.get('placements',0):,}" if est.get('placements') else "")
            self.finance_health_detail.setText(
                f"Revenus ~{est['income']:,} €/mois (billetterie {est['gate']:,} • TV {est['tv']:,} • sponsors {est['sponsor']:,} • installations {est['facility']:,}{placement_txt})  •  "
                f"charges ~{est['expense']:,} €/mois (joueurs {est['payroll']:,} • staff {est['staff']:,} • prêts {est['loans']:,})  •  {runway}.".replace(","," "))
        except Exception:
            pass
        self.finance_hero_balance.setText(f"{balance:,} €".replace(","," "))

        self.finance_hero_balance.setStyleSheet(f"font-size:22pt;font-weight:900;color:{'#ff8d8d' if balance<0 else '#9ce6bf'};")

        if not locals().get("est"):
            self.finance_health_label.setText(("ÉQUILIBRE FINANCIER  •  SOLIDE" if balance>=150000 else "ÉQUILIBRE FINANCIER  •  SOUS SURVEILLANCE" if balance>=0 else "ÉQUILIBRE FINANCIER  •  DÉFICIT"))
            self.finance_health_label.setStyleSheet("font-size:8pt;font-weight:900;color:%s;letter-spacing:1px;" % ("#9ce6bf" if balance>=150000 else "#ffcf70" if balance>=0 else "#ff8d8d"))
            self.finance_health_detail.setText(f"Flux récents : +{incomes:,} € de revenus • -{expenses:,} € de charges • solde {net:+,} €.".replace(","," "))

        if hasattr(self,"sponsor_status"):

            season=int(club["season"] or 1); conn=db(); used=conn.execute("SELECT value FROM meta WHERE key='sponsor_used_season'").fetchone(); conn.close(); available=not used or int(used["value"] or 0)!=season

            self.sponsor_status.setText("Session de négociation disponible" if available else "Sponsors déjà négociés cette saison")

            self.sponsor_btn.setEnabled(available)

            self._sponsor_refresh()

            self.refresh_finance_charts(club)

        if hasattr(self,"finance_flow_bars"):

            values=[int(t["amount"]) for t in reversed(tx[:8])]

            max_abs=max([abs(v) for v in values] or [1])

            for index,bar in enumerate(self.finance_flow_bars):

                value=values[index] if index<len(values) else 0; bar.setValue(int(abs(value)*100/max_abs) if value else 0)

                bar.setStyleSheet("QProgressBar{background:#20283a;border:0;border-radius:4px;} QProgressBar::chunk{background:%s;border-radius:4px;}" % ("#63d79d" if value>=0 else "#ec7180"))

                bar.finance_label.setText(("+" if value>0 else "")+f"{value//1000}k" if value else "—")

        try:
            if self.stack.currentIndex()==9 and getattr(self,"finance_tabs",None) is not None and self.finance_tabs.currentIndex()==1:
                self._finance_exploitation_dirty=False
                self.refresh_finance_exploitation(club)
            else:
                self._finance_exploitation_dirty=True
        except Exception as exc: self.log_error("finance_exploitation",exc)



    def refresh_finance_charts(self,club):

        """Graphe de tresorerie (cumul depuis le debut de la carrière) + flux nets mensuels."""

        if not hasattr(self,"finance_curve"): return

        conn=db()

        try:

            rows=conn.execute("SELECT amount,created_at FROM finance_tx WHERE club_id=1 ORDER BY id ASC").fetchall()

        finally:

            conn.close()

        balance=int(club["budget"] or 0)

        total=sum(int(r["amount"]) for r in rows)

        run=balance-total  # ancre : tresorerie theorique au debut de la carriere

        series_running=[]

        for r in rows:

            run+=int(r["amount"]); series_running.append(run)

        series_running=series_running[-140:]

        self.finance_curve.set_series(series_running)

        months={}

        for r in rows:

            key=str(r["created_at"] or "")[:7]

            if key: months[key]=months.get(key,0)+int(r["amount"])

        keys=sorted(months)[-8:]

        self.finance_month_chart.set_series([months[k] for k in keys])



